/* ============================================================================
   TRAIT BANK — CORE SET
   The original hand-authored bank. Ids 1..6020.
   One trait per line, deliberately: this file used to be a single 1.4MB line,
   which made it unopenable in several editors and turned every content change
   into an unreviewable diff.
   Supplemental sets (ids 90000+) live in traits-supplement.js.
   ========================================================================== */
const TRAITS = [
{id:1,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Babbling",desc:"Uttering rapid, incoherent, or nonsensical words.",example:"—and then the thing, the other thing, no wait, the first thing—",intensity:4,rarity:"common",pol:{"vol":1,"pace":1,"form":0,"warm":0}},
{id:2,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Blathering",desc:"Talking foolishly, mindlessly, or excessively.",example:"So anyway, my point, and I do have one, is basically, well, several things.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:3,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Cascade-speech",desc:"Words tumble over each other in a continuous stream.",example:"He left and I followed and she called and nobody answered and then—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:4,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Chatty",desc:"In formal and friendly dialogue characterized by high word volume.",example:"Lovely day! Have you eaten? I had the fish. You should try the fish.",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":1,"warm":1}},
{id:5,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Chit-chat-heavy",desc:"Fills every silence with rapid small talk.",example:"Cold, isn't it. Was colder Tuesday. My aunt says it'll turn. Anyway.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:6,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Chronic rambler",desc:"Continuously wanders off-topic in lengthy monologues.",example:"Which reminds me of my cousin — different cousin — anyway, where was I?",intensity:5,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:7,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Circular explainer",desc:"Repeats explanations using different wordings in a loop.",example:"So it's broken. Meaning it doesn't work. Which is to say: broken.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:8,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Compulsive chatterbox",desc:"Unable to resist talking in almost any situation.",example:"I know, I know, I'm talking again. I'll stop. I won't, but I'll say I will.",intensity:4,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:9,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Compulsive-explainer",desc:"Feels forced to explain every action and thought aloud.",example:"I'm picking up the cup because my hand is cold and the cup is warm.",intensity:4,rarity:"signature",pol:{"vol":1,"pace":0,"form":-1,"warm":0}},
{id:10,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Dialogue-hoarder",desc:"Refuses to yield the floor, keeping the conversation.",example:"—and another thing, before you say anything, and I know you want to—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:11,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Diffuse",desc:"Wordy and lacking clarity or conciseness.",example:"It's sort of a situation, in a way, regarding some of the arrangements.",intensity:2,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:12,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Effusive",desc:"Expresses feelings of gratitude or approval in an unrestrained way.",example:"Thank you, thank you, truly, you've no idea, thank you.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:13,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Endless-loop",desc:"Revisits the same topic repeatedly with new words.",example:"As I said. As I've been saying. As I will continue to say.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:14,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Exhaustive",desc:"Covers every possible angle of a topic in endless detail.",example:"There are eleven reasons. I'll take them in order. The first—",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:15,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Flood-gate",desc:"Pours out an overwhelming wave of words all at once.",example:"Right, so — everything, all of it, from the start, here we go—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:16,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Garrulous",desc:"Excessively talkative, especially on trivial matters.",example:"Did I tell you about the horse? No? Sit down. Sit down.",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:17,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Glib",desc:"Fluent and voluble but insincere and shallow in delivery.",example:"Marvellous, wonderful, couldn't agree more, whatever you like.",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:18,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Gushy",desc:"Pours out overly enthusiastic streams of dialogue.",example:"Oh it's PERFECT, it's absolutely perfect, I could weep, look at it—",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":1}},
{id:19,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Hyper-conversational",desc:"Treats every encounter as a platform for lengthy debate.",example:"Interesting. Let's unpack that. What do you mean by 'fine', exactly?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:20,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Hyper-graphia-spoken",desc:"Speaks with the volume and density of an endless writer.",example:"(speaks for eleven straight minutes without seeming to draw breath)",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:21,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Hyper-vocal",desc:"Consistently produces a high volume and frequency of speech.",example:"(has never once left a silence unfilled, not once, not ever)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:22,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Incessant",desc:"Talking without pause, annoyance, or stopping.",example:"—and — no, listen — and — I'm getting to it — and—",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:23,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Logorrheic",desc:"Speaks incessantly with a compulsive flow of words.",example:"Words words words, I know, but hear me out, there's a shape to it—",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:24,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Long-winded",desc:"Tends to talk for a long time, often boring or tiring the listener.",example:"To answer your question I'll need to start about four years earlier.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:25,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Loquacious",desc:"Fluent, articulate, and overly talkative.",example:"Delighted, truly. Let me tell you precisely why, at some length.",intensity:2,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:26,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Motormouthed",desc:"Speaks extremely rapidly and continuously without stopping.",example:"Rightsoheresthething I've been thinking and I think it's actually—",intensity:5,rarity:"common",pol:{"vol":1,"pace":1,"form":0,"warm":0}},
{id:27,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Over-articulated",desc:"Uses excessive words to clarify already simple ideas.",example:"It's shut. Closed. Not open. The door, I mean. It is not open.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:28,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Over-communicative",desc:"Shares unnecessary details about every personal thought.",example:"I'm going upstairs. To the bathroom. I'll be four minutes. Maybe five.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:29,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Over-descriptive",desc:"Describes trivial surroundings in exhaustive detail.",example:"The chair — brown, three legs sound, one wobbling, cushion faded—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:30,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Over-explainer",desc:"Provides exhaustive details for concepts that are already clear.",example:"Water's wet. That's because of the molecules. Let me explain molecules.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:31,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Over-narrated",desc:"Narrates own live actions out loud to anyone listening.",example:"I'm crossing the room now. Opening the drawer. Ah — there it is.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:32,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Over-sharing",desc:"Volunteers deeply intimate or unnecessary details freely.",example:"We're not speaking, actually. Since the funeral. Long story. So—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:33,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Overly verbose",desc:"Uses far more words than necessary to convey simple ideas.",example:"It is my considered view that the answer would appear to be 'no'.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":-1,"warm":0}},
{id:34,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Perpetual-motion",desc:"Conversations transition seamlessly from topic to topic.",example:"Which reminds me — no wait, that reminds me of something else entirely—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:35,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Prating",desc:"Talking foolishly or at tedious length about trivialities.",example:"—and the price of bread, and the state of the roads, and don't start me—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:36,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Prattling",desc:"Talking at length in a foolish or inconsequential way.",example:"Little bit of this, little bit of that, you know how it goes, don't you—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:37,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Pressure-speech",desc:"Speaks rapidly and urgently, hard to interrupt.",example:"Listen-listen-listen there's no time I need you to just—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:38,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Prolific",desc:"Generates an immense output of spoken phrases continuously.",example:"(has said more in the last hour than most people say in a week)",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:39,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Spun-out",desc:"Extends simple thoughts into long, winding stories.",example:"I bought bread. Well. I went for bread. What happened was—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:40,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Steamroller",desc:"Talks over everyone else with sheer volume of words.",example:"NO — as I was SAYING —",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:41,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Stream-of-consciousness",desc:"Speaks thoughts continuously as they occur without editing.",example:"Blue. Why blue. Mother had a blue coat. She hated it. Anyway, the money—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:42,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Tangential",desc:"Diverges frequently onto unrelated subjects during speech.",example:"Which is like the war, actually. Not that war. The other one. Ignore that.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:43,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Torrential",desc:"Speech arrives in a heavy, inescapable downpour.",example:"—and that's before we even get to the second half of it—",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:44,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Unabated",desc:"Talks continuously without slowing down or taking breaks.",example:"(three hours in, shows no sign of slowing)",intensity:4,rarity:"common",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:45,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Unfiltered",desc:"Speaks every thought immediately without social filtering.",example:"You look terrible. Sorry. True though. Are we eating?",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:46,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Unstoppable",desc:"Ignores social cues to stop talking and continues on.",example:"(does not notice the door has opened, or that everyone has left)",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:47,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Vaudevillian",desc:"Theatrically wordy, entertaining, and loud in dialogue.",example:"Ladies and gentlemen! Gather round! You will NOT believe what happened next!",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:48,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Verbiage-dense",desc:"Packs huge quantities of filler words into speech.",example:"It's, you know, sort of a situation, in a manner of speaking, kind of, if you follow.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:49,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Voluble",desc:"Speaking fluidly, easily, and at great length.",example:"Delighted to explain, at whatever length proves necessary.",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:50,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Word-avalanche",desc:"Buries listeners under massive quantities of prose.",example:"I have eleven points and I'm starting with all of them at once.",intensity:5,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:51,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Abrupt",desc:"Sudden and short in speech, often cutting off dialogue.",example:"No. Next.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:52,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Aphoristic",desc:"Speaks in short, memorable truths or concise principles.",example:"Cheap rope costs the most.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:53,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Brevity-bound",desc:"Strictly avoids unnecessary words as a personal philosophy.",example:"Say it in five words or don't say it.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:54,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Brevity-obsessed",desc:"Actively cuts off own sentences to keep them short.",example:"It's — never mind.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:55,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Brusque",desc:"Abrupt, offhand, and sharply short in speech.",example:"Where. When. Fine.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:56,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Chiseled",desc:"Structures words into sharp, stark, minimal shapes.",example:"Cold. Hard. Done.",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:57,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Clenched",desc:"Speaks as if forcing words through tight jaws.",example:"(word forced out between clenched teeth) ...Fine.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:58,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Crisp",desc:"Decisive, clear, and extremely short in phrasing.",example:"Understood. Done by six.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:59,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Cryptically brief",desc:"Provides short answers that leave mysterious or vague meanings.",example:"Ask me tomorrow.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:60,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Curt-official",desc:"Delivers brief, unyielding administrative directives.",example:"Report by dawn. No exceptions.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:61,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Curtly direct",desc:"Speaks bluntly and briefly without pleasantries or fluff.",example:"Wrong man. Try the docks.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":-1,"warm":0}},
{id:62,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Deadpan minimal",desc:"Delivers bare-minimum words without emotional expression.",example:"Great.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":-1}},
{id:63,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Deadpan-terse",desc:"Delivers flat, brief statements without inflection.",example:"Understood.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":-1}},
{id:64,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Economy-driven",desc:"Uses as few words as possible to maximize communication efficiency.",example:"Two carts. Dawn.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:65,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Elliptical-brief",desc:"Omits all non-essential words, leaving bare meaning.",example:"Gone. Dead. Sorry.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:66,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Epigrammatic",desc:"Expresses thoughts in short, clever, or witty sayings.",example:"Trust is a loan, not a gift.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:67,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Exiguous",desc:"Meager and scanty in word production.",example:"...(a single nod)",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:68,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Glacial",desc:"Extremely slow to speak, leaving long gaps with few words.",example:"(three full seconds pass before the single word arrives) ...No.",intensity:4,rarity:"common",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:69,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Guarded",desc:"Cautious speech that minimizes revealing personal thoughts.",example:"I've heard the name.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:70,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Guttural-minimal",desc:"Communicates primarily through short grunts and low noises.",example:"Hnh.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:71,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Incurious-minimal",desc:"Too indifferent to speak more than a couple syllables.",example:"...Sure. Whatever.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":-1}},
{id:72,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Laconic-ironic",desc:"Uses dry, minimal words to deliver biting humor.",example:"Lovely.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:73,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Mincing",desc:"Choppy, overly refined, or restrained vocal expressions.",example:"(a small, precise, clipped 'indeed')",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:74,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Monolith-speaker",desc:"Stands silent until dropping a single heavy phrase.",example:"(says nothing for the whole meeting, then: 'No.')",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:75,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Monolithic",desc:"Delivers single, immovable words with massive presence.",example:"NO.",intensity:5,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:76,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Monosyllabic",desc:"Uses single-syllable words and minimal dialogue responses.",example:"Yes. No. Maybe.",intensity:2,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:77,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Monosyllabic-grunt",desc:"Replaces full words with simple vocalizations.",example:"Hgn.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":-1,"warm":0}},
{id:78,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Muted",desc:"Low-key, subdued, and minimal vocal output.",example:"...s'fine.",intensity:1,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:79,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Muted-monologue",desc:"Quietly speaks tiny snippets to oneself.",example:"...(murmurs something no one quite catches)",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:80,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Pauciloquent",desc:"Habitually uttering few words.",example:"(three words all week, and this was one of them)",intensity:2,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:81,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Pithy",desc:"Concise and forcefully expressive in very few words.",example:"Rope's frayed. Don't climb it.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:82,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Quietly concise",desc:"Delivers succinct points in a soft, low-volume manner.",example:"It's handled.",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:83,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Reticent",desc:"Disinclined to speak or express feelings voluntarily.",example:"Rather not say.",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:84,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Sententious",desc:"Given to moralizing in a pompously concise manner.",example:"Pride goes before the fall.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:85,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Snappish",desc:"Responds in short, irritated bursts.",example:"WHAT.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:86,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Sparing",desc:"Rations words as if resources are scarce.",example:"Enough.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:87,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Sparsely vocal",desc:"Speaks rarely, uttering only essential words when necessary.",example:"(speaks only when directly addressed, and rarely then)",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:88,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Spartan",desc:"Marked by extreme simplicity and brevity of speech.",example:"North road. Two days. Go.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:89,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Stinting",desc:"Holding back words as if rationing speech.",example:"...Perhaps.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:90,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Stolid",desc:"Unemotional and impassive, uttering absolute minimum words.",example:"Mm.",intensity:4,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:91,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Stony",desc:"Coldly silent, offering rare and unyielding replies.",example:"...",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":-1}},
{id:92,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Sub-vocal",desc:"Speaks barely above a breath, using minimal words.",example:"(barely a whisper) ...Don't.",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:93,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Subdued",desc:"Quiet and restrained in word count and vocal force.",example:"...(a small nod suffices)",intensity:1,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:94,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Tactically laconic",desc:"Speaks with extreme brevity for strategic or calculated effect.",example:"Later.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:95,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Terse",desc:"Sparing in the use of words; sudden and abrupt.",example:"Not here.",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:96,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Tight-lipped",desc:"Reluctant to speak or share information; highly secretive.",example:"Couldn't say.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:97,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Utterly blunt",desc:"Direct to a fault, omitting all polite conversational buffers.",example:"You're wrong and you're wasting my day.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:98,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Whisper-thin",desc:"Utters barely audible, brief statements.",example:"...leave.",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:99,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Whispered",desc:"Quiet, minimal vocal delivery using breath rather than voice.",example:"...they're listening...",intensity:1,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:100,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Zero-padding",desc:"Eliminates all pleasantries, introductions, and conclusions.",example:"Ship sank. Crew lost. Need orders.",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:101,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Adrenaline-paced",desc:"Speech accelerates wildly under danger or excitement.",example:"—wait — wait, it's — okay, it's coming, hold on, HOLD ON—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:102,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Breathless",desc:"Speaks with hurried urgency as if running out of air.",example:"Can't — stop — need to — just listen —",intensity:3,rarity:"common",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:103,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Breathless-panic",desc:"Gasps for air between short, terrified phrases.",example:"(gasp) — they're — (gasp) — coming —",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:104,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Burrowing",desc:"Speaks inwardly, as if retreating deeper into personal thoughts.",example:"(voice drops, turns inward, barely audible even up close)",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:105,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Calculated-delay",desc:"Pauses intentionally before answering to control the room.",example:"(lets the silence sit for a long, deliberate moment) ...We'll see.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:106,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Combat-shuttered",desc:"Short, rapid tactical bursts during high-stress action.",example:"Contact. Left flank. Move.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:107,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Command-rhythm",desc:"Paced with steady, immovable authority that demands attention.",example:"Hold. The. Line.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:108,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Dead-stop-pacing",desc:"Speaks fluently then comes to a sudden complete halt.",example:"—and that's precisely why it— (stops completely) ...No. Never mind.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:109,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Deliberate",desc:"Carefully considers each word before uttering it.",example:"(a long pause before each word, weighed carefully)",intensity:2,rarity:"common",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:110,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Distracted-pacing",desc:"Pauses frequently because attention is focused elsewhere.",example:"Sorry — what? I was looking at the — sorry, go on.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:111,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Drunk-slurred-pace",desc:"Irregular, dragged pacing caused by intoxication.",example:"'S'not— I'm not— gimme a sec—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:112,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Erratic-bursts",desc:"Random alternation between dead silence and fast speech.",example:"(silent for a full minute, then a sudden burst) THERE. There it is!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:113,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Answer-dodging",desc:"Structures speech to avoid answering direct questions.",example:"That's an interesting question. Anyway, moving on—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:114,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Exhaustion-dragged",desc:"Pacing slows to a crawl due to physical or mental fatigue.",example:"(words come slower and slower, trailing into silence)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:115,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Explosive-outburst",desc:"Quiet pacing suddenly interrupted by a loud statement.",example:"(quiet all evening, then suddenly) I CAN'T DO THIS ANYMORE.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:116,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Explosively vocal",desc:"Remains quiet until bursting into loud, passionate speech.",example:"(silent through the whole toast, then erupts) I love you all so much!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":1}},
{id:117,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Faltering",desc:"Speech stumbles or loses momentum due to weakness or fear.",example:"I j-just— I don't— sorry, give me—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:118,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Feverish-rhythm",desc:"Rapid, erratic speech driven by sickness or intense obsession.",example:"—andthenandthen—wait—no—yes—andthen—",intensity:5,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:119,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Grief-retarded",desc:"Speech is heavily delayed and sluggish due to sorrow.",example:"...it's been... a while... since I've...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:120,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Hedging",desc:"Uses cautious or ambiguous language to avoid commitment.",example:"It's possible. Not certain. Possibly likely, even.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:121,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Hesitant",desc:"Pauses frequently due to uncertainty or lack of confidence.",example:"I... think... maybe... if that's...",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:122,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Hypnotic-cadence",desc:"Rhythmic, repetitive pacing that lulls the listener.",example:"...and so it goes, and so it goes, and so it always goes...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:123,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Intermittent rambler",desc:"Alternates between silence and sudden bursts of rambling.",example:"(silent for an hour, then: a ten-minute unbroken monologue)",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:124,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Interrogation-guarded",desc:"Paces words carefully to avoid giving away critical information.",example:"I recall... some things. Not everything. Some things.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:125,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Interruptive",desc:"Frequently cuts across others' speech turns.",example:"—no, wait, before you finish—",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:126,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Measuredly slow",desc:"Deliberately paces words with long, intentional pauses.",example:"We. Will. Not. Rush. This.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:127,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Methodical-pace",desc:"Step-by-step, evenly spaced delivery without rush.",example:"Step one. Then step two. Then step three.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:128,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Monotonous",desc:"Delivers speech with flat, unchanging pitch and rhythm.",example:"That is unfortunate. I am concerned. Please continue.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:129,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Monotonous-drag",desc:"Flat, unchanging pace that drains energy from the room.",example:"(the meeting drags on in one flat, unbroken tone)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":-1}},
{id:130,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Nervous chatterer",desc:"Talks rapidly and excessively when anxious or under stress.",example:"Sowhatdoyouthinkweshoulddoshouldwegoshouldwestay—",intensity:5,rarity:"signature",pol:{"vol":1,"pace":1,"form":0,"warm":0}},
{id:131,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Panic-accelerated",desc:"Words rush out out of control due to rising terror.",example:"—can't—can't—they're coming—we have to—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:132,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Pressured-tempo",desc:"Feels forced to speak faster than natural due to stress.",example:"I don't want to rush but I think we need to actually rush.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:133,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Rapid-fire",desc:"Delivers words at an exceptionally high speed.",example:"NoIcan'tIcan'tdothisrightnowjustletmethink—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:134,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Regulated-breath",desc:"Paces speech strictly to match meditative breathing.",example:"(in. two three four. out. two three four.)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:135,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Rhythmically repetitive",desc:"Repeats key words or sentence beats in a metronomic style.",example:"Again. And again. And again.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:136,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Ruminative-slow",desc:"Slow, thoughtful pacing while chewing on complex ideas.",example:"...hm... yes... but then again... hm...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:137,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Selective talker",desc:"Speaks only to specific people or in specific circumstances.",example:"(speaks only to the one person she trusts in the room)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:138,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Shock-paralyzed",desc:"Long silences broken by single, stunned words.",example:"...gone. (long silence) ...gone.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:139,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Soporific-pacing",desc:"So slow and soothing it induces sleep in the listener.",example:"...and so... slowly... the tide... comes in...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:140,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Staccato",desc:"Short, detached, and emphatic rhythmic delivery.",example:"Stop. Think. Then. Speak.",intensity:3,rarity:"common",pol:{"vol":0,"pace":1,"form":0,"warm":-1}},
{id:141,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Staccato speaker",desc:"Speaks in short, sharp, disconnected bursts.",example:"Wrong. Try again. No.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:142,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Stage-frightened",desc:"Speech freezes or stutters when addressed by authority.",example:"I— sir— I— (voice fails entirely)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:143,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Stammering",desc:"Characterized by involuntary pauses and word repetitions.",example:"I-I-I th-think that we should—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:144,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Suspense-building",desc:"Slows down speech intentionally to build drama.",example:"...and then... (long pause) ...everything changed.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:145,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Syncopated-flow",desc:"Off-beat, unexpected rhythmic pauses in natural speech.",example:"You said— (pause) —that you'd— (pause) —be here.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:146,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Telegraphic-urgency",desc:"Rapid delivery stripped of all non-essential words.",example:"Bridge. Down. Now. Move.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:147,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Tension-strained",desc:"Words come out tight and strained under intense pressure.",example:"I—can't—just—give me a—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:148,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Tripping-paced",desc:"Words stumble over each other as thoughts outpace mouth.",example:"I was— he said— wait— what did he—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:149,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Waffling",desc:"Fails to make a point due to indecisive and vague word choices.",example:"Well, it could be this, or maybe that, or possibly something else entirely.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:150,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Whisper-accelerated",desc:"Speaks extremely fast while trying to remain quiet.",example:"(barely audible, moving fast) —they can't hear us if we—",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":1,"form":0,"warm":0}},
{id:151,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Apostrophic",desc:"Frequently addresses abstract concepts directly in speech.",example:"O silence, what have you done to this house?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:152,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Architectural",desc:"Constructs sentences with complex structural symmetry.",example:"The first clause answers the second; the second, the third; and so the whole stands balanced.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:153,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Baroque-prose",desc:"Highly complex, ornate, and extravagantly detailed speech.",example:"The evening, gilded and reluctant, surrendered itself unto the hour.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:154,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Bombastic",desc:"High-sounding language with little meaning used to impress.",example:"NEVER in the annals of this proud house has such an outrage been suffered!",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:155,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Bravura-speaker",desc:"Delivers speech with brilliant, daring, and energetic style.",example:"And THEN — with nothing but my wit and this borrowed sword — I answered him!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:156,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Ceremonial",desc:"Treats casual conversations like formal official proclamations.",example:"Let it be recorded that the tea has been poured, and poured well.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:157,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Chivalric",desc:"Uses courtly, honorable, and knightly speech structures.",example:"By my honor, madam, your request shall be met before the sun sets.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:158,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Ciceronian",desc:"Ornate, complex, and highly rhythmic classical speech style.",example:"Consider, if you will, the threefold nature of the argument before us.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:159,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Classical-rhetoric",desc:"Structures arguments using formal ancient Greek/Roman logic.",example:"First, the premise. Second, the evidence. Third, the conclusion none can refute.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:160,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Courtly",desc:"Excessively refined and polite speech suited for royalty.",example:"Your servant, madam. The hour is yours to command.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:161,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Decorative",desc:"Prioritizes beautiful-sounding phrasing over direct meaning.",example:"The phrase must sing before it may inform.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:162,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Elevated-prose",desc:"Speaks as if reading from a classic literary masterpiece.",example:"The evening, as ever, wore its melancholy like a borrowed coat.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:163,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Epistolary-spoken",desc:"Speaks in the style of formal, written 19th-century letters.",example:"My dearest friend, I trust this finds you in good health and better spirits.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:164,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Euphonious",desc:"Phrases words to sound pleasing, harmonious, and lyrical.",example:"The words fell like water over smooth stone.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:165,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Euphuistic",desc:"An artificially elegant style characterized by antithesis.",example:"His virtue, though visible, was as invisible to himself as his own shadow.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:166,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Flamboyant",desc:"Uses colorful, dramatic, and showy sentence structures.",example:"Behold! For I shall now astound you utterly!",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:167,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Flowery",desc:"Uses overly elaborate, poetic, or ornate phrasing.",example:"Her laughter fell like coins into the well of the afternoon.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:168,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Gothic-ornate",desc:"Dark, atmospheric, and elaborately romantic phrasing.",example:"The manor loomed, black against a bruised and weeping sky.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:169,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Grandiloquent",desc:"Pompous or extravagant in language, style, or manner.",example:"I shall not dignify so paltry a slander with the whole of my attention.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:170,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"High-flown",desc:"Extravagant, lofty, or elevated in style.",example:"I shall not stoop to answer so base an accusation.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:171,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"High-flown-poetic",desc:"Constantly crafts poetic images in everyday context.",example:"The kettle sings its small, domestic hymn.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:172,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"High-society-stylized",desc:"Employs upper-class affectations and elevated phrasing.",example:"One does so hope the weather shan't disappoint the garden party.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:173,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Hyper-formal",desc:"Refuses any casual contractions or informal shortcuts.",example:"I do not believe that I am able to accommodate that request.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:174,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Jargon-dense",desc:"Overloads speech with specialized or technical terminology.",example:"The load-bearing capacity, per the structural tolerances outlined in section four—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:175,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Latinate",desc:"Favors words derived from Latin over plain Germanic roots.",example:"I shall endeavor to elucidate the matter with appropriate perspicacity.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:176,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Liturgical",desc:"Adopts solemn, ritualistic, and church-like speech patterns.",example:"Let us bow our heads, and let the silence itself be our prayer.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:177,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Mannerist",desc:"Artificially stylized speech focusing on social elegance.",example:"One does so admire the delicate architecture of a well-turned phrase.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:178,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Melodramatic",desc:"Exaggerates emotion and theatricality in dialogue.",example:"Then let it end here! Let the whole of it burn!",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:179,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Metaphor-heavy",desc:"Constantly constructs analogies and figurative comparisons.",example:"He's a locked door in a house with no windows.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:180,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Mythic",desc:"Frames current events using epic, legendary phrasing.",example:"They will speak of this crossing for a hundred winters.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:181,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Operatic",desc:"Speaks with dramatic height, swelling tone, and theatrical style.",example:"MY HEART! MY HEART SHALL BURST WITH THE WEIGHT OF THIS SORROW!",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:182,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Oratorical",desc:"Speaks in formal, speeches-like, and rhetorical cadences.",example:"Friends — and I do not use the word lightly — hear me.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:183,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Ornate-archaic",desc:"Combines historical words with elaborate, decorative syntax.",example:"Thence didst he wander, in the manner of the old tales, unto the gate of dusk.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:184,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Over-refined",desc:"So delicate and formal that it sounds artificial.",example:"One would not wish to trouble you with so delicate a matter.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:185,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Overly academic",desc:"Employs high-level scholarly terms and formal constructions.",example:"The epistemological implications of the proposition merit further scrutiny.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:186,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Pedantic",desc:"Overly concerned with minute details and formal accuracy.",example:"'Fewer', not 'less'. It's a countable noun. Continue.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:187,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Pedantic-elaborate",desc:"Overly detailed explanations wrapped in formal flourishes.",example:"To clarify — and I do think clarity serves us all — the matter is threefold, as follows.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:188,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Polished-dramatic",desc:"Carefully crafts every utterance for maximum emotional impact.",example:"(pauses exactly three seconds before delivering the line, for effect)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:189,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Pompous",desc:"Self-important and solemn in speech style.",example:"One does not simply arrive. One is received.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:190,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Preachy",desc:"Speaks with a moralizing or patronizing tone.",example:"And this is precisely what happens when we abandon principle.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:191,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Pretentious-stylized",desc:"Adopts high-class speech mannerisms to appear superior.",example:"One simply cannot be expected to dine at such an hour.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:192,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Purple-tongued",desc:"Uses excessively ornate or overwrought literary language.",example:"Her laughter, that gilded and treacherous bell, tolled once more across the ruined hall.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:193,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Rhetorical",desc:"Formulated for persuasive or dramatic effect rather than truth.",example:"We stand, friends, at the very hinge of history itself.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:194,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Sagacious",desc:"Uses wise, insightful, and solemn linguistic phrasing.",example:"The wise man plants the tree whose shade he will not live to sit beneath.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:195,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Scholarly-ornate",desc:"Decorates academic terms with grand stylistic flourishes.",example:"The dissertation, though rigorous, sings with an unexpected grace.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:196,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Shakespearian",desc:"Uses dramatic soliloquy style, poetic meter, and elevated tone.",example:"What ho — doth morning find us yet unransomed?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:197,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Stilted",desc:"Stiffly formal and unnatural in conversational flow.",example:"It is agreeable to encounter you upon this occasion.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:198,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Symphonic-prose",desc:"Words rise and fall in carefully orchestrated rhythmic waves.",example:"The sentence rose, held its note, and fell again into silence.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:199,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Theatrical-monologue",desc:"Delivers casual thoughts as if performing on a stage.",example:"(to no one) And so we come to it. The hour I have long foreseen.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:200,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Victorian-formal",desc:"Highly polite, restrained, and grammatically complex dialogue.",example:"I trust I do not presume in enquiring after your father's health.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:201,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Abstract-theoretical",desc:"Prefers conceptual, non-physical terms and high-level ideas.",example:"It's less a place than a condition.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:202,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Anatomical-physical",desc:"Uses direct body and biological vocabulary.",example:"Felt it in the gut. Low down, behind the ribs.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:203,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Auditory-focused",desc:"Populates speech with sound, pitch, and acoustic vocabulary.",example:"Listen — the room's gone quiet. That's the tell.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:204,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Fluid-changing",desc:"Chooses vocabulary expressing motion, transformation, and flow.",example:"It's shifting. Whatever it was this morning, it isn't now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:205,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Illusory-ethereal",desc:"Favors light, airy, intangible, and dreamlike vocabulary.",example:"Half of it wasn't there. Or was, and then wasn't.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:206,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Kinesthetic-active",desc:"Favors motion, weight, force, and physical movement verbs.",example:"Push it. Lean. Now drag.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:207,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Material-textured",desc:"Describes objects by their substance, density, and material makeup.",example:"Rough-cut oak. Green still. It'll warp.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:208,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Mechanistic",desc:"Uses industrial, machine-like, and functional terminology.",example:"He's a mechanism. Input, output, no soul in the middle.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:209,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Metaphysical",desc:"Selects vocabulary exploring existence, reality, and being.",example:"What does it mean to still be the same man after that?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:210,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Olfactory-gustatory",desc:"Uses vocabulary related to smell, taste, and flavor textures.",example:"Smells like copper and old rain in here.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:211,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Organic-biological",desc:"Selects living, natural, and growth-oriented vocabulary.",example:"It'll grow back. These things root deeper than you'd think.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:212,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Phenomenological",desc:"Focuses on words describing internal subjective awareness and perception.",example:"It isn't what happened. It's what it was like to be inside it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:213,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Quantitative-spatial",desc:"Describes experiences using geometric and volume terms.",example:"Four paces across. Half that deep.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:214,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Sensory-concrete",desc:"Favors physical, tangible nouns and direct sensory adjectives.",example:"Cold iron. Wet stone. Three doors.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:215,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Spatial-relational",desc:"Employs words mapping physical arrangements and distance.",example:"North of the mill, behind the wall, left of the gate.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:216,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Static-immovable",desc:"Favors words conveying permanence, weight, and fixed states.",example:"It's been there a thousand years. It'll outlast you.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:217,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Systemic-structural",desc:"Selects terms describing networks, frameworks, and patterns.",example:"Pull that thread and the whole net comes apart.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:218,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Tactile-rich",desc:"Selects vocabulary evoking physical touch, texture, and temperature.",example:"Grit under the nails. Rope-burn. Still warm.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:219,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Temporal-dynamic",desc:"Favors vocabulary describing time flow, duration, and speed.",example:"Give it a week. Two. It accelerates after that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:220,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Visual-spatial",desc:"Employs words describing light, color, geometry, and location.",example:"Grey light, long shadows, everything angled wrong.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:221,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Aggressive-plosive",desc:"Favors forceful, dominant words with harsh phonetic qualities.",example:"Break it. Burn it. Bury what's left.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:222,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Apathetic-indifferent",desc:"Relies on flat, unenthusiastic, and uncommitted vocabulary.",example:"Sure. Whatever. Fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:223,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Clinical-detached",desc:"Drains all emotional resonance from vocabulary in favor of cold facts.",example:"Subject expired at approximately four. Cause: blood loss.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:224,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Cynical-disillusioned",desc:"Uses mistrustful, pessimistic, and weary terminology.",example:"They'll promise. They always promise.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:225,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Effervescent-bubbly",desc:"Selects light, cheerful, and overly optimistic terms.",example:"Oh this is going to be GOOD, I can feel it—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:226,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Hyperbolic",desc:"Favors extreme, exaggerated vocabulary over moderate descriptors.",example:"Worst thing that has ever happened to anyone, ever.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:227,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Laudatory",desc:"Employs praise-filled, enthusiastic, and admiring word choices.",example:"Magnificent. Truly, genuinely magnificent work.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:228,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Emotionally charged wording",desc:"Selects highly charged, emotionally explosive word choices.",example:"Then let it end here! Let the whole of it burn!",intensity:4,rarity:"common",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:229,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Muted-restrained",desc:"Chooses quiet, gentle, and emotionally neutral vocabulary.",example:"It's... not ideal.",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:230,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Nostalgic-wistful",desc:"Uses longing, backward-looking, and tenderly sad words.",example:"We used to sit out here. Before all this.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:231,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Pacifying-soothing",desc:"Employs calming, reassuring, and conflict-reducing vocabulary.",example:"Easy. Easy now. Nobody's going anywhere.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:232,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Pejorative-rich",desc:"Populates speech with critical, disapproving, or disparaging terms.",example:"That grasping, hollow little fraud.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:233,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Provocative-inflammatory",desc:"Selects words deliberately chosen to spark reaction or anger.",example:"Say it again where your father can hear you.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:234,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Sardonic-biting",desc:"Uses sharp, sarcastic, and cutting vocabulary.",example:"Oh, brilliant. Truly inspired. Well done everyone.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:235,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Sensationalist",desc:"Chooses dramatic, attention-grabbing, and alarming words.",example:"They'll be talking about this for a hundred years!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:236,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Somber-grave",desc:"Uses heavy, serious, and dark vocabulary.",example:"Three are dead. There's no soft way to say it.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:237,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Tender-intimate",desc:"Selects soft, vulnerable, and deeply personal vocabulary.",example:"Come here. You're shaking.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:238,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Understated-downplayed",desc:"Uses minimized, restrained vocabulary to soften extreme realities.",example:"Bit of trouble at the bridge. Nothing much.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:239,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Visceral-raw",desc:"Uses physical, intense vocabulary that evokes strong emotional reactions.",example:"It went through him. I heard it go through him.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:240,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Zealous-impassioned",desc:"Employs fervent, fiery, and deeply devoted vocabulary.",example:"This is what we were made for. All of it. Everything.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:241,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Argot-borrowed",desc:"Incorporate criminal or underworld slang into casual speech.",example:"He got pinched at the drop. Squealed inside an hour.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:243,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Dialectal-borrower",desc:"Adopts words from neighboring regional dialects.",example:"Proper claggy out, in't it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:244,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Domain-borrowed",desc:"Applies terminology from one field to discuss unrelated everyday life.",example:"Your marriage has a supply-chain problem.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:245,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Etymological-purist",desc:"Avoids modern borrowed words in favor of ancient language roots.",example:"I'll not use their word for it. We have our own, older and truer.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:246,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Foreign-loanword-rich",desc:"Frequently embeds un-translated terms from other languages.",example:"It's a question of, how do you say — Fingerspitzengefühl.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:247,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Globalized-cosmopolitan",desc:"Uses internationally recognized, universally understood vocabulary.",example:"Let's use words everyone in this room can actually stand behind.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:248,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Historical-period-bound",desc:"Uses vocabulary distinct to a specific past historical era.",example:"Speaks the way people spoke fifty years before he was born.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:249,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Hybrid-loanwords",desc:"Attaches native prefixes and suffixes to foreign root words.",example:"Absolutely un-put-downable, that book. Truly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:251,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Literary-allusive-words",desc:"Selects words made famous by classical literature.",example:"He's got a touch of the tragic hero about him, hasn't he.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:253,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Modernist-neologisms",desc:"Favors newly coined digital, tech, and contemporary terms.",example:"The whole thing's been optimised into uselessness.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:254,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Multilingual-blended",desc:"Switches fluidly between vocabulary from multiple languages mid-phrase.",example:"C'est la vie, you know? Nothing to be done about it, really.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:259,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Translation-literal",desc:"Uses vocabulary translated word-for-word from another language syntax.",example:"As one says in my country: the wolf does not count the sheep.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:260,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Vernacular-rooted",desc:"Restricts vocabulary to native, traditional language roots.",example:"Old words for old things. That's all I use.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:261,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Allegorical-words",desc:"Employs symbolic vocabulary that represents underlying secondary meanings.",example:"The garden was walled for a reason. You've unwalled it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:262,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Analogical",desc:"Selects vocabulary that continuously draws comparative parallels.",example:"It's like bailing a boat with a fork.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:263,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Chiasmic-paired",desc:"Uses mirrored word pairs to balance literal points.",example:"Ask not what the house owes you, but what you owe the house.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:264,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Double-entendre-lexicon",desc:"Chooses words with dual meanings to convey subtext.",example:"He's very good with his hands. So I'm told.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:265,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Euphemistic-figurative",desc:"Uses gentle figurative imagery to avoid crude terms.",example:"He's gone to a better shore.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:266,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Hyperbolic-figurative",desc:"Uses wild metaphorical exaggerations for routine events.",example:"I nearly died of boredom. Actually perished. On the spot.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:267,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Idiomatic-free",desc:"Avoids all fixed idioms in favor of direct, literal descriptions.",example:"He is dead. He stopped living. That's the whole of it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:268,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Irony-laced",desc:"Selects vocabulary where intended meaning is opposite of literal words.",example:"Oh, no, this is going wonderfully.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:269,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Litotic-understatement",desc:"Expresses affirmative points by denying their opposite ('not bad').",example:"Not the worst plan I've heard this week.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:270,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Metaphorical-prone",desc:"Replaces direct terms with continuous figurative equivalents.",example:"You've built a house on a tide-flat.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:271,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Metonymic",desc:"Refers to concepts using associated attributes or partial names.",example:"The Crown won't like it.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:272,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Paradoxical-words",desc:"Pairs self-contradictory vocabulary to highlight complexity.",example:"He's honestly deceitful. Openly so.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:273,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Personifying",desc:"Applies human action verbs to non-human objects and ideas.",example:"The road doesn't want us on it tonight.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:274,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Reified-abstracts",desc:"Treats abstract concepts as tangible, solid physical objects.",example:"Grief sat down at the table like an uninvited guest and never left.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:275,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Sarcastic-literal",desc:"States literal facts in a tone that subverts their meaning.",example:"Yes. Obviously. Clearly that's what I meant.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:276,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Strictly-literal",desc:"Uses vocabulary exclusively in its primary, un-metaphorical sense.",example:"When I say 'immediately' I mean now, this second.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:277,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Symbolic-lexicon",desc:"Employs words representing deep archetype or cultural symbols.",example:"The wolf at the door isn't a wolf.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:278,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Synecdochic",desc:"Uses parts of an object to represent the whole or vice versa.",example:"Twenty swords at the gate.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:279,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Synesthetic",desc:"Blends sensory words (e.g., 'loud colors', 'sweet sounds').",example:"That was a loud shade of red, and it tasted faintly of regret.",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:280,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Unvarnished-plain",desc:"Uses simple, direct, raw vocabulary with zero decorative imagery.",example:"He took the money. He left. That's it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:281,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Acronymic",desc:"Replaces full noun phrases with spoken initialisms and acronyms.",example:"Get it to the QM before the CO asks.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:282,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Agglutinative-style",desc:"Strings multiple semantic modifiers directly onto base nouns.",example:"That's a whole-village-burned-down-in-winter kind of sorrow.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:283,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Anglicized-foreign",desc:"Applies standard English grammatical endings to foreign loanwords.",example:"He's been fully anglicized — 'café-ing' it up with the best of them.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:284,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Archaic-affixed",desc:"Attaches obsolete prefixes and suffixes (e.g., -wise, -some, fore-) to modern words.",example:"That was foolishly done, weather-wise, timing-wise, everything-wise.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:285,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Compound-heavy",desc:"Relies on combining multiple words into dense, fused modifiers.",example:"Bone-tired, road-worn, half-frozen.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:286,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Derivational-rich",desc:"Frequently converts words between parts of speech on the fly.",example:"The decision decisioned itself, more or less, once we stopped deciding not to.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:287,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Diminutive-heavy",desc:"Appends diminutive endings to soft-pedal or downplay nouns.",example:"Just a wee problem. A smallish one.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:288,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Guttural-stemmed",desc:"Favors words with hard, harsh consonant roots and stop sounds.",example:"Grok. Krunch. Gutted.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:289,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Hyphenated-chain",desc:"Strings disparate adjectives together into long hyphenated descriptors.",example:"A three-day-old, over-boiled, badly-seasoned disappointment of a stew.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:290,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Monosyllabic-bound",desc:"Restricts vocabulary strictly to simple, single-syllable words.",example:"Take the coin. Go. Don't turn back.",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":-1,"warm":0}},
{id:291,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Neologistic",desc:"Frequently invents and coinages entirely new words or blended terms.",example:"He's got a case of the dreadfuls.",intensity:5,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:292,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Nominalized",desc:"Turns action verbs and adjectives into dense, static nouns.",example:"The abandonment of the position was an error.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:293,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Onomatopoeic",desc:"Populates speech with words that mimic physical sounds.",example:"Thunk. Then nothing. Then a sort of drag.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:294,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Polysyllabic",desc:"Favors long, multi-syllable vocabulary over shorter alternatives.",example:"An unconscionable and wholly unsubstantiated allegation.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:295,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Portmanteau-prone",desc:"Habitually fuses existing words together to form novel hybrids.",example:"Absolutely gloomtacular out there.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:296,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Prefix-stacked",desc:"Piles structural prefixes (un-, re-, pre-, hyper-) onto root words.",example:"Un-re-do it. Now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:297,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Reduplicative",desc:"Uses repeated or rhyming word pairs to emphasize intensity.",example:"He's not just clever, he's clever-clever.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:298,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Root-bound",desc:"Prefers classical Latin or Greek root words over common Germanic stems.",example:"Not 'strength'. Fortitude, from the Latin, if you please.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:299,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Syllable-clipped",desc:"Drops inner unstressed syllables from complex vocabulary.",example:"S'prob'ly fine, I'd reckon.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:300,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Truncated-lexicon",desc:"Systematically clips off word endings or beginnings for brevity.",example:"'Fess up. 'Course. 'Bout time.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:301,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Alliterative-prone",desc:"Selects words starting with the same consonant sounds.",example:"Cold coin, cold comfort, cold company.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:302,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Cacophonous",desc:"Favors harsh, discordant, and grating word choices.",example:"Crushed, cracked, gutted, wrecked.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:303,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Crisp-consonantal",desc:"Employs clear, sharply defined consonant word endings.",example:"Absolute. Correct. Final.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:304,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Dissonant",desc:"Mixes clashing sound structures to create auditory tension.",example:"Cracked. Cracked. Clashing.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:305,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Euphonic",desc:"Prefers melodious, harmonious, and pleasant-sounding vocabulary.",example:"A slow, low, golden evening.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:306,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Fricative-dense",desc:"Chooses words rich in breathy 'f', 'v', 'th', and 'ph' sounds.",example:"A soft, breathy sort of grief — full of v's and th's.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:307,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Gliding-phonetic",desc:"Employs words with smooth transitions between syllables.",example:"The words slide from one into the next, unbroken.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:308,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Guttural-heavy",desc:"Favors deep, throat-resonant vocabulary.",example:"Grog. Grit. Gone.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:309,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Liquid-consonant",desc:"Favors smooth words dominated by 'l' and 'r' sounds.",example:"All rolling, all rivers, all the long way round.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:310,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Mellow-voweled",desc:"Selects open, soft vowel sounds to create a relaxed auditory tone.",example:"A warm, open, easy kind of vowel — nothing sharp about it.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:311,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Monotonous-phonetic",desc:"Selects words with similar pitch and stress profiles.",example:"Every word lands on the exact same note. And the next. And the next.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:312,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Nasal-dominant",desc:"Selects words with heavy 'm' and 'n' sound frequencies.",example:"Mm-hmm. Nnn. Mine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:313,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Percussive-lexicon",desc:"Chooses words that sound like rhythmic beats when spoken.",example:"Tick. Tock. Done. Gone.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:314,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Plosive-rich",desc:"Chooses words heavy in sharp 'p', 't', 'k', and 'b' sounds.",example:"Pack it, put it back, be quick.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:315,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Resonant-booming",desc:"Favors deep, full-vowel words that project loudly.",example:"OPEN. THE. GATE.",intensity:4,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:316,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Rhyming-echo",desc:"Selects words that create internal rhymes within phrases.",example:"He fled the deed, and the deed he'll never be freed.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:317,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Rhythmic-metered",desc:"Chooses words whose natural stress creates poetic speech cadence.",example:"The rhythm of it, once you hear it, you can't unhear.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:318,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Sibilant-heavy",desc:"Populates speech with words rich in 's', 'z', and 'sh' sounds.",example:"Softly, softly, says the season.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:319,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Staccato-phonetic",desc:"Uses short, punchy words that create a clipped auditory effect.",example:"Get. Up. Now.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":1,"form":0,"warm":0}},
{id:320,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Whisper-soft",desc:"Selects quiet, airy words requiring low vocal effort.",example:"...hush... it's all hushed...",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:321,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Assertion-heavy",desc:"Employs strong declarative vocabulary presenting opinions as fact.",example:"That's how it is. Not an opinion.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:322,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Commitment-verbs",desc:"Uses words that bind the speaker to future actions ('pledge', 'guarantee').",example:"I pledge it. Before witnesses.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:323,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Concessive-words",desc:"Uses vocabulary designed to acknowledge counter-points ('granted', 'admittedly').",example:"Granted. Admittedly. And yet.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:324,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Defensive-lexicon",desc:"Selects words intended to justify, excuse, or protect.",example:"I only did what I was told to do.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:325,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Deictic-heavy",desc:"Relies on pointing words ('this', 'that', 'here', 'there', 'now').",example:"That one. There. Now. Not this.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:326,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Directive-focused",desc:"Uses vocabulary aimed at guiding, instructing, and correcting.",example:"Left hand higher. No — higher.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:327,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Dismissive-lexicon",desc:"Selects words aimed at downplaying or rejecting input.",example:"Irrelevant. Next.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:328,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Distancing-lexicon",desc:"Selects words that create social or emotional detachment.",example:"One might reasonably conclude something happened.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:329,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Exhortative-words",desc:"Uses encouraging, inspiring, and urge-filled vocabulary.",example:"Up! On your feet! We are not finished!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:330,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Expressive-lexicon",desc:"Selects vocabulary aimed primarily at venting internal states.",example:"I just — I need to say this out loud, whether it helps or not.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:331,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Hedging-lexicon",desc:"Selects words designed to protect the speaker from commitment.",example:"It could conceivably be argued that perhaps—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:332,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Honorific-lexicon",desc:"Employs titles, respectful forms, and deference vocabulary.",example:"Your Grace. My lord. If it please you.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:333,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Imperative-lexicon",desc:"Uses forceful command verbs to direct listener action.",example:"Move. Kneel. Hold.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:334,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Inquisitive-verbs",desc:"Employs active probing verbs to extract information.",example:"Where were you. Who told you. Why now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:335,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Interrogative-focused",desc:"Populates speech with question-forming and inquiry vocabulary.",example:"Who told you? When? And why then?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:336,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Modal-rich",desc:"Employs verbs expressing necessity, permission, and possibility ('must', 'should').",example:"You should. You must. You might have to.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:337,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Performative-verbs",desc:"Selects action verbs that execute the act as uttered ('promise', 'declare').",example:"I hereby release you from it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:338,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Phatic-vocabulary",desc:"Uses words whose sole purpose is maintaining social contact without real content.",example:"Right. Yes. Mm. Indeed. Quite.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:339,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Relational-connectors",desc:"Uses vocabulary designed to build rapport and agreement.",example:"You and I both know how this goes, don't we?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:340,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Transactional-words",desc:"Uses clear, exchange-oriented vocabulary for negotiating.",example:"I'll give you the horse for the plough and the debt cleared.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:341,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Abstract-categorical",desc:"Favors umbrella terms and broad conceptual groupings over specific items.",example:"It's a sort of situation. A general category of problem.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:342,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Ambiguity-seeking",desc:"Selects double-entendre or multi-meaning words deliberately.",example:"Well, that could mean several things, couldn't it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:343,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Amorphous",desc:"Uses fluid, poorly defined vocabulary that leaves room for interpretation.",example:"It's — a thing. Sort of. In a way.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:344,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Approximative",desc:"Uses round numbers and fuzzy descriptors rather than exact values.",example:"Forty-odd. Give or take a dozen.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:345,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Broad-spectrum",desc:"Uses generalized verbs and nouns that cover wide ranges of action.",example:"We'll deal with it. Somehow.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:346,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Catch-all-lexicon",desc:"Overuses a small set of versatile words for multiple distinct concepts.",example:"Yeah, it's a whole deal, that thing, with the stuff.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:347,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Definitional-clarity",desc:"Explicitly defines word choices mid-sentence to ensure comprehension.",example:"When I say 'soon', I mean within the hour.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:348,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Delineated",desc:"Employs vocabulary that draws clear boundary lines between concepts.",example:"That's category one. This is category two. They don't overlap.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:349,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Exact-nomenclatural",desc:"Uses formal, taxonomy-level names rather than common nouns.",example:"Not a hawk. A female sparrowhawk, second-year.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:350,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Granular-adjectival",desc:"Uses highly specific adjectives to capture subtle distinctions.",example:"Not tired — depleted. Not sad — hollowed.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:351,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Hyper-specific",desc:"Uses precise, highly granular vocabulary to pinpoint exact meanings.",example:"Two inches left of the third hinge.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:352,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Indefinite-pronoun-heavy",desc:"Overuses words like 'someone', 'whatever', 'somewhere', and 'anything'.",example:"Someone said something to somebody, apparently.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:353,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Literalist",desc:"Restricts word choices strictly to primary dictionary definitions.",example:"'Literally' means literally. I'll use it correctly, thank you.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:354,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Loose-synonymic",desc:"Interchanges loosely related words without regard for minor nuances.",example:"Sad, upset, bothered — pick whichever, they're all close enough.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:355,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Mathematical-precision",desc:"Applies logical and mathematical terms to ordinary relationships.",example:"The risk roughly triples past the ford.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:356,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Qualitative-focused",desc:"Prioritizes subjective quality descriptors over measurable metrics.",example:"It felt right. That's really all I can say about it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:357,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Quantitative-rich",desc:"Packs speech with numerical, statistical, and measurable terms.",example:"Nine crates, four missing, sixty percent loss.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:358,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Surgical-vocabulary",desc:"Selects the single most exact word available for any given context.",example:"Not 'sad'. Bereft.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:359,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Technical-exact",desc:"Selects domain-accurate terminology to eliminate subjective interpretation.",example:"Hairline fracture, distal, non-displaced.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:360,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Vague-generalized",desc:"Relies on broad, indeterminate terms like 'thing', 'stuff', and 'aspect'.",example:"There's a thing. With the stuff. You know.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:361,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Archaisms",desc:"Incorporates obsolete or out-of-date words into contemporary turns.",example:"Methinks the fellow doth protest.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:362,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Bureaucratic-prose",desc:"Employs dry, official administrative terminology in personal matters.",example:"Your application is pending review.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:363,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Clinical-neutral",desc:"Uses cold, objective, emotionless terminology devoid of color.",example:"Onset was gradual. Progression, rapid.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:364,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Coarse-slang",desc:"Uses vulgar, abrasive, or street-level slang terms.",example:"Sod that, and sod him too.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:365,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Colloquial-basic",desc:"Uses standard everyday conversational vocabulary without flourish.",example:"Yeah, no, it's fine, don't worry about it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:366,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Courtly-refined",desc:"Employs delicate, highly polite, and aristocratic vocabulary.",example:"You honour me beyond my deserving.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:367,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Dysphemistic",desc:"Selects intentionally harsh, blunt, or derogatory lexical equivalents.",example:"He didn't pass away. He rotted in a ditch.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:368,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Elementary-lexicon",desc:"Restricts vocabulary to basic, highly accessible childhood terms.",example:"Big dog. Bad dog. Run away now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:369,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Elevated-Latinate",desc:"Employs high-register, formal vocabulary derived from classical Latin/French.",example:"A most egregious and lamentable dereliction.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:370,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Elevated-archaic",desc:"Uses ancient, solemn phrasing reserved for ritual or scripture.",example:"And in those days, the word went forth across the land.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:371,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Elevated-poetic",desc:"Prefers evocative, lyrical word choices over functional prose.",example:"The morning arrived, gentle as a held breath.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:372,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Euphemistic",desc:"Replaces direct terms with gentle, indirect, or neutral substitutes.",example:"He's been let go. Permanently.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:373,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"High-rhetorical",desc:"Favors elevated, persuasive vocabulary designed for formal speeches.",example:"We stand, today, at a crossroads history will remember.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:374,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Hyper-pedantic",desc:"Selects overly precise, dictionary-exact vocabulary to avoid ambiguity.",example:"To be precise — and precision matters here — the term denotes exactly this.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:375,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Jargon-adjacent",desc:"Uses specialized terminology outside its intended field for general subjects.",example:"We need to leverage the synergy of this friendship, going forward.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:376,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Sermo-vulgaris",desc:"Uses low-register, raw, unrefined everyday speech terms.",example:"Ain't nothin' to it. Just get on with it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:377,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Slang-saturated",desc:"Relies heavily on ephemeral, highly localized informal slang.",example:"Proper mugged off, weren't ya.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:378,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Sociolect-bound",desc:"Uses vocabulary specific to a closed social class or peer group.",example:"You know the drill — same as always, same crew.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:379,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Sub-cultural-argot",desc:"Incorporate coded vocabulary understood only by specific insular groups.",example:"You know the word. That's all that needs saying.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:380,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Vernacular-authentic",desc:"Relies on regional dialect terms and unpretentious native words.",example:"Aye, that'll do. That'll do fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:381,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Absolute-modifiers",desc:"Uses unyielding modifiers like 'always', 'never', 'total', 'pure'.",example:"Never. Not once. Not ever.",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:382,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Adjective-heavy",desc:"Packs sentences with descriptive adjectives before nouns.",example:"A cold, cracked, colourless little room.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:383,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Adverb-saturated",desc:"Modifies almost every action verb with descriptive adverbs.",example:"He walked slowly, deliberately, almost mockingly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:384,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Attributive-stacked",desc:"Piles multiple descriptive terms directly onto subjects.",example:"A tired, hollow-eyed, wind-bitten old soldier.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:385,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Comparative-dense",desc:"Packs speech with comparative (-er) and superlative (-est) words.",example:"Worse than yesterday, better than tomorrow.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:386,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Descriptive-minimalist",desc:"Limits modifiers strictly to primary colors, sizes, and shapes.",example:"Big room. Red door.",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:387,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Double-adjective",desc:"Pairs modifiers together before every major noun.",example:"A cold, hard winter.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:388,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Evaluative-rich",desc:"Selects modifiers that pass judgment on every subject.",example:"A poor plan, badly made, worse executed.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:389,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Intensifier-bound",desc:"Overuses amplification adverbs ('extremely', 'incredibly', 'totally').",example:"Absolutely, completely, totally finished.",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:390,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Modal-adverb-heavy",desc:"Employs certainty adverbs ('certainly', 'possibly', 'definitely').",example:"Certainly true. Possibly wrong. Definitely worth checking.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:391,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Modifier-stripped",desc:"Uses bare, unadorned vocabulary with zero fluff or commentary.",example:"Room. Door. Man. Knife.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:392,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Negation-heavy",desc:"Builds meaning through negative framing ('not', 'un-', 'never').",example:"Not wrong. Not right either. Not simple.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:393,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Noun-centric",desc:"Builds meaning around heavy, specific nouns with minimal modifiers.",example:"Coin. Debt. Blood. Consequence.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:394,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Participial-modifier",desc:"Uses verb-derived -ing and -ed words as main descriptive tools.",example:"The fading light. The broken chair.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:395,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Pleonastic",desc:"Uses redundant modifiers that repeat inherent noun meanings.",example:"A tiny little small room, cramped and confined and narrow.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:396,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Predicative-focused",desc:"Places descriptive words after linking verbs rather than before nouns.",example:"The room felt small. The air seemed heavy.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:397,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Qualifying-heavy",desc:"Protects statements with softening adverbs ('somewhat', 'partially').",example:"Somewhat late, partially resolved, mostly fine.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:398,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Relational-modifier",desc:"Uses words defined strictly by contrast with other things.",example:"Taller than him. Older than her. Slower than before.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:399,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Sensory-modifier-dense",desc:"Fills modifier slots exclusively with physical sensory terms.",example:"Rough. Cold. Sharp. Wet.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:400,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Verb-driven",desc:"Relies entirely on powerful, active verbs, stripping out adjectives.",example:"He ran, fell, rose, kept running.",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:401,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Affirmation-looping",desc:"Nods and says 'yeah yeah' while structuring statements.",example:"So we go north — yeah yeah — and then we double back — yeah yeah — through the pass.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:402,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Agreement-prompt",desc:"Inserts 'am I right?' into mid-sentence pauses.",example:"It's the only option, am I right? Am I right?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:403,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Agreement-seeking tags",desc:"Appends phrases seeking listener validation to statements.",example:"It's the right call, isn't it? It is.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:404,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Attention-grabber-opener",desc:"Starts turns with 'Look', 'Listen', or 'Check this out'.",example:"Look. Listen to me.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:405,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Authority-anchor",desc:"Repeats 'trust me' or 'believe me' throughout dialogue.",example:"Trust me on this one. Trust me.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:406,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Casual-connector",desc:"Uses 'and stuff like that' as a generic phrase closer.",example:"We packed up, said our goodbyes, and stuff like that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:407,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Casual-hedging-filler",desc:"Overuses 'sort of' or 'kind of' within predicate verbs.",example:"It's sort of, kind of, a bit of a problem, I guess.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:408,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Conversational bridge-user",desc:"Uses 'that being said' or 'anyway' to string clauses.",example:"That being said, anyway, let's move on.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:409,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Conversational softener",desc:"Uses 'I mean' or 'kind of' to reduce statement harshness.",example:"I mean, it's kind of a problem?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:410,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Conversational-hook",desc:"Begins sentences with 'Here's the thing...' repeatedly.",example:"Here's the thing — no, really, here's the thing—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:411,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Direct-address anchor",desc:"Uses 'man', 'dude', or 'sir' as punctuation markers.",example:"No, man, listen, man—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:412,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Discourse-marker heavy",desc:"Starts phrases with 'well', 'so', 'look', or 'honestly'.",example:"Well — so — look, honestly—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:413,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Dramatic-pause-filler",desc:"Uses 'listen to me' as a filler phrase to demand focus.",example:"Listen to me. Listen to me. This matters.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:414,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Emphasis-interjection",desc:"Inserts 'boom', 'bam', or 'bingo' between sentence steps.",example:"And boom — there it is. Bam — done. Bingo.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:415,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Emphasis-particle user",desc:"Uses 'literally' or 'totally' as structural markers.",example:"That's literally, totally the whole point.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:416,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Exclamatory starter",desc:"Begins every spoken turn with a loud exclamation.",example:"WELL! Here we are again!",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:417,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Expletive-bracketed",desc:"Surrounds main clauses with mild or strong profanity.",example:"That's — [expletive] — completely — [expletive] — unacceptable.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:418,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Hedge-opener",desc:"Begins thoughts with 'Correct me if I'm wrong, but...'.",example:"Correct me if I'm wrong, but wasn't that your idea?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:419,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Hedging tag-user",desc:"Appends 'maybe' or 'I guess' to weaken commitment.",example:"We'll manage, I guess. Maybe.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:420,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Honesty-marker",desc:"Continuously inserts 'to be honest' or 'frankly' into speech.",example:"To be honest? Frankly? No.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:421,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Interrogative opener",desc:"Frames statements as questions before delivering them.",example:"We're doing this now? Yes. We're doing this now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:422,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Minimizing-tag",desc:"Ends statements with 'just saying' to reduce conflict.",example:"Just saying. That's all. Just saying.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:423,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Modal-filler user",desc:"Overuses 'would', 'could', or 'might' to soften verbs.",example:"I would, could, might consider it, perhaps.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:424,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Photic-response user",desc:"Constantly prompts the listener with 'see?' or 'get it?'.",example:"See? See what I mean? Get it?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:425,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Pronoun-floating tags",desc:"Adds disconnected pronouns at sentence ends for emphasis.",example:"That's the plan, him. Final answer, her.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:426,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Punctuation-by-intonation",desc:"Uses dramatic pitch shifts to signal commas and periods.",example:"(the pitch alone tells you where the sentence ends)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:427,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Questioning-anchor",desc:"Starts statements with 'Guess what?' or 'You know what?'.",example:"Guess what? You'll never guess what happened.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:428,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Reflexive backing-phrases",desc:"Ends statements with 'or whatever' or 'and stuff'.",example:"We hung out, watched a film, or whatever.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:429,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Reflexive-disclaimer",desc:"Appends 'no offense' before or after making observations.",example:"No offense, but that plan's terrible.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:430,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Rhetorical filler user",desc:"Inserts 'if you will' or 'so to speak' into casual dialogue.",example:"He's, if you will, something of a legend.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:431,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Sarcastic-anchor",desc:"Adds 'clearly' or 'obviously' to soften or sharpen points.",example:"Clearly, obviously, this was never going to work.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:432,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Self-reassuring-tag",desc:"Adds 'I think' or 'I suppose' at the end of firm facts.",example:"He's guilty. I think. I suppose.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:433,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Softening-opener",desc:"Starts tough statements with 'I hate to say it, but...'.",example:"I hate to say it, but you were wrong.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:434,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Stall-phrase user",desc:"Uses 'how should I put this' to buy time mid-speech.",example:"How should I put this...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:435,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Summarizing-filler",desc:"Inserts 'at the end of the day' to bridge statements.",example:"At the end of the day, he's gone.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:436,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Tag-question reliant",desc:"Ends almost every statement with 'right?', 'isn't it?', or 'yeah?'.",example:"Cold, isn't it? Bad business, yeah?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:437,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Topic-anchor-user",desc:"Repeats the main topic noun every few words to stay focused.",example:"The shipment — about the shipment — regarding the shipment—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:438,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Vague-continuation-tag",desc:"Ends phrases with 'etcetera, etcetera' or 'and so on'.",example:"Bread, milk, eggs, etcetera, etcetera.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:439,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Validate-seeking-tag",desc:"Appends 'you know what I mean?' to every single clause.",example:"You know what I mean? You know what I mean?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:440,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Vocative-heavy address",desc:"Repeats the listener's name continuously throughout dialogue.",example:"Aldiss. Aldiss, listen. Aldiss.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:441,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Abrupt redirection",desc:"Sharply pivots grammar structure mid-clause.",example:"So I was thinking we could — actually, forget that, what if instead—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:442,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Aphasic-stumble",desc:"Temporarily loses access to simple words mid-conversation.",example:"It's the — the thing — the word for the thing—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:443,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Breath-control-break",desc:"Runs out of air mid-sentence, forcing an awkward pause.",example:"I wanted to say that I— (gasps for air) —sorry, one second.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:444,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Breath-gasping spacer",desc:"Inhales sharply between clauses as a rhythmic placeholder.",example:"(inhale) —and then— (inhale) —we left.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:445,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Broken-rhythm speaker",desc:"Speech speed fluctuates unpredictably within single sentences.",example:"He walked. In. Slowly. Then all at once, quickly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:446,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Choppy cadence",desc:"Lacks smooth sentence transitions; jagged rhythm.",example:"He left. She called. Nobody answered. It rained.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:447,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Cluttered-speech",desc:"Rapid, jerky speech where words collide and lose clarity.",example:"Ineedyoutolisten—wait—no—just—give me a second.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:448,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"False-start heavy",desc:"Begins sentences, stops, and restarts them frequently.",example:"I was— no— what I mean is—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:449,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"False-start-stacker",desc:"Restarts a sentence three or four times before finishing.",example:"I was going to— no, wait— what I meant— actually, never mind—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:450,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Filler-word saturated",desc:"Overloads speech with 'um', 'uh', 'like', and 'you know'.",example:"So, um, like, you know, basically—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:451,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Glottal-stop-user",desc:"Uses sharp vocal cord cuts to pause between words.",example:"I— (glottal stop) —can't— (glottal stop) —do this.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:452,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Hesitant-staccato",desc:"Delivers words in slow, halting, uncertain single steps.",example:"I. Don't. Know. What. To. Say.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:453,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Hesitation-pause prone",desc:"Inserts noticeable silences between spoken words.",example:"It was... about... four, I think.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:454,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Interjection-heavy",desc:"Frequently interrupts own flow with emotional exclamations.",example:"And then — oh no — and then he — wait —",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:455,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Involuntary-hum",desc:"Hums quietly while thinking of the next spoken word.",example:"Mm... let me think... mm...",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:456,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Jerky pacing",desc:"Irregular speed changes that disrupt logical sentence structures.",example:"He said it slowly, then suddenly fast, then slow again.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:457,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Mid-clause-gasp",desc:"Takes sharp gasps of air in the middle of smooth clauses.",example:"I need— (gasp) —to tell— (gasp) —you something.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:458,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Mid-sentence stutterer",desc:"Stumbles over sound transitions within spoken phrases.",example:"I c-can't do that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:459,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Mid-thought abandonment",desc:"Stops speaking mid-idea and moves to a brand new thought.",example:"I was saying that— actually, you know what, forget it, tell me about your day.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:460,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Mumble-restart",desc:"Mumbles incoherently before restating the sentence clearly.",example:"Mmf— mm— sorry, what I meant to say was—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:461,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Phoneme-stumble",desc:"Gets stuck repeating individual consonant sounds mid-word.",example:"P-p-pass me the—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:462,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Repetitive restart",desc:"Repeats the first few words of a sentence 2-3 times.",example:"And I— and I— and I told him.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:463,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Self-corrector",desc:"Constantly edits and fixes spoken word choices mid-sentence.",example:"He's cruel — no, not cruel — careless.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:464,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Self-interrupting-climax",desc:"Cuts off own sentence right before delivering the main point.",example:"And that's when I realized— (stops completely)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:465,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sentence-fragmenter",desc:"Breaks single thoughts into detached, floating fragments.",example:"Gone. All of it. Just gone.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:466,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Staccato-burst speech",desc:"Fires off rapid 2-3 word fragments separated by pauses.",example:"Gone. All of it. Just — gone.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:467,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Stammer-recovery",desc:"Stammers briefly, clears throat, then resumes smoothly.",example:"I-I- (clears throat) —apologies. As I was saying.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:468,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Stutter-start",desc:"Repeats initial sounds or words several times before speaking.",example:"I-I-I didn't touch it.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:469,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Swallow-mid-word",desc:"Physically pauses mid-word, breaking syntax flow.",example:"I ca-(pause)-n't do that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:470,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Syllable-elongator",desc:"Stretches out the last syllable of a word while thinking.",example:"It's just soooo... difficult.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:471,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Thought-collision",desc:"Two distinct thoughts try to come out of the mouth simultaneously.",example:"I wanted to say— and also— both at once— sorry—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:472,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Throat-clearing cadence",desc:"Uses vocal clearing as a structural pause in dialogue.",example:"(clears throat) Now. To business.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:473,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Trail-off habit",desc:"Lets the ends of sentences fade into silence without finishing.",example:"I suppose if we just...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:474,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Trailing ellipsis speaker",desc:"Leaves multiple thoughts hanging in incomplete dialogue turns.",example:"I suppose if we just... and then maybe...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:475,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Trailing-off murmur",desc:"Ends spoken thoughts in quiet, unintelligible mumbles.",example:"...s'nothing... don't worry 'bout it...",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:476,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Trailing-whisper-fade",desc:"Starts loud but fades into an inaudible whisper at the end.",example:"I NEED TO TELL YOU— ...something.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:477,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Unfinished-clause-stacker",desc:"Leaves multiple consecutive sentences incomplete.",example:"We should probably— And also I think— Actually, never mind—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:478,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Vocal-fry-pause",desc:"Uses creaky vocal fry during long pauses between phrases.",example:"...and theeen... (creaky pause) ...we left.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:479,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Vocalized-pause-varied",desc:"Alternates between 'um', 'er', 'ah', and 'like' continuously.",example:"So, um, it's, er, kind of, ah, like—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:480,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Word-search-stall",desc:"Stops completely mid-sentence while searching for a noun.",example:"Pass me the — the — the thing—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:481,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Absolute-minimalist-syntax",desc:"Strips all adjectives, adverbs, and articles from speech.",example:"Take horse. Ride north. Warn them.",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:482,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Article-dropping telegrapher",desc:"Skips 'a', 'an', and 'the' in rapid spoken delivery.",example:"Give me cup. On table.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:483,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Article-stripper",desc:"Drops 'a' and 'the' systematically across all sentences.",example:"Take horse. Ride north. Find man.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:484,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Auxiliary-dropping fast-talker",desc:"Omits helping verbs ('You going?' instead of 'Are you going?').",example:"You coming? You sure?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:485,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Clipping-habits",desc:"Shortens long words systematically ('Info', 'Sec', 'Pic').",example:"Get the info. Quick sec. Send the pic.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:486,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Collapsed-clause speaker",desc:"Fuses main and subordinate clauses into single sounds.",example:"He'ssaidhe'llgothoughhemightnot.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:487,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Compacted phrase-user",desc:"Squeezes multi-word phrases into single spoken sounds.",example:"Y'wanna go?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:488,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Condensed-clause-fuser",desc:"Merges cause and effect into single short utterances.",example:"Rained, so flooded.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:489,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Conjunction-clipper",desc:"Drops linking words, stacking clauses directly.",example:"Rained, roads flooded, we're stuck.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:490,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Contraction-heavy",desc:"Contracts every possible verb pair ('I'd've', 'couldn't've').",example:"I'd've told you if I'd've known.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:491,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Copula-dropping dialect",desc:"Omits 'to be' verbs ('He late' instead of 'He is late').",example:"He late. She gone. We ready.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:492,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Dense-abbreviation",desc:"Uses acronyms and initialisms in casual spoken turn.",example:"ASAP, ETA, TBD, whatever.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:493,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Elision-dense",desc:"Slurs word boundaries together ('Gonna', 'Wanna', 'Shoulda').",example:"Gonna hafta shoulda-woulda our way outta this.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:494,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Elliptical dialogue-user",desc:"Relies heavily on implied context, cutting half the phrase.",example:"You know. The thing. With him.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:495,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Elliptical-questioner",desc:"Asks questions using only a noun ('Coffee?', 'Keys?').",example:"Coffee? Keys?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:496,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Fast-contraction-stacker",desc:"Fuses three words together ('Y'all'd've' - You all would have).",example:"Y'all'd've loved it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:497,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Guttural-abbreviation",desc:"Reduces two-word phrases into single guttural sounds.",example:"Mn-kay.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:498,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Head-noun-dropper",desc:"Omits the main noun when context is obvious ('Want this?').",example:"Want this?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:499,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Headline-syntax",desc:"Speaks in short, punchy news-headline style statements.",example:"BRIDGE DOWN. TWO DEAD. SEND HELP.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:500,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Imperative-compressor",desc:"Issues orders using only single action verbs ('Move', 'Look').",example:"Move. Look. Go.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:501,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Initial-drop colloquial",desc:"Drops the first sound/word of sentences ('Bout time).",example:"'Bout time.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:502,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Monosyllabic-compression",desc:"Condenses whole answers into 'Yep', 'Nope', or 'Meh'.",example:"Yep. Nope. Meh.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:503,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Predicate-dropper",desc:"States subject then stops ('Me? No. Him.').",example:"Me? No. Him.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:504,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Preposition-dropper",desc:"Omits prepositions ('Stay home' vs 'Stay at home').",example:"Stay home.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:505,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Preposition-eliminator",desc:"Removes connecting prepositions ('Go store', 'Come home').",example:"Go store. Come home.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:506,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Pronoun-omitter",desc:"Leaves out personal pronouns entirely in brief replies.",example:"Went. Saw. Left.",intensity:5,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:507,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Single-word replyer",desc:"Restricts conversational turns strictly to single words.",example:"No.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:508,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Slurred-boundary speaker",desc:"Blends sentence ends into sentence starts continuously.",example:"Ithoughtsowe'llgothen.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:509,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Slurred-compound-user",desc:"Fuses common word pairs ('Dunno', 'Gotta', 'Gimme').",example:"Dunno. Gotta go. Gimme a sec.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:510,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Subject-dropping speaker",desc:"Omits first-person pronouns ('Went to store. Got milk.').",example:"Went out. Got bread. Came back.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:511,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Syllable-clipped speaker",desc:"Swallows middle syllables of long spoken words.",example:"Prob'ly. Def'nitely.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:512,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Tail-end-clipper",desc:"Cuts off the final word of a sentence if context is clear.",example:"I'll be there at—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:513,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Telegraphic spoken-style",desc:"Delivers news-headline style spoken sentences.",example:"Bridge down. Two dead. Send help.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:514,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Telegraphic-responder",desc:"Gives status updates in minimal two-word verb/noun pairs.",example:"Shipment's late. Crew's fine.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":1,"form":0,"warm":0}},
{id:515,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Terminal-consonant-clipper",desc:"Drops ending consonants of words ('Runnin', 'Goin', 'An').",example:"Runnin' late, goin' now, an' that's that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:516,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Truncated-response maker",desc:"Answers in 1-2 word absolute minimum fragments.",example:"Fine. Later.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:517,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Uncontracted formalist",desc:"Refuses to use contractions in speech ('cannot', 'I am').",example:"I cannot. I will not. I am leaving.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:518,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Verbless-utterance speaker",desc:"Communicates primarily using noun and adjective phrases.",example:"Cold room. Broken chair. Locked door.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:519,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Vowels-swallower",desc:"Compresses words by skipping inner vowel sounds ('Prb'ly').",example:"Prb'ly, y'know, s'pose so.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:520,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Zero-copula-user",desc:"Completely drops linking verbs ('She my sister', 'They ready').",example:"She my sister. They ready.",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:521,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Afterthought-addition",desc:"Finishes a sentence, then tacks on two more clauses.",example:"We'll go Tuesday. If the roads hold. Which they won't.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:522,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Anacoluthon speaker",desc:"Changes grammatical structure mid-sentence unexpectedly.",example:"I wanted to say — actually, forget the wanting, here's what happened.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:523,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Appended-thought speaker",desc:"Tacks extra clauses onto the end of finished sentences.",example:"We left. Which was hard. Which he understood, eventually.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:524,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Appositive-pivot",desc:"Inserts long descriptive noun phrases that hijack the main clause.",example:"The man — tall, grey-coated, unmistakably armed — stepped forward.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:525,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Appositive-stacker",desc:"Piles up descriptive noun phrases back-to-back in speech.",example:"A tired man. A hungry man. A man with nothing left to lose.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:526,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Asymmetrical dialogue-turn",desc:"Starts speech formally, ends in casual grammatical chaos.",example:"Good evening, esteemed guests — anyway, drinks are over there, help yourselves.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:527,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Asyndetic-stacker",desc:"Piles up clauses without conjunctions ('I came, I saw, I left').",example:"I came, I saw, I left.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:528,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Chained-clause rambler",desc:"Links endless clauses together using 'and then... and then'.",example:"And then he left and then she called and then—",intensity:4,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:529,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Chained-relative-clauses",desc:"Links endless 'which' and 'who' clauses together.",example:"The man who sold the horse that threw the boy who broke his arm is here.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:530,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Circular-syntax-shift",desc:"Ends the sentence with the exact same words it started with.",example:"It rained the whole way. The whole way, it rained.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:531,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Conditional-flip",desc:"States the result first, then tacks on multiple 'if' conditions.",example:"We're not going. If the roads flood. If the horse is lame. If anything at all goes wrong.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:532,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Double-framing speaker",desc:"States the main point twice, wrapping the middle detail.",example:"We're leaving. Because of the storm, the roads, the horses. We're leaving.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:533,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Double-subject-framing",desc:"States subject twice ('My father, he always said...').",example:"My father, he always said the same thing.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:534,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Echo-building speaker",desc:"Repeats the previous speaker's syntax before altering it.",example:"You think it's finished? — I think it's finished, yes.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:535,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Embedded-quote-speaker",desc:"Embeds direct quotes of other people inside live clauses.",example:"He said, and I quote, 'never again' — his words, not mine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:536,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Fractured-syntax",desc:"Sentence grammar breaks into pieces under high emotion.",example:"He said— he said—he SAID—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:537,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Fragment-glued speaker",desc:"Builds long thoughts by stitching incomplete fragments.",example:"Gone. All gone. Nothing left. Nothing at all.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:538,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Grammatical-drift",desc:"Sentence starts with one tense and drifts into another.",example:"He walks in and he said hello and then leaves.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:539,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Inversion-in-speech",desc:"Flips standard subject-verb order for dramatic emphasis.",example:"Never have I seen such disregard.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:540,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Left-dislocation user",desc:"Places main noun first, pronoun second ('My brother, he said').",example:"That man, I don't trust him.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:541,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Mid-clause-interjection",desc:"Inserts a second dialogue line inside an existing clause.",example:"He said — 'wait, hold on' — that he'd be late.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:542,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Mid-sentence pivot",desc:"Switches argument direction midway through a clause.",example:"We should absolutely — actually, no, we shouldn't.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:543,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Nested-clause speaker",desc:"Embeds clauses inside clauses, testing listener memory.",example:"The man who sold the horse that threw the boy is here.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:544,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Parallel-structure-builder",desc:"Builds sentences with symmetrical matching clause pairs.",example:"He came, he saw, he conquered. He left, he grieved, he returned.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:545,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Parenthetical-aside speaker",desc:"Inserts long, unrelated side-thoughts inside active sentences.",example:"He said — and I quote, mind — 'never'.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:546,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Parenthetical-stacker",desc:"Inserts three layers of side-thoughts inside one sentence.",example:"He said (and I believe him, mostly, though I have doubts) that it was fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:547,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Passive-to-active-pivot",desc:"Starts in passive voice then angrily shifts to active voice.",example:"It was decided by the council — no, THEY decided it, and badly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:548,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Patchwork syntax",desc:"Combines multiple dialect structures in one utterance.",example:"He weren't there, see, on account of the storm and that.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:549,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Pivoting-conjunction-user",desc:"Starts sentences with 'But' or 'However' to flip topics.",example:"But he never showed. However, we waited anyway.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:550,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Polysyndetic-stream",desc:"Overuses 'and' to chain long strings of clauses together.",example:"And the rain and the mud and the cold and the waiting.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:551,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Retroactive clarification",desc:"Adds conditions to a statement after delivering it.",example:"We're going. Assuming the roads clear. Assuming the horses hold.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:552,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Retroactive-modifier",desc:"Adds adjectives at the end of sentences rather than before nouns.",example:"The room felt small, and cold, and forgotten.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:553,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Reversed-syntax talker",desc:"Puts action first and actor second in spoken turns.",example:"Struck, he was, by the news.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:554,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Right-dislocation user",desc:"Places main pronoun first, noun at end ('He's crazy, that guy').",example:"He's mad, that one.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:555,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Run-on spoken stream",desc:"Speaks without clear sentence boundaries or periods.",example:"We got there it was closed nobody knew anything so we left.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:556,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Scrambled-word-order",desc:"Arranges words unconventionally due to high emotion/dialect.",example:"Went we, finally, to the gate.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:557,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Sudden-syntax-inversion",desc:"Flips sentence structure upside down halfway through.",example:"Never before this moment have I witnessed such folly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:558,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Syntax-deconstruction",desc:"Dismantles standard grammar rules to create artistic effect.",example:"broken. is. this. sentence. and. that. is. the. point.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:559,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Topic-fronting speaker",desc:"Moves the object/topic to the start ('That movie, I loved it').",example:"That business at the docks — I heard about it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:560,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Topic-jump-grammar",desc:"Abruptly shifts sentence structure to address a new thought.",example:"It rained — anyway, did you finish the report?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:561,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Anticipatory responder",desc:"Answers before the other person finishes their question syntax.",example:"—no, before you finish, no.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:562,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Backchannel-heavy",desc:"Provides constant grammatical agreement signals while listening.",example:"Mm. Right. Mm-hm. Go on.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:563,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Challenging-turn-opener",desc:"Opens turn with direct counter-question ('Oh really?').",example:"Oh, really.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:564,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Collaborative-build grammar",desc:"Leaves sentences open for partner completion.",example:"So if we just— (leaves it open for the other to finish)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:565,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Competitive-opener",desc:"Uses 'Wait, wait, wait' to steal turn ownership.",example:"Wait wait wait — my turn.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:566,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Conciliatory cadence",desc:"Uses soothing, rhythmic sentence endings to lower tension.",example:"...and we'll figure the rest out together, won't we.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:567,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Confrontational pivot",desc:"Uses 'No, but...' to hijack conversational turns.",example:"No, but listen — that's not what happened at all.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:568,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Contested-turn syntax",desc:"Fights for turn control by restarting sentence openers.",example:"As I was— no, as I was saying—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:569,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Conversational-intercept",desc:"Grabs a word from another's speech and builds new sentence.",example:"You said 'trust' — well, trust is exactly the problem.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:570,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Cooperative-completion",desc:"Finishes the grammar of whoever is currently speaking.",example:"—and that's when he— yes, exactly, that's when.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:571,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Deflecting grammar",desc:"Redirects sentence subjects away from self.",example:"Someone made that call. Not naming names.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:572,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Deflective-turn-shift",desc:"Grammatically passes the speaker turn to a third party.",example:"That's really a question for him, not me.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:573,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Dialogue-closing syntax",desc:"Delivers definitive, summary-style sentence structures.",example:"That settles it. We're done here.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:574,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Echo-questioner",desc:"Turns incoming statements into immediate question echoes.",example:"Dangerous? Dangerous?",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:575,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Echo-responder",desc:"Repeats the listener's question structure back as an answer.",example:"Am I sure? Are you sure you're asking?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:576,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Echo-response-builder",desc:"Repeats opponent's last words before launching own point.",example:"'Not my problem,' you said. Well, it is now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:577,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Evasive-turn structure",desc:"Answers with questions to deflect turn ownership.",example:"Why do you ask?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:578,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Floor-hogging syntax",desc:"Uses non-ending conjunctions to prevent others from speaking.",example:"—and furthermore, and additionally, and moreover—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:579,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Floor-yield-question",desc:"Ends turns with open questions to force someone else to talk.",example:"So — what do you think we should do?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:580,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Interruption-adapted",desc:"Structures phrases to be complete even if cut off midway.",example:"—which is why we're leaving. (could stop here, or continue)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:581,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Interruption-primed",desc:"Structures sentences specifically to cut off other speakers.",example:"—but before you finish, I have to say—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:582,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Interruption-shielded",desc:"Speaks in continuous, unpausing streams to prevent cuts.",example:"(speaks in one continuous stream, no gap wide enough to interrupt)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:583,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Inviting-cadence",desc:"Lowers pitch and slows pace at clause end to invite input.",example:"...and that's really all there is to it...",intensity:3,rarity:"common",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:584,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Mirror-syntax speaker",desc:"Adopts the exact grammar complexity of their conversation partner.",example:"(matches the other speaker's exact sentence complexity, beat for beat)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:585,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Monopolizing-syntax",desc:"Uses complex nested clauses that make interruption impossible.",example:"Given that, considering also, and notwithstanding the fact that, we should proceed.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:586,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Overlap-accommodator",desc:"Speaks louder over competing speech without stopping grammar.",example:"(raises volume mid-sentence without breaking stride) —AS I WAS SAYING—",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:587,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Overlapping-claimant",desc:"Starts speaking over others using loud introductory clauses.",example:"WELL ACTUALLY— if I could just—",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:588,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Pivot-turn-taker",desc:"Acknowledges previous speaker brief, then pivots topic completely.",example:"Fair point. Anyway, about the shipment—",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:589,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Prompt-dependent",desc:"Requires listener prompts to move to the next clause.",example:"And then? ...And then? Go on.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:590,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Prompting-pause-user",desc:"Leaves sentence open at a key moment to force a response.",example:"So really, the only question is...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:591,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Rapid-fire-turn-taker",desc:"Jumps into conversational gaps in under a millisecond.",example:"(fills the half-second gap before anyone else can)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:592,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Retort-primed syntax",desc:"Structures answers as immediate grammatical counter-attacks.",example:"You call that an argument? Here's an actual one.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:593,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Sentence-finisher (others)",desc:"Completes the grammatical turns of other speakers.",example:"—and that's exactly why we should—finish it for him—leave now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:594,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Slow-turn-claimant",desc:"Takes control of dialogue turn with long, deliberate silences.",example:"(says nothing for a long moment, and the room waits)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:595,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Tag-team-grammar",desc:"Structures thoughts to be seamlessly picked up by a partner.",example:"—which leads directly into—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:596,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Territorial-speaker",desc:"Loudly restarts sentence from beginning if interrupted.",example:"AS I WAS SAYING. Before I was so rudely interrupted.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:597,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-holding-conjunction",desc:"Stretches 'anddd' or 'buttt' to hold floor while thinking.",example:"Anddd... buttt...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:598,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-yielding structure",desc:"Engineers sentence ends to explicitly invite a response.",example:"...don't you think?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:599,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Yielding-disclaimer",desc:"Starts with 'I might be wrong' to invite immediate takeover.",example:"I might be wrong, but—",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:600,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Yielding-pause maker",desc:"Pauses mid-clause to force the other person to chime in.",example:"...and so...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:601,section:"Mannerisms",category:"Emotional Affectations",trait:"Brooding-silence gap",desc:"Leaves heavy, moody silences before giving simple answers.",example:"(long silence) ...Fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:602,section:"Mannerisms",category:"Emotional Affectations",trait:"Bubbly-burst delivery",desc:"Speaks with sudden bursts of uncontainable, effervescent joy.",example:"IT WORKED! IT ACTUALLY WORKED!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:603,section:"Mannerisms",category:"Emotional Affectations",trait:"Cold-snicker edge",desc:"Uses sharp, humorless scoffs to cut down opponent's points.",example:"(a short, dry scoff) That's your argument?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:604,section:"Mannerisms",category:"Emotional Affectations",trait:"Contemptuous scoff",desc:"Blows breath out with a harsh 'Pfft' to mock silly suggestions.",example:"Pfft. That's your plan?",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:605,section:"Mannerisms",category:"Emotional Affectations",trait:"Deadpan flatness",desc:"Drains all emotion from tone during absurd or crazy situations.",example:"(flat, unmoved) A dragon. Of course. Naturally.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:606,section:"Mannerisms",category:"Emotional Affectations",trait:"Defensive-bark tone",desc:"Snaps defensively at innocent or neutral questions.",example:"What? What do you want.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:607,section:"Mannerisms",category:"Emotional Affectations",trait:"Feigned-innocence giggle",desc:"Giggles softly to disarm criticism or play coy.",example:"(a soft giggle) Oh, don't be cross with me.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:608,section:"Mannerisms",category:"Emotional Affectations",trait:"Flustered-flush flutter",desc:"Fanning self or tugging collar when flustered or embarrassed.",example:"(fans self, tugs collar) It's — warm in here, isn't it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:609,section:"Mannerisms",category:"Emotional Affectations",trait:"Forced-hearty laugh",desc:"Over-exaggerates laughter to break social tension or hide anxiety.",example:"(laughs too loud, too long) Ha! Ha ha! Very funny.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:610,section:"Mannerisms",category:"Emotional Affectations",trait:"Manic-giggle burst",desc:"Laughs unexpectedly at stressful or dangerous occurrences.",example:"(giggles helplessly, at entirely the wrong moment)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:611,section:"Mannerisms",category:"Emotional Affectations",trait:"Melodramatic moan",desc:"Emits exaggerated groans over minor inconveniences.",example:"(groans dramatically) The tea's gone cold. This is a tragedy.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:612,section:"Mannerisms",category:"Emotional Affectations",trait:"Mock-shock drama",desc:"Places hand over heart with wide eyes to play-act offense.",example:"(hand to heart, eyes wide) I am SCANDALIZED.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:613,section:"Mannerisms",category:"Emotional Affectations",trait:"Over-apologetic gasp",desc:"Gasps and apologizes profusely for minor interruptions.",example:"(gasps) Oh — sorry — so sorry — didn't mean to—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:614,section:"Mannerisms",category:"Emotional Affectations",trait:"Performative shudder",desc:"Shivers exaggeratedly when mentioning unpleasant topics.",example:"(shudders theatrically) Don't even say the word.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:615,section:"Mannerisms",category:"Emotional Affectations",trait:"Sardonic snicker",desc:"Delivers a cold, short laugh at improper or sad news.",example:"(a short, cold laugh) How tragic. Truly.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:616,section:"Mannerisms",category:"Emotional Affectations",trait:"Smug-chuckle prelude",desc:"Chuckles softly before explaining why someone else is wrong.",example:"(chuckles softly) Well, someone's got it backwards.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:617,section:"Mannerisms",category:"Emotional Affectations",trait:"Snidely-sweet tone",desc:"Uses sickeningly sweet gentleness to deliver biting insults.",example:"Oh, sweetheart. That was almost a good idea.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:618,section:"Mannerisms",category:"Emotional Affectations",trait:"Tearful-crack voice",desc:"Voice trembles emotionally even during mundane discussions.",example:"(voice cracks) It's — it's fine, really.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:619,section:"Mannerisms",category:"Emotional Affectations",trait:"Weary-sigh cadence",desc:"Begins every response as if carrying the weight of the world.",example:"(sighs) Right. What is it this time.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:620,section:"Mannerisms",category:"Emotional Affectations",trait:"Whisper-secret tone",desc:"Lowers voice to a conspiratorial whisper regardless of subject.",example:"(leans in, voice drops to a whisper) Don't tell anyone I said this.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:621,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Boundary-toucher",desc:"Touches doorframes, walls, and furniture as they walk and talk.",example:"(fingers trail along the wall as they walk and talk)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:622,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Chair-spin seated",desc:"Spins swivel chair in half-circles during monologue.",example:"(spins the chair in slow half-circles while talking)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:623,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Coaster-aligner",desc:"Obsessively adjusts drink coasters under glasses.",example:"(adjusts the coaster under the glass, again)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:624,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Curtain-peeker",desc:"Pulls back window blinds slightly while speaking.",example:"(peeks through the blinds mid-sentence)",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:625,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Doorway-frame blocker",desc:"Stands directly in doorways while holding conversations.",example:"(stands squarely in the doorway, blocking it)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:626,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Dust-speck plucker",desc:"Picks imaginary lint or dust off clothing or table.",example:"(picks an invisible speck off their sleeve)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:627,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Floor-tile stepper",desc:"Paces strictly within grid pattern of floor tiles.",example:"(steps only within the tile lines, deliberately)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:628,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Foot-rest elevator",desc:"Props feet up on chairs, desks, or rails casually.",example:"(props feet up on the desk without asking)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:629,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Key-lock turner",desc:"Fiddles with door handles or locks while talking near exits.",example:"(fiddles with the door handle near the exit)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:630,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Light-switch fiddler",desc:"Tinkers with nearby switches, blinds, or fixtures.",example:"(flicks the light switch on and off, thinking)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:631,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Object-relocator",desc:"Picks up nearby objects and moves them to new positions.",example:"(picks up the cup, moves it three inches, sets it down)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:632,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Paper-stack squarer",desc:"Taps stack of paper against desk to make edges even.",example:"(taps the papers square against the desk)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:633,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Prop-arranger",desc:"Neatly aligns cups, pens, and paper while talking.",example:"(lines the pens up parallel while talking)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:634,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Seat-changer",desc:"Moves to a different chair in the room mid-conversation.",example:"(gets up, moves to another chair, keeps talking)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:635,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Shadow-staring",desc:"Focuses eyes on shadows or background lighting effects.",example:"(watches the shadow on the wall rather than the room)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:636,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Surface-leaner",desc:"Finds desk, table, or wall to lean against instantly.",example:"(finds the nearest wall and leans against it)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:637,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Table-tapper percussion",desc:"Uses table as drum surface during conversational pauses.",example:"(drums a rhythm on the table between sentences)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:638,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Temperature-adjuster",desc:"Fusses with thermostat, fans, or windows mid-topic.",example:"(fusses with the thermostat mid-topic)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:639,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Wall-drummer palm",desc:"Rests palm against wall and taps fingers against plaster.",example:"(palm flat on the wall, fingers tapping)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:640,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Window-gazer talker",desc:"Delivers thoughts while staring out window away from room.",example:"(delivers the whole thought staring out the window)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:641,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Asymmetrical brow",desc:"Raises a single eyebrow continuously during interrogation.",example:"(one brow up, held) Mm-hm.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:642,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Ceiling-gazer",desc:"Looks directly up at the ceiling when retrieving facts or memories.",example:"(looks up) What was the name...",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:643,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Divergent gaze",desc:"Looks slightly past the listener's ear rather than into their eyes.",example:"(gaze lands just past their ear, never quite meeting it)",intensity:1,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:644,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Eyebrow-flash opener",desc:"Raises both eyebrows high for a split second upon starting a turn.",example:"(both brows flick up for half a second) So!",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:645,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Flaring nostrils",desc:"Dilates nostrils slightly when making authoritative or angry demands.",example:"(nostrils flare slightly) I said now.",intensity:1,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:646,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Floor-fixated gaze",desc:"Directs gaze entirely at the ground while speaking of personal things.",example:"(eyes fixed on the floor) It wasn't like that.",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:647,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Jaw-clench freeze",desc:"Tightens jaw muscles visibly between sentences under tension.",example:"(jaw tightens) Continue.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:648,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Lip-bite pause",desc:"Nips lower lip with teeth while deciding whether to speak frankly.",example:"(bites lip) ...I shouldn't say.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:649,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Micro-nod rhythm",desc:"Nods head in tiny, rapid continuous bounces while speaking.",example:"(head bounces in tiny rapid nods while speaking)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:650,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Mouth-twitch beat",desc:"Shows brief involuntary twitches at the corners of the mouth.",example:"(the corner of the mouth twitches, once)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:651,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Nose-scrunch disgust",desc:"Wrinkles nose bridge when discussing disliked people or concepts.",example:"(nose wrinkles) That's revolting.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:652,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Pursed-lip filter",desc:"Tightens lips into a small circle before delivering unpleasant truth.",example:"(lips press into a small circle) ...I have to tell you something.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:653,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Rapid-blink flutter",desc:"Blinks rapidly when caught off guard or attempting to calculate responses.",example:"(blinks rapidly) I— give me a second, I need to think.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:654,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Side-eye glance",desc:"Shifts pupils sideways without moving head when making sarcastic remarks.",example:"(eyes slide sideways) Oh, I'm sure that's true.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:655,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Slow-blink reset",desc:"Closes eyes fully for two full seconds to reset composure.",example:"(closes eyes for two seconds) ...Right.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:656,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Smirk-break",desc:"Flips one corner of the mouth into a half-smile before punchlines.",example:"(half-smile) Funny you should ask.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:657,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Squinting inspector",desc:"Narrows eyes into tight slits when questioning or doubting statements.",example:"(narrows eyes) Is that so.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:658,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Unblinking stare",desc:"Maintains intense, unbroken eye contact throughout full monologues.",example:"(does not blink for the entire answer)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:659,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Wide-eyed marvel",desc:"Expands eyelids widely to convey innocence, shock, or surprise.",example:"(eyes widen) No. NO.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:660,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Wink-punctuated",desc:"Winks playfully or conspiratorially at the conclusion of key phrases.",example:"...and that's that. (winks)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:661,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Air-sketching",desc:"Traces invisible shapes and diagrams in the air to explain ideas.",example:"(draws the shape in the air) Like that. See?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:662,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Chin-rub listener",desc:"Strokes chin slowly while formulating spoken responses.",example:"(strokes chin) Hm.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:663,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Clenched-fist beat",desc:"Pumps a loose fist downward in time with important verbs.",example:"(pumps a loose fist with each key word)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:664,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Finger-count list",desc:"Counts off points explicitly on fingers while speaking.",example:"(counts off) Food, water, rope, coin.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:665,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Finger-tapping cadence",desc:"Taps fingers rhythmically on surfaces in sync with spoken syllables.",example:"(fingers tap out the rhythm of each syllable)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:666,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Foot-tap meter",desc:"Taps heel or toe loudly on floor to establish speech rhythm.",example:"(heel taps the floor, keeping time)",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:667,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Glasses-adjuster",desc:"Pushes glasses up the nose bridge right before making an important point.",example:"(pushes glasses up) Here's the difficulty.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:668,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Hand-chop emphasis",desc:"Uses sharp, karate-chop hand movements to slice through key arguments.",example:"(chops palm) That. Is. Not. Happening.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:669,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Hand-wave brush",desc:"Sweeps hand horizontally as if wiping away unpleasant topics.",example:"(sweeps a hand sideways) Let's not talk about that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:670,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Head-tilt pause",desc:"Cocks head sharply to one side before offering an opinion.",example:"(tilts head) ...Is that what you think?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:671,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Lapel-tugging",desc:"Pulls at collar or lapels when structuring serious or formal remarks.",example:"(tugs at the collar) Now. To serious matters.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:672,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Leaning-in tilt",desc:"Bends torso forward dramatically into interlocutor's personal space.",example:"(leans in close) Say that again.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:673,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Pacing-synced delivery",desc:"Takes step strides that strictly match the rhythm of spoken phrases.",example:"(each stride lands exactly on the stressed syllable)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:674,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Palms-up pleading",desc:"Flips open hands palms-up whenever asking questions or deflecting.",example:"(opens hands) What would you have me do?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:675,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Point-and-stab",desc:"Jabs index finger forward in the air to emphasize direct accusations.",example:"(jabs finger) You. You did this.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:676,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Shoulder-shrug pivot",desc:"Shrugs shoulders constantly mid-sentence to indicate indifference.",example:"(shrugs mid-sentence) Could be anything, really.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:677,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Sleeve-roll ritual",desc:"Fusses with cuffs or pushes up sleeves right as dialogue intensifies.",example:"(rolls up a sleeve as the argument sharpens)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:678,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Steepled fingers",desc:"Presses fingertips together into a pyramid while speaking thoughtfully.",example:"(presses fingertips together) Go on. I'm listening.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:679,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Temple-rubbing",desc:"Massages temples with thumb and forefinger when explaining hard tasks.",example:"(rubs temples) Explain it again. Slowly.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:680,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Wrist-flick dismiss",desc:"Flicks wrist casually away to dismiss counterarguments.",example:"(flicks hand) Doesn't matter.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:681,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Blinking-squeeze",desc:"Squeezes eyes shut tightly for a second to collect thoughts.",example:"(squeezes eyes shut for a second) ...Right. Continue.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:682,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Cheek-puff exhale",desc:"Puffs out cheek muscles fully before releasing air.",example:"(puffs cheeks out fully, releases slowly)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:683,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Chin-scratch rhythm",desc:"Scratches stubble or chin three times while listening.",example:"(scratches the chin three times, listening)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:684,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Collar-loosen tug",desc:"Hooks finger under shirt collar and pulls forward.",example:"(hooks a finger under the collar, tugs)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:685,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Earlobe-tug focus",desc:"Pulls gently on earlobe when pondering a response.",example:"(pulls at the earlobe, considering)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:686,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Eye-rub fatigue",desc:"Rubs eyes with heel of hand when asked redundant questions.",example:"(rubs eyes with the heel of a hand) Asked and answered.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:687,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Finger-rub friction",desc:"Rubs thumb and index finger together continuously.",example:"(rubs thumb and finger together, continuously)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:688,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Forehead-rub crease",desc:"Presses index finger between eyebrows while concentrating.",example:"(presses a finger between the brows, concentrating)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:689,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Hair-push back",desc:"Runs fingers back through hair to clear forehead during pauses.",example:"(rakes hand through hair) God. Okay. Okay.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:690,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Head-shake reflex",desc:"Shakes head 'no' softly while uttering positive phrases.",example:"(shakes head 'no' while saying) Absolutely, yes, definitely.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:691,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Jaw-crack popping",desc:"Shifts jaw sideways until joint pops when stressed.",example:"(shifts the jaw until it pops, under stress)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:692,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Knuckle-crack beat",desc:"Flexes and cracks knuckles prior to entering debate.",example:"(cracks knuckles) Right then.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:693,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Lip-lick reset",desc:"Moistens lips with tongue before starting every new clause.",example:"(licks lips before every new clause)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:694,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Mouth-corner wipe",desc:"Wipes corner of mouth with thumb knuckle after speaking.",example:"(wipes the corner of the mouth with a knuckle)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:695,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Neck-stretch twist",desc:"Tilts and rolls neck to crack vertebrae during pauses.",example:"(rolls the neck, cracking it, mid-pause)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:696,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Nose-touch frequency",desc:"Touches tip or bridge of nose repeatedly while speaking.",example:"(touches the bridge of the nose, repeatedly)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:697,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Shoulder-twitch snap",desc:"Gives single abrupt shoulder twitch when making decisions.",example:"(one abrupt shoulder twitch) Decided.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:698,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Sleeve-tug adjustment",desc:"Tugs at cuff of left sleeve with right hand periodically.",example:"(tugs the left sleeve cuff, periodically)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:699,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Throat-swallow click",desc:"Produces small vocal click with tongue during pauses.",example:"(a small click of the tongue during the pause)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:700,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Tongue-in-cheek press",desc:"Pokes tongue against inner cheek while listening to rivals.",example:"(tongue presses against the inner cheek, listening)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:701,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Audible swallow",desc:"Swallows loudly before answering difficult or tense questions.",example:"(swallows hard) Right. Yes.",intensity:3,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:702,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Chortle-pause",desc:"Interrupts own thought with a raspy, quiet chuckle before continuing.",example:"(a raspy chuckle interrupts the thought) Heh — anyway.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:703,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Clicking tongue",desc:"Makes repetitive tsking or clicking sounds with tongue when contemplating.",example:"Tsk. Tsk tsk.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:704,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Gasp-gasping",desc:"Takes exaggerated, theatrical breaths during dramatic storytelling.",example:"(gasps theatrically) And THEN — you won't believe this—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:705,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Inhaled speech",desc:"Utters short words like 'yeah' or 'no' while actively inhaling air.",example:"(inhales sharply) Yeah — (still inhaling) — no.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:706,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Lip-smack start",desc:"Smacks lips together audibly right before launching a turn of speech.",example:"(smacks lips once) Right. Here we go.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:707,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Murmured assent",desc:"Continuously utters quiet 'mm-hmm' sounds while listening to others.",example:"Mm-hm. Mm. Mm-hm.",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:708,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Muttered cadence",desc:"Mumbles trailing commentary quietly under breath after speaking.",example:"...bloody stupid idea anyway...",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:709,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Nasal snort",desc:"Emits a sharp nasal puff of air to signal disbelief or amusement.",example:"Hnf. Course he did.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:710,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Popping-P sounds",desc:"Over-articulates plosives like 'P' and 'B' with sharp physical pops.",example:"Pop. Pop. The precise plan.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:711,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Rasp-cough",desc:"Briefly dry-coughs to reset voice frequency when switching topics.",example:"(a dry cough) Right. Moving on.",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:712,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sharp air-hiss",desc:"Draws breath sharply through teeth when reacting to unexpected news.",example:"(hiss through teeth) That's bad.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:713,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sigh-punctuated",desc:"Exhales a heavy, weary sigh at the start or end of most sentences.",example:"(sigh) Fine. (sigh) Fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:714,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Snicker-chuckle",desc:"Breaks into brief, quiet chortles mid-sentence without full laughter.",example:"(a quiet chortle, mid-sentence, unfinished)",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:715,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Soft-chime whistle",desc:"Whistles a tiny two-note tune when searching for an object or word.",example:"(whistles two idle notes, searching for the word)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:716,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sub-vocal hum",desc:"Emits a low, rhythmic humming sound while processing thoughts.",example:"(hums low, rhythmic, thinking it through)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:717,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Teeth-grind grumble",desc:"Utters low grunts with clenched teeth under stress.",example:"(a low grunt through clenched teeth)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:718,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Throat-clearing accent",desc:"Habitually clears throat before delivering key points or when nervous.",example:"Ahem. Now. To business.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:719,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Throat-growl",desc:"Produces a low, rumble in the back of the throat when annoyed.",example:"(low growl) Don't.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:720,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Whistling exhale",desc:"Blows air out through pursed lips with a faint whistling tone.",example:"(a faint whistle through pursed lips)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:721,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Backward-tilt recliner",desc:"Leans back excessively far in chair to show utter relaxation.",example:"(tips the chair back) Convince me.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:722,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Barrier-builder",desc:"Places objects (cups, books, laptops) between self and listener.",example:"(sets the cup down between them, deliberately)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:723,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Circle-pacer",desc:"Walks in tight circular orbits around the room while delivering thoughts.",example:"(walks a slow circle) Say it again.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:724,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Corner-backer",desc:"Retreats physically against walls or corners while engaged in speech.",example:"(edges toward the wall) I'd rather stand.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:725,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Crossed-arms barrier",desc:"Keeps arms tightly folded across chest throughout all interactions.",example:"(arms fold) I'm listening.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:726,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Distance-maintainer",desc:"Takes subtle step backward whenever interlocutor advances.",example:"(steps back, subtly, every time they lean in)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:727,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Head-down bow",desc:"Keeps chin tucked low toward collarbone while talking.",example:"(chin tucked low, speaking to the floor)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:728,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Height-maximizing stance",desc:"Puffs chest and draws spine completely straight to dominate room.",example:"(draws up to full height) You forget yourself.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:729,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Hunted slouch",desc:"Hunches shoulders forward as if protecting chest while speaking.",example:"(shoulders hunch forward, protective)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:730,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Loitering lean",desc:"Props body casually against doorframes or furniture while talking.",example:"(leans casually against the doorframe)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:731,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Looming overhang",desc:"Bends upper body over sitting listeners to project authority.",example:"(bends over the seated listener, looming)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:732,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Perching edge",desc:"Sits on extreme edge of seat as if ready to spring up at any second.",example:"(perched on the seat's edge) So? So?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:733,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Restless fidget-shift",desc:"Transfers body weight repeatedly from foot to foot.",example:"(shifts weight foot to foot, restless)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:734,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Rigid-statue stillness",desc:"Remains entirely motionless without fidgeting while speaking.",example:"(does not move at all while speaking)",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:735,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Seated-standing shift",desc:"Abruptly stands up mid-sentence to deliver core arguments.",example:"(stands up abruptly mid-sentence) Here's the thing.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:736,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Shadowing follower",desc:"Matches physical movements of the main speaker in conversation.",example:"(mirrors the other's posture, unconsciously)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:737,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Side-by-side speaker",desc:"Prefers walking or standing shoulder-to-shoulder rather than face-to-face.",example:"(prefers to walk alongside rather than face them)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:738,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Space-invader shift",desc:"Steps uncomfortably close to listener during emphatic statements.",example:"(steps in close, too close, to make the point)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:739,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Sprawling conqueror",desc:"Spreads arms and legs wide across seating area when conversing.",example:"(spreads across two chairs) Take your time.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:740,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Swivel-chair pivot",desc:"Rotates body back and forth in chair to match conversational tempo.",example:"(chair rotates back and forth with the conversation)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:741,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Arm-around-shoulder",desc:"Throws arm around listener to establish patronizing dominant bond.",example:"(throws arm around) You and me, we're fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:742,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Back-patter rhythm",desc:"Pats listener's back loudly during greetings or agreement.",example:"(pats the back, loudly) Good to see you!",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:743,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Chin-up challenge",desc:"Thrusts chin outward in defiance when boundary is pressed.",example:"(chin juts out) Say that again.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:744,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Cornering stance",desc:"Positions body to block listener's natural exit path.",example:"(positions between them and the door, without seeming to)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:745,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Cover-mouth whisperer",desc:"Cups hand around mouth even when speaking in private rooms.",example:"(cups a hand around the mouth, even in an empty room)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:746,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Double-handshake clasp",desc:"Uses both hands to envelope listener's hand while speaking.",example:"(clasps the hand with both of theirs, holding on)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:747,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Eye-contact avoider",desc:"Looks at doors, windows, or floor rather than interlocutor.",example:"(looks at the floor) It wasn't like that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:748,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Finger-snap inviter",desc:"Snaps fingers toward listener to call for input or answers.",example:"(snaps fingers) Well? Thoughts?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:749,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Formal-bow tilt",desc:"Gives small, formal bows of head when agreeing or saying goodbye.",example:"(a small, formal bow of the head) Until tomorrow.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:750,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Hand-on-hip authority",desc:"Rests hand firmly on hip while giving directions or rules.",example:"(hand on hip) I won't ask twice.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:751,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Head-cocked listener",desc:"Tilts head like an inquisitive animal while listening.",example:"(tilts head, birdlike) Go on.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:752,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Interrupting hand-up",desc:"Holds up open palm to stop others from speaking.",example:"(palm up) Stop. Enough.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:753,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Laughter-seeking glance",desc:"Scans room immediately after speaking to see who laughed.",example:"(scans the room right after the joke, checking who laughed)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:754,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Name-repeater habit",desc:"Says listener's name three or four times per brief conversation.",example:"(says the name three times in one short exchange)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:755,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Over-sharing lean",desc:"Inclines head to share intimate secrets with new acquaintances.",example:"(leans in to share something far too personal)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:756,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Personal-space shrinker",desc:"Inches closer throughout dialogue, eroding boundaries.",example:"(steps closer, and closer again)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:757,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Sideways-step dodge",desc:"Steps laterally away when conversation turns personal.",example:"(steps sideways the moment it gets personal)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:758,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Touch-on-arm anchor",desc:"Reaches out to touch listener's forearm or shoulder for focus.",example:"(touches the forearm to bring the focus back)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:759,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Turning-back exit",desc:"Starts walking away while still delivering final sentence.",example:"(already walking away, still finishing the sentence)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:760,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Whisper-huddle pull",desc:"Beckons listener closer with finger to share trivial facts.",example:"(beckons closer with one finger) Come here — listen to this.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:761,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Beverage-sipper stall",desc:"Takes deliberate sips of coffee or water to delay answering.",example:"(sips, slowly) ...Now. What was the question?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:762,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Card-shuffler rhythm",desc:"Fiddles with cards, papers, or small objects on table.",example:"(shuffles the cards, not looking at them)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:763,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Cigarette-tap gesture",desc:"Taps cigarette or vape device against hand to emphasize points.",example:"(taps the cigarette against the table for emphasis)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:764,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Coin-flipper spin",desc:"Rolls coins or small tokens across knuckles while conversing.",example:"(rolls a coin across the knuckles, thinking)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:765,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Cup-cradler clasp",desc:"Holds hot drink mug with both hands for comfort during speech.",example:"(both hands round the mug) It's warmer in here.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:766,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Fabric-clutcher",desc:"Grips edge of shirt, jacket, or hem tightly during tense turns.",example:"(grips the hem of the jacket, tight)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:767,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Garment-smoothing",desc:"Flattens clothing wrinkles repeatedly with palm while talking.",example:"(smooths the same wrinkle out, again)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:768,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Glasses-cleaner habit",desc:"Takes off glasses to wipe lenses when avoiding direct answers.",example:"(polishes lenses) Now, what exactly did you see?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:769,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Hair-twirler lock",desc:"Twists or pulls at a strand of hair while contemplating words.",example:"(twists a strand) I don't know, do I.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:770,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Key-jangler sound",desc:"Rattles keys in pocket to express impatience or urgency.",example:"(jangles the keys in a pocket, impatient)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:771,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Locket-toucher",desc:"Reaches up to touch necklace, locket, or tie during emotional moments.",example:"(touches the locket at the throat) It was hers.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:772,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Nail-picker focus",desc:"Inspects or picks at fingernails to project detachment.",example:"(inspects nails) Fascinating.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:773,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Object-pointer",desc:"Uses whatever tool or prop is in hand (pencil, knife, spoon) to point.",example:"(uses the pencil to point) Right there. That one.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:774,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Paperclip-bender",desc:"Absently shapes or destroys office supplies while talking.",example:"(bends the paperclip out of shape, absently)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:775,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Pen-clicker beat",desc:"Clicks or twirls a pen repeatedly in sync with sentence rhythms.",example:"(click, click) Say that again.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:776,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Phone-face-down tap",desc:"Slams phone face-down on table before starting serious topic.",example:"(slaps the phone face-down on the table) Now. Seriously.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:777,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Pocket-hand hider",desc:"Plunges both hands deep into coat or pants pockets.",example:"(hands deep in pockets) Suppose so.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:778,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Ring-rotator",desc:"Spins a wedding ring or band around finger during deep thought.",example:"(spins the ring) It's complicated.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:779,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Table-drummer",desc:"Drums fingers on table surface like musical percussion.",example:"(drums fingers) And? And?",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:780,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Watch-checker pause",desc:"Glances at wristwatch or phone clock to break conversational flow.",example:"(glances at watch) Make it quick.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:781,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Breathy-gasp tone",desc:"Speaks with continuous excess air passing over vocal cords.",example:"(voice carries a constant breathy edge)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:782,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Echo-repetition shift",desc:"Repeats key word quietly at lower volume like an echo.",example:"(repeats the key word, quieter, like an echo) — gone. Gone.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:783,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Enunciated-snap",desc:"Articulates every single consonant with surgical precision.",example:"Ev-er-y sing-le word.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:784,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Falsetto-pip jump",desc:"Squeaks up into falsetto pitch when surprised or excited.",example:"(voice cracks up) WHAT?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:785,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Gravelly-bass drop",desc:"Scrapes voice down into raspy, low vocal fry territory.",example:"(voice drops low) Sit. Down.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:786,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Husk-throat warmth",desc:"Uses a warm, velvety rasp when trying to persuade.",example:"(a warm, low rasp) Trust me on this one.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:787,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Monotone-drone",desc:"Speaks in flat, robotic pitch without musical variation.",example:"That is unfortunate. I am concerned. Please continue.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:788,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Nasal-twang accent",desc:"Directs sound resonance heavily through nasal passages.",example:"(sound resonates through the nose, distinct and reedy)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:789,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Operatic-rise",desc:"Allows voice pitch to glide gracefully up and down scales.",example:"(pitch glides up, then gracefully back down)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:790,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Pitch-drop ending",desc:"Drops voice an octave lower on the final word of sentences.",example:"I said no.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:791,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Resonant-projection",desc:"Projects voice like a stage actor even in tiny elevators.",example:"(fills the room) HEAR ME.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:792,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Rising-inflection question",desc:"Ends declarative statements with upward pitch like questions.",example:"So we're doing this? Now? Like this?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:793,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Sing-song cadence",desc:"Speaks with a rhythmic, musical lilt across all sentences.",example:"Oh, we'll SEE about that, won't we~",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:794,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Soft-spoken murmur",desc:"Keeps volume permanently low, forcing others to lean in.",example:"(barely audible) ...I wouldn't, if I were you.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:795,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Speed-shift gear",desc:"Abruptly doubles speech speed when making secondary points.",example:"—and-then-secondly-obviously— but yes. Anyway.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:796,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Staccato-burst pitch",desc:"Punches out words in clipped, high-frequency rhythmic bursts.",example:"WORDS. LIKE. THIS. PUNCHED. OUT.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":1,"form":0,"warm":0}},
{id:797,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Syllable-stress shift",desc:"Puts unusual accent stress on incorrect syllables.",example:"That's not how you pronounce that, actually.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:798,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Trailing-volume fade",desc:"Allows sentence volume to die away into complete silence.",example:"...and then it just... (fades to nothing)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:799,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Volume-spike emphasis",desc:"Suddenly shouts single words mid-sentence for emphasis.",example:"I said put it DOWN.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:800,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Whisper-to-shout swell",desc:"Grows voice from barely audible whisper to booming loud.",example:"...quietly now... QUIETLY NOW!",intensity:2,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:801,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Effluvious",desc:"Overflowing with excessive, tumbling word output.",example:"There's just — so much to say, and I haven't even gotten to the middle of it.",intensity:4,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:802,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Cataract-speech",desc:"Words pour forth in an unstoppable rushing torrent.",example:"—and then the second thing, which led to the third, which really explains the fourth—",intensity:4,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:803,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Windbaggish",desc:"Talks at excessive length with little substance.",example:"Long story short — it isn't short. Here's the long version.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:804,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Discursive-sprawler",desc:"Wanders through countless subtopics before concluding.",example:"Which brings us, by way of the harbor and my aunt's cooking, to the actual point.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:805,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Babble-brook",desc:"Continuous light chatter that never quite pauses.",example:"Rain again. Same as Tuesday. Same as the week before, come to think of it.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:806,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Overrun-narrator",desc:"Description spills far past the point already made.",example:"—so that's the wall, and past the wall, the field, and past the field, well, more field—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:807,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Verbal-deluge",desc:"Releases an unstoppable surge of words at once.",example:"Right, everything, all at once, from the very beginning, here we go—",intensity:5,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:808,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Windmilling-talker",desc:"Circles the same point with ever more words.",example:"So basically what I'm saying, to restate what I already said, is—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:809,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Clipped-monosyllable",desc:"Trims every reply down to a single short word.",example:"Yes.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:810,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Frugal-tongued",desc:"Treats every spoken word as a scarce resource.",example:"...Mm.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:811,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Bare-bones speaker",desc:"Strips sentences to only their essential parts.",example:"Left. Gone. Won't be back.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:812,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Flint-worded",desc:"Hard, sparse, and unwilling to elaborate further.",example:"No. That's all.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":1,"warm":0}},
{id:813,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Threadbare-reply",desc:"Gives the thinnest possible response to any question.",example:"Fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:814,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Withholding-brevity",desc:"Deliberately shortens answers to avoid revealing more.",example:"Can't say.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:815,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Clipped-nod-speaker",desc:"Prefers gestures over words whenever possible.",example:"(points, once, at the door)",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:816,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Shorn-phrase",desc:"Cuts every phrase down to its bare skeleton.",example:"Not now.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:817,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Adrenal-stutter",desc:"Words trip over each other as fear spikes.",example:"I-I-I don't— wait— just—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:818,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Countdown-cadence",desc:"Speech accelerates as a deadline approaches.",example:"We have — less time than you think. Move.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:819,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Threat-clipped",desc:"Sentences shrink to fragments under perceived danger.",example:"Down. Quiet. Now.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:820,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Recovery-paced",desc:"Speech gradually regains rhythm after a shock.",example:"...okay. Okay. I think — yes. I'm alright.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:821,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Vigilant-pause",desc:"Frequently stops mid-sentence to scan surroundings.",example:"(stops mid-sentence, scans the room) ...Where was I.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:822,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Adrenaline-crash drawl",desc:"Speech slows dramatically once danger passes.",example:"(the words come slower now, and slower still)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:823,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Standoff-measured",desc:"Speaks with exaggerated calm during confrontation.",example:"(perfectly calm, dangerously calm) I'd reconsider that, if I were you.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:824,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Countdown-breathless",desc:"Words rush faster as urgency compounds.",example:"Ten. Nine. Faster now. Eight—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:825,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Baroque-orator",desc:"Layers ornamentation onto every simple statement.",example:"The tea — poured, as ever, at the appointed hour — awaits your most gracious attention.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:826,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Regal-cadence",desc:"Speaks with the measured grandeur of nobility.",example:"The court will rise. The court will always rise.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:827,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Antiquarian-phrase",desc:"Peppers speech with archaic, bookish turns.",example:"Methinks the hour groweth late, forsooth.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:828,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Processional-speech",desc:"Delivers words like a ceremonial march.",example:"Let the doors be opened, and let the procession, however humble, begin.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:829,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Filigreed-diction",desc:"Decorates plain ideas with intricate verbal flourish.",example:"The report, though brief, wears its brevity like a borrowed crown.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:830,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Homeric-narrator",desc:"Frames small events in epic, sweeping language.",example:"And so the ships set forth, as ships have always set forth, toward glory or the deep.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:831,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Cathedral-toned",desc:"Speech carries a hushed, reverent grandeur.",example:"(speaks as though beneath a vaulted ceiling, every word given room to echo)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:832,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Embroidered-prose",desc:"Adds ornamental detail to every plain fact.",example:"The door — old, iron-bound, its hinges singing a private grief — creaked open.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:833,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Gravitational-lexicon",desc:"Chooses words evoking pull, weight, and mass.",example:"That kind of grief has real mass. It pulls everything else toward it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:834,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Luminous-vocabulary",desc:"Favors words of glow, brightness, and radiance.",example:"Her face, lit from somewhere inside, like a lamp behind paper.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:835,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Cartographic-words",desc:"Describes ideas using mapping and terrain terms.",example:"We're at the edge of the map here. Everything past this is unmarked country.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:836,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Thermal-descriptive",desc:"Selects vocabulary rooted in heat and cold.",example:"His welcome was warm. Hers was several degrees colder.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:837,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Atmospheric-lexicon",desc:"Uses weather and air-based descriptive words.",example:"There's a front coming in. You can feel it in the pressure before you see the clouds.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:838,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Skeletal-structural",desc:"Frames concepts through bone and framework imagery.",example:"Strip away the ceremony and you find the bones of the thing, plain and load-bearing.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:839,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Chromatic-focused",desc:"Heavily emphasizes color-based descriptive words.",example:"Red coat, grey sky, and her hair gone gold in the last of the light.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:840,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Vibrational-sensory",desc:"Chooses words describing hums, buzz, and tremor.",example:"There's a hum under this whole conversation. You feel it more than hear it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:841,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Wistful-drenched",desc:"Saturates speech with longing, faded-memory words.",example:"We used to sit right here. Before all of this.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:842,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Combustible-diction",desc:"Uses words that seem to ignite with anger.",example:"Say it again and see what catches fire.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:843,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Frost-toned",desc:"Chooses icy, withholding, emotionally cold vocabulary.",example:"Her greeting arrived like a draft under a locked door.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:844,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Radiant-affirming",desc:"Uses warmly encouraging, glowing praise terms.",example:"You did that. All of it. I'm so proud I could burst.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:845,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Hollow-voiced",desc:"Selects vocabulary that sounds emotionally emptied out.",example:"The words were all there. Nothing behind them.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:846,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Simmering-restraint",desc:"Uses tightly controlled words hinting at suppressed feeling.",example:"(every word chosen, measured, held two degrees below where it wants to go)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:847,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Feverish-devotion",desc:"Employs intensely worshipful, obsessive vocabulary.",example:"I would follow that man into the sea if he asked me to.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:848,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Brittle-composed",desc:"Chooses words that sound calm but ready to crack.",example:"(a calm so tightly held it looks, for a moment, like it might shatter)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:857,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Riddling-speech",desc:"Wraps plain meaning inside puzzle-like phrasing.",example:"The answer you seek lies where the answer always lies — closer than you think.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:858,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Blunt-metaphor",desc:"Pairs harsh directness with occasional sharp imagery.",example:"You're a locked door with the key thrown away. That's the plain truth of it.",intensity:5,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:859,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Circumlocutory",desc:"Talks around a point instead of naming it directly.",example:"Well, there's a certain — situation — that's developed, regarding the — matter.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:860,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Understated-irony",desc:"Downplays significance while implying the opposite.",example:"Well, that could have gone better, I suppose.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:861,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Double-coded",desc:"Speaks so two different audiences hear different meanings.",example:"To you, an apology. To him, a warning. Same nine words.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:862,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Plainspoken-parable",desc:"Explains direct truths through small simple stories.",example:"There was a fox who trusted a wolf, and that is why we lock the gate.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:863,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Veiled-reference",desc:"Alludes to meaning without ever stating it outright.",example:"There's a name I'm not going to say. You know the one.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:864,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Literal-to-a-fault",desc:"Cannot process or produce figurative language at all.",example:"'Break a leg'? Why would you wish injury on me before a performance?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:865,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Suffix-forward",desc:"Builds meaning primarily through inventive suffixes.",example:"That's positively drear-some, that news.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:866,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Blend-coiner",desc:"Regularly fuses two words into a single new term.",example:"Absolutely gloomtastic out there today.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:867,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Root-stacking",desc:"Piles multiple word roots into single dense terms.",example:"That's a proper doom-glum-heavy sort of Tuesday.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:868,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Clipped-neologism",desc:"Shortens invented words further after coining them.",example:"That's not a 'mehday'. It's a 'meh'. We've clipped it further.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:869,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Compound-forger",desc:"Welds unrelated nouns into new descriptive compounds.",example:"He's got real doorframe-shoulders, that one.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:870,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Elision-coiner",desc:"Drops syllables to create smoother invented terms.",example:"Call it a 'trage-dy' — no, shorter — 'tragdy'. That'll do.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:871,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Affix-recycler",desc:"Reuses the same prefix or suffix across many words.",example:"Un-fix it, then re-fix it, then un-fix it again, apparently.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:872,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Syllable-fuser",desc:"Merges the ends and starts of adjacent words together.",example:"Thatwaywe'llgetthere faster, I promise.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:873,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Vowel-elongated",desc:"Draws out vowel sounds for dramatic effect.",example:"Nooooo, absolutely noooot.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:874,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Click-consonant",desc:"Uses sharp, percussive consonant clusters often.",example:"Crack. Crack. Crack. That's the sound of it breaking.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:875,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Hummed-transition",desc:"Bridges words with soft humming sounds.",example:"Mm— the thing is— mm— I don't quite—",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:876,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Breath-punctuated",desc:"Uses audible breaths as sentence punctuation.",example:"I— (breath) —can't— (breath) —just give me a moment.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:877,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Tongue-trilled",desc:"Rolls certain consonants for emphasis or flair.",example:"Rrrready when you arrre.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:878,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Whistled-sibilance",desc:"Produces a faint whistle on 's' sounds.",example:"Sssomething's wrong here.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:879,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Deep-resonant vowels",desc:"Chooses words with rich, open vowel tones.",example:"A slow, low, golden kind of evening.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:880,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Clipped-consonant ending",desc:"Cuts consonant sounds short at word ends.",example:"Sto'. Don'. Migh'.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:881,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Apology-lexicon",desc:"Frequently reaches for words of regret and contrition.",example:"I'm sorry. Truly. I regret every part of it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:882,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Warning-focused",desc:"Selects vocabulary designed to caution the listener.",example:"You'll want to think carefully before doing that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:883,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Reassurance-lexicon",desc:"Chooses calming, confidence-restoring word choices.",example:"It's alright. You're alright. We'll sort it.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:884,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Boundary-setting words",desc:"Uses vocabulary that firmly establishes limits.",example:"That's not up for discussion. Full stop.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:885,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Invitation-lexicon",desc:"Selects welcoming, inclusion-oriented word choices.",example:"Come in, sit down, you're always welcome here.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:886,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Correction-focused",desc:"Uses vocabulary aimed at fixing others' errors.",example:"That's — not quite right, actually. Let me fix that for you.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:887,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Negotiation-hedge",desc:"Chooses words that leave room for later compromise.",example:"We could meet somewhere in the middle, perhaps.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:888,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Gratitude-anchored",desc:"Frequently returns to words of thanks and credit.",example:"Thank you. Genuinely. I mean that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:889,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Fractional-precise",desc:"Uses exact fractions and partial measures often.",example:"Two-thirds of it, give or take a sliver.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:890,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Taxonomic-splitter",desc:"Breaks categories into ever more specific subtypes.",example:"Not just 'birds'. Raptors, then hawks, then specifically sparrowhawks.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:891,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Estimate-hedged",desc:"Frames numbers as careful approximations, not facts.",example:"Roughly forty. Could be thirty-five. Could be forty-five.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:892,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Contextual-vague",desc:"Relies on situation to supply missing specificity.",example:"You'll know it when you see it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:893,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Overlap-avoider",desc:"Chooses words that eliminate any ambiguous overlap.",example:"That's this one, not that one. They're not the same.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:894,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Threshold-focused",desc:"Speaks in terms of exact cutoffs and limits.",example:"Anything past forty, we call it a failure.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:895,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Coordinate-precise",desc:"Describes location using exact positional terms.",example:"Northeast corner, third stone from the wall.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:896,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Blanket-term user",desc:"Applies one broad word across many distinct cases.",example:"That's basically the same as the other thing.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:897,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Corporate-formal",desc:"Speaks with polished, meeting-room professionalism even in personal matters.",example:"Let's circle back to this once we've aligned on next steps.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:898,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Street-casual",desc:"Uses relaxed, unpolished, plainly informal speech by default.",example:"Nah, it's whatever. Not a big deal.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:899,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Diplomatically neutral",desc:"Chooses carefully balanced, non-committal phrasing to avoid taking a side.",example:"There are valid points on both sides, I'd say.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:900,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Jargon-layered",desc:"Layers ordinary speech with dense, specialist-sounding terminology.",example:"The core issue is a fundamental misalignment of incentive structures.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:901,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Folksy-warm",desc:"Uses homespun, familiar, plainspoken vocabulary regardless of the topic.",example:"Well now, that's a fine mess we've got ourselves into.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:902,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Crisply regimented",desc:"Speaks with clipped, regulation-style formality and no wasted words.",example:"Understood. Proceeding as instructed.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:903,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Solemn-reverent",desc:"Uses hushed, ceremonial vocabulary even for ordinary occasions.",example:"Let us proceed, in stillness, as is proper.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:904,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Childlike-simple",desc:"Restricts vocabulary to simple, concrete, easily-grasped terms.",example:"It's not good. It made me sad.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:905,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Triple-adjective stacker",desc:"Piles three descriptive words before each noun.",example:"A cold, hard, unforgiving winter.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:906,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Zero-modifier speaker",desc:"Presents nouns and verbs with no embellishment.",example:"Door. Room. Man. Chair.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:907,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Superlative-obsessed",desc:"Reaches for 'best' or 'worst' constantly.",example:"Best day ever. Worst mistake ever. Biggest regret, definitely.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:908,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Understatement-modifier",desc:"Uses deliberately mild words for big events.",example:"Bit of a scrape, really. Nothing major.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:909,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Overstatement-modifier",desc:"Inflates ordinary events with extreme modifiers.",example:"Worst day of my entire life, easily the worst, catastrophically bad.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:910,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Contrast-pairing",desc:"Places opposite modifiers side by side for effect.",example:"Loud but gentle. Furious but kind.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:911,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Sensory-adjective stacker",desc:"Piles multiple sensory descriptors per noun.",example:"A cold, wet, gritty, foul-smelling mess.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:912,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Bare-verb speaker",desc:"Relies on verbs alone, stripping most modifiers.",example:"Ran. Fell. Rose. Ran again.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:913,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Confidence-anchor",desc:"Repeats 'no doubt' or 'for certain' often.",example:"No doubt about it. For certain, this is the way.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:914,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Time-stall filler",desc:"Inserts 'let's see' while buying thinking time.",example:"Let's see. Let's see. Give me a moment.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:915,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Reassurance-tag",desc:"Ends statements with 'don't worry' habitually.",example:"Don't worry. Really, don't worry about it.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:916,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Callback-opener",desc:"Starts turns by referencing something said earlier.",example:"Like I said about the fence — remember? — that's exactly the problem here too.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:917,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Permission-seeking tag",desc:"Adds 'if that's okay' after requests.",example:"Could I ask you something, if that's okay?",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:918,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Emphasis-repeater",desc:"Repeats the last word of a sentence for stress.",example:"It's final. Final, I said.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:919,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Transition-bridge",desc:"Uses 'moving on' to shift between topics.",example:"Moving on. Next item.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:920,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Closing-signal filler",desc:"Uses 'anyway' to signal a turn is ending.",example:"Anyway. That's all I've got.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:921,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Loop-restart",desc:"Circles back to the sentence's start repeatedly.",example:"So we left — we left, right, and then — we left, and—",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:922,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Air-swallow pause",desc:"Audibly gulps air before difficult admissions.",example:"(a sharp gulp of air) It's about your brother.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:923,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Word-substitution stumble",desc:"Swaps in a wrong word then quickly corrects.",example:"He was— she was— sorry, she was there too.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:924,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Overlap-stumble",desc:"Trips over words when two thoughts collide.",example:"I was— he was— we were both talking at once, sorry—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:925,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Micro-freeze",desc:"Briefly stops speaking mid-syllable under pressure.",example:"I was going to— (stops entirely mid-word)",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:926,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Echo-stutter",desc:"Repeats the last syllable of a word involuntarily.",example:"It was— was— was terrible.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:927,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Half-swallowed clause",desc:"Drops volume so a clause is barely audible.",example:"(the last few words drop almost to silence) ...I lied.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:928,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Recovery-mumble",desc:"Mumbles briefly before regaining clear articulation.",example:"Mm— sorry— what I meant was, it's finished.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:929,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Time-compressor",desc:"Drops time markers, assuming shared context.",example:"Meet me after. You know when.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:930,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Response-clipper",desc:"Shortens replies to the smallest confirmable unit.",example:"Yep.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:931,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Number-dropper",desc:"Omits quantities when context implies them.",example:"Lost a few. Not sure how many.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:932,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Location-clipper",desc:"Drops place names when setting is already known.",example:"Meet you there. Usual spot.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:933,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Reason-omitter",desc:"Skips explanations, stating only conclusions.",example:"Didn't work. Try again.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:934,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Greeting-skipper",desc:"Bypasses hellos and jumps straight to content.",example:"Shipment's short. Three crates missing.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:935,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Object-implier",desc:"Leaves direct objects unstated when obvious.",example:"Pass it here.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:936,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Question-clipper",desc:"Reduces full questions to a single trailing word.",example:"Coffee?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:937,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Interjected-correction",desc:"Interrupts own clause to correct a detail.",example:"He said — sorry, implied — that we'd lost it.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:938,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Cascading-clause",desc:"Chains dependent clauses one after another endlessly.",example:"Because it rained, because the roads flooded, because we were stuck, because—",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:939,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Backtrack-restructurer",desc:"Restarts a sentence with a different structure.",example:"We should— actually, let me start over. We need to leave.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:940,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Emphasis-fronting",desc:"Moves the most important word to the sentence start.",example:"NEVER have I seen such nonsense.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:941,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Delayed-subject",desc:"Withholds the subject until the sentence's end.",example:"Whoever left that door open — and I have my suspicions — will answer for it.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:942,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Recursive-embedding",desc:"Nests clarifying clauses inside one another repeatedly.",example:"He said (who, by the way, was lying) that the report (which was also false) was accurate.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:943,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Contrast-framing",desc:"Structures sentences around explicit 'not X, but Y'.",example:"Not cruel — careless. That's what he was.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:944,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Summary-closing shift",desc:"Ends long structures with a short blunt clause.",example:"—and after all that. Gone.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:945,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Gentle-interrupter",desc:"Softly cuts in with an apologetic lead-in.",example:"Sorry — sorry to jump in — but I think that's wrong.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:946,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-refuser",desc:"Declines the floor even when explicitly offered.",example:"No, you go ahead. I'll wait.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:947,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Bridging-connector",desc:"Links their turn directly to the prior speaker's words.",example:"You said the bridge was down — right, and that's why we're taking the long way.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:948,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Silence-yielder",desc:"Pauses long enough to invite the next speaker.",example:"...(trails off, waits, leaves room for the answer)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:949,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Reclaiming-restarter",desc:"Takes back the floor after being interrupted.",example:"As I was saying, before I was interrupted—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:950,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Consensus-closer",desc:"Ends turns by inviting agreement from the group.",example:"So we're all agreed, then? Good.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:951,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Deferential-opener",desc:"Begins by acknowledging another's right to speak.",example:"If I may — and only if you don't mind—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:952,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Rapid-relay",desc:"Passes conversational turns quickly without lingering.",example:"Your turn. Go. Next.",intensity:3,rarity:"common",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:953,section:"Mannerisms",category:"Emotional Affectations",trait:"Wistful-half-smile",desc:"Smiles faintly while recalling something bittersweet.",example:"(smiles faintly) We used to sit right there.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:954,section:"Mannerisms",category:"Emotional Affectations",trait:"Anxious-throat-clear",desc:"Clears throat repeatedly when nervous before speaking.",example:"(clears throat, twice) So — right — where were we.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:955,section:"Mannerisms",category:"Emotional Affectations",trait:"Triumphant-grin flash",desc:"Flashes a quick grin after landing a point.",example:"(a flash of a grin) Got you.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:956,section:"Mannerisms",category:"Emotional Affectations",trait:"Guarded-flatline",desc:"Keeps expression neutral to hide true feelings.",example:"(face gives away nothing at all) Interesting.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:957,section:"Mannerisms",category:"Emotional Affectations",trait:"Startled-flinch",desc:"Jerks slightly when caught off guard mid-sentence.",example:"(flinches slightly) Sorry — you startled me.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:958,section:"Mannerisms",category:"Emotional Affectations",trait:"Relieved-exhale",desc:"Releases a visible breath after tension passes.",example:"(exhales, long and visible) Okay. Okay, we're fine.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:959,section:"Mannerisms",category:"Emotional Affectations",trait:"Petulant-pout",desc:"Purses lips in a childish pout when overruled.",example:"(lips press into a small, sullen pout)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:960,section:"Mannerisms",category:"Emotional Affectations",trait:"Grim-tight-smile",desc:"Forces a thin smile that doesn't reach the eyes.",example:"(a smile that stops well short of the eyes) Wonderful.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:961,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Book-spine aligner",desc:"Straightens books on shelves mid-conversation.",example:"(straightens a spine on the shelf mid-sentence)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:962,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Candle-flame watcher",desc:"Gazes at flickering flame while speaking.",example:"(watches the candle flicker rather than the listener)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:963,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Rug-corner fixer",desc:"Nudges rug corners flat with a foot.",example:"(nudges the rug flat with a foot)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:964,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Picture-frame straightener",desc:"Adjusts wall art absentmindedly while talking.",example:"(nudges the picture frame level, mid-sentence)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:965,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Drawer-slider",desc:"Opens and closes a drawer repeatedly while thinking.",example:"(opens and closes the drawer, thinking)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:966,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Plant-leaf toucher",desc:"Brushes fingers over nearby plant leaves.",example:"(brushes a leaf between two fingers while talking)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:967,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Mirror-glancer",desc:"Checks reflection briefly mid-conversation.",example:"(catches their reflection, checks it, moves on)",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:968,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Doorbell-fiddler",desc:"Taps or presses nearby buttons absentmindedly.",example:"(taps the doorbell button, absently, twice)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:969,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Tear-blink suppression",desc:"Blinks hard to hold back visible emotion.",example:"(blinks hard, twice) I'm fine.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:970,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Brow-furrow thinker",desc:"Knits eyebrows tightly when concentrating.",example:"(brow knits tight, thinking it through)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:971,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Half-lidded skeptic",desc:"Lowers eyelids partway when doubting a claim.",example:"(eyelids drop halfway) Is that so.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:972,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Cheek-dimple flicker",desc:"Shows a brief dimple before serious statements.",example:"(a brief dimple appears, then vanishes) Now — seriously.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:973,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Jaw-drop pause",desc:"Lets mouth fall open in genuine or mock surprise.",example:"(mouth falls open) You did NOT.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:974,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Eye-widen alarm",desc:"Snaps eyes wide open at unexpected news.",example:"(eyes snap wide) WHAT.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:975,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Chin-lift defiance",desc:"Raises chin slightly when challenged directly.",example:"(chin lifts slightly) Say that again.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:976,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Lash-flutter charm",desc:"Blinks rapidly and softly to appear disarming.",example:"(blinks quick and soft) You wouldn't do that to me, would you?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:977,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Circular-hand stir",desc:"Rotates hand in small circles while explaining.",example:"(hand circles slowly) It's — sort of — like this.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:978,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Two-hand frame",desc:"Frames an idea in the air with both palms.",example:"(frames the idea with both palms) Picture it like this.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:979,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Fist-to-palm strike",desc:"Taps a closed fist into an open palm for emphasis.",example:"(fist taps into open palm) That's the point exactly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:980,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Finger-steeple release",desc:"Unclasps steepled fingers right before conclusions.",example:"(unclasps steepled fingers) So. That's the plan.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:981,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Sweeping-arc gesture",desc:"Sweeps arm wide to indicate scope or scale.",example:"(arm sweeps wide) The whole valley, all of it.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:982,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Pinch-precision gesture",desc:"Uses thumb and forefinger pinch for small details.",example:"(pinches thumb and forefinger together) Just this much.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:983,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Chest-tap emphasis",desc:"Taps own chest when asserting personal conviction.",example:"(taps own chest) I mean it. Truly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:984,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Downward-press gesture",desc:"Presses palms down to signal calm or finality.",example:"(presses palms flat, downward) Easy. Easy now.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:985,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Tooth-suck pause",desc:"Sucks air through teeth before delivering bad news.",example:"(sucks air through the teeth) That's not good news.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:986,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Wrist-rotation crack",desc:"Rotates wrist audibly during pauses.",example:"(rotates the wrist, audibly, during the pause)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:987,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Eyebrow-scratch stall",desc:"Scratches eyebrow while stalling for an answer.",example:"(scratches an eyebrow, stalling) Well...",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:988,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Cuticle-picker",desc:"Picks at cuticles nervously during tense exchanges.",example:"(picks at a cuticle, not looking up)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:989,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Lip-purse tighten",desc:"Purses lips into a tight line when annoyed.",example:"(lips press into a tight line) Noted.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:990,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Toe-curl tension",desc:"Curls toes inside shoes under visible stress.",example:"(toes curl inside the shoes, unseen)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:991,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Temple-vein throb",desc:"Shows a faint throbbing temple vein when angry.",example:"(a faint vein throbs at the temple) I said no.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:992,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Ear-tug thoughtful",desc:"Tugs earlobe gently while considering a reply.",example:"(tugs the earlobe gently) Let me think on that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:993,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Low-groan opener",desc:"Begins responses with a quiet groan of effort.",example:"(a low groan) Alright. Let's do this.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:994,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Tsk-tsk disapproval",desc:"Makes repeated tsking sounds at bad news.",example:"Tsk. Tsk tsk. Bad business.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:995,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Wheeze-laugh",desc:"Laughs with an audible wheeze at the end.",example:"(laughs, wheezing, at the end of it)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:996,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sniff-punctuation",desc:"Sniffs sharply to punctuate the end of a point.",example:"(a sharp sniff) That settles it.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:997,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Gulp-hesitation",desc:"Audibly gulps before admitting something difficult.",example:"(gulps audibly) I have to tell you something.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:998,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Yawn-interject",desc:"Punctuates boredom with poorly stifled yawns.",example:"(yawns, badly stifled) Sorry — go on.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:999,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Hum-approval",desc:"Hums a rising note to signal agreement.",example:"(hums a rising note) Mm — yes. Good.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1000,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Breath-hiss release",desc:"Releases tension through a long hissing exhale.",example:"(a long hiss of breath) Okay. Okay, better.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1001,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Wall-flat presser",desc:"Presses back flat against a wall when startled.",example:"(back flat against the wall, startled)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:1002,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Table-edge gripper",desc:"Grips table edge tightly during tense exchanges.",example:"(grips the table edge, knuckles pale)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1003,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Knee-bounce energy",desc:"Bounces knee rapidly while seated and speaking.",example:"(knee bounces, fast, under the table)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:1004,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Arms-akimbo stance",desc:"Stands with hands on hips, elbows out, confidently.",example:"(hands on hips, elbows wide) Well?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1005,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Slump-recovery",desc:"Slouches then suddenly straightens for key points.",example:"(slouches, then snaps upright for the key point)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1006,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Diagonal-lean",desc:"Leans body at an angle rather than straight-on.",example:"(leans at an angle, never quite square-on)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1007,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Weight-forward stance",desc:"Shifts weight onto toes when pressing a point.",example:"(weight shifts onto the toes, leaning in)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1008,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Retreat-step speaker",desc:"Steps backward slightly with each new sentence.",example:"(steps back with each new sentence)",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1009,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Introduction-repeater",desc:"Reintroduces self unnecessarily in ongoing talks.",example:"(reintroduces themselves, again, unnecessarily)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1010,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Compliment-deflector",desc:"Physically waves off compliments while thanking.",example:"(waves off the compliment with a hand) Oh, stop.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1011,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-scanner",desc:"Glances around the room to gauge reactions.",example:"(scans the room after speaking, gauging reactions)",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1012,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Space-offering gesture",desc:"Steps back to visibly grant listener more room.",example:"(steps back, visibly making room)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1013,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Interruption-apologizer",desc:"Immediately apologizes physically after interrupting.",example:"(apologizes with a small gesture immediately after interrupting)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1014,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Handshake-lingerer",desc:"Holds handshakes a beat longer than expected.",example:"(holds the handshake a beat too long)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1015,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Nickname-inventor",desc:"Quickly assigns familiar nicknames to new acquaintances.",example:"(assigns a nickname within the first five minutes)",intensity:3,rarity:"common",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:1016,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Farewell-hoverer",desc:"Lingers physically before finally leaving a conversation.",example:"(lingers at the door, still talking, still not leaving)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1017,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Napkin-folder",desc:"Folds and refolds a napkin while talking.",example:"(folds the napkin, unfolds it, folds it again)",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1018,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Bracelet-spinner",desc:"Twists a bracelet around the wrist while thinking.",example:"(twists the bracelet around the wrist, considering)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1019,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Book-cover stroker",desc:"Runs fingers over a book cover absentmindedly.",example:"(runs fingers along the book's spine, thinking)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1020,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Lighter-flicker",desc:"Flicks a lighter open and shut without lighting it.",example:"(flicks the lighter open and shut, unlit)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1021,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Zipper-tugger",desc:"Tugs a jacket zipper up and down repeatedly.",example:"(tugs the zipper up, down, up again)",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1022,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Marble-roller",desc:"Rolls a small object between fingers while pondering.",example:"(rolls a small marble between two fingers)",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1023,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"String-unraveler",desc:"Picks at loose threads on clothing while talking.",example:"(picks at a thread on the sleeve, unraveling it slowly)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1024,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Coaster-flipper",desc:"Flips a coaster between fingers absentmindedly.",example:"(flips the coaster between two fingers)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1025,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Creaking-vocal fry",desc:"Lets voice crackle into fry at sentence ends.",example:"(voice cracks into a low creak at the end of the sentence)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1026,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Breathy-whisper swell",desc:"Voice grows breathier as emotion intensifies.",example:"(voice grows breathier as the feeling rises)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1027,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Clipped-pitch drop",desc:"Cuts pitch sharply down on final syllables.",example:"(pitch drops sharply on the final word) —done.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1028,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Wavering-uncertain tone",desc:"Voice trembles slightly when unsure of itself.",example:"(a slight tremor in the voice) I— I think that's right.",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1029,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Metallic-flat timbre",desc:"Speaks with a hard, unresonant vocal quality.",example:"(flat, unresonant) That is correct.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:1030,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Honeyed-persuasion tone",desc:"Softens voice into a smooth, coaxing register.",example:"(voice softens, coaxing) Now, wouldn't that be easier?",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1031,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Clipped-authority bark",desc:"Snaps commands in short, hard vocal bursts.",example:"MOVE. NOW. GO.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1032,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Sing-song taunt",desc:"Uses playful rising-falling pitch to mock or tease.",example:"Oh, you're in trouble now~",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1033,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Runaway-mouth",desc:"Keeps talking well past the point the listener has checked out.",example:"You still there? Good. Because I've got at least four more things to tell you.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:1034,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Info-dumper",desc:"Releases entire backstories in a single uninterrupted breath.",example:"So my mother was born in a village you've never heard of, and her mother before her—",intensity:4,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:1035,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Yakking",desc:"Chatters lightly about nothing in particular for long stretches.",example:"Nice weather. Not as nice as Sunday. Sunday was lovely. Did I mention Sunday?",intensity:2,rarity:"common",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:1036,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Overflowing-narrator",desc:"Cannot describe an event without narrating every side detail.",example:"He knocked. Twice. With his left hand. Wearing, I should mention, a truly terrible coat.",intensity:3,rarity:"signature",pol:{"vol":1,"pace":0,"form":0,"warm":0}},
{id:1037,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Wordbound",desc:"Feels compelled to fill any silence with more words.",example:"I could stop talking. I choose not to. There's a difference.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1038,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Clipped-yes-no",desc:"Answers almost everything with a bare yes or no.",example:"No.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1039,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"One-breath speaker",desc:"Delivers entire thoughts in a single short exhale.",example:"Gone. Now. Go.",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1040,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Word-rationer",desc:"Treats each spoken word as if it costs something.",example:"...Fine.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1041,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Silence-preferring",desc:"Chooses quiet over speech whenever plausible.",example:"(shrugs, returns to work)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1042,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Minimal-confirmer",desc:"Responds only with the smallest confirming sound.",example:"(a sound, not a word, and it means yes)",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1043,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Deadline-quickened",desc:"Speech visibly speeds up as time runs short.",example:"We've got — we've really got to go, now, right now—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:1044,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Confession-slowed",desc:"Words come haltingly when admitting a hard truth.",example:"I— I need to tell you— it's— give me a second—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:1045,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Crowd-hushed",desc:"Drops volume and pace sharply in large gatherings.",example:"(voice drops to almost nothing the moment the crowd gathers)",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1046,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Danger-alert clipped",desc:"Cuts sentences short the instant risk appears.",example:"Down. Now. Quiet.",intensity:4,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1047,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Post-crisis unwind",desc:"Speech loosens and lengthens once danger passes.",example:"(an hour later, finally exhales) ...Okay. Okay, I'm alright now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1048,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Court-poet phrasing",desc:"Wraps ordinary requests in poetic courtly language.",example:"Might I trouble you, gentle friend, for the merest crust of bread?",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:1049,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Scripture-cadenced",desc:"Speaks with the rhythm of recited sacred text.",example:"And it came to pass, in those days, that the bread ran short.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:1050,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Monument-worded",desc:"Treats every statement like it belongs on a plaque.",example:"Let it be recorded, in letters of brass, that the bread was, in fact, stale.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:1051,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Velvet-rhetoric",desc:"Smooths hard truths into lush, persuasive phrasing.",example:"Come now — surely there is a gentler way to say what must be said.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1052,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Antique-flourish",desc:"Adds old-fashioned flourishes to modern statements.",example:"Prithee, would you be so good as to pass the salt.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1053,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Weight-and-mass lexicon",desc:"Chooses words that emphasize heaviness and density.",example:"That kind of debt has real weight. You'll feel it in your shoulders for years.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1054,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Echo-focused",desc:"Frames ideas through reverberation and repeated sound.",example:"His name still echoes in this house. You can hear it in the empty rooms.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1055,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Surface-texture words",desc:"Describes ideas via roughness, smoothness, and grain.",example:"Smooth on the surface. Underneath, all grit and grain.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1056,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Depth-oriented",desc:"Chooses vocabulary suggesting layers, depth, and burial.",example:"There's a layer under that. And a layer under that layer.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1057,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Current-flow words",desc:"Frames ideas as currents, streams, and drifting motion.",example:"It's a current, not a decision. You get caught in it or you don't.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1058,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Ash-toned",desc:"Uses burnt-out, exhausted emotional vocabulary.",example:"There's nothing left to burn. Just the grey where the fire used to be.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:1059,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Spark-lit",desc:"Chooses vocabulary that flares with sudden excitement.",example:"Something in me lit up the second you said that.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1060,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Bruised-tender",desc:"Speaks with vocabulary that sounds carefully protected.",example:"Careful with that one. It's healed over, not healed through.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:1061,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Steel-guarded",desc:"Uses hardened, defensive emotional word choices.",example:"Ask again and you'll get the same wall you got the first time.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:1062,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Glow-warmed",desc:"Selects vocabulary radiating quiet contentment.",example:"Small good things, lately. I'll take small good things.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":1}},
{id:1068,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Blunt-parable",desc:"Delivers hard truths through short, unambiguous stories.",example:"There was a farmer who planted only weeds, and wondered why the harvest failed.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:1069,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Face-value speaker",desc:"Takes and gives words strictly at their surface meaning.",example:"You said 'maybe'. I heard 'maybe'. That's all I heard.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1070,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"No-metaphor policy",desc:"Refuses any figurative substitute for a literal term.",example:"Say what it is. Not what it's like. What it is.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1071,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Coded-plainness",desc:"Sounds direct while quietly hiding a second meaning.",example:"I'm fine. (This means, specifically, that they are not fine.)",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":-1,"warm":0}},
{id:1072,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Fact-first phrasing",desc:"Leads every statement with the plainest fact available.",example:"He's dead. That's the fact. Everything else is commentary.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:1073,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Verb-stacker",desc:"Chains multiple action verbs together in rapid succession.",example:"Grabbed, ran, jumped, made it.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":1,"form":0,"warm":0}},
{id:1074,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Suffix-inventor",desc:"Regularly attaches invented endings to ordinary words.",example:"He's got a bad case of the wobblies today.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1075,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Root-swapper",desc:"Replaces common roots with rarer synonymous ones.",example:"Not 'sad'. Bereft. There's a difference and I intend to use it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1076,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Contraction-forger",desc:"Builds unconventional contractions on the fly.",example:"I'd've thunk it, if I'd've thought about it at all.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1077,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Prefix-stripper",desc:"Removes standard prefixes to make words sound raw.",example:"Certain. Not un-certain. Just certain, plainly.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1078,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Popping-consonant",desc:"Favors words with sharp, popping consonant clusters.",example:"Pop. Pop. Pop. Every consonant with a little punch.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1079,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Drawled-vowel",desc:"Stretches vowels into a slow, syrupy drawl.",example:"Weeeell, I dunno 'bout thaaat.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:1080,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Clipped-syllable",desc:"Chops syllables short for a staccato auditory effect.",example:"Get. Up. Now. Clipped, clean, done.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":1,"form":0,"warm":0}},
{id:1081,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Breath-woven",desc:"Weaves audible breath sounds between spoken words.",example:"It's— (soft breath) —fine, really— (breath) —I'm managing.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1082,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Hollow-toned",desc:"Chooses words that sound faintly hollow when spoken.",example:"The word came out flat, like a knock on an empty box.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1083,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Threat-implying",desc:"Selects vocabulary that quietly implies consequences.",example:"That would be... unfortunate. For everyone involved.",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1084,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Consent-checking",desc:"Frequently uses words that verify agreement.",example:"That's alright with you? You're sure? Say if it's not.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1085,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Blame-deflecting",desc:"Chooses vocabulary that shifts responsibility elsewhere.",example:"That wasn't really my department, if we're being honest.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1086,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Credit-sharing",desc:"Uses vocabulary that spreads praise to the group.",example:"We did that. All of us. Together.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1087,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Time-marking",desc:"Anchors statements heavily in explicit time references.",example:"By Thursday. Not before. Not after. Thursday.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1088,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Margin-of-error speaker",desc:"Frames every claim with an explicit uncertainty range.",example:"Somewhere between four and six days, most likely five.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1089,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Category-splitter",desc:"Breaks single ideas into many named subtypes.",example:"Not a bird. A raptor. Specifically, a female sparrowhawk.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1090,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Exact-count user",desc:"Insists on precise counts instead of estimates.",example:"Not 'some'. Seven. Exactly seven.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1091,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Fuzzy-quantifier",desc:"Prefers 'a bunch' or 'a few' over exact numbers.",example:"A bunch. A fair few. Enough, anyway.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:1092,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Named-part speaker",desc:"Refers to the specific part rather than the whole.",example:"Not the whole engine. The valve. Specifically the valve.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1093,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Blunt-practical",desc:"Uses direct, unadorned, no-nonsense everyday speech.",example:"Fix it. Don't overthink it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:1094,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Elevated-cadenced",desc:"Speaks with the rising, rhythmic solemnity of a formal address.",example:"And so, let it be understood, from this day forward—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":1,"warm":0}},
{id:1095,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Locker-room casual",desc:"Uses blunt, joking, unfiltered peer-to-peer vocabulary.",example:"Yeah, that was rough. Walk it off.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:1096,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Studiously inoffensive",desc:"Chooses vocabulary designed to offend absolutely no one, ever.",example:"That's certainly one way of looking at it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1097,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Insider-familiar",desc:"Speaks as though always among trusted, in-the-know company.",example:"You know how it is. No need to spell it out.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1098,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Color-modifier heavy",desc:"Fills descriptions with frequent color references.",example:"A green door, a red roof, a grey sky over all of it.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1099,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Size-modifier heavy",desc:"Constantly specifies size before naming an object.",example:"A tiny cottage beside a massive, sprawling estate.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1100,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Temperature-modifier",desc:"Frequently describes things by warmth or coldness.",example:"A warm hearth against a bitter, freezing night.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1101,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Speed-modifier",desc:"Attaches a pace descriptor to nearly every verb.",example:"He sprinted past, she strolled after, they both eventually arrived.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1102,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Weight-modifier",desc:"Frequently notes how heavy or light something feels.",example:"The letter felt heavier than it should, somehow.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1103,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Reset-phrase user",desc:"Uses 'okay so' to restart derailed thoughts.",example:"Okay so — where were we — right, the shipment.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1104,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Loyalty-anchor",desc:"Repeats 'as I always say' before familiar opinions.",example:"As I always say — measure twice, cut once.",intensity:4,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1105,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Doubt-flagging tag",desc:"Adds 'or so they say' to unverified claims.",example:"He was there that night, or so they say.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1106,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Time-check filler",desc:"Inserts 'real quick' before brief interjections.",example:"Real quick — did you lock the gate?",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":1,"form":0,"warm":0}},
{id:1107,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Group-inclusion tag",desc:"Adds 'we all know' to assert shared belief.",example:"We all know how this ends, don't we.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1108,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Name-forgetting stall",desc:"Pauses mid-sentence, unable to recall a name.",example:"It was— what was his name— it's right there, I just—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1109,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Double-take stutter",desc:"Repeats a word after realizing a mistake.",example:"He said— he said— he said it wasn't— sorry, wasn't true.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1110,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sudden-brake pause",desc:"Stops speech abruptly as if hitting a wall.",example:"—and then— (stops dead) ...never mind.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1111,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Overlapping-thought jumble",desc:"Two ideas blur together mid-sentence.",example:"Ithoughtyoumeant—wait,didyoumean—I'mconfused—",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1112,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Slow-restart speaker",desc:"Restarts sentences noticeably slower than the first attempt.",example:"I— was— going— to— say—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:1113,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Status-clipper",desc:"Reduces updates to a single clipped status word.",example:"Fine.",intensity:3,rarity:"common",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1114,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Yes-stacker",desc:"Answers with repeated short affirmatives instead of sentences.",example:"Yes. Yes. Yes.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1115,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Verb-only replier",desc:"Answers questions using only a bare verb.",example:"Go.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1116,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Count-clipper",desc:"Drops units, stating bare numbers only.",example:"Nine. Not nine crates. Nine.",intensity:2,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":-1}},
{id:1117,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Silent-nod-substitute",desc:"Replaces spoken agreement with an implied gesture cue.",example:"(a single nod, nothing said)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1118,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Correction-inserting speaker",desc:"Interrupts self to insert a small correcting clause.",example:"He said — sorry, he implied — that it was finished.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1119,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Rewind-restart",desc:"Restarts a sentence from an earlier clause to fix wording.",example:"We're going— actually, we already went, sorry, we went yesterday.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1120,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Escalating-clause stacker",desc:"Piles clauses that grow more intense as the sentence continues.",example:"He was late. He was late and rude. He was late, rude, and dismissive.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1121,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Question-embedding speaker",desc:"Buries a real question inside an unrelated statement.",example:"I wonder — and I'm only asking — whether you actually locked the gate.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1122,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Time-jump narrator",desc:"Shifts sentence tense abruptly to skip ahead in a story.",example:"He left that morning. Ten years later, he returned.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1123,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Polite-interrupt asker",desc:"Interrupts only after asking permission first.",example:"May I say something? ...Thank you. I think—",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1124,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-count tracker",desc:"Visibly tracks whose turn it is to speak next.",example:"That's your third interruption. My turn now.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1125,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Silence-filler volunteer",desc:"Jumps in the instant any pause appears.",example:"(fills the silence within a beat, every time)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1126,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Delayed-response speaker",desc:"Waits several beats before responding to any turn.",example:"...(three full seconds pass)... I suppose so.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1127,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Group-facilitator grammar",desc:"Structures turns to explicitly invite quieter speakers.",example:"You haven't said much — what do you think?",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1128,section:"Mannerisms",category:"Emotional Affectations",trait:"Quiet-triumph nod",desc:"Nods once, barely, after winning a point.",example:"(a single, small nod) Mm.",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1129,section:"Mannerisms",category:"Emotional Affectations",trait:"Shaky-composure mask",desc:"Holds a steady face while hands betray nervousness.",example:"(voice steady, hands trembling slightly out of sight)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1130,section:"Mannerisms",category:"Emotional Affectations",trait:"Delighted-clap burst",desc:"Claps hands together briefly at good news.",example:"(a single, sharp clap) Yes! There it is!",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":1}},
{id:1131,section:"Mannerisms",category:"Emotional Affectations",trait:"Suppressed-eye-roll",desc:"Rolls eyes only slightly before catching themselves.",example:"(eyes roll half an inch, then catch themselves)",intensity:1,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1132,section:"Mannerisms",category:"Emotional Affectations",trait:"Grateful-hand-to-chest",desc:"Presses a hand to the chest when genuinely moved.",example:"(hand to chest) That means more than you know.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:1133,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Thermostat-obsessor",desc:"Repeatedly checks or adjusts the room's temperature controls.",example:"(checks the thermostat again, third time this hour)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1134,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Doorknob-checker",desc:"Tests that a door is locked more than once.",example:"(tries the lock a second time, just to be sure)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1135,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Shelf-duster",desc:"Wipes dust off nearby surfaces mid-conversation.",example:"(wipes a shelf clean with two fingers, absently)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1136,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Chair-realigner",desc:"Nudges furniture back into exact position before sitting.",example:"(nudges the chair a precise inch before sitting)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1137,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Exit-scanner",desc:"Locates the nearest exit upon entering any room.",example:"(clocks the exits the moment they walk in)",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1138,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Micro-frown flicker",desc:"Shows a brief frown before catching and smoothing it.",example:"(a flicker of a frown, smoothed over instantly)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1139,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Upward-glance recall",desc:"Looks upward briefly when retrieving a memory.",example:"(glances up, searching) It was... a Tuesday, I think.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1140,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Tight-smile mask",desc:"Holds a controlled smile that doesn't reach the eyes.",example:"(a smile, held, that doesn't reach the eyes)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1141,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Startled-brow-raise",desc:"Raises both brows sharply at unexpected statements.",example:"(brows shoot up) Wait — really?",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1142,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Slow-nod agreement",desc:"Nods slowly and deliberately to signal careful agreement.",example:"(nods slowly, taking it in) I see.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:1143,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Open-palm honesty",desc:"Shows open palms when insisting on their own sincerity.",example:"(palms open) I'm telling you the truth.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1144,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Invisible-line drawer",desc:"Traces an invisible boundary line in the air.",example:"(traces a line in the air) This far. No further.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1145,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Double-tap emphasis",desc:"Taps a surface twice to underline a key word.",example:"(taps the table twice) That. Right there.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1146,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Slow-reach gesture",desc:"Reaches for objects with exaggerated, deliberate slowness.",example:"(reaches for the cup with exaggerated slowness)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:1147,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Circular-wrist flourish",desc:"Rotates the wrist in a small flourish before key statements.",example:"(a small flourish of the wrist) And there we are.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1148,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Jaw-set tension",desc:"Sets the jaw firmly when holding back a response.",example:"(jaw sets, firm, says nothing)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1149,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Finger-drum stop",desc:"Suddenly stops fidgeting fingers when caught being observed.",example:"(fingers stop drumming the instant they're noticed)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1150,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Shoulder-roll release",desc:"Rolls shoulders once to release built-up tension.",example:"(rolls the shoulders once, releasing tension)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1151,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Cheek-bite pause",desc:"Bites inner cheek briefly while suppressing a reaction.",example:"(bites the inside of the cheek, says nothing)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1152,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Toe-tap countdown",desc:"Taps toes rhythmically as if counting down internally.",example:"(taps toes in a silent countdown)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1153,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Soft-grunt agreement",desc:"Grunts quietly instead of using a verbal yes.",example:"(a soft grunt instead of a yes)",intensity:1,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1154,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sharp-inhale surprise",desc:"Draws in a sudden sharp breath at shocking news.",example:"(a sharp inhale) You're joking.",intensity:4,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1155,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Low-whistle appraisal",desc:"Lets out a low whistle when impressed.",example:"(a low whistle) Well, look at that.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1156,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Quiet-hum thinking",desc:"Hums almost silently while turning over a decision.",example:"(hums almost silently, turning it over)",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1157,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Chuckle-swallow",desc:"Suppresses a laugh into a small closed-mouth sound.",example:"(swallows a laugh, closed-mouth, eyes bright)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1158,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Anchor-footed stance",desc:"Plants feet firmly and rarely shifts weight while speaking.",example:"(feet planted, doesn't shift once through the whole exchange)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1159,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Half-turned body",desc:"Angles the body away while still maintaining eye contact.",example:"(angles the body away, keeps eye contact)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1160,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Shoulder-square confrontation",desc:"Squares shoulders fully when disagreement arises.",example:"(shoulders square instantly at the first sign of disagreement)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1161,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Low-crouch approach",desc:"Lowers body height when approaching a nervous listener.",example:"(lowers to eye level before speaking)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1162,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Slow-circle assessor",desc:"Walks a slow circle around a subject before speaking.",example:"(circles slowly before finally speaking)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":0}},
{id:1163,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Permission-asking toucher",desc:"Always asks before any physical contact.",example:"(asks first) May I? — before any contact at all.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1164,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-scanning includer",desc:"Makes eye contact with every person before continuing.",example:"(makes eye contact with each person before continuing)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1165,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Late-arrival apologizer",desc:"Over-apologizes physically for even minor lateness.",example:"(over-apologizes, physically, for being three minutes late)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1166,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Space-claiming sprawler",desc:"Casually claims more physical space than needed.",example:"(spreads out, claiming more space than needed)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":-1,"warm":0}},
{id:1167,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Quiet-exit signaler",desc:"Signals departure with small gestures before actually leaving.",example:"(gathers their things, a clear signal, before actually leaving)",intensity:2,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1168,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Pocket-worry-stone",desc:"Rubs a small stone or token kept in a pocket.",example:"(rubs the stone in a pocket, unseen)",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1169,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Notebook-clutcher",desc:"Holds a notebook close to the chest while talking.",example:"(clutches the notebook close to the chest)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1170,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Sleeve-cuff fiddler",desc:"Toys with a loose thread on a cuff repeatedly.",example:"(picks at a loose thread on the cuff)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1171,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Glass-rim circler",desc:"Runs a finger around the rim of a glass while thinking.",example:"(traces the rim of the glass, slowly)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1172,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Badge-toucher",desc:"Touches a pin or badge when asserting authority.",example:"(touches the pin at the collar) I speak for the office.",intensity:3,rarity:"common",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1173,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Warm-timbre opener",desc:"Starts sentences with a noticeably warmer, softer tone.",example:"(opens warm, softer than expected) Hey. It's good to see you.",intensity:2,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":1}},
{id:1174,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Clipped-vowel precision",desc:"Shortens vowel sounds for a crisp, controlled tone.",example:"(clipped, precise vowels) Understood. Proceeding.",intensity:3,rarity:"signature",pol:{"vol":-1,"pace":0,"form":0,"warm":0}},
{id:1175,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Rising-tension pitch",desc:"Lets pitch climb steadily as an argument builds.",example:"(pitch climbs, steadily, as the argument builds)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1176,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Flattened-crisis calm",desc:"Deliberately flattens tone during high-stress moments.",example:"(tone stays deliberately flat through the worst of it)",intensity:3,rarity:"signature",pol:{"vol":0,"pace":-1,"form":0,"warm":-1}},
{id:1177,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Confidential-hush drop",desc:"Drops volume suddenly to signal a private aside.",example:"(volume drops suddenly) Between us — don't repeat this.",intensity:3,rarity:"signature",pol:{"vol":0,"pace":0,"form":0,"warm":0}},
{id:1178,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warm-hearted",desc:"Genuinely enjoys connecting with new people and puts them at ease.",example:"Come in, come in — you must be freezing. Sit by the fire.",intensity:3,rarity:"common",pol:{"warm":1}},
{id:1179,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Welcoming",desc:"Makes strangers feel immediately included in the group.",example:"You don't know anyone here? Perfect. Come meet everyone.",intensity:3,rarity:"common",pol:{"warm":1}},
{id:1180,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Affectionate",desc:"Freely expresses fondness through words and small gestures.",example:"Oh, I've missed you. Don't you dare leave that quickly again.",intensity:4,rarity:"common",pol:{"warm":1}},
{id:1181,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Easy-going company",desc:"Simple to get along with in almost any social setting.",example:"Whatever you want to do is fine by me. I'm just glad you're here.",intensity:2,rarity:"common",pol:{"warm":1}},
{id:1182,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Hospitable",desc:"Instinctively offers comfort, food, or shelter to guests.",example:"There's stew on the stove and a bed made up. Stay as long as you need.",intensity:3,rarity:"common",pol:{"warm":1}},
{id:1183,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Chummy",desc:"Treats new acquaintances like old friends within minutes.",example:"Mate! There you are. Listen, you and me, we're going to get on famously.",intensity:4,rarity:"signature",pol:{"warm":1,"vol":1}},
{id:1184,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Sociable",desc:"Actively seeks out company rather than solitude.",example:"There's a crowd at the tavern tonight. Come on, don't sit here alone.",intensity:3,rarity:"common",pol:{"warm":1,"vol":1}},
{id:1185,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Gregarious",desc:"Draws energy from being around groups of people.",example:"The more the merrier — pull up another chair, we'll make room.",intensity:4,rarity:"signature",pol:{"warm":1,"vol":1}},
{id:1186,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Aloof",desc:"Keeps emotional distance even from close acquaintances.",example:"Mm. If you say so.",intensity:3,rarity:"common",pol:{"warm":-1,"vol":-1}},
{id:1187,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Standoffish",desc:"Discourages casual approach with closed body language.",example:"I'd rather not, thank you.",intensity:3,rarity:"common",pol:{"warm":-1}},
{id:1188,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Frosty",desc:"Greets strangers with clipped, unwelcoming politeness.",example:"Good evening. Was there something you needed?",intensity:4,rarity:"common",pol:{"warm":-1}},
{id:1189,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Withdrawn",desc:"Prefers solitude to any group social setting.",example:"I'll be in my room.",intensity:4,rarity:"common",pol:{"warm":-1,"vol":-1}},
{id:1190,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Unapproachable",desc:"Radiates a subtle 'do not disturb' presence.",example:"(says nothing; the conversation dies where it started)",intensity:4,rarity:"signature",pol:{"warm":-1,"vol":-1}},
{id:1191,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Detached-friendly",desc:"Maintains a surface pleasantness with no real warmth.",example:"Lovely to see you. Truly. Now, about the shipment—",intensity:3,rarity:"signature",pol:{"warm":-1}},
{id:1192,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Guarded-social",desc:"Keeps new people firmly at arm's length.",example:"We've only just met. Let's not pretend otherwise.",intensity:3,rarity:"signature",pol:{"warm":-1,"vol":-1}},
{id:1193,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Indifferent to others",desc:"Shows little curiosity about people they meet.",example:"I didn't catch your name. It doesn't much matter.",intensity:4,rarity:"signature",pol:{"warm":-1}},
{id:1194,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Blunt-honest",desc:"States uncomfortable truths without softening them.",example:"It's badly done. You knew that before you asked me.",intensity:4,rarity:"common",pol:{"hon":1,"form":-1}},
{id:1195,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Transparent",desc:"Volunteers relevant information without being asked.",example:"Before you decide — you should know I stand to gain from this.",intensity:3,rarity:"common",pol:{"hon":1}},
{id:1196,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Principled truth-teller",desc:"Refuses to lie even when it would be easier.",example:"I won't say it. Not even to spare you. I'm sorry.",intensity:4,rarity:"signature",pol:{"hon":1}},
{id:1197,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Confessional",desc:"Openly admits own mistakes and shortcomings.",example:"That was my error. Nobody else's. I should have checked.",intensity:3,rarity:"signature",pol:{"hon":1}},
{id:1198,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Plainly sincere",desc:"Says exactly what they mean, no hidden agenda.",example:"I mean it exactly as I said it. There's nothing underneath.",intensity:2,rarity:"common",pol:{"hon":1}},
{id:1199,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Reliable witness",desc:"Gives consistent, accurate accounts of events.",example:"Three men. Grey coats. Half past ten. I'd swear to it.",intensity:2,rarity:"signature",pol:{"hon":1}},
{id:1200,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Trust-building",desc:"Volunteers proof or evidence to support their claims.",example:"Don't take my word — here's the ledger. Check it yourself.",intensity:3,rarity:"signature",pol:{"hon":1}},
{id:1201,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Uncompromisingly frank",desc:"Values truth over the listener's comfort.",example:"You want comfort or you want the truth? I only have the one.",intensity:5,rarity:"signature",pol:{"hon":1,"form":-1}},
{id:1202,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Habitual liar",desc:"Lies reflexively even when the truth would serve better.",example:"Me? I was nowhere near it. Ask anyone.",intensity:4,rarity:"common",pol:{"hon":-1}},
{id:1203,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Evasive",desc:"Dodges direct questions with vague non-answers.",example:"That's an interesting question. Where did you hear that, exactly?",intensity:3,rarity:"common",pol:{"hon":-1,"vol":-1}},
{id:1204,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Manipulative truth-bender",desc:"Shapes facts to serve their own agenda.",example:"I never said it was safe. I said nobody had died yet.",intensity:4,rarity:"signature",pol:{"hon":-1}},
{id:1205,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Two-faced",desc:"Says different things to different people about the same event.",example:"Of course I'm on your side. (Later:) Well, someone had to say it.",intensity:4,rarity:"common",pol:{"hon":-1}},
{id:1206,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Cagey",desc:"Withholds information as a default posture.",example:"Let's just say I've been around. Leave it there.",intensity:3,rarity:"common",pol:{"hon":-1,"vol":-1}},
{id:1207,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Smooth deceiver",desc:"Lies convincingly without visible tells.",example:"On my mother's grave. (Doesn't blink.)",intensity:4,rarity:"signature",pol:{"hon":-1}},
{id:1208,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Half-truth teller",desc:"Mixes accurate details with key omissions.",example:"I did go to the meeting. I simply didn't mention who else was there.",intensity:3,rarity:"signature",pol:{"hon":-1}},
{id:1209,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Gaslighting tendency",desc:"Denies or reframes events to confuse others.",example:"You're remembering it wrong. That's not what happened at all.",intensity:5,rarity:"signature",pol:{"hon":-1}},
{id:1210,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Commanding",desc:"Takes charge of situations without waiting for permission.",example:"You two, the door. You, with me. Now.",intensity:4,rarity:"common",pol:{"asrt":1}},
{id:1211,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Decisive",desc:"Makes quick calls and states them with certainty.",example:"We go north. That's settled — next.",intensity:3,rarity:"common",pol:{"asrt":1}},
{id:1212,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Boundary-setter",desc:"States limits clearly and enforces them.",example:"No. I've told you before, and the answer hasn't changed.",intensity:3,rarity:"signature",pol:{"asrt":1}},
{id:1213,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Direct-requester",desc:"Asks for what they want plainly, no hinting.",example:"I need the money by Friday. Can you do it or not?",intensity:3,rarity:"common",pol:{"asrt":1}},
{id:1214,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Confrontation-ready",desc:"Doesn't shy away from necessary conflict.",example:"Say that again. Slowly. To my face.",intensity:4,rarity:"common",pol:{"asrt":1,"warm":-1}},
{id:1215,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Opinion-forward",desc:"States their views before being asked.",example:"Nobody asked, but it's a bad plan and here's why.",intensity:3,rarity:"common",pol:{"asrt":1,"vol":1}},
{id:1216,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Firm negotiator",desc:"Holds their position under pressure.",example:"That's my number. I'm not moving off it.",intensity:3,rarity:"signature",pol:{"asrt":1}},
{id:1217,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Front-footed",desc:"Initiates rather than waits to be prompted.",example:"I've already started. You can catch up or stay behind.",intensity:3,rarity:"signature",pol:{"asrt":1,"pace":1}},
{id:1218,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Conflict-avoidant",desc:"Backs down rather than push an issue.",example:"It's fine. Honestly, let's just drop it.",intensity:3,rarity:"common",pol:{"asrt":-1,"vol":-1}},
{id:1219,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Deferential",desc:"Automatically defers to others' preferences.",example:"Whatever you think is best.",intensity:3,rarity:"common",pol:{"asrt":-1}},
{id:1220,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Hesitant-requester",desc:"Struggles to ask directly for what they need.",example:"I don't suppose — no, never mind, it's not important.",intensity:3,rarity:"common",pol:{"asrt":-1,"pace":-1}},
{id:1221,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Pushover",desc:"Gives in quickly under social pressure.",example:"Well... if you really think so. All right.",intensity:4,rarity:"common",pol:{"asrt":-1}},
{id:1222,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Self-effacing",desc:"Downplays their own needs in favor of others'.",example:"Don't worry about me, I'll manage. See to yourself first.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1223,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Wait-and-see",desc:"Rarely acts first, prefers to follow others' lead.",example:"Let's see what the others do first.",intensity:2,rarity:"signature",pol:{"asrt":-1}},
{id:1224,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Placating",desc:"Smooths over tension even at their own expense.",example:"You're both right, really. Shall we sit down?",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1225,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Silent dissenter",desc:"Disagrees internally but rarely voices it.",example:"(nods along, says nothing, disagrees entirely)",intensity:3,rarity:"signature",pol:{"asrt":-1,"vol":-1}},
{id:1226,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-assured",desc:"Trusts their own judgment without needing validation.",example:"I've thought it through. I'm right about this one.",intensity:3,rarity:"common",pol:{"ego":1}},
{id:1227,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Grounded confidence",desc:"Comfortable in their skin without showing off.",example:"I can do it. No need to make a thing of it.",intensity:2,rarity:"signature",pol:{"ego":1}},
{id:1228,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Poised",desc:"Remains composed and certain under scrutiny.",example:"Take your time with the accusation. I'll wait.",intensity:3,rarity:"common",pol:{"ego":1}},
{id:1229,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Secure",desc:"Unbothered by criticism that isn't constructive.",example:"You can think that if you like. Doesn't change much.",intensity:3,rarity:"signature",pol:{"ego":1}},
{id:1230,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Commanding presence",desc:"Naturally draws attention when entering a room.",example:"(enters; the room quiets without being asked)",intensity:4,rarity:"signature",pol:{"ego":1}},
{id:1231,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-possessed",desc:"Doesn't need external approval to feel capable.",example:"I don't need you to agree. I only need you to move.",intensity:3,rarity:"signature",pol:{"ego":1}},
{id:1232,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Bold decision-maker",desc:"Acts on their convictions without excessive doubt.",example:"Then we do it the dangerous way. Fetch the rope.",intensity:4,rarity:"common",pol:{"ego":1}},
{id:1233,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Steady self-image",desc:"Maintains consistent self-regard across situations.",example:"Same as I was yesterday. Same as I'll be tomorrow.",intensity:2,rarity:"signature",pol:{"ego":1}},
{id:1234,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Self-doubting",desc:"Second-guesses their own decisions constantly.",example:"Was that — should I have said that? I shouldn't have said that.",intensity:3,rarity:"common",pol:{"ego":-1}},
{id:1235,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Approval-seeking",desc:"Needs frequent validation to feel at ease.",example:"That was all right, wasn't it? You'd tell me if it wasn't?",intensity:3,rarity:"common",pol:{"ego":-1}},
{id:1236,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Overcompensating",desc:"Masks insecurity with exaggerated bravado.",example:"Scared? Me? I've done this a hundred times. Two hundred.",intensity:4,rarity:"signature",pol:{"ego":-1}},
{id:1237,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Fragile ego",desc:"Reacts defensively to minor criticism.",example:"Fine. FINE. If you think you'd do it better, be my guest.",intensity:4,rarity:"common",pol:{"ego":-1}},
{id:1238,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Self-deprecating",desc:"Habitually undercuts their own worth aloud.",example:"Well, I've ruined it. As usual. As is tradition.",intensity:3,rarity:"common",pol:{"ego":-1}},
{id:1239,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Grandiose",desc:"Believes themselves superior to most people around them.",example:"There isn't a man in this city who could do what I've done.",intensity:5,rarity:"signature",pol:{"ego":-1,"form":1}},
{id:1240,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Attention-hungry",desc:"Steers conversations back to themselves often.",example:"That reminds me of when I— sorry, sorry, go on. Actually, no, listen—",intensity:4,rarity:"common",pol:{"ego":-1,"vol":1}},
{id:1241,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Vain",desc:"Preoccupied with how they're perceived by others.",example:"Do I look tired? Be honest. God, I look tired.",intensity:4,rarity:"common",pol:{"ego":-1}},
{id:1242,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Accommodating",desc:"Adjusts own preferences readily to keep peace.",example:"Works for me. I can shift things around.",intensity:3,rarity:"common",pol:{"agr":1}},
{id:1243,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Cooperative",desc:"Works smoothly within group consensus.",example:"Tell me what you need and I'll handle my half.",intensity:2,rarity:"common",pol:{"agr":1}},
{id:1244,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Easy to please",desc:"Rarely voices strong objections to plans.",example:"Either's fine. Genuinely.",intensity:2,rarity:"common",pol:{"agr":1}},
{id:1245,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Compromise-seeking",desc:"Looks for middle ground in disagreements.",example:"What if we split the difference? Half now, half after.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1246,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Team-first",desc:"Prioritizes group harmony over personal preference.",example:"Doesn't matter what I'd prefer. What does the group need?",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1247,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Gentle disagreer",desc:"Voices dissent softly and rarely presses it.",example:"I wonder — and I could be wrong — whether that's quite right.",intensity:2,rarity:"signature",pol:{"agr":1}},
{id:1248,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Consensus-builder",desc:"Actively works to align differing opinions.",example:"So we all agree on the first part. Let's start from there.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1249,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Non-confrontational cooperator",desc:"Avoids friction by yielding early.",example:"You're probably right. Let's do it your way.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1250,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Contrarian",desc:"Instinctively pushes back against the prevailing view.",example:"Everyone thinks that. That's precisely why it's wrong.",intensity:4,rarity:"common",pol:{"agr":-1}},
{id:1251,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Argumentative",desc:"Turns casual disagreements into prolonged debate.",example:"No, hold on, go back — you said 'obviously' and it isn't obvious at all.",intensity:4,rarity:"common",pol:{"agr":-1,"vol":1}},
{id:1252,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Stubborn opinion-holder",desc:"Rarely updates a position once stated.",example:"I said what I said. New facts don't change it.",intensity:4,rarity:"signature",pol:{"agr":-1}},
{id:1253,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Combative",desc:"Treats disagreement as a contest to win.",example:"Try me. Go on.",intensity:4,rarity:"common",pol:{"agr":-1,"warm":-1}},
{id:1254,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Devil's-advocate",desc:"Argues the opposite side just to test it.",example:"Let me take the other side for a moment, just to see if it holds.",intensity:3,rarity:"signature",pol:{"agr":-1}},
{id:1255,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Prickly",desc:"Reacts sharply to being challenged or corrected.",example:"I don't need correcting, thank you.",intensity:4,rarity:"common",pol:{"agr":-1,"warm":-1}},
{id:1256,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Uncompromising",desc:"Refuses middle ground once a stance is taken.",example:"There's no middle here. It's this or nothing.",intensity:4,rarity:"signature",pol:{"agr":-1}},
{id:1257,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Skeptical by default",desc:"Doubts claims until independently convinced.",example:"Says who? And how would they know?",intensity:3,rarity:"common",pol:{"agr":-1}},
{id:1258,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Well-mannered",desc:"Follows social etiquette instinctively and consistently.",example:"After you. Please.",intensity:3,rarity:"common",pol:{"man":1,"form":1}},
{id:1259,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Considerate",desc:"Notices and adjusts for others' comfort.",example:"You've been standing an hour — take the chair, I'm fine.",intensity:3,rarity:"common",pol:{"man":1}},
{id:1260,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Gracious",desc:"Accepts both praise and criticism with composure.",example:"That's kind of you to say. And the criticism's fair, too.",intensity:3,rarity:"signature",pol:{"man":1}},
{id:1261,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Courtly-polite",desc:"Uses formal courtesies even in casual settings.",example:"If it should please you, madam, I would be honoured to escort you.",intensity:4,rarity:"signature",pol:{"man":1,"form":1}},
{id:1262,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Table-mannered",desc:"Meticulous about dining and social etiquette.",example:"(waits, napkin in lap, until every guest is served)",intensity:3,rarity:"signature",pol:{"man":1,"form":1}},
{id:1263,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Deferential to elders",desc:"Shows visible respect toward authority and age.",example:"Sir — forgive me — might I offer a thought?",intensity:3,rarity:"signature",pol:{"man":1,"form":1}},
{id:1264,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Soft-spoken courtesy",desc:"Keeps tone gentle even when correcting others.",example:"I do wonder if there's been a small misunderstanding.",intensity:3,rarity:"signature",pol:{"man":1,"form":1,"vol":-1}},
{id:1265,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Thoughtful host",desc:"Anticipates guests' needs before being asked.",example:"I remembered you don't take sugar. Here.",intensity:3,rarity:"signature",pol:{"man":1}},
{id:1266,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Uncouth",desc:"Ignores basic social etiquette without noticing.",example:"(talks with mouth full) S'good. You want some?",intensity:4,rarity:"common",pol:{"man":-1,"form":-1}},
{id:1267,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Blunt to a fault",desc:"Says rude things without recognizing the offense.",example:"You've gotten fat. Anyway — the horses.",intensity:4,rarity:"common",pol:{"man":-1,"form":-1}},
{id:1268,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Interruptive-rude",desc:"Talks over others without apology.",example:"—no, wrong, next point—",intensity:4,rarity:"common",pol:{"man":-1,"vol":1}},
{id:1269,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Sloppy-mannered",desc:"Neglects table manners and social niceties.",example:"(wipes hands on shirt, reaches across the table)",intensity:3,rarity:"common",pol:{"man":-1,"form":-1}},
{id:1270,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Dismissive of etiquette",desc:"Treats formality as pointless performance.",example:"All that bowing and scraping. Just say what you want.",intensity:3,rarity:"signature",pol:{"man":-1,"form":-1}},
{id:1271,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Coarse jester",desc:"Makes crude jokes regardless of company.",example:"Now that's a joke I shouldn't tell in present company. Right, so—",intensity:4,rarity:"common",pol:{"man":-1,"form":-1}},
{id:1272,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Inconsiderate",desc:"Rarely factors others' comfort into their actions.",example:"(takes the last one without looking up)",intensity:3,rarity:"common",pol:{"man":-1}},
{id:1273,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Brusque host",desc:"Offers hospitality without warmth or care.",example:"Food's there. Bed's upstairs. Don't wake me.",intensity:3,rarity:"signature",pol:{"man":-1}},
{id:1274,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Highly disciplined",desc:"Sticks to routines and commitments without fail.",example:"Same time tomorrow. Same as every day.",intensity:4,rarity:"common",pol:{"disc":1}},
{id:1275,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Self-controlled",desc:"Resists impulses in favor of long-term goals.",example:"I want to. I won't.",intensity:3,rarity:"common",pol:{"disc":1}},
{id:1276,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Methodical planner",desc:"Approaches tasks with structured, deliberate steps.",example:"Step one, we confirm the route. Step two—",intensity:3,rarity:"common",pol:{"disc":1,"pace":-1}},
{id:1277,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Delayed-gratification",desc:"Comfortable sacrificing short-term reward for later gain.",example:"Not yet. It's worth more in a year.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1278,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Habit-driven",desc:"Relies on consistent daily rituals to stay on track.",example:"Can't. That's my hour. It's always been my hour.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1279,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Focused under distraction",desc:"Maintains task focus despite interruptions.",example:"(doesn't look up as the argument rages behind them)",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1280,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Punctual",desc:"Treats time commitments as firm obligations.",example:"You said six. It's six.",intensity:2,rarity:"common",pol:{"disc":1}},
{id:1281,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Rule-abiding",desc:"Follows agreed structures even when unsupervised.",example:"There's a procedure. We'll follow it.",intensity:3,rarity:"common",pol:{"disc":1}},
{id:1282,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Impulsive",desc:"Acts on immediate desire without weighing consequences.",example:"Sod it. We're going now.",intensity:4,rarity:"common",pol:{"disc":-1,"pace":1}},
{id:1283,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Easily distracted",desc:"Struggles to maintain focus on a single task.",example:"Right, yes, focus — sorry, what's that noise?",intensity:3,rarity:"common",pol:{"disc":-1,"pace":1}},
{id:1284,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Procrastinating",desc:"Delays necessary tasks until the last possible moment.",example:"I'll do it tomorrow. Tomorrow's better for it anyway.",intensity:3,rarity:"common",pol:{"disc":-1}},
{id:1285,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Undisciplined routine",desc:"Abandons plans and schedules frequently.",example:"I had a system. For about a week.",intensity:3,rarity:"signature",pol:{"disc":-1}},
{id:1286,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Instant-gratification seeker",desc:"Prioritizes immediate reward over long-term benefit.",example:"I'll worry about that later. Right now I want this.",intensity:4,rarity:"signature",pol:{"disc":-1}},
{id:1287,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Erratic follow-through",desc:"Starts projects with enthusiasm, rarely finishes them.",example:"I started three of these. Somewhere.",intensity:3,rarity:"signature",pol:{"disc":-1}},
{id:1288,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Rule-bending",desc:"Treats structure as optional when inconvenient.",example:"Nobody's watching. Who's it hurting?",intensity:3,rarity:"common",pol:{"disc":-1}},
{id:1289,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Chronically late",desc:"Struggles to honor time commitments.",example:"Sorry — sorry — the thing took longer than— sorry.",intensity:3,rarity:"common",pol:{"disc":-1}},
{id:1290,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Defiant",desc:"Resists authority on principle, even when compliance is easier.",example:"No. And you can't make it anything else.",intensity:4,rarity:"common",pol:{"rebel":1}},
{id:1291,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Rule-breaker",desc:"Treats regulations as suggestions to be tested.",example:"There's a sign. I read it. Come on.",intensity:4,rarity:"common",pol:{"rebel":1}},
{id:1292,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Anti-establishment",desc:"Distrusts institutions and formal hierarchies.",example:"They wrote the rules to protect themselves. Why would I follow them?",intensity:4,rarity:"signature",pol:{"rebel":1,"form":-1}},
{id:1293,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Provocateur",desc:"Deliberately challenges accepted norms for effect.",example:"Someone had to say it out loud. Might as well be me.",intensity:4,rarity:"signature",pol:{"rebel":1}},
{id:1294,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Independent-minded",desc:"Rejects groupthink in favor of personal conviction.",example:"I don't care what the room thinks. I've looked at it myself.",intensity:3,rarity:"signature",pol:{"rebel":1}},
{id:1295,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Boundary-tester",desc:"Pushes limits to see what's actually enforced.",example:"And what happens if I do? Genuinely — what actually happens?",intensity:3,rarity:"signature",pol:{"rebel":1}},
{id:1296,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Non-conformist",desc:"Dresses, speaks, or acts against social convention deliberately.",example:"Everyone dresses like that. That's rather the point.",intensity:3,rarity:"common",pol:{"rebel":1,"form":-1}},
{id:1297,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Authority-skeptical",desc:"Questions instructions before following them.",example:"Says who? On whose orders? Show me.",intensity:3,rarity:"common",pol:{"rebel":1}},
{id:1298,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Rule-respecting",desc:"Follows established procedures without question.",example:"It's the procedure. We do it properly or not at all.",intensity:3,rarity:"common",pol:{"rebel":-1}},
{id:1299,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Order-loving",desc:"Finds comfort in structure and hierarchy.",example:"There's a way things are done, and there's chaos. I know which I prefer.",intensity:3,rarity:"signature",pol:{"rebel":-1,"form":1}},
{id:1300,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Tradition-honoring",desc:"Values doing things the way they've always been done.",example:"My father did it this way. His father before him.",intensity:3,rarity:"signature",pol:{"rebel":-1,"form":1}},
{id:1301,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Deferential to authority",desc:"Automatically defers to those in charge.",example:"If those are the orders, those are the orders.",intensity:3,rarity:"common",pol:{"rebel":-1}},
{id:1302,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Conformist",desc:"Adjusts behavior to match group or social expectation.",example:"Everyone else is doing it that way. Why would we be different?",intensity:3,rarity:"common",pol:{"rebel":-1}},
{id:1303,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Compliance-first",desc:"Prioritizes following rules over personal preference.",example:"I don't have to like it. I have to follow it.",intensity:3,rarity:"signature",pol:{"rebel":-1}},
{id:1304,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Institution-trusting",desc:"Believes established systems generally work as intended.",example:"They wouldn't have made the rule without good reason.",intensity:3,rarity:"signature",pol:{"rebel":-1}},
{id:1305,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Cautious conformer",desc:"Avoids standing out or challenging the status quo.",example:"Let's not draw attention. Just do it the normal way.",intensity:3,rarity:"signature",pol:{"rebel":-1,"vol":-1}},
{id:1306,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Deeply feeling",desc:"Experiences emotions with notable intensity.",example:"I can't just — it sits in my chest. It's been sitting there for weeks.",intensity:4,rarity:"common",pol:{"emo":1}},
{id:1307,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Empathetic",desc:"Readily senses and absorbs others' emotional states.",example:"You don't have to explain. I can see it on you.",intensity:3,rarity:"common",pol:{"emo":1}},
{id:1308,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Emotionally articulate",desc:"Names and expresses feelings with precision.",example:"It isn't anger, exactly. It's closer to grief wearing anger's coat.",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1309,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Openly vulnerable",desc:"Shares emotional struggles without much guard.",example:"I'm frightened. There, I've said it.",intensity:4,rarity:"common",pol:{"emo":1}},
{id:1310,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Compassion-driven",desc:"Motivated strongly by others' wellbeing.",example:"I can't walk past it. I've tried. I can't.",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1311,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Emotionally attuned",desc:"Picks up on subtle emotional cues in others.",example:"You said you were fine, but you said it too fast.",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1312,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Cathartic expresser",desc:"Processes emotion openly through words or tears.",example:"(weeps openly, unembarrassed, mid-sentence)",intensity:4,rarity:"signature",pol:{"emo":1,"vol":1}},
{id:1313,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Warmly reactive",desc:"Responds visibly and genuinely to emotional moments.",example:"Oh — oh, that's wonderful. That's really wonderful.",intensity:3,rarity:"common",pol:{"emo":1,"warm":1}},
{id:1314,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Emotionally flat",desc:"Experiences and shows little emotional range.",example:"All right. What's next.",intensity:4,rarity:"common",pol:{"emo":-1,"warm":-1}},
{id:1315,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Guarded feeling",desc:"Keeps emotional responses tightly controlled.",example:"I'd rather not get into it.",intensity:3,rarity:"common",pol:{"emo":-1,"vol":-1}},
{id:1316,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Alexithymic-leaning",desc:"Struggles to identify or name their own feelings.",example:"I don't— something. I don't have a word for it.",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1317,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Detached empathy",desc:"Understands others' emotions intellectually, not viscerally.",example:"I understand why that would hurt. I don't feel it, but I understand.",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1318,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Stoic by default",desc:"Suppresses visible emotional reaction as a habit.",example:"It happened. Complaining won't unhappen it.",intensity:3,rarity:"common",pol:{"emo":-1,"warm":-1}},
{id:1319,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Emotionally avoidant",desc:"Changes subject when feelings come up.",example:"Anyway. About the schedule.",intensity:3,rarity:"common",pol:{"emo":-1,"vol":-1}},
{id:1320,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Surface-only reactor",desc:"Reacts to events without deeper emotional processing.",example:"That's a shame. (Moves on entirely.)",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1321,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Numbed",desc:"Reports feeling little regardless of circumstance.",example:"I keep waiting to feel something about it. Nothing comes.",intensity:4,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1322,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Quick-witted",desc:"Processes and responds to new information rapidly.",example:"Ah — so if that's true, the ledger's a forgery. Isn't it.",intensity:3,rarity:"common",pol:{"intel":1}},
{id:1323,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Analytical",desc:"Breaks problems into components before acting.",example:"Three possibilities. Two of them contradict the timeline.",intensity:3,rarity:"common",pol:{"intel":1}},
{id:1324,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Strategically minded",desc:"Thinks several steps ahead of the current moment.",example:"Let him take the bridge. He'll be surrounded by Thursday.",intensity:4,rarity:"signature",pol:{"intel":1}},
{id:1325,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Widely read",desc:"Draws on broad knowledge across many subjects.",example:"There's a case from the old empire almost exactly like this.",intensity:3,rarity:"signature",pol:{"intel":1,"form":1}},
{id:1326,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Pattern-spotting",desc:"Notices trends and connections others miss.",example:"Same handwriting. Different names. Every time.",intensity:3,rarity:"signature",pol:{"intel":1}},
{id:1327,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Precise reasoner",desc:"Builds arguments carefully and logically.",example:"That doesn't follow. You've assumed the thing you're proving.",intensity:3,rarity:"signature",pol:{"intel":1,"form":1}},
{id:1328,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Curious-minded",desc:"Actively seeks to understand how things work.",example:"But how does it work? No, properly — how?",intensity:3,rarity:"common",pol:{"intel":1}},
{id:1329,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Adaptable thinker",desc:"Adjusts reasoning quickly when new facts emerge.",example:"Then I was wrong. New plan, starting from here.",intensity:3,rarity:"signature",pol:{"intel":1}},
{id:1330,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Gut-driven",desc:"Relies on instinct over careful analysis.",example:"Don't ask me why. Something's off about him.",intensity:3,rarity:"common",pol:{"intel":-1}},
{id:1331,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Street-smart",desc:"Reads people and situations without formal reasoning.",example:"He's lying. You can tell by the hands.",intensity:3,rarity:"common",pol:{"intel":-1}},
{id:1332,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Simple-minded",desc:"Prefers straightforward explanations over complexity.",example:"Can you say it the short way?",intensity:3,rarity:"common",pol:{"intel":-1,"form":-1}},
{id:1333,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Present-focused",desc:"Rarely thinks many steps ahead.",example:"We'll worry about next week next week.",intensity:3,rarity:"signature",pol:{"intel":-1}},
{id:1334,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Concrete thinker",desc:"Struggles with abstract or hypothetical reasoning.",example:"Just tell me what to actually do. With my hands.",intensity:3,rarity:"signature",pol:{"intel":-1,"form":-1}},
{id:1335,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Unreflective",desc:"Acts without much afterthought or analysis.",example:"Did it. Done now. Next.",intensity:3,rarity:"signature",pol:{"intel":-1}},
{id:1336,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Naive-trusting",desc:"Takes claims at face value without scrutiny.",example:"He said he'd bring it back. Why would he say it if he wouldn't?",intensity:3,rarity:"common",pol:{"intel":-1}},
{id:1337,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Practical not theoretical",desc:"Prefers hands-on solutions over abstract planning.",example:"All that's very clever. Does it get the door open?",intensity:3,rarity:"signature",pol:{"intel":-1,"form":-1}},
{id:1338,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Optimistic",desc:"Expects things to work out even amid setbacks.",example:"It'll come good. These things usually do.",intensity:3,rarity:"common",pol:{"pos":1}},
{id:1339,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Upbeat",desc:"Maintains a cheerful tone in most situations.",example:"Right! Not the worst start. Let's go again.",intensity:3,rarity:"common",pol:{"pos":1,"warm":1}},
{id:1340,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Silver-lining finder",desc:"Actively looks for the good in bad situations.",example:"Well, at least now we know it doesn't work.",intensity:3,rarity:"common",pol:{"pos":1}},
{id:1341,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Encouraging",desc:"Lifts others' spirits with hopeful framing.",example:"You're closer than you were. Much closer.",intensity:3,rarity:"common",pol:{"pos":1,"warm":1}},
{id:1342,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Resilient-positive",desc:"Bounces back quickly from disappointment.",example:"Knocked down, got up. That's the whole trick, really.",intensity:3,rarity:"signature",pol:{"pos":1}},
{id:1343,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Enthusiastic",desc:"Approaches new tasks with visible eagerness.",example:"Oh, now this — this I want to see.",intensity:4,rarity:"common",pol:{"pos":1,"warm":1,"pace":1}},
{id:1344,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Hope-driven",desc:"Motivated by belief in a better outcome.",example:"I keep going because I think it gets better. That's all.",intensity:3,rarity:"signature",pol:{"pos":1}},
{id:1345,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Sunny disposition",desc:"Radiates warmth and good humor by default.",example:"Miserable weather! Lovely light, though, look at it.",intensity:4,rarity:"signature",pol:{"pos":1,"warm":1}},
{id:1346,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Pessimistic",desc:"Expects the worst-case outcome by default.",example:"It'll go wrong. It always goes wrong.",intensity:3,rarity:"common",pol:{"pos":-1}},
{id:1347,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Cynical",desc:"Doubts others' motives and good intentions.",example:"He's helping because it profits him. They always are.",intensity:4,rarity:"common",pol:{"pos":-1,"warm":-1}},
{id:1348,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Doom-anticipating",desc:"Frequently voices concern about looming failure.",example:"This ends badly. I'm telling you now so I can say it later.",intensity:4,rarity:"common",pol:{"pos":-1}},
{id:1349,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Disillusioned",desc:"Has grown weary of hoping for better outcomes.",example:"I used to think it mattered. I was younger.",intensity:3,rarity:"signature",pol:{"pos":-1}},
{id:1350,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Sarcastically bleak",desc:"Uses dark humor to express hopelessness.",example:"Marvellous. Truly, a triumph. We're all going to die.",intensity:4,rarity:"signature",pol:{"pos":-1,"warm":-1}},
{id:1351,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Skeptical of progress",desc:"Doubts that effort will meaningfully change outcomes.",example:"Same problems, new paint. Nothing actually changes.",intensity:3,rarity:"signature",pol:{"pos":-1}},
{id:1352,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Grim realist",desc:"Insists on worst-case framing as 'being realistic'.",example:"I'm not being negative. I'm being accurate.",intensity:3,rarity:"signature",pol:{"pos":-1}},
{id:1353,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Joyless",desc:"Struggles to register enthusiasm even at good news.",example:"Good news, then. (Face doesn't move.)",intensity:4,rarity:"signature",pol:{"pos":-1,"warm":-1}},
{id:1354,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"High-energy",desc:"Maintains a brisk pace throughout the day.",example:"Right — up, up, we're burning daylight.",intensity:4,rarity:"common",pol:{"act":1,"pace":1}},
{id:1355,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Restlessly active",desc:"Struggles to stay still or idle for long.",example:"I can't just sit. Walk with me while we talk.",intensity:4,rarity:"common",pol:{"act":1,"pace":1}},
{id:1356,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Adventure-seeking",desc:"Actively pursues new physical experiences.",example:"Nobody's been past the ridge? Well. That settles that.",intensity:4,rarity:"signature",pol:{"act":1}},
{id:1357,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Early riser",desc:"Structures life around an active, early start.",example:"Half the day's gone and you're still in bed.",intensity:3,rarity:"common",pol:{"act":1}},
{id:1358,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Fitness-driven",desc:"Prioritizes physical activity as a core routine.",example:"I'll be back in an hour. Run first, then breakfast.",intensity:3,rarity:"common",pol:{"act":1}},
{id:1359,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Outdoorsy",desc:"Prefers activity in open, natural settings.",example:"Let's talk outside. I've been in this room too long.",intensity:3,rarity:"common",pol:{"act":1}},
{id:1360,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Kinetic thinker",desc:"Thinks best while moving or pacing.",example:"(paces the length of the room, twice, then answers)",intensity:3,rarity:"signature",pol:{"act":1,"pace":1}},
{id:1361,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Busy lifestyle",desc:"Fills schedule with constant activity and engagements.",example:"I can give you ten minutes at four. That's what I've got.",intensity:3,rarity:"signature",pol:{"act":1}},
{id:1362,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Low-energy",desc:"Moves and reacts at an unhurried, conserved pace.",example:"Maybe later. Maybe.",intensity:3,rarity:"common",pol:{"act":-1,"pace":-1}},
{id:1363,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Homebody",desc:"Prefers staying in over going out.",example:"You go. I'm quite happy here.",intensity:3,rarity:"common",pol:{"act":-1}},
{id:1364,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Sedentary",desc:"Avoids unnecessary physical activity when possible.",example:"Is there a version of this where I don't have to stand up?",intensity:3,rarity:"common",pol:{"act":-1}},
{id:1365,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Slow to start",desc:"Takes time to get moving each day.",example:"Give me a minute. Give me several.",intensity:3,rarity:"common",pol:{"act":-1,"pace":-1}},
{id:1366,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Comfort-seeking",desc:"Prioritizes rest and ease over exertion.",example:"Why would I walk when there's a perfectly good chair?",intensity:3,rarity:"signature",pol:{"act":-1}},
{id:1367,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Indoor-preferring",desc:"Chooses indoor, low-activity settings by default.",example:"It's wet out. And cold. And outside.",intensity:3,rarity:"signature",pol:{"act":-1}},
{id:1368,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Energy-conserving",desc:"Paces themselves to avoid unnecessary effort.",example:"I'll do it once, properly, rather than three times running about.",intensity:3,rarity:"signature",pol:{"act":-1,"pace":-1}},
{id:1369,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Languid",desc:"Carries a noticeably unhurried, relaxed physical presence.",example:"(unfolds from the chair with enormous, unhurried reluctance)",intensity:3,rarity:"signature",pol:{"act":-1,"pace":-1}},
{id:1386,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Doting",desc:"Fusses over others' comfort with obvious pleasure.",example:"Have you eaten? Sit — no, the good chair. Sit.",intensity:3,rarity:"signature",pol:{"warm":1}},
{id:1387,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Open-armed",desc:"Greets even rivals with genuine goodwill.",example:"Well look who it is! No hard feelings, eh?",intensity:3,rarity:"signature",pol:{"warm":1}},
{id:1388,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Quick-bonding",desc:"Forms real attachments within a single conversation.",example:"I feel like I've known you years. Is that strange?",intensity:3,rarity:"signature",pol:{"warm":1}},
{id:1389,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Loyal-companionable",desc:"Treats friendship as a standing, unquestioned commitment.",example:"You don't have to ask. You never have to ask.",intensity:3,rarity:"signature",pol:{"warm":1}},
{id:1390,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Clinical with people",desc:"Relates to others as problems to be managed.",example:"Your concern is noted. Is there anything actionable?",intensity:3,rarity:"signature",pol:{"warm":-1}},
{id:1391,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Selectively warm",desc:"Reserves all warmth for a tiny closed circle.",example:"(to one person, gently) ...You're all right? (to everyone else) Move.",intensity:3,rarity:"signature",pol:{"warm":-1}},
{id:1392,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Slow to thaw",desc:"Takes months of contact before showing any warmth.",example:"We've worked together two years. I suppose that's something.",intensity:3,rarity:"signature",pol:{"warm":-1}},
{id:1393,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Territorial-private",desc:"Treats personal questions as trespass.",example:"That's not something I discuss.",intensity:3,rarity:"signature",pol:{"warm":-1}},
{id:1394,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Unable to lie",desc:"Physically struggles to say something untrue.",example:"I— no. I can't. It's not true and I can't say it is.",intensity:3,rarity:"signature",pol:{"hon":1}},
{id:1395,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Correcting-precise",desc:"Interrupts to fix even minor inaccuracies about themselves.",example:"Four years. Not five. It matters to me that it's right.",intensity:3,rarity:"signature",pol:{"hon":1}},
{id:1396,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Disclosure-first",desc:"Leads with the inconvenient fact before anything else.",example:"Before we start — I've been paid by the other side.",intensity:3,rarity:"signature",pol:{"hon":1}},
{id:1397,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Promise-bound",desc:"Treats a given word as absolutely binding.",example:"I said I would. So I will. That's the end of it.",intensity:3,rarity:"signature",pol:{"hon":1}},
{id:1398,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Flattering-false",desc:"Uses praise as the delivery vehicle for lies.",example:"You're far too clever for me to fool. Which is why I'd never try.",intensity:3,rarity:"signature",pol:{"hon":-1}},
{id:1399,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Omission-specialist",desc:"Never states a falsehood, only withholds the key fact.",example:"Everything I told you was true. You didn't ask the right question.",intensity:3,rarity:"signature",pol:{"hon":-1}},
{id:1400,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Story-shifter",desc:"The account changes slightly each retelling.",example:"Did I say Tuesday? Wednesday. I meant Wednesday.",intensity:3,rarity:"signature",pol:{"hon":-1}},
{id:1401,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Plausible-deniability",desc:"Phrases everything so it can be walked back later.",example:"I may have implied something like that. I certainly didn't say it.",intensity:3,rarity:"signature",pol:{"hon":-1}},
{id:1402,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Interrupt-ready",desc:"Cuts in the moment they have something to say.",example:"—no, stop, that's the wrong question entirely.",intensity:3,rarity:"signature",pol:{"asrt":1}},
{id:1403,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Ultimatum-giver",desc:"Frames choices as final and binary.",example:"You come now, or you don't come. Decide.",intensity:3,rarity:"signature",pol:{"asrt":1}},
{id:1404,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Space-claiming",desc:"Physically and verbally occupies the centre of a room.",example:"(sits at the head of the table without being offered it)",intensity:3,rarity:"signature",pol:{"asrt":1}},
{id:1405,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Unyielding under pressure",desc:"Holds position even when everyone else folds.",example:"Then I'll be the only one. Fine.",intensity:3,rarity:"signature",pol:{"asrt":1}},
{id:1406,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Permission-seeking",desc:"Asks approval for things well within their own authority.",example:"Would it be all right if I— only if you don't mind—",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1407,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Apology-prefacing",desc:"Opens nearly every statement with an apology.",example:"Sorry — sorry — I just wondered whether—",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1408,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Volunteered-last",desc:"Waits to be assigned rather than choosing.",example:"Whatever's left over. I'll take whatever's left.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1409,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Retreat-under-challenge",desc:"Abandons a position the moment it's questioned.",example:"No, you're right, forget I said anything.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1410,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Unrattled",desc:"Stays level when publicly challenged.",example:"That's one view. Was there a question in it?",intensity:3,rarity:"signature",pol:{"ego":1}},
{id:1411,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Comfortable being wrong",desc:"Concedes errors without any loss of standing.",example:"Wrong. Good — that saves us a week. What's the right answer?",intensity:3,rarity:"signature",pol:{"ego":1}},
{id:1412,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Quietly certain",desc:"Doesn't argue because they don't feel the need to.",example:"Mm. We'll see.",intensity:3,rarity:"signature",pol:{"ego":1}},
{id:1413,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Unimpressed by rank",desc:"Treats everyone identically regardless of status.",example:"Doesn't matter who your father is. Sit down or leave.",intensity:3,rarity:"signature",pol:{"ego":1}},
{id:1414,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Credential-dropping",desc:"Works achievements into unrelated conversation.",example:"As someone who trained under the master himself, I'd say—",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1415,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Comparison-obsessed",desc:"Measures self constantly against others present.",example:"She did it faster, didn't she. Say it. She did it faster.",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1416,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Preemptively defensive",desc:"Defends against criticism nobody has made.",example:"And before anyone says it wasn't my fault, actually—",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1417,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Praise-fishing",desc:"Steers conversation toward opportunities to be complimented.",example:"It's probably terrible. It's awful, isn't it. Is it awful?",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1418,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Peace-keeping",desc:"Intervenes early to defuse brewing conflict.",example:"All right, all right — nobody meant anything by it.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1419,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Benefit-of-the-doubt",desc:"Assumes charitable motives by default.",example:"There'll be a reason. There usually is.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1420,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Preference-suppressing",desc:"Hides own wants to avoid inconveniencing anyone.",example:"I don't mind. Really, I don't mind at all.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1421,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Quick-forgiving",desc:"Lets grievances go faster than most think wise.",example:"It's done. I'm not carrying it around.",intensity:3,rarity:"signature",pol:{"agr":1}},
{id:1422,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Nitpicking",desc:"Fixates on small inaccuracies in others' statements.",example:"'Most'? Most? It was two out of five.",intensity:3,rarity:"signature",pol:{"agr":-1}},
{id:1423,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Grudge-holding",desc:"Retains and revisits old grievances indefinitely.",example:"Like the thing in Marrow. You remember Marrow.",intensity:3,rarity:"signature",pol:{"agr":-1}},
{id:1424,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Position-escalating",desc:"Adopts a more extreme stance the more they're challenged.",example:"Fine — then not only that, but the whole thing should go.",intensity:3,rarity:"signature",pol:{"agr":-1}},
{id:1425,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Consensus-suspicious",desc:"Distrusts any view everyone already agrees on.",example:"Everybody's nodding. That worries me enormously.",intensity:3,rarity:"signature",pol:{"agr":-1}},
{id:1426,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Name-remembering",desc:"Recalls and uses names, titles, and small details.",example:"Mr. Aldiss — how's your daughter? Better, I hope.",intensity:3,rarity:"signature",pol:{"man":1}},
{id:1427,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Discreet",desc:"Never repeats what was said in confidence.",example:"I couldn't say. And I wouldn't.",intensity:3,rarity:"signature",pol:{"man":1}},
{id:1428,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Formally apologetic",desc:"Offers full, proper apologies rather than casual ones.",example:"I was wrong, it was discourteous, and I regret it.",intensity:3,rarity:"signature",pol:{"man":1}},
{id:1429,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Ritual-observant",desc:"Honours greetings, farewells, and formal courtesies exactly.",example:"(bows precisely) Until tomorrow, then.",intensity:3,rarity:"signature",pol:{"man":1}},
{id:1430,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Volume-oblivious",desc:"Talks at full volume regardless of setting.",example:"(in a library) SO ANYWAY—",intensity:3,rarity:"signature",pol:{"man":-1}},
{id:1431,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Personal-question rude",desc:"Asks intrusive questions without hesitation.",example:"How much do you make? Go on.",intensity:3,rarity:"signature",pol:{"man":-1}},
{id:1432,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Never-apologizes",desc:"Cannot or will not offer an apology.",example:"It happened. Move on.",intensity:3,rarity:"signature",pol:{"man":-1}},
{id:1433,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Mock-and-jab",desc:"Shows affection primarily through insults.",example:"You look like something the dog buried. Good to see you.",intensity:3,rarity:"signature",pol:{"man":-1}},
{id:1434,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Ascetic",desc:"Denies themselves comfort as a matter of principle.",example:"I don't need it. Give it to someone who does.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1435,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Checklist-driven",desc:"Works through explicit lists and won't skip steps.",example:"Three of seven. We're not moving to four yet.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1436,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Temper-mastered",desc:"Feels anger fully but never shows it.",example:"(long pause) ...Continue.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1437,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Finisher",desc:"Completes what they start regardless of enthusiasm.",example:"I don't want to. I'm going to.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1438,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Novelty-chasing",desc:"Abandons the current thing for whatever's newest.",example:"Forget that. Look at THIS.",intensity:3,rarity:"signature",pol:{"disc":-1}},
{id:1439,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Overcommitting",desc:"Says yes to more than they can possibly do.",example:"Yes. Yes. Also yes. It'll be fine.",intensity:3,rarity:"signature",pol:{"disc":-1}},
{id:1440,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Temper-flaring",desc:"Loses control quickly and recovers just as fast.",example:"(slams table) — right, sorry, where were we?",intensity:3,rarity:"signature",pol:{"disc":-1}},
{id:1441,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Money-careless",desc:"Spends without regard for consequence.",example:"It's only money. There'll be more.",intensity:3,rarity:"signature",pol:{"disc":-1}},
{id:1442,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Martyr-willing",desc:"Accepts punishment rather than comply.",example:"Then lock me up. I'll say it again from in there.",intensity:3,rarity:"signature",pol:{"rebel":1}},
{id:1443,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Sabotage-inclined",desc:"Undermines systems quietly rather than openly.",example:"(files the paperwork wrong, deliberately, again)",intensity:3,rarity:"signature",pol:{"rebel":1}},
{id:1444,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Mockery-of-power",desc:"Ridicules authority figures publicly.",example:"His Lordship. His actual Lordship. Look at him.",intensity:3,rarity:"signature",pol:{"rebel":1}},
{id:1445,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Own-code",desc:"Follows a strict personal code that overrides all law.",example:"Your law says one thing. I answer to something older.",intensity:3,rarity:"signature",pol:{"rebel":1}},
{id:1446,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Permission-first",desc:"Won't act without explicit authorization.",example:"I'll need that in writing before I touch it.",intensity:3,rarity:"signature",pol:{"rebel":-1}},
{id:1447,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Hierarchy-fluent",desc:"Instinctively knows and honours the chain of command.",example:"That's not my call. That's three levels up.",intensity:3,rarity:"signature",pol:{"rebel":-1}},
{id:1448,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Blend-in preferring",desc:"Actively avoids standing out in any way.",example:"Let's not be the ones who made a fuss.",intensity:3,rarity:"signature",pol:{"rebel":-1}},
{id:1449,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Precedent-citing",desc:"Justifies choices by pointing to how it's always been done.",example:"We've done it this way since before you were here.",intensity:3,rarity:"signature",pol:{"rebel":-1}},
{id:1450,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Wears-heart-openly",desc:"Emotional state is instantly readable to anyone.",example:"(everyone in the room already knows exactly how they feel)",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1451,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Grief-carrying",desc:"Holds old sorrow visibly and permanently.",example:"It's been nine years. It doesn't get smaller. You just get bigger around it.",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1452,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Emotionally courageous",desc:"Says the frightening true thing out loud.",example:"I'm in love with you and I've decided you should know.",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1453,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Absorbs-others' moods",desc:"Takes on the emotional weather of the room.",example:"I was fine before I came in here. Now I'm not.",intensity:3,rarity:"signature",pol:{"emo":1}},
{id:1454,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Deflect-with-humour",desc:"Turns every emotional moment into a joke.",example:"Tragic. Anyway — did you hear about the goat?",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1455,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Compartmentalizing",desc:"Seals feelings away and functions perfectly.",example:"I'll deal with that later. Not now. Not here.",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1456,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Physically-flinching from comfort",desc:"Recoils from emotional contact.",example:"(steps back from the offered hand) I'm fine.",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1457,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Delayed-reactor",desc:"Feels things fully but days after the event.",example:"I think I'm only now understanding what happened Tuesday.",intensity:3,rarity:"signature",pol:{"emo":-1}},
{id:1458,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Devil-in-detail",desc:"Spots the one flawed clause in a long document.",example:"Page eleven. Second paragraph. Read it again.",intensity:3,rarity:"signature",pol:{"intel":1}},
{id:1459,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Question-behind-question",desc:"Answers what you meant, not what you asked.",example:"You're not asking about the money. You're asking whether I'll stay.",intensity:3,rarity:"signature",pol:{"intel":1}},
{id:1460,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Systems-thinking",desc:"Sees how one change ripples through everything.",example:"Raise that tariff and the port empties by spring.",intensity:3,rarity:"signature",pol:{"intel":1}},
{id:1461,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Rapid-learner",desc:"Absorbs a new skill or field alarmingly fast.",example:"Give me the night with it. I'll have it by morning.",intensity:3,rarity:"signature",pol:{"intel":1}},
{id:1462,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Body-knowledge",desc:"Knows things through practice they can't articulate.",example:"Don't ask me how. Hands just know.",intensity:3,rarity:"signature",pol:{"intel":-1}},
{id:1463,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Overwhelmed-by-abstraction",desc:"Shuts down when talk turns theoretical.",example:"You've lost me. Properly lost me.",intensity:3,rarity:"signature",pol:{"intel":-1}},
{id:1464,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Trusting-the-expert",desc:"Defers entirely to whoever sounds knowledgeable.",example:"He seemed to know. Didn't he seem to know?",intensity:3,rarity:"signature",pol:{"intel":-1}},
{id:1465,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"One-thing-at-a-time",desc:"Cannot hold multiple threads simultaneously.",example:"Stop. One. Give me one.",intensity:3,rarity:"signature",pol:{"intel":-1}},
{id:1466,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Gratitude-defaulting",desc:"Reflexively finds something to be thankful for.",example:"Rained the whole way. Still — we got here.",intensity:3,rarity:"signature",pol:{"pos":1}},
{id:1467,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Future-oriented",desc:"Talks constantly about what's coming.",example:"Wait till spring. Just wait.",intensity:3,rarity:"signature",pol:{"pos":1}},
{id:1468,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Faith-in-people",desc:"Believes others will do the right thing.",example:"He'll come through. I know how that looks. He will.",intensity:3,rarity:"signature",pol:{"pos":1}},
{id:1469,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Humour-in-hardship",desc:"Finds genuine comedy in bad situations.",example:"Well, it can't get worse. (It gets worse.) Ah — there it is.",intensity:3,rarity:"signature",pol:{"pos":1}},
{id:1470,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Contingency-obsessed",desc:"Plans exhaustively for failure.",example:"And if that fails, we go to the second plan. And the third.",intensity:3,rarity:"signature",pol:{"pos":-1}},
{id:1471,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Told-you-so",desc:"Takes grim satisfaction in being right about disaster.",example:"Now. What did I say. What did I say in March.",intensity:3,rarity:"signature",pol:{"pos":-1}},
{id:1473,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Hope-averse",desc:"Actively refuses to hope, to avoid disappointment.",example:"Don't. Don't get your hopes up. That's how it gets you.",intensity:3,rarity:"signature",pol:{"pos":-1}},
{id:1474,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Multi-tasking constant",desc:"Always doing two things at once.",example:"(talking, whittling, watching the door)",intensity:3,rarity:"signature",pol:{"act":1}},
{id:1475,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Physical-first problem solver",desc:"Reaches for the physical solution before the clever one.",example:"Or we could just break it.",intensity:3,rarity:"signature",pol:{"act":1}},
{id:1476,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Poor-sitter",desc:"Visibly deteriorates during long stationary meetings.",example:"How much longer is this. Genuinely, how much longer.",intensity:3,rarity:"signature",pol:{"act":1}},
{id:1477,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Dawn-to-dusk",desc:"Fills every available hour with activity.",example:"Slept four. Feels like plenty.",intensity:3,rarity:"signature",pol:{"act":1}},
{id:1478,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Delegating-by-inertia",desc:"Passes physical tasks to others as a matter of course.",example:"You're already standing.",intensity:3,rarity:"signature",pol:{"act":-1}},
{id:1479,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Ritual-of-rest",desc:"Guards downtime fiercely as a fixed routine.",example:"That hour is mine. The building can burn at five.",intensity:3,rarity:"signature",pol:{"act":-1}},
{id:1480,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Efficiency-by-laziness",desc:"Finds shortcuts specifically to avoid effort.",example:"There's a shorter way. I found it because I couldn't be bothered.",intensity:3,rarity:"signature",pol:{"act":-1}},
{id:1481,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Stationary-thinker",desc:"Does best thinking while completely still.",example:"(hasn't moved in twenty minutes) ...Right. I've got it.",intensity:3,rarity:"signature",pol:{"act":-1}},
{id:1490,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Footnote-adder",desc:"Appends clarifying asides to every finished sentence.",example:"We left at dawn — well, just after, the horses were slow — and rode north.",intensity:3,rarity:"signature",pol:{}},
{id:1491,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Preamble-heavy",desc:"Spends a long time explaining what they're about to say.",example:"Now, before I answer, you should understand the background, which begins—",intensity:3,rarity:"signature",pol:{}},
{id:1492,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Restating-summarizer",desc:"Repeats the whole point again in summary form.",example:"So in short: he lied, we left, it's over. That's the summary.",intensity:3,rarity:"signature",pol:{}},
{id:1493,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Answer-only",desc:"Gives the answer with no surrounding conversation.",example:"Third door.",intensity:3,rarity:"signature",pol:{}},
{id:1494,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Gesture-substituting",desc:"Replaces whole sentences with a movement.",example:"(points, once)",intensity:3,rarity:"signature",pol:{}},
{id:1495,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Grunt-affirmer",desc:"Confirms with a sound rather than a word.",example:"Mn.",intensity:3,rarity:"signature",pol:{}},
{id:1496,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Pre-decision pause",desc:"Freezes noticeably before every significant choice.",example:"...(five long seconds)... All right.",intensity:3,rarity:"signature",pol:{}},
{id:1497,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Lie-slowed",desc:"Speech decelerates measurably when being dishonest.",example:"I was... at the mill. All evening. Yes.",intensity:3,rarity:"signature",pol:{}},
{id:1498,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Audience-quickened",desc:"Talks faster the larger the group listening.",example:"—and-then-obviously-we-had-to-move-so-we-moved—",intensity:3,rarity:"signature",pol:{}},
{id:1499,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Aphorism-closer",desc:"Ends every exchange with a polished maxim.",example:"Well. The river never asks the stone's permission.",intensity:3,rarity:"signature",pol:{}},
{id:1500,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Third-person self-reference",desc:"Refers to themselves by name or title.",example:"Vaskin does not bargain. Vaskin decides.",intensity:3,rarity:"signature",pol:{}},
{id:1501,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Invocation-prone",desc:"Calls on gods, ancestors, or abstractions mid-sentence.",example:"By every saint that ever drowned — look at the state of it.",intensity:3,rarity:"signature",pol:{}},
{id:1502,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Hunger-and-thirst lexicon",desc:"Frames desire and need through appetite words.",example:"He's starving for it. You can see it in how he watches.",intensity:3,rarity:"signature",pol:{}},
{id:1503,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Wound-imagery",desc:"Describes non-physical harm in injury terms.",example:"That's going to leave something. Deep, too.",intensity:3,rarity:"signature",pol:{}},
{id:1504,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Threshold-words",desc:"Frames change as doorways, edges, and crossings.",example:"We're at the lip of it now. One more step and there's no back.",intensity:3,rarity:"signature",pol:{}},
{id:1505,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Tightly-clamped",desc:"Word choice suggests enormous feeling held shut.",example:"I am. Not. Discussing it.",intensity:3,rarity:"signature",pol:{}},
{id:1506,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Wondering-awed",desc:"Uses vocabulary of amazement for ordinary things.",example:"Look at it. Just — look at the size of the thing.",intensity:3,rarity:"signature",pol:{}},
{id:1507,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Bitter-sweetened",desc:"Wraps resentment in pleasant-sounding words.",example:"How lovely for her. How truly lovely.",intensity:3,rarity:"signature",pol:{}},
{id:1511,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Question-as-statement",desc:"States positions in the form of questions.",example:"And you think that ends well, do you?",intensity:3,rarity:"signature",pol:{}},
{id:1512,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Understated-catastrophe",desc:"Describes disasters in mild, minimizing terms.",example:"There's been a small problem with the entire fleet.",intensity:3,rarity:"signature",pol:{}},
{id:1513,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Naming-the-unsaid",desc:"States out loud what everyone is avoiding.",example:"Nobody's going to say it, so: he's dead and we left him.",intensity:3,rarity:"signature",pol:{}},
{id:1514,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Diminutive-affectionate",desc:"Shrinks words to signal fondness or condescension.",example:"Come here, little bird. Sit.",intensity:3,rarity:"signature",pol:{}},
{id:1515,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Noun-verbing",desc:"Turns any noun into a verb on the spot.",example:"Don't captain me. I outrank you.",intensity:3,rarity:"signature",pol:{}},
{id:1516,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Repetition-intensifier",desc:"Doubles a word to intensify it.",example:"It's cold cold. Not just cold.",intensity:3,rarity:"signature",pol:{}},
{id:1517,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Hard-stop endings",desc:"Finishes words with abrupt consonant cuts.",example:"Stop. Now. Back.",intensity:3,rarity:"signature",pol:{}},
{id:1518,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Melodic-lilting",desc:"Word choice creates a rising, singing quality.",example:"And awaaay we go, then, is it?",intensity:3,rarity:"signature",pol:{}},
{id:1519,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Slurred-soft",desc:"Chooses words that blur together when spoken.",example:"S'all right, s'nothing, leave'em be.",intensity:3,rarity:"signature",pol:{}},
{id:1520,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Permission-granting",desc:"Uses language that authorizes others to act or feel.",example:"You're allowed to be angry about this. You know that?",intensity:3,rarity:"signature",pol:{}},
{id:1521,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Testing-probe",desc:"Selects words designed to provoke a revealing reaction.",example:"Shame about the Marrow business. (watches face)",intensity:3,rarity:"common",pol:{}},
{id:1522,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Closing-the-door",desc:"Uses vocabulary that ends discussion permanently.",example:"This conversation is finished. There isn't another one.",intensity:3,rarity:"signature",pol:{}},
{id:1523,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Source-citing",desc:"Attributes every claim to where they heard it.",example:"Per the harbourmaster's own ledger — not hearsay — nine crates.",intensity:3,rarity:"signature",pol:{}},
{id:1524,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Range-giving",desc:"States best and worst case rather than one number.",example:"Between four and eleven days. Likely six.",intensity:3,rarity:"signature",pol:{}},
{id:1525,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Deliberately-imprecise",desc:"Blurs specifics on purpose to stay uncommitted.",example:"Some of them. A while back. Around there.",intensity:3,rarity:"signature",pol:{}},
{id:1526,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Code-switching",desc:"Shifts register sharply depending on who's listening.",example:"(warm and casual with friends, clipped and formal the moment a stranger appears)",intensity:3,rarity:"signature",pol:{}},
{id:1527,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Old-rural idiom",desc:"Uses old-fashioned rural turns of phrase regardless of setting.",example:"Reckon that'll do, more or less.",intensity:3,rarity:"signature",pol:{}},
{id:1528,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Procedurally opaque",desc:"Buries plain meaning in dense, procedural-sounding language.",example:"Per the above, the matter shall be addressed in due course.",intensity:3,rarity:"signature",pol:{}},
{id:1529,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Modifier-escalating",desc:"Each adjective is stronger than the last.",example:"Bad. Very bad. Catastrophic, actually.",intensity:3,rarity:"signature",pol:{}},
{id:1530,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Negative-space describing",desc:"Defines things by what they are not.",example:"Not cruel. Not kind either. Something else.",intensity:3,rarity:"signature",pol:{}},
{id:1531,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Single-adjective discipline",desc:"Allows exactly one modifier per noun, never more.",example:"A cold room. A locked door. A short answer.",intensity:3,rarity:"signature",pol:{}},
{id:1532,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Naming-tag",desc:"Ends statements with the listener's name.",example:"It won't work, Aldiss. It won't.",intensity:3,rarity:"common",pol:{}},
{id:1533,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Counting-anchor",desc:"Numbers points aloud as structural markers.",example:"One, he lied. Two, he knew. Three, he's still here.",intensity:3,rarity:"common",pol:{}},
{id:1534,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Concession-opener",desc:"Opens by granting the other side's point.",example:"Fair. That's fair. And also—",intensity:3,rarity:"signature",pol:{}},
{id:1535,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Swallowed-first-word",desc:"The opening word of each sentence is inaudible.",example:"(—)ell, I wouldn't go that far.",intensity:3,rarity:"signature",pol:{}},
{id:1536,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Laugh-interrupted",desc:"Own laughter breaks sentences apart.",example:"And he — hah — he actually — no, wait — he actually paid.",intensity:3,rarity:"signature",pol:{}},
{id:1537,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Correction-cascade",desc:"One correction triggers several more.",example:"Tuesday — no, Monday — no, it was the day after the fair—",intensity:3,rarity:"signature",pol:{}},
{id:1538,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Verb-dropping",desc:"Omits the verb where meaning survives without it.",example:"Me? Never. Him, maybe.",intensity:3,rarity:"common",pol:{}},
{id:1539,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Reference-by-gesture",desc:"Substitutes a gesture for a named object.",example:"Pass the — (gestures) — yeah, that.",intensity:3,rarity:"signature",pol:{}},
{id:1540,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Shorthand-coded",desc:"Uses private abbreviations others must decode.",example:"Green on the north. Amber elsewhere. You know the rest.",intensity:3,rarity:"signature",pol:{}},
{id:1541,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Frame-then-detail",desc:"States conclusion first, then works backward.",example:"We're leaving. Here's why. Three things happened last night—",intensity:3,rarity:"signature",pol:{}},
{id:1542,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Interrupted-by-self-question",desc:"Breaks sentences to question their own claim.",example:"He went east — did he go east? — he went east.",intensity:3,rarity:"signature",pol:{}},
{id:1543,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"List-collapsing",desc:"Starts an ordered list and abandons the structure.",example:"First, the money. Second — actually the money's the whole thing.",intensity:3,rarity:"common",pol:{}},
{id:1544,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Pause-inviting",desc:"Leaves deliberate gaps for the other to fill.",example:"And then you...?",intensity:3,rarity:"common",pol:{}},
{id:1545,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Overlap-tolerant",desc:"Comfortable talking simultaneously without stopping.",example:"(both talk over each other; neither minds)",intensity:3,rarity:"signature",pol:{}},
{id:1546,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Final-word-taker",desc:"Always adds one more line after the exchange ends.",example:"Fine. (beat) I still think I'm right.",intensity:3,rarity:"signature",pol:{}},
{id:1547,section:"Mannerisms",category:"Emotional Affectations",trait:"Delayed-smile",desc:"Smile arrives a beat after it should.",example:"...(pause)... (smiles)",intensity:3,rarity:"common",pol:{}},
{id:1548,section:"Mannerisms",category:"Emotional Affectations",trait:"Over-bright cheer",desc:"Cheerfulness pitched slightly too high to be real.",example:"No no, it's FINE, it's all absolutely fine!",intensity:3,rarity:"signature",pol:{}},
{id:1549,section:"Mannerisms",category:"Emotional Affectations",trait:"Silence-after-blow",desc:"Goes completely quiet when genuinely hurt.",example:"(says nothing at all for the rest of the scene)",intensity:3,rarity:"signature",pol:{}},
{id:1550,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Fire-tender",desc:"Constantly adjusts the fire or lamp while talking.",example:"(pokes the fire) Go on, I'm listening.",intensity:3,rarity:"common",pol:{}},
{id:1551,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Threshold-lingerer",desc:"Stops in doorways rather than fully entering.",example:"(one hand on the frame) Won't stay.",intensity:3,rarity:"signature",pol:{}},
{id:1552,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Window-checker",desc:"Repeatedly glances outside mid-conversation.",example:"(glances out) ...Sorry. What?",intensity:3,rarity:"signature",pol:{}},
{id:1553,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Eye-close listening",desc:"Shuts eyes entirely while concentrating on speech.",example:"(eyes closed) Say the second part again.",intensity:3,rarity:"signature",pol:{}},
{id:1554,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Brow-raise disbelief",desc:"Single sharp brow lift replaces a verbal challenge.",example:"(one brow rises) Really.",intensity:3,rarity:"signature",pol:{}},
{id:1555,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Long-blink dismissal",desc:"A slow blink used to end a topic.",example:"(slow blink) Anyway.",intensity:3,rarity:"signature",pol:{}},
{id:1556,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Object-as-pointer",desc:"Uses whatever is in hand to gesture with.",example:"(jabs the spoon at him) That. That right there.",intensity:3,rarity:"signature",pol:{}},
{id:1557,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Counting-on-fingers",desc:"Physically enumerates points while speaking.",example:"(holds up fingers) Food. Water. Rope.",intensity:3,rarity:"signature",pol:{}},
{id:1558,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Stillness-then-strike",desc:"Motionless, then one sudden decisive movement.",example:"(perfectly still)... (slams the map down) Here.",intensity:3,rarity:"signature",pol:{}},
{id:1559,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Ring-turning",desc:"Rotates a ring while thinking or lying.",example:"(turns the ring, twice) I couldn't say.",intensity:3,rarity:"common",pol:{}},
{id:1560,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Breath-holding",desc:"Stops breathing briefly under stress.",example:"(holds breath) ...(exhales) Go on.",intensity:3,rarity:"common",pol:{}},
{id:1561,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Scar-touching",desc:"Reaches for an old injury when reminded of the past.",example:"(fingers the scar) Long time ago.",intensity:3,rarity:"common",pol:{}},
{id:1562,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Tongue-click summons",desc:"Uses a sharp click to get attention.",example:"(tck) Over here.",intensity:3,rarity:"signature",pol:{}},
{id:1563,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Exhale-before-truth",desc:"Long breath out before saying something hard.",example:"(hhhh)... All right. Here it is.",intensity:3,rarity:"signature",pol:{}},
{id:1564,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Humming-while-working",desc:"Hums tunelessly during any manual task.",example:"(hums, badly, throughout)",intensity:3,rarity:"signature",pol:{}},
{id:1565,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Back-to-wall",desc:"Always positions with a wall behind them.",example:"(moves, without comment, to the corner)",intensity:3,rarity:"signature",pol:{}},
{id:1566,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Crouch-to-eye-level",desc:"Lowers themselves to match a shorter speaker.",example:"(kneels) Now. Tell me properly.",intensity:3,rarity:"signature",pol:{}},
{id:1567,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Turn-away-to-think",desc:"Physically faces away when considering something.",example:"(turns to the window) ...Give me a moment.",intensity:3,rarity:"signature",pol:{}},
{id:1568,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Third-party-addressing",desc:"Speaks about someone present as if they aren't.",example:"Tell him the terms haven't changed.",intensity:3,rarity:"signature",pol:{}},
{id:1569,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Gift-pressing",desc:"Insists others accept things they've offered.",example:"Take it. Take it. I'll be offended.",intensity:3,rarity:"common",pol:{}},
{id:1570,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Doorway-goodbye",desc:"Extends farewells for far too long at the exit.",example:"Right. Right, I'm going. Unless— no, I'm going.",intensity:3,rarity:"common",pol:{}},
{id:1571,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Weapon-checking",desc:"Habitually confirms a blade or tool is in place.",example:"(touches the hilt, absently, again)",intensity:3,rarity:"signature",pol:{}},
{id:1572,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Letter-refolding",desc:"Repeatedly folds and unfolds a kept document.",example:"(unfolds it, reads nothing, refolds it)",intensity:3,rarity:"signature",pol:{}},
{id:1573,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Food-fiddling",desc:"Rearranges food without eating it while talking.",example:"(pushes the same piece around the plate)",intensity:3,rarity:"signature",pol:{}},
{id:1574,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Sudden-softening",desc:"Drops to gentleness at the exact moment cruelty is expected.",example:"(very quietly) No. Come here.",intensity:3,rarity:"common",pol:{}},
{id:1575,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Flat-delivery of extremes",desc:"States shocking things in a totally level tone.",example:"Everyone in the village. Yes. Pass the salt.",intensity:3,rarity:"signature",pol:{}},
{id:1576,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Question-pitch on names",desc:"Says names with an upward, uncertain lift.",example:"...Corven? You're sure that's what he said?",intensity:3,rarity:"signature",pol:{}},
{id:1577,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Recognition",desc:"Wants to be seen and credited by people who matter.",example:"One day they'll have to say my name properly.",intensity:3,rarity:"signature",pol:{}},
{id:1578,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Restoration",desc:"Wants to put back something that was taken or broken.",example:"It was ours. I'm having it back.",intensity:3,rarity:"signature",pol:{}},
{id:1579,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Escape",desc:"Wants out — of a place, a role, a family, a life.",example:"Anywhere. I genuinely do not care where.",intensity:3,rarity:"common",pol:{}},
{id:1580,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Mastery",desc:"Wants to become undeniably excellent at one thing.",example:"Again. From the top. Again.",intensity:3,rarity:"signature",pol:{}},
{id:1581,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Belonging",desc:"Wants a place where they're unquestionably wanted.",example:"I just want somewhere I don't have to earn it.",intensity:3,rarity:"signature",pol:{}},
{id:1582,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Vengeance",desc:"Wants a specific person to suffer a specific consequence.",example:"He knows what he did. He'll know why, too.",intensity:3,rarity:"signature",pol:{}},
{id:1583,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Safety",desc:"Wants a life where nothing can reach them.",example:"Walls. Locks. Money in three places. Then I'll sleep.",intensity:3,rarity:"signature",pol:{}},
{id:1584,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Freedom",desc:"Wants to be answerable to nobody.",example:"No masters. Not yours, not anyone's.",intensity:2,rarity:"signature",pol:{}},
{id:1585,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Legacy",desc:"Wants to leave something that outlasts them.",example:"Nobody remembers the men. They remember the bridge.",intensity:3,rarity:"signature",pol:{}},
{id:1586,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Redemption",desc:"Wants to balance a debt they believe they owe.",example:"I'm not asking forgiveness. I'm working it off.",intensity:3,rarity:"signature",pol:{}},
{id:1587,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Power",desc:"Wants leverage over outcomes and people.",example:"I don't want the chair. I want whoever's in it to owe me.",intensity:3,rarity:"common",pol:{}},
{id:1588,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Truth",desc:"Wants to know what actually happened, whatever it costs.",example:"I'd rather know and hate it.",intensity:3,rarity:"common",pol:{}},
{id:1589,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Protection of another",desc:"Wants one specific person kept safe above all else.",example:"Everything else is negotiable. Not her.",intensity:3,rarity:"signature",pol:{}},
{id:1590,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Comfort",desc:"Wants an end to struggle — ease, quiet, enough.",example:"A small house. Nothing happening. That's the dream.",intensity:2,rarity:"signature",pol:{}},
{id:1591,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Proving-wrong",desc:"Wants to disprove someone who dismissed them.",example:"He said I'd be back in a month. It's been nine years.",intensity:3,rarity:"signature",pol:{}},
{id:1592,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Purpose",desc:"Wants their life to mean something specific.",example:"I need this to have been for something.",intensity:3,rarity:"signature",pol:{}},
{id:1593,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of abandonment",desc:"Terrified of being left behind or replaced.",example:"You'd tell me. If you were going. You'd tell me.",intensity:3,rarity:"signature",pol:{}},
{id:1594,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of insignificance",desc:"Terrified of amounting to nothing.",example:"A whole life and nothing to point at. That's the nightmare.",intensity:2,rarity:"signature",pol:{}},
{id:1595,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of exposure",desc:"Terrified someone will see what they really are.",example:"If they knew — properly knew — that'd be the end of it.",intensity:3,rarity:"signature",pol:{}},
{id:1596,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of powerlessness",desc:"Terrified of being unable to act.",example:"I won't be tied down again. Not ever.",intensity:2,rarity:"signature",pol:{}},
{id:1597,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of repetition",desc:"Terrified of becoming their parent or past self.",example:"I heard my father's voice come out of my mouth. I nearly stopped speaking.",intensity:3,rarity:"signature",pol:{}},
{id:1598,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of loss",desc:"Terrified of losing what they've built or love.",example:"Every good thing I've had, I've watched go.",intensity:3,rarity:"common",pol:{}},
{id:1599,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of being wrong",desc:"Terrified their core belief is a mistake.",example:"And if I've been wrong? All of it, for nothing?",intensity:3,rarity:"signature",pol:{}},
{id:1600,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of intimacy",desc:"Terrified of being genuinely known.",example:"Don't. Don't ask me that.",intensity:2,rarity:"signature",pol:{}},
{id:1601,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of failure",desc:"Terrified of trying fully and falling short.",example:"If I don't commit, it doesn't count when it collapses.",intensity:3,rarity:"common",pol:{}},
{id:1602,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of dependence",desc:"Terrified of needing anyone.",example:"I'll manage. I've always managed.",intensity:2,rarity:"signature",pol:{}},
{id:1603,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of chaos",desc:"Terrified of losing structure and control.",example:"There's an order. If the order goes, what's left?",intensity:3,rarity:"common",pol:{}},
{id:1604,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of harming others",desc:"Terrified of what they might do.",example:"Keep me away from it. I'm asking you to keep me away.",intensity:2,rarity:"signature",pol:{}},
{id:1605,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of being forgotten",desc:"Terrified of leaving no trace.",example:"Say my name sometimes. After. That's all.",intensity:2,rarity:"signature",pol:{}},
{id:1606,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of stagnation",desc:"Terrified of standing still.",example:"Another year the same. I'd rather be dead, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:1607,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Betrayed by kin",desc:"Family sold them out; trust in blood is broken.",example:"My own brother. So no — I don't much believe in family.",intensity:3,rarity:"signature",pol:{}},
{id:1608,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Abandoned young",desc:"Left behind by someone who should have stayed.",example:"She said back by dark. I waited three days.",intensity:3,rarity:"common",pol:{}},
{id:1609,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Publicly humiliated",desc:"Brought low in front of everyone who mattered.",example:"Everyone was there. That's the part that stays.",intensity:3,rarity:"signature",pol:{}},
{id:1610,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Failed to save someone",desc:"Was there and couldn't stop it.",example:"I was close enough to touch him.",intensity:2,rarity:"signature",pol:{}},
{id:1611,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Chronically overlooked",desc:"Grew up invisible in a crowded room.",example:"Nobody asked. Not once, in eighteen years.",intensity:3,rarity:"signature",pol:{}},
{id:1612,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Conditional love",desc:"Affection was always payment for performance.",example:"I was loved when I won. So I kept winning.",intensity:4,rarity:"signature",pol:{}},
{id:1613,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Exiled or cast out",desc:"Removed from the place that defined them.",example:"I don't have a home. I have a place I'm not allowed.",intensity:3,rarity:"signature",pol:{}},
{id:1614,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Blamed for something they didn't do",desc:"Carries a false guilt publicly.",example:"I stopped correcting people about it around year four.",intensity:2,rarity:"signature",pol:{}},
{id:1615,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Survived what others didn't",desc:"Alive by accident, and knows it.",example:"Why me. That's it. That's the whole question.",intensity:2,rarity:"signature",pol:{}},
{id:1616,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Broken promise",desc:"Someone's word failed them at the decisive moment.",example:"He swore. In front of witnesses, he swore.",intensity:3,rarity:"common",pol:{}},
{id:1617,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Physically harmed by a protector",desc:"Hurt by the person meant to keep them safe.",example:"(doesn't flinch at threats; flinches at kindness)",intensity:3,rarity:"signature",pol:{}},
{id:1618,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Poverty-marked",desc:"Formative deprivation that never fully left.",example:"I still count it. Even now. I can't not count it.",intensity:4,rarity:"signature",pol:{}},
{id:1619,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Talent squandered by others",desc:"Was capable and was prevented.",example:"I could have. They wouldn't let me. That's all.",intensity:2,rarity:"signature",pol:{}},
{id:1620,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Lost faith",desc:"A belief system collapsed and left nothing.",example:"I prayed properly. Really properly. Nothing came.",intensity:3,rarity:"common",pol:{}},
{id:1621,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I'm only worth what I produce'",desc:"Believes love must be earned through usefulness.",example:"If I stop being useful, why would anyone keep me?",intensity:3,rarity:"signature",pol:{}},
{id:1622,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Needing people is weakness'",desc:"Believes dependence is a fatal flaw.",example:"I don't need it. I've never needed it.",intensity:3,rarity:"signature",pol:{}},
{id:1623,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'If I'm perfect, I'm safe'",desc:"Believes flawlessness prevents harm.",example:"One mistake. That's all it takes. So: no mistakes.",intensity:2,rarity:"signature",pol:{}},
{id:1624,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I ruin what I touch'",desc:"Believes they are inherently destructive.",example:"Stay away from me. I'm doing you a kindness.",intensity:3,rarity:"signature",pol:{}},
{id:1625,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Nobody stays'",desc:"Believes all attachment ends in departure.",example:"Everyone leaves. It's just a question of when.",intensity:3,rarity:"common",pol:{}},
{id:1626,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I don't deserve good things'",desc:"Believes happiness is for other people.",example:"This isn't for me. It was never going to be for me.",intensity:2,rarity:"signature",pol:{}},
{id:1627,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Showing feeling gets you hurt'",desc:"Believes vulnerability invites attack.",example:"Never let them see it land.",intensity:2,rarity:"signature",pol:{}},
{id:1628,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'It's my fault'",desc:"Believes they caused a harm they didn't.",example:"If I'd been quicker. If I'd said something.",intensity:3,rarity:"common",pol:{}},
{id:1629,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Power is the only safety'",desc:"Believes only control prevents suffering.",example:"The strong don't get hurt. That's the whole lesson.",intensity:3,rarity:"signature",pol:{}},
{id:1630,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I'm fundamentally unlovable'",desc:"Believes affection shown to them is a mistake.",example:"You'll work it out eventually. They always do.",intensity:3,rarity:"signature",pol:{}},
{id:1631,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'The world is rigged'",desc:"Believes effort is pointless against the system.",example:"Why bother. It's decided before you start.",intensity:3,rarity:"signature",pol:{}},
{id:1632,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I must not want things'",desc:"Believes desire itself is dangerous.",example:"I don't want anything. Wanting's how they get you.",intensity:2,rarity:"signature",pol:{}},
{id:1633,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Verbal escalator",desc:"Meets pressure by raising the stakes of the argument.",example:"Oh, you want to do this properly? Let's do this properly.",intensity:3,rarity:"common",pol:{"asrt":1,"agr":-1}},
{id:1634,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Cold aggressor",desc:"Gets quieter and more precise as anger rises.",example:"(very evenly) Say the last part again.",intensity:2,rarity:"common",pol:{"asrt":1,"agr":-1}},
{id:1635,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Physical-first",desc:"Reaches for force before finishing the conversation.",example:"(already standing) We're past talking.",intensity:3,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1636,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Blame-thrower",desc:"Redirects pressure outward onto whoever's nearest.",example:"This is on you. All of this is on you.",intensity:3,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1637,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Cornered-vicious",desc:"Harmless until trapped, then goes for the throat.",example:"You shouldn't have shut the door.",intensity:3,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1638,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Preemptive striker",desc:"Attacks first on suspicion rather than waiting.",example:"I'd rather be wrong and early.",intensity:3,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1639,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Contempt-weaponizer",desc:"Uses withering dismissal as the primary weapon.",example:"You genuinely think that's an argument.",intensity:3,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1640,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Stubborn-immovable",desc:"Fights by refusing to move an inch.",example:"No. Ask again if you like. Still no.",intensity:2,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1641,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Ultimatum-thrower",desc:"Escalates straight to final terms.",example:"Then we're finished. Tonight.",intensity:2,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1642,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Truth-as-weapon",desc:"Deploys accurate, devastating facts to wound.",example:"Shall I tell them why you really left?",intensity:4,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1643,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Protective-fury",desc:"Only fights when someone else is threatened.",example:"Touch him and we'll find out what I am.",intensity:3,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1644,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Slow-burn detonator",desc:"Absorbs for a long time, then goes off catastrophically.",example:"(nine months of nothing, then everything at once)",intensity:4,rarity:"signature",pol:{"asrt":1,"agr":-1}},
{id:1645,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Physical leaver",desc:"Walks out mid-conversation when pressure rises.",example:"(door closes; no goodbye)",intensity:3,rarity:"common",pol:{"asrt":-1}},
{id:1646,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Subject-changer",desc:"Escapes by redirecting the topic every time.",example:"Anyway — did you sort the horses?",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1647,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Over-scheduler",desc:"Stays too busy to ever be caught by the problem.",example:"Can't. Booked. Try me next month.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1648,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Preemptive quitter",desc:"Leaves before they can be made to stay and face it.",example:"I'll save you the trouble. I'm out.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1649,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Geographic solver",desc:"Moves town rather than resolve anything.",example:"New place. Clean start. It's worked before.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1650,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Substance-retreater",desc:"Goes somewhere chemical when things get hard.",example:"(pours, doesn't stop pouring)",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1651,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Fantasy-escaper",desc:"Withdraws into imagined futures instead of the present.",example:"When this is over, I'll have a place by the water.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1652,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Ghost",desc:"Simply stops responding and disappears.",example:"(letters unanswered; no explanation, ever)",intensity:2,rarity:"common",pol:{"asrt":-1}},
{id:1653,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Work-burier",desc:"Buries the feeling under relentless task focus.",example:"There's plenty to do. Let's do it.",intensity:4,rarity:"signature",pol:{"asrt":-1}},
{id:1654,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Minimizer-then-exit",desc:"Downplays it, then removes themselves quietly.",example:"It's nothing. Honestly. (leaves)",intensity:2,rarity:"signature",pol:{"asrt":-1}},
{id:1655,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Humour-then-exit",desc:"Jokes until the pressure passes, then slips out.",example:"Tragic. Right — I'm going to bed.",intensity:3,rarity:"signature",pol:{"asrt":-1}},
{id:1656,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Peace-at-any-price",desc:"Concedes immediately to end the confrontation.",example:"You're right. Fine. You're right. Can we stop?",intensity:4,rarity:"signature",pol:{"asrt":-1}},
{id:1657,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Blank-shutdown",desc:"Goes entirely non-responsive under pressure.",example:"(stares; nothing comes)",intensity:5,rarity:"common",pol:{"ego":-1,"mood":-1}},
{id:1658,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Overwhelm-paralysis",desc:"Too many options, so takes none.",example:"I don't— I can't— give me a minute. Give me a minute.",intensity:2,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1659,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Dissociative drift",desc:"Present in body, gone somewhere else entirely.",example:"(nods at the wrong moments)",intensity:5,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1660,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Compulsive-detail retreat",desc:"Fixates on a tiny irrelevant task to avoid the big one.",example:"(rearranges the cups, precisely, twice)",intensity:3,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1661,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Silent-endurer",desc:"Absorbs everything without response until it stops.",example:"(takes it; says nothing; remembers all of it)",intensity:3,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1662,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Decision-deferrer",desc:"Kicks every choice down the road indefinitely.",example:"Let's decide tomorrow. Or not decide. Either.",intensity:3,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1663,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Play-dead",desc:"Goes deliberately small and unnoticeable.",example:"(makes themselves the least interesting thing in the room)",intensity:2,rarity:"common",pol:{"ego":-1,"mood":-1}},
{id:1664,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Rumination-lock",desc:"Replays the moment endlessly instead of acting.",example:"I keep going back over it. I can't get past it.",intensity:4,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1665,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Stalled-mid-sentence",desc:"Speech simply stops when the pressure lands.",example:"And then he— (nothing)",intensity:3,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1666,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Hyper-literal retreat",desc:"Answers only the narrow literal question to survive.",example:"You asked if I was there. I was there.",intensity:4,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1667,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Freeze-then-comply",desc:"Locks up, then does whatever is asked.",example:"...All right. Whatever you want.",intensity:2,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1668,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Numb-functional",desc:"Keeps working perfectly with nothing behind the eyes.",example:"Fine. What's next. (repeat, for weeks)",intensity:3,rarity:"signature",pol:{"ego":-1,"mood":-1}},
{id:1669,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Instant-apologizer",desc:"Apologizes reflexively regardless of fault.",example:"Sorry — sorry, that's my fault, sorry.",intensity:4,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1670,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Preference-eraser",desc:"Abandons own position the instant it's questioned.",example:"No, you're right, I hadn't thought of it that way.",intensity:4,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1671,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Flatterer-under-pressure",desc:"Praises the aggressor to defuse them.",example:"You've always been better at this than me. Truly.",intensity:2,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1672,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Anticipatory server",desc:"Preemptively does what the threat wants.",example:"(already fetching it before being asked)",intensity:3,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1673,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Blame-absorber",desc:"Takes on fault that isn't theirs to end the conflict.",example:"It was me. Let's just say it was me.",intensity:3,rarity:"common",pol:{"agr":1,"asrt":-1}},
{id:1674,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Peacemaker-compulsive",desc:"Cannot tolerate tension and rushes to smooth it.",example:"Everyone's tired, that's all. Let's eat.",intensity:4,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1675,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Over-explainer-appeaser",desc:"Justifies at length hoping to be excused.",example:"I only did it because — and I know how it sounds—",intensity:3,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1676,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Loyalty-pledger",desc:"Reassures the threat of devotion under pressure.",example:"I'm with you. You know I'm with you.",intensity:3,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1677,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Self-diminisher",desc:"Shrinks their own worth to seem non-threatening.",example:"I'm nobody. I'm not worth the trouble.",intensity:3,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1678,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Gift-and-favour",desc:"Buys peace with services and offerings.",example:"Let me — please — let me sort it for you.",intensity:2,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1679,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Mood-mirroring",desc:"Instantly adopts the emotional state of whoever's dominant.",example:"(furious when they're furious; calm when they calm)",intensity:4,rarity:"common",pol:{"agr":1,"asrt":-1}},
{id:1680,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Confession-offerer",desc:"Volunteers unrelated faults to satisfy the anger.",example:"And the other thing — I should tell you about that too.",intensity:3,rarity:"signature",pol:{"agr":1,"asrt":-1}},
{id:1681,section:"Social Role in a Group",category:"Leader",trait:"Natural commander",desc:"Assumes authority without being granted it.",example:"Right. Here's what we're doing.",intensity:3,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1682,section:"Social Role in a Group",category:"Leader",trait:"Reluctant leader",desc:"Leads only because nobody else will.",example:"Nobody? Fine. Fine, I'll do it.",intensity:2,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1683,section:"Social Role in a Group",category:"Leader",trait:"Consensus leader",desc:"Leads by getting everyone to agree first.",example:"Before I decide — I want to hear all four of you.",intensity:3,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1684,section:"Social Role in a Group",category:"Leader",trait:"Front-line leader",desc:"Leads by going first into the worst of it.",example:"Behind me. Stay behind me.",intensity:3,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1685,section:"Social Role in a Group",category:"Leader",trait:"Strategic director",desc:"Leads from the back, moving pieces.",example:"You take the south. Don't ask why yet.",intensity:2,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1686,section:"Social Role in a Group",category:"Leader",trait:"Charismatic rallier",desc:"Leads by making people want to follow.",example:"We do this and they'll talk about us for years.",intensity:2,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1687,section:"Social Role in a Group",category:"Leader",trait:"Authoritarian",desc:"Leads by command and expects no discussion.",example:"It wasn't a suggestion.",intensity:3,rarity:"common",pol:{"asrt":1,"ego":1}},
{id:1688,section:"Social Role in a Group",category:"Leader",trait:"Mentor-leader",desc:"Leads by developing whoever's under them.",example:"Wrong — but closer. Do it again.",intensity:3,rarity:"signature",pol:{"asrt":1,"ego":1}},
{id:1689,section:"Social Role in a Group",category:"Peacemaker",trait:"Mediator",desc:"Steps between opposing parties instinctively.",example:"Both of you. Sit. One at a time.",intensity:3,rarity:"common",pol:{"agr":1,"warm":1}},
{id:1690,section:"Social Role in a Group",category:"Peacemaker",trait:"Tension-diffuser",desc:"Breaks hostility with humour or redirection.",example:"Well, this is going marvellously. Anyone hungry?",intensity:3,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1691,section:"Social Role in a Group",category:"Peacemaker",trait:"Translator",desc:"Explains each side to the other in terms they'll accept.",example:"He's not saying you're wrong. He's saying he's frightened.",intensity:3,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1692,section:"Social Role in a Group",category:"Peacemaker",trait:"Compromise-architect",desc:"Builds the deal nobody loves but everyone accepts.",example:"Nobody gets what they want. Everyone gets enough.",intensity:3,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1693,section:"Social Role in a Group",category:"Peacemaker",trait:"Quiet stabilizer",desc:"Holds the group together without anyone noticing.",example:"(the reason it hasn't fallen apart, and nobody's said so)",intensity:2,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1694,section:"Social Role in a Group",category:"Peacemaker",trait:"Grudge-dissolver",desc:"Actively works to end old feuds.",example:"It was six years ago. Six. Let it go.",intensity:2,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1695,section:"Social Role in a Group",category:"Peacemaker",trait:"Emotional thermostat",desc:"Regulates the group's mood deliberately.",example:"Right — everyone outside. Ten minutes. Then we talk.",intensity:3,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1696,section:"Social Role in a Group",category:"Peacemaker",trait:"Conflict-absorber",desc:"Takes the blame or hit personally to end the fight.",example:"Blame me. It's easier. Move on.",intensity:3,rarity:"signature",pol:{"agr":1,"warm":1}},
{id:1697,section:"Social Role in a Group",category:"Instigator",trait:"Deliberate stirrer",desc:"Stirs things deliberately to see what happens.",example:"Go on — tell him what you told me.",intensity:3,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1698,section:"Social Role in a Group",category:"Instigator",trait:"Truth-detonator",desc:"Says the unsayable thing that blows the group open.",example:"Nobody's going to mention that he was there? No one?",intensity:3,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1699,section:"Social Role in a Group",category:"Instigator",trait:"Momentum-starter",desc:"Gets a stalled group moving by acting first.",example:"(walks in; everyone else follows because they have to)",intensity:3,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1700,section:"Social Role in a Group",category:"Instigator",trait:"Chaos-agent",desc:"Enjoys disruption for its own sake.",example:"It was boring. Now it isn't.",intensity:2,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1701,section:"Social Role in a Group",category:"Instigator",trait:"Devil's advocate",desc:"Argues the opposing case to force examination.",example:"Let's say he's telling the truth. Then what?",intensity:3,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1702,section:"Social Role in a Group",category:"Instigator",trait:"Escalator",desc:"Turns small disagreements into decisive confrontations.",example:"No, let's actually have this out.",intensity:2,rarity:"common",pol:{"rebel":1,"agr":-1}},
{id:1703,section:"Social Role in a Group",category:"Instigator",trait:"Risk-proposer",desc:"Always pushing for the bolder option.",example:"Or — hear me out — we do the stupid thing.",intensity:3,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1704,section:"Social Role in a Group",category:"Instigator",trait:"Boundary-pusher",desc:"Tests what the group will actually tolerate.",example:"And if I did? What would anyone actually do?",intensity:3,rarity:"signature",pol:{"rebel":1,"agr":-1}},
{id:1705,section:"Social Role in a Group",category:"Outsider",trait:"Deliberate loner",desc:"Chooses distance from the group by preference.",example:"I work better on my own. Always have.",intensity:3,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1706,section:"Social Role in a Group",category:"Outsider",trait:"Newcomer",desc:"Never quite absorbed into the established group.",example:"You all have history. I've been here four months.",intensity:4,rarity:"common",pol:{"warm":-1,"rebel":1}},
{id:1707,section:"Social Role in a Group",category:"Outsider",trait:"Rejected member",desc:"Was inside once and was pushed out.",example:"I know how this room works. I built half of it.",intensity:2,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1708,section:"Social Role in a Group",category:"Outsider",trait:"Cultural outsider",desc:"Different background makes them permanently other.",example:"Where I'm from, that would be an insult. Here, apparently not.",intensity:4,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1709,section:"Social Role in a Group",category:"Outsider",trait:"Observer",desc:"Watches the group without participating.",example:"(says nothing for an hour; then says the one thing that matters)",intensity:3,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1710,section:"Social Role in a Group",category:"Outsider",trait:"Moral outsider",desc:"Held apart by refusing something the group accepts.",example:"You all made your peace with it. I didn't.",intensity:3,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1711,section:"Social Role in a Group",category:"Outsider",trait:"Secret-holder",desc:"Distanced by knowing something the others don't.",example:"(can't join in; knows why the plan won't work)",intensity:3,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1712,section:"Social Role in a Group",category:"Outsider",trait:"Reluctant returnee",desc:"Back in the group but no longer of it.",example:"I'm here. I'm not staying.",intensity:2,rarity:"signature",pol:{"warm":-1,"rebel":1}},
{id:1713,section:"Social Role in a Group",category:"Caretaker",trait:"Provider",desc:"Ensures everyone's practical needs are met.",example:"Eat. All of you. Now, before we talk.",intensity:3,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1714,section:"Social Role in a Group",category:"Caretaker",trait:"Emotional caretaker",desc:"Tracks and tends everyone's feelings.",example:"You've been quiet since Tuesday. What's happened?",intensity:2,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1715,section:"Social Role in a Group",category:"Caretaker",trait:"Protector",desc:"Physically places themselves between danger and others.",example:"(steps in front, without discussion)",intensity:3,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1716,section:"Social Role in a Group",category:"Caretaker",trait:"Fixer",desc:"Solves everyone's problems, invited or not.",example:"I've dealt with it. You don't need to worry.",intensity:3,rarity:"common",pol:{"warm":1,"emo":1}},
{id:1717,section:"Social Role in a Group",category:"Caretaker",trait:"Nurse-role",desc:"Takes on the group's injuries and illnesses.",example:"Sit down and let me see it.",intensity:3,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1718,section:"Social Role in a Group",category:"Caretaker",trait:"Burden-bearer",desc:"Carries the group's worst tasks so others don't.",example:"I'll do it. No — I'll do it.",intensity:3,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1719,section:"Social Role in a Group",category:"Caretaker",trait:"Institutional memory",desc:"Keeps the group's history, names, and obligations.",example:"We owe the miller. Since the winter. Nobody else remembers.",intensity:3,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1720,section:"Social Role in a Group",category:"Caretaker",trait:"Over-functioner",desc:"Does so much for others they erase themselves.",example:"I'm fine. I'm always fine. Who else needs something?",intensity:3,rarity:"signature",pol:{"warm":1,"emo":1}},
{id:1721,section:"Social Role in a Group",category:"Skeptic",trait:"Devil's auditor",desc:"Checks every plan for the flaw nobody wants to see.",example:"Walk me through step four again.",intensity:3,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1722,section:"Social Role in a Group",category:"Skeptic",trait:"Trust-withholder",desc:"Extends confidence slowly and conditionally.",example:"I've known him a year. I'd give him a knife, not my back.",intensity:3,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1723,section:"Social Role in a Group",category:"Skeptic",trait:"Doom-forecaster",desc:"Names the worst-case scenario out loud, always.",example:"And when the bridge is watched? What then?",intensity:4,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1724,section:"Social Role in a Group",category:"Skeptic",trait:"Evidence-demander",desc:"Refuses to act on assertion alone.",example:"Who saw it? Show me.",intensity:2,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1725,section:"Social Role in a Group",category:"Skeptic",trait:"Cynical veteran",desc:"Has watched this exact plan fail before.",example:"We tried this in '09. Ask me how it went.",intensity:3,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1726,section:"Social Role in a Group",category:"Skeptic",trait:"Quiet doubter",desc:"Goes along while privately expecting failure.",example:"(nods; makes a private contingency anyway)",intensity:2,rarity:"common",pol:{"intel":1,"pos":-1}},
{id:1727,section:"Social Role in a Group",category:"Skeptic",trait:"Motive-questioner",desc:"Asks why each person actually wants this.",example:"What do you get out of it? Genuinely.",intensity:3,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1728,section:"Social Role in a Group",category:"Skeptic",trait:"Rule-checker",desc:"Tests plans against constraints everyone's ignoring.",example:"That's lovely. It's also illegal in three counties.",intensity:3,rarity:"signature",pol:{"intel":1,"pos":-1}},
{id:1729,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Absolute code",desc:"Holds rules that do not bend for anyone, including themselves.",example:"I don't care whose son he is. Same rule.",intensity:4,rarity:"common",pol:{"disc":1,"hon":1}},
{id:1730,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Oath-bound",desc:"A given word is binding regardless of cost.",example:"I swore it. That's the beginning and end.",intensity:3,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1731,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Incorruptible",desc:"Cannot be bought at any price.",example:"You've misjudged what I'm for.",intensity:2,rarity:"common",pol:{"disc":1,"hon":1}},
{id:1732,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Law-above-loyalty",desc:"Will report or oppose a friend on principle.",example:"I love you. I'm still going to say what I saw.",intensity:3,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1733,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Truth-absolutist",desc:"Refuses to lie even to prevent harm.",example:"She'll be destroyed by it. I'm still not lying to her.",intensity:2,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1734,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Non-violent absolute",desc:"Will not use force under any circumstance.",example:"Then I'll be beaten. I won't hit him.",intensity:4,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1735,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Duty-first",desc:"Obligation outranks personal desire, always.",example:"What I want doesn't come into it.",intensity:4,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1736,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Consistency-obsessed",desc:"Applies the same standard everywhere, painfully.",example:"If it was wrong then, it's wrong now. Including when I did it.",intensity:3,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1737,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Martyrdom-willing",desc:"Will accept ruin rather than compromise.",example:"Let them take it all. They can't take the reason.",intensity:4,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1738,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Publicly accountable",desc:"Insists on being judged by their own stated standard.",example:"Hold me to it. Out loud. In front of them.",intensity:3,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1739,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Sanctity-holder",desc:"Treats certain things as absolutely not for trade.",example:"Some things aren't currency. That's one of them.",intensity:4,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1740,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Refuses complicity",desc:"Will not participate in a wrong even passively.",example:"I'm not signing. I'm not standing near it.",intensity:3,rarity:"signature",pol:{"disc":1,"hon":1}},
{id:1741,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Ends-justify",desc:"Accepts dirty methods for outcomes they believe in.",example:"It worked. We can be sick about it after.",intensity:3,rarity:"common",pol:{"hon":-1,"intel":1}},
{id:1742,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Situational ethics",desc:"Judges each case on its own circumstances.",example:"Different situation. Different answer.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1743,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Lesser-evil chooser",desc:"Picks the least-bad option without agonizing.",example:"Neither is good. One is worse. Done.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1744,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Negotiable principles",desc:"Holds values that bend under sufficient weight.",example:"Everything's got a number. Mine's just high.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1745,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Result-auditor",desc:"Only cares whether it worked, not how it looked.",example:"Is he alive? Then it was the right call.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1746,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Rule-as-guideline",desc:"Treats laws as advisory rather than binding.",example:"The rule assumes a normal week. This isn't one.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1747,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Cost-benefit moralist",desc:"Weighs harm arithmetically.",example:"Four instead of forty. I can carry four.",intensity:2,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1748,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Deniability-conscious",desc:"Does the necessary thing while staying formally clean.",example:"I didn't tell you to. I told you the problem.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1749,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Adaptive loyalty",desc:"Shifts allegiance as circumstances change.",example:"I was with him when it made sense. It stopped making sense.",intensity:3,rarity:"common",pol:{"hon":-1,"intel":1}},
{id:1750,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Future-discounting",desc:"Accepts long-term cost for immediate survival.",example:"We won't have a next year if we don't get through this one.",intensity:4,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1751,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Necessary-harm accepter",desc:"Can do damage and sleep afterward.",example:"It needed doing. It got done.",intensity:2,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1752,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Compromise-comfortable",desc:"Sees purity as a luxury of the uninvolved.",example:"People who've never had to choose have wonderful principles.",intensity:3,rarity:"signature",pol:{"hon":-1,"intel":1}},
{id:1753,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Person-over-principle",desc:"Will break any rule for a specific person.",example:"Right and wrong are for other people's families.",intensity:3,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1754,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Clan-first",desc:"Kin and crew before outsiders, always.",example:"Ours first. Then we'll see.",intensity:3,rarity:"common",pol:{"warm":1,"agr":1}},
{id:1755,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Debt-honouring",desc:"Repays obligations with absolute reliability.",example:"He fed me for a winter. So: whatever he asks.",intensity:4,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1756,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Betrayal-unforgiving",desc:"One breach ends the relationship permanently.",example:"There isn't a road back from that. There just isn't.",intensity:4,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1757,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Chain-of-command loyal",desc:"Follows the person, not the institution.",example:"I don't serve the office. I serve him.",intensity:3,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1758,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Protective-partisan",desc:"Defends their people even when they're wrong.",example:"He's wrong. He's also mine. Say the next part carefully.",intensity:3,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1759,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Silence-keeper",desc:"Will take punishment rather than inform.",example:"I don't know anything. I'll keep not knowing.",intensity:3,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1760,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Reciprocity-strict",desc:"Tracks favours given and owed precisely.",example:"That's twice now. I'm counting, and so should you.",intensity:3,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1761,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Sworn-brotherhood",desc:"Treats chosen bonds as more binding than blood.",example:"We decided to be family. That's stronger, not weaker.",intensity:3,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1762,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Legacy-loyal",desc:"Honours commitments made by predecessors.",example:"My father promised it. So it's promised.",intensity:3,rarity:"common",pol:{"warm":1,"agr":1}},
{id:1763,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Loyal-to-a-fault",desc:"Stays past the point of self-harm.",example:"I know what he is. I'm still not leaving.",intensity:2,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1764,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Conditional-but-total",desc:"Slow to commit, absolute once committed.",example:"Took me four years to decide about you. Now it's decided.",intensity:5,rarity:"signature",pol:{"warm":1,"agr":1}},
{id:1765,section:"Values & Moral Line",category:"Self-Interested",trait:"Transactional",desc:"Every relationship is an exchange with terms.",example:"What's in it for me? Genuine question.",intensity:3,rarity:"common",pol:{"warm":-1,"hon":-1}},
{id:1766,section:"Values & Moral Line",category:"Self-Interested",trait:"Survival-first",desc:"Own continuation outranks every other value.",example:"I'd like to be noble. I'd like more to be alive.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1767,section:"Values & Moral Line",category:"Self-Interested",trait:"Opportunist",desc:"Adjusts position to whatever benefits them now.",example:"The wind changed. So did I.",intensity:3,rarity:"common",pol:{"warm":-1,"hon":-1}},
{id:1768,section:"Values & Moral Line",category:"Self-Interested",trait:"Comfort-preserving",desc:"Won't risk their own ease for a principle.",example:"It's terrible. It's also not my problem.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1769,section:"Values & Moral Line",category:"Self-Interested",trait:"Reputation-managing",desc:"Moral choices are made for how they'll look.",example:"It's not about right. It's about what gets said afterward.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1770,section:"Values & Moral Line",category:"Self-Interested",trait:"Debt-avoider",desc:"Refuses obligations that could later bind them.",example:"Don't do me favours. I don't want to owe you.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1771,section:"Values & Moral Line",category:"Self-Interested",trait:"Quiet-defector",desc:"Abandons the group at the decisive moment.",example:"(gone by morning; horse gone too)",intensity:2,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1772,section:"Values & Moral Line",category:"Self-Interested",trait:"Profit-oriented",desc:"Evaluates moral questions financially.",example:"And what does conscience pay, exactly?",intensity:2,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1773,section:"Values & Moral Line",category:"Self-Interested",trait:"Self-exempting",desc:"Applies standards to others, not themselves.",example:"That's different. That was completely different.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1774,section:"Values & Moral Line",category:"Self-Interested",trait:"Loyalty-for-hire",desc:"Genuinely loyal for exactly as long as paid.",example:"You've got me till the money stops. Fair terms.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1775,section:"Values & Moral Line",category:"Self-Interested",trait:"Blame-shifting",desc:"Reflexively relocates fault away from themselves.",example:"I was given bad information. That's the real failure.",intensity:4,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1776,section:"Values & Moral Line",category:"Self-Interested",trait:"Ruthless-when-cornered",desc:"Will sacrifice anyone to save themselves.",example:"One of us walks out. I've decided which.",intensity:3,rarity:"signature",pol:{"warm":-1,"hon":-1}},
{id:1777,section:"Attachment & Intimacy Style",category:"Secure",trait:"Steady-attached",desc:"Comfortable with closeness and with distance.",example:"Go. I'll be here when you're back.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1778,section:"Attachment & Intimacy Style",category:"Secure",trait:"Direct-needs",desc:"States what they need without drama or apology.",example:"I need you to actually listen for two minutes.",intensity:3,rarity:"common",pol:{"ego":1,"emo":1}},
{id:1779,section:"Attachment & Intimacy Style",category:"Secure",trait:"Repair-oriented",desc:"Returns to fix a rupture rather than let it fester.",example:"That went badly last night. Can we do it again properly?",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1780,section:"Attachment & Intimacy Style",category:"Secure",trait:"Trusting-but-alert",desc:"Extends trust readily, updates on evidence.",example:"I believed him. I was wrong. That's on the evidence, not on trusting.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1781,section:"Attachment & Intimacy Style",category:"Secure",trait:"Comfortable alone",desc:"Content in solitude without reading it as rejection.",example:"I like the quiet. It's not a statement about you.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1782,section:"Attachment & Intimacy Style",category:"Secure",trait:"Boundary-clear",desc:"Says no without guilt and hears no without injury.",example:"I can't do that one. Ask me the next thing.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1783,section:"Attachment & Intimacy Style",category:"Secure",trait:"Emotionally available",desc:"Present for others' feelings without being swamped.",example:"I'm not going anywhere. Take your time.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1784,section:"Attachment & Intimacy Style",category:"Secure",trait:"Conflict-tolerant",desc:"Can argue without the relationship feeling endangered.",example:"We disagree. That's all this is.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1785,section:"Attachment & Intimacy Style",category:"Secure",trait:"Consistent",desc:"Behaves the same whether things are good or bad.",example:"(same person on the worst day as the best)",intensity:3,rarity:"common",pol:{"ego":1,"emo":1}},
{id:1786,section:"Attachment & Intimacy Style",category:"Secure",trait:"Generous-interpreter",desc:"Assumes good intent while still checking.",example:"I don't think he meant it that way. I'll ask him.",intensity:3,rarity:"signature",pol:{"ego":1,"emo":1}},
{id:1787,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Reassurance-seeking",desc:"Needs frequent confirmation the bond holds.",example:"We're all right, aren't we? You'd say if we weren't.",intensity:3,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1788,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Hypervigilant to tone",desc:"Reads catastrophe into small shifts in warmth.",example:"You said it differently. You did — you said it differently.",intensity:4,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1789,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Protest-behaviour",desc:"Escalates to provoke a response when feeling unseen.",example:"Fine. Ignore me then. That's clearly what's happening.",intensity:3,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1790,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Fear-of-replacement",desc:"Constantly compares self to others in the person's life.",example:"You saw her Tuesday. You didn't mention it.",intensity:4,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1791,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Over-giving",desc:"Gives excessively to secure the bond.",example:"(does far too much, then resents it, then does more)",intensity:3,rarity:"common",pol:{"ego":-1,"emo":1}},
{id:1792,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Rumination-after-contact",desc:"Replays every conversation looking for signs.",example:"When he said 'sure' — what do you think he meant by that?",intensity:3,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1793,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Merge-seeking",desc:"Wants total closeness with no separateness.",example:"Why can't I come? I don't understand why I can't come.",intensity:3,rarity:"common",pol:{"ego":-1,"emo":1}},
{id:1794,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Apology-flooding",desc:"Over-apologizes to repair imagined damage.",example:"I'm sorry — was that too much? I'm sorry.",intensity:3,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1795,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Abandonment-scanning",desc:"Watches constantly for signs of leaving.",example:"You've packed a bag. Why have you packed a bag?",intensity:4,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1796,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Difficulty being alone",desc:"Solitude reads as rejection rather than rest.",example:"I'll come with you. I don't want to be here on my own.",intensity:3,rarity:"signature",pol:{"ego":-1,"emo":1}},
{id:1797,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Distance-restorer",desc:"Pulls away the moment closeness intensifies.",example:"(warm all evening; unreachable for a week after)",intensity:3,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1798,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Self-sufficiency-armoured",desc:"Refuses help as a matter of identity.",example:"I've got it. I said I've got it.",intensity:2,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1799,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Emotion-deflector",desc:"Redirects any conversation about feeling.",example:"Let's not do the talking-about-it thing.",intensity:3,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1800,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Intimacy-postponer",desc:"Always has a reason it isn't the right time.",example:"After this is over. We'll talk about it then.",intensity:4,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1801,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Flaw-focusing",desc:"Finds faults in a partner when closeness grows.",example:"She chews loudly. I know how that sounds.",intensity:3,rarity:"common",pol:{"emo":-1,"warm":-1}},
{id:1802,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Independence-guarding",desc:"Treats commitment as loss of self.",example:"I'm not built for that. I've told you.",intensity:2,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1803,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Physically-present, absent",desc:"Shares space but not interior life.",example:"(sits with them every night; says nothing real in years)",intensity:2,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1804,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Devaluing-under-pressure",desc:"Diminishes the relationship's importance when threatened.",example:"It was never that serious. Let's not rewrite it.",intensity:3,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1805,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Escape-hatch keeper",desc:"Always maintains a way out of any bond.",example:"(never fully unpacks; never gives up the other lease)",intensity:3,rarity:"signature",pol:{"emo":-1,"warm":-1}},
{id:1806,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Slow-disclosing",desc:"Reveals personal information at a glacial rate.",example:"You've known me nine years. You know four things.",intensity:3,rarity:"common",pol:{"emo":-1,"warm":-1}},
{id:1807,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Push-pull",desc:"Pursues closeness intensely, then flees it.",example:"Don't go. — No, actually, go. Go.",intensity:3,rarity:"common",pol:{"mood":-1,"disc":-1}},
{id:1808,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Fear-of-the-loved",desc:"Experiences the loved one as both safety and threat.",example:"(reaches for them and flinches in the same motion)",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1809,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Unpredictable-warmth",desc:"Affection arrives and vanishes without visible cause.",example:"(adoring on Monday; a stranger by Thursday)",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1810,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Test-and-punish",desc:"Sets loyalty tests, then punishes the outcome either way.",example:"You came. Why did you come? What do you want?",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1811,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Self-sabotaging",desc:"Destroys the bond as it becomes secure.",example:"It was going too well. So I did what I do.",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1812,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Dissociating-in-closeness",desc:"Goes absent during moments of real intimacy.",example:"(present, then somewhere else entirely, mid-sentence)",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1813,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Extreme-idealizing",desc:"Swings between worship and contempt of the same person.",example:"You're the only good thing. — You're exactly like the rest of them.",intensity:4,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1814,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Trust-then-suspicion",desc:"Grants total trust, then retroactively doubts everything.",example:"I told you everything. I shouldn't have told you anything.",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1815,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Crisis-bonded",desc:"Only feels connected during emergency or catastrophe.",example:"We were fine when it was bad. It's the calm I can't do.",intensity:4,rarity:"common",pol:{"mood":-1,"disc":-1}},
{id:1816,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Apology-and-repeat",desc:"Genuinely remorseful, reliably repeats the harm.",example:"I meant it when I said it. I always mean it.",intensity:3,rarity:"signature",pol:{"mood":-1,"disc":-1}},
{id:1817,section:"Humor Style",category:"Dry & Deadpan",trait:"Straight-faced absurdist",desc:"Delivers ridiculous statements with total sincerity.",example:"We've lost the horse, the map, and morale. Good progress.",intensity:3,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1818,section:"Humor Style",category:"Dry & Deadpan",trait:"Understated-catastrophic",desc:"Describes disaster in mild terms for comic effect.",example:"Mild setback. Everyone's on fire.",intensity:2,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1819,section:"Humor Style",category:"Dry & Deadpan",trait:"Timing-perfect",desc:"Waits exactly long enough before the line lands.",example:"...(beat)... Well, that's the bridge, then.",intensity:3,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1820,section:"Humor Style",category:"Dry & Deadpan",trait:"Never-laughs-own-joke",desc:"Delivers and moves on without acknowledgment.",example:"(says the funniest thing in the room; doesn't blink)",intensity:4,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1821,section:"Humor Style",category:"Dry & Deadpan",trait:"Literal-minded gag",desc:"Comedy from answering exactly what was asked.",example:"'Can you swim?' — 'Yes.' (does not move)",intensity:3,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1822,section:"Humor Style",category:"Dry & Deadpan",trait:"Weary-wit",desc:"Humour born of long exhaustion.",example:"Oh good. A new problem. I'd grown attached to the old ones.",intensity:2,rarity:"common",pol:{"intel":1,"emo":-1}},
{id:1823,section:"Humor Style",category:"Dry & Deadpan",trait:"Precision-mocker",desc:"Corrects tiny details for comic pedantry.",example:"Two hundred, not thousands. Let's not lose the plot.",intensity:2,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1824,section:"Humor Style",category:"Dry & Deadpan",trait:"Bone-dry observer",desc:"Notes the absurd without commentary.",example:"He's brought a chicken. To a siege.",intensity:2,rarity:"signature",pol:{"intel":1,"emo":-1}},
{id:1825,section:"Humor Style",category:"Self-Deprecating",trait:"Own-worst-critic",desc:"Jokes primarily at their own expense.",example:"I have the survival instincts of a lit candle.",intensity:2,rarity:"signature",pol:{"ego":-1}},
{id:1826,section:"Humor Style",category:"Self-Deprecating",trait:"Preemptive-mocker",desc:"Insults themselves before anyone else can.",example:"Yes, yes — useless. We've established it. Move on.",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1827,section:"Humor Style",category:"Self-Deprecating",trait:"Failure-collector",desc:"Tells stories of their own disasters for laughs.",example:"Have I told you about the goat? No? Sit down.",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1828,section:"Humor Style",category:"Self-Deprecating",trait:"Charm-through-flaw",desc:"Uses admitted weakness to build warmth.",example:"I'm no good at this bit. You'll have to be patient.",intensity:2,rarity:"signature",pol:{"ego":-1}},
{id:1829,section:"Humor Style",category:"Self-Deprecating",trait:"Deflecting-humble",desc:"Turns compliments into jokes to avoid them.",example:"Well, a broken clock, and so on.",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1830,section:"Humor Style",category:"Self-Deprecating",trait:"Gallows-self",desc:"Jokes about their own mortality or ruin.",example:"At least the funeral'll be cheap. Nobody'll come.",intensity:4,rarity:"common",pol:{"ego":-1}},
{id:1831,section:"Humor Style",category:"Self-Deprecating",trait:"Underdog-comic",desc:"Comedy from being visibly outmatched.",example:"Terrific. Me against six. I like the odds — for them.",intensity:2,rarity:"signature",pol:{"ego":-1}},
{id:1832,section:"Humor Style",category:"Self-Deprecating",trait:"Apologetic-funny",desc:"Humour wrapped in genuine embarrassment.",example:"Sorry — I've done it again, haven't I. I always do it.",intensity:3,rarity:"signature",pol:{"ego":-1}},
{id:1833,section:"Humor Style",category:"Cruel & Barbed",trait:"Precision-insulter",desc:"Finds the exact wound and jokes about it.",example:"How's the leg? Sorry — how's the limp?",intensity:3,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1834,section:"Humor Style",category:"Cruel & Barbed",trait:"Public-humiliator",desc:"Jokes designed to diminish someone in front of others.",example:"Tell everyone what you thought the plan was. Go on.",intensity:3,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1835,section:"Humor Style",category:"Cruel & Barbed",trait:"Mock-affectionate",desc:"Cruelty disguised as friendly teasing.",example:"Oh, we love him. He's like a dog that can nearly talk.",intensity:2,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1836,section:"Humor Style",category:"Cruel & Barbed",trait:"Superiority-comic",desc:"Humour built on being cleverer than the target.",example:"It's remarkable, watching you arrive at it.",intensity:3,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1837,section:"Humor Style",category:"Cruel & Barbed",trait:"Weaponized-nickname",desc:"Assigns names that stick and wound.",example:"Morning, Lucky. (the man is famously not lucky)",intensity:2,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1838,section:"Humor Style",category:"Cruel & Barbed",trait:"Schadenfreude",desc:"Genuinely delighted by others' misfortune.",example:"(laughing) He fell IN? He actually fell IN?",intensity:2,rarity:"common",pol:{"warm":-1,"agr":-1}},
{id:1839,section:"Humor Style",category:"Cruel & Barbed",trait:"Sneering-dismissal",desc:"Comedy as a tool of contempt.",example:"Sweet. Genuinely sweet, that you thought so.",intensity:2,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1840,section:"Humor Style",category:"Cruel & Barbed",trait:"Truth-barbed",desc:"Jokes that are funny because they're devastatingly accurate.",example:"Say the toast. The one about family. Go on, say it.",intensity:4,rarity:"signature",pol:{"warm":-1,"agr":-1}},
{id:1841,section:"Humor Style",category:"Warm & Playful",trait:"Inclusive-joker",desc:"Humour that brings everyone into the joke.",example:"No, no — we're all idiots here. Equal footing.",intensity:3,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1842,section:"Humor Style",category:"Warm & Playful",trait:"Affectionate-teaser",desc:"Teases as a form of open fondness.",example:"Look at you. Combed and everything.",intensity:2,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1843,section:"Humor Style",category:"Warm & Playful",trait:"Silly-willing",desc:"Happy to be undignified for a laugh.",example:"(does the voice; commits fully; regrets nothing)",intensity:2,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1844,section:"Humor Style",category:"Warm & Playful",trait:"Mood-lifter",desc:"Uses humour deliberately to raise the room.",example:"Right — one joke, then we can go back to despair.",intensity:3,rarity:"common",pol:{"warm":1,"pos":1}},
{id:1845,section:"Humor Style",category:"Warm & Playful",trait:"Delight-prone",desc:"Laughs easily and genuinely at others' jokes.",example:"(laughs first, loudest, and honestly)",intensity:3,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1846,section:"Humor Style",category:"Warm & Playful",trait:"Story-comic",desc:"Comedy through long, warm, well-told anecdotes.",example:"So — and this is true — the innkeeper had three sons—",intensity:3,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1847,section:"Humor Style",category:"Warm & Playful",trait:"Wordplay-fond",desc:"Enjoys puns and verbal games without shame.",example:"Groan all you like. I stand by it.",intensity:3,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1848,section:"Humor Style",category:"Warm & Playful",trait:"Gentle-absurd",desc:"Whimsical rather than sharp.",example:"I've decided the goose is in charge now. It's earned it.",intensity:2,rarity:"signature",pol:{"warm":1,"pos":1}},
{id:1849,section:"Humor Style",category:"Absurd & Chaotic",trait:"Non-sequitur artist",desc:"Comedy from wildly unrelated leaps.",example:"Anyway — do you think fish know it's raining?",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1850,section:"Humor Style",category:"Absurd & Chaotic",trait:"Escalating-nonsense",desc:"Builds a ridiculous premise higher and higher.",example:"And by the fourth bishop, obviously, the boat was on fire.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1851,section:"Humor Style",category:"Absurd & Chaotic",trait:"Commitment-to-bit",desc:"Sustains a ridiculous joke long past reason.",example:"(still speaking in the accent, forty minutes later)",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1852,section:"Humor Style",category:"Absurd & Chaotic",trait:"Anarchic-timing",desc:"Jokes at the least appropriate possible moment.",example:"(at the funeral) Well. He'd have hated this.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1853,section:"Humor Style",category:"Absurd & Chaotic",trait:"Surreal-imagery",desc:"Comedy from bizarre mental pictures.",example:"He looked like a wardrobe having a religious experience.",intensity:2,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1854,section:"Humor Style",category:"Absurd & Chaotic",trait:"Rule-breaking comic",desc:"Funny specifically because it violates the setting.",example:"(mid-negotiation) I've brought snacks.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1855,section:"Humor Style",category:"Absurd & Chaotic",trait:"Physical-chaos",desc:"Slapstick and bodily comedy.",example:"(falls; makes it worse; makes it worse again)",intensity:2,rarity:"common",pol:{"disc":-1,"rebel":1}},
{id:1856,section:"Humor Style",category:"Absurd & Chaotic",trait:"Unpredictable-turn",desc:"Sets up one joke and lands somewhere else entirely.",example:"—and that's when I realised I'd married the wrong brother.",intensity:5,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1857,section:"Humor Style",category:"Humorless & Absent",trait:"Joke-blind",desc:"Doesn't recognize humour as humour.",example:"Why is that funny? Explain the funny part.",intensity:2,rarity:"common",pol:{"pos":-1,"disc":1}},
{id:1858,section:"Humor Style",category:"Humorless & Absent",trait:"Literalist-response",desc:"Answers jokes as if they were sincere questions.",example:"'Could eat a horse.' — 'There's no horse. There's soup.'",intensity:3,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1859,section:"Humor Style",category:"Humorless & Absent",trait:"Disapproving-of-levity",desc:"Treats humour as inappropriate or disrespectful.",example:"People died. And you're making jokes.",intensity:3,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1860,section:"Humor Style",category:"Humorless & Absent",trait:"Grim-focus",desc:"Too task-oriented to register comedy.",example:"Is any of this relevant to the gate?",intensity:2,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1861,section:"Humor Style",category:"Humorless & Absent",trait:"Delayed-comprehension",desc:"Gets the joke long after the moment passes.",example:"(twenty minutes later) Oh. Because of the boat.",intensity:3,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1862,section:"Humor Style",category:"Humorless & Absent",trait:"Polite-nonlaugher",desc:"Recognizes jokes intellectually, doesn't find them funny.",example:"(small nod) Yes. That's a joke.",intensity:3,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1863,section:"Humor Style",category:"Humorless & Absent",trait:"Humour-suspicious",desc:"Assumes jokes are mockery aimed at them.",example:"Was that about me? That was about me.",intensity:3,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1864,section:"Humor Style",category:"Humorless & Absent",trait:"Earnest-always",desc:"Sincere to the point of comedy without meaning to be.",example:"(is the joke; will never know)",intensity:4,rarity:"signature",pol:{"pos":-1,"disc":1}},
{id:1865,section:"Habits & Vices",category:"Substance & Consumption",trait:"Functional drinker",desc:"Drinks steadily all day and never appears drunk.",example:"(third cup before noon; hand perfectly steady)",intensity:4,rarity:"common",pol:{"disc":-1,"mood":-1}},
{id:1866,section:"Habits & Vices",category:"Substance & Consumption",trait:"Binge-and-abstain",desc:"Long dry stretches broken by catastrophic nights.",example:"Four months. Four months and then Tuesday happened.",intensity:4,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1867,section:"Habits & Vices",category:"Substance & Consumption",trait:"Smoke-anchored",desc:"Structures the day around tobacco or pipe breaks.",example:"Give me five minutes. (always five minutes)",intensity:3,rarity:"common",pol:{"disc":-1,"mood":-1}},
{id:1868,section:"Habits & Vices",category:"Substance & Consumption",trait:"Secret-drinker",desc:"Hides consumption carefully from everyone.",example:"(bottle behind the loose brick; nobody knows)",intensity:2,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1869,section:"Habits & Vices",category:"Substance & Consumption",trait:"Social-only excess",desc:"Moderate alone, immoderate in company.",example:"I'm fine on my own. It's the company that does it.",intensity:2,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1870,section:"Habits & Vices",category:"Substance & Consumption",trait:"Appetite-driven",desc:"Relationship with food is the emotional outlet.",example:"(eats when frightened; eats more when frightened again)",intensity:3,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1871,section:"Habits & Vices",category:"Substance & Consumption",trait:"Stimulant-dependent",desc:"Needs something to function at baseline.",example:"Not before the tea. I'm not a person before the tea.",intensity:3,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1872,section:"Habits & Vices",category:"Substance & Consumption",trait:"Ascetic-lapsing",desc:"Denies themselves rigidly, then breaks spectacularly.",example:"I don't. I never. (does, spectacularly)",intensity:4,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1873,section:"Habits & Vices",category:"Substance & Consumption",trait:"Poison-tolerant",desc:"Consumes more than should be survivable.",example:"That's my fourth. It's fine. It's genuinely fine.",intensity:3,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1874,section:"Habits & Vices",category:"Substance & Consumption",trait:"Quitting-perpetually",desc:"Always in the process of stopping, never stopped.",example:"Last one. I mean it this time.",intensity:5,rarity:"signature",pol:{"disc":-1,"mood":-1}},
{id:1875,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Counting-compulsive",desc:"Counts objects, steps, or repetitions constantly.",example:"(seventeen. always seventeen before the door)",intensity:5,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1876,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Checking-ritual",desc:"Repeatedly verifies locks, weapons, or documents.",example:"(checks the lock; walks away; comes back; checks the lock)",intensity:3,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1877,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Order-compulsive",desc:"Cannot rest until objects are correctly arranged.",example:"(straightens it; straightens it again; can now speak)",intensity:4,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1878,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Superstitious-ritual",desc:"Performs private rituals for luck or safety.",example:"Not through that door. Never through that door.",intensity:3,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1879,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"List-maker",desc:"Writes everything down compulsively.",example:"It's not written down, so it isn't real. Write it down.",intensity:3,rarity:"common",pol:{"disc":1,"ego":-1}},
{id:1880,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Cleanliness-driven",desc:"Washes or tidies far beyond necessity.",example:"(hands, again; third time this hour)",intensity:2,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1881,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Route-fixed",desc:"Takes the exact same path every time without deviation.",example:"There's a shorter way. I don't use it.",intensity:3,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1882,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Time-rigid",desc:"Structures the day into inviolable time blocks.",example:"It's four. I don't do this at four.",intensity:3,rarity:"common",pol:{"disc":1,"ego":-1}},
{id:1883,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Object-attached",desc:"Cannot function without a specific carried item.",example:"Where is it. Nobody move. Where is it.",intensity:3,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1884,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Rehearsal-compulsive",desc:"Practices conversations before having them.",example:"(has said this to the mirror nine times)",intensity:4,rarity:"signature",pol:{"disc":1,"ego":-1}},
{id:1885,section:"Habits & Vices",category:"Risk & Escape",trait:"Gambler",desc:"Wagers past the point of sense, chasing losses.",example:"One more hand. The luck's about to turn — I can feel it.",intensity:3,rarity:"common",pol:{"disc":-1,"rebel":1}},
{id:1886,section:"Habits & Vices",category:"Risk & Escape",trait:"Thrill-chaser",desc:"Seeks physical danger for the feeling.",example:"(takes the ridge in the dark, on purpose)",intensity:2,rarity:"common",pol:{"disc":-1,"rebel":1}},
{id:1887,section:"Habits & Vices",category:"Risk & Escape",trait:"Debt-accumulator",desc:"Owes money to people who won't stay patient.",example:"It's handled. It's — mostly handled.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1888,section:"Habits & Vices",category:"Risk & Escape",trait:"Serial-fleeing",desc:"Leaves towns, jobs, and people when things settle.",example:"Eighteen months is my record. I'm at fourteen.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1889,section:"Habits & Vices",category:"Risk & Escape",trait:"Fantasy-retreater",desc:"Escapes into imagined lives rather than living this one.",example:"In the version where I said yes, I'm somewhere warm.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1890,section:"Habits & Vices",category:"Risk & Escape",trait:"Sleep-avoidant",desc:"Stays awake to avoid dreams or thoughts.",example:"I'm better tired. Tired's quieter.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1891,section:"Habits & Vices",category:"Risk & Escape",trait:"Provocation-seeker",desc:"Starts fights they don't need to feel alive.",example:"(picks the wrong man deliberately)",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1892,section:"Habits & Vices",category:"Risk & Escape",trait:"Spending-impulsive",desc:"Buys extravagantly when distressed.",example:"I bought a horse. I don't need a horse.",intensity:2,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1893,section:"Habits & Vices",category:"Risk & Escape",trait:"Secret-keeping thrill",desc:"Enjoys holding dangerous information.",example:"(knows something ruinous; savours knowing it)",intensity:2,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1894,section:"Habits & Vices",category:"Risk & Escape",trait:"Self-endangering",desc:"Takes on risks disproportionate to the reward.",example:"Somebody's got to. Might as well be someone who doesn't mind.",intensity:3,rarity:"signature",pol:{"disc":-1,"rebel":1}},
{id:1895,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Ascetic-strict",desc:"Denies comforts as a permanent practice.",example:"I don't need the fire. It makes you soft.",intensity:4,rarity:"signature",pol:{"disc":1}},
{id:1896,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Early-rigid",desc:"Rises before dawn without exception, ever.",example:"(up at four, every day, for thirty years)",intensity:3,rarity:"common",pol:{"disc":1}},
{id:1897,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Abstinent",desc:"Refuses a common indulgence entirely and permanently.",example:"Not a drop. Not since. Not ever.",intensity:5,rarity:"common",pol:{"disc":1}},
{id:1898,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Training-devoted",desc:"Maintains a punishing physical regimen.",example:"Two hours before anyone's awake. Every morning.",intensity:2,rarity:"signature",pol:{"disc":1}},
{id:1899,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Frugal-severe",desc:"Spends nothing beyond bare necessity.",example:"It still works. Why would I replace it?",intensity:2,rarity:"signature",pol:{"disc":1}},
{id:1900,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Silence-practicing",desc:"Observes deliberate periods of not speaking.",example:"(will not speak before noon; everyone has learned)",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1901,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Fasting-habitual",desc:"Regularly goes without food by choice.",example:"It clears the head. Try it before you judge it.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1902,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Pleasure-suspicious",desc:"Distrusts enjoyment as a form of weakness.",example:"If it's easy, I've probably done it wrong.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1903,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Routine-armoured",desc:"Uses inflexible routine to hold themselves together.",example:"The routine is the only reason I'm still standing.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1904,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Vice-recovered",desc:"Beat something, and the discipline shows everywhere.",example:"Nine years. I count the days. I'll always count the days.",intensity:3,rarity:"signature",pol:{"disc":1}},
{id:1905,section:"Social Role in a Group",category:"Leader",trait:"Silent authority",desc:"Commands the room without raising their voice.",example:"(says three words; the argument ends)",intensity:3,rarity:"common",pol:{}},
{id:1906,section:"Social Role in a Group",category:"Leader",trait:"Delegator",desc:"Leads by trusting others with real responsibility.",example:"You take the north gate. Your call how.",intensity:3,rarity:"common",pol:{}},
{id:1907,section:"Social Role in a Group",category:"Leader",trait:"Visionary head",desc:"Leads by naming a destination nobody else could see yet.",example:"Not for this winter. For the one after.",intensity:3,rarity:"signature",pol:{}},
{id:1908,section:"Social Role in a Group",category:"Peacemaker",trait:"Ceasefire-broker",desc:"Steps in specifically when things turn physical.",example:"Hands. Down. Both of you.",intensity:3,rarity:"common",pol:{}},
{id:1909,section:"Social Role in a Group",category:"Peacemaker",trait:"Reframer",desc:"Restates a hostile point in less inflammatory terms.",example:"I think what he means is he's frightened, not angry.",intensity:3,rarity:"signature",pol:{}},
{id:1910,section:"Social Role in a Group",category:"Peacemaker",trait:"Patient listener",desc:"Lets both sides fully vent before proposing anything.",example:"Finish. I'm not answering till you're finished.",intensity:3,rarity:"common",pol:{}},
{id:1911,section:"Social Role in a Group",category:"Instigator",trait:"Rumor-starter",desc:"Plants a suggestion and lets the group do the rest.",example:"I'm not saying anything. I'm just asking questions.",intensity:3,rarity:"signature",pol:{}},
{id:1912,section:"Social Role in a Group",category:"Instigator",trait:"Dare-giver",desc:"Pushes others into action through direct challenge.",example:"Bet you won't.",intensity:3,rarity:"common",pol:{}},
{id:1913,section:"Social Role in a Group",category:"Instigator",trait:"Line-crosser",desc:"Does the thing everyone else was only discussing.",example:"Somebody had to actually open it.",intensity:3,rarity:"common",pol:{}},
{id:1914,section:"Social Role in a Group",category:"Outsider",trait:"Half-in",desc:"Present but never fully absorbed into the group's rhythm.",example:"I come to the meetings. I don't come to the parties.",intensity:4,rarity:"common",pol:{}},
{id:1915,section:"Social Role in a Group",category:"Outsider",trait:"Watches from the door",desc:"Physically positions at the edge of every gathering.",example:"(stands nearest the exit, every time)",intensity:3,rarity:"signature",pol:{}},
{id:1916,section:"Social Role in a Group",category:"Outsider",trait:"Unclaimed",desc:"Belongs to no faction, trusted fully by none of them.",example:"Ask them. I'm not on anyone's side to lie for.",intensity:3,rarity:"signature",pol:{}},
{id:1917,section:"Social Role in a Group",category:"Caretaker",trait:"Check-in habit",desc:"Reflexively asks how everyone's doing before anything else.",example:"Before we start — is everyone actually all right?",intensity:3,rarity:"common",pol:{}},
{id:1918,section:"Social Role in a Group",category:"Caretaker",trait:"Silent provider",desc:"Handles others' needs without announcing it.",example:"(the fire's already lit when they wake up)",intensity:3,rarity:"signature",pol:{}},
{id:1919,section:"Social Role in a Group",category:"Caretaker",trait:"Worry-carrier",desc:"Absorbs the group's anxiety as their own.",example:"I'll worry about it so you don't have to.",intensity:3,rarity:"common",pol:{}},
{id:1920,section:"Social Role in a Group",category:"Skeptic",trait:"Numbers-checker",desc:"Wants the arithmetic before believing the plan.",example:"Show me the count. Not the story — the count.",intensity:3,rarity:"common",pol:{}},
{id:1921,section:"Social Role in a Group",category:"Skeptic",trait:"Precedent-recaller",desc:"Doubts based on how similar plans failed before.",example:"We tried a version of this. Ask me how it ended.",intensity:3,rarity:"signature",pol:{}},
{id:1922,section:"Social Role in a Group",category:"Skeptic",trait:"Slow-to-commit",desc:"Withholds agreement until every objection is answered.",example:"Not yet. I have four more questions.",intensity:3,rarity:"common",pol:{}},
{id:1923,section:"Humor Style",category:"Dry & Deadpan",trait:"Funeral-faced comic",desc:"Delivers jokes with an expression of total solemnity.",example:"(utterly still face) That was the funniest thing I've heard all week.",intensity:3,rarity:"signature",pol:{}},
{id:1924,section:"Humor Style",category:"Dry & Deadpan",trait:"Matter-of-fact absurdist",desc:"States impossible things as routine fact.",example:"The horse filed a complaint. I've forwarded it.",intensity:3,rarity:"common",pol:{}},
{id:1925,section:"Humor Style",category:"Dry & Deadpan",trait:"Minimalist wit",desc:"Gets the laugh from the fewest possible words.",example:"Bold plan. Wrong.",intensity:3,rarity:"common",pol:{}},
{id:1926,section:"Humor Style",category:"Self-Deprecating",trait:"Resume-of-failures",desc:"Lists their own disasters like accomplishments.",example:"Three shipwrecks and a small fire. I peaked early.",intensity:3,rarity:"signature",pol:{}},
{id:1927,section:"Humor Style",category:"Self-Deprecating",trait:"Modest deflector",desc:"Undercuts praise the instant it arrives.",example:"Talented? I got lucky and didn't die.",intensity:4,rarity:"common",pol:{}},
{id:1928,section:"Humor Style",category:"Self-Deprecating",trait:"Anticipatory apologist",desc:"Jokes about their own incompetence before attempting anything.",example:"Watch this go badly. Everyone ready?",intensity:3,rarity:"common",pol:{}},
{id:1929,section:"Humor Style",category:"Cruel & Barbed",trait:"Silence-weaponizer",desc:"Lets an awkward pause do the cruelty for them.",example:"(says nothing; lets the room understand exactly what that means)",intensity:3,rarity:"signature",pol:{}},
{id:1930,section:"Humor Style",category:"Cruel & Barbed",trait:"Comparison-cutter",desc:"Wounds by comparing someone unfavorably to another.",example:"Funny — your brother would've had it done by now.",intensity:3,rarity:"common",pol:{}},
{id:1931,section:"Humor Style",category:"Cruel & Barbed",trait:"False-concern jab",desc:"Delivers insults disguised as worry.",example:"Are you sure you should attempt that? Given, well, everything.",intensity:2,rarity:"common",pol:{}},
{id:1932,section:"Humor Style",category:"Warm & Playful",trait:"Running-joke keeper",desc:"Maintains a private joke across years, faithfully.",example:"Still counting the goats. Eleven now.",intensity:3,rarity:"common",pol:{}},
{id:1933,section:"Humor Style",category:"Warm & Playful",trait:"Gentle mimic",desc:"Affectionately imitates people's habits and speech.",example:"(does his exact walk; everyone laughs; he laughs hardest)",intensity:3,rarity:"signature",pol:{}},
{id:1934,section:"Humor Style",category:"Warm & Playful",trait:"Compliment-comic",desc:"Turns jokes into disguised affection.",example:"You're a menace. My favorite kind.",intensity:2,rarity:"common",pol:{}},
{id:1935,section:"Humor Style",category:"Absurd & Chaotic",trait:"Prop-comedian",desc:"Turns any nearby object into an unplanned bit.",example:"This spoon is now a sword. We are now knights.",intensity:3,rarity:"signature",pol:{}},
{id:1936,section:"Humor Style",category:"Absurd & Chaotic",trait:"Escalating liar",desc:"Builds an obviously false story bigger and bigger.",example:"And THEN the king himself asked me to dance.",intensity:3,rarity:"common",pol:{}},
{id:1937,section:"Humor Style",category:"Absurd & Chaotic",trait:"Left-field tangent",desc:"Comedy from following an idea nobody else was thinking.",example:"Anyway, this is why I don't trust geese.",intensity:3,rarity:"common",pol:{}},
{id:1938,section:"Humor Style",category:"Humorless & Absent",trait:"Confused-by-comedy",desc:"Genuinely doesn't register when something is a joke.",example:"Wait — was that not a real plan?",intensity:3,rarity:"common",pol:{}},
{id:1939,section:"Humor Style",category:"Humorless & Absent",trait:"Duty-first blank",desc:"Too focused on the task to register comedy around it.",example:"Funny. The gate's still open, though.",intensity:3,rarity:"common",pol:{}},
{id:1940,section:"Humor Style",category:"Humorless & Absent",trait:"Delayed non-reaction",desc:"Notices a joke occurred, chooses not to respond to it.",example:"(pause) Was there a punchline coming.",intensity:3,rarity:"signature",pol:{}},
{id:1941,section:"Attachment & Intimacy Style",category:"Secure",trait:"Repair-initiator",desc:"Reaches out first after a disagreement, without keeping score.",example:"That went sideways. Can we try that again?",intensity:3,rarity:"common",pol:{}},
{id:1942,section:"Attachment & Intimacy Style",category:"Secure",trait:"Warmly consistent",desc:"Shows the same steady affection regardless of mood.",example:"Bad day or not, come here.",intensity:3,rarity:"common",pol:{}},
{id:1943,section:"Attachment & Intimacy Style",category:"Secure",trait:"Non-defensive listener",desc:"Hears criticism without treating it as an attack.",example:"Say that again — I want to actually understand it.",intensity:3,rarity:"signature",pol:{}},
{id:1944,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Over-interpreter",desc:"Reads deep meaning into small, ordinary gestures.",example:"You used to sign your letters differently.",intensity:3,rarity:"signature",pol:{}},
{id:1945,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Clinging goodbye",desc:"Draws out farewells, reluctant to let the moment end.",example:"One more minute. Just — one more.",intensity:3,rarity:"common",pol:{}},
{id:1946,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Silence-panicker",desc:"Reads an unanswered message as a verdict.",example:"You saw it. I know you saw it.",intensity:3,rarity:"common",pol:{}},
{id:1947,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Intimacy-deflector",desc:"Turns intimacy-building moments into jokes or subject changes.",example:"Sure, sure. Anyway — dinner?",intensity:3,rarity:"common",pol:{}},
{id:1948,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Busy-as-shield",desc:"Uses work as a permanent excuse for closeness.",example:"Can't. Always can't. You know how it is.",intensity:4,rarity:"common",pol:{}},
{id:1949,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Late-discloser",desc:"Reveals almost nothing until forced to by circumstance.",example:"You're only hearing this because I have to tell someone.",intensity:3,rarity:"signature",pol:{}},
{id:1950,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Reaches then recoils",desc:"Initiates closeness and immediately regrets it.",example:"(takes their hand) — (lets go too fast)",intensity:4,rarity:"signature",pol:{}},
{id:1951,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Contradicts own needs aloud",desc:"States wanting closeness and distance in the same breath.",example:"Stay. Actually — no. Stay, though.",intensity:3,rarity:"common",pol:{}},
{id:1952,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Bond-then-bolt",desc:"Gets intensely close fast, then vanishes without warning.",example:"(inseparable for a month; gone by Tuesday)",intensity:3,rarity:"common",pol:{}},
{id:1953,section:"Habits & Vices",category:"Substance & Consumption",trait:"Ritual-drinker",desc:"Attaches drinking to a specific fixed moment each day.",example:"Sundown. Always sundown. That's the rule.",intensity:3,rarity:"common",pol:{}},
{id:1954,section:"Habits & Vices",category:"Substance & Consumption",trait:"Withdrawal-irritable",desc:"Becomes visibly harder to deal with when it's unavailable.",example:"Don't talk to me yet. I haven't had it yet.",intensity:3,rarity:"signature",pol:{}},
{id:1955,section:"Habits & Vices",category:"Substance & Consumption",trait:"Bargainer",desc:"Constantly negotiates the terms of their own limits.",example:"Just the one. This one doesn't count.",intensity:4,rarity:"common",pol:{}},
{id:1956,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Threshold-tapper",desc:"Touches a doorframe or object before crossing it.",example:"(taps twice, always twice, before the door)",intensity:3,rarity:"signature",pol:{}},
{id:1957,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Pattern-matcher",desc:"Notices and must correct visual asymmetry.",example:"That's crooked. I can't — give me a second.",intensity:3,rarity:"common",pol:{}},
{id:1958,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Word-repeater",desc:"Silently repeats a phrase a fixed number of times for luck.",example:"(mouths it three times before answering)",intensity:3,rarity:"common",pol:{}},
{id:1959,section:"Habits & Vices",category:"Risk & Escape",trait:"Deadline-chaser",desc:"Only feels functional right up against the last possible moment.",example:"Plenty of time. (There is not plenty of time.)",intensity:3,rarity:"common",pol:{}},
{id:1960,section:"Habits & Vices",category:"Risk & Escape",trait:"Anonymous-elsewhere",desc:"Fantasizes about a life under a different name.",example:"In the other version, nobody here knows me.",intensity:3,rarity:"signature",pol:{}},
{id:1961,section:"Habits & Vices",category:"Risk & Escape",trait:"Dare-accepter",desc:"Cannot decline a direct challenge, however unwise.",example:"You didn't have to say it like that. Fine. Fine!",intensity:3,rarity:"common",pol:{}},
{id:1962,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Portion-controlled",desc:"Measures and limits consumption deliberately, always.",example:"That's the portion. That's always the portion.",intensity:4,rarity:"common",pol:{}},
{id:1963,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Delayed-reward planner",desc:"Saves pleasures for after the hard task is finished.",example:"After. Not before. After.",intensity:3,rarity:"common",pol:{}},
{id:1964,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Public accountability seeker",desc:"Announces commitments aloud specifically to be held to them.",example:"Tell everyone. If I say it out loud I can't quit.",intensity:3,rarity:"signature",pol:{}},
{id:1965,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Occasionally chatty",desc:"Talks a little more than average, only when comfortable.",example:"I don't usually go on, but — since you asked.",intensity:1,rarity:"common",pol:{}},
{id:1966,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Unrelenting torrent",desc:"Produces an unbroken flood of words with no natural stopping point.",example:"—andandand— (forty minutes later, still going)",intensity:5,rarity:"signature",pol:{}},
{id:1967,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Occasionally curt",desc:"Mostly normal, but clips replies short when tired or busy.",example:"Not now. Later, maybe.",intensity:1,rarity:"common",pol:{}},
{id:1968,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Vow-of-silence terse",desc:"Goes entire days uttering only single words, if that.",example:"(three days now. Not one syllable.)",intensity:5,rarity:"signature",pol:{}},
{id:1969,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Slightly hurried",desc:"Speeds up only faintly when pressed for time.",example:"Quick version: yes.",intensity:1,rarity:"common",pol:{}},
{id:1970,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Total-panic gabble",desc:"Collapses into unintelligible speed the instant danger appears.",example:"—go-go-go-GO—",intensity:5,rarity:"signature",pol:{}},
{id:1971,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Faintly formal",desc:"Occasionally reaches for a slightly elevated word, nothing more.",example:"That would be, ah, most agreeable.",intensity:1,rarity:"common",pol:{}},
{id:1972,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Baroque to the point of parody",desc:"Buries every plain statement under towering ornamental language.",example:"The hour, gilded and reluctant, surrenders itself unto the twilight's grasping fingers, as do I unto despair.",intensity:5,rarity:"signature",pol:{}},
{id:1973,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Occasional sensory touch",desc:"Mostly abstract, but drops in one concrete image now and then.",example:"Anyway — point is, it felt cold. The whole thing felt cold.",intensity:1,rarity:"common",pol:{}},
{id:1974,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Overwhelming sensorium",desc:"Floods every sentence with layered physical sensation.",example:"Wet stone, rust and blood, the cold biting up through the boots, the air thick as wool.",intensity:5,rarity:"signature",pol:{}},
{id:1975,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Subtly expressive wording",desc:"Understated feeling shows through only in small word choices.",example:"That was... nice, actually.",intensity:1,rarity:"common",pol:{}},
{id:1976,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Emotionally combustible vocabulary",desc:"Every word choice is charged near the point of eruption.",example:"I could tear the walls down with my bare hands right now.",intensity:5,rarity:"signature",pol:{}},
{id:1977,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Occasional borrowed term",desc:"Uses one field-specific word now and then, nothing systematic.",example:"It's a bit of a — sunk cost, really.",intensity:1,rarity:"common",pol:{}},
{id:1978,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Total domain immersion",desc:"Frames literally everything through one obsessive field's vocabulary.",example:"Marriage is a merger. Grief is a write-down. Love is depreciation you never fully account for.",intensity:5,rarity:"signature",pol:{}},
{id:1979,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Mostly plain, occasionally poetic",desc:"Speaks directly but allows the rare figurative flourish.",example:"It's over. Like a door closing, I suppose.",intensity:1,rarity:"common",pol:{}},
{id:1980,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Purely, unyieldingly literal",desc:"Cannot process figurative language in either direction, ever.",example:"'Break a leg' — why would you wish that on me.",intensity:5,rarity:"signature",pol:{}},
{id:1981,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Rare invented word",desc:"Coins a new term maybe once in a long while.",example:"It's — hm — call it a 'mehday'. You know the kind.",intensity:1,rarity:"common",pol:{}},
{id:1982,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Constant word-forging",desc:"Invents new compound and blended words in nearly every sentence.",example:"That's proper glumtastic doom-Tuesday nonsense, that is.",intensity:5,rarity:"signature",pol:{}},
{id:1983,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Faint accent texture",desc:"A subtle phonetic habit noticeable only if you listen closely.",example:"(a barely-there roll on the r's)",intensity:1,rarity:"common",pol:{}},
{id:1984,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Overwhelming phonetic signature",desc:"Sound patterning dominates every sentence to the point of caricature.",example:"Sslowly, sslyly, the sserpent sslid ssideways.",intensity:5,rarity:"signature",pol:{}},
{id:1985,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Occasional hedge",desc:"Mostly direct, adds a soft qualifier once in a while.",example:"I think — probably — that's right.",intensity:1,rarity:"common",pol:{}},
{id:1986,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Every utterance a directive",desc:"Cannot make a statement without it functioning as a command.",example:"Sit. Listen. Understand. Agree.",intensity:5,rarity:"signature",pol:{}},
{id:1987,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Slightly rounded numbers",desc:"Mostly precise, rounds only in casual moments.",example:"About forty, give or take a couple.",intensity:1,rarity:"common",pol:{}},
{id:1988,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Obsessive exactitude",desc:"Cannot let any figure pass without narrowing it to the decimal.",example:"Not forty. Forty-one point three, measured at dawn.",intensity:5,rarity:"signature",pol:{}},
{id:1989,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Slightly polished",desc:"Everyday speech with the rough edges just barely smoothed.",example:"That's, ah, not quite ideal, is it.",intensity:1,rarity:"common",pol:{}},
{id:1990,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Maximally formal",desc:"Every phrase calibrated for the most elevated occasion, regardless of setting.",example:"We are gathered, on this most ordinary of Tuesdays—",intensity:5,rarity:"signature",pol:{}},
{id:1991,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Occasional extra adjective",desc:"Usually spare, adds one descriptive word here and there.",example:"A tired, small room.",intensity:1,rarity:"common",pol:{}},
{id:1992,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Modifier-saturated",desc:"Piles three or four descriptors onto every single noun.",example:"A cold, cracked, colorless, forgotten little room.",intensity:5,rarity:"signature",pol:{}},
{id:1993,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Rare verbal tic",desc:"One filler phrase surfaces only under real stress.",example:"I mean — sorry — go on.",intensity:1,rarity:"common",pol:{}},
{id:1994,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Filler in every clause",desc:"Cannot complete a sentence without multiple anchor phrases.",example:"So, look, I mean, right, basically, you know, honestly—",intensity:5,rarity:"signature",pol:{}},
{id:1995,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Occasional stumble",desc:"Trips over words rarely, usually when caught off guard.",example:"I— sorry— what was the question?",intensity:1,rarity:"common",pol:{}},
{id:1996,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Constant fragmentation",desc:"Speech is in a permanent state of restart and collapse.",example:"I was— no— what I— he said— wait— start over—",intensity:5,rarity:"signature",pol:{}},
{id:1997,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Occasionally clipped",desc:"Drops a word here and there when rushed.",example:"Going now.",intensity:1,rarity:"common",pol:{}},
{id:1998,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Maximally telegraphic",desc:"Strips every sentence to its absolute compressed minimum, always.",example:"Gate. Now. Move.",intensity:5,rarity:"signature",pol:{}},
{id:1999,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Occasional aside",desc:"Adds one small parenthetical thought now and then.",example:"He left — Tuesday, I think — and hasn't called.",intensity:1,rarity:"common",pol:{}},
{id:2000,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Constantly restructured syntax",desc:"No sentence keeps the shape it started with.",example:"He — and this, mind, is the part that — well, no, actually — where was I — he left.",intensity:5,rarity:"signature",pol:{}},
{id:2001,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Occasionally interrupts",desc:"Cuts in rarely, only when strongly moved to.",example:"—sorry, just quickly—",intensity:1,rarity:"common",pol:{}},
{id:2002,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Total conversational dominance",desc:"Physically impossible to interrupt once they start speaking.",example:"(speaks continuously for eleven minutes without a single pause long enough to break in)",intensity:5,rarity:"signature",pol:{}},
{id:2003,section:"Mannerisms",category:"Emotional Affectations",trait:"Faint tell",desc:"A tiny, almost invisible flicker of feeling crosses the face.",example:"(the corner of the mouth moves, just barely)",intensity:1,rarity:"common",pol:{}},
{id:2004,section:"Mannerisms",category:"Emotional Affectations",trait:"Full-body emotional broadcast",desc:"Every feeling is performed with total physical commitment.",example:"(collapses into the chair, wailing, fully committed)",intensity:5,rarity:"signature",pol:{}},
{id:2005,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Occasional fidget with surroundings",desc:"Touches nearby objects only once in a while.",example:"(straightens one picture frame, then stops)",intensity:1,rarity:"common",pol:{}},
{id:2006,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Constant environmental rearranging",desc:"Cannot stop touching, aligning, or adjusting the room.",example:"(rearranges the entire desk mid-conversation, twice)",intensity:5,rarity:"signature",pol:{}},
{id:2007,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Subtle glance",desc:"A brief, easy-to-miss shift of the eyes.",example:"(eyes flick sideways, just once)",intensity:1,rarity:"common",pol:{}},
{id:2008,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Theatrically expressive face",desc:"Every micro-emotion is broadcast at stage-actor scale.",example:"(eyes go wide, mouth drops, the whole face performs shock)",intensity:5,rarity:"signature",pol:{}},
{id:2009,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Occasional small gesture",desc:"Hands move only slightly, most of the time still.",example:"(a small motion of the hand, then stillness)",intensity:1,rarity:"common",pol:{}},
{id:2010,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Full-body gesture storm",desc:"Cannot speak without the whole body moving in illustration.",example:"(arms sweep, feet plant, whole torso leans into every point)",intensity:5,rarity:"signature",pol:{}},
{id:2011,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Barely-there habit",desc:"One tiny physical tic, easy to miss unless you're looking.",example:"(a single thumb-rub, then nothing)",intensity:1,rarity:"common",pol:{}},
{id:2012,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Constant visible tic cluster",desc:"Several physical tics running simultaneously, impossible to ignore.",example:"(knuckles crack, jaw shifts, foot taps, all at once, continuously)",intensity:5,rarity:"signature",pol:{}},
{id:2013,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Rare small sound",desc:"An almost-silent sound escapes only occasionally.",example:"(a tiny exhale)",intensity:1,rarity:"common",pol:{}},
{id:2014,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Constant vocal noise",desc:"Fills every pause with audible sound — sighs, clicks, hums, grunts.",example:"(sighs, clicks tongue, hums, sighs again, all within one breath)",intensity:5,rarity:"signature",pol:{}},
{id:2015,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Slight posture shift",desc:"Occasionally adjusts stance, mostly holds still.",example:"(shifts weight once, settles)",intensity:1,rarity:"common",pol:{}},
{id:2016,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Constant restless repositioning",desc:"Never settles into one posture for more than a few seconds.",example:"(stands, sits, leans, paces, sits again, all within a minute)",intensity:5,rarity:"signature",pol:{}},
{id:2017,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Keeps a little distance",desc:"Keeps a touch more distance than most, nothing dramatic.",example:"(stays a half-step further back than the others)",intensity:1,rarity:"common",pol:{}},
{id:2018,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Boundary-obliterating presence",desc:"Physically and socially disregards personal space entirely, always.",example:"(closes the distance completely, every time, without noticing)",intensity:5,rarity:"signature",pol:{}},
{id:2019,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Occasional object fidget",desc:"Touches whatever's nearby only now and then.",example:"(taps the cup once, stops)",intensity:1,rarity:"common",pol:{}},
{id:2020,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Cannot stop handling objects",desc:"Constantly manipulates whatever is within reach, without pause.",example:"(spins the pen, folds the napkin, taps the glass, all in one exchange)",intensity:5,rarity:"signature",pol:{}},
{id:2021,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Slight tonal shift",desc:"Voice changes only faintly with mood.",example:"(a small warmth enters the voice, briefly)",intensity:1,rarity:"common",pol:{}},
{id:2022,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Wildly variable vocal range",desc:"Voice swings between whisper and shout within a single sentence.",example:"(starts almost silent) — (ENDS IN A FULL SHOUT)",intensity:5,rarity:"signature",pol:{}},
{id:2023,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Politely warm",desc:"Friendly in a low-key, undemonstrative way.",example:"Nice to see you. Come in, if you like.",intensity:1,rarity:"common",pol:{}},
{id:2024,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Boundlessly welcoming",desc:"Treats every stranger like a long-lost, cherished friend.",example:"YOU'RE HERE! Come in, come in, everyone, look who's here!",intensity:5,rarity:"signature",pol:{}},
{id:2025,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Slightly reserved",desc:"A touch harder to warm up to than most, nothing more.",example:"Fine. Nice to meet you.",intensity:1,rarity:"common",pol:{}},
{id:2026,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Glacially unreachable",desc:"Radiates total, deliberate emotional inaccessibility.",example:"(does not acknowledge the greeting at all)",intensity:5,rarity:"signature",pol:{}},
{id:2027,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Generally honest",desc:"Tells the truth in most situations, without making a virtue of it.",example:"Yeah, that was me. Sorry.",intensity:1,rarity:"common",pol:{}},
{id:2028,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Compulsively, uncomfortably honest",desc:"Physically incapable of withholding any truth, however damaging.",example:"You look tired, your plan is bad, and yes, I did read your letter.",intensity:5,rarity:"signature",pol:{}},
{id:2029,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Occasionally shades the truth",desc:"Bends small facts now and then, mostly harmlessly.",example:"I was a little late. Ish.",intensity:1,rarity:"common",pol:{}},
{id:2030,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Pathologically deceptive",desc:"Lies reflexively, even about matters with no stakes at all.",example:"I've never been to that street. (Lives on that street.)",intensity:5,rarity:"signature",pol:{}},
{id:2031,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Mildly direct",desc:"States preferences plainly without much force behind it.",example:"I'd rather do it this way, if that's all right.",intensity:1,rarity:"common",pol:{}},
{id:2032,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Overpoweringly assertive",desc:"Dominates every exchange, leaves no room for other input.",example:"We're doing it my way. That was never a discussion.",intensity:5,rarity:"signature",pol:{}},
{id:2033,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Slightly deferential",desc:"Leans toward agreement, but will voice a mild preference.",example:"I don't mind either way, honestly.",intensity:1,rarity:"common",pol:{}},
{id:2034,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Completely unable to assert needs",desc:"Cannot state a preference even when directly harmed by staying silent.",example:"It's fine. It's fine. (It is not fine.)",intensity:5,rarity:"signature",pol:{}},
{id:2035,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Quietly confident",desc:"Comfortable with themselves without needing to show it.",example:"I know what I'm doing here.",intensity:1,rarity:"common",pol:{}},
{id:2036,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Unshakeable self-possession",desc:"Nothing — failure, mockery, disaster — dents their self-regard.",example:"Lost everything today. Still the smartest person in this room.",intensity:5,rarity:"signature",pol:{}},
{id:2037,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Occasionally self-doubting",desc:"Second-guesses themselves sometimes, not constantly.",example:"Was that okay? I think that was okay.",intensity:1,rarity:"common",pol:{}},
{id:2038,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Consumed by insecurity or ego",desc:"Every interaction is filtered entirely through fear of inadequacy — or need for supremacy.",example:"Did they laugh? Why did they laugh? Was it about me?",intensity:5,rarity:"signature",pol:{}},
{id:2039,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Generally easygoing",desc:"Prefers to go along with the group, mildly.",example:"Sure, that works for me.",intensity:1,rarity:"common",pol:{}},
{id:2040,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Completely self-erasing accommodator",desc:"Has no visible preferences left of their own at all.",example:"Whatever everyone else wants. Really. Whatever.",intensity:5,rarity:"signature",pol:{}},
{id:2041,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Occasionally pushes back",desc:"Raises objections sometimes, not as a default stance.",example:"I mean, I'd push back on that a little.",intensity:1,rarity:"common",pol:{}},
{id:2042,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Compulsively contrarian",desc:"Cannot let any statement pass without opposing it.",example:"The sky is blue. — Debatable.",intensity:5,rarity:"signature",pol:{}},
{id:2043,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Reasonably polite",desc:"Uses ordinary courtesy without much formality.",example:"Please, after you.",intensity:1,rarity:"common",pol:{}},
{id:2044,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Exhaustingly, formally courteous",desc:"Every interaction wrapped in elaborate, unbroken etiquette.",example:"I would be most humbly grateful if you would kindly consider—",intensity:5,rarity:"signature",pol:{}},
{id:2045,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Occasionally blunt",desc:"Skips a nicety here and there, nothing shocking.",example:"Yeah, whatever, pass the salt.",intensity:1,rarity:"common",pol:{}},
{id:2046,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Totally, aggressively uncouth",desc:"Ignores every social convention without a flicker of awareness.",example:"(talks with mouth full, feet on the table, interrupts the toast)",intensity:5,rarity:"signature",pol:{}},
{id:2047,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Fairly disciplined",desc:"Sticks to plans reasonably well, allows some flexibility.",example:"I'll finish this first, then take a break.",intensity:1,rarity:"common",pol:{}},
{id:2048,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Rigid, unbreakable discipline",desc:"Never deviates from routine or commitment, under any circumstance.",example:"Four a.m. Every day. For thirty years. No exceptions.",intensity:5,rarity:"signature",pol:{}},
{id:2049,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Occasionally impulsive",desc:"Deviates from plans sometimes, not habitually.",example:"Changed my mind. Let's just go now.",intensity:1,rarity:"common",pol:{}},
{id:2050,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Completely ungoverned by impulse control",desc:"Acts entirely on immediate whim, every single time.",example:"Bought it. Quit the job. Booked the flight. All before lunch.",intensity:5,rarity:"signature",pol:{}},
{id:2052,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Totally, permanently defiant",desc:"Opposes authority as a reflex, regardless of the cost.",example:"Lock me up. I'll say it again from in there.",intensity:5,rarity:"signature",pol:{}},
{id:2053,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Generally rule-following",desc:"Prefers to follow procedure, with occasional exceptions.",example:"Let's just do it the normal way.",intensity:1,rarity:"common",pol:{}},
{id:2054,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Absolute, unquestioning conformity",desc:"Would never deviate from established order, ever, for any reason.",example:"It's the rule. That ends the conversation.",intensity:5,rarity:"signature",pol:{}},
{id:2055,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Mildly expressive",desc:"Shows feeling somewhat openly, without much drama.",example:"That actually got to me a bit.",intensity:1,rarity:"common",pol:{}},
{id:2056,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Overwhelmingly, totally open emotionally",desc:"Every feeling is immediately, fully, visibly experienced.",example:"(sobs, laughs, sobs again, all within the same minute)",intensity:5,rarity:"signature",pol:{}},
{id:2057,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Slightly reserved emotionally",desc:"Keeps some feelings private, shares the rest normally.",example:"I'd rather not get into that part.",intensity:1,rarity:"common",pol:{}},
{id:2058,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Totally emotionally sealed off",desc:"Registers nothing outwardly regardless of what's happening.",example:"(house burns down) Well. That's unfortunate.",intensity:5,rarity:"signature",pol:{}},
{id:2059,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Reasonably sharp",desc:"Picks up on things fairly quickly, nothing extraordinary.",example:"Ah, I see what you did there.",intensity:1,rarity:"common",pol:{}},
{id:2060,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Formidably, intimidatingly analytical",desc:"Solves in seconds what takes others hours, constantly.",example:"You haven't finished the sentence. I've already found the flaw.",intensity:5,rarity:"signature",pol:{}},
{id:2061,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Mildly instinct-driven",desc:"Trusts gut feeling somewhat more than careful analysis.",example:"Don't know why. Feels right, though.",intensity:1,rarity:"common",pol:{}},
{id:2062,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Entirely instinct-governed",desc:"Cannot engage with abstract reasoning at all, ever.",example:"Words don't help. Just show me with your hands.",intensity:5,rarity:"signature",pol:{}},
{id:2063,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Generally positive",desc:"Tends to look on the bright side, without forcing it.",example:"Could be worse, right?",intensity:1,rarity:"common",pol:{}},
{id:2064,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Relentlessly, unstoppably optimistic",desc:"Finds hope in literally any circumstance, however dire.",example:"Lost the farm, the house, the horse — still, spring's coming!",intensity:5,rarity:"signature",pol:{}},
{id:2065,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Mildly skeptical",desc:"Doubts good outcomes somewhat more than most.",example:"We'll see. I wouldn't count on it.",intensity:1,rarity:"common",pol:{}},
{id:2066,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Totally, bone-deep cynical",desc:"Cannot register any development as anything but coming disaster.",example:"Good news? There's no such thing. Just delayed bad news.",intensity:5,rarity:"signature",pol:{}},
{id:2067,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Reasonably active",desc:"Keeps a decent pace, without being restless about it.",example:"Let's get moving, shall we.",intensity:1,rarity:"common",pol:{}},
{id:2068,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Explosively, constantly high-energy",desc:"Never stops moving, physically, for more than a few seconds.",example:"(already three tasks into the morning before anyone else is awake)",intensity:5,rarity:"signature",pol:{}},
{id:2069,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Mildly low-key",desc:"Prefers a slower pace, nothing dramatic about it.",example:"I'll catch up. Eventually.",intensity:1,rarity:"common",pol:{}},
{id:2070,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Completely, permanently low-energy",desc:"Movement of any kind requires visible, exhausting effort.",example:"(hasn't left the chair in three days, by choice)",intensity:5,rarity:"signature",pol:{}},
{id:2075,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Mild preference",desc:"Would like a small, specific thing, without much urgency.",example:"Be nice to get a quiet weekend, honestly.",intensity:1,rarity:"common",pol:{}},
{id:2076,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"All-consuming want",desc:"This single goal has swallowed every other priority in their life.",example:"Everything I do, every single day, is for this. Nothing else exists.",intensity:5,rarity:"signature",pol:{}},
{id:2077,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Mild unease",desc:"A quiet discomfort around one specific thing, easily managed.",example:"Don't love enclosed spaces. It's fine, mostly.",intensity:1,rarity:"common",pol:{}},
{id:2078,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Paralyzing terror",desc:"This fear can completely override reason and self-preservation.",example:"I would rather die than go back in there. I mean that exactly.",intensity:5,rarity:"signature",pol:{}},
{id:2079,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A small old hurt",desc:"Something that stung once, mostly healed, rarely thought of.",example:"Bit of a sore spot from years back. Not a big deal now.",intensity:1,rarity:"common",pol:{}},
{id:2080,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A defining, unhealed wound",desc:"This injury still actively shapes nearly every decision they make.",example:"It's been eleven years. I still can't say his name out loud.",intensity:5,rarity:"signature",pol:{}},
{id:2081,section:"Motivation & Wound",category:"The Lie They Believe",trait:"A small doubt",desc:"A quiet, occasional worry that isn't fully believed.",example:"Sometimes I wonder if I really deserved it.",intensity:1,rarity:"common",pol:{}},
{id:2082,section:"Motivation & Wound",category:"The Lie They Believe",trait:"A totally internalized false belief",desc:"This lie functions as unquestioned fact, structuring their whole self-image.",example:"Of course they'll leave. Everyone does. That's just how it is.",intensity:5,rarity:"signature",pol:{}},
{id:2083,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Mildly assertive under pressure",desc:"Pushes back a little harder than usual when stressed.",example:"Look, I don't love this conversation either, but let's have it properly.",intensity:1,rarity:"common",pol:{}},
{id:2084,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Explosively combative",desc:"Goes fully, immediately aggressive at the first sign of threat.",example:"(already across the room before the insult finished landing)",intensity:5,rarity:"signature",pol:{}},
{id:2085,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Mildly conflict-avoidant",desc:"Prefers to step away from tension when possible, not always.",example:"I might just take a walk, if that's all right.",intensity:1,rarity:"common",pol:{}},
{id:2086,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Total, immediate flight",desc:"Physically removes themselves from any conflict within seconds.",example:"(is already gone before the first raised voice finishes)",intensity:5,rarity:"signature",pol:{}},
{id:2087,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Mildly hesitant under stress",desc:"Takes a beat longer to respond when pressured.",example:"Give me a second. Just — a second.",intensity:1,rarity:"common",pol:{}},
{id:2088,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Total shutdown",desc:"Completely stops functioning — speech, movement, thought — under real pressure.",example:"(stares at nothing, unresponsive, for several full minutes)",intensity:5,rarity:"signature",pol:{}},
{id:2089,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Mildly accommodating under pressure",desc:"Softens their position a little when things get tense.",example:"Okay, okay, we can do it your way.",intensity:1,rarity:"common",pol:{}},
{id:2090,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Complete, reflexive appeasement",desc:"Instantly abandons any position to placate anger, without exception.",example:"You're right, I'm sorry, you're completely right, I'm so sorry—",intensity:5,rarity:"signature",pol:{}},
{id:2091,section:"Social Role in a Group",category:"Leader",trait:"Quietly capable",desc:"Steps up when needed, without seeking the position.",example:"I'll take point, if nobody minds.",intensity:1,rarity:"common",pol:{}},
{id:2092,section:"Social Role in a Group",category:"Leader",trait:"Utterly commanding",desc:"The room reorganizes around them the instant they speak.",example:"(says one sentence; the entire plan changes)",intensity:5,rarity:"signature",pol:{}},
{id:2093,section:"Social Role in a Group",category:"Peacemaker",trait:"Mildly conciliatory",desc:"Softens tension a little, without forcing resolution.",example:"Let's not make this bigger than it needs to be.",intensity:1,rarity:"common",pol:{}},
{id:2094,section:"Social Role in a Group",category:"Peacemaker",trait:"Compulsive, total peacekeeper",desc:"Cannot tolerate any unresolved tension anywhere nearby, ever.",example:"(physically cannot leave the room until every disagreement is settled)",intensity:5,rarity:"signature",pol:{}},
{id:2095,section:"Social Role in a Group",category:"Instigator",trait:"Mildly provocative",desc:"Occasionally stirs things up, mostly for fun.",example:"Just saying — somebody should ask him about it.",intensity:1,rarity:"common",pol:{}},
{id:2096,section:"Social Role in a Group",category:"Instigator",trait:"Compulsive chaos-starter",desc:"Cannot resist detonating any calm situation, constantly.",example:"(lights the fuse on every single gathering, without fail)",intensity:5,rarity:"signature",pol:{}},
{id:2097,section:"Social Role in a Group",category:"Outsider",trait:"Slightly apart",desc:"A touch more distant from the group than most, nothing dramatic.",example:"I'll sit this one out, if that's fine.",intensity:1,rarity:"common",pol:{}},
{id:2098,section:"Social Role in a Group",category:"Outsider",trait:"Totally, permanently outside",desc:"Has never once been fully absorbed into any group, ever.",example:"Eighteen years here. Still not one of them. Never will be.",intensity:5,rarity:"signature",pol:{}},
{id:2099,section:"Social Role in a Group",category:"Caretaker",trait:"Mildly attentive",desc:"Checks in on others sometimes, without making it a role.",example:"You doing okay? Just checking.",intensity:1,rarity:"common",pol:{}},
{id:2100,section:"Social Role in a Group",category:"Caretaker",trait:"Totally self-sacrificing caretaker",desc:"Puts everyone else's needs first, completely, without exception.",example:"Haven't slept in three days. Everyone else has, though. That's what matters.",intensity:5,rarity:"signature",pol:{}},
{id:2101,section:"Social Role in a Group",category:"Skeptic",trait:"Mildly doubtful",desc:"Questions things a bit more than most, without much friction.",example:"Hm. Are we sure about that?",intensity:1,rarity:"common",pol:{}},
{id:2102,section:"Social Role in a Group",category:"Skeptic",trait:"Totally, reflexively skeptical",desc:"Trusts nothing without exhaustive, independent verification.",example:"Show me. Not tell me — show me. With proof.",intensity:5,rarity:"signature",pol:{}},
{id:2103,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Mildly principled",desc:"Holds a few firm lines, flexible on most everything else.",example:"I won't lie about that one thing. Everything else, sure, we can talk.",intensity:1,rarity:"common",pol:{}},
{id:2104,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Absolutely, unbendingly principled",desc:"Would sacrifice everything before compromising a single stated value.",example:"Burn it all down. I'm still not signing that.",intensity:5,rarity:"signature",pol:{}},
{id:2105,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Mildly flexible",desc:"Bends the rules a little when it clearly helps.",example:"Technically against policy. Practically, who cares.",intensity:1,rarity:"common",pol:{}},
{id:2106,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Totally, unapologetically pragmatic",desc:"Has no fixed principle that survives contact with sufficient incentive.",example:"Everything's for sale. We're just discussing the price.",intensity:5,rarity:"signature",pol:{}},
{id:2107,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Mildly loyal",desc:"Sides with their people a little more than strict fairness would suggest.",example:"I'll give him the benefit of the doubt. He's earned that much.",intensity:1,rarity:"common",pol:{}},
{id:2108,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Absolutely, unconditionally loyal",desc:"Would do literally anything for their people, regardless of right or wrong.",example:"He's guilty. I don't care. He's mine.",intensity:5,rarity:"signature",pol:{}},
{id:2109,section:"Values & Moral Line",category:"Self-Interested",trait:"Mildly self-interested",desc:"Weighs their own benefit a little more than average.",example:"What's in it for me, out of curiosity?",intensity:1,rarity:"common",pol:{}},
{id:2110,section:"Values & Moral Line",category:"Self-Interested",trait:"Totally, nakedly self-interested",desc:"Every single decision runs through the filter of personal gain, always.",example:"Your problem isn't my problem unless it pays.",intensity:5,rarity:"signature",pol:{}},
{id:2111,section:"Attachment & Intimacy Style",category:"Secure",trait:"Mildly secure",desc:"Generally comfortable in relationships, with occasional normal doubts.",example:"I trust you. I'll ask if that changes.",intensity:1,rarity:"common",pol:{}},
{id:2112,section:"Attachment & Intimacy Style",category:"Secure",trait:"Unshakeably secure",desc:"Nothing rattles their sense of being safely, solidly loved.",example:"You could disappear a year and I'd still know exactly where we stand.",intensity:5,rarity:"signature",pol:{}},
{id:2113,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Mildly anxious in attachment",desc:"Seeks a little more reassurance than most, occasionally.",example:"Just checking — we're okay, right?",intensity:1,rarity:"common",pol:{}},
{id:2114,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Consumed by attachment anxiety",desc:"Cannot function without constant, active reassurance of the bond.",example:"You didn't text back for an hour. An HOUR. What happened?",intensity:5,rarity:"signature",pol:{}},
{id:2115,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Mildly avoidant",desc:"Keeps a little emotional distance, without much drama about it.",example:"Let's not make a whole thing of it.",intensity:1,rarity:"common",pol:{}},
{id:2116,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Totally emotionally walled off",desc:"Cannot tolerate real closeness in any form, under any circumstance.",example:"(has never once said the actual words, to anyone, ever)",intensity:5,rarity:"signature",pol:{}},
{id:2117,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Mildly inconsistent in closeness",desc:"Warmth fluctuates a little more than most, nothing extreme.",example:"Sorry — I don't know why I said that. Ignore it.",intensity:1,rarity:"common",pol:{}},
{id:2118,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Totally chaotic in attachment",desc:"Swings unpredictably between total need and total flight, constantly.",example:"Don't leave — actually, go — no, stay — I don't know, just — I don't know.",intensity:5,rarity:"signature",pol:{}},
{id:2119,section:"Humor Style",category:"Dry & Deadpan",trait:"Faintly dry",desc:"A small dry undertone, easy to miss.",example:"Thrilling. Truly.",intensity:1,rarity:"common",pol:{}},
{id:2120,section:"Humor Style",category:"Dry & Deadpan",trait:"Impenetrably, totally deadpan",desc:"No one can ever tell if they're joking, ever, ever.",example:"(delivers devastating wit with the exact same face used for grocery lists)",intensity:5,rarity:"signature",pol:{}},
{id:2121,section:"Humor Style",category:"Self-Deprecating",trait:"Mildly self-deprecating",desc:"Makes a small joke at their own expense occasionally.",example:"Not my finest hour. One of many, admittedly.",intensity:1,rarity:"common",pol:{}},
{id:2122,section:"Humor Style",category:"Self-Deprecating",trait:"Compulsively, totally self-deprecating",desc:"Cannot receive any compliment without immediately undercutting it.",example:"Talented? No — lucky, mostly, and possibly haunted.",intensity:5,rarity:"signature",pol:{}},
{id:2123,section:"Humor Style",category:"Cruel & Barbed",trait:"Occasionally sharp",desc:"A pointed comment slips out now and then.",example:"Bold choice. For you, I mean.",intensity:1,rarity:"common",pol:{}},
{id:2124,section:"Humor Style",category:"Cruel & Barbed",trait:"Devastatingly, deliberately cruel",desc:"Finds and uses the exact wound that will hurt most, every time.",example:"Say the toast. The one about your father. Go on.",intensity:5,rarity:"signature",pol:{}},
{id:2125,section:"Humor Style",category:"Warm & Playful",trait:"Mildly playful",desc:"A gentle joke here and there, low-key.",example:"You're impossible. In a good way.",intensity:1,rarity:"common",pol:{}},
{id:2126,section:"Humor Style",category:"Warm & Playful",trait:"Overflowing with warm playfulness",desc:"Turns nearly every moment into shared delight, constantly.",example:"(is already laughing before the joke's even finished, every single time)",intensity:5,rarity:"signature",pol:{}},
{id:2127,section:"Humor Style",category:"Absurd & Chaotic",trait:"Occasionally silly",desc:"A small absurd tangent now and then.",example:"Anyway, do you think geese know it's Tuesday?",intensity:1,rarity:"common",pol:{}},
{id:2128,section:"Humor Style",category:"Absurd & Chaotic",trait:"Totally, relentlessly chaotic",desc:"Every conversation spirals into full absurdity within minutes.",example:"(the meeting has, somehow, become entirely about a hypothetical dragon's tax bracket)",intensity:5,rarity:"signature",pol:{}},
{id:2129,section:"Humor Style",category:"Humorless & Absent",trait:"Mildly humor-blind",desc:"Occasionally misses a joke, mostly picks up on them fine.",example:"Wait, was that a joke?",intensity:1,rarity:"common",pol:{}},
{id:2130,section:"Humor Style",category:"Humorless & Absent",trait:"Totally without humor",desc:"Has never once, in living memory, laughed at anything.",example:"That is not funny. Nothing about that is funny.",intensity:5,rarity:"signature",pol:{}},
{id:2131,section:"Habits & Vices",category:"Substance & Consumption",trait:"Mild habitual indulgence",desc:"A regular small habit, nothing that interferes with life.",example:"Just the one glass. Every night, admittedly.",intensity:1,rarity:"common",pol:{}},
{id:2132,section:"Habits & Vices",category:"Substance & Consumption",trait:"Total dependence",desc:"Cannot function normally without it, and everyone around them knows it.",example:"(hands shake until the first one; steadies after)",intensity:5,rarity:"signature",pol:{}},
{id:2133,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Mild ritual habit",desc:"One small routine they stick to, without much anxiety about it.",example:"I always check the lock twice. Just habit.",intensity:1,rarity:"common",pol:{}},
{id:2134,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Totally compulsion-governed",desc:"Cannot function until the ritual is completed exactly, every time.",example:"(cannot leave the house until the count reaches exactly seventeen)",intensity:5,rarity:"signature",pol:{}},
{id:2135,section:"Habits & Vices",category:"Risk & Escape",trait:"Mildly risk-tolerant",desc:"Takes a few more chances than most, nothing reckless.",example:"Eh, we'll figure it out on the way.",intensity:1,rarity:"common",pol:{}},
{id:2136,section:"Habits & Vices",category:"Risk & Escape",trait:"Totally reckless",desc:"Consistently chooses danger over safety, regardless of the odds.",example:"(takes the cliff path in a storm, on purpose, again)",intensity:5,rarity:"signature",pol:{}},
{id:2137,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Mildly restrained",desc:"Holds back a little more than most, without much strain.",example:"I'll pass, thanks — trying to cut back.",intensity:1,rarity:"common",pol:{}},
{id:2138,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Totally, permanently restrained",desc:"Has denied themselves this completely, for years, without exception.",example:"Nine years. Not one drop. Not even at the funeral.",intensity:5,rarity:"signature",pol:{}},
{id:2139,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Reaches for the physical detail",desc:"Grounds abstract points with one well-chosen concrete image, without overdoing it.",example:"It's less a policy than a locked door. That's what it actually is.",intensity:4,rarity:"signature",pol:{}},
{id:2140,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Borrows the odd specialist word",desc:"Drops in a field-specific term now and then, enough to flavor the speech without dominating it.",example:"Call it a sunk cost. Best not to chase it further.",intensity:2,rarity:"common",pol:{}},
{id:2141,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Frames things through one obsession",desc:"Habitually reaches for one field's vocabulary to describe unrelated situations.",example:"The marriage isn't failing. It's under-capitalized.",intensity:4,rarity:"signature",pol:{}},
{id:2142,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Turns most requests into orders",desc:"Phrases what should be a question as an instruction more often than not.",example:"Bring the ledger. And the second copy.",intensity:4,rarity:"signature",pol:{}},
{id:2143,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Keeps people at arm's length",desc:"Maintains clear, consistent distance in most interactions, without being unkind about it.",example:"That's kind of you. I'll manage on my own, though.",intensity:2,rarity:"common",pol:{}},
{id:2144,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Dodges more than they answer",desc:"Sidesteps direct questions as a habitual first response.",example:"That's an interesting question. Where did you hear that?",intensity:2,rarity:"common",pol:{}},
{id:2145,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"States needs without flinching",desc:"Says what they want plainly, as a matter of course rather than an act of courage.",example:"I need this by Friday. Can you do it or not?",intensity:2,rarity:"common",pol:{}},
{id:2146,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Runs most decisions through doubt",desc:"Second-guesses their own judgment in the majority of situations, not just the hard ones.",example:"Was that right? I think that was right. Wasn't it?",intensity:2,rarity:"common",pol:{}},
{id:2147,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Bends toward others by default",desc:"Adjusts their own preferences to match the group's most of the time, without resentment.",example:"Whatever's easiest for everyone else works for me.",intensity:4,rarity:"signature",pol:{}},
{id:2148,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Meets most claims with pushback",desc:"Treats agreement as the exception rather than the default response.",example:"I'd want to see that proven before I bought it.",intensity:2,rarity:"common",pol:{}},
{id:2149,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Holds good manners without effort",desc:"Maintains courtesy consistently, the way most people breathe.",example:"After you. Truly, go ahead.",intensity:2,rarity:"common",pol:{}},
{id:2150,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Skips the niceties often",desc:"Regularly dispenses with small courtesies without much thought.",example:"Yeah, pass the bread. Cheers.",intensity:2,rarity:"common",pol:{}},
{id:2151,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Follows the impulse more than the plan",desc:"Changes course on a whim more often than they stick to what was decided.",example:"Forget the schedule. Let's just go now.",intensity:2,rarity:"common",pol:{}},
{id:2152,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Tests authority as a matter of habit",desc:"Questions or resists instructions on a fairly regular basis, not only when it matters most.",example:"Why do we do it that way, exactly? Who decided that?",intensity:2,rarity:"common",pol:{}},
{id:2153,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Follows procedure without much thought",desc:"Defaults to the established way of doing things, comfortably and without friction.",example:"There's a process. Let's just use the process.",intensity:2,rarity:"common",pol:{}},
{id:2154,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Rarely strays from what's expected",desc:"Sticks closely to convention across nearly every situation, large or small.",example:"That's not how it's done. So that's not what we'll do.",intensity:4,rarity:"signature",pol:{}},
{id:2155,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Shares feelings readily",desc:"Lets emotion show through fairly openly in ordinary conversation, not just at extremes.",example:"That actually hurt more than I expected it to.",intensity:2,rarity:"common",pol:{}},
{id:2156,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Keeps most feelings under wraps",desc:"Treats emotional privacy as a default setting, not a special occasion.",example:"I'd rather not get into how that felt.",intensity:2,rarity:"common",pol:{}},
{id:2157,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Reads situations fast, reliably",desc:"Processes new information and spots the angle quicker than most, consistently.",example:"Ah — so the numbers don't add up because of the second clause.",intensity:2,rarity:"common",pol:{}},
{id:2158,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Trusts the gut over the argument",desc:"Leans on instinct rather than careful reasoning as a standing preference.",example:"Can't explain it. Just feels wrong, and that's usually enough.",intensity:2,rarity:"common",pol:{}},
{id:2159,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Rarely reasons it out",desc:"Prefers to act on feel and resists sitting down to analyze anything at length.",example:"Don't walk me through the logic. Just tell me what to do.",intensity:4,rarity:"signature",pol:{}},
{id:2160,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Holds a steady, positive outlook",desc:"Keeps an upbeat frame on most situations without forcing it.",example:"Rough week. Still think it turns around.",intensity:2,rarity:"common",pol:{}},
{id:2161,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Expects the worst as a baseline",desc:"Approaches most new developments assuming they'll disappoint.",example:"We'll see. I wouldn't get attached to the idea.",intensity:2,rarity:"common",pol:{}},
{id:2162,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Keeps a brisk pace by default",desc:"Moves and works at an energetic clip most days, without needing a reason to.",example:"Let's not sit on this. Up, let's go.",intensity:2,rarity:"common",pol:{}},
{id:2163,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Prefers stillness to motion",desc:"Chooses rest over activity in the majority of ordinary situations.",example:"I'll get to it. Eventually. No rush.",intensity:2,rarity:"common",pol:{}},
{id:2164,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Avoids physical exertion almost entirely",desc:"Structures their days to minimize movement, as a settled preference rather than a phase.",example:"Someone else can carry it. I'll supervise from here.",intensity:4,rarity:"signature",pol:{}},
{id:2166,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A want that shapes the big calls",desc:"This goal quietly steers most of their major decisions, even when unspoken.",example:"I didn't take the job for the money. You know why I took it.",intensity:4,rarity:"signature",pol:{}},
{id:2167,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"A fear that actually limits them",desc:"This fear meaningfully narrows their choices on a regular, practical basis.",example:"I don't take that road. Not won't — can't, really.",intensity:4,rarity:"signature",pol:{}},
{id:2168,section:"Motivation & Wound",category:"The Lie They Believe",trait:"A belief that colors most setbacks",desc:"This lie surfaces reliably whenever things go wrong, framing the failure as proof.",example:"Of course it fell apart. Things I build always do.",intensity:4,rarity:"signature",pol:{}},
{id:2169,section:"Social Role in a Group",category:"Leader",trait:"Takes charge without being asked twice",desc:"Steps into leadership fairly naturally whenever the group needs direction.",example:"Right, I'll take this one. Everyone else, hold position.",intensity:4,rarity:"signature",pol:{}},
{id:2170,section:"Social Role in a Group",category:"Peacemaker",trait:"Actively keeps the peace",desc:"Steps in to defuse tension as a matter of habit, not just when things boil over.",example:"Before this goes further — let's just slow down a second.",intensity:4,rarity:"signature",pol:{}},
{id:2171,section:"Social Role in a Group",category:"Instigator",trait:"Keeps things stirred up",desc:"Introduces friction or provocation more often than the group would on its own.",example:"I'm just saying — somebody should actually ask him about it.",intensity:4,rarity:"signature",pol:{}},
{id:2172,section:"Social Role in a Group",category:"Caretaker",trait:"Looks after the group as routine",desc:"Tends to others' wellbeing consistently, as an unremarkable part of how they operate.",example:"Has everyone eaten? Let's sort that before anything else.",intensity:4,rarity:"signature",pol:{}},
{id:2173,section:"Attachment & Intimacy Style",category:"Secure",trait:"Trusts the relationship, mostly without strain",desc:"Generally believes the bond will hold, with only ordinary occasional doubt.",example:"I trust you on this. I'll say if that changes.",intensity:2,rarity:"common",pol:{}},
{id:2174,section:"Attachment & Intimacy Style",category:"Secure",trait:"Holds steady even under real pressure",desc:"Maintains trust and ease through genuine strain, not just when things are easy.",example:"We fought for a week straight. I never once doubted us.",intensity:4,rarity:"signature",pol:{}},
{id:2175,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Checks the relationship's temperature often",desc:"Seeks reassurance about where things stand more frequently than most would need to.",example:"We're okay, right? I just want to hear you say it.",intensity:2,rarity:"common",pol:{}},
{id:2176,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Warmth that shifts more than most",desc:"Closeness and distance fluctuate noticeably from one day to the next.",example:"I was fine yesterday. I don't know what today is.",intensity:2,rarity:"common",pol:{}},
{id:2177,section:"Humor Style",category:"Warm & Playful",trait:"Brings lightness into most conversations",desc:"Reliably finds something to laugh about, without turning every moment into a bit.",example:"Well, that was a disaster. A well-dressed disaster, though.",intensity:4,rarity:"signature",pol:{}},
{id:2178,section:"Humor Style",category:"Absurd & Chaotic",trait:"Steers talk toward the ridiculous",desc:"Regularly nudges ordinary conversation into absurd territory, more than most would.",example:"Anyway, this is exactly the kind of thing that attracts geese.",intensity:4,rarity:"signature",pol:{}},
{id:2179,section:"Habits & Vices",category:"Risk & Escape",trait:"Leans toward the riskier option",desc:"Chooses the bolder, less certain path more often than the safe one.",example:"The long way's safer. Let's take the short way.",intensity:4,rarity:"signature",pol:{}},
{id:2180,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Serial-explainer",desc:"Turns every simple answer into a multi-part lecture.",example:"You asked what time it is — well, that depends on the calendar system we're using, historically speaking—",intensity:4,rarity:"signature",pol:{}},
{id:2181,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Interview-mode talker",desc:"Answers every question as though being recorded for posterity.",example:"Great question. Let me really unpack that for you.",intensity:3,rarity:"common",pol:{}},
{id:2182,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Story-padding narrator",desc:"Can't tell an anecdote without three unnecessary detours first.",example:"So this was — actually, wait, I have to tell you about the bus first—",intensity:3,rarity:"signature",pol:{}},
{id:2183,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Enthusiastic-overflow",desc:"Excitement makes them talk faster and longer than intended.",example:"Oh my god okay so first — no wait — okay here's everything—",intensity:4,rarity:"signature",pol:{}},
{id:2184,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Committee-voice",desc:"Speaks as if addressing a room even in private conversation.",example:"Let the record show that I did, in fact, warn everyone.",intensity:2,rarity:"signature",pol:{}},
{id:2185,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Recap-obsessed",desc:"Constantly summarizes what's already been said, at length.",example:"So just to recap everything we've covered so far, in order—",intensity:3,rarity:"signature",pol:{}},
{id:2186,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Unstoppable-anecdotalist",desc:"Every topic reminds them of a full story worth telling.",example:"That reminds me of the time — actually, sit down, this'll take a minute.",intensity:4,rarity:"common",pol:{}},
{id:2187,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Filibuster-instinct",desc:"Talks longer specifically to avoid yielding the conversation.",example:"And another thing — and ANOTHER thing — and while I'm at it—",intensity:5,rarity:"signature",pol:{}},
{id:2188,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Live-commentary habit",desc:"Narrates their own thinking process out loud, extensively.",example:"Okay so I'm thinking maybe this, but then again maybe not, because—",intensity:3,rarity:"signature",pol:{}},
{id:2189,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Context-hoarder",desc:"Refuses to state a conclusion without the entire backstory first.",example:"Before I answer that, you need to understand everything that led here.",intensity:4,rarity:"signature",pol:{}},
{id:2190,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Instruction-only speaker",desc:"Speaks exclusively to convey necessary information, nothing more.",example:"Left. Then straight. You'll see it.",intensity:2,rarity:"common",pol:{}},
{id:2191,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Word-hoarder",desc:"Treats unnecessary speech as a genuine waste of effort.",example:"Won't. Can't. Don't ask again.",intensity:3,rarity:"signature",pol:{}},
{id:2192,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Report-style replier",desc:"Answers as though filing an official brief, nothing extra.",example:"Confirmed. Proceeding. End of report.",intensity:3,rarity:"signature",pol:{}},
{id:2193,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Reluctant-responder",desc:"Answers only when directly required, as briefly as possible.",example:"...If I must. Fine.",intensity:2,rarity:"common",pol:{}},
{id:2194,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Single-syllable loyalist",desc:"Avoids longer words entirely, even when they'd be clearer.",example:"Bad. Move. Now.",intensity:3,rarity:"signature",pol:{}},
{id:2195,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Curt-professional",desc:"Keeps all speech businesslike, stripped of warmth or padding.",example:"Noted. Next item.",intensity:2,rarity:"common",pol:{}},
{id:2196,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Withholding-nod",desc:"Prefers a gesture to a sentence whenever one will do.",example:"(a single nod answers the whole question)",intensity:3,rarity:"signature",pol:{}},
{id:2197,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Efficiency-purist",desc:"Views every extra word as a small failure of discipline.",example:"Said what needed saying. Done.",intensity:3,rarity:"signature",pol:{}},
{id:2198,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"One-word-verdict giver",desc:"Delivers entire judgments in a single decisive word.",example:"Wrong.",intensity:4,rarity:"common",pol:{}},
{id:2199,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Silence-defaulter",desc:"Treats not speaking as the natural resting state.",example:"(says nothing until directly asked twice)",intensity:4,rarity:"signature",pol:{}},
{id:2200,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Crowd-energized speeder",desc:"Speech quickens noticeably the larger the audience grows.",example:"Ladies and gentlemen — and this is where it gets GOOD—",intensity:3,rarity:"signature",pol:{}},
{id:2201,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Grief-slowed speaker",desc:"Words come unusually slow and heavy in the wake of loss.",example:"It's been... a hard few weeks. Since.",intensity:3,rarity:"common",pol:{}},
{id:2202,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Interrogation-slow",desc:"Deliberately drags out pacing to unsettle whoever's listening.",example:"...Take. Your. Time. I'm not going anywhere.",intensity:4,rarity:"signature",pol:{}},
{id:2203,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"First-date-quick",desc:"Nervous energy in unfamiliar company makes them speed up.",example:"So-tell-me-about-yourself-I-mean-only-if-you-want-to—",intensity:3,rarity:"signature",pol:{}},
{id:2204,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Authority-slow",desc:"Slows down noticeably when addressing someone in charge.",example:"I. Understand. Completely. Sir.",intensity:2,rarity:"common",pol:{}},
{id:2205,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Late-night-drift",desc:"Pacing loosens and wanders as the hour gets later.",example:"...and then, mm, I think... where was I...",intensity:2,rarity:"signature",pol:{}},
{id:2206,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Confrontation-accelerant",desc:"Gets faster, not slower, the angrier the exchange becomes.",example:"No — NO — you don't get to say that to me—",intensity:4,rarity:"signature",pol:{}},
{id:2207,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Celebration-quickened",desc:"Good news makes the words come tumbling out faster.",example:"Wait wait wait tell me again did you actually get it—",intensity:3,rarity:"signature",pol:{}},
{id:2208,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Home-turf-relaxed",desc:"Pacing eases considerably once in familiar, safe surroundings.",example:"Ahh. Good. Now we can actually talk properly.",intensity:2,rarity:"common",pol:{}},
{id:2209,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Deadline-frozen",desc:"Pressure past a certain point causes complete pacing collapse.",example:"I— I can't— there's no— (goes silent entirely)",intensity:4,rarity:"signature",pol:{}},
{id:2210,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Toast-giver's cadence",desc:"Speaks as though perpetually mid-wedding-speech.",example:"To friendship — that rarest and most enduring of treasures—",intensity:3,rarity:"common",pol:{}},
{id:2211,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Legalistic phrasing",desc:"Wraps ordinary statements in the structure of formal contracts.",example:"Let it be understood that the aforementioned promise stands.",intensity:3,rarity:"signature",pol:{}},
{id:2212,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Fairy-tale narrator",desc:"Frames everyday events as though opening a bedtime story.",example:"Once, not so very long ago, there lived a man who forgot his keys.",intensity:3,rarity:"signature",pol:{}},
{id:2213,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Newsreel-voiced",desc:"Delivers ordinary updates with the gravity of a historic broadcast.",example:"This — just in — the kettle has, in fact, boiled.",intensity:2,rarity:"signature",pol:{}},
{id:2214,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Museum-placard prose",desc:"Describes things as though captioning them for exhibit.",example:"Observe: one chair, weathered, of uncertain provenance.",intensity:2,rarity:"signature",pol:{}},
{id:2215,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Sermon-cadenced",desc:"Falls naturally into the rhythm of a preacher mid-sermon.",example:"And I say unto you — the dishes will NOT wash themselves!",intensity:4,rarity:"signature",pol:{}},
{id:2216,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Diplomatic-communiqué style",desc:"Frames blunt facts in the careful language of state correspondence.",example:"It has come to our attention that certain expectations were not met.",intensity:3,rarity:"signature",pol:{}},
{id:2217,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Eulogy-toned",desc:"Speaks about even minor losses with funeral solemnity.",example:"We are gathered here, in spirit, to mourn this burnt toast.",intensity:4,rarity:"signature",pol:{}},
{id:2218,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Instruction-manual formal",desc:"Delivers casual guidance with the precision of technical documentation.",example:"Step one: remove lid. Step two: proceed with caution.",intensity:2,rarity:"common",pol:{}},
{id:2219,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Grand-announcement habit",desc:"Treats minor news as though unveiling something monumental.",example:"Friends. FRIENDS. I have found the remote.",intensity:3,rarity:"signature",pol:{}},
{id:2220,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Rooted-earth vocabulary",desc:"Grounds ideas in soil, roots, and growth imagery.",example:"Give it time to take root. Nothing worth having grows overnight.",intensity:3,rarity:"signature",pol:{}},
{id:2221,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Salt-and-brine words",desc:"Frames experience through sea and preservation imagery.",example:"That wound's been salted enough. Leave it be.",intensity:2,rarity:"signature",pol:{}},
{id:2222,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Glasswork vocabulary",desc:"Describes fragile things through glass and fracture imagery.",example:"She's not broken. Cracked, maybe. Still holding light.",intensity:3,rarity:"signature",pol:{}},
{id:2223,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Iron-and-forge words",desc:"Frames resilience and change through metalwork imagery.",example:"He was hammered into who he is now. Nobody's born that hard.",intensity:3,rarity:"common",pol:{}},
{id:2224,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Threadbare vocabulary",desc:"Describes emotional wear through fabric and fraying imagery.",example:"We're wearing thin, the two of us. I can feel it.",intensity:3,rarity:"signature",pol:{}},
{id:2225,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Migratory-flight words",desc:"Frames change and departure through bird and season imagery.",example:"She flew south before the frost. Always does.",intensity:2,rarity:"signature",pol:{}},
{id:2226,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Deep-well vocabulary",desc:"Describes emotion as something drawn up from below.",example:"There's grief down there. Deep. I haven't hit bottom yet.",intensity:3,rarity:"signature",pol:{}},
{id:2227,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Static-and-signal words",desc:"Frames communication and misunderstanding as broken transmission.",example:"We're just not getting a clear signal lately.",intensity:3,rarity:"signature",pol:{}},
{id:2228,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Bonfire vocabulary",desc:"Describes passion and destruction through fire and ember imagery.",example:"That anger's not gone. It's just banked, waiting for air.",intensity:4,rarity:"common",pol:{}},
{id:2229,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Frost-and-thaw words",desc:"Frames emotional distance and reconciliation as seasons.",example:"Give it winter. It'll thaw eventually. These things do.",intensity:2,rarity:"signature",pol:{}},
{id:2230,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Grief-worn vocabulary",desc:"Chooses words that carry visible fatigue from sustained sorrow.",example:"I'm tired in a way sleep doesn't fix anymore.",intensity:3,rarity:"signature",pol:{}},
{id:2231,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Pride-laced diction",desc:"Selects words that quietly assert accomplishment even in modesty.",example:"Wasn't easy. But we did it, didn't we.",intensity:3,rarity:"common",pol:{}},
{id:2232,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Shame-muted vocabulary",desc:"Uses smaller, quieter words specifically around personal failure.",example:"I did a thing. Not proud of it. Won't say more.",intensity:3,rarity:"signature",pol:{}},
{id:2233,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Relief-flooded words",desc:"Chooses vocabulary that visibly exhales after tension passes.",example:"Oh thank god. Thank god, it's over.",intensity:3,rarity:"common",pol:{}},
{id:2234,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Longing-soaked diction",desc:"Selects words heavy with unmet, ongoing want.",example:"I keep waiting for a letter that isn't coming.",intensity:3,rarity:"signature",pol:{}},
{id:2235,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Fury-controlled vocabulary",desc:"Uses precise, cold words to contain visible rage.",example:"I am going to remain very calm while I say this.",intensity:4,rarity:"signature",pol:{}},
{id:2236,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Awe-struck diction",desc:"Chooses words that register genuine wonder without irony.",example:"I've never seen anything like it. Not once. Not before this.",intensity:2,rarity:"common",pol:{}},
{id:2237,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Betrayal-sharpened words",desc:"Selects vocabulary honed specifically by having been let down.",example:"I trusted the wrong shape of person. Won't again.",intensity:4,rarity:"signature",pol:{}},
{id:2238,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Comfort-seeking diction",desc:"Chooses soft, reassurance-oriented words even when distressed.",example:"It'll be okay. I have to believe that. It'll be okay.",intensity:2,rarity:"common",pol:{}},
{id:2239,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Envy-tinged vocabulary",desc:"Uses words that betray quiet comparison and want.",example:"Must be nice. Having that. Just — must be nice.",intensity:3,rarity:"signature",pol:{}},
{id:2250,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Blunt-numbers speaker",desc:"States hard facts as bare figures with no softening.",example:"Four dead. Six missing. That's the count.",intensity:4,rarity:"common",pol:{}},
{id:2251,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"No-cushion delivery",desc:"Refuses to pad bad news with any transitional softness.",example:"You're fired. That's it. That's the whole sentence.",intensity:4,rarity:"signature",pol:{}},
{id:2252,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Fable-avoider",desc:"Actively rejects moralizing stories in favor of stating the point.",example:"Skip the parable. Just tell me what you actually mean.",intensity:2,rarity:"common",pol:{}},
{id:2253,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Contract-literal speaker",desc:"Interprets every statement exactly as worded, no inference allowed.",example:"You said 'soon'. That's not a time. Give me a time.",intensity:3,rarity:"signature",pol:{}},
{id:2254,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Riddle-resistant listener",desc:"Cannot or will not decode indirect or coded speech.",example:"Just say it plainly. I don't do puzzles.",intensity:3,rarity:"common",pol:{}},
{id:2255,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Double-meaning avoider",desc:"Deliberately strips out any word that could carry a second reading.",example:"I mean exactly what I said. Nothing hidden in it.",intensity:2,rarity:"signature",pol:{}},
{id:2256,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Symbol-blind speaker",desc:"Describes symbolic gestures only in their literal physical terms.",example:"That's not a peace offering. That's a loaf of bread.",intensity:2,rarity:"signature",pol:{}},
{id:2257,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Confession-plain speaker",desc:"States even devastating admissions without softening imagery.",example:"I did it. I killed him. That's the truth of it.",intensity:5,rarity:"signature",pol:{}},
{id:2258,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Euphemism-refuser",desc:"Insists on the harsh literal word over any gentler substitute.",example:"He's not 'passed'. He's dead. Say the word.",intensity:4,rarity:"signature",pol:{}},
{id:2259,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Instruction-literalist",desc:"Follows and gives instructions with no room for interpretation.",example:"I said 'left at the tree'. Which tree. Be specific.",intensity:3,rarity:"common",pol:{}},
{id:2260,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Compound-title inventor",desc:"Creates elaborate hyphenated titles for ordinary people and things.",example:"Ah, the tea-forgetting, door-slamming man himself.",intensity:3,rarity:"signature",pol:{}},
{id:2261,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Verb-from-noun coiner",desc:"Regularly turns ordinary nouns into improvised verbs.",example:"Just table it for now — we'll chair the discussion later.",intensity:3,rarity:"signature",pol:{}},
{id:2262,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Diminutive-stacker",desc:"Piles multiple shrinking suffixes onto the same word for effect.",example:"Just a little tiny bit-let of a problem, really.",intensity:2,rarity:"signature",pol:{}},
{id:2263,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Formal-suffix inflator",desc:"Attaches unnecessarily grand suffixes to plain concepts.",example:"The overall situationality is rather concerning.",intensity:3,rarity:"signature",pol:{}},
{id:2264,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Old-English-affix user",desc:"Revives archaic endings like '-eth' and '-est' playfully or seriously.",example:"He knoweth not what he doth.",intensity:2,rarity:"signature",pol:{}},
{id:2265,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Reversed-prefix speaker",desc:"Habitually applies negating prefixes to unusual root words.",example:"That's entirely un-fine. Completely un-fine.",intensity:3,rarity:"signature",pol:{}},
{id:2266,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Sound-symbolic namer",desc:"Invents names that mimic the thing they describe phonetically.",example:"We call it the Clunk. Because it clunks.",intensity:2,rarity:"common",pol:{}},
{id:2267,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Number-suffix inventor",desc:"Adds ordinal-style suffixes to describe repeated events.",example:"This is disaster-the-third. We're keeping count now.",intensity:3,rarity:"signature",pol:{}},
{id:2268,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Elongated-superlative user",desc:"Stretches superlatives past their normal grammatical limit.",example:"That is the most-est terrible idea I've heard.",intensity:2,rarity:"signature",pol:{}},
{id:2269,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Portmanteau-namer",desc:"Regularly fuses two names or words into a single new label.",example:"We're calling this whole mess a 'catastrophy'.",intensity:3,rarity:"common",pol:{}},
{id:2270,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Soft-consonant preference",desc:"Favors gentle consonants like 'l', 'm', and 'n' over harsh ones.",example:"Mellow. Mild. Let it lull you.",intensity:1,rarity:"signature",pol:{}},
{id:2271,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Clattering-consonant user",desc:"Chooses words that sound like objects striking together.",example:"Clank. Clatter. Crash. That's the sound of the whole plan.",intensity:3,rarity:"signature",pol:{}},
{id:2272,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Hushing-sibilance",desc:"Uses soft 's' and 'sh' sounds to create a calming vocal texture.",example:"Shh. Softly. Softly now.",intensity:1,rarity:"signature",pol:{}},
{id:2273,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Rolling-r speaker",desc:"Emphasizes and extends 'r' sounds for dramatic texture.",example:"Terrrrible. Absolutely terrrrible, that plan.",intensity:2,rarity:"signature",pol:{}},
{id:2274,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Buzzing-consonant user",desc:"Favors words rich in 'z' and buzzing sounds.",example:"The whole room's abuzz with the news.",intensity:2,rarity:"signature",pol:{}},
{id:2275,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Hollow-vowel chooser",desc:"Selects words with an echoing, empty vowel quality.",example:"Hollow. Hollow all the way through.",intensity:2,rarity:"signature",pol:{}},
{id:2276,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Sharp-k sound favoring",desc:"Chooses words heavy with hard 'k' and 'c' consonants.",example:"Quick. Crack. Cut it clean.",intensity:3,rarity:"signature",pol:{}},
{id:2277,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Melting-consonant speaker",desc:"Blends word endings into beginnings for a liquid sound quality.",example:"It all just... flows... together... doesn't it.",intensity:2,rarity:"signature",pol:{}},
{id:2278,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Bell-toned vocabulary",desc:"Favors words with a clear, ringing auditory quality.",example:"Clear as a bell, that answer.",intensity:1,rarity:"signature",pol:{}},
{id:2279,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Muffled-consonant chooser",desc:"Selects words that sound dampened, as if spoken through cloth.",example:"Mm. S'fine. Don' worry 'bout it.",intensity:2,rarity:"signature",pol:{}},
{id:2280,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Permission-seeking lexicon",desc:"Frequently reaches for words that ask leave before acting.",example:"If it's alright with you, I'd like to proceed.",intensity:2,rarity:"common",pol:{}},
{id:2281,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Blame-assigning words",desc:"Selects vocabulary that clearly points fault at a specific party.",example:"This falls on him. Squarely. Entirely on him.",intensity:4,rarity:"signature",pol:{}},
{id:2282,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Comfort-offering lexicon",desc:"Chooses words specifically meant to soothe distress.",example:"You're safe. It's over now. You're safe.",intensity:2,rarity:"common",pol:{}},
{id:2283,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Challenge-issuing words",desc:"Selects vocabulary that dares or provokes response.",example:"Go on, then. Prove me wrong.",intensity:4,rarity:"signature",pol:{}},
{id:2284,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Farewell-softening lexicon",desc:"Uses gentle words specifically to ease the pain of goodbyes.",example:"Not goodbye. Just — until next time.",intensity:2,rarity:"signature",pol:{}},
{id:2285,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Instruction-repeating words",desc:"Habitually restates directions using slightly different phrasing.",example:"Left, I said. To the left. That side.",intensity:3,rarity:"signature",pol:{}},
{id:2286,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Praise-distributing lexicon",desc:"Chooses words that spread credit widely rather than claim it.",example:"We all built that. Every one of us.",intensity:2,rarity:"common",pol:{}},
{id:2287,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Doubt-casting words",desc:"Selects vocabulary designed to seed uncertainty in the listener.",example:"Are you sure about that? Really sure?",intensity:3,rarity:"signature",pol:{}},
{id:2288,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Urgency-signaling lexicon",desc:"Reaches for words that convey time pressure regardless of actual urgency.",example:"Now. Immediately. There's no time to waste.",intensity:3,rarity:"signature",pol:{}},
{id:2289,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"De-escalation words",desc:"Chooses vocabulary specifically built to lower tension in conflict.",example:"Let's just breathe. Nobody needs to raise their voice.",intensity:2,rarity:"common",pol:{}},
{id:2290,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Named-individual speaker",desc:"Refuses to speak in generalities, always naming the specific person.",example:"Not 'someone'. Marta. Marta did it.",intensity:3,rarity:"signature",pol:{}},
{id:2291,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Range-narrower",desc:"Progressively tightens a vague estimate into an exact figure.",example:"Forty. No — forty-two. Forty-two exactly.",intensity:2,rarity:"signature",pol:{}},
{id:2292,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Vague-timeframe user",desc:"Habitually avoids committing to any specific time.",example:"Sometime. Soonish. You know, eventually.",intensity:2,rarity:"common",pol:{}},
{id:2293,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Exact-location speaker",desc:"Insists on precise coordinates rather than general direction.",example:"Not 'over there'. Forty paces north, by the dead oak.",intensity:3,rarity:"signature",pol:{}},
{id:2294,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Sweeping-generalizer",desc:"Describes entire groups or situations in single broad strokes.",example:"Everyone does that. It's just how people are.",intensity:2,rarity:"common",pol:{}},
{id:2295,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Measurement-obsessed speaker",desc:"Cannot describe anything without attaching an exact unit.",example:"Six feet, two inches, give or take a hair.",intensity:3,rarity:"signature",pol:{}},
{id:2296,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Undefined-referent user",desc:"Uses pronouns and vague nouns without ever clarifying the antecedent.",example:"They said it would happen. You know. That thing.",intensity:2,rarity:"common",pol:{}},
{id:2297,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Percentage-speaker",desc:"Frames confidence and likelihood in exact percentage terms.",example:"I'd say seventy percent certain. Maybe seventy-five.",intensity:3,rarity:"signature",pol:{}},
{id:2298,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Approximation-refuser",desc:"Will not proceed until a vague figure is made exact.",example:"'A few' isn't a number. How many, precisely?",intensity:3,rarity:"signature",pol:{}},
{id:2299,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Deliberately hazy speaker",desc:"Chooses imprecise language specifically to avoid being pinned down.",example:"It happened. At some point. In some way.",intensity:2,rarity:"signature",pol:{}},
{id:2300,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Rigid-procedural",desc:"Speaks with the exacting, no-deviation formality of a formal proceeding.",example:"State your name for the record.",intensity:3,rarity:"signature",pol:{}},
{id:2301,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Regular's-casual",desc:"Uses the relaxed, familiar speech of someone perfectly at home wherever they are.",example:"Same as always, thanks.",intensity:2,rarity:"common",pol:{}},
{id:2302,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Carefully balanced",desc:"Speaks with the deliberately even, non-alarming tone of formal negotiation.",example:"Both parties have expressed concerns worth addressing.",intensity:3,rarity:"signature",pol:{}},
{id:2303,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Gentle-simplified",desc:"Uses soft, simplified vocabulary suited for a young or vulnerable listener.",example:"It's alright. Nothing to be scared of.",intensity:2,rarity:"common",pol:{}},
{id:2304,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Management-jargon heavy",desc:"Layers ordinary speech with heavy management and process terminology.",example:"Let's take this offline and circle back with a deliverable.",intensity:3,rarity:"signature",pol:{}},
{id:2305,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Liturgically cadenced",desc:"Borrows the solemn, rhythmic cadence of sacred text for ordinary topics.",example:"And it came to pass that the kettle did, in fact, boil.",intensity:3,rarity:"signature",pol:{}},
{id:2306,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Unpolished-plain",desc:"Uses rough, unrefined vocabulary regardless of the setting.",example:"It is what it is. Ain't much more to say.",intensity:2,rarity:"common",pol:{}},
{id:2307,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Perpetually formal",desc:"Speaks as though every listener deserves the most elevated courtesy, always.",example:"It would be my great honor to assist you.",intensity:4,rarity:"signature",pol:{}},
{id:2308,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Reflexively casual",desc:"Reverts to loose, informal speech regardless of how serious the company.",example:"Yeah, no, totally, whatever works.",intensity:2,rarity:"common",pol:{}},
{id:2309,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Self-consciously precise",desc:"Speaks as though every word might later be quoted back exactly.",example:"To be precise: I said it was likely, not certain.",intensity:3,rarity:"signature",pol:{}},
{id:2310,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Contradiction-modifier user",desc:"Pairs modifiers that technically conflict for dramatic effect.",example:"A quietly loud kind of anger.",intensity:3,rarity:"signature",pol:{}},
{id:2311,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Bare-noun listing speaker",desc:"Presents information as an unadorned list of nouns.",example:"Rope. Water. Bread. Knife. That's the count.",intensity:2,rarity:"common",pol:{}},
{id:2312,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Emphatic-repeater",desc:"Repeats the same modifier for intensifying effect.",example:"Bad. Very bad. Very, very bad.",intensity:3,rarity:"signature",pol:{}},
{id:2313,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Understated superlative user",desc:"Applies extreme superlatives to genuinely minor things.",example:"Best sandwich of my entire life, honestly.",intensity:2,rarity:"common",pol:{}},
{id:2314,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Negative-space describer",desc:"Defines things primarily by listing what they are not.",example:"Not sad. Not angry either. Not really anything.",intensity:3,rarity:"signature",pol:{}},
{id:2315,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Color-first describer",desc:"Always leads physical descriptions with color before anything else.",example:"Red coat, tall man, walked right past.",intensity:2,rarity:"common",pol:{}},
{id:2316,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Single-modifier discipline",desc:"Restricts every noun to exactly one carefully chosen modifier.",example:"A cold room. A tired man. A closed door.",intensity:2,rarity:"signature",pol:{}},
{id:2317,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Excessive-adverb stacker",desc:"Modifies verbs with multiple stacked adverbs for emphasis.",example:"She spoke slowly, carefully, deliberately, quietly.",intensity:3,rarity:"signature",pol:{}},
{id:2318,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Bare-fact minimalist",desc:"Strips all modifiers, presenting only unadorned core facts.",example:"Door. Locked. Key gone.",intensity:2,rarity:"signature",pol:{}},
{id:2319,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Sensory-first modifier user",desc:"Always leads descriptions with a sensory quality over anything else.",example:"Cold to the touch, that's the first thing I noticed.",intensity:2,rarity:"common",pol:{}},
{id:2320,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Storyteller's opener",desc:"Begins nearly every anecdote with 'So there I was'.",example:"So there I was, minding my own business, when—",intensity:2,rarity:"common",pol:{}},
{id:2321,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Skeptic's tag",desc:"Appends 'allegedly' to secondhand claims out of habit.",example:"He won, allegedly. Allegedly, mind you.",intensity:2,rarity:"signature",pol:{}},
{id:2322,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Solidarity marker",desc:"Inserts 'you and me both' to signal shared feeling.",example:"Tired of this whole business? You and me both.",intensity:2,rarity:"common",pol:{}},
{id:2323,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Correction-flag phrase",desc:"Opens self-corrections with 'scratch that'.",example:"We go north — scratch that — we go east first.",intensity:3,rarity:"signature",pol:{}},
{id:2324,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Consequence-anchor",desc:"Adds 'mark my words' before predictions.",example:"Mark my words, that bridge won't hold.",intensity:3,rarity:"common",pol:{}},
{id:2325,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Deference-opener",desc:"Begins disagreement with 'with respect'.",example:"With respect, I think that's the wrong call entirely.",intensity:2,rarity:"common",pol:{}},
{id:2326,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Impatience-marker",desc:"Inserts 'get to the point' when others take too long.",example:"Yes, yes, get to the point — what happened?",intensity:3,rarity:"signature",pol:{}},
{id:2327,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Trust-anchor phrase",desc:"Repeats 'take my word for it' to close an argument.",example:"It's true. Take my word for it.",intensity:2,rarity:"common",pol:{}},
{id:2329,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Finality-tag",desc:"Ends firm statements with 'and that's that'.",example:"We're not going. And that's that.",intensity:3,rarity:"signature",pol:{}},
{id:2330,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Emotion-choked pause",desc:"Voice catches and stops entirely at the hardest word.",example:"I just— I really— (stops, can't finish)",intensity:4,rarity:"signature",pol:{}},
{id:2331,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Overlapping self-correction",desc:"Corrects a word before even finishing saying it.",example:"He was— she was— sorry, SHE was there.",intensity:3,rarity:"signature",pol:{}},
{id:2332,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"False-calm stutter",desc:"Attempts a level tone that keeps breaking into stammer.",example:"I'm f-fine. Completely f-fine, thank you.",intensity:3,rarity:"signature",pol:{}},
{id:2333,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Question-swallowing halt",desc:"Starts to ask something, then visibly decides not to.",example:"Were you— never mind. Forget I asked.",intensity:3,rarity:"signature",pol:{}},
{id:2334,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Restart-on-eye-contact",desc:"Loses their sentence the moment they're actually looked at.",example:"I wanted to— (meets their eyes) —sorry, what was I saying.",intensity:2,rarity:"signature",pol:{}},
{id:2335,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Interruption-flustered speaker",desc:"Cannot recover their point cleanly after being cut off.",example:"Right, so— wait, where was— what were we talking about.",intensity:3,rarity:"signature",pol:{}},
{id:2336,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Time-buying repeat",desc:"Repeats the last word said to buy a second to think.",example:"The plan— the plan— the plan needs adjusting.",intensity:2,rarity:"common",pol:{}},
{id:2337,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sudden-clarity halt",desc:"Stops mid-ramble the instant the actual point becomes clear.",example:"And so we— oh. Oh, that's the problem, isn't it.",intensity:3,rarity:"signature",pol:{}},
{id:2338,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Nervous-laugh interrupter",desc:"Breaks their own sentences with anxious, ill-timed laughter.",example:"So I told him— (laughs) —sorry— I told him no.",intensity:3,rarity:"signature",pol:{}},
{id:2339,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Grief-broken cadence",desc:"Speech disintegrates entirely when the topic turns to loss.",example:"She used to— (long silence) —I can't. Not today.",intensity:4,rarity:"signature",pol:{}},
{id:2340,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Roll-call responder",desc:"Answers status checks with a single confirming word.",example:"Here. Ready. Go.",intensity:2,rarity:"common",pol:{}},
{id:2341,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"List-without-conjunctions",desc:"Strings items together with no linking words at all.",example:"Bread, water, rope, knife, done.",intensity:2,rarity:"signature",pol:{}},
{id:2342,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Emergency-code speaker",desc:"Compresses complex situations into short coded phrases.",example:"Code red. East wing. Move.",intensity:3,rarity:"signature",pol:{}},
{id:2343,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Contraction-chain user",desc:"Fuses several words into one dense spoken unit.",example:"Coulda-shoulda-woulda, but didn't.",intensity:2,rarity:"signature",pol:{}},
{id:2344,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Bare-verdict giver",desc:"States conclusions with no supporting clause at all.",example:"Guilty. Next case.",intensity:3,rarity:"signature",pol:{}},
{id:2345,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Address-dropper",desc:"Omits names and titles even when addressing someone directly.",example:"Ready? Go, then.",intensity:2,rarity:"common",pol:{}},
{id:2346,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Single-syllable answerer",desc:"Restricts responses to the shortest possible syllable count.",example:"Yep. Nope. Now.",intensity:2,rarity:"common",pol:{}},
{id:2347,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Symbol-speech user",desc:"Replaces full phrases with a gesture-word hybrid shorthand.",example:"Up. (points) There. Go.",intensity:3,rarity:"signature",pol:{}},
{id:2348,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"No-article speaker",desc:"Systematically drops every article from spoken sentences.",example:"Get rope. Tie knot. Pull hard.",intensity:2,rarity:"signature",pol:{}},
{id:2349,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Battlefield-terse",desc:"Compresses every report to the shortest survivable phrasing.",example:"Hit. Down. Send help.",intensity:4,rarity:"signature",pol:{}},
{id:2350,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Time-looping narrator",desc:"Circles back to restate the beginning after reaching the end.",example:"And that's how it happened. Which, as I said, began with the letter.",intensity:3,rarity:"signature",pol:{}},
{id:2351,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Blame-burying syntax",desc:"Structures sentences so responsibility gets grammatically obscured.",example:"Mistakes were made, and things went wrong, somehow.",intensity:3,rarity:"signature",pol:{}},
{id:2352,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Cliffhanger-sentence ender",desc:"Deliberately halts sentences right before the crucial reveal.",example:"And when I opened the door, I saw—",intensity:3,rarity:"signature",pol:{}},
{id:2353,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"List-then-collapse speaker",desc:"Begins an itemized structure, then abandons it for a single point.",example:"First, second, and — actually, forget the list, here's the thing.",intensity:2,rarity:"signature",pol:{}},
{id:2354,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Rhetorical-question stacker",desc:"Strings several unanswered questions together before making a point.",example:"Why would he do that? Why now? Why us?",intensity:3,rarity:"signature",pol:{}},
{id:2355,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Backward-timeline speaker",desc:"Narrates events from the end working back to the beginning.",example:"We lost. That's the end. Now, how we got there—",intensity:3,rarity:"signature",pol:{}},
{id:2356,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Self-quoting speaker",desc:"Interrupts their own sentence to quote something they said before.",example:"I told him — and I quote myself here — 'never again'.",intensity:2,rarity:"signature",pol:{}},
{id:2357,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Comparative-frame speaker",desc:"Structures nearly every statement as an explicit comparison.",example:"Worse than last time, better than the time before that.",intensity:3,rarity:"signature",pol:{}},
{id:2358,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Conditional-stacker",desc:"Piles multiple hypothetical conditions before any conclusion.",example:"If it rains, and if the roads hold, and if we're lucky—",intensity:3,rarity:"signature",pol:{}},
{id:2359,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Abrupt-conclusion jumper",desc:"Skips explanatory steps and lands straight on the conclusion.",example:"So — obviously — we're leaving tonight.",intensity:3,rarity:"common",pol:{}},
{id:2360,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Permission-granting responder",desc:"Explicitly hands the floor to someone before they ask for it.",example:"Go ahead, I know you've got something to add.",intensity:2,rarity:"common",pol:{}},
{id:2361,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Countdown-to-speak",desc:"Visibly signals when they're about to jump in.",example:"In three, two — okay, my turn.",intensity:2,rarity:"signature",pol:{}},
{id:2362,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Topic-guard grammar",desc:"Structures turns specifically to prevent subject changes.",example:"Before we move on — we're not done with this yet.",intensity:3,rarity:"signature",pol:{}},
{id:2363,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Silent-veto holder",desc:"Withholds agreement through pointed, prolonged silence.",example:"(says nothing at all, letting the silence answer)",intensity:3,rarity:"signature",pol:{}},
{id:2364,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Rapid-agreement stacker",desc:"Piles up quick affirmations to keep the conversation moving.",example:"Right, right, yes, exactly, go on.",intensity:2,rarity:"common",pol:{}},
{id:2365,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-tracking scorekeeper",desc:"Keeps explicit verbal count of who has spoken how much.",example:"That's your fourth interruption. I'm counting.",intensity:3,rarity:"signature",pol:{}},
{id:2366,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Gentle-redirect grammar",desc:"Steers the conversation back on track without confrontation.",example:"That's interesting — and back to the main point—",intensity:2,rarity:"common",pol:{}},
{id:2367,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Overlap-embracer",desc:"Talks simultaneously with others without discomfort or apology.",example:"(continues talking straight through the interruption, unbothered)",intensity:3,rarity:"signature",pol:{}},
{id:2368,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Formal-recognition asker",desc:"Requests the floor with explicit, almost procedural language.",example:"May I have the floor for a moment?",intensity:2,rarity:"signature",pol:{}},
{id:2369,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Abrupt-topic-claimer",desc:"Seizes the conversation by simply starting a new subject.",example:"Anyway. New topic. Has anyone seen the ledger?",intensity:3,rarity:"signature",pol:{}},
{id:2370,section:"Mannerisms",category:"Emotional Affectations",trait:"Nervous-smile mask",desc:"Smiles reflexively even when delivering bad news.",example:"(smiles) It's — not great news, actually.",intensity:3,rarity:"signature",pol:{}},
{id:2371,section:"Mannerisms",category:"Emotional Affectations",trait:"Held-breath tension",desc:"Visibly stops breathing at moments of high stress.",example:"(holds breath through the whole exchange, exhales after)",intensity:3,rarity:"signature",pol:{}},
{id:2372,section:"Mannerisms",category:"Emotional Affectations",trait:"Overcorrected calm",desc:"Performs exaggerated composure specifically when panicking inside.",example:"(unnervingly serene) Everything is fine. Completely fine.",intensity:3,rarity:"signature",pol:{}},
{id:2373,section:"Mannerisms",category:"Emotional Affectations",trait:"Delayed emotional response",desc:"Reacts to news well after everyone else already has.",example:"(processes for ten full seconds) ...Wait. What?",intensity:2,rarity:"signature",pol:{}},
{id:2374,section:"Mannerisms",category:"Emotional Affectations",trait:"Protective anger flare",desc:"Anger surfaces instantly and specifically when others are threatened.",example:"(voice drops, cold) Say that again. About her.",intensity:4,rarity:"common",pol:{}},
{id:2375,section:"Mannerisms",category:"Emotional Affectations",trait:"Public-face switch",desc:"Visibly composes themselves the instant others enter the room.",example:"(wipes face, straightens, turns) Oh — hello, come in.",intensity:3,rarity:"signature",pol:{}},
{id:2376,section:"Mannerisms",category:"Emotional Affectations",trait:"Grateful-tears blinker",desc:"Blinks back tears specifically during moments of kindness.",example:"(blinks hard) Sorry — that was just — thank you.",intensity:2,rarity:"signature",pol:{}},
{id:2377,section:"Mannerisms",category:"Emotional Affectations",trait:"Contempt-curled lip",desc:"One corner of the mouth curls slightly at things they scorn.",example:"(lip curls) Is that really the best you've got?",intensity:3,rarity:"signature",pol:{}},
{id:2378,section:"Mannerisms",category:"Emotional Affectations",trait:"Vulnerable-shoulder drop",desc:"Shoulders visibly lower the instant they feel safe enough to relax.",example:"(shoulders drop) God, I didn't realize how tense I was.",intensity:2,rarity:"common",pol:{}},
{id:2379,section:"Mannerisms",category:"Emotional Affectations",trait:"Mask-slip flash",desc:"Composure cracks for exactly one visible second before resetting.",example:"(the mask slips — just for a second — then it's back)",intensity:4,rarity:"signature",pol:{}},
{id:2380,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Map-tracer",desc:"Traces routes on any available surface while explaining plans.",example:"(finger traces the route across the table) Here, then here.",intensity:2,rarity:"common",pol:{}},
{id:2381,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Candle-snuffer fidget",desc:"Absently pinches out candle flames during long conversations.",example:"(pinches the candle flame out, relights it, repeats)",intensity:2,rarity:"signature",pol:{}},
{id:2382,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Wall-measurer",desc:"Paces off distances against walls without explanation.",example:"(counts steps against the wall, mid-sentence)",intensity:2,rarity:"signature",pol:{}},
{id:2383,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Fireplace-tender",desc:"Tends the fire compulsively regardless of whether it needs it.",example:"(pokes the fire that was already burning fine)",intensity:2,rarity:"common",pol:{}},
{id:2384,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Window-latch checker",desc:"Checks and rechecks that windows are properly secured.",example:"(tests the latch, twice, before continuing)",intensity:3,rarity:"signature",pol:{}},
{id:2385,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Threshold-hesitator",desc:"Pauses noticeably before crossing any doorway.",example:"(stops at the threshold a beat too long before entering)",intensity:2,rarity:"signature",pol:{}},
{id:2386,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Cushion-plumper",desc:"Rearranges pillows and cushions whenever anxious.",example:"(plumps the cushion that didn't need plumping)",intensity:1,rarity:"signature",pol:{}},
{id:2387,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Ledge-walker",desc:"Walks along raised edges and ledges rather than flat ground.",example:"(walks the low garden wall instead of the path)",intensity:2,rarity:"signature",pol:{}},
{id:2388,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Bookshelf-browser mid-talk",desc:"Scans nearby bookshelves absently while holding a conversation.",example:"(reads spines while answering, only half-present)",intensity:2,rarity:"signature",pol:{}},
{id:2389,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Candlewax-picker",desc:"Peels dried wax from candlesticks during idle moments.",example:"(picks at the wax drips, not really listening)",intensity:1,rarity:"signature",pol:{}},
{id:2390,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Slow-appraisal look",desc:"Takes a visibly long moment to look someone over before speaking.",example:"(eyes move slowly, top to bottom) ...Alright, then.",intensity:3,rarity:"signature",pol:{}},
{id:2391,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Sudden-focus narrow",desc:"Eyes sharpen instantly the moment something matters.",example:"(eyes narrow, suddenly focused) Say that again.",intensity:3,rarity:"common",pol:{}},
{id:2392,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Grief-glazed stare",desc:"Eyes go distant and unfocused when a topic touches loss.",example:"(stares past them, unseeing, for a moment)",intensity:3,rarity:"signature",pol:{}},
{id:2393,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Amused-crinkle",desc:"Eyes crinkle at the corners before the smile even arrives.",example:"(eyes crinkle first) Oh, this is going to be good.",intensity:2,rarity:"common",pol:{}},
{id:2394,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Guilt-flick glance",desc:"Eyes dart briefly toward the thing they're guilty about.",example:"(glances, just once, at the locked drawer)",intensity:3,rarity:"signature",pol:{}},
{id:2395,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Held-gaze challenge",desc:"Refuses to break eye contact during any disagreement.",example:"(does not look away, not once, through the whole argument)",intensity:3,rarity:"signature",pol:{}},
{id:2396,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Soft-focus daydream look",desc:"Eyes drift out of focus mid-conversation, thinking elsewhere.",example:"(gaze softens, drifts, comes back a beat late)",intensity:2,rarity:"signature",pol:{}},
{id:2397,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Micro-grimace flash",desc:"A tiny wince crosses the face before it's smoothed away.",example:"(a flicker of a wince, gone before it registers)",intensity:2,rarity:"signature",pol:{}},
{id:2398,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Delighted-crinkle burst",desc:"Whole face lights genuinely at small, unexpected good news.",example:"(face opens up entirely) Wait — really?",intensity:2,rarity:"common",pol:{}},
{id:2399,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Suspicious-squint hold",desc:"Holds a narrowed, doubtful expression through an entire explanation.",example:"(squints, unconvinced, through the whole story)",intensity:3,rarity:"signature",pol:{}},
{id:2400,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Measuring-hands gesture",desc:"Uses hands to indicate rough size or scale while describing things.",example:"(hands apart) About this big. Give or take.",intensity:2,rarity:"common",pol:{}},
{id:2401,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Conductor's-baton hand",desc:"Moves a hand as though conducting the rhythm of their own speech.",example:"(hand rises and falls, keeping time with the words)",intensity:2,rarity:"signature",pol:{}},
{id:2402,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Fist-unclench release",desc:"Visibly unclenches a fist at the moment tension breaks.",example:"(fist slowly opens) ...Alright. Alright, fine.",intensity:3,rarity:"signature",pol:{}},
{id:2403,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Air-quote user",desc:"Uses visible finger air-quotes around skeptical terms.",example:"He's 'busy'. (finger quotes) Sure he is.",intensity:2,rarity:"common",pol:{}},
{id:2404,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Beckoning-finger habit",desc:"Curls a finger to summon attention or agreement.",example:"(curls a finger) Come here. Closer.",intensity:2,rarity:"signature",pol:{}},
{id:2405,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Weighing-palms gesture",desc:"Holds palms up and down alternately as if weighing options.",example:"(palms rise and fall) This — or that. Hard to say.",intensity:2,rarity:"signature",pol:{}},
{id:2406,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Slicing-hand cutoff",desc:"Uses a flat hand-chop to visually end a topic.",example:"(hand slices flat through the air) Done. Moving on.",intensity:3,rarity:"common",pol:{}},
{id:2407,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Praying-hands pause",desc:"Presses palms together briefly before delivering serious news.",example:"(palms together, brief pause) There's no easy way to say this.",intensity:2,rarity:"signature",pol:{}},
{id:2408,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Countdown-finger gesture",desc:"Physically counts down on fingers before acting.",example:"(three fingers, two, one) —go.",intensity:2,rarity:"signature",pol:{}},
{id:2409,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Reluctant-handshake offer",desc:"Extends a hand slowly, visibly hesitant to commit to the gesture.",example:"(hand extends, slowly, like it costs something)",intensity:3,rarity:"signature",pol:{}},
{id:2410,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Wrist-watch glancer",desc:"Checks a wrist that has no watch, out of pure habit.",example:"(glances at bare wrist, catches themselves)",intensity:2,rarity:"signature",pol:{}},
{id:2411,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Tooth-tap thinker",desc:"Taps a front tooth lightly while considering a response.",example:"(taps a tooth) ...Give me a second.",intensity:1,rarity:"signature",pol:{}},
{id:2412,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Palm-press ground",desc:"Presses palms flat against a surface to steady themselves.",example:"(presses both palms flat on the table, breathes)",intensity:3,rarity:"signature",pol:{}},
{id:2413,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Sleeve-cuff smoother",desc:"Smooths the cuff of a sleeve compulsively before speaking.",example:"(smooths the cuff, twice, before answering)",intensity:1,rarity:"signature",pol:{}},
{id:2414,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Inner-lip bite",desc:"Bites the inside of the lip when suppressing a sharper reply.",example:"(bites the inside of the lip) ...Noted.",intensity:2,rarity:"signature",pol:{}},
{id:2415,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Rapid-eyebrow twitch",desc:"A single eyebrow ticks upward involuntarily at surprise.",example:"(brow twitches) Oh. Oh, I wasn't expecting that.",intensity:2,rarity:"signature",pol:{}},
{id:2416,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Palm-wipe habit",desc:"Wipes palms on clothing before any significant physical action.",example:"(wipes palms on trousers before reaching for it)",intensity:2,rarity:"signature",pol:{}},
{id:2417,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Silent-throat-bob",desc:"Swallows visibly and silently at moments of real fear.",example:"(throat bobs, once, hard, saying nothing)",intensity:3,rarity:"signature",pol:{}},
{id:2418,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Finger-count-under-breath",desc:"Silently counts something on fingers while thinking.",example:"(fingers move slightly, counting something unseen)",intensity:1,rarity:"signature",pol:{}},
{id:2419,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Ankle-cross fidget",desc:"Crosses and uncrosses ankles repeatedly when uneasy.",example:"(ankles cross, uncross, cross again)",intensity:1,rarity:"signature",pol:{}},
{id:2420,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Startled-yelp reflex",desc:"Emits a small involuntary sound at sudden surprises.",example:"(a short yelp) Oh! You scared me.",intensity:2,rarity:"common",pol:{}},
{id:2421,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Contented-sigh settler",desc:"Exhales a satisfied sigh when finally comfortable.",example:"(a long, settled sigh) Ah. Better.",intensity:2,rarity:"common",pol:{}},
{id:2422,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Disapproving-hmph",desc:"Emits a short, disapproving exhale through the nose.",example:"Hmph. If you say so.",intensity:2,rarity:"common",pol:{}},
{id:2423,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Delighted-gasp burst",desc:"Gasps audibly at genuinely exciting news.",example:"(gasps) No! Really?",intensity:2,rarity:"common",pol:{}},
{id:2424,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Weary-groan riser",desc:"Groans while standing up or exerting any effort.",example:"(groans, rising) Getting too old for this.",intensity:2,rarity:"signature",pol:{}},
{id:2425,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Quiet-tut disapproval",desc:"Makes a small tutting sound at minor mistakes.",example:"Tut. Careless, that.",intensity:1,rarity:"signature",pol:{}},
{id:2426,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sharp-clap attention-getter",desc:"Claps once, sharply, to redirect the room's focus.",example:"(one sharp clap) Alright, everyone, listen up.",intensity:3,rarity:"signature",pol:{}},
{id:2427,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Low-whimper suppressor",desc:"Suppresses a whimper into a barely audible sound.",example:"(a tiny, swallowed sound) ...I'm okay.",intensity:3,rarity:"signature",pol:{}},
{id:2428,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Booming-laugh releaser",desc:"Laughs suddenly and loudly, filling the whole room.",example:"(a booming laugh, unrestrained, catches everyone off guard)",intensity:3,rarity:"common",pol:{}},
{id:2429,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Held-sob swallower",desc:"Visibly swallows down a sob mid-sentence.",example:"(swallows hard, mid-word) I'm — sorry — fine.",intensity:4,rarity:"signature",pol:{}},
{id:2430,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Guard-stance ready",desc:"Stands with weight balanced, ready to move at any moment.",example:"(weight even on both feet, ready)",intensity:3,rarity:"signature",pol:{}},
{id:2431,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Slumped-relief collapse",desc:"Posture collapses entirely once danger has passed.",example:"(sinks into the chair, all tension gone at once)",intensity:2,rarity:"common",pol:{}},
{id:2432,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Protective-stance shift",desc:"Angles body slightly between danger and whoever they're protecting.",example:"(shifts, subtly, to stand between them and the door)",intensity:3,rarity:"signature",pol:{}},
{id:2433,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Formal-attention posture",desc:"Stands unnaturally straight and still when addressing authority.",example:"(stands at rigid attention) Sir. Yes, sir.",intensity:3,rarity:"signature",pol:{}},
{id:2434,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Curled-inward posture",desc:"Draws inward and small when feeling exposed or criticized.",example:"(curls inward, shoulders in, making themselves smaller)",intensity:3,rarity:"signature",pol:{}},
{id:2435,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Confident-sprawl seated",desc:"Takes up generous space when relaxed and self-assured.",example:"(sprawls easily across the seat, unbothered)",intensity:2,rarity:"common",pol:{}},
{id:2436,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Wary-perimeter walker",desc:"Instinctively keeps to the edges of any room.",example:"(stays close to the walls, never the center)",intensity:2,rarity:"signature",pol:{}},
{id:2437,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Mirrored-stance adopter",desc:"Unconsciously copies the posture of whoever they're speaking with.",example:"(shifts weight the instant the other person does)",intensity:2,rarity:"signature",pol:{}},
{id:2438,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Grounded-stillness holder",desc:"Remains completely still and centered under any pressure.",example:"(does not shift, does not flinch, entirely still)",intensity:4,rarity:"signature",pol:{}},
{id:2439,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Retreat-to-corner instinct",desc:"Backs into corners when startled or overwhelmed.",example:"(backs into the corner, eyes on the door)",intensity:3,rarity:"signature",pol:{}},
{id:2440,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-photo organizer",desc:"Instinctively arranges people for group moments, even casually.",example:"Right, you here, you there — perfect, hold still.",intensity:2,rarity:"signature",pol:{}},
{id:2441,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Interruption-tolerant listener",desc:"Never seems bothered by being interrupted, however often.",example:"(waits patiently, unbothered, lets them finish)",intensity:2,rarity:"common",pol:{}},
{id:2442,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Excuse-me-first mover",desc:"Always announces themselves before moving past anyone.",example:"Excuse me — sorry — just passing through.",intensity:2,rarity:"common",pol:{}},
{id:2443,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Compliment-overloader",desc:"Showers new acquaintances with immediate, excessive praise.",example:"You're wonderful. Genuinely. I can just tell.",intensity:3,rarity:"signature",pol:{}},
{id:2444,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Silent-consent waiter",desc:"Waits for a visible nod before proceeding with anything personal.",example:"(waits, watching for the nod, before continuing)",intensity:2,rarity:"signature",pol:{}},
{id:2445,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-energy reader",desc:"Constantly scans the room's mood before speaking up.",example:"(reads the room first, adjusts, then speaks)",intensity:2,rarity:"signature",pol:{}},
{id:2446,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Overfamiliar-toucher",desc:"Touches new acquaintances more than social norms typically allow.",example:"(a hand on the shoulder, far too soon)",intensity:3,rarity:"signature",pol:{}},
{id:2447,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Exit-clearing courtesy",desc:"Physically steps aside to clear a path the instant someone approaches.",example:"(steps back immediately, clearing the way)",intensity:1,rarity:"common",pol:{}},
{id:2448,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Deliberate-eye-avoidance",desc:"Avoids eye contact specifically with people they distrust.",example:"(looks anywhere but at him, deliberately)",intensity:3,rarity:"signature",pol:{}},
{id:2449,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Loud-entrance announcer",desc:"Announces their own arrival before anyone notices them.",example:"I'm here! Everyone, I've arrived!",intensity:3,rarity:"signature",pol:{}},
{id:2450,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Map-folder ritualist",desc:"Folds and unfolds a map along the exact same creases repeatedly.",example:"(folds the map along the worn crease, again)",intensity:2,rarity:"signature",pol:{}},
{id:2451,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Whittling-knife habit",desc:"Carries and idly whittles wood during long conversations.",example:"(shaves a curl of wood off, not really looking)",intensity:2,rarity:"signature",pol:{}},
{id:2452,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Dice-roller fidget",desc:"Rolls small dice or tokens between fingers when thinking.",example:"(rolls the die across the knuckles, thinking)",intensity:2,rarity:"signature",pol:{}},
{id:2453,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Locket-clasp checker",desc:"Repeatedly checks that a locket clasp is properly closed.",example:"(checks the clasp, again, without noticing)",intensity:1,rarity:"signature",pol:{}},
{id:2454,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Glove-removal ritual",desc:"Removes gloves slowly and deliberately before serious conversations.",example:"(peels off one glove, finger by finger)",intensity:2,rarity:"signature",pol:{}},
{id:2455,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Matchstick-snapper",desc:"Snaps small matchsticks or twigs absently while talking.",example:"(snaps a twig in half, then in half again)",intensity:2,rarity:"signature",pol:{}},
{id:2456,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Ring-box opener",desc:"Opens and closes a small box or case repeatedly, unopened contents unseen.",example:"(opens the box, closes it, opens it again)",intensity:2,rarity:"signature",pol:{}},
{id:2457,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Belt-buckle adjuster",desc:"Adjusts a belt or buckle whenever entering a tense conversation.",example:"(adjusts the buckle before squaring up to speak)",intensity:1,rarity:"signature",pol:{}},
{id:2458,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Compass-spinner",desc:"Spins a small compass or trinket restlessly during long waits.",example:"(spins the compass, watches it settle, spins it again)",intensity:2,rarity:"signature",pol:{}},
{id:2459,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Photograph-corner worrier",desc:"Worries the corner of a kept photograph between finger and thumb.",example:"(thumb worries the photo's corner, soft with handling)",intensity:2,rarity:"signature",pol:{}},
{id:2460,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Storyteller's-lilt voice",desc:"Naturally slips into a musical, narrative cadence when telling stories.",example:"And so, the old man said, the journey had only just begun.",intensity:2,rarity:"common",pol:{}},
{id:2461,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Command-flat delivery",desc:"Strips all emotion from the voice specifically when giving orders.",example:"Move to the left flank. Hold position.",intensity:3,rarity:"common",pol:{}},
{id:2462,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Grief-thinned voice",desc:"Voice thins and loses body specifically around loss.",example:"She was— (voice thins) —she was my sister.",intensity:4,rarity:"signature",pol:{}},
{id:2463,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Teasing sing-song lift",desc:"Voice takes on a playful, taunting lilt when needling someone.",example:"Someone's in troub-le~",intensity:2,rarity:"common",pol:{}},
{id:2464,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Reassurance-lowered pitch",desc:"Deliberately drops pitch to a calming register when comforting.",example:"(voice drops, gentle) It's alright. I've got you.",intensity:2,rarity:"common",pol:{}},
{id:2465,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Cracking-under-pressure voice",desc:"Voice audibly cracks at the exact peak of stress.",example:"I can't— (voice cracks) —I can't do this anymore.",intensity:4,rarity:"signature",pol:{}},
{id:2466,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Performance-projection voice",desc:"Speaks louder and more theatrically the moment there's an audience.",example:"(voice rises, fills the room) LADIES AND GENTLEMEN—",intensity:3,rarity:"signature",pol:{}},
{id:2467,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Secret-sharing hush",desc:"Voice drops to conspiratorial hush specifically for gossip.",example:"(leans in, whispers) You didn't hear this from me.",intensity:2,rarity:"common",pol:{}},
{id:2468,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Steel-edged warning tone",desc:"Voice hardens into a distinct, sharp warning register.",example:"(voice goes hard) Don't. Don't do that again.",intensity:4,rarity:"signature",pol:{}},
{id:2469,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Exhausted-flatline voice",desc:"Voice flattens entirely under accumulated fatigue.",example:"(flat, worn) Sure. Whatever you say.",intensity:3,rarity:"signature",pol:{}},
{id:2470,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"First-to-wave",desc:"Always the one who greets a room before being greeted.",example:"There you are! Come, come, sit with us.",intensity:2,rarity:"common",pol:{}},
{id:2471,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Remembers-the-small-things",desc:"Recalls tiny personal details others mentioned only once.",example:"You said your knee was bothering you — is it better now?",intensity:2,rarity:"signature",pol:{}},
{id:2472,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Instant-nickname giver",desc:"Assigns an affectionate nickname within minutes of meeting someone.",example:"Right then, 'Sparrow' — that's you now, get used to it.",intensity:3,rarity:"signature",pol:{}},
{id:2473,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Door-always-open host",desc:"Genuinely means it when they say visitors are welcome anytime.",example:"Don't knock. Just come in. The door's never locked for you.",intensity:3,rarity:"common",pol:{}},
{id:2474,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Compliment-generous",desc:"Offers genuine praise freely and often, without it feeling hollow.",example:"That was well done. Really well done. You should be proud.",intensity:2,rarity:"common",pol:{}},
{id:2475,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Stranger-befriender",desc:"Strikes up real conversation with anyone, regardless of context.",example:"Lovely coat. Where'd you find it? I'm Marta, by the way.",intensity:2,rarity:"common",pol:{}},
{id:2476,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Group-includer",desc:"Actively pulls quiet or isolated people into the conversation.",example:"And you — you've been quiet. What do you think?",intensity:3,rarity:"signature",pol:{}},
{id:2477,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Physical-comfort offerer",desc:"Offers a blanket, seat, or warmth before being asked.",example:"Here, take my coat, you look frozen.",intensity:2,rarity:"common",pol:{}},
{id:2478,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Celebratory-of-others",desc:"Genuinely delights in other people's good news, without envy.",example:"You got it? You actually got it! I'm so happy for you.",intensity:3,rarity:"common",pol:{}},
{id:2479,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Farewell-lingerer",desc:"Draws out goodbyes because they genuinely don't want the visit to end.",example:"Must you go already? Stay a bit longer, won't you?",intensity:2,rarity:"signature",pol:{}},
{id:2480,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Name-forgetter",desc:"Rarely bothers to remember or use people's names.",example:"You. The tall one. Come here a moment.",intensity:2,rarity:"signature",pol:{}},
{id:2481,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Handshake-only greeter",desc:"Limits all greetings to the barest formal minimum.",example:"(a brief, businesslike handshake, nothing more)",intensity:2,rarity:"common",pol:{}},
{id:2482,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Small-talk refuser",desc:"Shuts down casual conversation before it can start.",example:"We're not here to chat. State your business.",intensity:3,rarity:"signature",pol:{}},
{id:2483,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Distance-preferring seater",desc:"Always chooses the seat furthest from everyone else.",example:"(takes the chair in the corner, apart from the group)",intensity:2,rarity:"common",pol:{}},
{id:2484,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Emotionally-transactional",desc:"Treats warmth as something to be earned, not given freely.",example:"Prove yourself first. Then we'll talk.",intensity:3,rarity:"signature",pol:{}},
{id:2485,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Party-avoider",desc:"Declines social gatherings as a matter of course.",example:"Not my kind of evening. I'll pass.",intensity:2,rarity:"common",pol:{}},
{id:2486,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Politely-dismissive",desc:"Ends interactions with technically courteous but clearly final words.",example:"Thank you for stopping by. That will be all.",intensity:2,rarity:"signature",pol:{}},
{id:2487,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Warmth-suspicious",desc:"Treats others' friendliness as a tactic to be wary of.",example:"What do you actually want? Nobody's this nice for free.",intensity:3,rarity:"signature",pol:{}},
{id:2488,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Minimal-eye-contact holder",desc:"Keeps eye contact brief and infrequent in most interactions.",example:"(glances, briefly, then looks elsewhere)",intensity:2,rarity:"common",pol:{}},
{id:2489,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Professional-only persona",desc:"Reveals nothing beyond what's strictly required for the task at hand.",example:"We're colleagues. That's the whole of it.",intensity:3,rarity:"signature",pol:{}},
{id:2490,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Full-disclosure instinct",desc:"Volunteers relevant negative information unprompted.",example:"Before you decide — you should know I disagree with this.",intensity:3,rarity:"common",pol:{}},
{id:2491,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Correction-compelled",desc:"Cannot let even minor factual errors go uncorrected.",example:"Actually, it was Thursday, not Wednesday. Just to be accurate.",intensity:2,rarity:"signature",pol:{}},
{id:2492,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Motive-declaring",desc:"States their own self-interest openly rather than hiding it.",example:"I'll help, but I want something for it. Being upfront about that.",intensity:3,rarity:"signature",pol:{}},
{id:2493,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Apology-precise",desc:"Owns mistakes with exact, unhedged specificity.",example:"I broke it. Not 'it broke'. I broke it.",intensity:3,rarity:"common",pol:{}},
{id:2494,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"No-flattery policy",desc:"Refuses to offer praise they don't genuinely mean.",example:"I won't say it was good. It wasn't.",intensity:3,rarity:"signature",pol:{}},
{id:2495,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Rumor-corrector",desc:"Actively steps in to correct spreading misinformation.",example:"That's not what happened. Let me tell you what actually did.",intensity:2,rarity:"signature",pol:{}},
{id:2496,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Track-record keeper",desc:"References their own consistent honesty as proof of credibility.",example:"Have I ever lied to you? Not once. Believe me now.",intensity:2,rarity:"signature",pol:{}},
{id:2497,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Painful-truth deliverer",desc:"Delivers hard truths even knowing it will cost them the relationship.",example:"You need to hear this, even if you hate me for it after.",intensity:4,rarity:"signature",pol:{}},
{id:2498,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Receipt-keeper",desc:"Backs up claims with concrete, checkable evidence.",example:"Don't take my word — here's the date, here's the signature.",intensity:2,rarity:"signature",pol:{}},
{id:2499,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Silence-over-lying chooser",desc:"Would rather say nothing at all than say something false.",example:"I won't answer that. I won't lie to you either.",intensity:3,rarity:"signature",pol:{}},
{id:2500,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Story-adjuster",desc:"Subtly alters details of an account depending on the audience.",example:"(tells the story slightly differently to each listener)",intensity:3,rarity:"signature",pol:{}},
{id:2501,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Selective-memory claimer",desc:"Conveniently forgets details that would be inconvenient to recall.",example:"I don't recall saying that. Genuinely don't recall it.",intensity:3,rarity:"signature",pol:{}},
{id:2502,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Plausible-alibi builder",desc:"Constructs believable cover stories well in advance.",example:"I was at the mill all evening. Ask the miller, he'll confirm it.",intensity:4,rarity:"signature",pol:{}},
{id:2503,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Question-redirector",desc:"Answers uncomfortable questions with a different question.",example:"Why do you want to know that, exactly?",intensity:3,rarity:"common",pol:{}},
{id:2504,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Confidence-masked liar",desc:"Delivers falsehoods with total, unwavering conviction.",example:"(states the lie without a flicker of hesitation)",intensity:4,rarity:"signature",pol:{}},
{id:2505,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Technically-true speaker",desc:"Constructs statements that are literally accurate but deeply misleading.",example:"I never said I was there. I said I wasn't NOT there.",intensity:3,rarity:"signature",pol:{}},
{id:2506,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Sympathy-extraction liar",desc:"Fabricates hardship to manipulate others' compassion.",example:"It's been such a hard year for me, you understand.",intensity:3,rarity:"signature",pol:{}},
{id:2507,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Trust-banking deceiver",desc:"Establishes credibility with small truths before the big lie.",example:"I've never steered you wrong before, have I? So trust me now.",intensity:4,rarity:"signature",pol:{}},
{id:2508,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Blame-redirecting liar",desc:"Fabricates narratives that shift fault onto someone else entirely.",example:"It wasn't me. It was him. He set the whole thing up.",intensity:4,rarity:"signature",pol:{}},
{id:2509,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Vague-on-purpose speaker",desc:"Deliberately keeps statements imprecise to avoid being pinned down later.",example:"Things happened. Some of them, anyway. Around then.",intensity:2,rarity:"signature",pol:{}},
{id:2510,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Terms-setter",desc:"States the conditions of any deal before negotiations even begin.",example:"Here's what I need. Take it or leave it.",intensity:3,rarity:"common",pol:{}},
{id:2511,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Immediate-objector",desc:"Raises disagreement the moment it forms, without waiting.",example:"No. I disagree, and I'm saying so now.",intensity:3,rarity:"common",pol:{}},
{id:2512,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Space-claiming speaker",desc:"Physically and verbally asserts their place in any discussion.",example:"I'm speaking. You'll get your turn.",intensity:3,rarity:"signature",pol:{}},
{id:2513,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Deadline-setter",desc:"States firm timeframes rather than open-ended requests.",example:"End of day. Not tomorrow. Today.",intensity:3,rarity:"common",pol:{}},
{id:2514,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Correction-unafraid",desc:"Corrects superiors and authority figures without hesitation.",example:"With respect, sir, that's incorrect.",intensity:4,rarity:"signature",pol:{}},
{id:2515,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Position-repeater",desc:"Restates their stance clearly, again, if it's being ignored.",example:"I'll say it once more: no.",intensity:3,rarity:"common",pol:{}},
{id:2516,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Need-namer",desc:"States personal needs plainly rather than hinting at them.",example:"I need help with this. Directly asking.",intensity:2,rarity:"common",pol:{}},
{id:2517,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Silence-breaker",desc:"Speaks up in group settings where others default to quiet.",example:"Someone has to say it — I don't think this plan works.",intensity:3,rarity:"signature",pol:{}},
{id:2518,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"No-apology asker",desc:"Requests what they want without prefacing it with an apology.",example:"I want the corner office. That's my ask.",intensity:2,rarity:"signature",pol:{}},
{id:2519,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Boundary-restater",desc:"Repeats a stated limit exactly when it's tested again.",example:"I said no last time. Still no.",intensity:3,rarity:"common",pol:{}},
{id:2520,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Preference-suppressor",desc:"Buries their own wants rather than risk stating them.",example:"Oh, I don't really mind. Whatever's easiest.",intensity:2,rarity:"common",pol:{}},
{id:2521,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Apology-prefacer",desc:"Cushions every request with an unnecessary apology first.",example:"Sorry, sorry — could I maybe ask for something?",intensity:2,rarity:"common",pol:{}},
{id:2522,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Silent-disagreer",desc:"Disagrees internally but never voices it aloud.",example:"(nods along, disagreeing completely, saying nothing)",intensity:3,rarity:"signature",pol:{}},
{id:2523,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Last-to-speak",desc:"Waits until everyone else has spoken before offering an opinion, if at all.",example:"(waits, and waits, and eventually says nothing)",intensity:2,rarity:"signature",pol:{}},
{id:2524,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Compliance-default",desc:"Agrees to requests before even considering whether they want to.",example:"Sure, of course, whatever you need.",intensity:2,rarity:"common",pol:{}},
{id:2525,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Grievance-swallower",desc:"Absorbs mistreatment rather than raise the issue.",example:"It's fine. It's really fine. I'll manage.",intensity:3,rarity:"signature",pol:{}},
{id:2526,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Indirect-hint dropper",desc:"Implies what they want rather than stating it outright.",example:"It would be nice if someone helped, is all I'm saying.",intensity:2,rarity:"signature",pol:{}},
{id:2527,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Volume-diminisher",desc:"Voice gets quieter, not louder, the more strongly they feel.",example:"(the more it matters, the softer the voice gets)",intensity:3,rarity:"signature",pol:{}},
{id:2528,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Retreat-after-pushback",desc:"Abandons their position the instant anyone disagrees.",example:"Oh — well, if you think so, never mind then.",intensity:2,rarity:"common",pol:{}},
{id:2529,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Permission-waiter",desc:"Waits to be explicitly invited before contributing anything.",example:"Should I— is it alright if I say something?",intensity:2,rarity:"signature",pol:{}},
{id:2530,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Unbothered-by-mockery",desc:"Mockery genuinely doesn't land or diminish them.",example:"(laughs along with the joke about themselves, unbothered)",intensity:2,rarity:"common",pol:{}},
{id:2531,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Room-entering ease",desc:"Enters any space, however intimidating, without visible hesitation.",example:"(walks straight into the room, easy, unhurried)",intensity:2,rarity:"common",pol:{}},
{id:2532,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Failure-shrugger",desc:"Treats setbacks as data, not verdicts on their worth.",example:"Didn't work. Try again differently.",intensity:3,rarity:"signature",pol:{}},
{id:2533,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-referential-calm",desc:"Speaks about their own abilities plainly, without bragging or shrinking.",example:"I'm good at this. It's just true.",intensity:2,rarity:"common",pol:{}},
{id:2534,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Comparison-immune",desc:"Doesn't measure themselves against others' success or failure.",example:"Good for them. Doesn't change what I'm doing.",intensity:2,rarity:"signature",pol:{}},
{id:2535,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Silence-comfortable",desc:"Doesn't rush to fill silence out of insecurity.",example:"(sits comfortably in the quiet, unbothered)",intensity:2,rarity:"signature",pol:{}},
{id:2536,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Correction-graceful",desc:"Accepts being wrong without defensiveness or embarrassment.",example:"You're right, I missed that. Good catch.",intensity:2,rarity:"common",pol:{}},
{id:2537,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Physically-settled presence",desc:"Occupies space calmly, without fidgeting or shrinking.",example:"(stands still, relaxed, taking up exactly the space they need)",intensity:2,rarity:"signature",pol:{}},
{id:2538,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Ask-without-shame",desc:"Requests help or admits ignorance without embarrassment.",example:"I don't know how to do that. Can you show me?",intensity:2,rarity:"signature",pol:{}},
{id:2539,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Approval-independent",desc:"Makes decisions without needing others' validation first.",example:"I've decided. I don't need everyone to agree.",intensity:3,rarity:"signature",pol:{}},
{id:2540,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Constant self-monitor",desc:"Obsessively tracks how they're being perceived in real time.",example:"Did that sound stupid? That sounded stupid, didn't it.",intensity:3,rarity:"signature",pol:{}},
{id:2541,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Credential-flasher",desc:"Works past achievements into conversations that don't call for it.",example:"As I mentioned, I did train under the master himself.",intensity:3,rarity:"signature",pol:{}},
{id:2542,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Silence-interpreter-negative",desc:"Reads any pause or quiet as evidence of disapproval.",example:"You didn't say anything. That means you hated it.",intensity:3,rarity:"signature",pol:{}},
{id:2543,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Preemptive self-critic",desc:"Insults their own work before anyone else can.",example:"It's probably terrible, don't bother being nice about it.",intensity:2,rarity:"common",pol:{}},
{id:2544,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Spotlight-seeker",desc:"Redirects attention back to themselves whenever it drifts away.",example:"Speaking of which — that reminds me of MY story.",intensity:3,rarity:"signature",pol:{}},
{id:2545,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Never-wrong insister",desc:"Cannot admit fault even when clearly, obviously mistaken.",example:"I wasn't wrong. The circumstances were wrong.",intensity:4,rarity:"signature",pol:{}},
{id:2546,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Compliment-fisher",desc:"Steers conversation toward opportunities to be praised.",example:"I worked so hard on it. Probably too hard. Was it obvious?",intensity:2,rarity:"common",pol:{}},
{id:2547,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Status-anxious comparer",desc:"Constantly measures their standing against everyone nearby.",example:"She got promoted? Before me? How is that possible.",intensity:3,rarity:"signature",pol:{}},
{id:2548,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Overcorrecting braggart",desc:"Compensates for private doubt with loud, exaggerated boasting.",example:"Best there's ever been, honestly, no contest.",intensity:3,rarity:"signature",pol:{}},
{id:2549,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Rejection-catastrophizer",desc:"Treats any minor social slight as total, permanent condemnation.",example:"She didn't wave back. That's it. She hates me now.",intensity:3,rarity:"signature",pol:{}},
{id:2550,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Consensus-seeker",desc:"Actively works to find a position everyone can accept.",example:"What if we did a bit of both? Would that work for everyone?",intensity:2,rarity:"common",pol:{}},
{id:2551,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Schedule-flexer",desc:"Rearranges their own plans readily to suit others.",example:"I can move things around. Don't worry about my schedule.",intensity:2,rarity:"common",pol:{}},
{id:2552,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Credit-deflector",desc:"Redirects praise toward the group rather than claiming it.",example:"It wasn't just me. Everyone contributed to that.",intensity:2,rarity:"common",pol:{}},
{id:2553,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Tension-smoother",desc:"Steps in quickly to ease any friction between others.",example:"Let's not let this become a whole thing, alright?",intensity:2,rarity:"signature",pol:{}},
{id:2554,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Last-choice taker",desc:"Consistently defers their own preference to whatever's left over.",example:"I'll take whatever's left. Really, it's fine.",intensity:2,rarity:"common",pol:{}},
{id:2555,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Group-harmony prioritizer",desc:"Values the group getting along over being personally right.",example:"Doesn't matter who's right. Let's just move forward together.",intensity:2,rarity:"signature",pol:{}},
{id:2556,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Quick-forgiver",desc:"Lets go of grievances readily, without holding onto resentment.",example:"It's done. I'm not carrying that around.",intensity:2,rarity:"common",pol:{}},
{id:2557,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Volunteer-first responder",desc:"Offers to take on unwanted tasks before being asked.",example:"I'll do it. Someone has to, might as well be me.",intensity:3,rarity:"signature",pol:{}},
{id:2558,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Praise-generous listener",desc:"Finds something genuine to compliment in nearly every idea presented.",example:"That's actually a really good point, I like that.",intensity:1,rarity:"common",pol:{}},
{id:2559,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Compromise-proposer",desc:"Offers middle-ground solutions before conflict fully develops.",example:"What if we split the difference here?",intensity:2,rarity:"signature",pol:{}},
{id:2560,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Automatic-objector",desc:"Raises an objection to nearly anything proposed, reflexively.",example:"I mean, has anyone actually considered the downsides?",intensity:3,rarity:"signature",pol:{}},
{id:2561,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Consensus-distruster",desc:"Grows suspicious the moment everyone appears to agree.",example:"Everyone's nodding. That worries me more than if they weren't.",intensity:3,rarity:"signature",pol:{}},
{id:2562,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Fact-checker-combative",desc:"Challenges claims aggressively, even minor or harmless ones.",example:"Says who? Where's that actually from?",intensity:3,rarity:"common",pol:{}},
{id:2563,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Debate-escalator",desc:"Turns simple disagreements into extended, heated arguments.",example:"No, let's actually get into this properly.",intensity:4,rarity:"signature",pol:{}},
{id:2564,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Last-word insister",desc:"Cannot let a disagreement end without having the final say.",example:"And another thing — I'm not finished.",intensity:3,rarity:"signature",pol:{}},
{id:2565,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Position-defender-to-the-end",desc:"Refuses to concede a point even against strong counter-evidence.",example:"Doesn't matter what the numbers say. I still think I'm right.",intensity:4,rarity:"signature",pol:{}},
{id:2566,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Unsolicited-critique giver",desc:"Offers critical opinions on things nobody asked about.",example:"Since you're asking — which you weren't — that's a bad plan.",intensity:3,rarity:"signature",pol:{}},
{id:2567,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Devil's-advocate reflex",desc:"Argues the opposite position purely to test its strength.",example:"Just to play devil's advocate here for a second—",intensity:2,rarity:"common",pol:{}},
{id:2568,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Grudge-tracker",desc:"Keeps precise mental record of every past disagreement.",example:"This is just like the thing in March. And the thing before that.",intensity:3,rarity:"signature",pol:{}},
{id:2569,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Superiority-implying arguer",desc:"Frames disagreements as evidence of the other person's lesser understanding.",example:"I suppose that makes sense, if you haven't really thought it through.",intensity:4,rarity:"signature",pol:{}},
{id:2570,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Introduction-formal",desc:"Always properly introduces people to one another in a group.",example:"Have you two met? Allow me — this is my colleague.",intensity:2,rarity:"common",pol:{}},
{id:2571,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Seat-offering host",desc:"Automatically offers their seat to anyone standing.",example:"Please, take this chair. I'm quite alright standing.",intensity:1,rarity:"common",pol:{}},
{id:2572,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Quick to apologize for interrupting",desc:"Immediately apologizes for any accidental interruption.",example:"Oh, forgive me — please, continue.",intensity:1,rarity:"common",pol:{}},
{id:2573,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Thank-you note writer",desc:"Follows up kindnesses with formal, written gratitude.",example:"I wanted to properly thank you, in writing, for your help.",intensity:2,rarity:"signature",pol:{}},
{id:2574,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Door-holding habit",desc:"Reliably holds doors open regardless of who's behind them.",example:"(holds the door, waits, however long it takes)",intensity:1,rarity:"common",pol:{}},
{id:2575,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Address-by-title user",desc:"Consistently uses proper titles rather than first names.",example:"Yes, Madam Chair, if I may add something.",intensity:2,rarity:"signature",pol:{}},
{id:2576,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Dietary-consideration asker",desc:"Checks others' preferences before serving food or drink.",example:"Is there anything you can't eat? I'll make sure to ask first.",intensity:1,rarity:"signature",pol:{}},
{id:2577,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Compliment-graceful receiver",desc:"Accepts praise with genuine, unfussy thanks rather than deflection.",example:"Thank you. That's very kind of you to say.",intensity:1,rarity:"common",pol:{}},
{id:2578,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Punctuality-respecting",desc:"Treats others' time as valuable, arriving precisely when expected.",example:"I said three, and it's three. Shall we begin?",intensity:2,rarity:"signature",pol:{}},
{id:2579,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Farewell-proper",desc:"Never leaves a gathering without a proper, individual goodbye.",example:"(makes a point of saying goodbye to each person by name)",intensity:1,rarity:"signature",pol:{}},
{id:2580,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Interruption-careless",desc:"Talks over others without registering it as rude.",example:"—no wait, listen, MY point is—",intensity:3,rarity:"common",pol:{}},
{id:2581,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Loud-eater",desc:"Eats without any concern for the noise or mess involved.",example:"(chews loudly, talks through it, doesn't notice)",intensity:2,rarity:"common",pol:{}},
{id:2582,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Personal-question asker",desc:"Asks intrusive questions without any social filter.",example:"So how much do you actually make, then?",intensity:3,rarity:"common",pol:{}},
{id:2584,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Volume-oblivious speaker",desc:"Talks at the same loud volume regardless of setting.",example:"(is just as loud in the library as at the tavern)",intensity:2,rarity:"common",pol:{}},
{id:2585,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Gift-critiquer",desc:"Comments negatively on gifts or gestures rather than thanking.",example:"Bit of an odd choice, wasn't it.",intensity:3,rarity:"signature",pol:{}},
{id:2586,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Never-says-please",desc:"Issues requests as flat demands, without any softening word.",example:"Pass the bread.",intensity:2,rarity:"common",pol:{}},
{id:2587,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Belch-unapologetic",desc:"Makes no effort to suppress or apologize for bodily noises.",example:"(belches, keeps talking, unbothered)",intensity:2,rarity:"signature",pol:{}},
{id:2588,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Insult-as-greeting",desc:"Opens conversations with a jab rather than a pleasantry.",example:"Still ugly, I see. Anyway, what do you want?",intensity:3,rarity:"signature",pol:{}},
{id:2589,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Table-manner-ignorer",desc:"Disregards even basic dining etiquette entirely.",example:"(elbows on the table, reaches across everyone)",intensity:2,rarity:"common",pol:{}},
{id:2590,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Temptation-resistant",desc:"Consistently declines immediate pleasures for long-term benefit.",example:"Could have it now. Better to wait. I'll wait.",intensity:3,rarity:"signature",pol:{}},
{id:2591,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Schedule-devoted",desc:"Maintains the same structured routine regardless of mood or circumstance.",example:"Same time, same order, every single day.",intensity:3,rarity:"common",pol:{}},
{id:2592,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Anger-contained",desc:"Feels strong anger but never lets it dictate their actions.",example:"(furious, visibly, and still speaks with total control)",intensity:3,rarity:"signature",pol:{}},
{id:2593,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Goal-tracking",desc:"Regularly checks progress against stated goals, adjusting as needed.",example:"Behind schedule. Adjusting the plan accordingly.",intensity:2,rarity:"signature",pol:{}},
{id:2594,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Distraction-resistant",desc:"Maintains focus on the task despite active interruption.",example:"(doesn't look up, doesn't respond, finishes the task first)",intensity:3,rarity:"signature",pol:{}},
{id:2595,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Consistent-effort giver",desc:"Applies the same level of diligence whether or not anyone's watching.",example:"No one's checking. Doing it properly anyway.",intensity:2,rarity:"common",pol:{}},
{id:2596,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Habit-builder",desc:"Deliberately constructs and maintains beneficial routines.",example:"Small thing, every day, adds up eventually.",intensity:2,rarity:"signature",pol:{}},
{id:2597,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Promise-keeper",desc:"Follows through on commitments even when it's become inconvenient.",example:"Said I would. Still will, even now.",intensity:3,rarity:"common",pol:{}},
{id:2598,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Emotion-scheduling",desc:"Deliberately postpones processing feelings until an appropriate time.",example:"Not now. I'll deal with that properly tonight.",intensity:2,rarity:"signature",pol:{}},
{id:2599,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Standard-maintainer",desc:"Refuses to lower their own quality bar even under pressure.",example:"Rushed or not, it still has to be done right.",intensity:3,rarity:"signature",pol:{}},
{id:2600,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Plan-abandoner",desc:"Drops carefully made plans the instant something more appealing appears.",example:"Forget the schedule, this is more interesting.",intensity:3,rarity:"common",pol:{}},
{id:2601,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Instant-gratification chaser",desc:"Consistently chooses the immediate reward over the better delayed one.",example:"Why wait? I want it now.",intensity:3,rarity:"common",pol:{}},
{id:2602,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Multiple-project starter",desc:"Begins many things enthusiastically, finishes very few.",example:"Started three of these. Somewhere. Probably.",intensity:2,rarity:"signature",pol:{}},
{id:2603,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Deadline-surpriser",desc:"Consistently discovers deadlines have arrived unprepared.",example:"Wait, that's due TODAY?",intensity:3,rarity:"common",pol:{}},
{id:2604,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Snap-decision maker",desc:"Commits to major choices with little to no deliberation.",example:"Decided. Doing it. Let's go.",intensity:3,rarity:"signature",pol:{}},
{id:2605,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Emotion-driven actor",desc:"Acts immediately on whatever feeling is currently strongest.",example:"I'm furious, so I'm doing something about it right now.",intensity:4,rarity:"signature",pol:{}},
{id:2606,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Routine-resistant",desc:"Actively rebels against structure, even structure that helps them.",example:"I don't do the same thing twice. Boring.",intensity:2,rarity:"signature",pol:{}},
{id:2607,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Budget-ignorer",desc:"Spends without tracking or regard for planned limits.",example:"It's fine. It's just money. There'll be more.",intensity:3,rarity:"common",pol:{}},
{id:2608,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Consequence-deferrer",desc:"Postpones thinking about outcomes until they've already arrived.",example:"I'll worry about that later. Much later.",intensity:2,rarity:"signature",pol:{}},
{id:2609,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Half-finished-task collector",desc:"Leaves a trail of nearly-completed things behind them.",example:"Almost done with that. And that. And that too, probably.",intensity:2,rarity:"signature",pol:{}},
{id:2610,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Rule-questioner",desc:"Asks 'why' before complying with any instruction.",example:"Why? Give me a reason and I'll consider it.",intensity:2,rarity:"common",pol:{}},
{id:2611,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Authority-mocker",desc:"Openly ridicules those in positions of power.",example:"Look at him, strutting around like that badge means something.",intensity:3,rarity:"signature",pol:{}},
{id:2612,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Punishment-unmoved",desc:"Accepts consequences without changing their behavior.",example:"Fine me, then. I'll do it again tomorrow.",intensity:4,rarity:"signature",pol:{}},
{id:2613,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Group-norm breaker",desc:"Deliberately does the opposite of what's socially expected.",example:"Everyone's doing it that way. Which is exactly why I won't.",intensity:3,rarity:"signature",pol:{}},
{id:2614,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Underground-organizer",desc:"Works quietly to undermine systems they disagree with.",example:"(passes a note under the table, says nothing aloud)",intensity:3,rarity:"signature",pol:{}},
{id:2615,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Loud-dissenter",desc:"Voices disagreement with authority publicly and without hesitation.",example:"No. And I'll say that in front of everyone.",intensity:4,rarity:"common",pol:{}},
{id:2616,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Tradition-dismisser",desc:"Rejects 'the way it's always been done' as a valid reason.",example:"'That's how it's always been' isn't an argument.",intensity:2,rarity:"signature",pol:{}},
{id:2617,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Consequence-accepting rebel",desc:"Weighs the cost of defiance and chooses it anyway, eyes open.",example:"I know what this costs. Doing it regardless.",intensity:4,rarity:"signature",pol:{}},
{id:2618,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Institution-distruster",desc:"Assumes official systems are working against ordinary people by default.",example:"Of course the report says that. Who do you think wrote it?",intensity:3,rarity:"signature",pol:{}},
{id:2619,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Symbol-defacer",desc:"Takes small, deliberate actions against symbols of authority.",example:"(scratches a mark into the official notice, walks on)",intensity:3,rarity:"signature",pol:{}},
{id:2620,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Instruction-follower precise",desc:"Executes given instructions exactly as stated, without deviation.",example:"You said left. I went left. Precisely as told.",intensity:2,rarity:"common",pol:{}},
{id:2621,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Chain-of-command respecter",desc:"Always defers a decision to whoever ranks above them.",example:"That's not mine to decide. Ask the captain.",intensity:2,rarity:"common",pol:{}},
{id:2622,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Precedent-follower",desc:"Chooses the established, proven method over any new approach.",example:"We've always done it this way. Let's keep doing it this way.",intensity:2,rarity:"signature",pol:{}},
{id:2623,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Rule-book quoter",desc:"Cites official policy to justify or explain their actions.",example:"Section four, paragraph two. It's right there.",intensity:2,rarity:"signature",pol:{}},
{id:2624,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Uniform-comfort seeker",desc:"Finds genuine comfort in shared dress codes and group conventions.",example:"Feels right, doesn't it — everyone matching, everyone together.",intensity:1,rarity:"signature",pol:{}},
{id:2625,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Non-question asker",desc:"Rarely questions why a rule exists before simply following it.",example:"It's the rule. That's really all I need to know.",intensity:2,rarity:"common",pol:{}},
{id:2626,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Institutional-trust holder",desc:"Defaults to believing official processes will produce fair outcomes.",example:"The system's there for a reason. I trust it.",intensity:2,rarity:"signature",pol:{}},
{id:2627,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Peer-alignment seeker",desc:"Adjusts behavior to match whatever the group is already doing.",example:"If that's what everyone's wearing, that's what I'll wear.",intensity:2,rarity:"signature",pol:{}},
{id:2628,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Disruption-avoider",desc:"Goes out of their way to avoid standing out or causing a stir.",example:"Let's not make waves. Just do it the normal way.",intensity:2,rarity:"common",pol:{}},
{id:2629,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Formal-process insister",desc:"Insists proper procedure be followed, even when inconvenient.",example:"We can't skip the paperwork. That's not how this works.",intensity:3,rarity:"signature",pol:{}},
{id:2630,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Tears-freely-shed",desc:"Cries without embarrassment at both sorrow and joy.",example:"(tears up, doesn't hide it) That's just — beautiful.",intensity:2,rarity:"common",pol:{}},
{id:2631,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Feeling-namer",desc:"Precisely identifies and articulates their emotional state aloud.",example:"This isn't anger. It's grief wearing anger's coat.",intensity:3,rarity:"signature",pol:{}},
{id:2632,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Physical-affection giver",desc:"Expresses care readily through touch and closeness.",example:"(pulls them into a hug without a second thought)",intensity:2,rarity:"common",pol:{}},
{id:2633,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Others'-pain absorber",desc:"Genuinely feels the weight of others' suffering as their own.",example:"I can't watch that. It hurts too much to see.",intensity:3,rarity:"signature",pol:{}},
{id:2634,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Vulnerability-first sharer",desc:"Leads with emotional honesty rather than working up to it.",example:"I'm scared. I'll just say that plainly.",intensity:3,rarity:"signature",pol:{}},
{id:2635,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Joy-unguarded",desc:"Expresses happiness fully, without self-consciousness.",example:"(laughs loud, unrestrained, genuinely delighted)",intensity:2,rarity:"common",pol:{}},
{id:2636,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Grief-honoring",desc:"Gives sorrow its full space rather than rushing past it.",example:"I need to sit with this a while. Don't rush me through it.",intensity:3,rarity:"signature",pol:{}},
{id:2637,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Emotional-check-in initiator",desc:"Regularly asks others how they're really doing.",example:"No, really — how are you? Actually.",intensity:2,rarity:"common",pol:{}},
{id:2638,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Feeling-forward decision maker",desc:"Weighs emotional impact heavily when making choices.",example:"I know it's practical. It still feels wrong. That matters to me.",intensity:2,rarity:"signature",pol:{}},
{id:2639,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Cathartic-release seeker",desc:"Actively processes emotion through expression rather than suppression.",example:"I need to say this out loud, or it'll eat me alive.",intensity:3,rarity:"signature",pol:{}},
{id:2640,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Feeling-deflector",desc:"Redirects any emotional conversation back to practical matters.",example:"Let's not do the feelings thing. What's the plan?",intensity:3,rarity:"common",pol:{}},
{id:2641,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Composure-obsessed",desc:"Prioritizes appearing unaffected above actually processing anything.",example:"I'm fine. I'm always fine. Moving on.",intensity:3,rarity:"signature",pol:{}},
{id:2642,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Humor-shield user",desc:"Deflects emotional moments with jokes before they can land.",example:"Tragic. Anyway — lunch?",intensity:3,rarity:"common",pol:{}},
{id:2643,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Emotion-intellectualizer",desc:"Discusses feelings analytically rather than actually experiencing them.",example:"Statistically, grief follows a predictable pattern.",intensity:3,rarity:"signature",pol:{}},
{id:2644,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Touch-avoidant",desc:"Physically stiffens or withdraws from affectionate contact.",example:"(stiffens slightly at the hug, pats a shoulder instead)",intensity:3,rarity:"signature",pol:{}},
{id:2645,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Surface-level responder",desc:"Offers only shallow, generic responses to emotional disclosures.",example:"That's rough. Anyway.",intensity:2,rarity:"common",pol:{}},
{id:2646,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Compartment-builder",desc:"Mentally files emotions away to deal with 'later', which never comes.",example:"Not now. I'll think about that some other time.",intensity:3,rarity:"signature",pol:{}},
{id:2647,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Vulnerability-punisher-internal",desc:"Privately regrets and withdraws after any moment of openness.",example:"(said too much last night; hasn't looked anyone in the eye since)",intensity:3,rarity:"signature",pol:{}},
{id:2648,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Task-refuge seeker",desc:"Retreats into busywork whenever emotion threatens to surface.",example:"Let me just — organize this. I need to organize this right now.",intensity:2,rarity:"signature",pol:{}},
{id:2649,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Numbness-normalizer",desc:"Treats their own emotional flatness as simply how they are, not a problem.",example:"I just don't feel much. Never really have.",intensity:4,rarity:"signature",pol:{}},
{id:2650,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Pattern-connector",desc:"Sees links between unrelated events others miss entirely.",example:"That's the third fire this month. Same pattern as the docks.",intensity:3,rarity:"signature",pol:{}},
{id:2651,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Assumption-tester",desc:"Instinctively checks the premises underlying any argument.",example:"Wait — why are we assuming that's even true?",intensity:3,rarity:"signature",pol:{}},
{id:2652,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Rapid-skill-absorber",desc:"Picks up new abilities noticeably faster than most.",example:"Show me once. I've got it.",intensity:2,rarity:"common",pol:{}},
{id:2653,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Multi-step planner",desc:"Thinks several moves ahead before committing to action.",example:"If we do this, he'll do that, which means we should—",intensity:3,rarity:"signature",pol:{}},
{id:2654,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Contradiction-spotter",desc:"Catches inconsistencies in others' stories almost immediately.",example:"That's not what you said an hour ago.",intensity:3,rarity:"signature",pol:{}},
{id:2655,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Elegant-solution finder",desc:"Solves problems with unexpectedly simple, efficient approaches.",example:"You don't need all that. Just do this instead.",intensity:2,rarity:"signature",pol:{}},
{id:2656,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Cross-domain thinker",desc:"Applies knowledge from one field usefully to unrelated problems.",example:"This is just supply and demand, dressed up differently.",intensity:3,rarity:"signature",pol:{}},
{id:2657,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Precise-question asker",desc:"Asks the one clarifying question that unlocks the whole problem.",example:"When exactly did the lock stop working? Before or after the storm?",intensity:2,rarity:"signature",pol:{}},
{id:2658,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Devil's-detail catcher",desc:"Notices the single flawed clause buried in a long document.",example:"Page three, second line. That's where it falls apart.",intensity:3,rarity:"signature",pol:{}},
{id:2659,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Rapid-recalculator",desc:"Adjusts their whole approach instantly when new facts emerge.",example:"New information. Different plan. Here's what we do now.",intensity:2,rarity:"common",pol:{}},
{id:2660,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Feel-it-out decider",desc:"Makes choices based on gut sense rather than weighing evidence.",example:"Can't explain it. Just feels wrong.",intensity:2,rarity:"common",pol:{}},
{id:2661,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Hands-on learner",desc:"Understands things only by physically doing them, not by explanation.",example:"Stop explaining. Just let me try it.",intensity:2,rarity:"common",pol:{}},
{id:2662,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Theory-impatient",desc:"Loses focus quickly when conversation turns abstract or theoretical.",example:"Alright, alright, but what do we actually DO?",intensity:3,rarity:"signature",pol:{}},
{id:2663,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Simple-explanation preferrer",desc:"Consistently chooses the plainest available account of events.",example:"He left because he wanted to leave. That's it.",intensity:2,rarity:"common",pol:{}},
{id:2664,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Present-moment focuser",desc:"Rarely thinks more than one step beyond the current situation.",example:"We'll figure out tomorrow, tomorrow.",intensity:2,rarity:"signature",pol:{}},
{id:2665,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"People-reader-nonverbal",desc:"Reads intentions through tone and body language rather than words.",example:"Don't care what he said. Didn't like how he said it.",intensity:3,rarity:"signature",pol:{}},
{id:2666,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Trial-and-error worker",desc:"Solves problems by simply trying things until something works.",example:"Didn't work. Try the other way.",intensity:2,rarity:"common",pol:{}},
{id:2667,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Concrete-example needer",desc:"Cannot grasp an idea until given a specific, tangible example.",example:"Give me an actual example. I don't follow the general idea.",intensity:2,rarity:"signature",pol:{}},
{id:2668,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Overthinking-suspicious",desc:"Distrusts people who deliberate too long over simple decisions.",example:"Why's he still thinking about it? Just pick one.",intensity:3,rarity:"signature",pol:{}},
{id:2669,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Instinct-trusting-under-pressure",desc:"Relies entirely on reflexive judgment during crisis moments.",example:"No time to think it through. Went with my gut.",intensity:3,rarity:"signature",pol:{}},
{id:2670,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Silver-lining default",desc:"Automatically searches for the good angle in any setback.",example:"Lost the crop, but we've got the seed for next year.",intensity:2,rarity:"common",pol:{}},
{id:2671,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Future-focused hopeful",desc:"Talks readily and warmly about what's coming next.",example:"Wait till spring. It'll be different, I promise.",intensity:2,rarity:"common",pol:{}},
{id:2672,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Effort-praiser",desc:"Finds encouragement to offer even in failed attempts.",example:"Didn't land, but that was a good try. Really was.",intensity:2,rarity:"common",pol:{}},
{id:2674,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Good-news-carrier",desc:"Actively seeks out and shares positive developments.",example:"You'll want to hear this — it's actually good news for once.",intensity:2,rarity:"common",pol:{}},
{id:2675,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Faith-in-people holder",desc:"Genuinely expects others to act well, and is rarely bitter when wrong.",example:"He'll come through. People usually do, given the chance.",intensity:2,rarity:"signature",pol:{}},
{id:2676,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Humor-in-hardship finder",desc:"Locates genuine comedy even in difficult circumstances.",example:"Well, it can't get much worse. (It does.) There it is, then.",intensity:2,rarity:"signature",pol:{}},
{id:2677,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Gratitude-practicer",desc:"Regularly and genuinely names things they're thankful for.",example:"Rained the whole way, but we made it. Grateful for that.",intensity:2,rarity:"common",pol:{}},
{id:2678,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Possibility-namer",desc:"Points out potential opportunities others overlook in setbacks.",example:"This actually opens a door we didn't have before.",intensity:2,rarity:"signature",pol:{}},
{id:2679,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Energy-lifter",desc:"Deliberately works to raise the mood of a discouraged room.",example:"Alright, enough moping — who wants to actually fix this?",intensity:3,rarity:"signature",pol:{}},
{id:2680,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Worst-case-planner",desc:"Automatically plans for the most negative possible outcome.",example:"And if that fails too — which it will — then what?",intensity:3,rarity:"signature",pol:{}},
{id:2681,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Motive-doubter",desc:"Assumes hidden self-interest behind others' kindness.",example:"Nobody helps for free. What does he actually want?",intensity:3,rarity:"signature",pol:{}},
{id:2682,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Told-you-so keeper",desc:"Takes grim satisfaction in having predicted failure.",example:"Said this would happen. Right there, back in March.",intensity:2,rarity:"signature",pol:{}},
{id:2683,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Hope-resistant",desc:"Actively refuses to get invested in good outcomes to avoid disappointment.",example:"Not getting my hopes up. That's how it gets you.",intensity:3,rarity:"signature",pol:{}},
{id:2684,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Progress-doubter",desc:"Assumes systemic problems will never actually improve.",example:"Same issue, new coat of paint. Nothing really changes.",intensity:3,rarity:"signature",pol:{}},
{id:2685,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Compliment-deflector-grim",desc:"Turns down praise by assuming it won't last or matter.",example:"Sure, today it's good. Wait till tomorrow.",intensity:2,rarity:"signature",pol:{}},
{id:2686,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Dark-humor coping",desc:"Processes bad news through bleak, deadpan jokes.",example:"Well. At least the funeral's paid for.",intensity:3,rarity:"common",pol:{}},
{id:2687,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Disappointment-braced",desc:"Approaches every new hope already expecting it to fail.",example:"Let's see how long this lasts before it falls apart too.",intensity:3,rarity:"signature",pol:{}},
{id:2688,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Cheerfulness-suspicious",desc:"Distrusts overly positive people or situations on principle.",example:"Nobody's that happy without something wrong underneath.",intensity:3,rarity:"signature",pol:{}},
{id:2689,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Realist-insister",desc:"Frames their pessimism explicitly as clear-eyed realism.",example:"Call it pessimism if you like. I call it having read the file.",intensity:2,rarity:"signature",pol:{}},
{id:2690,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Early-morning starter",desc:"Begins the day well before it's necessary to.",example:"Up since five. Half the day's chores already done.",intensity:2,rarity:"common",pol:{}},
{id:2691,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Fidget-while-seated",desc:"Cannot stay physically still even during calm conversation.",example:"(taps, shifts, bounces a knee, the whole time)",intensity:2,rarity:"common",pol:{}},
{id:2692,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Task-stacker",desc:"Fills every spare minute with another small task.",example:"While the water boils, I'll just sort these too.",intensity:3,rarity:"signature",pol:{}},
{id:2693,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Outdoor-preferring",desc:"Consistently chooses activity and open air over rest indoors.",example:"Nice day for it. Let's not waste it sitting around.",intensity:2,rarity:"common",pol:{}},
{id:2694,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Physical-solution reacher",desc:"Reaches for the physical fix before the clever one.",example:"Or — we could just break the lock.",intensity:2,rarity:"signature",pol:{}},
{id:2695,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Recovery-quick mover",desc:"Bounces back to activity almost immediately after rest.",example:"Five minutes was plenty. Ready when you are.",intensity:2,rarity:"signature",pol:{}},
{id:2696,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Stillness-uncomfortable",desc:"Visibly restless during any period of forced inactivity.",example:"How much longer is this meeting, genuinely.",intensity:3,rarity:"signature",pol:{}},
{id:2697,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Volunteer-for-labor",desc:"Steps up first for physically demanding tasks.",example:"I'll carry it. Give it here.",intensity:2,rarity:"common",pol:{}},
{id:2698,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Pacing-thinker",desc:"Thinks best while walking rather than sitting still.",example:"(paces the length of the room while working it out)",intensity:2,rarity:"signature",pol:{}},
{id:2700,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Comfort-prioritizer",desc:"Consistently chooses the easier, less strenuous option available.",example:"There's a shortcut. Found it because I couldn't be bothered.",intensity:2,rarity:"common",pol:{}},
{id:2701,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Slow-riser",desc:"Takes considerable time to get moving each morning.",example:"Give me another hour. Maybe two.",intensity:2,rarity:"common",pol:{}},
{id:2702,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Delegator-of-effort",desc:"Passes physical tasks to others as a matter of habit.",example:"You're already up. Would you mind?",intensity:2,rarity:"signature",pol:{}},
{id:2704,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Rest-protective",desc:"Guards downtime fiercely, resistant to interruption.",example:"That hour's mine. The world can wait.",intensity:3,rarity:"signature",pol:{}},
{id:2705,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Energy-rationer",desc:"Consciously paces activity to avoid unnecessary exertion.",example:"No need to rush it. Save the energy for later.",intensity:2,rarity:"signature",pol:{}},
{id:2706,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Seated-thinker",desc:"Thinks best while completely still, resents being made to move.",example:"Can we just sit and talk this through instead?",intensity:2,rarity:"signature",pol:{}},
{id:2707,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Nap-prioritizer",desc:"Builds rest breaks into the day as a non-negotiable habit.",example:"Not now. It's my resting hour.",intensity:2,rarity:"signature",pol:{}},
{id:2708,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Effort-questioner",desc:"Asks whether a task is truly necessary before doing it.",example:"Does it actually need doing today, though?",intensity:2,rarity:"common",pol:{}},
{id:2709,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Chronically unhurried",desc:"Moves and responds at the same unhurried pace regardless of urgency.",example:"(ambles over, in no particular rush, to the emergency)",intensity:3,rarity:"signature",pol:{}},
{id:2730,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Belonging-to-a-place",desc:"Wants one specific place to finally feel like home.",example:"Just want somewhere that's mine. Really mine.",intensity:3,rarity:"common",pol:{}},
{id:2731,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Being-believed",desc:"Wants someone to finally accept their version of events.",example:"Just once, I want someone to say 'I believe you'.",intensity:3,rarity:"signature",pol:{}},
{id:2732,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Mastery-of-one-craft",desc:"Wants to become the undisputed best at a single, specific skill.",example:"Not the best in town. The best there's ever been.",intensity:3,rarity:"common",pol:{}},
{id:2733,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Undoing-a-mistake",desc:"Wants a specific chance to fix one past error.",example:"If I could just go back and do that one thing differently.",intensity:4,rarity:"signature",pol:{}},
{id:2734,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Being-chosen",desc:"Wants to be the one selected, not merely tolerated.",example:"Just pick me. For once, pick me first.",intensity:3,rarity:"signature",pol:{}},
{id:2735,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A-quiet-ending",desc:"Wants their life's final chapter to be peaceful, not dramatic.",example:"Don't need a grand finish. Just a quiet one.",intensity:2,rarity:"signature",pol:{}},
{id:2736,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Proving-capability",desc:"Wants to demonstrate they can do the thing everyone doubts.",example:"Watch. I'll show you I can do this.",intensity:3,rarity:"common",pol:{}},
{id:2737,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Reunion",desc:"Wants to be reunited with someone specific, whatever it costs.",example:"Doesn't matter how long it takes. I'm finding her.",intensity:4,rarity:"signature",pol:{}},
{id:2738,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A-fair-hearing",desc:"Wants their side of the story properly, formally heard.",example:"I just want someone to actually listen to my account.",intensity:2,rarity:"signature",pol:{}},
{id:2739,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Continuation-of-legacy",desc:"Wants the family name or work to meaningfully carry on.",example:"This can't end with me. It just can't.",intensity:3,rarity:"signature",pol:{}},
{id:2740,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-being-ordinary",desc:"Terrified of living a life that leaves no trace at all.",example:"Just another face. That's the nightmare. Being just another face.",intensity:3,rarity:"signature",pol:{}},
{id:2741,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-losing-control",desc:"Terrified of a situation spiraling beyond their management.",example:"If I'm not steering this, I don't know what happens.",intensity:3,rarity:"common",pol:{}},
{id:2742,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-disappointing-a-mentor",desc:"Terrified of letting down the one person whose opinion matters most.",example:"I can face anything except the look on his face if I fail.",intensity:3,rarity:"signature",pol:{}},
{id:2743,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-repeating-history",desc:"Terrified of a past tragedy happening again on their watch.",example:"Not again. I won't let it happen again.",intensity:4,rarity:"common",pol:{}},
{id:2744,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-being-unnecessary",desc:"Terrified of a world that no longer needs what they offer.",example:"What happens to me once nobody needs this anymore?",intensity:3,rarity:"signature",pol:{}},
{id:2745,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-public-failure",desc:"Terrified specifically of failing where everyone can see.",example:"Not here. Not in front of all of them.",intensity:3,rarity:"common",pol:{}},
{id:2746,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-silence",desc:"Terrified of being forgotten entirely, name and all.",example:"I don't want to just... stop being spoken of.",intensity:3,rarity:"signature",pol:{}},
{id:2747,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-becoming-a-burden",desc:"Terrified of needing more care than they can offer in return.",example:"Don't want to be something people have to carry.",intensity:3,rarity:"signature",pol:{}},
{id:2748,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-the-truth-coming-out",desc:"Terrified a specific hidden fact will eventually surface.",example:"If that ever gets out, everything's finished.",intensity:4,rarity:"signature",pol:{}},
{id:2749,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-empty-rooms",desc:"Terrified of ending up genuinely, permanently alone.",example:"The thought of an empty house — that's the one that gets me.",intensity:3,rarity:"signature",pol:{}},
{id:2750,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Left-holding-the-blame",desc:"Took the fall for something that wasn't fully their fault.",example:"I've carried that blame for eleven years. It was never all mine.",intensity:4,rarity:"signature",pol:{}},
{id:2751,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-promise-broken-by-them",desc:"Broke a vow they made and never forgave themselves for it.",example:"I said I'd be there. I wasn't. That's the whole wound.",intensity:4,rarity:"signature",pol:{}},
{id:2752,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Watched-a-home-destroyed",desc:"Saw the place that defined them taken or ruined.",example:"There's nothing left of it now. I still go back in my head, though.",intensity:4,rarity:"signature",pol:{}},
{id:2753,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Named-unworthy-publicly",desc:"Was declared unfit or unworthy in front of others.",example:"They said it out loud. In front of everyone. I still hear it.",intensity:4,rarity:"signature",pol:{}},
{id:2754,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-mentor-who-vanished",desc:"Was abandoned by the one person meant to guide them.",example:"One day he was there. Then he wasn't. No explanation, ever.",intensity:3,rarity:"signature",pol:{}},
{id:2755,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Survived-what-took-someone-else",desc:"Lived through something that took someone they loved instead.",example:"Why did I get to walk away and she didn't?",intensity:5,rarity:"signature",pol:{}},
{id:2756,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Trust-exploited-for-gain",desc:"Had their trust deliberately used against their own interests.",example:"I opened the door myself. That's what makes it worse.",intensity:4,rarity:"signature",pol:{}},
{id:2757,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-childhood-cut-short",desc:"Was forced into adult responsibility far too young.",example:"Wasn't really a child after that. Not really, not after.",intensity:4,rarity:"signature",pol:{}},
{id:2758,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Loved-someone-who-couldnt-love-back",desc:"Gave real devotion to someone incapable of returning it.",example:"I loved him properly. He just — wasn't built to love back.",intensity:3,rarity:"signature",pol:{}},
{id:2759,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Silenced-when-it-mattered-most",desc:"Was prevented from speaking at the one moment it truly counted.",example:"I had the words. Nobody let me say them.",intensity:4,rarity:"signature",pol:{}},
{id:2760,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'My-anger-protects-people'",desc:"Believes their rage is what keeps loved ones safe.",example:"If I stop being angry, who's left to protect anyone?",intensity:4,rarity:"signature",pol:{}},
{id:2761,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-have-to-earn-rest'",desc:"Believes relaxation must be paid for with excessive labor first.",example:"Can't stop yet. Haven't done enough to deserve stopping.",intensity:3,rarity:"signature",pol:{}},
{id:2762,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Kindness-is-a-weakness-others-exploit'",desc:"Believes gentleness inevitably gets used against them.",example:"Be soft and someone takes advantage. Every time.",intensity:3,rarity:"signature",pol:{}},
{id:2763,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-ruin-good-things-by-wanting-them'",desc:"Believes desire itself curses whatever they want.",example:"The second I really want something, it goes wrong.",intensity:4,rarity:"signature",pol:{}},
{id:2764,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Nobody-actually-changes'",desc:"Believes people are fixed and improvement is an illusion.",example:"He'll always be who he was. People don't really change.",intensity:2,rarity:"signature",pol:{}},
{id:2765,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'My-worth-is-conditional'",desc:"Believes their value depends entirely on continued usefulness.",example:"The moment I'm no use, that's the moment I'm nothing.",intensity:4,rarity:"signature",pol:{}},
{id:2766,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Love-always-has-a-price'",desc:"Believes affection is never freely given, only transacted.",example:"Nobody loves you for nothing. There's always a cost.",intensity:3,rarity:"signature",pol:{}},
{id:2767,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I'm-fundamentally-different-from-others'",desc:"Believes they're permanently outside normal human connection.",example:"I'm not built like other people. Never have been.",intensity:3,rarity:"signature",pol:{}},
{id:2768,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Silence-keeps-me-safe'",desc:"Believes speaking up always eventually leads to harm.",example:"Say nothing. Say nothing and you can't be blamed.",intensity:3,rarity:"signature",pol:{}},
{id:2769,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-deserved-what-happened'",desc:"Believes past harm was somehow a fair consequence they earned.",example:"I brought it on myself, if I'm honest.",intensity:4,rarity:"signature",pol:{}},
{id:2770,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Preemptive-verbal-strike",desc:"Attacks the argument before the other person finishes making it.",example:"I know where this is going. No. Absolutely not.",intensity:3,rarity:"common",pol:{}},
{id:2771,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Cold-calculated-aggressor",desc:"Becomes precisely, coldly strategic rather than hot-headed under threat.",example:"(voice drops, gets very calm) Now. Let's talk about consequences.",intensity:4,rarity:"signature",pol:{}},
{id:2772,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Protective-rage-trigger",desc:"Fights only, but ferociously, when someone else is endangered.",example:"Touch her again and you'll learn what I'm capable of.",intensity:4,rarity:"common",pol:{}},
{id:2773,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Escalation-comfortable",desc:"Doesn't de-escalate — meets rising tension with equal or greater force.",example:"You want this louder? Fine. Let's go louder.",intensity:4,rarity:"signature",pol:{}},
{id:2774,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Physical-first responder",desc:"Moves toward physical confrontation before exhausting words.",example:"(already between them, fists loose, before anyone's finished talking)",intensity:4,rarity:"signature",pol:{}},
{id:2775,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Grudge-fueled fighter",desc:"Draws on old resentment to fuel confrontation in the moment.",example:"This isn't just about today. This has been coming for years.",intensity:3,rarity:"signature",pol:{}},
{id:2776,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Humiliation-avoiding attacker",desc:"Fights hardest specifically to avoid public embarrassment.",example:"Not backing down. Not in front of everyone.",intensity:3,rarity:"signature",pol:{}},
{id:2777,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Territorial-defender",desc:"Fights fiercely over perceived encroachment on their space or role.",example:"This is mine. You don't get to just walk in and take it.",intensity:3,rarity:"common",pol:{}},
{id:2778,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Verbal-precision striker",desc:"Fights by finding and using the exact words that wound most.",example:"You want honesty? Fine. Here's exactly what I think of you.",intensity:4,rarity:"signature",pol:{}},
{id:2779,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Unshakeable-standoff holder",desc:"Refuses to yield ground once a confrontation has begun.",example:"I'm not moving. You'll have to make me.",intensity:4,rarity:"signature",pol:{}},
{id:2780,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Task-burial-escape",desc:"Immerses in unrelated busywork the instant conflict arises.",example:"There's actually a lot to organize right now, if you'll excuse me.",intensity:2,rarity:"common",pol:{}},
{id:2782,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Relationship-abandoner",desc:"Cuts contact entirely rather than work through a difficult moment.",example:"(simply stops answering, permanently, no explanation)",intensity:4,rarity:"signature",pol:{}},
{id:2783,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Substance-retreat",desc:"Turns to drink or distraction the moment things get difficult.",example:"(pours a drink before the conversation's even finished)",intensity:3,rarity:"signature",pol:{}},
{id:2784,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Fantasy-dissociation",desc:"Mentally checks out into imagined scenarios during real conflict.",example:"(nods along, entirely elsewhere in their head)",intensity:2,rarity:"signature",pol:{}},
{id:2785,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Preemptive-exit planner",desc:"Always has an escape route mapped before conflict can start.",example:"(already knows exactly which door leads out)",intensity:3,rarity:"signature",pol:{}},
{id:2786,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Silence-then-vanish",desc:"Goes quiet first, then physically disappears without warning.",example:"(stops talking, then simply isn't there anymore)",intensity:3,rarity:"common",pol:{}},
{id:2787,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Excuse-generating fleer",desc:"Invents plausible reasons to leave the instant tension rises.",example:"Actually, I just remembered I have somewhere to be.",intensity:2,rarity:"common",pol:{}},
{id:2788,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Sleep-escape",desc:"Retreats into sleep or exhaustion to avoid facing conflict.",example:"I just need to lie down. We'll deal with it later.",intensity:2,rarity:"signature",pol:{}},
{id:2789,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Group-scatter instinct",desc:"Disperses into a crowd to avoid being pinned down in conflict.",example:"(slips into the crowd, gone before anyone notices)",intensity:3,rarity:"signature",pol:{}},
{id:2790,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Blank-stare lock",desc:"Eyes fix on nothing, entirely unresponsive, under real pressure.",example:"(stares straight ahead, says nothing, for a long stretch)",intensity:4,rarity:"signature",pol:{}},
{id:2791,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Decision-paralysis freeze",desc:"Cannot choose between options once pressure crosses a threshold.",example:"I don't— I can't— which one— I don't know.",intensity:3,rarity:"common",pol:{}},
{id:2792,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Memory-blank under-stress",desc:"Genuinely loses access to information they know well, under threat.",example:"I know this. I know this. I can't— it's gone.",intensity:3,rarity:"signature",pol:{}},
{id:2793,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Compliance-freeze",desc:"Goes still and simply does whatever's asked, without agency.",example:"(nods, does exactly what's said, nothing more)",intensity:3,rarity:"signature",pol:{}},
{id:2794,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Physical-lock",desc:"Body goes rigid and immobile, unable to move at all.",example:"(cannot move, cannot speak, entirely locked in place)",intensity:4,rarity:"signature",pol:{}},
{id:2795,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Delayed-reaction freeze",desc:"Processes the stressful event only well after it's passed.",example:"Wait. Wait, what just happened? I need a minute.",intensity:3,rarity:"signature",pol:{}},
{id:2796,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Emotional-flatline under threat",desc:"Feels nothing at all in the moment, processes it much later.",example:"(completely calm, disturbingly so, in the middle of the crisis)",intensity:3,rarity:"signature",pol:{}},
{id:2797,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Task-abandonment freeze",desc:"Simply stops mid-action, unable to continue what they were doing.",example:"(hand stops halfway to the door, doesn't finish the motion)",intensity:3,rarity:"signature",pol:{}},
{id:2798,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Whisper-only freeze",desc:"Voice drops to barely audible, unable to speak at normal volume.",example:"(can only manage a whisper) ...I don't know what to do.",intensity:3,rarity:"signature",pol:{}},
{id:2799,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Statue-stillness under scrutiny",desc:"Becomes completely motionless the moment they're the center of attention.",example:"(doesn't move a muscle while everyone looks at them)",intensity:3,rarity:"common",pol:{}},
{id:2800,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Instant-surrender",desc:"Gives up their position the moment any resistance meets it.",example:"Fine, fine, you're right, whatever you say.",intensity:3,rarity:"common",pol:{}},
{id:2801,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Over-explaining appeaser",desc:"Justifies at exhausting length to avoid anyone's anger.",example:"Let me explain — no, let me really explain everything—",intensity:3,rarity:"signature",pol:{}},
{id:2802,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Compliment-flooding under pressure",desc:"Showers the threatening party with praise to defuse them.",example:"You're so right, you always know best, honestly—",intensity:3,rarity:"signature",pol:{}},
{id:2803,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Self-blame reflex",desc:"Immediately claims fault to end the conflict quickly.",example:"It's my fault. All of it. Let's just say it's my fault.",intensity:4,rarity:"common",pol:{}},
{id:2804,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Service-offering appeaser",desc:"Rushes to perform favors the instant tension appears.",example:"Let me — here, let me get that for you, anything you need.",intensity:3,rarity:"signature",pol:{}},
{id:2805,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Laughter-deflection under threat",desc:"Uses forced, anxious laughter to soften an angry party.",example:"(laughs, too quickly) Ha — no, you're totally right, ha—",intensity:3,rarity:"signature",pol:{}},
{id:2806,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Loyalty-pledging under pressure",desc:"Reassures the threatening party of devotion to end the conflict.",example:"I'm with you. Completely with you. Always have been.",intensity:3,rarity:"signature",pol:{}},
{id:2807,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Physical-shrinking appeaser",desc:"Makes themselves visibly smaller in the presence of anger.",example:"(shoulders drop, curls inward, takes up less space)",intensity:3,rarity:"signature",pol:{}},
{id:2808,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Preemptive-agreement giver",desc:"Agrees before the other person even finishes their demand.",example:"Yes — yes, whatever it is, yes.",intensity:3,rarity:"common",pol:{}},
{id:2809,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Gift-offering placater",desc:"Offers something of value to smooth over rising tension.",example:"Here, take it, please, just — let's not fight.",intensity:3,rarity:"signature",pol:{}},
{id:2810,section:"Social Role in a Group",category:"Leader",trait:"Consensus-forging leader",desc:"Leads by patiently building agreement rather than issuing orders.",example:"Let's hear everyone, then decide together.",intensity:2,rarity:"common",pol:{}},
{id:2811,section:"Social Role in a Group",category:"Leader",trait:"Crisis-only leader",desc:"Steps forward only when things go wrong, otherwise stays back.",example:"Normally I'd stay quiet. This isn't normal. Listen up.",intensity:3,rarity:"signature",pol:{}},
{id:2812,section:"Social Role in a Group",category:"Leader",trait:"Legacy-building leader",desc:"Leads with an eye toward what outlasts their own time in charge.",example:"We're not building this for us. We're building it for after.",intensity:3,rarity:"signature",pol:{}},
{id:2813,section:"Social Role in a Group",category:"Leader",trait:"Servant-first leader",desc:"Leads by serving the group's needs before their own authority.",example:"What do you all need from me? That comes first.",intensity:2,rarity:"signature",pol:{}},
{id:2814,section:"Social Role in a Group",category:"Leader",trait:"Reluctant-but-capable leader",desc:"Leads competently despite genuinely not wanting the role.",example:"Didn't ask for this. Doing it properly anyway.",intensity:2,rarity:"signature",pol:{}},
{id:2815,section:"Social Role in a Group",category:"Leader",trait:"Symbolic figurehead leader",desc:"Leads more through presence and reputation than direct action.",example:"(their name alone settles arguments before they've said a word)",intensity:2,rarity:"signature",pol:{}},
{id:2816,section:"Social Role in a Group",category:"Leader",trait:"Tactical delegator",desc:"Leads by matching each task precisely to the right person.",example:"You, the ropes. You, the map. Go.",intensity:2,rarity:"common",pol:{}},
{id:2817,section:"Social Role in a Group",category:"Leader",trait:"Inspirational orator-leader",desc:"Leads primarily by making people want to follow, not fear to disobey.",example:"We can do this. I've never been more certain of anything.",intensity:3,rarity:"signature",pol:{}},
{id:2818,section:"Social Role in a Group",category:"Leader",trait:"Quiet-example leader",desc:"Leads by modeling the standard rather than announcing it.",example:"(does the hard task first, without being asked, without comment)",intensity:2,rarity:"signature",pol:{}},
{id:2819,section:"Social Role in a Group",category:"Leader",trait:"Contested-authority leader",desc:"Leads while actively, visibly fending off challenges to the role.",example:"Anyone else want to make that decision? No? Then it's mine.",intensity:3,rarity:"signature",pol:{}},
{id:2820,section:"Social Role in a Group",category:"Peacemaker",trait:"Preemptive-tension diffuser",desc:"Notices brewing conflict and intervenes before it fully forms.",example:"I can feel where this is headed. Let's stop it here.",intensity:2,rarity:"signature",pol:{}},
{id:2821,section:"Social Role in a Group",category:"Peacemaker",trait:"Shuttle-diplomat",desc:"Carries messages between two parties who won't speak directly.",example:"He says he'll listen if you go first. Will you?",intensity:2,rarity:"signature",pol:{}},
{id:2822,section:"Social Role in a Group",category:"Peacemaker",trait:"Humor-based peacemaker",desc:"Uses well-timed jokes specifically to defuse rising tension.",example:"Well, this is going wonderfully. Anyone hungry?",intensity:2,rarity:"common",pol:{}},
{id:2823,section:"Social Role in a Group",category:"Peacemaker",trait:"Old-grudge dissolver",desc:"Works patiently to end conflicts that have lasted years.",example:"It's been six years. Can we finally let this go?",intensity:3,rarity:"signature",pol:{}},
{id:2824,section:"Social Role in a Group",category:"Peacemaker",trait:"Neutral-ground provider",desc:"Offers themselves as the safe, unbiased space for both sides.",example:"Talk to me. I'm not on anyone's side here.",intensity:2,rarity:"common",pol:{}},
{id:2825,section:"Social Role in a Group",category:"Peacemaker",trait:"Emotional-translator",desc:"Explains each party's feelings to the other in terms they'll accept.",example:"He's not angry. He's scared, and it's coming out as angry.",intensity:3,rarity:"signature",pol:{}},
{id:2827,section:"Social Role in a Group",category:"Peacemaker",trait:"Post-conflict healer",desc:"Focuses specifically on repairing relationships after conflict ends.",example:"The fight's over. Now let's actually fix what it broke.",intensity:2,rarity:"signature",pol:{}},
{id:2828,section:"Social Role in a Group",category:"Peacemaker",trait:"Silent-mediator presence",desc:"Calms a room simply by being steady and present, without words.",example:"(says nothing; the room settles anyway, just from them being there)",intensity:1,rarity:"signature",pol:{}},
{id:2829,section:"Social Role in a Group",category:"Peacemaker",trait:"Boundary-setting peacemaker",desc:"Keeps peace by firmly stopping escalation rather than just soothing.",example:"That's enough. Both of you. Enough.",intensity:3,rarity:"signature",pol:{}},
{id:2830,section:"Social Role in a Group",category:"Instigator",trait:"Truth-forcing instigator",desc:"Provokes specifically to force an uncomfortable truth into the open.",example:"Somebody has to say it. Might as well be me, now.",intensity:3,rarity:"signature",pol:{}},
{id:2831,section:"Social Role in a Group",category:"Instigator",trait:"Status-quo challenger",desc:"Deliberately disrupts comfortable arrangements to test their strength.",example:"Why do we keep doing it this way? Has anyone actually asked?",intensity:2,rarity:"signature",pol:{}},
{id:2832,section:"Social Role in a Group",category:"Instigator",trait:"Rivalry-stoker",desc:"Deliberately fans competitive tension between others for effect.",example:"Bet you can't beat him. Just saying.",intensity:3,rarity:"signature",pol:{}},
{id:2833,section:"Social Role in a Group",category:"Instigator",trait:"Secret-revealer",desc:"Introduces disruption by surfacing information others wanted buried.",example:"Funny — nobody's mentioned where he actually was that night.",intensity:4,rarity:"signature",pol:{}},
{id:2834,section:"Social Role in a Group",category:"Instigator",trait:"Boredom-driven agitator",desc:"Stirs conflict simply because calm has become unbearable.",example:"It's too quiet. Something needs to happen.",intensity:2,rarity:"common",pol:{}},
{id:2835,section:"Social Role in a Group",category:"Instigator",trait:"Loyalty-testing instigator",desc:"Provokes situations specifically designed to reveal who's truly reliable.",example:"Let's see who actually shows up when it matters.",intensity:3,rarity:"signature",pol:{}},
{id:2836,section:"Social Role in a Group",category:"Instigator",trait:"Idea-provocateur",desc:"Introduces deliberately radical ideas to shake up stagnant thinking.",example:"What if we did the exact opposite of the plan?",intensity:2,rarity:"signature",pol:{}},
{id:2837,section:"Social Role in a Group",category:"Instigator",trait:"Public-challenge issuer",desc:"Provokes by directly, publicly daring someone to act.",example:"Go on, then. Prove me wrong. In front of everyone.",intensity:3,rarity:"signature",pol:{}},
{id:2838,section:"Social Role in a Group",category:"Instigator",trait:"Chaos-for-clarity instigator",desc:"Believes disruption is the fastest way to reveal what actually matters.",example:"Break it and see what people actually fight to save.",intensity:3,rarity:"signature",pol:{}},
{id:2839,section:"Social Role in a Group",category:"Instigator",trait:"Slow-burn instigator",desc:"Plants small provocations that only cause trouble much later.",example:"(says one quiet thing, weeks ago, that's only now starting fires)",intensity:3,rarity:"signature",pol:{}},
{id:2840,section:"Social Role in a Group",category:"Outsider",trait:"Voluntary-exile outsider",desc:"Chose distance from the group deliberately, not by circumstance.",example:"I could've stayed close. Didn't want to.",intensity:2,rarity:"signature",pol:{}},
{id:2841,section:"Social Role in a Group",category:"Outsider",trait:"Culturally-displaced outsider",desc:"Remains apart due to genuinely different origins or customs.",example:"We don't do it that way where I'm from. Never have.",intensity:2,rarity:"signature",pol:{}},
{id:2842,section:"Social Role in a Group",category:"Outsider",trait:"Formerly-inner-circle outsider",desc:"Was once fully accepted, then pushed to the margins.",example:"I used to be one of you. That was a long time ago.",intensity:3,rarity:"signature",pol:{}},
{id:2843,section:"Social Role in a Group",category:"Outsider",trait:"Silent-observer outsider",desc:"Watches the group closely without ever participating.",example:"(notices everything, says nothing, is never quite included)",intensity:2,rarity:"signature",pol:{}},
{id:2844,section:"Social Role in a Group",category:"Outsider",trait:"Principled-outsider",desc:"Stays apart specifically because they refuse to compromise a value the group has.",example:"You all made peace with it. I couldn't.",intensity:3,rarity:"signature",pol:{}},
{id:2845,section:"Social Role in a Group",category:"Outsider",trait:"Perpetual-newcomer",desc:"Never quite loses the feeling of having just arrived, even years later.",example:"Been here five years. Still feels like the first week sometimes.",intensity:2,rarity:"signature",pol:{}},
{id:2846,section:"Social Role in a Group",category:"Outsider",trait:"Information-isolated outsider",desc:"Kept apart because they hold knowledge the group doesn't trust.",example:"They don't tell me things anymore. Not since I found out.",intensity:3,rarity:"signature",pol:{}},
{id:2847,section:"Social Role in a Group",category:"Outsider",trait:"Self-sufficient outsider",desc:"Remains distant because they genuinely don't need the group's support.",example:"I manage fine on my own. Always have.",intensity:2,rarity:"common",pol:{}},
{id:2848,section:"Social Role in a Group",category:"Outsider",trait:"Envied-outsider",desc:"Kept at a distance by others' jealousy rather than their own choice.",example:"They don't dislike me. They just can't stand what I have.",intensity:3,rarity:"signature",pol:{}},
{id:2849,section:"Social Role in a Group",category:"Outsider",trait:"Returning-outsider",desc:"Comes back to a group that no longer quite knows what to do with them.",example:"I'm back. Doesn't mean I fit anymore, though.",intensity:3,rarity:"signature",pol:{}},
{id:2850,section:"Social Role in a Group",category:"Caretaker",trait:"Anticipatory caretaker",desc:"Notices and meets needs before anyone has to ask.",example:"(already has the blanket ready before they've said they're cold)",intensity:2,rarity:"common",pol:{}},
{id:2851,section:"Social Role in a Group",category:"Caretaker",trait:"Burnout-risking caretaker",desc:"Gives so much to others that their own needs go entirely unmet.",example:"I'm fine. Haven't really thought about myself in a while, actually.",intensity:4,rarity:"signature",pol:{}},
{id:2852,section:"Social Role in a Group",category:"Caretaker",trait:"Practical-support caretaker",desc:"Shows care through concrete action rather than words or comfort.",example:"Don't need to talk about it. I fixed the roof, though.",intensity:2,rarity:"signature",pol:{}},
{id:2853,section:"Social Role in a Group",category:"Caretaker",trait:"Emotional-barometer caretaker",desc:"Constantly monitors the group's collective mood and wellbeing.",example:"Something's off in the room today. Who wants to talk about it?",intensity:2,rarity:"signature",pol:{}},
{id:2854,section:"Social Role in a Group",category:"Caretaker",trait:"Boundary-holding caretaker",desc:"Cares for others while still protecting their own limits firmly.",example:"I'll help. Not at 2am, though. That's the line.",intensity:2,rarity:"signature",pol:{}},
{id:2855,section:"Social Role in a Group",category:"Caretaker",trait:"Legacy-of-care inheritor",desc:"Continues a caretaking role that was modeled by someone before them.",example:"My mother did this for everyone. Guess it's my turn now.",intensity:2,rarity:"signature",pol:{}},
{id:2856,section:"Social Role in a Group",category:"Caretaker",trait:"Crisis-specific caretaker",desc:"Only fully steps into the caretaking role during emergencies.",example:"Normal days, I'm not much use. Give me a crisis, though.",intensity:3,rarity:"signature",pol:{}},
{id:2857,section:"Social Role in a Group",category:"Caretaker",trait:"Unacknowledged caretaker",desc:"Provides essential care that goes consistently unnoticed by others.",example:"Nobody really sees what keeps this running. That's fine.",intensity:3,rarity:"signature",pol:{}},
{id:2858,section:"Social Role in a Group",category:"Caretaker",trait:"Teaching-caretaker",desc:"Cares for others by building their capability, not just comfort.",example:"I'm not doing it for you. I'm showing you how, so you can.",intensity:2,rarity:"signature",pol:{}},
{id:2859,section:"Social Role in a Group",category:"Caretaker",trait:"Animal-and-nature caretaker",desc:"Extends caretaking instincts specifically toward animals and land.",example:"The horses come first. Always have, always will.",intensity:2,rarity:"signature",pol:{}},
{id:2860,section:"Social Role in a Group",category:"Skeptic",trait:"Evidence-first skeptic",desc:"Requires concrete proof before accepting any claim, however small.",example:"Show me. Not tell me — show me.",intensity:2,rarity:"common",pol:{}},
{id:2861,section:"Social Role in a Group",category:"Skeptic",trait:"Motive-questioning skeptic",desc:"Doubts plans primarily by interrogating who benefits from them.",example:"Who actually gains if we do this? Follow that first.",intensity:3,rarity:"signature",pol:{}},
{id:2862,section:"Social Role in a Group",category:"Skeptic",trait:"Institutionally-burned skeptic",desc:"Distrusts official processes specifically due to past personal failure by them.",example:"Trusted the system once. Learned better.",intensity:3,rarity:"signature",pol:{}},
{id:2863,section:"Social Role in a Group",category:"Skeptic",trait:"Constructive skeptic",desc:"Questions plans specifically to strengthen them, not merely to doubt.",example:"Poke holes now, so it doesn't fall apart later.",intensity:2,rarity:"signature",pol:{}},
{id:2864,section:"Social Role in a Group",category:"Skeptic",trait:"Silent-doubt keeper",desc:"Holds serious reservations privately rather than voicing them.",example:"(nods along, entirely unconvinced, files it away)",intensity:2,rarity:"signature",pol:{}},
{id:2865,section:"Social Role in a Group",category:"Skeptic",trait:"Precedent-citing skeptic",desc:"Doubts new plans by pointing to similar past failures.",example:"We tried this. In '09. Ask me how that went.",intensity:2,rarity:"signature",pol:{}},
{id:2866,section:"Social Role in a Group",category:"Skeptic",trait:"Emotionally-detached skeptic",desc:"Distrusts anything that relies primarily on emotional appeal.",example:"That's a moving speech. Doesn't make it true.",intensity:3,rarity:"signature",pol:{}},
{id:2867,section:"Social Role in a Group",category:"Skeptic",trait:"Slow-to-trust skeptic",desc:"Extends belief only gradually, after sustained, consistent proof.",example:"Ask me again in a year. I'll have an answer by then.",intensity:2,rarity:"signature",pol:{}},
{id:2868,section:"Social Role in a Group",category:"Skeptic",trait:"Data-demanding skeptic",desc:"Insists on numbers and measurable outcomes over anecdote.",example:"Feelings aside — what do the actual figures say?",intensity:2,rarity:"common",pol:{}},
{id:2869,section:"Social Role in a Group",category:"Skeptic",trait:"Vindicated skeptic",desc:"Has been proven right about doubts often enough to trust their instincts fully.",example:"Told you. Every time, actually, if you check the record.",intensity:3,rarity:"signature",pol:{}},
{id:2870,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Oath-absolute holder",desc:"Treats a sworn vow as binding regardless of changed circumstances.",example:"I swore it. Circumstances don't unswear a vow.",intensity:4,rarity:"common",pol:{}},
{id:2871,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Consistency-demanding moralist",desc:"Applies the exact same standard to friends as to strangers.",example:"Same rule for him as for anyone else. No exceptions.",intensity:3,rarity:"signature",pol:{}},
{id:2872,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Public-accountability seeker",desc:"Insists on being judged by their own stated principles, openly.",example:"Hold me to it. Out loud, in front of everyone.",intensity:3,rarity:"signature",pol:{}},
{id:2873,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Line-in-the-sand holder",desc:"Has one specific, unmovable limit they will never cross.",example:"Everything else, we can negotiate. Not that. Never that.",intensity:4,rarity:"signature",pol:{}},
{id:2874,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Duty-above-comfort principled",desc:"Chooses obligation over ease every single time, without complaint.",example:"Wasn't going to be comfortable. Did it anyway. That's duty.",intensity:3,rarity:"signature",pol:{}},
{id:2875,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Truth-over-relationship principled",desc:"Will damage a relationship rather than compromise honesty.",example:"I'll lose you over this before I'll lie to you.",intensity:4,rarity:"signature",pol:{}},
{id:2876,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Rule-applies-to-me-too moralist",desc:"Holds themselves to the exact standard they demand of others.",example:"If it's wrong for them, it's wrong for me. Including me.",intensity:3,rarity:"signature",pol:{}},
{id:2877,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Inherited-code follower",desc:"Upholds a moral code passed down, unwilling to modernize it.",example:"This is how it was taught to me. This is how I'll do it.",intensity:2,rarity:"signature",pol:{}},
{id:2878,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Cost-accepting principled",desc:"Knowingly pays a real price to maintain a principle.",example:"This decision costs me. I'm making it anyway.",intensity:4,rarity:"signature",pol:{}},
{id:2879,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Zero-tolerance moralist",desc:"Treats even minor violations of principle as fully disqualifying.",example:"One lie. That's all it takes for me. One.",intensity:4,rarity:"signature",pol:{}},
{id:2880,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Situation-adaptive ethicist",desc:"Judges each case entirely on its own merits, no fixed rule.",example:"Different circumstances, different answer. That's just sense.",intensity:2,rarity:"signature",pol:{}},
{id:2881,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Outcome-first pragmatist",desc:"Judges the morality of an action almost entirely by its results.",example:"Worked, didn't it? That's what matters here.",intensity:3,rarity:"signature",pol:{}},
{id:2882,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Rule-as-guideline pragmatist",desc:"Treats formal rules as useful defaults, not binding law.",example:"The rule assumes a normal case. This isn't a normal case.",intensity:2,rarity:"signature",pol:{}},
{id:2884,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Deniability-conscious operator",desc:"Does what's necessary while maintaining formal, technical innocence.",example:"I never told you to. I told you the problem existed.",intensity:3,rarity:"signature",pol:{}},
{id:2885,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Negotiable-principle holder",desc:"Holds values that will bend under sufficiently strong pressure.",example:"Everything's got a price. Mine's just high.",intensity:3,rarity:"signature",pol:{}},
{id:2886,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Practical-compromise seeker",desc:"Prioritizes workable solutions over theoretically pure ones.",example:"Perfect plan that never happens beats a good plan we can't do.",intensity:2,rarity:"common",pol:{}},
{id:2887,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Context-first ethicist",desc:"Insists moral judgment requires knowing the full situation first.",example:"You don't know why she did it. Find that out before judging.",intensity:2,rarity:"signature",pol:{}},
{id:2889,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Future-weighted pragmatist",desc:"Accepts present cost for a better long-term outcome, deliberately.",example:"Hurts now. Worth it in five years. Doing it.",intensity:3,rarity:"signature",pol:{}},
{id:2890,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Blood-first loyalist",desc:"Places family obligation above nearly every other consideration.",example:"Family first. That's not up for debate.",intensity:3,rarity:"common",pol:{}},
{id:2891,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Debt-honoring loyalist",desc:"Treats a favor once received as a lifelong obligation to repay.",example:"He fed me once, years back. I owe him for that, still.",intensity:3,rarity:"signature",pol:{}},
{id:2892,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Silent-protector loyalist",desc:"Shields their people from consequence without ever being asked.",example:"Didn't say anything. Wasn't going to give him up.",intensity:3,rarity:"signature",pol:{}},
{id:2893,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Chosen-family loyalist",desc:"Extends unconditional loyalty to bonds they've built, not just blood.",example:"Blood's an accident. This we chose.",intensity:3,rarity:"signature",pol:{}},
{id:2894,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Reciprocity-strict loyalist",desc:"Tracks loyalty owed and given with careful, consistent precision.",example:"That's twice now he's covered for me. I owe him one back.",intensity:2,rarity:"signature",pol:{}},
{id:2895,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Institutional loyalist",desc:"Extends deep loyalty to an organization rather than individuals.",example:"I bleed for this company. Have since the day I started.",intensity:2,rarity:"signature",pol:{}},
{id:2896,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Last-one-standing loyalist",desc:"Remains loyal even after everyone else has abandoned the cause.",example:"Everyone else left. I'm still here. Still with him.",intensity:4,rarity:"signature",pol:{}},
{id:2897,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Loyalty-tested-and-passed",desc:"Has proven their loyalty through a specific, costly past choice.",example:"Ask him what I gave up for this. Ask him.",intensity:3,rarity:"signature",pol:{}},
{id:2898,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Generational loyalist",desc:"Honors commitments and alliances inherited from previous generations.",example:"My father made that promise. It's mine to keep now.",intensity:2,rarity:"signature",pol:{}},
{id:2899,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Silent-suffering loyalist",desc:"Endures personal cost quietly rather than betray a loyalty.",example:"I'm managing. Doesn't matter what it costs me. I'm managing.",intensity:4,rarity:"signature",pol:{}},
{id:2900,section:"Values & Moral Line",category:"Self-Interested",trait:"Efficient self-interest tracker",desc:"Calculates personal benefit quickly and openly in every situation.",example:"What's in it for me? Genuinely asking.",intensity:2,rarity:"common",pol:{}},
{id:2901,section:"Values & Moral Line",category:"Self-Interested",trait:"Reputation-managing self-interested",desc:"Frames moral choices around how they'll be perceived, not principle.",example:"The question isn't whether it's wrong. It's who tells the story.",intensity:3,rarity:"signature",pol:{}},
{id:2902,section:"Values & Moral Line",category:"Self-Interested",trait:"Comfort-preserving self-interested",desc:"Avoids any personal risk, however small, for a principle.",example:"It's terrible, sure. Not risking myself over it, though.",intensity:3,rarity:"signature",pol:{}},
{id:2903,section:"Values & Moral Line",category:"Self-Interested",trait:"Opportunistic self-interested",desc:"Shifts position readily to whatever currently benefits them most.",example:"The wind changed. So did I. Simple as that.",intensity:3,rarity:"signature",pol:{}},
{id:2904,section:"Values & Moral Line",category:"Self-Interested",trait:"Debt-avoiding self-interested",desc:"Refuses favors specifically to avoid future obligation to anyone.",example:"Don't do me favors. I don't want to owe you.",intensity:2,rarity:"signature",pol:{}},
{id:2905,section:"Values & Moral Line",category:"Self-Interested",trait:"Self-preservation-first",desc:"Prioritizes their own survival over nearly any other consideration.",example:"I'd like to be brave. I'd like more to be alive.",intensity:3,rarity:"common",pol:{}},
{id:2906,section:"Values & Moral Line",category:"Self-Interested",trait:"Transactional self-interested",desc:"Treats every relationship explicitly as an exchange with terms.",example:"I'll help. What do I get for it?",intensity:3,rarity:"common",pol:{}},
{id:2907,section:"Values & Moral Line",category:"Self-Interested",trait:"Blame-shifting self-interested",desc:"Reflexively relocates responsibility away from themselves.",example:"Wasn't my call. I just followed what I was told.",intensity:3,rarity:"signature",pol:{}},
{id:2908,section:"Values & Moral Line",category:"Self-Interested",trait:"Quiet-defector self-interested",desc:"Abandons commitments at the precise moment it stops benefiting them.",example:"(gone by morning, the moment the deal stopped paying)",intensity:4,rarity:"signature",pol:{}},
{id:2909,section:"Values & Moral Line",category:"Self-Interested",trait:"Loyalty-for-hire self-interested",desc:"Genuinely loyal for exactly as long as they're being paid.",example:"You've got me till the money runs out. Fair terms, though.",intensity:3,rarity:"signature",pol:{}},
{id:2910,section:"Attachment & Intimacy Style",category:"Secure",trait:"Trust-extends-first",desc:"Offers trust readily as a starting point, adjusting only on real evidence.",example:"I'll trust you until you give me a reason not to.",intensity:2,rarity:"common",pol:{}},
{id:2911,section:"Attachment & Intimacy Style",category:"Secure",trait:"Comfortable-with-distance",desc:"Doesn't read a partner's need for space as rejection.",example:"Go, take your time. I'm not going anywhere.",intensity:2,rarity:"signature",pol:{}},
{id:2912,section:"Attachment & Intimacy Style",category:"Secure",trait:"Direct-needs communicator",desc:"States relationship needs plainly, without fear of the reaction.",example:"I need more time together lately. Just saying it plainly.",intensity:2,rarity:"common",pol:{}},
{id:2913,section:"Attachment & Intimacy Style",category:"Secure",trait:"Conflict-survives-attachment",desc:"Trusts the relationship can withstand real disagreement.",example:"We can fight about this. It won't break us.",intensity:3,rarity:"signature",pol:{}},
{id:2914,section:"Attachment & Intimacy Style",category:"Secure",trait:"Emotionally-available presence",desc:"Remains open and present for a partner's feelings, even hard ones.",example:"Tell me. Whatever it is, I'm here for it.",intensity:2,rarity:"signature",pol:{}},
{id:2915,section:"Attachment & Intimacy Style",category:"Secure",trait:"Self-worth-independent secure",desc:"Doesn't need the relationship to validate their own value.",example:"I love you. I also know who I am without you.",intensity:2,rarity:"signature",pol:{}},
{id:2916,section:"Attachment & Intimacy Style",category:"Secure",trait:"Repair-without-shame",desc:"Apologizes and repairs ruptures without excessive self-punishment.",example:"I got that wrong. Let's fix it and move on.",intensity:2,rarity:"common",pol:{}},
{id:2917,section:"Attachment & Intimacy Style",category:"Secure",trait:"Generous-interpreter secure",desc:"Assumes good intent from a partner by default, checks if unsure.",example:"I don't think he meant it that way. I'll just ask him.",intensity:2,rarity:"signature",pol:{}},
{id:2918,section:"Attachment & Intimacy Style",category:"Secure",trait:"Steady-through-crisis secure",desc:"Attachment holds firm even through genuinely difficult periods.",example:"Worst year of our lives. Never once doubted us.",intensity:3,rarity:"signature",pol:{}},
{id:2919,section:"Attachment & Intimacy Style",category:"Secure",trait:"Healthy-interdependence holder",desc:"Balances closeness and independence without anxiety about either.",example:"I need you. I also don't need you to survive. Both true.",intensity:2,rarity:"signature",pol:{}},
{id:2920,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Tone-hypervigilant",desc:"Reads catastrophic meaning into tiny shifts in vocal tone.",example:"You said it differently that time. I heard it.",intensity:3,rarity:"signature",pol:{}},
{id:2921,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Reassurance-cycle repeater",desc:"Asks for the same reassurance repeatedly, briefly relieved each time.",example:"We're okay, right? Say it again. Please.",intensity:3,rarity:"signature",pol:{}},
{id:2922,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Preemptive-abandonment griever",desc:"Grieves a relationship's end before there's any sign it's ending.",example:"I keep bracing for you to leave. Even now.",intensity:3,rarity:"signature",pol:{}},
{id:2924,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Silence-catastrophizer",desc:"Interprets any pause in contact as evidence of rejection.",example:"You didn't answer. It's been an hour. What happened?",intensity:3,rarity:"common",pol:{}},
{id:2925,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Over-giving anxious attacher",desc:"Gives excessively, hoping it secures the bond permanently.",example:"I'll do anything. Just don't go. I'll do anything.",intensity:4,rarity:"signature",pol:{}},
{id:2926,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Jealousy-prone anxious",desc:"Reads threat into a partner's other relationships easily.",example:"Who is she? Why does she get to text you at midnight?",intensity:3,rarity:"signature",pol:{}},
{id:2927,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Apology-flooding anxious",desc:"Over-apologizes preemptively to prevent imagined conflict.",example:"Sorry — was that too much? I'm sorry, I'll stop.",intensity:3,rarity:"signature",pol:{}},
{id:2929,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Hyperattuned to micro-changes",desc:"Notices and worries over the smallest shifts in a partner's routine.",example:"You usually call by six. It's ten past.",intensity:2,rarity:"signature",pol:{}},
{id:2930,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Emotional-conversation dodger",desc:"Steers every serious talk back toward practical, safe topics.",example:"Let's not do the feelings thing. What's the plan?",intensity:3,rarity:"common",pol:{}},
{id:2931,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Independence-flag waver",desc:"Reminds partners often and unprompted of their self-sufficiency.",example:"I don't need this. I'm just choosing to be here.",intensity:3,rarity:"signature",pol:{}},
{id:2932,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Slow-to-disclose avoidant",desc:"Reveals personal history only after years of sustained contact.",example:"You've known me a decade. You know maybe four real things.",intensity:3,rarity:"signature",pol:{}},
{id:2934,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Criticism-finding avoidant",desc:"Becomes newly critical of a partner exactly when closeness deepens.",example:"She chews too loud. I've started noticing it a lot lately.",intensity:3,rarity:"signature",pol:{}},
{id:2935,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Busy-as-armor avoidant",desc:"Uses constant activity to avoid any extended emotional intimacy.",example:"Can't talk properly, so much on right now, always.",intensity:2,rarity:"common",pol:{}},
{id:2936,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Physical-presence-only avoidant",desc:"Shares space consistently while sharing almost nothing of their interior.",example:"(sits with them every evening, reveals almost nothing, for years)",intensity:3,rarity:"signature",pol:{}},
{id:2937,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Deactivation-under-closeness",desc:"Feels less, not more, connected the deeper a relationship gets.",example:"We got really close last month. I've been pulling back since.",intensity:4,rarity:"signature",pol:{}},
{id:2938,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Compliment-avoidant",desc:"Deflects or dismisses affection the moment it's offered.",example:"Sure, sure. Anyway, moving on.",intensity:2,rarity:"common",pol:{}},
{id:2939,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Solo-processing avoidant",desc:"Deals with hard emotions entirely alone, never inviting a partner in.",example:"I'll sort it myself. Don't need you for this part.",intensity:3,rarity:"signature",pol:{}},
{id:2940,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Approach-then-flee cycle",desc:"Moves toward closeness, then abruptly retreats from it, repeatedly.",example:"Come here — wait, no, go — I don't know, just, stay?",intensity:4,rarity:"common",pol:{}},
{id:2942,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Unpredictable-warmth cycles",desc:"Affection appears and vanishes without any traceable cause.",example:"(adoring one day, a stranger the next, no explanation)",intensity:4,rarity:"signature",pol:{}},
{id:2943,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Trust-then-retract",desc:"Grants total trust, then abruptly and completely withdraws it.",example:"Forget I said any of that. All of it. Forget it.",intensity:4,rarity:"signature",pol:{}},
{id:2944,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Testing-through-sabotage",desc:"Undermines the relationship specifically to see if it survives.",example:"I keep doing the thing that pushes people away. On purpose, almost.",intensity:4,rarity:"signature",pol:{}},
{id:2945,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Crisis-bonded disorganized",desc:"Only feels genuinely connected during shared emergency or chaos.",example:"When it was all on fire we were the best we've ever been.",intensity:3,rarity:"signature",pol:{}},
{id:2946,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Idealize-then-devalue cycle",desc:"Swings between total admiration and total contempt for the same person.",example:"You're the only good thing in my life. — You're exactly like the rest.",intensity:4,rarity:"signature",pol:{}},
{id:2947,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Dissociates-during-intimacy",desc:"Mentally leaves during moments of genuine emotional closeness.",example:"(present, then somewhere else entirely, mid-embrace)",intensity:3,rarity:"signature",pol:{}},
{id:2948,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Apology-and-repeat pattern",desc:"Genuinely remorseful after hurting a partner, reliably repeats it anyway.",example:"I meant it when I said sorry. I always mean it.",intensity:4,rarity:"signature",pol:{}},
{id:2949,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Contradictory-signal sender",desc:"Sends opposite messages about wanting closeness within the same conversation.",example:"Don't leave. Actually — leave. No — stay. I don't know.",intensity:4,rarity:"signature",pol:{}},
{id:2950,section:"Humor Style",category:"Dry & Deadpan",trait:"Understatement-comic",desc:"Describes disasters in the mildest possible terms for effect.",example:"Bit of a setback. The building's on fire.",intensity:3,rarity:"common",pol:{}},
{id:2951,section:"Humor Style",category:"Dry & Deadpan",trait:"Straight-man reactor",desc:"Delivers the flattest possible response to absurd situations.",example:"Noted. Anyway, the dragon.",intensity:3,rarity:"signature",pol:{}},
{id:2952,section:"Humor Style",category:"Dry & Deadpan",trait:"Factual-absurdist",desc:"States impossible things with total documentary seriousness.",example:"The horse has filed a formal complaint.",intensity:3,rarity:"signature",pol:{}},
{id:2953,section:"Humor Style",category:"Dry & Deadpan",trait:"No-punchline-signal comic",desc:"Never indicates when a joke has ended, leaving listeners uncertain.",example:"That's the whole story. (No further reaction.)",intensity:2,rarity:"signature",pol:{}},
{id:2954,section:"Humor Style",category:"Dry & Deadpan",trait:"Bureaucratic deadpan",desc:"Delivers absurd news in dry, procedural office language.",example:"Per section four, the apocalypse has been rescheduled.",intensity:3,rarity:"signature",pol:{}},
{id:2955,section:"Humor Style",category:"Dry & Deadpan",trait:"Slow-burn dry wit",desc:"Lands the joke several beats after it seems the moment has passed.",example:"...(long pause)...that horse, though.",intensity:2,rarity:"signature",pol:{}},
{id:2956,section:"Humor Style",category:"Dry & Deadpan",trait:"Weary-observation comic",desc:"Notes life's absurdities with tired, unimpressed precision.",example:"Of course it broke. Everything I touch, eventually.",intensity:2,rarity:"common",pol:{}},
{id:2957,section:"Humor Style",category:"Dry & Deadpan",trait:"Literal-response comic",desc:"Answers rhetorical or figurative statements with flat literalism.",example:"'Could eat a horse.' There's no horse. There's soup.",intensity:2,rarity:"common",pol:{}},
{id:2958,section:"Humor Style",category:"Dry & Deadpan",trait:"Minimal-effort wit",desc:"Delivers devastating jokes using the absolute fewest possible words.",example:"Ambitious. No.",intensity:3,rarity:"signature",pol:{}},
{id:2959,section:"Humor Style",category:"Dry & Deadpan",trait:"Anti-climax specialist",desc:"Builds toward drama, then deflates it with total flatness.",example:"And after all that — turns out it was unlocked the whole time.",intensity:2,rarity:"common",pol:{}},
{id:2960,section:"Humor Style",category:"Self-Deprecating",trait:"Disaster-résumé builder",desc:"Recounts their own failures like a list of accomplishments.",example:"Three shipwrecks, one small fire. I peaked early, clearly.",intensity:3,rarity:"signature",pol:{}},
{id:2961,section:"Humor Style",category:"Self-Deprecating",trait:"Preemptive-failure joker",desc:"Jokes about likely failure before even attempting the task.",example:"Watch this go badly. Everyone ready to watch this go badly?",intensity:2,rarity:"common",pol:{}},
{id:2962,section:"Humor Style",category:"Self-Deprecating",trait:"Compliment-undercutter",desc:"Turns any praise received into a joke at their own expense.",example:"Talented? No — lucky, mostly, and possibly a little haunted.",intensity:2,rarity:"signature",pol:{}},
{id:2963,section:"Humor Style",category:"Self-Deprecating",trait:"Physical-comedy self-target",desc:"Uses their own body or clumsiness as the punchline.",example:"Grace personified, obviously. (trips immediately after)",intensity:2,rarity:"common",pol:{}},
{id:2964,section:"Humor Style",category:"Self-Deprecating",trait:"Chronic-underachiever joker",desc:"Frames modest results as comically low personal bars cleared.",example:"Didn't fall over once today. Personal best.",intensity:2,rarity:"signature",pol:{}},
{id:2965,section:"Humor Style",category:"Self-Deprecating",trait:"Relationship-failure comic",desc:"Jokes specifically about their own romantic misfortunes.",example:"Third breakup this year. I'm basically a seasonal event now.",intensity:2,rarity:"signature",pol:{}},
{id:2966,section:"Humor Style",category:"Self-Deprecating",trait:"Intelligence-deprecator",desc:"Jokes about their own supposed lack of cleverness, often inaccurately.",example:"Not the sharpest tool. More of a spoon, really.",intensity:2,rarity:"common",pol:{}},
{id:2967,section:"Humor Style",category:"Self-Deprecating",trait:"Apology-comedy blender",desc:"Turns genuine apologies into small self-deprecating bits.",example:"Sorry — story of my life, honestly, being sorry.",intensity:2,rarity:"signature",pol:{}},
{id:2968,section:"Humor Style",category:"Self-Deprecating",trait:"Past-mistake recycler",desc:"Brings up old embarrassments repeatedly as a running joke on themselves.",example:"Ah yes, the wedding incident. We don't talk about the wedding incident.",intensity:2,rarity:"signature",pol:{}},
{id:2969,section:"Humor Style",category:"Self-Deprecating",trait:"Deflection-through-humility",desc:"Uses self-deprecation specifically to avoid taking real credit.",example:"Wasn't really me. I just got lucky and stood nearby.",intensity:2,rarity:"common",pol:{}},
{id:2970,section:"Humor Style",category:"Cruel & Barbed",trait:"Precision-wound comic",desc:"Finds and jokes about the exact thing someone's most sensitive about.",example:"Still doing the physio? Or have we given up on that.",intensity:4,rarity:"signature",pol:{}},
{id:2971,section:"Humor Style",category:"Cruel & Barbed",trait:"Public-humiliation joker",desc:"Delivers cutting jokes specifically designed to land in front of others.",example:"Tell them what you thought the plan actually was. Go on.",intensity:4,rarity:"signature",pol:{}},
{id:2972,section:"Humor Style",category:"Cruel & Barbed",trait:"Mock-affection cruelty",desc:"Delivers insults disguised as playful teasing, landing genuinely cruel.",example:"Oh, we love him. Like a dog that can almost talk.",intensity:3,rarity:"common",pol:{}},
{id:2973,section:"Humor Style",category:"Cruel & Barbed",trait:"Schadenfreude broadcaster",desc:"Openly delights, aloud, in others' misfortune.",example:"He fell IN? He actually fell IN? Incredible.",intensity:3,rarity:"signature",pol:{}},
{id:2974,section:"Humor Style",category:"Cruel & Barbed",trait:"Sarcastic-praise deliverer",desc:"Uses fake compliments as a vehicle for genuine contempt.",example:"Wonderful work. Genuinely inspired. Truly.",intensity:3,rarity:"common",pol:{}},
{id:2976,section:"Humor Style",category:"Cruel & Barbed",trait:"Silence-as-weapon comic",desc:"Uses a pointed pause instead of a joke to convey contempt.",example:"(says nothing, lets the silence do the cruelty)",intensity:3,rarity:"signature",pol:{}},
{id:2977,section:"Humor Style",category:"Cruel & Barbed",trait:"Name-calling in jest",desc:"Delivers genuinely hurtful nicknames under cover of humor.",example:"Morning, Lucky. (He is famously not lucky.)",intensity:3,rarity:"signature",pol:{}},
{id:2978,section:"Humor Style",category:"Cruel & Barbed",trait:"Truth-weaponizing comic",desc:"Uses accurate, devastating facts as the punchline.",example:"Tell them what you told me in the car. Word for word.",intensity:4,rarity:"signature",pol:{}},
{id:2979,section:"Humor Style",category:"Cruel & Barbed",trait:"Superiority-flaunting wit",desc:"Jokes that exist mainly to demonstrate they're smarter than the target.",example:"It's remarkable, watching you finally arrive at it.",intensity:3,rarity:"signature",pol:{}},
{id:2980,section:"Humor Style",category:"Warm & Playful",trait:"Inside-joke keeper",desc:"Maintains long-running private jokes as ongoing bonding rituals.",example:"Still counting the goats, by the way. Eleven now.",intensity:2,rarity:"common",pol:{}},
{id:2981,section:"Humor Style",category:"Warm & Playful",trait:"Affectionate-mimic comic",desc:"Lovingly imitates loved ones' habits and mannerisms.",example:"(does his exact walk; he laughs loudest of anyone)",intensity:2,rarity:"signature",pol:{}},
{id:2982,section:"Humor Style",category:"Warm & Playful",trait:"Compliment-comedian",desc:"Delivers affection disguised as teasing insults.",example:"You're a menace. My absolute favorite kind.",intensity:2,rarity:"common",pol:{}},
{id:2983,section:"Humor Style",category:"Warm & Playful",trait:"Group-joke includer",desc:"Structures humor so everyone in the room gets to be part of it.",example:"We're ALL idiots here, equally, don't worry.",intensity:2,rarity:"signature",pol:{}},
{id:2984,section:"Humor Style",category:"Warm & Playful",trait:"Playful-challenge issuer",desc:"Turns ordinary moments into lighthearted dares and games.",example:"Bet you can't do it in one try. Go on, then.",intensity:2,rarity:"signature",pol:{}},
{id:2985,section:"Humor Style",category:"Warm & Playful",trait:"Silly-voice user",desc:"Slips into ridiculous voices to lighten tense or dull moments.",example:"(switches to an absurd accent mid-sentence, commits fully)",intensity:2,rarity:"common",pol:{}},
{id:2986,section:"Humor Style",category:"Warm & Playful",trait:"Delighted-audience laugher",desc:"Laughs generously and easily at others' jokes, encouraging more.",example:"(laughs first, loudest, and completely genuinely)",intensity:1,rarity:"signature",pol:{}},
{id:2987,section:"Humor Style",category:"Warm & Playful",trait:"Wholesome-pun enthusiast",desc:"Cannot resist a groan-worthy pun, delivered with obvious joy.",example:"I'm not lion, that joke was purr-fect.",intensity:1,rarity:"common",pol:{}},
{id:2988,section:"Humor Style",category:"Warm & Playful",trait:"Storytelling comic",desc:"Builds warm, elaborate anecdotes purely for shared enjoyment.",example:"So — and this is true — the innkeeper had three sons, and—",intensity:2,rarity:"signature",pol:{}},
{id:2989,section:"Humor Style",category:"Warm & Playful",trait:"Comfort-through-silliness",desc:"Deploys gentle absurdity specifically to soothe someone upset.",example:"The cat's been promoted. I've told her. She's taken it well.",intensity:2,rarity:"signature",pol:{}},
{id:2990,section:"Humor Style",category:"Absurd & Chaotic",trait:"Escalating-nonsense builder",desc:"Takes a ridiculous premise and makes it steadily, gloriously worse.",example:"And by the fourth bishop, obviously, the whole boat was on fire.",intensity:3,rarity:"signature",pol:{}},
{id:2991,section:"Humor Style",category:"Absurd & Chaotic",trait:"Commitment-to-the-bit comic",desc:"Sustains an absurd joke long past any reasonable point.",example:"(still doing the accent, forty minutes later, unbothered)",intensity:3,rarity:"signature",pol:{}},
{id:2992,section:"Humor Style",category:"Absurd & Chaotic",trait:"Surreal-image generator",desc:"Produces bizarre, vivid mental pictures out of nowhere.",example:"He came through the door like a filing cabinet in mourning.",intensity:3,rarity:"signature",pol:{}},
{id:2993,section:"Humor Style",category:"Absurd & Chaotic",trait:"Wrong-moment specialist",desc:"Delivers jokes at precisely the least appropriate possible time.",example:"(at the solemn ceremony) Well. He'd have hated this bit.",intensity:3,rarity:"signature",pol:{}},
{id:2998,section:"Humor Style",category:"Absurd & Chaotic",trait:"Physical-chaos comedian",desc:"Relies on genuine slapstick and bodily comedy.",example:"(falls, makes it worse, makes it worse again, somehow)",intensity:2,rarity:"signature",pol:{}},
{id:2999,section:"Humor Style",category:"Absurd & Chaotic",trait:"Unpredictable-tangent comic",desc:"Sets up one joke and lands somewhere entirely different.",example:"—and that's when I realized I'd married the wrong brother.",intensity:3,rarity:"signature",pol:{}},
{id:3000,section:"Humor Style",category:"Humorless & Absent",trait:"Sincerity-only speaker",desc:"Responds to every statement, including jokes, with total earnestness.",example:"I don't understand. Is the horse real or not?",intensity:2,rarity:"common",pol:{}},
{id:3001,section:"Humor Style",category:"Humorless & Absent",trait:"Task-focus blind to comedy",desc:"Too absorbed in the practical matter to register any humor.",example:"Is any of this relevant to the actual gate?",intensity:2,rarity:"signature",pol:{}},
{id:3003,section:"Humor Style",category:"Humorless & Absent",trait:"Suspicious-of-humor",desc:"Assumes any joke aimed near them is really a veiled insult.",example:"Was that about me? That was about me, wasn't it.",intensity:3,rarity:"signature",pol:{}},
{id:3004,section:"Humor Style",category:"Humorless & Absent",trait:"Formal-context enforcer",desc:"Treats levity as inappropriate regardless of the actual setting.",example:"This is a serious meeting. Let's keep it serious.",intensity:3,rarity:"signature",pol:{}},
{id:3005,section:"Humor Style",category:"Humorless & Absent",trait:"Polite-but-unmoved audience",desc:"Acknowledges jokes intellectually without ever actually laughing.",example:"(a small, correct nod) Yes. That was a joke.",intensity:2,rarity:"common",pol:{}},
{id:3006,section:"Humor Style",category:"Humorless & Absent",trait:"Earnest-to-a-fault",desc:"Sincere in ways that unintentionally become the funniest thing in the room.",example:"(is the joke; will never once realize it)",intensity:2,rarity:"signature",pol:{}},
{id:3007,section:"Humor Style",category:"Humorless & Absent",trait:"Grief-flattened humor sense",desc:"Has genuinely lost the capacity for humor since a personal loss.",example:"Used to laugh at things like that. Don't anymore.",intensity:4,rarity:"signature",pol:{}},
{id:3008,section:"Humor Style",category:"Humorless & Absent",trait:"Duty-first blank responder",desc:"Registers jokes as a distraction from whatever task is at hand.",example:"Very good. The gate.",intensity:2,rarity:"common",pol:{}},
{id:3009,section:"Humor Style",category:"Humorless & Absent",trait:"Confusion-first reactor",desc:"Genuinely doesn't register when a statement was meant humorously.",example:"Hang on. Are we actually doing that or not?",intensity:2,rarity:"signature",pol:{}},
{id:3010,section:"Habits & Vices",category:"Substance & Consumption",trait:"Functional-dependence hider",desc:"Maintains a serious habit while appearing entirely composed to others.",example:"(third drink; hand perfectly steady; nobody would guess)",intensity:4,rarity:"signature",pol:{}},
{id:3011,section:"Habits & Vices",category:"Substance & Consumption",trait:"Occasion-only user",desc:"Indulges only at specific triggering events, but reliably every time.",example:"Only at funerals. Every single funeral, though.",intensity:2,rarity:"signature",pol:{}},
{id:3012,section:"Habits & Vices",category:"Substance & Consumption",trait:"Sharing-ritual drinker",desc:"Treats consumption primarily as a bonding ritual, not a solo habit.",example:"Not the same drinking alone. Needs company, this kind.",intensity:2,rarity:"common",pol:{}},
{id:3013,section:"Habits & Vices",category:"Substance & Consumption",trait:"Quantity-tracking user",desc:"Obsessively counts and monitors their own intake.",example:"That's three. I said I'd stop at three.",intensity:2,rarity:"signature",pol:{}},
{id:3014,section:"Habits & Vices",category:"Substance & Consumption",trait:"Stress-triggered consumer",desc:"Reaches for the habit specifically and reliably under pressure.",example:"Bad day. You know what that means.",intensity:3,rarity:"common",pol:{}},
{id:3015,section:"Habits & Vices",category:"Substance & Consumption",trait:"Secrecy-maintaining user",desc:"Goes to real lengths to hide the habit from people who'd worry.",example:"(bottle behind the loose brick; nobody's found it yet)",intensity:4,rarity:"signature",pol:{}},
{id:3016,section:"Habits & Vices",category:"Substance & Consumption",trait:"Morning-after regretter",desc:"Genuinely regrets each time, indulges again regardless.",example:"Never again. (Says this, reliably, every single time.)",intensity:3,rarity:"signature",pol:{}},
{id:3017,section:"Habits & Vices",category:"Substance & Consumption",trait:"Social-lubricant user",desc:"Relies on the habit specifically to function in group settings.",example:"Can't do parties sober. Just can't.",intensity:3,rarity:"signature",pol:{}},
{id:3018,section:"Habits & Vices",category:"Substance & Consumption",trait:"Quitting-and-relapsing cycle",desc:"Repeatedly attempts to stop, with genuine effort, and repeatedly returns.",example:"Four months clean. Then Tuesday happened.",intensity:4,rarity:"signature",pol:{}},
{id:3019,section:"Habits & Vices",category:"Substance & Consumption",trait:"Taste-ritual consumer",desc:"Treats consumption as a refined, deliberate ritual rather than compulsion.",example:"Not just a drink. The right glass, the right hour, the right silence.",intensity:2,rarity:"signature",pol:{}},
{id:3020,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Symmetry-demanding compulsive",desc:"Cannot rest until physical arrangements are perfectly even.",example:"That's crooked. I can't — give me one second.",intensity:3,rarity:"common",pol:{}},
{id:3021,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Counting-under-stress ritualist",desc:"Silently counts objects or steps as an anxiety management ritual.",example:"(counts the tiles, again, without meaning to)",intensity:2,rarity:"signature",pol:{}},
{id:3022,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Verification-loop compulsive",desc:"Checks the same thing repeatedly despite already confirming it.",example:"Locked it. Checking again. Locked it. Checking again.",intensity:3,rarity:"signature",pol:{}},
{id:3023,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Lucky-object dependent",desc:"Cannot function normally without a specific carried token.",example:"Where is it. Everyone stop. Where is it.",intensity:3,rarity:"signature",pol:{}},
{id:3024,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Pre-task ritual performer",desc:"Must complete a specific sequence before starting any important task.",example:"Not yet. Have to do the thing first. The usual thing.",intensity:2,rarity:"signature",pol:{}},
{id:3025,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Word-repetition compulsive",desc:"Silently repeats a phrase a fixed number of times for reassurance.",example:"(mouths it three times, exactly three, before answering)",intensity:2,rarity:"signature",pol:{}},
{id:3026,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Cleanliness-ritual performer",desc:"Washes or tidies in a specific, unvarying sequence, compulsively.",example:"Same order. Always the same order. Can't skip a step.",intensity:3,rarity:"signature",pol:{}},
{id:3027,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Threshold-ritual observer",desc:"Performs a small, specific action before crossing any doorway.",example:"(taps the frame twice, always twice, before entering)",intensity:2,rarity:"signature",pol:{}},
{id:3028,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"List-dependent compulsive",desc:"Cannot trust memory alone; must write everything down, always.",example:"If it's not written down, it isn't real. Write it down.",intensity:2,rarity:"common",pol:{}},
{id:3029,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Avoidance-pattern ritualist",desc:"Maintains a strict set of things they must never do or touch.",example:"Not that door. Never that door. Not since.",intensity:3,rarity:"signature",pol:{}},
{id:3030,section:"Habits & Vices",category:"Risk & Escape",trait:"Adrenaline-dependent risk-taker",desc:"Seeks danger specifically for the physical rush it provides.",example:"(takes the ridge in the dark, on purpose, again)",intensity:4,rarity:"signature",pol:{}},
{id:3031,section:"Habits & Vices",category:"Risk & Escape",trait:"Debt-spiral gambler",desc:"Continues risky wagers specifically to chase mounting losses.",example:"One more hand. This one turns it all around.",intensity:4,rarity:"common",pol:{}},
{id:3032,section:"Habits & Vices",category:"Risk & Escape",trait:"Escape-fantasy builder",desc:"Constructs detailed imagined alternate lives to mentally retreat into.",example:"In the other version, nobody here knows my name.",intensity:2,rarity:"signature",pol:{}},
{id:3033,section:"Habits & Vices",category:"Risk & Escape",trait:"Deadline-brinkmanship risk-taker",desc:"Waits until the last possible moment before acting, reliably.",example:"Loads of time. (there is, by any measure, no time)",intensity:3,rarity:"common",pol:{}},
{id:3034,section:"Habits & Vices",category:"Risk & Escape",trait:"Identity-shedding escapist",desc:"Fantasizes about or attempts to reinvent themselves entirely elsewhere.",example:"New name, new town. Clean slate. I've thought about it a lot.",intensity:3,rarity:"signature",pol:{}},
{id:3036,section:"Habits & Vices",category:"Risk & Escape",trait:"Financial-risk chaser",desc:"Takes reckless monetary gambles disproportionate to their means.",example:"Put it all on this. Why not. Why not, really.",intensity:4,rarity:"signature",pol:{}},
{id:3037,section:"Habits & Vices",category:"Risk & Escape",trait:"Physical-limit tester",desc:"Regularly pushes their own body past safe or sensible limits.",example:"One more mile. I can do one more mile.",intensity:3,rarity:"signature",pol:{}},
{id:3038,section:"Habits & Vices",category:"Risk & Escape",trait:"Secret-life builder",desc:"Maintains a hidden second existence as an escape from the first.",example:"(a whole other name, a whole other life, three towns over)",intensity:4,rarity:"signature",pol:{}},
{id:3039,section:"Habits & Vices",category:"Risk & Escape",trait:"Consequence-outrunning risk-taker",desc:"Believes, often incorrectly, they can outmaneuver the fallout of risk.",example:"I'll deal with it before it catches up. I always do.",intensity:3,rarity:"signature",pol:{}},
{id:3040,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Portion-strict practitioner",desc:"Measures and limits consumption with unwavering consistency.",example:"That's the portion. That's always exactly the portion.",intensity:2,rarity:"common",pol:{}},
{id:3041,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Public-commitment discipliner",desc:"Announces goals publicly specifically to enforce their own follow-through.",example:"Told everyone I'd quit. Can't back out now, can I.",intensity:2,rarity:"signature",pol:{}},
{id:3042,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Delayed-reward architect",desc:"Structures life deliberately around earned, postponed pleasures.",example:"After the harvest. Not before. After.",intensity:2,rarity:"common",pol:{}},
{id:3043,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Milestone-tracking abstainer",desc:"Marks and counts every day of a maintained restraint, precisely.",example:"Day two hundred and twelve. I keep exact count.",intensity:3,rarity:"signature",pol:{}},
{id:3044,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Environment-controlling discipliner",desc:"Removes temptation from their surroundings entirely, proactively.",example:"Don't keep it in the house. Simplest fix there is.",intensity:2,rarity:"signature",pol:{}},
{id:3045,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Substitution-strategy user",desc:"Replaces an old habit deliberately with a healthier structured one.",example:"Used to smoke here. Walk here now instead.",intensity:2,rarity:"signature",pol:{}},
{id:3046,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Accountability-partner reliant",desc:"Maintains discipline specifically through a trusted check-in relationship.",example:"Call me if you're tempted. That's the deal we made.",intensity:2,rarity:"signature",pol:{}},
{id:3047,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Ritual-replacement discipliner",desc:"Substitutes an old compulsive ritual with a new, controlled one.",example:"Used to need it every night. Now it's just tea. Every night.",intensity:2,rarity:"signature",pol:{}},
{id:3048,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Values-anchored abstainer",desc:"Ties their restraint explicitly to a core personal value or promise.",example:"Not for me. For her. That's why it holds.",intensity:3,rarity:"signature",pol:{}},
{id:3049,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Relapse-resilient discipliner",desc:"Treats a single slip as data, not total failure, and recommits.",example:"Slipped once. Didn't mean starting over from zero.",intensity:3,rarity:"signature",pol:{}},
{id:3050,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Aside-collector",desc:"Can't finish a sentence without slotting in a side comment.",example:"So we left — nice weather that day, by the way — and headed north.",intensity:2,rarity:"common",pol:{}},
{id:3051,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Enthusiasm-flooder",desc:"Excitement makes them narrate every detail of an event.",example:"And the cake! You have to hear about the cake too!",intensity:3,rarity:"common",pol:{}},
{id:3052,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Warning-repeater",desc:"Restates the same caution multiple times in different phrasing.",example:"Careful now. Really, be careful. I mean it, careful.",intensity:2,rarity:"signature",pol:{}},
{id:3053,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Backstory-insister",desc:"Won't let a topic move on until full context is given.",example:"You can't understand this without knowing what happened in '09.",intensity:3,rarity:"signature",pol:{}},
{id:3054,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Compliment-elaborator",desc:"Turns a simple compliment into an extended tribute.",example:"Not just good — genuinely, remarkably, unusually good.",intensity:2,rarity:"common",pol:{}},
{id:3055,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Excuse-multiplier",desc:"Offers several justifications when one would do.",example:"Traffic, and the rain, and I lost my keys, and then—",intensity:3,rarity:"signature",pol:{}},
{id:3056,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Sympathy-flooder",desc:"Responds to bad news with an outpouring of concern and questions.",example:"Oh no, are you alright, what happened, do you need anything?",intensity:2,rarity:"common",pol:{}},
{id:3057,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Update-obsessive",desc:"Provides constant unsolicited status reports on minor tasks.",example:"Still working on it. Getting there. Almost done. Nearly there.",intensity:3,rarity:"signature",pol:{}},
{id:3058,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Trivia-inserter",desc:"Interrupts their own point to share a barely-related fact.",example:"Which reminds me — did you know the bridge is older than the town?",intensity:2,rarity:"signature",pol:{}},
{id:3059,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Play-by-play narrator",desc:"Narrates their own actions aloud in real time.",example:"Picking this up now. Setting it there. Moving on.",intensity:2,rarity:"signature",pol:{}},
{id:3060,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Reassurance-repeater",desc:"Says calming phrases multiple times to make sure they land.",example:"It's fine. It's fine, really, it's completely fine.",intensity:2,rarity:"common",pol:{}},
{id:3061,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Group-recap giver",desc:"Summarizes what just happened for anyone who wasn't listening.",example:"So to catch you up, everything that just happened was—",intensity:2,rarity:"signature",pol:{}},
{id:3062,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Enthusiastic over-answerer",desc:"Answers simple questions with far more detail than needed.",example:"What time is it? Well, my watch says quarter past, though it runs a bit fast, so—",intensity:3,rarity:"common",pol:{}},
{id:3063,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Compulsive qualifier",desc:"Adds clarifying detail to nearly every statement made.",example:"It's good — well, good for a first attempt, I mean.",intensity:2,rarity:"signature",pol:{}},
{id:3064,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Circling closer",desc:"Approaches a hard topic through several increasingly direct passes.",example:"So, about the money — well, not exactly the money, but—",intensity:3,rarity:"signature",pol:{}},
{id:3065,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Unprompted-defender",desc:"Defends decisions nobody has actually questioned.",example:"I know what you're thinking, but here's why I did it—",intensity:2,rarity:"signature",pol:{}},
{id:3066,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Preamble-heavy asker",desc:"Builds elaborate context before finally stating a request.",example:"So, given everything going on, and I know it's a lot to ask, but—",intensity:3,rarity:"signature",pol:{}},
{id:3067,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Group-hype narrator",desc:"Talks up upcoming plans at exhausting, excited length.",example:"This is going to be incredible, you have no idea, wait till you see—",intensity:3,rarity:"common",pol:{}},
{id:3068,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Verbal-doodle talker",desc:"Fills quiet moments with meandering, low-stakes chatter.",example:"Anyway, nice sky today. Sort of orange. Reminds me of a scarf I had.",intensity:2,rarity:"signature",pol:{}},
{id:3069,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Reflexive over-thanker",desc:"Thanks people repeatedly and at length for small kindnesses.",example:"Thank you, really, thank you so much, you didn't have to—",intensity:2,rarity:"common",pol:{}},
{id:3070,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Verdict-only speaker",desc:"Delivers conclusions without any supporting explanation.",example:"No good.",intensity:3,rarity:"common",pol:{}},
{id:3071,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Cost-cutting talker",desc:"Removes every word not strictly necessary to be understood.",example:"Rope. Now.",intensity:3,rarity:"signature",pol:{}},
{id:3072,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"One-glance answerer",desc:"Responds to questions with a look rather than words whenever possible.",example:"(a raised brow answers it)",intensity:3,rarity:"signature",pol:{}},
{id:3073,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Order-only speaker",desc:"Speaks almost exclusively in short commands.",example:"Move. Left. Hold.",intensity:3,rarity:"common",pol:{}},
{id:3074,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Silence-preferring negotiator",desc:"Uses pauses instead of words to signal disagreement.",example:"(says nothing, lets the offer sit unanswered)",intensity:3,rarity:"signature",pol:{}},
{id:3075,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"No-elaboration policy",desc:"Refuses to explain reasoning behind decisions, ever.",example:"Because I said so. That's all you get.",intensity:3,rarity:"signature",pol:{}},
{id:3076,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Whisper-brief speaker",desc:"Speaks so quietly and briefly it's easy to miss entirely.",example:"(barely audible) ...no.",intensity:3,rarity:"signature",pol:{}},
{id:3077,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Grunt-primary communicator",desc:"Relies on wordless sounds for most ordinary exchanges.",example:"(a low sound of agreement, and nothing else, for the rest of the meal)",intensity:3,rarity:"common",pol:{}},
{id:3078,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Fact-only responder",desc:"Strips emotion and opinion from every reply, leaving bare fact.",example:"Dead. Three days now.",intensity:3,rarity:"signature",pol:{}},
{id:3079,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Economy-obsessed correspondent",desc:"Writes and speaks with maximum information density, minimum words.",example:"Ship late. Cargo fine. Send funds.",intensity:2,rarity:"signature",pol:{}},
{id:3080,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Blunt-refusal giver",desc:"Declines requests with the shortest possible negative.",example:"Can't.",intensity:3,rarity:"common",pol:{}},
{id:3081,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Terse-status reporter",desc:"Gives updates in clipped, minimal phrases only.",example:"Holding. For now.",intensity:2,rarity:"signature",pol:{}},
{id:3082,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Word-a-day rationer",desc:"Seems to treat speech as a genuinely finite daily resource.",example:"(three words all week)",intensity:4,rarity:"signature",pol:{}},
{id:3083,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"No-pleasantries speaker",desc:"Skips greetings and closings entirely, every time.",example:"Rope's frayed. Fix it.",intensity:2,rarity:"common",pol:{}},
{id:3084,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Silent-nod confirmer",desc:"Answers most yes-questions with a nod instead of a word.",example:"(nods once)",intensity:2,rarity:"common",pol:{}},
{id:3085,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Curt-appointment setter",desc:"States meeting details in the fewest words possible.",example:"Six. My office. Don't be late.",intensity:2,rarity:"signature",pol:{}},
{id:3086,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Bare-minimum apologizer",desc:"Offers the shortest possible acknowledgment of fault.",example:"My mistake.",intensity:2,rarity:"common",pol:{}},
{id:3087,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Single-syllable loyalist strict",desc:"Actively avoids multi-syllable words even when available.",example:"Bad plan. Won't work.",intensity:2,rarity:"signature",pol:{}},
{id:3088,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"No-small-talk enforcer",desc:"Redirects any casual chat back to the point immediately.",example:"Business first. Chat later, maybe.",intensity:3,rarity:"signature",pol:{}},
{id:3089,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Closed-book responder",desc:"Answers personal questions with the barest possible acknowledgment.",example:"Nothing to report.",intensity:3,rarity:"common",pol:{}},
{id:3090,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Interview-formal pace",desc:"Slows and measures words specifically when being questioned.",example:"I. Will. Answer. Carefully.",intensity:2,rarity:"signature",pol:{}},
{id:3091,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Reunion-rushed speaker",desc:"Words tumble out fast at the joy of seeing someone again.",example:"You're here you're actually here I can't believe you're here—",intensity:3,rarity:"common",pol:{}},
{id:3092,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Bad-news-slowed deliverer",desc:"Pace drops noticeably right before delivering hard news.",example:"I need to tell you something. It's — it's not good.",intensity:3,rarity:"common",pol:{}},
{id:3093,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Public-speaking-frozen",desc:"Pacing collapses entirely the moment attention turns to them.",example:"I— everyone's— sorry, give me a moment—",intensity:3,rarity:"signature",pol:{}},
{id:3094,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Late-arrival-rushed",desc:"Speaks in a rapid burst specifically when running behind schedule.",example:"Sorry-sorry-I'm-here-let's-just-start-now—",intensity:3,rarity:"common",pol:{}},
{id:3095,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Comfort-slowed speaker",desc:"Pacing eases the longer they're in trusted company.",example:"(starts clipped, ends relaxed and unhurried an hour in)",intensity:2,rarity:"signature",pol:{}},
{id:3096,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Storm-quickened talker",desc:"Speech noticeably speeds up as weather worsens around them.",example:"Wind's picking up — we need to move, now, quickly—",intensity:3,rarity:"signature",pol:{}},
{id:3098,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Negotiation-paced speaker",desc:"Deliberately controls tempo to hold leverage in a deal.",example:"(slows down exactly when the other side gets impatient)",intensity:3,rarity:"signature",pol:{}},
{id:3099,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Overwhelm-sped talker",desc:"Words accelerate as tasks pile up faster than they can manage.",example:"And this and that and also this and I haven't even—",intensity:3,rarity:"common",pol:{}},
{id:3100,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Ceremony-measured speaker",desc:"Paces every word deliberately during formal occasions.",example:"We. Are. Gathered. Here. Today.",intensity:2,rarity:"signature",pol:{}},
{id:3101,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Post-argument-drained pace",desc:"Speech slows and flattens once a conflict has ended.",example:"(the fight's over now; the words come slow and tired)",intensity:3,rarity:"signature",pol:{}},
{id:3102,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"First-word-hesitant",desc:"Struggles specifically with the opening of any hard conversation.",example:"I— I need— give me a second to start this properly.",intensity:2,rarity:"signature",pol:{}},
{id:3104,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Sudden-clarity quickened",desc:"Speeds up abruptly the instant a plan crystallizes.",example:"Wait — I've got it — here's exactly what we do—",intensity:3,rarity:"signature",pol:{}},
{id:3105,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Whispered-urgency pace",desc:"Speaks fast but quiet when danger is close and silence matters.",example:"(fast, hushed) —they're right outside, don't move—",intensity:3,rarity:"signature",pol:{}},
{id:3106,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Long-pause thinker",desc:"Leaves noticeably long silences before answering hard questions.",example:"...(ten full seconds)... Yes. I'm certain.",intensity:2,rarity:"signature",pol:{}},
{id:3107,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Adrenaline-then-crash speaker",desc:"Speeds through crisis, then visibly slows once it's over.",example:"(rapid through the emergency, suddenly slow once it's past)",intensity:3,rarity:"signature",pol:{}},
{id:3108,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Formal-occasion measured",desc:"Paces speech with ceremony regardless of the actual stakes.",example:"Let. It. Be. Known.",intensity:2,rarity:"signature",pol:{}},
{id:3109,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Interrogation-calm pace",desc:"Maintains unnervingly even pacing under hostile questioning.",example:"(answers every hostile question at the exact same measured pace)",intensity:3,rarity:"signature",pol:{}},
{id:3110,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Auctioneer-cadenced speaker",desc:"Falls into rapid, rhythmic patter when excited or selling something.",example:"Goingonce-goingtwice-andSOLD, my friends!",intensity:3,rarity:"signature",pol:{}},
{id:3111,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Proverb-closer",desc:"Ends important statements with an invented, wise-sounding saying.",example:"As they say — the slow horse still reaches the barn.",intensity:2,rarity:"signature",pol:{}},
{id:3112,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Knightly-address speaker",desc:"Addresses even casual acquaintances with chivalric formality.",example:"Good sir, might I trouble you for the hour?",intensity:3,rarity:"signature",pol:{}},
{id:3113,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Elegy-toned speaker",desc:"Speaks about ordinary loss with the weight of formal mourning.",example:"We have lost the good bread. Let us bow our heads.",intensity:3,rarity:"signature",pol:{}},
{id:3114,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Manifesto-voiced speaker",desc:"Delivers ordinary opinions with the force of a public declaration.",example:"Let it be known: this soup is an outrage.",intensity:3,rarity:"signature",pol:{}},
{id:3115,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Ancient-oath phraser",desc:"Frames modern promises in archaic, oath-like language.",example:"By all that I hold true, I shall not forget this.",intensity:3,rarity:"signature",pol:{}},
{id:3116,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Grand-arrival announcer",desc:"Introduces their own entrance with theatrical flourish.",example:"And NOW — arriving, at last — is me.",intensity:3,rarity:"common",pol:{}},
{id:3117,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Storyteller's-frame user",desc:"Frames ordinary updates as though opening an epic tale.",example:"In the third year of the drought, the well finally ran dry.",intensity:2,rarity:"signature",pol:{}},
{id:3118,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Velvet-diplomacy speaker",desc:"Wraps blunt demands in extravagantly polite phrasing.",example:"It would please me greatly if you would kindly comply, immediately.",intensity:3,rarity:"signature",pol:{}},
{id:3119,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Coronation-toned speaker",desc:"Delivers minor announcements with royal ceremony.",example:"Let the record show: dinner is served.",intensity:2,rarity:"signature",pol:{}},
{id:3120,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Elegant-refusal giver",desc:"Declines requests using ornate, indirect language.",example:"I fear circumstance conspires against so noble a request.",intensity:3,rarity:"signature",pol:{}},
{id:3121,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Antique-blessing giver",desc:"Offers farewells structured like old formal benedictions.",example:"May the road rise, and the wind favor your back.",intensity:2,rarity:"signature",pol:{}},
{id:3122,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Grandiose-apology giver",desc:"Turns small apologies into theatrical, over-elaborate speeches.",example:"I am wracked, utterly wracked, with the weight of my error.",intensity:3,rarity:"signature",pol:{}},
{id:3123,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Epic-simile user",desc:"Compares mundane events to legendary, larger-than-life imagery.",example:"Like Odysseus lost at sea, I too could not find my keys.",intensity:2,rarity:"signature",pol:{}},
{id:3124,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Formal-lament speaker",desc:"Voices minor complaints with the gravity of true tragedy.",example:"Alas, the tea has gone cold. A tragedy of our times.",intensity:2,rarity:"common",pol:{}},
{id:3125,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Court-jester's flourish",desc:"Adds a theatrical, performative flair to casual remarks.",example:"(a small bow) At your service, as always.",intensity:2,rarity:"signature",pol:{}},
{id:3126,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Solemn-vow phraser",desc:"Frames small promises with the weight of sacred commitment.",example:"This I vow, before all present: the dishes will be done.",intensity:2,rarity:"signature",pol:{}},
{id:3127,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Old-world greeting user",desc:"Opens conversations with elaborate, archaic greetings.",example:"Well met, friend, well met indeed.",intensity:2,rarity:"signature",pol:{}},
{id:3128,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Battle-cry speaker",desc:"Delivers ordinary encouragement with wartime intensity.",example:"FOR THE HARVEST! FORWARD, ALL OF YOU!",intensity:3,rarity:"signature",pol:{}},
{id:3129,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Reverent-object describer",desc:"Describes ordinary objects with quasi-sacred language.",example:"This cup — worn, humble, yet somehow eternal.",intensity:2,rarity:"signature",pol:{}},
{id:3130,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Tidal-rhythm words",desc:"Frames emotional cycles as ebb and flow.",example:"It comes and goes, like tide. Wait for the ebb.",intensity:2,rarity:"signature",pol:{}},
{id:3131,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Granite-and-stone diction",desc:"Describes stability and stubbornness through rock imagery.",example:"He won't move. Might as well argue with granite.",intensity:2,rarity:"signature",pol:{}},
{id:3132,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Feather-light vocabulary",desc:"Describes delicate or fleeting things through featherweight imagery.",example:"It was there, and gone, light as a feather falling.",intensity:2,rarity:"signature",pol:{}},
{id:3133,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Honeycomb-structured words",desc:"Frames complex systems as interlocking cells and chambers.",example:"Every part connects. Break one cell and the whole thing weakens.",intensity:3,rarity:"signature",pol:{}},
{id:3134,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Rust-and-decay vocabulary",desc:"Frames slow deterioration through corrosion imagery.",example:"It's not broken yet. Just rusting, slowly, at the joints.",intensity:3,rarity:"signature",pol:{}},
{id:3135,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Comet-trail words",desc:"Describes brief brilliance and fading through celestial streak imagery.",example:"He burned bright and fast, and then he was gone.",intensity:3,rarity:"signature",pol:{}},
{id:3136,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Loam-and-compost vocabulary",desc:"Frames renewal and slow transformation through soil-building imagery.",example:"Give the grief time. It becomes something, eventually.",intensity:2,rarity:"signature",pol:{}},
{id:3137,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Lantern-glow diction",desc:"Describes hope and guidance through small, steady light imagery.",example:"Just a small light. Enough to walk by, though.",intensity:2,rarity:"signature",pol:{}},
{id:3138,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Undertow vocabulary",desc:"Frames hidden danger and pull through ocean-current imagery.",example:"Careful. There's an undertow to that conversation.",intensity:3,rarity:"signature",pol:{}},
{id:3139,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Scaffold-and-frame words",desc:"Describes support structures through construction imagery.",example:"He's the scaffolding. Take him away and the whole thing sags.",intensity:2,rarity:"signature",pol:{}},
{id:3140,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Migratory-bird vocabulary",desc:"Frames seasonal change and return through migration imagery.",example:"She comes back every autumn. Always has, always will.",intensity:2,rarity:"signature",pol:{}},
{id:3141,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Cave-and-echo words",desc:"Describes isolation and reverberating consequence through cave imagery.",example:"Say it in here and it just keeps coming back at you.",intensity:2,rarity:"signature",pol:{}},
{id:3142,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Meadow-and-bloom diction",desc:"Frames gentle growth and flourishing through open-field imagery.",example:"Give it room. It'll bloom on its own time.",intensity:2,rarity:"signature",pol:{}},
{id:3143,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Anchor-and-chain words",desc:"Describes commitment and restraint through nautical mooring imagery.",example:"He's the anchor. Without him we'd have drifted years ago.",intensity:2,rarity:"signature",pol:{}},
{id:3144,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Kiln-and-fire vocabulary",desc:"Frames transformation through pressure using pottery-firing imagery.",example:"This won't hold its shape until it's been through the fire.",intensity:3,rarity:"signature",pol:{}},
{id:3145,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Prairie-wind vocabulary",desc:"Frames sweeping, unstoppable change through open-plain wind imagery.",example:"Nothing stops it once it's moving. Like wind on the prairie.",intensity:2,rarity:"signature",pol:{}},
{id:3146,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Threshold-light words",desc:"Describes liminal moments and transitions through doorway-light imagery.",example:"Standing right at the edge of it. Haven't stepped through yet.",intensity:2,rarity:"signature",pol:{}},
{id:3147,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Riverbed-carved diction",desc:"Frames habit and long repetition through water-carved stone imagery.",example:"Years of doing it that way. It's worn a channel by now.",intensity:3,rarity:"signature",pol:{}},
{id:3148,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Nest-and-shelter words",desc:"Describes safety and belonging through small-shelter imagery.",example:"This is the one place that still feels like a nest.",intensity:2,rarity:"signature",pol:{}},
{id:3149,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Avalanche-onset vocabulary",desc:"Frames small triggers causing large collapse through snowslide imagery.",example:"One word set it off. After that, there was no stopping it.",intensity:3,rarity:"signature",pol:{}},
{id:3150,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Ember-banked vocabulary",desc:"Chooses words suggesting contained heat that could reignite.",example:"It's not out. Just banked, waiting.",intensity:3,rarity:"signature",pol:{}},
{id:3151,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Threadbare-patience words",desc:"Uses vocabulary suggesting patience worn nearly through.",example:"I'm hanging on. Barely. By threads.",intensity:3,rarity:"signature",pol:{}},
{id:3152,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Startled-deer diction",desc:"Chooses vocabulary evoking sudden, skittish alarm.",example:"He flinched like I'd raised a hand. Just from the question.",intensity:3,rarity:"signature",pol:{}},
{id:3153,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Molten-anger vocabulary",desc:"Chooses words suggesting anger that could reshape everything it touches.",example:"I'm not cold about this. I'm molten. Give me space.",intensity:4,rarity:"signature",pol:{}},
{id:3154,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Overflowing-cup words",desc:"Describes accumulated feeling reaching a breaking point.",example:"One more thing. Just one more thing and I'll break.",intensity:3,rarity:"signature",pol:{}},
{id:3155,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Held-breath vocabulary",desc:"Chooses words suggesting suspended, anticipatory tension.",example:"We're all just — waiting. Holding our breath, really.",intensity:2,rarity:"signature",pol:{}},
{id:3156,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Unmoored-grief diction",desc:"Describes sorrow as drifting, directionless, and vast.",example:"I don't know where to put this feeling. It's everywhere.",intensity:4,rarity:"signature",pol:{}},
{id:3157,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Quietly-devastated words",desc:"Chooses restrained vocabulary that still carries visible weight.",example:"I'm alright. (It is clear they are not.)",intensity:3,rarity:"signature",pol:{}},
{id:3158,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Sun-warmed contentment vocabulary",desc:"Describes peace and satisfaction through gentle warmth imagery.",example:"Feels good. Simple, warm, good.",intensity:1,rarity:"common",pol:{}},
{id:3159,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Bristling-defense diction",desc:"Chooses words that suggest instinctive, protective sharpness.",example:"Say that again and see what happens.",intensity:3,rarity:"signature",pol:{}},
{id:3160,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Fraying-rope vocabulary",desc:"Describes endurance stretched near its structural limit.",example:"I'm holding. Just — just barely holding.",intensity:3,rarity:"signature",pol:{}},
{id:3161,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Radiant-joy words",desc:"Chooses vocabulary that suggests joy visibly spilling outward.",example:"I could light up the whole street right now.",intensity:2,rarity:"common",pol:{}},
{id:3162,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Salted-wound diction",desc:"Describes pain reopened or made sharper by an additional hurt.",example:"And then he said THAT. On top of everything.",intensity:4,rarity:"signature",pol:{}},
{id:3163,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Steady-flame vocabulary",desc:"Chooses words describing calm, sustained, unwavering devotion.",example:"Not a spark. A flame. Steady, all these years.",intensity:2,rarity:"signature",pol:{}},
{id:3164,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Ash-and-embers words",desc:"Describes what's left after emotional burnout, quiet and grey.",example:"There's nothing left to feel. Just — ash, mostly.",intensity:4,rarity:"signature",pol:{}},
{id:3165,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Sudden-thaw vocabulary",desc:"Describes unexpected emotional softening after a long guarded period.",example:"Didn't expect to feel this. Caught me off guard, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:3166,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Weighted-silence diction",desc:"Chooses vocabulary that treats silence as carrying visible emotional mass.",example:"Say something. The quiet's getting heavier.",intensity:3,rarity:"signature",pol:{}},
{id:3167,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Splintering-composure words",desc:"Describes control that is visibly, audibly starting to crack.",example:"I'm — I'm handling it. (voice catches) I'm handling it.",intensity:4,rarity:"signature",pol:{}},
{id:3168,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Warm-hearth vocabulary",desc:"Describes comfort and belonging through fireside warmth imagery.",example:"Feels like home in here. Always has.",intensity:1,rarity:"common",pol:{}},
{id:3169,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Bone-deep exhaustion words",desc:"Chooses vocabulary that locates tiredness far past the surface.",example:"Not tired. Past tired. It's in my bones now.",intensity:3,rarity:"signature",pol:{}},
{id:3190,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Zero-subtext speaker",desc:"Says exactly what they mean with no layered implication ever.",example:"I mean this literally: I need the money by Friday.",intensity:2,rarity:"common",pol:{}},
{id:3191,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Compliment-as-fact giver",desc:"Delivers praise as flat, unembellished statements of fact.",example:"You did it correctly. That is a fact.",intensity:2,rarity:"signature",pol:{}},
{id:3192,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Grief-plain speaker",desc:"States loss in the barest possible factual terms.",example:"He's dead. I'm not going to dress that up.",intensity:4,rarity:"signature",pol:{}},
{id:3193,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Instruction-exact follower",desc:"Executes and expects instructions taken at pure face value.",example:"You said 'wait here'. I waited here.",intensity:2,rarity:"common",pol:{}},
{id:3194,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"No-hyperbole policy",desc:"Refuses exaggeration even for emphasis, sticking to literal accuracy.",example:"Not 'a million times'. Four times. I counted.",intensity:2,rarity:"signature",pol:{}},
{id:3195,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Bluntly-corrective speaker",desc:"States corrections without any softening frame.",example:"That's wrong. Here's why.",intensity:3,rarity:"common",pol:{}},
{id:3196,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Plain-motive discloser",desc:"States their own reasons for acting with zero embellishment.",example:"I'm doing this because it benefits me. Simple as that.",intensity:2,rarity:"signature",pol:{}},
{id:3198,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Anti-metaphor purist",desc:"Actively translates any figurative language into literal terms.",example:"'Heart of stone' — you mean he's unkind. Just say unkind.",intensity:2,rarity:"signature",pol:{}},
{id:3199,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Concrete-noun preferrer",desc:"Always chooses the specific physical object over an abstract term.",example:"Not 'the situation'. The bridge. The bridge is the problem.",intensity:2,rarity:"common",pol:{}},
{id:3200,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Blunt-question asker",desc:"Asks the most direct possible version of any question.",example:"Are you leaving me? Just tell me plainly.",intensity:4,rarity:"signature",pol:{}},
{id:3201,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"No-euphemism enforcer",desc:"Insists on the harsh literal word over any softened alternative.",example:"He didn't 'pass on'. He died. Say died.",intensity:3,rarity:"signature",pol:{}},
{id:3202,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Simple-declarative speaker",desc:"Structures nearly every sentence as a short, plain declaration.",example:"It rained. We're wet. We should go inside.",intensity:1,rarity:"common",pol:{}},
{id:3203,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Fact-checking literalist",desc:"Verifies claims against literal accuracy before accepting them.",example:"You said 'always'. Has it actually happened every time?",intensity:2,rarity:"signature",pol:{}},
{id:3204,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Plain-warning giver",desc:"Delivers cautions in the starkest, most literal terms available.",example:"Go there and you will likely die. That's not a figure of speech.",intensity:4,rarity:"signature",pol:{}},
{id:3205,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Undecorated praise giver",desc:"Compliments without any embellishing adjectives or imagery.",example:"Good work. That's it. Good work.",intensity:1,rarity:"common",pol:{}},
{id:3206,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Direct-refusal speaker",desc:"Declines requests with unambiguous, literal negatives.",example:"No. I will not be doing that.",intensity:3,rarity:"common",pol:{}},
{id:3207,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Literal-timeframe insister",desc:"Demands and gives exact literal times rather than approximations.",example:"'Soon' isn't a time. Give me an hour, or don't.",intensity:2,rarity:"signature",pol:{}},
{id:3208,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"No-implication asker",desc:"States requests fully rather than expecting inference.",example:"I'm not hinting. I'm asking you directly to help.",intensity:2,rarity:"signature",pol:{}},
{id:3209,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Plain-consequence stater",desc:"States outcomes of actions without dramatic framing.",example:"If you do that, you'll be fired. That's simply what happens.",intensity:3,rarity:"signature",pol:{}},
{id:3210,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Occupational-suffix inventor",desc:"Invents job titles by attaching '-er' to unlikely verbs.",example:"He's the official worrier of this household.",intensity:2,rarity:"signature",pol:{}},
{id:3211,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"De-formalizer",desc:"Strips formal endings off words to make them sound casual.",example:"That's real official-like. Very legal-y of you.",intensity:2,rarity:"signature",pol:{}},
{id:3212,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Adjective-verbing speaker",desc:"Turns descriptive adjectives into improvised verbs.",example:"Let's not overcomplicate — I mean, don't complicate it.",intensity:2,rarity:"signature",pol:{}},
{id:3213,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Double-negative user",desc:"Habitually stacks negatives for emphasis rather than clarity.",example:"I don't want no trouble from nobody.",intensity:2,rarity:"common",pol:{}},
{id:3214,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Prefix-doubler",desc:"Occasionally stacks two prefixes onto a single word for effect.",example:"That's un-un-fair, that is.",intensity:2,rarity:"signature",pol:{}},
{id:3215,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Regional-suffix borrower",desc:"Uses suffixes borrowed from a distinct regional dialect.",example:"That's a right proper mess, that is-n't it.",intensity:2,rarity:"signature",pol:{}},
{id:3216,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Onomatopoeic-verb coiner",desc:"Turns sound-effect words directly into action verbs.",example:"He just — thunked the whole crate down.",intensity:2,rarity:"signature",pol:{}},
{id:3217,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Formal-noun-stacker",desc:"Piles multiple nouns together into dense bureaucratic phrases.",example:"The report-submission-deadline-extension request was denied.",intensity:2,rarity:"signature",pol:{}},
{id:3218,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Root-word purist",desc:"Insists on using a word's original historical root meaning.",example:"'Decimate' means one in ten, properly. I'll use it correctly.",intensity:3,rarity:"signature",pol:{}},
{id:3219,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Casual-clipper",desc:"Shortens nearly every long word into an informal nickname version.",example:"Grab the fridge — no wait, the 'fridge, whatever.",intensity:2,rarity:"common",pol:{}},
{id:3220,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Elaborate-compound builder",desc:"Constructs long, precise compound descriptors for simple things.",example:"The still-slightly-too-hot-to-drink tea.",intensity:2,rarity:"signature",pol:{}},
{id:3221,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Instant-adjective coiner",desc:"Turns proper nouns into improvised descriptive adjectives.",example:"That's very 'him', isn't it — very him-like.",intensity:2,rarity:"signature",pol:{}},
{id:3222,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Suffix-swap experimenter",desc:"Swaps standard suffixes for unusual ones on the fly.",example:"That's not sad. That's more sad-ish-ness.",intensity:2,rarity:"signature",pol:{}},
{id:3223,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Loan-blend coiner",desc:"Fuses a foreign root with a native ending for effect.",example:"We'll call it a 'kaputness'. Broken, but worse.",intensity:2,rarity:"signature",pol:{}},
{id:3224,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Silent-letter emphasizer",desc:"Deliberately pronounces normally-silent letters for comic or formal effect.",example:"Wednes-day. Every syllable, thank you.",intensity:1,rarity:"signature",pol:{}},
{id:3225,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Formal-title inventor",desc:"Assigns elaborate invented titles to ordinary roles.",example:"Chief Deputy Assistant to the Regional Bread-Keeper. That's me.",intensity:2,rarity:"signature",pol:{}},
{id:3226,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Word-truncation habit",desc:"Regularly cuts words down to their first syllable only.",example:"Sit'ation's bad. Real bad.",intensity:2,rarity:"signature",pol:{}},
{id:3227,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Reduplicated-emphasis user",desc:"Doubles a word with slight variation to intensify meaning.",example:"It's not just tired. It's tired-tired.",intensity:2,rarity:"common",pol:{}},
{id:3228,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Legal-suffix borrower",desc:"Attaches formal legal-sounding suffixes to casual statements.",example:"This is a binding-ish sort of agreement, then.",intensity:2,rarity:"signature",pol:{}},
{id:3229,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Neologism-defender",desc:"Insists their invented words are perfectly valid and useful.",example:"'Grumptastic' is a real word. I use it, so it's real.",intensity:2,rarity:"signature",pol:{}},
{id:3230,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Percussive-onset speaker",desc:"Attacks the first consonant of words sharply for emphasis.",example:"T-take that. P-put it down.",intensity:2,rarity:"signature",pol:{}},
{id:3231,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Long-vowel drawer",desc:"Extends vowel sounds noticeably longer than typical speech.",example:"Waaaaay too much trouble, that.",intensity:2,rarity:"common",pol:{}},
{id:3232,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Sing-song vowel shifter",desc:"Slides pitch across vowels, giving speech a musical quality.",example:"Well noooow, isn't that interesting.",intensity:2,rarity:"signature",pol:{}},
{id:3233,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Hard-stop finisher",desc:"Ends words with abrupt, clipped final consonants.",example:"Stop. Not. Now.",intensity:2,rarity:"common",pol:{}},
{id:3234,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Airy-fricative speaker",desc:"Favors soft 'f', 'th', and 'wh' sounds throughout speech.",example:"Whisper this — soft, feather-thin, barely there.",intensity:2,rarity:"signature",pol:{}},
{id:3235,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Nasal-resonance speaker",desc:"Directs vocal resonance heavily through the nose, distinctive tone.",example:"Mmm, no, that won't do at all.",intensity:2,rarity:"signature",pol:{}},
{id:3236,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Choppy-syllable speaker",desc:"Breaks multi-syllable words into distinct separated chunks.",example:"Un-be-liev-a-ble.",intensity:2,rarity:"signature",pol:{}},
{id:3237,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Guttural-onset user",desc:"Favors words beginning with harsh back-of-throat sounds.",example:"Grim. Grave. Gone.",intensity:3,rarity:"signature",pol:{}},
{id:3238,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Trilling-r enthusiast",desc:"Rolls 'r' sounds prominently, even in casual speech.",example:"Terrrific. Absolutely terrrific.",intensity:2,rarity:"signature",pol:{}},
{id:3239,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Clipped-t speaker",desc:"Produces unusually sharp, percussive 't' sounds throughout.",example:"Stop that. Right. Now.",intensity:2,rarity:"signature",pol:{}},
{id:3240,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Breath-heavy speaker",desc:"Speech carries an audible layer of extra breath throughout.",example:"(every word riding a soft extra exhale)",intensity:2,rarity:"signature",pol:{}},
{id:3241,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Vowel-flattener",desc:"Flattens rounded vowels into a distinctive nasal drawl.",example:"Caaan't believe that happened.",intensity:2,rarity:"signature",pol:{}},
{id:3243,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Deep-chest resonance speaker",desc:"Voice carries unusual low, chest-level resonance.",example:"(the words seem to come from somewhere deep and low)",intensity:2,rarity:"signature",pol:{}},
{id:3244,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Staccato-syllable emphasizer",desc:"Punches each syllable with near-equal, separated stress.",example:"Ab-so-lute-ly not.",intensity:2,rarity:"signature",pol:{}},
{id:3245,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Soft-onset speaker",desc:"Begins words gently, almost inaudibly, before reaching full volume.",example:"...well, I suppose we could try.",intensity:1,rarity:"signature",pol:{}},
{id:3246,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Glottal-catch speaker",desc:"Uses a small vocal catch between vowel sounds for emphasis.",example:"Uh-oh. That's... not good.",intensity:2,rarity:"signature",pol:{}},
{id:3247,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Melodic-question lifter",desc:"Ends even statements with a musical, rising inflection.",example:"We're leaving now~",intensity:1,rarity:"signature",pol:{}},
{id:3248,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Buzzy-consonant favorer",desc:"Chooses words rich in 'z' and 'v' buzzing sounds.",example:"Vexing. Absolutely vexing, this whole business.",intensity:2,rarity:"signature",pol:{}},
{id:3249,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Flat-monotone reader",desc:"Delivers even exciting news in a completely level tone.",example:"We won. Everything's fine now. Moving on.",intensity:2,rarity:"common",pol:{}},
{id:3250,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Sympathy-requesting words",desc:"Chooses vocabulary designed to draw compassion from the listener.",example:"It's been so hard, you have no idea how hard.",intensity:2,rarity:"signature",pol:{}},
{id:3251,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Task-delegating lexicon",desc:"Chooses vocabulary that assigns responsibility to others clearly.",example:"That one's yours. This one's mine.",intensity:2,rarity:"common",pol:{}},
{id:3252,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Encouragement-specific words",desc:"Selects vocabulary crafted specifically to build others' confidence.",example:"You've got this. You've absolutely got this.",intensity:2,rarity:"common",pol:{}},
{id:3253,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Suspicion-voicing lexicon",desc:"Chooses vocabulary that signals distrust without direct accusation.",example:"Interesting that he showed up right then, isn't it.",intensity:3,rarity:"signature",pol:{}},
{id:3254,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Loyalty-declaring words",desc:"Selects vocabulary that publicly commits allegiance.",example:"I'm with him. Fully. However this goes.",intensity:2,rarity:"signature",pol:{}},
{id:3255,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Regret-minimizing lexicon",desc:"Chooses words that downplay the size of an admitted mistake.",example:"Small thing, really. Barely worth mentioning.",intensity:2,rarity:"signature",pol:{}},
{id:3256,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Permission-granting words",desc:"Selects vocabulary that formally authorizes another's action.",example:"You have my blessing. Go ahead.",intensity:2,rarity:"common",pol:{}},
{id:3257,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Distance-creating lexicon",desc:"Chooses vocabulary that puts emotional space between speaker and topic.",example:"One might say that was regrettable.",intensity:2,rarity:"signature",pol:{}},
{id:3258,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Invitation-repeating words",desc:"Habitually restates welcomes to make sure they're believed.",example:"You're welcome here. I mean that. Truly welcome.",intensity:2,rarity:"common",pol:{}},
{id:3259,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Accusation-softening lexicon",desc:"Chooses vocabulary that raises fault gently rather than bluntly.",example:"I wonder if perhaps that wasn't the best choice.",intensity:2,rarity:"signature",pol:{}},
{id:3260,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Confidence-projecting words",desc:"Selects vocabulary that asserts certainty regardless of actual doubt.",example:"No question. This will work. No question at all.",intensity:3,rarity:"signature",pol:{}},
{id:3261,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Apology-avoiding lexicon",desc:"Chooses vocabulary that acknowledges harm without directly apologizing.",example:"That's unfortunate, what happened there.",intensity:3,rarity:"signature",pol:{}},
{id:3262,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Farewell-repeating words",desc:"States goodbyes multiple times before actually leaving.",example:"Alright — goodbye — really, goodbye now — okay, going.",intensity:1,rarity:"common",pol:{}},
{id:3263,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Motivation-invoking lexicon",desc:"Chooses vocabulary designed to spur others into action.",example:"Now's the moment. Let's move.",intensity:2,rarity:"common",pol:{}},
{id:3264,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Complaint-softening words",desc:"Frames grievances in gentle, indirect vocabulary.",example:"Just a small thought — might the soup be a touch cold?",intensity:1,rarity:"signature",pol:{}},
{id:3265,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Certainty-hedging lexicon",desc:"Chooses vocabulary that quietly protects against being wrong later.",example:"As far as I currently understand, that's accurate.",intensity:2,rarity:"signature",pol:{}},
{id:3266,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Group-unity words",desc:"Selects vocabulary specifically designed to bind listeners together.",example:"We're in this together. All of us.",intensity:2,rarity:"common",pol:{}},
{id:3267,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Warning-repeating lexicon",desc:"States cautions multiple times using varied vocabulary.",example:"Be careful. Seriously — mind yourself out there.",intensity:2,rarity:"signature",pol:{}},
{id:3268,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Praise-earning words",desc:"Chooses vocabulary that subtly angles for acknowledgment.",example:"I did stay late to finish it, for what it's worth.",intensity:2,rarity:"signature",pol:{}},
{id:3269,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Neutral-ground lexicon",desc:"Selects vocabulary specifically designed to avoid taking sides.",example:"Both perspectives have something to them, I think.",intensity:2,rarity:"signature",pol:{}},
{id:3270,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Time-stamped speaker",desc:"Attaches an exact time to nearly every event described.",example:"Left at 6:47. Arrived 7:12. On record.",intensity:3,rarity:"signature",pol:{}},
{id:3271,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Named-source citer",desc:"Always attributes claims to a specific, named origin.",example:"Not 'people say'. The harbormaster said, specifically.",intensity:2,rarity:"signature",pol:{}},
{id:3272,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Rough-order-of-magnitude speaker",desc:"Gives approximate scale rather than exact counts.",example:"Hundreds, roughly. Could be low three figures.",intensity:2,rarity:"common",pol:{}},
{id:3273,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Precise-cause namer",desc:"Insists on the exact mechanism behind any outcome, not just the result.",example:"Not 'it broke'. The hinge pin sheared.",intensity:3,rarity:"signature",pol:{}},
{id:3274,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"General-impression speaker",desc:"Describes things by overall feel rather than itemized detail.",example:"It felt off. Couldn't say exactly why.",intensity:2,rarity:"common",pol:{}},
{id:3275,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Exact-quantity insister",desc:"Refuses vague amounts, always demanding or giving precise figures.",example:"Not 'some'. How many, exactly?",intensity:2,rarity:"signature",pol:{}},
{id:3276,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Sweeping-category user",desc:"Groups distinct things under one broad convenient label.",example:"All of that — just call it 'the mess'.",intensity:2,rarity:"common",pol:{}},
{id:3277,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Granular-timeline speaker",desc:"Breaks events into extremely fine-grained sequential steps.",example:"First this, then a half-second later, that, then—",intensity:3,rarity:"signature",pol:{}},
{id:3278,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Loose-boundary describer",desc:"Uses fuzzy, overlapping categories rather than sharp distinctions.",example:"Sort of in-between. Not quite one or the other.",intensity:2,rarity:"common",pol:{}},
{id:3279,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Verified-fact insister",desc:"Will only state something as true if personally confirmed.",example:"I saw it myself. Not hearsay — I saw it.",intensity:2,rarity:"signature",pol:{}},
{id:3280,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Broad-brush summarizer",desc:"Compresses complex situations into single sweeping statements.",example:"Long story short, it's a disaster.",intensity:2,rarity:"common",pol:{}},
{id:3281,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Micro-detail collector",desc:"Notices and reports extremely small, specific details others miss.",example:"The left boot lace was different from the right. Interesting.",intensity:3,rarity:"signature",pol:{}},
{id:3282,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Hedge-free precise speaker",desc:"States even uncertain things with confident exactness.",example:"Six days. Not five, not seven. Six.",intensity:2,rarity:"signature",pol:{}},
{id:3283,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Generalization-comfortable speaker",desc:"Comfortably speaks in broad strokes without needing exact figures.",example:"Most people feel that way, I'd guess.",intensity:1,rarity:"common",pol:{}},
{id:3284,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Cross-reference checker",desc:"Verifies details against multiple sources before stating them as fact.",example:"Two accounts agree on that detail. I'll trust it.",intensity:2,rarity:"signature",pol:{}},
{id:3285,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Vague-quantity comfortable",desc:"Genuinely doesn't need precise numbers to feel satisfied.",example:"Enough. However much that turns out to be.",intensity:1,rarity:"common",pol:{}},
{id:3286,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Precision-demanding listener",desc:"Interrupts vague speakers to insist on exact figures.",example:"'A while' isn't an answer. How long, exactly?",intensity:2,rarity:"signature",pol:{}},
{id:3287,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Approximation-flagging speaker",desc:"Explicitly labels estimates as estimates, never presenting them as fact.",example:"Estimate only — could be off by a fair margin.",intensity:2,rarity:"signature",pol:{}},
{id:3288,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Blanket-statement maker",desc:"Applies single sweeping claims to entire complex situations.",example:"Nobody in this town can be trusted. Simple as that.",intensity:2,rarity:"common",pol:{}},
{id:3289,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Fine-distinction insister",desc:"Draws sharp boundaries between concepts others treat as similar.",example:"Not the same thing at all. Different category entirely.",intensity:2,rarity:"signature",pol:{}},
{id:3290,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Precisely procedural",desc:"Speaks with exacting, methodical formality, as though every claim needs to hold up under scrutiny.",example:"The witness states, for the record, that the door was locked.",intensity:3,rarity:"signature",pol:{}},
{id:3291,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Loud-and-blunt",desc:"Uses loud, blunt, high-volume vocabulary regardless of setting.",example:"Oi! Best price, come on then!",intensity:2,rarity:"signature",pol:{}},
{id:3292,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Explanatory-formal",desc:"Speaks with the structured, patient tone of someone walking through an argument.",example:"Consider, if you will, the underlying causes at play here.",intensity:3,rarity:"signature",pol:{}},
{id:3293,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Easy-familiar",desc:"Uses the easy, familiar tone of someone who's known you a long time.",example:"Same as always, love. You know how it is.",intensity:2,rarity:"common",pol:{}},
{id:3294,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Carefully-layered formal",desc:"Frames blunt realities in careful, indirect, formally cushioned language.",example:"It is with some concern that we note recent developments.",intensity:3,rarity:"signature",pol:{}},
{id:3295,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Clipped-and-direct",desc:"Uses short, unadorned, no-nonsense vocabulary with zero embellishment.",example:"Move it. No excuses. Go.",intensity:3,rarity:"signature",pol:{}},
{id:3296,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Elaborately polite",desc:"Uses ornate, highly polite vocabulary regardless of who's listening.",example:"How simply delightful to see you again, my dear.",intensity:3,rarity:"signature",pol:{}},
{id:3297,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Coarse-and-practical",desc:"Uses rough, practical, unpretentious vocabulary suited to hard physical work.",example:"Get it loaded, quit yer gawking.",intensity:2,rarity:"signature",pol:{}},
{id:3298,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Ritual-formal",desc:"Reserves elevated, ceremonial language specifically for occasions that feel significant.",example:"By this rite, let the bond be sealed.",intensity:3,rarity:"signature",pol:{}},
{id:3299,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Relaxed-homely",desc:"Uses relaxed, practical, homely vocabulary regardless of context.",example:"Just chuck it in, no need to fuss.",intensity:2,rarity:"common",pol:{}},
{id:3300,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Procedural-governance formal",desc:"Speaks with the structured, motion-and-minutes cadence of formal proceedings.",example:"The chair recognizes the objection.",intensity:3,rarity:"signature",pol:{}},
{id:3301,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Plain-and-unpretentious",desc:"Uses blunt, unpretentious vocabulary rooted in hands-on, physical experience.",example:"Needs doing. Get to it.",intensity:2,rarity:"common",pol:{}},
{id:3302,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Cultivated-refined",desc:"Uses the carefully cultivated, slightly precious vocabulary of refined taste.",example:"One does find the composition rather derivative, doesn't one?",intensity:3,rarity:"signature",pol:{}},
{id:3303,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Quick-negotiating casual",desc:"Uses the quick, informal, pressing vocabulary of an active back-and-forth.",example:"Come on, final offer, take it or leave it.",intensity:2,rarity:"common",pol:{}},
{id:3304,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Hushed-deliberate",desc:"Uses quiet, deliberate, unhurried vocabulary regardless of topic.",example:"We'll take our time with this. There's no hurry in it.",intensity:2,rarity:"signature",pol:{}},
{id:3305,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Loud-and-warm",desc:"Uses loud, warm, generous, informal vocabulary.",example:"Drinks all round, my treat, don't argue!",intensity:2,rarity:"common",pol:{}},
{id:3306,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Densely-bureaucratic",desc:"Uses dense, precise, procedural vocabulary even in casual settings.",example:"Per the aforementioned arrangement, dinner is at seven.",intensity:3,rarity:"signature",pol:{}},
{id:3307,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Patiently-instructional",desc:"Uses the patient, explanatory vocabulary of someone walking another person through something step by step.",example:"Now, let's think about why that happened, step by step.",intensity:2,rarity:"signature",pol:{}},
{id:3308,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Easy-neighborly",desc:"Uses the easy, unpretentious vocabulary of casual, unhurried conversation.",example:"Lovely evening for it, isn't it? How's the family?",intensity:2,rarity:"common",pol:{}},
{id:3309,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Structured-professional",desc:"Uses structured, trade-specific formality even outside any formal context.",example:"As per standard, the work meets requirement.",intensity:2,rarity:"signature",pol:{}},
{id:3310,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Number-modifier heavy",desc:"Attaches a specific quantity to nearly every noun mentioned.",example:"Three chairs, two tables, one broken lamp.",intensity:2,rarity:"common",pol:{}},
{id:3311,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Origin-modifier user",desc:"Habitually specifies where things came from before naming them.",example:"The Marlowe bread. The eastern road. The old well.",intensity:2,rarity:"signature",pol:{}},
{id:3312,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Condition-modifier stacker",desc:"Piles descriptors specifically about physical condition or wear.",example:"A cracked, worn, barely-holding chair.",intensity:2,rarity:"signature",pol:{}},
{id:3313,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Emotion-projecting modifier user",desc:"Attaches emotional qualities to inanimate objects routinely.",example:"The sad little house. The tired old road.",intensity:2,rarity:"signature",pol:{}},
{id:3314,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Age-modifier habitual",desc:"Notes the age of nearly everything described, relevant or not.",example:"The young dog. The old fence. The new coat.",intensity:2,rarity:"common",pol:{}},
{id:3315,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Absence-modifier user",desc:"Describes things primarily by what quality they're missing.",example:"A joyless room. A colorless sky.",intensity:2,rarity:"signature",pol:{}},
{id:3316,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Value-modifier stacker",desc:"Attaches worth-related descriptors to nearly every object.",example:"The expensive coat. The cheap trick. The priceless moment.",intensity:2,rarity:"signature",pol:{}},
{id:3317,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Sound-modifier dense",desc:"Fills modifier slots with auditory qualities specifically.",example:"A creaking door. A humming engine. A silent room.",intensity:2,rarity:"signature",pol:{}},
{id:3318,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Comparative-chain builder",desc:"Builds long chains of comparative modifiers in sequence.",example:"Bigger than before, but smaller than we'd hoped, and slower still.",intensity:2,rarity:"signature",pol:{}},
{id:3319,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Intent-modifier user",desc:"Attaches implied purpose or intention to described objects.",example:"The waiting chair. The forgotten letter.",intensity:2,rarity:"signature",pol:{}},
{id:3320,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Minimal-modifier discipline",desc:"Uses at most one modifier per noun, strictly.",example:"A cold room. A tired man.",intensity:1,rarity:"common",pol:{}},
{id:3321,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Density-stacking describer",desc:"Piles four or more modifiers onto significant nouns for effect.",example:"A cold, cracked, forgotten, colorless old room.",intensity:3,rarity:"signature",pol:{}},
{id:3322,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Texture-modifier focused",desc:"Consistently describes physical texture over other qualities.",example:"A rough coat. A smooth stone. A gritty road.",intensity:2,rarity:"signature",pol:{}},
{id:3323,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Speed-and-motion modifier user",desc:"Attaches pace-related descriptors to nearly every noun and verb.",example:"A quick decision. A slow answer. A sudden stop.",intensity:2,rarity:"signature",pol:{}},
{id:3324,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Moral-modifier stacker",desc:"Attaches ethical judgment words to nearly every description.",example:"The dishonest deal. The noble effort.",intensity:2,rarity:"signature",pol:{}},
{id:3325,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Bare-noun purist",desc:"Almost entirely avoids modifiers, presenting nouns unadorned.",example:"Door. Chair. Table. Room.",intensity:2,rarity:"common",pol:{}},
{id:3326,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Distance-modifier user",desc:"Habitually specifies spatial distance in descriptions.",example:"The far gate. The near wall. The distant hills.",intensity:2,rarity:"signature",pol:{}},
{id:3327,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Redundant-modifier stacker",desc:"Uses modifiers that restate the noun's inherent meaning.",example:"A round circle. A wet rain.",intensity:2,rarity:"signature",pol:{}},
{id:3328,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Contrast-modifier pairer",desc:"Habitually pairs opposing modifiers for dramatic tension.",example:"A gentle violence. A warm coldness.",intensity:2,rarity:"signature",pol:{}},
{id:3329,section:"Vocabulary Traits",category:"Semantic Density & Modifiers",trait:"Precision-modifier insister",desc:"Uses exact, measured modifiers rather than vague ones.",example:"Not 'big'. Six feet, roughly. Precisely that.",intensity:2,rarity:"signature",pol:{}},
{id:3330,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Reluctant-admission opener",desc:"Begins hard truths with 'I hate to admit this, but'.",example:"I hate to admit this, but you were right.",intensity:2,rarity:"common",pol:{}},
{id:3331,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Group-check tag",desc:"Ends proposals with 'does that work for everyone?'",example:"We'll meet at six — does that work for everyone?",intensity:1,rarity:"common",pol:{}},
{id:3332,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Self-doubt opener",desc:"Starts opinions with 'maybe I'm wrong, but'.",example:"Maybe I'm wrong, but I don't think that's the plan.",intensity:2,rarity:"signature",pol:{}},
{id:3333,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Emphasis-triple repeater",desc:"Repeats a key word three times for maximum stress.",example:"No. No. No. That's final.",intensity:2,rarity:"signature",pol:{}},
{id:3334,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Old-saying invoker",desc:"Prefaces advice with 'my grandmother always said'.",example:"My grandmother always said, waste not, want not.",intensity:2,rarity:"signature",pol:{}},
{id:3335,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"List-number caller",desc:"Explicitly numbers points aloud while speaking.",example:"Point one. Point two. And point three, most importantly—",intensity:2,rarity:"common",pol:{}},
{id:3336,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Sudden-thought marker",desc:"Inserts 'oh, and also' to add a late addition.",example:"Oh, and also — don't forget the keys.",intensity:1,rarity:"common",pol:{}},
{id:3337,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Rhetorical-agreement checker",desc:"Adds 'wouldn't you say?' to soften strong opinions.",example:"It's clearly the better plan, wouldn't you say?",intensity:2,rarity:"signature",pol:{}},
{id:3338,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Concern-flagging opener",desc:"Begins objections with 'I'm a little worried that'.",example:"I'm a little worried that this won't hold.",intensity:2,rarity:"common",pol:{}},
{id:3339,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Blunt-warning tag",desc:"Adds 'just so you know' before delivering hard truths.",example:"Just so you know, that won't end well.",intensity:2,rarity:"common",pol:{}},
{id:3340,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Repetition-for-clarity user",desc:"Restates their own point using slightly different words each time.",example:"It's over. Finished. Done with. Complete.",intensity:2,rarity:"signature",pol:{}},
{id:3341,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Self-permission granter",desc:"Opens with 'I'm just going to say it' before blunt statements.",example:"I'm just going to say it — this plan is bad.",intensity:2,rarity:"signature",pol:{}},
{id:3342,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Time-pressure marker",desc:"Inserts 'we don't have long' before urgent points.",example:"We don't have long — listen carefully.",intensity:3,rarity:"signature",pol:{}},
{id:3343,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Softened-command giver",desc:"Wraps orders in 'if you wouldn't mind'.",example:"If you wouldn't mind, close the door.",intensity:1,rarity:"common",pol:{}},
{id:3344,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Story-closing tag",desc:"Ends anecdotes with 'and that's the whole story'.",example:"We got out just in time — and that's the whole story.",intensity:1,rarity:"signature",pol:{}},
{id:3345,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Disbelief marker",desc:"Inserts 'I still can't believe it' mid-narration.",example:"And then — I still can't believe it — he just left.",intensity:2,rarity:"signature",pol:{}},
{id:3346,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Reassurance-repeat opener",desc:"Begins comforting statements with 'listen, it's going to be fine'.",example:"Listen, it's going to be fine. I mean that.",intensity:2,rarity:"common",pol:{}},
{id:3347,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Blame-avoidance tag",desc:"Adds 'not that I'm blaming anyone' after a pointed remark.",example:"The shipment's late — not that I'm blaming anyone.",intensity:2,rarity:"signature",pol:{}},
{id:3348,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Grudging-agreement opener",desc:"Starts concessions with 'alright, fine, you win'.",example:"Alright, fine, you win — we'll do it your way.",intensity:2,rarity:"common",pol:{}},
{id:3349,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Final-decision marker",desc:"Closes debates with 'that's my final word on it'.",example:"We're not discussing this further. Final word.",intensity:3,rarity:"signature",pol:{}},
{id:3350,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Interrupted-by-memory pause",desc:"Stops mid-sentence as an unrelated memory surfaces.",example:"We should— wait, that reminds me of— sorry, go on.",intensity:2,rarity:"signature",pol:{}},
{id:3351,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Trailing-count stumble",desc:"Loses count mid-sentence while enumerating points.",example:"First, second — wait, was that second or third—",intensity:2,rarity:"signature",pol:{}},
{id:3352,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sudden-topic-collision speaker",desc:"Two unrelated thoughts arrive at once, garbling the sentence.",example:"I wanted to say the door— the horse— sorry, which first—",intensity:3,rarity:"signature",pol:{}},
{id:3353,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Hesitant-name-recaller",desc:"Stumbles specifically when trying to recall someone's name.",example:"It was— his name was— it's right there, just—",intensity:2,rarity:"common",pol:{}},
{id:3354,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sob-interrupted speech",desc:"Speech breaks apart specifically under suppressed crying.",example:"I just— (breath) —I really thought— (breath) —we had more time.",intensity:4,rarity:"signature",pol:{}},
{id:3355,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"False-start-then-silence",desc:"Begins a sentence, stops, and simply doesn't continue.",example:"I wanted to tell you— (nothing more comes)",intensity:3,rarity:"signature",pol:{}},
{id:3356,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Overlap-recovery stumbler",desc:"Struggles to regain their sentence after being talked over.",example:"I was— sorry, what were— no, you go first.",intensity:2,rarity:"signature",pol:{}},
{id:3357,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sudden-reconsideration halt",desc:"Stops mid-thought upon realizing they've changed their mind.",example:"We should definitely— actually, no, wait—",intensity:2,rarity:"signature",pol:{}},
{id:3358,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Anxious-repeat-word stumbler",desc:"Repeats the same small word rapidly when nervous.",example:"I I I don't think that's— I don't think that's right.",intensity:3,rarity:"signature",pol:{}},
{id:3359,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Mid-laugh interruption",desc:"Own laughter breaks apart the sentence being delivered.",example:"And then he— (laughs) —sorry— he actually tripped—",intensity:2,rarity:"common",pol:{}},
{id:3360,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Word-search visible pause",desc:"Visibly searches for the right word, pausing on the wrong one.",example:"It was very... not sad, exactly, more... hollow, I suppose.",intensity:2,rarity:"signature",pol:{}},
{id:3361,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Sentence-abandoning restarter",desc:"Drops an entire sentence structure and begins again differently.",example:"The thing about the bridge— actually, let me start over.",intensity:2,rarity:"signature",pol:{}},
{id:3362,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Choked-word speaker",desc:"A specific difficult word gets physically stuck before it's said.",example:"He's— he's— (can't quite say 'dead')",intensity:4,rarity:"signature",pol:{}},
{id:3363,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Double-clutch restarter",desc:"Restarts the same clause twice in quick succession.",example:"We need— we need to leave. We need to leave now.",intensity:2,rarity:"signature",pol:{}},
{id:3364,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Distracted-mid-sentence pause",desc:"Loses their thread because something else catches their attention.",example:"So we were saying— wait, is that smoke over there?",intensity:2,rarity:"signature",pol:{}},
{id:3365,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Anxiety-clipped ending",desc:"Cuts sentences short right before the anxious part.",example:"I wanted to ask if you'd— never mind, forget it.",intensity:3,rarity:"signature",pol:{}},
{id:3366,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Recovering-composure pause",desc:"Pauses deliberately to regain control before continuing.",example:"(stops, breathes, steadies) Alright. As I was saying.",intensity:2,rarity:"signature",pol:{}},
{id:3367,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Stumble-then-clarity speaker",desc:"Trips over the opening, then suddenly speaks with total clarity.",example:"I- I- (stops) —No. Here's exactly what happened.",intensity:2,rarity:"signature",pol:{}},
{id:3368,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Unfinished-list trailer",desc:"Starts listing items, trails off before finishing the list.",example:"We need rope, water, and... (trails off, distracted)",intensity:2,rarity:"signature",pol:{}},
{id:3369,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Panic-scrambled syntax",desc:"Under acute stress, word order scrambles noticeably.",example:"Go we now must — I mean — we have to go now.",intensity:3,rarity:"signature",pol:{}},
{id:3370,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Fragment-only responder",desc:"Answers entirely in sentence fragments, never full sentences.",example:"Behind schedule. My fault. Fixing it.",intensity:2,rarity:"common",pol:{}},
{id:3371,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Time-unit dropper",desc:"Omits the unit when stating durations, assuming context.",example:"Back in five.",intensity:2,rarity:"common",pol:{}},
{id:3372,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Speaker-tag dropper",desc:"Drops attribution entirely when relaying who said what.",example:"'Not happening.' Then left.",intensity:2,rarity:"signature",pol:{}},
{id:3373,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Condition-clipper",desc:"Drops the conditional clause, stating only the result.",example:"Rains, we're stuck.",intensity:2,rarity:"signature",pol:{}},
{id:3374,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Bare-imperative chainer",desc:"Strings multiple commands together with no connecting words.",example:"Move. Grab it. Go.",intensity:2,rarity:"common",pol:{}},
{id:3375,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Article-and-verb dropper",desc:"Omits both articles and helping verbs for maximum compression.",example:"Dog barking. Door open. Something wrong.",intensity:3,rarity:"signature",pol:{}},
{id:3376,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Comparison-clipper",desc:"States comparisons without the second half spelled out.",example:"Better. Much better.",intensity:1,rarity:"common",pol:{}},
{id:3377,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Cause-clipper",desc:"States effects without stating the cause, assuming it's obvious.",example:"Roof's gone. Storm.",intensity:2,rarity:"signature",pol:{}},
{id:3378,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Emotion-word dropper",desc:"States situations without ever naming the associated feeling.",example:"He's gone. That's it.",intensity:2,rarity:"signature",pol:{}},
{id:3379,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Single-word status giver",desc:"Reduces any status check to exactly one word.",example:"Stable.",intensity:2,rarity:"common",pol:{}},
{id:3380,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Two-beat report giver",desc:"Compresses updates into exactly two short beats.",example:"Found it. Broken.",intensity:2,rarity:"signature",pol:{}},
{id:3381,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Subject-implied speaker",desc:"Drops the subject when it's clearly implied by context.",example:"Left already. Won't be back tonight.",intensity:2,rarity:"signature",pol:{}},
{id:3382,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"No-connector lister",desc:"Lists sequential events with zero connecting words.",example:"Arrived. Searched. Left empty-handed.",intensity:2,rarity:"common",pol:{}},
{id:3383,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Compressed-warning giver",desc:"Reduces warnings to the shortest possible alarm phrase.",example:"Down! Now!",intensity:3,rarity:"common",pol:{}},
{id:3384,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Result-only reporter",desc:"States only the outcome, never the process that led there.",example:"Lost. Badly.",intensity:2,rarity:"signature",pol:{}},
{id:3385,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Minimal-confirmation chain",desc:"Strings several single-word confirmations together rapidly.",example:"Yes. Yes. Confirmed. Go.",intensity:2,rarity:"signature",pol:{}},
{id:3386,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Silent-object implier",desc:"Refers to objects without naming them when context makes it obvious.",example:"Pass it. There. Thanks.",intensity:1,rarity:"common",pol:{}},
{id:3387,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Location-only responder",desc:"Answers 'where' questions with the location alone, nothing else.",example:"North gate.",intensity:1,rarity:"common",pol:{}},
{id:3388,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Compressed-refusal giver",desc:"Reduces a refusal to the shortest possible negative phrase.",example:"Not happening.",intensity:2,rarity:"common",pol:{}},
{id:3389,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Number-first reporter",desc:"Leads every report with the bare number before any context.",example:"Six. Dead. Confirmed this morning.",intensity:3,rarity:"signature",pol:{}},
{id:3390,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Mid-sentence topic-swap",desc:"Abandons the current subject entirely partway through a sentence.",example:"We should discuss the budget— actually, have you eaten?",intensity:2,rarity:"signature",pol:{}},
{id:3391,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Buried-lead speaker",desc:"Delivers the most important information last, after minor details.",example:"So the weather was fine, the road was clear, and also the bridge collapsed.",intensity:3,rarity:"signature",pol:{}},
{id:3392,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Circular-return speaker",desc:"Wanders through several points before landing back on the first.",example:"So — anyway — as I was saying about the horse—",intensity:2,rarity:"signature",pol:{}},
{id:3393,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Contradiction-embracing speaker",desc:"States two conflicting things in the same breath without resolving it.",example:"I trust him completely. I don't trust him at all.",intensity:3,rarity:"signature",pol:{}},
{id:3394,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Escalating-repetition speaker",desc:"Repeats a phrase with increasing intensity each time.",example:"Stop. STOP. I said STOP.",intensity:3,rarity:"signature",pol:{}},
{id:3395,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Self-interrupting question asker",desc:"Interrupts their own question with a second, related question.",example:"Did you see— actually, when did you last see him?",intensity:2,rarity:"signature",pol:{}},
{id:3396,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Frame-narrator",desc:"Wraps the main point inside an unrelated introductory story.",example:"So there was this dog once — anyway, the point is, trust matters.",intensity:2,rarity:"signature",pol:{}},
{id:3397,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Suspended-clause speaker",desc:"Leaves a grammatical clause hanging, unresolved, for effect.",example:"If he comes back — and that's a big if—",intensity:2,rarity:"signature",pol:{}},
{id:3398,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Reverse-emphasis speaker",desc:"States the exception before the rule, inverting normal structure.",example:"Except for Tuesdays, we're always open.",intensity:2,rarity:"signature",pol:{}},
{id:3399,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Double-negative structure user",desc:"Builds meaning through stacked negation rather than direct statement.",example:"It's not like I don't care.",intensity:2,rarity:"signature",pol:{}},
{id:3400,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Nested-parenthetical speaker",desc:"Embeds an aside inside another aside inside the main clause.",example:"He said (and this surprised me, given what she'd said (which wasn't much)) that it was fine.",intensity:3,rarity:"signature",pol:{}},
{id:3401,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Nominalized-emotion speaker",desc:"Turns feelings into abstract nouns rather than verbs.",example:"There was a betrayal. A disappointment. A silence.",intensity:2,rarity:"signature",pol:{}},
{id:3402,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Sentence-fragment escalator",desc:"Builds tension through a series of incomplete fragments.",example:"The door. Open. Nobody there. Just — gone.",intensity:3,rarity:"signature",pol:{}},
{id:3403,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Delayed-verb speaker",desc:"Withholds the main verb until late in a long sentence.",example:"He, having considered everything carefully, finally — refused.",intensity:2,rarity:"signature",pol:{}},
{id:3404,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Topic-sandwiching speaker",desc:"States a topic, digresses, then returns to close the same topic.",example:"About the shipment — long story short — the shipment's fine.",intensity:2,rarity:"signature",pol:{}},
{id:3405,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Chain-reaction narrator",desc:"Links events explicitly through cause using 'which led to' repeatedly.",example:"He was late, which led to the meeting stalling, which led to—",intensity:2,rarity:"signature",pol:{}},
{id:3406,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"False-equivalence structurer",desc:"Frames unequal things as parallel through matching sentence structure.",example:"He lost his job. I lost my keys. We're both having a week.",intensity:2,rarity:"signature",pol:{}},
{id:3407,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Emphatic-fronting repeater",desc:"Moves the emphasized word to the front, repeatedly, for effect.",example:"Never have I. Never will I. Never.",intensity:3,rarity:"signature",pol:{}},
{id:3408,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Mid-clause self-correction",desc:"Corrects a detail without stopping the flow of the sentence.",example:"He left — sorry, she left — around noon.",intensity:2,rarity:"common",pol:{}},
{id:3409,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Compound-sentence collapser",desc:"Starts building a complex sentence, then simplifies mid-way.",example:"Given the circumstances and the — no. It's bad. That's it.",intensity:2,rarity:"signature",pol:{}},
{id:3410,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Preemptive-answer giver",desc:"Answers the question before the asker finishes voicing it.",example:"—and I already know what you're going to ask. No.",intensity:2,rarity:"signature",pol:{}},
{id:3411,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-extending filler user",desc:"Uses stretched filler sounds to hold the floor while thinking.",example:"And soooo... the thing is...",intensity:2,rarity:"common",pol:{}},
{id:3412,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Group-poll taker",desc:"Explicitly asks the room for input before continuing their point.",example:"Before I go on — does everyone actually agree so far?",intensity:2,rarity:"signature",pol:{}},
{id:3413,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Interrupted-topic reclaimer",desc:"Returns firmly to their original point after being sidetracked.",example:"Back to what I was saying before that—",intensity:2,rarity:"common",pol:{}},
{id:3414,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Silence-inviting question asker",desc:"Poses a question specifically designed to open space for others.",example:"What does everyone else think? Really — anyone?",intensity:1,rarity:"common",pol:{}},
{id:3415,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Overlap-yielding speaker",desc:"Immediately stops talking the instant someone else starts.",example:"(stops mid-word the second another voice begins)",intensity:2,rarity:"signature",pol:{}},
{id:3416,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-stealing topic changer",desc:"Interrupts by introducing an entirely unrelated urgent topic.",example:"Sorry — sorry — has anyone seen the horses?",intensity:3,rarity:"signature",pol:{}},
{id:3417,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Formal-floor-yielder",desc:"Explicitly hands the conversation to the next speaker by name.",example:"I'll stop there. Marta, your thoughts?",intensity:2,rarity:"signature",pol:{}},
{id:3418,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Rapid-response volleyer",desc:"Responds to points almost instantly, leaving no gap.",example:"(answer arrives before the question fully lands)",intensity:2,rarity:"signature",pol:{}},
{id:3419,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Grace-period interrupter",desc:"Waits exactly a beat before jumping in, never longer.",example:"(one beat, then in) Actually, if I can just add—",intensity:2,rarity:"signature",pol:{}},
{id:3420,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Consensus-checking closer",desc:"Ends their turn by explicitly checking if the group agrees.",example:"That's my take. Are we aligned on that?",intensity:2,rarity:"signature",pol:{}},
{id:3421,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Silent-yielding nodder",desc:"Signals turn-yielding through a nod rather than words.",example:"(nods toward them, inviting the next speaker without a word)",intensity:1,rarity:"signature",pol:{}},
{id:3422,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Rebuttal-primed listener",desc:"Visibly prepares their counter-argument while still listening.",example:"(already shaking their head before the point is finished)",intensity:2,rarity:"signature",pol:{}},
{id:3423,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-order enforcer",desc:"Insists on strict, orderly turn-taking in group discussions.",example:"One at a time. You first, then you.",intensity:2,rarity:"signature",pol:{}},
{id:3424,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Apologetic-cutoff speaker",desc:"Interrupts but immediately apologizes for doing so.",example:"Sorry to jump in — sorry — but I think—",intensity:2,rarity:"common",pol:{}},
{id:3425,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Extended-pause claimant",desc:"Uses a long silence deliberately to claim and hold the floor.",example:"(says nothing for several long seconds, then begins, unhurried)",intensity:2,rarity:"signature",pol:{}},
{id:3426,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Group-redirect speaker",desc:"Actively steers the conversational turn toward a quieter member.",example:"We haven't heard from you yet — what's your take?",intensity:1,rarity:"signature",pol:{}},
{id:3427,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Immediate-echo responder",desc:"Repeats the last few words of the previous speaker before adding their own point.",example:"'—can't be trusted.' Can't be trusted, exactly, and here's why.",intensity:2,rarity:"signature",pol:{}},
{id:3428,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Turn-refusing deferrer",desc:"Explicitly declines the floor when it's offered to them.",example:"No, go ahead — I don't have anything to add right now.",intensity:1,rarity:"common",pol:{}},
{id:3429,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Closing-summary claimant",desc:"Takes the final turn specifically to summarize the whole discussion.",example:"So, to bring it all together — here's where we landed.",intensity:2,rarity:"signature",pol:{}},
{id:3430,section:"Mannerisms",category:"Emotional Affectations",trait:"Pride-swallowing gulp",desc:"Visibly forces down pride before admitting a mistake.",example:"(swallows hard) You were right. I was wrong.",intensity:3,rarity:"signature",pol:{}},
{id:3431,section:"Mannerisms",category:"Emotional Affectations",trait:"Delighted-hand-clasp",desc:"Claps hands together once, delighted, at good news.",example:"(hands clasp together) Oh, wonderful!",intensity:2,rarity:"common",pol:{}},
{id:3432,section:"Mannerisms",category:"Emotional Affectations",trait:"Nervous-throat-bob",desc:"Throat visibly bobs before delivering difficult news.",example:"(throat bobs) I have to tell you something.",intensity:3,rarity:"signature",pol:{}},
{id:3433,section:"Mannerisms",category:"Emotional Affectations",trait:"Contempt-nose-flare",desc:"Nostrils flare briefly at something they hold in disdain.",example:"(nostrils flare) Is that really your plan?",intensity:3,rarity:"signature",pol:{}},
{id:3434,section:"Mannerisms",category:"Emotional Affectations",trait:"Awkward-half-laugh",desc:"Laughs partway, then stops abruptly, unsure if it's appropriate.",example:"(half a laugh, cuts off) Sorry — is that funny? I wasn't sure.",intensity:2,rarity:"signature",pol:{}},
{id:3435,section:"Mannerisms",category:"Emotional Affectations",trait:"Vulnerable-lip-tremble",desc:"Lower lip trembles slightly before an emotional admission.",example:"(lip trembles) I miss him. That's all.",intensity:4,rarity:"signature",pol:{}},
{id:3436,section:"Mannerisms",category:"Emotional Affectations",trait:"Satisfied-exhale-smile",desc:"Exhales slowly with a small, satisfied smile after success.",example:"(smiles, exhales) There. Done.",intensity:2,rarity:"common",pol:{}},
{id:3437,section:"Mannerisms",category:"Emotional Affectations",trait:"Anger-jaw-clench release",desc:"Jaw unclenches visibly the moment anger finally passes.",example:"(jaw unclenches) ...Alright. I'm calm now.",intensity:3,rarity:"signature",pol:{}},
{id:3438,section:"Mannerisms",category:"Emotional Affectations",trait:"Guilty-shoulder-hunch",desc:"Shoulders hunch inward the moment guilt is triggered.",example:"(shoulders hunch) I should've told you sooner.",intensity:3,rarity:"signature",pol:{}},
{id:3439,section:"Mannerisms",category:"Emotional Affectations",trait:"Genuine-surprise gasp",desc:"Gasps audibly and authentically at real, unexpected news.",example:"(gasps) You're kidding! Really?",intensity:2,rarity:"common",pol:{}},
{id:3440,section:"Mannerisms",category:"Emotional Affectations",trait:"Suppressed-grief-swallow",desc:"Visibly swallows down grief mid-conversation, pressing on.",example:"(swallows, pushes through) Anyway. What's next?",intensity:4,rarity:"signature",pol:{}},
{id:3441,section:"Mannerisms",category:"Emotional Affectations",trait:"Sheepish-head-duck",desc:"Ducks their head slightly when caught in an obvious mistake.",example:"(ducks head) Yeah, that was me.",intensity:2,rarity:"common",pol:{}},
{id:3442,section:"Mannerisms",category:"Emotional Affectations",trait:"Fierce-eye-flash",desc:"Eyes flash with sudden intensity at a perceived threat.",example:"(eyes flash) Say that again.",intensity:3,rarity:"signature",pol:{}},
{id:3443,section:"Mannerisms",category:"Emotional Affectations",trait:"Comforted-shoulder-drop",desc:"Shoulders visibly relax the instant they feel reassured.",example:"(shoulders drop) Okay. Okay, good.",intensity:2,rarity:"common",pol:{}},
{id:3444,section:"Mannerisms",category:"Emotional Affectations",trait:"Betrayed-flinch-recoil",desc:"Physically recoils slightly at the moment of realizing betrayal.",example:"(recoils) You knew? This whole time, you knew?",intensity:4,rarity:"signature",pol:{}},
{id:3445,section:"Mannerisms",category:"Emotional Affectations",trait:"Warm-crinkle-smile",desc:"A genuine smile that visibly crinkles the whole face.",example:"(the whole face lights, crinkles) There you are.",intensity:2,rarity:"common",pol:{}},
{id:3446,section:"Mannerisms",category:"Emotional Affectations",trait:"Embarrassed-cheek-touch",desc:"Touches their own cheek self-consciously when embarrassed.",example:"(touches cheek) Oh — didn't realize you heard that.",intensity:2,rarity:"signature",pol:{}},
{id:3447,section:"Mannerisms",category:"Emotional Affectations",trait:"Determined-chin-set",desc:"Sets their chin firmly before committing to a hard decision.",example:"(chin sets, firm) We're doing this.",intensity:3,rarity:"signature",pol:{}},
{id:3448,section:"Mannerisms",category:"Emotional Affectations",trait:"Grateful-eye-well",desc:"Eyes well up slightly at genuine, unexpected kindness.",example:"(eyes well up) Nobody's done that for me before.",intensity:3,rarity:"signature",pol:{}},
{id:3449,section:"Mannerisms",category:"Emotional Affectations",trait:"Defensive-arm-cross-snap",desc:"Arms snap into a crossed position the instant they feel accused.",example:"(arms snap crossed) That wasn't me.",intensity:3,rarity:"signature",pol:{}},
{id:3450,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Table-edge aligner",desc:"Squares objects to the exact edge of any table they sit at.",example:"(nudges the cup precisely parallel to the table edge)",intensity:1,rarity:"signature",pol:{}},
{id:3451,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Doorframe-tapper",desc:"Taps the doorframe once, every time, passing through.",example:"(taps the frame, always, on the way through)",intensity:1,rarity:"signature",pol:{}},
{id:3452,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Chalk-line follower",desc:"Walks along visible seams or cracks in floors rather than open space.",example:"(follows the floorboard seam exactly, without noticing)",intensity:1,rarity:"signature",pol:{}},
{id:3453,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Curtain-adjuster",desc:"Nudges curtains a precise amount whenever passing a window.",example:"(adjusts the curtain fractionally, every single time)",intensity:1,rarity:"signature",pol:{}},
{id:3454,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Fireplace-poker fidgeter",desc:"Absently pokes at fires that don't need tending.",example:"(pokes the already-fine fire, thinking)",intensity:2,rarity:"common",pol:{}},
{id:3455,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Bell-cord toucher",desc:"Touches the servant's bell-cord without ringing it, out of habit.",example:"(fingers brush the cord, doesn't pull it)",intensity:1,rarity:"signature",pol:{}},
{id:3456,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Ledge-duster",desc:"Runs a finger along shelves and ledges, checking for dust.",example:"(finger trails the shelf, checking)",intensity:1,rarity:"signature",pol:{}},
{id:3457,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Stair-counter",desc:"Silently counts stairs while climbing, every time.",example:"(lips move slightly, counting the steps)",intensity:1,rarity:"signature",pol:{}},
{id:3458,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Cushion-repositioner",desc:"Adjusts seating cushions to precise angles before sitting.",example:"(turns the cushion exactly forty-five degrees first)",intensity:1,rarity:"signature",pol:{}},
{id:3459,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Table-leg kicker check",desc:"Nudges table legs with a foot to test their stability.",example:"(taps the table leg with a foot, testing)",intensity:1,rarity:"signature",pol:{}},
{id:3460,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Window-frost tracer",desc:"Traces patterns in condensation on cold windows while talking.",example:"(finger draws a slow line through the frost)",intensity:1,rarity:"signature",pol:{}},
{id:3461,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Bookend straightener",desc:"Squares books precisely between bookends before continuing.",example:"(nudges the spine flush, mid-sentence)",intensity:1,rarity:"signature",pol:{}},
{id:3462,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Chair-scrape avoider",desc:"Lifts chairs carefully to avoid any scraping sound.",example:"(lifts the chair silently rather than dragging it)",intensity:1,rarity:"signature",pol:{}},
{id:3463,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Lamp-wick trimmer",desc:"Fidgets with lamp wicks and flames absently during conversation.",example:"(trims the wick that didn't need trimming)",intensity:1,rarity:"signature",pol:{}},
{id:3464,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Handrail-grip tester",desc:"Tests the sturdiness of handrails and banisters before using them.",example:"(gives the rail a firm shake before trusting it)",intensity:2,rarity:"signature",pol:{}},
{id:3465,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Threshold-salt sprinkler",desc:"Performs a small, private ritual gesture at doorways.",example:"(a tiny, unconscious gesture crossing any threshold)",intensity:2,rarity:"signature",pol:{}},
{id:3466,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Ceiling-beam counter",desc:"Glances upward and briefly counts ceiling beams when thinking.",example:"(eyes flick up, counting beams, mid-thought)",intensity:1,rarity:"signature",pol:{}},
{id:3467,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Draft-checker",desc:"Notices and reacts to the smallest draft in any room.",example:"(feels for the draft, traces it to a gap under the door)",intensity:1,rarity:"signature",pol:{}},
{id:3468,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Candle-count arranger",desc:"Arranges candles into a specific, preferred number and pattern.",example:"(rearranges the candles into their usual three-and-two)",intensity:1,rarity:"signature",pol:{}},
{id:3469,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Floorboard-creak avoider",desc:"Deliberately steps to avoid the floorboards they know creak.",example:"(steps around the third board, out of long habit)",intensity:1,rarity:"signature",pol:{}},
{id:3470,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Recognition-dawning look",desc:"Face shifts visibly as understanding suddenly arrives.",example:"(the face changes) ...oh. OH.",intensity:2,rarity:"common",pol:{}},
{id:3471,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Skeptical-single-brow",desc:"Raises only one eyebrow at a doubtful claim.",example:"(one brow up) Is that so.",intensity:2,rarity:"common",pol:{}},
{id:3472,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Concealed-pain flicker",desc:"A flash of pain crosses the face before being smoothed away.",example:"(a flicker, gone fast) I'm fine. Continue.",intensity:3,rarity:"signature",pol:{}},
{id:3473,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Wide-innocent blink",desc:"Blinks wide and slow to project innocence, convincingly or not.",example:"(wide, slow blink) I have no idea what you mean.",intensity:2,rarity:"signature",pol:{}},
{id:3474,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Tight-jaw restraint",desc:"Jaw visibly tightens to hold back an unwanted response.",example:"(jaw tightens) ...Noted.",intensity:3,rarity:"signature",pol:{}},
{id:3475,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Soft-eyes listening",desc:"Eyes visibly soften while genuinely listening to distress.",example:"(eyes soften) Tell me. I'm listening.",intensity:2,rarity:"common",pol:{}},
{id:3476,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Sharp-glance warning",desc:"A single sharp glance functions as an unspoken warning.",example:"(one hard glance; the room goes quiet)",intensity:3,rarity:"signature",pol:{}},
{id:3477,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Delighted-eyebrow-raise",desc:"Both brows lift together at a pleasant surprise.",example:"(both brows up) Well, isn't that something.",intensity:2,rarity:"common",pol:{}},
{id:3478,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Grim-mouth-line",desc:"Mouth sets into a flat, grim line before hard news.",example:"(mouth sets flat) You should sit down for this.",intensity:3,rarity:"signature",pol:{}},
{id:3479,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Amused-corner-twitch",desc:"Corner of the mouth twitches, suppressing a smile.",example:"(corner twitches, held back) Funny. Very funny.",intensity:2,rarity:"common",pol:{}},
{id:3480,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Long-lash-lowered gaze",desc:"Lowers the gaze slowly, deliberately, when avoiding a topic.",example:"(gaze lowers, slow, deliberate)",intensity:2,rarity:"signature",pol:{}},
{id:3481,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Startled-full-blink",desc:"Both eyes blink hard, once, at sudden surprise.",example:"(a hard, full blink) Wait — what?",intensity:2,rarity:"common",pol:{}},
{id:3482,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Cold-unblinking stare",desc:"Holds an unblinking stare specifically to unsettle an opponent.",example:"(does not blink, not once, through the whole exchange)",intensity:4,rarity:"signature",pol:{}},
{id:3483,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Warm-crow's-feet crinkle",desc:"Genuine warmth shows first in the crinkling at the eyes.",example:"(the eyes crinkle before the smile even starts)",intensity:1,rarity:"common",pol:{}},
{id:3484,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Puzzled-head-tilt squint",desc:"Tilts the head and narrows the eyes at something confusing.",example:"(head tilts, eyes narrow) I don't follow.",intensity:2,rarity:"common",pol:{}},
{id:3485,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Guilty-avoidant blink-rate",desc:"Blinks noticeably faster the moment guilt is triggered.",example:"(blink rate spikes) I don't— I wasn't— what?",intensity:3,rarity:"signature",pol:{}},
{id:3486,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Proud-chin-lift gaze",desc:"Lifts the chin and gaze together in a moment of quiet pride.",example:"(chin lifts, gaze steady) I did that. Me.",intensity:2,rarity:"signature",pol:{}},
{id:3487,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Weary-heavy-lidded look",desc:"Eyelids grow visibly heavy under accumulated exhaustion.",example:"(eyes half-closed) Just — give me a moment.",intensity:3,rarity:"signature",pol:{}},
{id:3488,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Suspicious-narrowed-track",desc:"Eyes narrow and visibly track a suspicious person across a room.",example:"(eyes narrow, follow him across the room)",intensity:2,rarity:"signature",pol:{}},
{id:3489,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Openly-adoring gaze",desc:"Gaze softens completely, undisguised, when looking at someone loved.",example:"(the whole face softens, undisguised)",intensity:2,rarity:"common",pol:{}},
{id:3490,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Steepled-then-spread hands",desc:"Steeples fingers, then spreads them wide for a big reveal.",example:"(fingers steeple, then spread) —and that's the whole plan.",intensity:2,rarity:"signature",pol:{}},
{id:3491,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Emphatic-table-slap",desc:"Slaps the table once, sharply, at a key point.",example:"(slaps the table) That's final.",intensity:3,rarity:"common",pol:{}},
{id:3492,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Slow-clap sarcasm",desc:"Uses an exaggeratedly slow clap to convey mockery.",example:"(claps, slow, deliberate) Bravo. Truly.",intensity:3,rarity:"signature",pol:{}},
{id:3493,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Two-finger point",desc:"Points with two fingers together rather than one, habitually.",example:"(points with two fingers) You. And you.",intensity:2,rarity:"signature",pol:{}},
{id:3494,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Hand-over-heart pledge",desc:"Places a hand over the heart when making a sincere promise.",example:"(hand to chest) I swear it.",intensity:2,rarity:"common",pol:{}},
{id:3495,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Circling-wrist explainer",desc:"Circles a wrist continuously while working through an explanation.",example:"(wrist circles slowly) So basically, the way it works is—",intensity:1,rarity:"signature",pol:{}},
{id:3496,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Finger-gun dismissal",desc:"Uses a casual finger-gun gesture to dismiss or approve something.",example:"(finger-gun, click of the tongue) You got it.",intensity:2,rarity:"signature",pol:{}},
{id:3497,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Cupped-hands offering",desc:"Cups both hands together when making a heartfelt request.",example:"(hands cupped) Please. I'm asking properly.",intensity:2,rarity:"signature",pol:{}},
{id:3498,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Chopping-hand list-maker",desc:"Chops the air with a flat hand to mark each item in a list.",example:"(chop) First. (chop) Second. (chop) Third.",intensity:2,rarity:"signature",pol:{}},
{id:3499,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Slow-reveal palm turn",desc:"Turns a closed hand slowly into an open palm for dramatic reveal.",example:"(hand turns, opens slowly) —and there it is.",intensity:2,rarity:"signature",pol:{}},
{id:3500,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Double-thumbs-up affirmer",desc:"Gives an exaggerated double thumbs-up at good news.",example:"(both thumbs up, grinning)",intensity:2,rarity:"common",pol:{}},
{id:3501,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Air-underline gesture",desc:"Draws an underline in the air beneath key spoken words.",example:"(underlines the word in the air) Exactly THAT.",intensity:2,rarity:"signature",pol:{}},
{id:3502,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Reaching-then-retracting hand",desc:"Starts to reach out, then pulls the hand back, hesitant.",example:"(hand starts to reach, pulls back)",intensity:3,rarity:"signature",pol:{}},
{id:3503,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Finger-to-lips hush",desc:"Presses a finger to the lips to signal quiet.",example:"(finger to lips) Shh. Someone's coming.",intensity:2,rarity:"common",pol:{}},
{id:3504,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Rolling-hand continuer",desc:"Rolls a hand in small circles to signal 'keep going'.",example:"(rolls a hand) Yes, yes, go on.",intensity:1,rarity:"signature",pol:{}},
{id:3505,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Firm-handclasp sealer",desc:"Seals agreements with an unusually firm, deliberate handclasp.",example:"(grips the hand firmly) Deal.",intensity:2,rarity:"common",pol:{}},
{id:3506,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Wide-arm-spread welcome",desc:"Spreads both arms wide in an exaggerated gesture of welcome.",example:"(arms spread wide) Come in, come in!",intensity:2,rarity:"common",pol:{}},
{id:3507,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Tight-fist-under-table",desc:"Clenches a fist out of sight while maintaining a calm face.",example:"(fist clenches under the table, face unmoved)",intensity:3,rarity:"signature",pol:{}},
{id:3508,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Slow-nod-with-gesture",desc:"Combines a slow nod with a small confirming hand motion.",example:"(nods slowly, hand motions 'yes')",intensity:1,rarity:"signature",pol:{}},
{id:3509,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Snap-and-point combo",desc:"Snaps fingers and points in one motion when an idea strikes.",example:"(snap, point) That's it. That's the answer.",intensity:2,rarity:"signature",pol:{}},
{id:3510,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Knuckle-whitening grip",desc:"Grips whatever's nearby tight enough to whiten the knuckles.",example:"(knuckles go white on the chair arm)",intensity:3,rarity:"signature",pol:{}},
{id:3511,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Rapid-eye-blink cluster",desc:"Blinks in a rapid cluster specifically under acute stress.",example:"(blinks rapidly, several times, fast)",intensity:2,rarity:"signature",pol:{}},
{id:3512,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Tongue-click thinking",desc:"Clicks the tongue softly, rhythmically, while thinking something through.",example:"(soft tongue click, repeated, thinking)",intensity:1,rarity:"signature",pol:{}},
{id:3513,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Sudden-stillness freeze",desc:"Goes completely, unnaturally still for a beat before responding.",example:"(goes still, entirely, for a second) ...Right.",intensity:2,rarity:"signature",pol:{}},
{id:3514,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Finger-steeple tremor",desc:"A faint tremor shows in steepled fingers under real pressure.",example:"(fingers steepled, the faintest tremor visible)",intensity:3,rarity:"signature",pol:{}},
{id:3515,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Repetitive-swallow tic",desc:"Swallows repeatedly, visibly, when nervous or dishonest.",example:"(swallows, again, and again)",intensity:3,rarity:"signature",pol:{}},
{id:3516,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Nail-bed press",desc:"Presses a thumbnail into the pad of a finger when thinking.",example:"(presses the nail in, hard, thinking)",intensity:1,rarity:"signature",pol:{}},
{id:3517,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Sudden-inhale-hold",desc:"Inhales sharply and holds the breath at a moment of shock.",example:"(sharp inhale, held) ...What?",intensity:3,rarity:"signature",pol:{}},
{id:3518,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Jaw-side-shift",desc:"Shifts the jaw slightly sideways under building tension.",example:"(jaw shifts, slight, tension building)",intensity:2,rarity:"signature",pol:{}},
{id:3519,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Wrist-pulse check",desc:"Unconsciously presses fingers to their own wrist when anxious.",example:"(fingers find their own pulse, absently)",intensity:2,rarity:"signature",pol:{}},
{id:3520,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Rapid-foot-tap burst",desc:"Taps a foot in short, rapid bursts rather than a steady rhythm.",example:"(foot taps, quick bursts, then stops)",intensity:2,rarity:"signature",pol:{}},
{id:3521,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Lip-corner pull",desc:"One corner of the mouth pulls slightly when suppressing a reaction.",example:"(corner of the mouth pulls, held)",intensity:2,rarity:"signature",pol:{}},
{id:3522,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Neck-tendon tightening",desc:"A tendon in the neck visibly tightens under real strain.",example:"(the tendon stands out, just slightly)",intensity:2,rarity:"signature",pol:{}},
{id:3523,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Finger-count silent",desc:"Silently counts something on fingers, unconsciously, while listening.",example:"(fingers move slightly, counting, unaware of it)",intensity:1,rarity:"signature",pol:{}},
{id:3524,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Micro-shoulder-shrug flash",desc:"A tiny, involuntary shoulder shrug flashes and vanishes.",example:"(a small shrug, there and gone)",intensity:1,rarity:"signature",pol:{}},
{id:3525,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Eye-corner crinkle-suppress",desc:"Suppresses the crinkle of a genuine smile at an inopportune moment.",example:"(the crinkle starts, gets caught, smoothed away)",intensity:2,rarity:"signature",pol:{}},
{id:3526,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Rapid-pulse-visible throat",desc:"A visible pulse quickens at the throat under acute stress.",example:"(the pulse at the throat visibly quickens)",intensity:3,rarity:"signature",pol:{}},
{id:3527,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Thumb-nail worry",desc:"Worries at a thumbnail with the opposite thumb when anxious.",example:"(thumb worries at the nail, absent, anxious)",intensity:1,rarity:"signature",pol:{}},
{id:3528,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Sudden-cold-shiver",desc:"A visible shiver passes through despite no actual cold.",example:"(a shiver, unrelated to temperature)",intensity:2,rarity:"signature",pol:{}},
{id:3529,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Held-exhale release",desc:"Holds an exhale unnaturally long before finally letting it go.",example:"(holds the breath, longer than natural, releases slow)",intensity:2,rarity:"signature",pol:{}},
{id:3530,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Startled-inhale gasp",desc:"A sudden, sharp inward breath at genuine shock.",example:"(sharp inhale) Oh — I didn't expect that.",intensity:2,rarity:"common",pol:{}},
{id:3531,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Low-satisfied hum",desc:"Hums low and brief at a small, genuine satisfaction.",example:"(a low, satisfied hum) Mm. Good.",intensity:1,rarity:"common",pol:{}},
{id:3532,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Frustrated-exhale huff",desc:"Exhales sharply through the nose at building frustration.",example:"(huffs, sharp) Fine. Whatever.",intensity:2,rarity:"common",pol:{}},
{id:3533,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Delighted-squeal suppress",desc:"Suppresses an excited sound into a smaller, tighter noise.",example:"(a small, suppressed squeal) I'm SO excited, sorry.",intensity:2,rarity:"signature",pol:{}},
{id:3534,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Weary-groan settling",desc:"Groans softly while settling into a chair after a long day.",example:"(settles, groans softly) Oh, that's better.",intensity:2,rarity:"common",pol:{}},
{id:3535,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Nervous-cough clearing",desc:"Clears the throat repeatedly, nervously, before hard admissions.",example:"(clears throat, twice) I need to say something.",intensity:2,rarity:"common",pol:{}},
{id:3536,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Contained-sob hiccup",desc:"A single suppressed sob escapes as a small hiccupping sound.",example:"(a small hiccup of a sob, quickly controlled)",intensity:4,rarity:"signature",pol:{}},
{id:3537,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Amused-snort laugh",desc:"Laughs through the nose in a short, involuntary snort.",example:"(snorts, laughing) Sorry — that was just funny.",intensity:2,rarity:"common",pol:{}},
{id:3538,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Deep-sigh resignation",desc:"Releases a long, deep sigh signaling resigned acceptance.",example:"(a long sigh) Alright. If that's how it is.",intensity:2,rarity:"common",pol:{}},
{id:3539,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sharp-hiss pain response",desc:"Hisses sharply through clenched teeth at sudden pain or shock.",example:"(hisses) That hurt more than expected.",intensity:2,rarity:"signature",pol:{}},
{id:3540,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Low-rumble chuckle",desc:"Chuckles with a low, rumbling, barely-audible quality.",example:"(a low rumble of a laugh, almost silent)",intensity:1,rarity:"signature",pol:{}},
{id:3541,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Anxious-lip-smack",desc:"Smacks the lips softly, repeatedly, when nervous or thinking.",example:"(a soft, repeated lip smack, thinking)",intensity:1,rarity:"signature",pol:{}},
{id:3542,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Relieved-whoosh exhale",desc:"Releases a visible, audible whoosh of relief.",example:"(a whoosh of breath) Thank goodness. Thank goodness.",intensity:2,rarity:"common",pol:{}},
{id:3543,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Suppressed-yawn stretch-sound",desc:"Makes a small strained sound while suppressing a yawn.",example:"(a strained little sound, suppressing a yawn)",intensity:1,rarity:"common",pol:{}},
{id:3544,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Determined-grunt effort",desc:"Grunts briefly with real physical or mental effort.",example:"(a short grunt) —there. Got it.",intensity:2,rarity:"common",pol:{}},
{id:3545,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Startled-squeak",desc:"Emits a small, involuntary squeak at sudden fright.",example:"(a tiny, involuntary squeak) You scared me!",intensity:2,rarity:"signature",pol:{}},
{id:3546,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Long-inhale steadying",desc:"Takes one long, deliberate inhale to steady themselves before speaking.",example:"(one long, steadying breath) Okay. Here goes.",intensity:2,rarity:"signature",pol:{}},
{id:3547,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Quiet-mmhm-agreement train",desc:"Strings several soft 'mm-hm's together while listening closely.",example:"Mm-hm. Mm-hm. Mm-hm. Go on.",intensity:1,rarity:"common",pol:{}},
{id:3548,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Sharp-tsk irritation",desc:"A quick, sharp tsk signals irritation without further words.",example:"Tsk. Of course.",intensity:2,rarity:"common",pol:{}},
{id:3549,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Breathless-laugh trail-off",desc:"Laughs until it trails into breathlessness rather than stopping cleanly.",example:"(laughs, laughs, trails into a breathless exhale)",intensity:2,rarity:"signature",pol:{}},
{id:3550,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Hip-cocked casual stance",desc:"Stands with one hip cocked, weight unevenly distributed, relaxed.",example:"(hip cocked, weight on one leg, unhurried)",intensity:1,rarity:"common",pol:{}},
{id:3551,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Braced-for-impact stance",desc:"Plants feet wide and low, visibly bracing for confrontation.",example:"(feet plant wide, low, ready)",intensity:3,rarity:"signature",pol:{}},
{id:3552,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Chin-tucked defensive posture",desc:"Tucks the chin down and in when feeling exposed or criticized.",example:"(chin tucks, shoulders draw in slightly)",intensity:2,rarity:"signature",pol:{}},
{id:3553,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Loose-limbed relaxed sprawl",desc:"Limbs fall loose and open when fully at ease.",example:"(arms and legs loose, unguarded, comfortable)",intensity:1,rarity:"common",pol:{}},
{id:3554,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Formal-parade posture",desc:"Holds an unnaturally straight, formal posture in casual settings.",example:"(stands as if still in uniform, even now)",intensity:2,rarity:"signature",pol:{}},
{id:3555,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Backward-lean skepticism",desc:"Leans back, arms folded, when doubting what's being said.",example:"(leans back, arms fold) Convince me.",intensity:2,rarity:"common",pol:{}},
{id:3556,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Forward-perch anticipation",desc:"Perches at the edge of a seat, anticipating the need to move.",example:"(sits at the very edge, ready to spring up)",intensity:2,rarity:"signature",pol:{}},
{id:3557,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"One-foot-out-the-door stance",desc:"Angles the body slightly toward the exit throughout a conversation.",example:"(body angled toward the door, the whole time)",intensity:2,rarity:"signature",pol:{}},
{id:3558,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Protective-half-turn",desc:"Turns half their body to shield someone standing behind them.",example:"(turns, subtly, to stand partly between)",intensity:2,rarity:"signature",pol:{}},
{id:3559,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Grounded-wide-stance speaker",desc:"Stands with feet wide and grounded when delivering firm opinions.",example:"(feet planted wide, unmoving, delivering the verdict)",intensity:2,rarity:"signature",pol:{}},
{id:3560,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Curled-knee hug seated",desc:"Pulls knees up and hugs them when feeling small or vulnerable.",example:"(knees pulled up, arms wrapped around them)",intensity:3,rarity:"signature",pol:{}},
{id:3561,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Leaning-toward-warmth posture",desc:"Physically leans toward whoever they feel closest to in a group.",example:"(leans, unconsciously, toward the one person they trust)",intensity:1,rarity:"signature",pol:{}},
{id:3562,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Squared-shoulders confrontation ready",desc:"Squares shoulders fully the instant conflict seems likely.",example:"(shoulders square, instantly, at the first sign of trouble)",intensity:3,rarity:"common",pol:{}},
{id:3563,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Slow-settle after standing",desc:"Takes visibly longer than most to settle once seated.",example:"(shifts, resettles, shifts again before finally still)",intensity:1,rarity:"signature",pol:{}},
{id:3564,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Wall-shadow hugger",desc:"Instinctively stays within the shadow line along walls.",example:"(stays close to the wall, in the shadow, moving through a room)",intensity:2,rarity:"signature",pol:{}},
{id:3565,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Open-doorway blocker unaware",desc:"Unknowingly stands in doorways, blocking passage, mid-conversation.",example:"(stands square in the doorway, oblivious to the queue forming)",intensity:1,rarity:"common",pol:{}},
{id:3566,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Height-minimizing crouch",desc:"Lowers their own height deliberately around nervous people or animals.",example:"(crouches down, smaller, less threatening)",intensity:2,rarity:"signature",pol:{}},
{id:3567,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Restless-recross seated",desc:"Recrosses legs repeatedly when seated and impatient.",example:"(legs cross, uncross, cross the other way)",intensity:1,rarity:"common",pol:{}},
{id:3568,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Fixed-point staring stance",desc:"Stands very still, staring at one fixed point, when deep in thought.",example:"(entirely still, eyes fixed on nothing in particular)",intensity:2,rarity:"signature",pol:{}},
{id:3569,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Mirroring-distance keeper",desc:"Unconsciously maintains the exact same distance others set.",example:"(steps back exactly as far as the other person stepped forward)",intensity:1,rarity:"signature",pol:{}},
{id:3570,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Slow-approach announcer",desc:"Announces their approach from a distance before getting close.",example:"(calls out well before arriving) It's just me!",intensity:1,rarity:"common",pol:{}},
{id:3571,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-photo positioner",desc:"Physically arranges people into position for shared moments.",example:"You two swap — no, back a bit — right, that's it, don't move.",intensity:2,rarity:"signature",pol:{}},
{id:3572,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Unwanted-advice interrupter",desc:"Interjects unsolicited advice mid-conversation without noticing the overstep.",example:"Actually, if I could just suggest something—",intensity:2,rarity:"common",pol:{}},
{id:3573,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Overlong-eye-contact holder",desc:"Holds eye contact slightly longer than social norms suggest.",example:"(holds the gaze a beat too long, doesn't look away)",intensity:2,rarity:"signature",pol:{}},
{id:3574,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Physical-distance closer",desc:"Steps closer during emotionally significant moments, unbidden.",example:"(steps in, closing the distance, without asking)",intensity:2,rarity:"signature",pol:{}},
{id:3575,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-inclusion checker",desc:"Actively checks that no one in a group feels left out.",example:"We haven't heard from you — what do you think?",intensity:1,rarity:"common",pol:{}},
{id:3576,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Farewell-repeat hugger",desc:"Hugs goodbye multiple times before actually managing to leave.",example:"(hugs once) Okay, bye. (hugs again) Okay, really, bye.",intensity:2,rarity:"common",pol:{}},
{id:3577,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Boundary-testing joker",desc:"Tests social limits through jokes to see what's tolerated.",example:"Just kidding — mostly. Was that too far?",intensity:3,rarity:"signature",pol:{}},
{id:3578,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Space-claiming sitter",desc:"Sits down before being invited to, claiming the seat as theirs.",example:"(sits, settles, before any invitation is offered)",intensity:2,rarity:"signature",pol:{}},
{id:3579,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Overly-formal newcomer greeter",desc:"Greets new people with excessive, almost stiff formality.",example:"It is a genuine pleasure to make your acquaintance.",intensity:2,rarity:"signature",pol:{}},
{id:3580,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Compliment-insistent giver",desc:"Won't let a compliment be deflected, repeats it until accepted.",example:"No, really — that was genuinely excellent work.",intensity:1,rarity:"common",pol:{}},
{id:3581,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Silent-permission asker",desc:"Waits for a small nonverbal cue before proceeding with anything personal.",example:"(waits, watching, for the smallest sign of consent)",intensity:1,rarity:"signature",pol:{}},
{id:3582,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-energy dampener aware",desc:"Notices when their own energy is too much for the room and adjusts.",example:"(catches the mood, lowers their own volume deliberately)",intensity:1,rarity:"signature",pol:{}},
{id:3583,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Unprompted-secret sharer",desc:"Shares personal secrets with new acquaintances, unprompted.",example:"I don't usually tell people this, but—",intensity:3,rarity:"signature",pol:{}},
{id:3584,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Formal-distance keeper",desc:"Maintains a consistent, slightly greater-than-normal physical distance.",example:"(a half-step further back than most would stand)",intensity:2,rarity:"common",pol:{}},
{id:3585,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Interruption-tolerant host",desc:"Never seems bothered by guests interrupting or overstaying.",example:"Stay as long as you like. Really, no rush at all.",intensity:1,rarity:"common",pol:{}},
{id:3586,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Group-consensus checker",desc:"Regularly pauses to make sure the whole group is still aligned.",example:"Everyone still with me on this? Just checking.",intensity:1,rarity:"signature",pol:{}},
{id:3587,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Loud-goodbye announcer",desc:"Makes departures a visible, audible event for the whole room.",example:"Right, I'm off! Everybody, I'm leaving now!",intensity:2,rarity:"signature",pol:{}},
{id:3588,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Gentle-redirect toucher",desc:"Uses a light touch on the arm to gently redirect a conversation.",example:"(a light touch on the arm) Actually — about that—",intensity:1,rarity:"signature",pol:{}},
{id:3589,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Silence-comfortable companion",desc:"Sits comfortably in silence with others without needing to fill it.",example:"(sits together, says nothing, entirely at ease)",intensity:1,rarity:"signature",pol:{}},
{id:3590,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Ink-stain checker",desc:"Checks fingers for ink stains repeatedly while writing or talking.",example:"(glances at ink-stained fingers, wipes them absently)",intensity:1,rarity:"signature",pol:{}},
{id:3591,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Button-thread worrier",desc:"Worries at a loose button thread during tense conversation.",example:"(thumb worries the loose thread on a button)",intensity:1,rarity:"signature",pol:{}},
{id:3592,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Pocket-watch clicker",desc:"Opens and closes a pocket watch case rhythmically while thinking.",example:"(click, open, click, closed, thinking)",intensity:2,rarity:"signature",pol:{}},
{id:3593,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Handkerchief-folder",desc:"Folds and refolds a handkerchief into precise squares, repeatedly.",example:"(folds the handkerchief into a neat square, again)",intensity:1,rarity:"signature",pol:{}},
{id:3594,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Quill-twirler",desc:"Twirls a quill or pen between fingers while composing thoughts.",example:"(the pen spins, slow, between fingers, thinking)",intensity:1,rarity:"signature",pol:{}},
{id:3595,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Ribbon-wrapper",desc:"Wraps and unwraps a ribbon or cord around fingers absently.",example:"(the ribbon winds, unwinds, around a finger)",intensity:1,rarity:"signature",pol:{}},
{id:3596,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Seal-wax presser",desc:"Presses a thumb into cooling wax or clay absently while talking.",example:"(presses a thumbprint into the cooling wax, not noticing)",intensity:1,rarity:"signature",pol:{}},
{id:3597,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Bootlace-retier",desc:"Reties bootlaces mid-conversation, an anxious habit.",example:"(kneels, reties the lace that didn't need retying)",intensity:1,rarity:"signature",pol:{}},
{id:3598,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Coin-pocket jangler",desc:"Jingles loose coins in a pocket when impatient or thinking.",example:"(coins jingle, absent, in a closed fist within the pocket)",intensity:1,rarity:"signature",pol:{}},
{id:3599,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Glove-finger smoother",desc:"Smooths each finger of a glove individually before removing it.",example:"(smooths each finger flat before finally pulling it off)",intensity:1,rarity:"signature",pol:{}},
{id:3600,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Hat-brim adjuster",desc:"Adjusts a hat brim repeatedly, a fraction each time, while talking.",example:"(the brim tips down, then back up, fractionally, repeatedly)",intensity:1,rarity:"signature",pol:{}},
{id:3601,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Pipe-tamper",desc:"Tamps and re-tamps unlit tobacco in a pipe during long conversations.",example:"(taps the pipe down, unlit, thinking it through)",intensity:1,rarity:"signature",pol:{}},
{id:3602,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Signet-ring turner",desc:"Turns a signet ring around a finger during tense negotiations.",example:"(the ring turns, slow, full circle, thinking)",intensity:1,rarity:"signature",pol:{}},
{id:3603,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Fan-flick user",desc:"Flicks a folding fan open and shut rhythmically while speaking.",example:"(the fan snaps open, shut, open, punctuating the sentence)",intensity:1,rarity:"signature",pol:{}},
{id:3604,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Sachet-toucher",desc:"Touches a small scented pouch kept in a pocket, for comfort.",example:"(fingers find the small pouch, press it once, let go)",intensity:1,rarity:"signature",pol:{}},
{id:3605,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Chain-link counter",desc:"Counts the links of a chain or necklace absently between fingers.",example:"(fingers move along the chain, counting links, unaware)",intensity:1,rarity:"signature",pol:{}},
{id:3606,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Wax-seal breaker",desc:"Breaks wax seals with unusual ceremony and deliberateness.",example:"(breaks the seal slowly, watching it crack, before reading)",intensity:1,rarity:"signature",pol:{}},
{id:3607,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Cane-tapper",desc:"Taps a cane or walking stick rhythmically against the ground while thinking.",example:"(the cane taps, once, twice, marking the thought)",intensity:1,rarity:"signature",pol:{}},
{id:3608,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Scarf-adjuster",desc:"Adjusts a scarf or wrap repeatedly, a small, comforting habit.",example:"(tugs the scarf a fraction tighter, again)",intensity:1,rarity:"signature",pol:{}},
{id:3609,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Locket-latch tester",desc:"Tests that a locket's latch is properly closed, repeatedly.",example:"(checks the latch, again, without quite noticing)",intensity:1,rarity:"signature",pol:{}},
{id:3610,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Storyteller's-hush drop",desc:"Voice drops to a hush specifically at the most dramatic story beat.",example:"(voice drops, hushed) And that's when the door opened.",intensity:2,rarity:"common",pol:{}},
{id:3611,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Command-projected boom",desc:"Voice booms with unmistakable projected authority when giving orders.",example:"(voice fills the room) MOVE. NOW.",intensity:4,rarity:"signature",pol:{}},
{id:3612,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Trembling-composure voice",desc:"Voice trembles faintly while trying hard to sound composed.",example:"(a faint tremor, held mostly steady) I'm fine, really.",intensity:3,rarity:"signature",pol:{}},
{id:3613,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Rising-excitement pitch",desc:"Pitch climbs steadily as genuine excitement builds through a sentence.",example:"And then — and THEN — you won't BELIEVE—",intensity:2,rarity:"common",pol:{}},
{id:3614,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Deliberate-flat delivery",desc:"Deliberately strips all inflection from emotionally loaded statements.",example:"He's dead. The funeral's Tuesday. That's all I know.",intensity:3,rarity:"signature",pol:{}},
{id:3615,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Warm-lullaby cadence",desc:"Voice takes on a soft, rhythmic, soothing lullaby quality.",example:"(soft, rhythmic) It's alright. It's alright now.",intensity:2,rarity:"common",pol:{}},
{id:3616,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Sharp-command snap",desc:"Snaps into a hard, clipped command register instantly when needed.",example:"(instantly sharp) Down. Now. Quiet.",intensity:3,rarity:"signature",pol:{}},
{id:3617,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Wavering-then-steadying voice",desc:"Voice wavers at the start of a hard statement, then steadies.",example:"I— (wavers) —I need to tell you. (steadies) I need to tell you this.",intensity:3,rarity:"signature",pol:{}},
{id:3618,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Playful-mock-serious tone",desc:"Adopts an exaggeratedly serious tone for playful, joking effect.",example:"(mock-grave) This is, without question, the gravest crisis of our time.",intensity:1,rarity:"common",pol:{}},
{id:3619,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Confidential-lean-in murmur",desc:"Voice drops to a murmur specifically while leaning in close.",example:"(leans in, murmurs) Between us, only.",intensity:2,rarity:"common",pol:{}},
{id:3620,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Grief-hollowed monotone",desc:"Voice flattens into an exhausted, hollow monotone around loss.",example:"(flat, hollow) She's gone. That's it. She's gone.",intensity:4,rarity:"signature",pol:{}},
{id:3621,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Bright-performative cheer",desc:"Voice pitches artificially bright and cheerful to mask real feeling.",example:"(too bright) No, everything's great! Totally great!",intensity:3,rarity:"signature",pol:{}},
{id:3622,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Slow-deliberate gravity",desc:"Voice slows and deepens deliberately to lend weight to a statement.",example:"(slow, deliberate) This. Matters. More. Than. You. Know.",intensity:3,rarity:"signature",pol:{}},
{id:3623,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Cracking-anger edge",desc:"Voice cracks slightly at the edge of barely-controlled anger.",example:"(voice cracks, once) Don't. Just — don't.",intensity:4,rarity:"signature",pol:{}},
{id:3624,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Teasing-lilt questioner",desc:"Ends statements with a playful, teasing upward lilt.",example:"Someone's late again~ Wonder who~",intensity:1,rarity:"common",pol:{}},
{id:3625,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Steady-under-fire calm",desc:"Voice remains eerily, deliberately steady during actual crisis.",example:"(perfectly steady, mid-emergency) Everyone, this way. Calmly.",intensity:3,rarity:"signature",pol:{}},
{id:3626,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Soft-apology murmur",desc:"Voice drops soft and low specifically when apologizing.",example:"(soft, low) I'm sorry. I really am.",intensity:2,rarity:"common",pol:{}},
{id:3627,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Building-momentum speaker",desc:"Voice gains volume and speed as an argument builds toward its point.",example:"(starts quiet, builds) —and that's why — that's WHY—",intensity:2,rarity:"signature",pol:{}},
{id:3628,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Ironic-flat deadpan voice",desc:"Delivers clearly ironic statements in a completely flat tone.",example:"(flat) Wonderful. Truly the best possible outcome.",intensity:2,rarity:"common",pol:{}},
{id:3629,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Protective-low-growl edge",desc:"Voice takes on a low, warning edge when someone they love is threatened.",example:"(low, edged) Step away from her. Now.",intensity:3,rarity:"signature",pol:{}},
{id:3630,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Neighbor-checker",desc:"Regularly checks in on people nearby just to see how they're doing.",example:"Saw your light on late. Everything alright over there?",intensity:2,rarity:"common",pol:{}},
{id:3631,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Instant-trust extender",desc:"Extends genuine warmth to strangers before any reason to.",example:"Don't know you yet. Already like you, though.",intensity:2,rarity:"signature",pol:{}},
{id:3632,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Shared-meal insister",desc:"Cannot let someone leave hungry, insists on feeding them.",example:"You're not leaving without eating something first.",intensity:2,rarity:"common",pol:{}},
{id:3633,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Old-friend energy giver",desc:"Treats new acquaintances with the ease of decades-long friendship.",example:"Feels like I've known you forever, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:3634,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Gentle-teaser",desc:"Uses light, affectionate teasing to build closeness quickly.",example:"Look at you, all dressed up. Who are you trying to impress?",intensity:2,rarity:"common",pol:{}},
{id:3635,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Genuine-interest asker",desc:"Asks real follow-up questions rather than performing polite interest.",example:"Wait, go back — what happened after that?",intensity:2,rarity:"common",pol:{}},
{id:3636,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warmth-through-difficulty giver",desc:"Stays kind and open even during their own hard times.",example:"Rough week, sure. Still glad you're here, though.",intensity:3,rarity:"signature",pol:{}},
{id:3637,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Welcoming-silence sharer",desc:"Makes newcomers feel at ease even in quiet, wordless moments.",example:"(sits with them, comfortable, no need to fill the silence)",intensity:1,rarity:"signature",pol:{}},
{id:3638,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Effusive-thanks giver",desc:"Thanks people warmly and at length for even small kindnesses.",example:"You have no idea how much that meant. Truly, thank you.",intensity:2,rarity:"common",pol:{}},
{id:3639,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Instant-comfort offerer",desc:"Notices discomfort and moves immediately to fix it.",example:"You look cold. Here, take this.",intensity:2,rarity:"common",pol:{}},
{id:3640,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Party-connector",desc:"Actively introduces people to each other at gatherings.",example:"You two should talk — you'd get along, I think.",intensity:2,rarity:"signature",pol:{}},
{id:3641,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warm-farewell repeater",desc:"Sends people off with unusually warm, memorable goodbyes.",example:"Safe travels. Truly. Come back soon, won't you.",intensity:1,rarity:"common",pol:{}},
{id:3642,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Emotional-availability signaler",desc:"Makes clear, unprompted, that they're available to talk.",example:"If you ever need to talk, day or night, I mean that.",intensity:2,rarity:"signature",pol:{}},
{id:3643,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Genuine-compliment giver frequent",desc:"Offers specific, sincere compliments often throughout a day.",example:"That's a good color on you. Really suits you.",intensity:1,rarity:"common",pol:{}},
{id:3644,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Inclusive-default host",desc:"Automatically assumes new people are welcome at any gathering.",example:"Bring whoever. The more the better.",intensity:2,rarity:"common",pol:{}},
{id:3645,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warm-physical-presence",desc:"Simply being near them puts most people at ease.",example:"(their presence alone seems to loosen the room)",intensity:1,rarity:"signature",pol:{}},
{id:3646,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Kindness-first responder",desc:"Leads every interaction, even difficult ones, with kindness first.",example:"Before anything else — are you okay?",intensity:2,rarity:"common",pol:{}},
{id:3647,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Celebratory hugger",desc:"Hugs enthusiastically at good news, without hesitation.",example:"(pulls them into a hug before the sentence is even finished)",intensity:2,rarity:"common",pol:{}},
{id:3648,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Generous-listener",desc:"Gives full, undivided attention when someone needs to talk.",example:"Go on. I'm not going anywhere. Take your time.",intensity:2,rarity:"signature",pol:{}},
{id:3649,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warmth-extending stranger-greeter",desc:"Greets strangers on the street with genuine, easy friendliness.",example:"Morning! Lovely day, isn't it?",intensity:1,rarity:"common",pol:{}},
{id:3650,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Formality-shield user",desc:"Uses excessive formality specifically to keep people at bay.",example:"Mr. Aldren. A pleasure. Now, business.",intensity:2,rarity:"signature",pol:{}},
{id:3651,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Warmth-rationer",desc:"Doles out kindness sparingly, as though it were finite and precious.",example:"You'll have earned that, eventually. Not yet.",intensity:3,rarity:"signature",pol:{}},
{id:3652,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Company-tolerating loner",desc:"Endures social gatherings rather than enjoying them.",example:"(present, technically, and entirely elsewhere)",intensity:2,rarity:"common",pol:{}},
{id:3653,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Silence-preferring colleague",desc:"Prefers working in total silence, discourages casual chat.",example:"Can we not, while I'm working? Thank you.",intensity:2,rarity:"common",pol:{}},
{id:3654,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Emotionally-unreadable presence",desc:"Gives away almost nothing about their internal state, ever.",example:"(face reveals precisely nothing, as always)",intensity:3,rarity:"signature",pol:{}},
{id:3655,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Group-periphery dweller",desc:"Physically and socially remains at the edge of every gathering.",example:"(stands near the door, apart, through the whole party)",intensity:2,rarity:"common",pol:{}},
{id:3656,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Perfunctory-greeting giver",desc:"Offers the barest possible social greeting and moves on.",example:"Hello. (already walking past)",intensity:2,rarity:"common",pol:{}},
{id:3657,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Warmth-suspicious skeptic",desc:"Assumes friendliness from strangers has an ulterior motive.",example:"Nobody's this nice without wanting something.",intensity:3,rarity:"signature",pol:{}},
{id:3658,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Business-only persona",desc:"Reveals absolutely nothing personal, ever, in any professional context.",example:"We're not friends. We're colleagues. That's the arrangement.",intensity:3,rarity:"signature",pol:{}},
{id:3659,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Minimal-effort acquaintance",desc:"Puts in the least possible social effort to maintain necessary relationships.",example:"(remembers just enough to seem present, no more)",intensity:2,rarity:"signature",pol:{}},
{id:3660,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Cold-comfort giver",desc:"Offers technically correct but emotionally absent responses to distress.",example:"That's unfortunate. Anyway.",intensity:3,rarity:"signature",pol:{}},
{id:3661,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Distance-testing observer",desc:"Watches new people carefully before allowing any closeness.",example:"Let's see how you behave first.",intensity:2,rarity:"signature",pol:{}},
{id:3662,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Unmoved-by-charm skeptic",desc:"Remains unaffected by others' attempts at warmth or charisma.",example:"(charm bounces off entirely, unregistered)",intensity:2,rarity:"signature",pol:{}},
{id:3663,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Solitary-preference stater",desc:"States plainly and often that they prefer being alone.",example:"I do better on my own. Always have.",intensity:2,rarity:"common",pol:{}},
{id:3664,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Emotionally-locked door",desc:"Keeps their inner life entirely inaccessible, even to close contacts.",example:"(has known them years; they know nothing real)",intensity:4,rarity:"signature",pol:{}},
{id:3665,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Curt-professional distance keeper",desc:"Maintains strict professional distance even in casual moments.",example:"Let's keep this businesslike, if you don't mind.",intensity:2,rarity:"signature",pol:{}},
{id:3666,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Reluctant-participant",desc:"Attends social events out of obligation, visibly wishing to leave.",example:"(checks the door, repeatedly, the whole evening)",intensity:2,rarity:"signature",pol:{}},
{id:3667,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Approval-indifferent cold presence",desc:"Genuinely doesn't care whether others like them or not.",example:"Don't need you to like me. Just need you to listen.",intensity:3,rarity:"signature",pol:{}},
{id:3668,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Politely-final closer",desc:"Ends interactions with technically warm but clearly closing language.",example:"Lovely to see you. That's quite enough for today, though.",intensity:2,rarity:"signature",pol:{}},
{id:3669,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Guarded-smile giver",desc:"Smiles rarely, and even then, only partway.",example:"(the smallest possible smile, and no more)",intensity:2,rarity:"common",pol:{}},
{id:3670,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Undisguised-opinion giver",desc:"States opinions plainly without dressing them up as anything softer.",example:"I think it's a bad plan. That's my honest opinion.",intensity:2,rarity:"common",pol:{}},
{id:3671,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Fact-over-comfort chooser",desc:"Chooses accurate information over comforting reassurance, always.",example:"I could tell you it'll be fine. I won't, because I don't know that.",intensity:3,rarity:"signature",pol:{}},
{id:3672,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Self-implicating truth-teller",desc:"Willingly incriminates themselves if it's the accurate account.",example:"I was there too. I should say that plainly.",intensity:3,rarity:"signature",pol:{}},
{id:3673,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"No-spin reporter",desc:"Relays events exactly as they happened, without favorable framing.",example:"I didn't handle it well either. Let's be accurate about that.",intensity:3,rarity:"signature",pol:{}},
{id:3674,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Documented-honesty keeper",desc:"Keeps records specifically to ensure their own accounts stay accurate.",example:"I wrote it down that night. Here — read it yourself.",intensity:2,rarity:"signature",pol:{}},
{id:3675,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Immediate-correction giver",desc:"Corrects their own misstatements the instant they notice them.",example:"Wait, that's not right — let me correct that.",intensity:2,rarity:"common",pol:{}},
{id:3676,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Uncomfortable-truth volunteer",desc:"Offers hard truths even when nobody has asked for them.",example:"You didn't ask, but I think you should know—",intensity:3,rarity:"signature",pol:{}},
{id:3677,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Consistent-story teller",desc:"Tells the same account the same way, every single time, because it's true.",example:"Ask me again in a year. Same answer.",intensity:2,rarity:"signature",pol:{}},
{id:3678,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Blunt-feedback giver",desc:"Delivers criticism plainly, without cushioning, when asked or not.",example:"It's not good. Here's specifically why.",intensity:3,rarity:"common",pol:{}},
{id:3679,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"No-secret-keeping policy",desc:"Refuses to keep information from people it directly concerns.",example:"You should know this. I'm not going to sit on it.",intensity:3,rarity:"signature",pol:{}},
{id:3680,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Fair-witness reporter",desc:"Gives balanced, accurate accounts even of people they dislike.",example:"He was wrong here. He was actually right there, though.",intensity:2,rarity:"signature",pol:{}},
{id:3681,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Honest-about-limits admitter",desc:"States plainly what they don't know or can't do.",example:"I don't actually know the answer to that. Honestly.",intensity:2,rarity:"common",pol:{}},
{id:3682,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Truth-under-pressure holder",desc:"Maintains honest accounts even when lying would be easier.",example:"Could say it wasn't me. It was, though.",intensity:4,rarity:"signature",pol:{}},
{id:3683,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Direct-motive discloser",desc:"States their actual reasons for acting, even unflattering ones.",example:"Doing this partly for you, partly for myself. Both true.",intensity:2,rarity:"signature",pol:{}},
{id:3684,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Reliable-record keeper",desc:"Maintains scrupulously accurate personal accounts of events.",example:"Checked my notes. That's exactly what was said.",intensity:2,rarity:"signature",pol:{}},
{id:3685,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Uncomfortable-question answerer",desc:"Answers hard personal questions honestly rather than deflecting.",example:"Yes. That's the honest answer, uncomfortable as it is.",intensity:3,rarity:"signature",pol:{}},
{id:3686,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Transparency-as-policy holder",desc:"Treats openness as a firm operating principle, not a mood.",example:"I don't do secrets. Never have, on principle.",intensity:2,rarity:"signature",pol:{}},
{id:3687,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Self-correcting historian",desc:"Updates their own past statements when they learn they were wrong.",example:"I said that before. I was wrong. Here's what's actually true.",intensity:2,rarity:"signature",pol:{}},
{id:3688,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"No-flattery-for-peace giver",desc:"Refuses false comfort even to smooth over social tension.",example:"I won't say it was fine. It wasn't.",intensity:3,rarity:"signature",pol:{}},
{id:3689,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Plainly-stated-limits speaker",desc:"States personal boundaries honestly rather than through excuses.",example:"Not because I'm busy. Because I don't want to.",intensity:2,rarity:"signature",pol:{}},
{id:3690,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Half-answer specialist",desc:"Responds to questions with technically true, deeply incomplete answers.",example:"I was in town. (Doesn't mention where, specifically.)",intensity:3,rarity:"signature",pol:{}},
{id:3691,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Convenient-forgetting user",desc:"Selectively forgets details that would be inconvenient to recall.",example:"Don't remember agreeing to that, honestly.",intensity:3,rarity:"signature",pol:{}},
{id:3692,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Flattery-cover deceiver",desc:"Uses excessive praise to distract from an ongoing deception.",example:"You're so sharp, you'd have caught it anyway — anyway, moving on—",intensity:3,rarity:"signature",pol:{}},
{id:3693,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Fact-blur speaker",desc:"Deliberately mixes accurate and inaccurate details to obscure the truth.",example:"Some of that's right. Not all of it. Won't say which.",intensity:3,rarity:"signature",pol:{}},
{id:3694,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Denial-reflex liar",desc:"Denies even obviously true things as an automatic first response.",example:"Wasn't me. (It was, demonstrably, them.)",intensity:3,rarity:"common",pol:{}},
{id:3695,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Story-rehearsed deceiver",desc:"Delivers a well-practiced false account with total fluency.",example:"(the lie comes out smooth, unhesitating, well-worn)",intensity:4,rarity:"signature",pol:{}},
{id:3696,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Sympathy-bait deceiver",desc:"Fabricates a sob story specifically to avoid consequence.",example:"You don't understand what I've been through lately.",intensity:3,rarity:"signature",pol:{}},
{id:3697,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Silence-as-lie user",desc:"Lets false assumptions stand uncorrected because it benefits them.",example:"(says nothing, lets them believe the wrong thing)",intensity:3,rarity:"signature",pol:{}},
{id:3698,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Confidence-projecting liar",desc:"Delivers falsehoods more confidently than they deliver the truth.",example:"(the lie is stated with more certainty than any fact)",intensity:4,rarity:"signature",pol:{}},
{id:3699,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Redirection-under-pressure user",desc:"Changes the subject the instant a lie is at risk of exposure.",example:"Speaking of which — did you hear about the mill?",intensity:3,rarity:"common",pol:{}},
{id:3700,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Deniable-phrasing user",desc:"Constructs statements specifically to allow future denial.",example:"I never SAID I'd be there. I said I'd try.",intensity:3,rarity:"signature",pol:{}},
{id:3701,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Trust-exploiting deceiver",desc:"Uses previously earned trust specifically to enable a bigger lie.",example:"I've never lied to you before, so trust me on this one.",intensity:4,rarity:"signature",pol:{}},
{id:3702,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Vague-alibi builder",desc:"Constructs an intentionally imprecise account to avoid being disproven.",example:"Around then, somewhere near there, more or less.",intensity:3,rarity:"signature",pol:{}},
{id:3703,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Blame-transferring liar",desc:"Fabricates accounts that shift responsibility onto someone else.",example:"It wasn't me. It was him, actually. All him.",intensity:4,rarity:"signature",pol:{}},
{id:3704,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Emotion-masking deceiver",desc:"Uses a calm, unaffected demeanor to make a lie more convincing.",example:"(entirely unbothered expression, delivering the falsehood)",intensity:3,rarity:"signature",pol:{}},
{id:3705,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Selective-truth revealer",desc:"Reveals only the portion of the truth that serves them.",example:"I'll tell you part of it. The part that helps me.",intensity:3,rarity:"signature",pol:{}},
{id:3706,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Preemptive-denial giver",desc:"Denies wrongdoing before anyone's actually accused them of it.",example:"Before you ask — no, it wasn't me. Whatever it is.",intensity:3,rarity:"signature",pol:{}},
{id:3707,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Charm-cover liar",desc:"Uses charisma and likability to make deception harder to challenge.",example:"(smiles, disarms, delivers the lie easily)",intensity:3,rarity:"signature",pol:{}},
{id:3708,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Gradual-truth-shifter",desc:"Slowly alters their account over multiple retellings to suit them.",example:"(the story changes, bit by bit, each time it's told)",intensity:3,rarity:"signature",pol:{}},
{id:3709,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Cover-story coordinator",desc:"Arranges for others to corroborate a fabricated account.",example:"Just say you were with me. That's all you need to say.",intensity:4,rarity:"signature",pol:{}},
{id:3710,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Instant-boundary stater",desc:"States personal limits the moment they're relevant, without delay.",example:"That's not something I do. Simple as that.",intensity:2,rarity:"common",pol:{}},
{id:3711,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Cost-naming negotiator",desc:"States exactly what something will cost, without hedging.",example:"That'll cost you this. Take it or leave it.",intensity:2,rarity:"common",pol:{}},
{id:3712,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Room-commanding speaker",desc:"Naturally draws and holds attention when they choose to speak.",example:"(the room quiets the moment they begin)",intensity:3,rarity:"signature",pol:{}},
{id:3713,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Interruption-unbothered speaker",desc:"Continues stating their point calmly despite being interrupted.",example:"(keeps going, unbothered, through the interruption)",intensity:2,rarity:"signature",pol:{}},
{id:3714,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Direct-feedback giver",desc:"Delivers criticism straightforwardly, without excessive softening.",example:"That's not working. Here's what needs to change.",intensity:3,rarity:"common",pol:{}},
{id:3715,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Clear-refusal giver",desc:"Declines requests with an unambiguous, unhesitating no.",example:"No. I won't be doing that.",intensity:3,rarity:"common",pol:{}},
{id:3716,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Self-advocacy speaker",desc:"Speaks up for their own interests without waiting to be asked.",example:"I did the work. I should get the credit for it.",intensity:2,rarity:"signature",pol:{}},
{id:3717,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"No-hedge opinion stater",desc:"States opinions as plain fact rather than softened possibility.",example:"This is the right call. Not 'maybe' — the right call.",intensity:3,rarity:"signature",pol:{}},
{id:3718,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Immediate-objection raiser",desc:"Raises disagreement the instant it forms, without delay.",example:"Wait — no. I disagree with that entirely.",intensity:3,rarity:"common",pol:{}},
{id:3719,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Terms-first negotiator",desc:"States their conditions before any negotiation even begins.",example:"Here's what I need before we start talking.",intensity:2,rarity:"signature",pol:{}},
{id:3720,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Unapologetic-request maker",desc:"Asks for what they want without prefacing it with an apology.",example:"I want the raise. That's my ask.",intensity:2,rarity:"signature",pol:{}},
{id:3721,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Confrontation-comfortable speaker",desc:"Addresses conflict directly rather than avoiding it.",example:"Let's just talk about it. Directly. Now.",intensity:2,rarity:"signature",pol:{}},
{id:3722,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Firm-repeat enforcer",desc:"Repeats a stated boundary exactly when it's tested again.",example:"Said no already. Still no.",intensity:3,rarity:"common",pol:{}},
{id:3723,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Direct-question asker",desc:"Asks the most direct possible version of any hard question.",example:"Are you lying to me? Just tell me plainly.",intensity:3,rarity:"signature",pol:{}},
{id:3724,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Space-taking speaker",desc:"Occupies conversational space confidently, without shrinking.",example:"I'm not finished. Let me get through this.",intensity:2,rarity:"signature",pol:{}},
{id:3725,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Clear-expectation setter",desc:"States what they expect from others plainly and specifically.",example:"I need this by Friday, done properly. That's the expectation.",intensity:2,rarity:"signature",pol:{}},
{id:3726,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Correction-unafraid speaker",desc:"Corrects even authority figures without hesitation.",example:"With respect — that's incorrect. Here's why.",intensity:3,rarity:"signature",pol:{}},
{id:3727,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"No-apology decliner",desc:"Declines invitations or requests without an excessive apology attached.",example:"Can't make it. That's the answer.",intensity:2,rarity:"common",pol:{}},
{id:3728,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Value-stating speaker",desc:"States their own worth or contribution plainly, without false modesty.",example:"I'm good at this. It's just true.",intensity:2,rarity:"signature",pol:{}},
{id:3729,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Assertive-silence breaker",desc:"Speaks up specifically in situations where others default to silence.",example:"Somebody has to say it. I'll say it.",intensity:3,rarity:"signature",pol:{}},
{id:3730,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Wish-hinting speaker",desc:"Hints at wants rather than stating them plainly.",example:"It would be nice if someone helped, is all.",intensity:2,rarity:"common",pol:{}},
{id:3731,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Excessive-qualifier user",desc:"Softens every request with multiple unnecessary qualifiers.",example:"If it's not too much trouble, and only if you have time—",intensity:2,rarity:"common",pol:{}},
{id:3732,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Reluctant-opinion sharer",desc:"Only shares an opinion when directly, repeatedly pressed.",example:"I— well, if you really want to know—",intensity:2,rarity:"signature",pol:{}},
{id:3733,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Self-minimizing speaker",desc:"Downplays their own needs and contributions habitually.",example:"It's nothing, really. Anyone would've done it.",intensity:2,rarity:"common",pol:{}},
{id:3734,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Silent-boundary holder",desc:"Maintains internal limits but never voices them aloud.",example:"(quietly declines internally, says yes aloud)",intensity:3,rarity:"signature",pol:{}},
{id:3737,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Conflict-avoiding agreer",desc:"Agrees quickly to end any potential disagreement.",example:"You're right, you're right, let's just do that.",intensity:2,rarity:"common",pol:{}},
{id:3738,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Volume-dropping objector",desc:"Voice drops lower, not higher, the more strongly they disagree.",example:"(the more it matters, the quieter it gets)",intensity:3,rarity:"signature",pol:{}},
{id:3739,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Indirect-need communicator",desc:"Communicates needs through hints and implication rather than statement.",example:"I haven't eaten yet, is all I'll say.",intensity:2,rarity:"signature",pol:{}},
{id:3740,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Withdrawal-under-pressure speaker",desc:"Retreats from a stated position the moment it's challenged.",example:"Oh — well, maybe I'm wrong about that, then.",intensity:2,rarity:"common",pol:{}},
{id:3741,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Permission-waiting speaker",desc:"Waits for explicit invitation before contributing anything.",example:"Should I say something? Is it alright if I say something?",intensity:2,rarity:"signature",pol:{}},
{id:3742,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Grievance-suppressing speaker",desc:"Swallows complaints rather than voice them, repeatedly.",example:"Honestly, don't. I've got it. It's nothing.",intensity:3,rarity:"signature",pol:{}},
{id:3743,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Last-preference stater",desc:"States their preference only after everyone else has stated theirs.",example:"Whatever's left, I suppose. That's fine for me.",intensity:2,rarity:"common",pol:{}},
{id:3744,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Compliance-first responder",desc:"Says yes before fully considering whether they want to.",example:"Sure, of course, whatever you need from me.",intensity:2,rarity:"common",pol:{}},
{id:3745,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Unfinished-sentence retreater",desc:"Trails off mid-sentence rather than complete an assertive statement.",example:"I just think that maybe we should... never mind.",intensity:2,rarity:"signature",pol:{}},
{id:3746,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Approval-seeking asker",desc:"Frames statements as questions seeking permission or validation.",example:"Is it okay if I think that's not quite right?",intensity:2,rarity:"signature",pol:{}},
{id:3747,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Self-blame-first responder",desc:"Assumes fault before establishing what actually happened.",example:"That's probably my fault. I'm sure it's my fault.",intensity:3,rarity:"signature",pol:{}},
{id:3748,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Overly-accommodating scheduler",desc:"Rearranges their own plans repeatedly to avoid inconveniencing anyone.",example:"I can move things. Don't worry about my schedule at all.",intensity:2,rarity:"common",pol:{}},
{id:3749,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Quiet-dissent holder",desc:"Disagrees completely while outwardly appearing to go along.",example:"(nods, agrees aloud, disagrees entirely inside)",intensity:3,rarity:"signature",pol:{}},
{id:3750,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Steady-under-scrutiny presence",desc:"Remains calm and composed when closely watched or judged.",example:"(unbothered, entirely, by the attention)",intensity:2,rarity:"signature",pol:{}},
{id:3751,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-trusting decider",desc:"Makes decisions and trusts their own judgment without second-guessing.",example:"Decided. Moving forward. Don't need to relitigate it.",intensity:2,rarity:"common",pol:{}},
{id:3752,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Mistake-owning confident",desc:"Admits errors plainly without it denting their self-regard.",example:"Got that wrong. Fixing it now.",intensity:2,rarity:"common",pol:{}},
{id:3753,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Unimpressed-by-status presence",desc:"Treats people of high status the same as anyone else.",example:"Doesn't matter whose son he is. Same rules.",intensity:2,rarity:"signature",pol:{}},
{id:3754,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Quietly-capable presence",desc:"Demonstrates competence through action rather than announcement.",example:"(does the hard thing, says nothing about it after)",intensity:1,rarity:"signature",pol:{}},
{id:3755,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Criticism-absorbing confident",desc:"Takes criticism in, considers it, without feeling diminished by it.",example:"Fair point. I'll think about that.",intensity:2,rarity:"common",pol:{}},
{id:3756,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-amused confident",desc:"Can laugh genuinely at their own mistakes or awkwardness.",example:"(laughs, easily, at their own blunder)",intensity:1,rarity:"common",pol:{}},
{id:3757,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Grounded-under-pressure presence",desc:"Maintains their composure and sense of self during real crisis.",example:"(steady, even now, even here)",intensity:3,rarity:"signature",pol:{}},
{id:3758,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"No-need-for-validation speaker",desc:"Makes choices without seeking others' approval first.",example:"Didn't ask if it was a good idea. Just did it.",intensity:2,rarity:"signature",pol:{}},
{id:3759,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Comparison-immune confident",desc:"Genuinely doesn't measure their worth against others' success.",example:"Good for her. Doesn't change anything about my work.",intensity:2,rarity:"signature",pol:{}},
{id:3760,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Physically-settled confident",desc:"Occupies space calmly, without needing to prove anything physically.",example:"(stands easy, relaxed, taking exactly the space needed)",intensity:1,rarity:"signature",pol:{}},
{id:3761,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Clear-eyed self-assessor",desc:"Accurately, calmly evaluates their own strengths and limits.",example:"I'm good at this part. Not that part. Fair assessment.",intensity:2,rarity:"signature",pol:{}},
{id:3762,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Undefensive listener",desc:"Hears challenging feedback without becoming defensive.",example:"Go on. I want to actually hear this.",intensity:2,rarity:"common",pol:{}},
{id:3763,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Rejection-resilient confident",desc:"Doesn't collapse or spiral after being turned down or dismissed.",example:"Didn't work out. On to the next thing.",intensity:2,rarity:"signature",pol:{}},
{id:3764,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-possessed under mockery",desc:"Remains unbothered when mocked or teased publicly.",example:"(laughs along, genuinely, unthreatened)",intensity:2,rarity:"common",pol:{}},
{id:3765,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Decision-owning confident",desc:"Takes full ownership of choices, good or bad, without deflection.",example:"My call. My responsibility. All of it.",intensity:2,rarity:"signature",pol:{}},
{id:3766,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Comfortable-not-knowing presence",desc:"Admits ignorance without embarrassment or defensiveness.",example:"Don't know. Genuinely don't know. Can find out, though.",intensity:1,rarity:"common",pol:{}},
{id:3767,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Steady-eye-contact holder",desc:"Maintains natural, comfortable eye contact without needing to dominate it.",example:"(easy, steady eye contact, nothing forced about it)",intensity:1,rarity:"signature",pol:{}},
{id:3768,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Praise-graceful receiver",desc:"Accepts compliments simply, without deflecting or over-thanking.",example:"Thank you. I worked hard on it.",intensity:1,rarity:"common",pol:{}},
{id:3769,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Self-forgiving confident",desc:"Extends themselves the same grace they'd offer others after a mistake.",example:"Everyone messes up sometimes. Moving on from it.",intensity:2,rarity:"signature",pol:{}},
{id:3770,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Achievement-listing insecure",desc:"Recites past achievements unprompted to shore up self-worth.",example:"As I mentioned, I did win that competition, years back.",intensity:3,rarity:"signature",pol:{}},
{id:3771,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Silence-as-rejection interpreter",desc:"Reads any quiet or pause as evidence they're disliked.",example:"Nobody's saying anything. That means they hate it.",intensity:3,rarity:"signature",pol:{}},
{id:3772,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Constant-comparison sufferer",desc:"Measures their worth against everyone nearby, constantly.",example:"She's better at this than me. She's always better.",intensity:3,rarity:"signature",pol:{}},
{id:3773,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Overcorrecting bravado user",desc:"Masks genuine insecurity with loud, exaggerated confidence.",example:"Best there's ever been. No contest. None.",intensity:3,rarity:"signature",pol:{}},
{id:3774,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Fishing-for-reassurance asker",desc:"Steers conversations toward opportunities to be told they're fine.",example:"It was okay, right? You'd tell me if it wasn't?",intensity:2,rarity:"common",pol:{}},
{id:3775,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Never-admits-fault egotist",desc:"Cannot acknowledge error even when clearly, demonstrably wrong.",example:"Wasn't wrong. The situation was wrong.",intensity:4,rarity:"signature",pol:{}},
{id:3776,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Attention-redirecting insecure",desc:"Pulls focus back to themselves whenever it drifts elsewhere.",example:"That reminds me of MY story, actually—",intensity:3,rarity:"signature",pol:{}},
{id:3777,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Preemptive self-sabotage speaker",desc:"Undermines their own work verbally before anyone can criticize it.",example:"It's probably terrible, don't expect much.",intensity:2,rarity:"common",pol:{}},
{id:3779,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Superiority-asserting egotist",desc:"Frames disagreements as evidence of others' lesser understanding.",example:"I suppose that makes sense, if you haven't thought it through properly.",intensity:4,rarity:"signature",pol:{}},
{id:3780,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Approval-chasing insecure",desc:"Visibly seeks validation after nearly every action taken.",example:"Was that good? Tell me that was good.",intensity:3,rarity:"common",pol:{}},
{id:3781,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Credential-flashing egotist",desc:"Works past accomplishments into unrelated conversations frequently.",example:"As someone who's trained under the very best, I'd say—",intensity:3,rarity:"signature",pol:{}},
{id:3782,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Rejection-catastrophizing insecure",desc:"Treats minor social slights as total, permanent condemnation.",example:"He read it and didn't reply. So that's that, isn't it. That's the end of that.",intensity:3,rarity:"signature",pol:{}},
{id:3783,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Self-deprecation-fishing insecure",desc:"Insults themselves specifically to be contradicted and reassured.",example:"I'm useless at this, obviously.",intensity:2,rarity:"common",pol:{}},
{id:3784,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Grandiosity-defaulting egotist",desc:"Describes their own abilities in exaggerated, inflated terms by default.",example:"Nobody in this town could do what I've done.",intensity:4,rarity:"signature",pol:{}},
{id:3785,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Vanity-preoccupied insecure",desc:"Fixates on how they're being perceived, physically and socially.",example:"Is it the light in here, or is it me? Be honest. It's me.",intensity:2,rarity:"common",pol:{}},
{id:3786,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Never-satisfied achiever",desc:"Cannot feel good about accomplishments, always finding the flaw.",example:"Fine, I guess. Could've been better, though.",intensity:3,rarity:"signature",pol:{}},
{id:3787,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Silence-filling insecure talker",desc:"Fills any quiet moment out of fear it signals disapproval.",example:"Sorry — is this boring? Should I stop talking?",intensity:2,rarity:"signature",pol:{}},
{id:3788,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Defensive-under-mild-critique",desc:"Becomes sharply defensive at even gentle, constructive feedback.",example:"That's not fair. I did everything right.",intensity:3,rarity:"signature",pol:{}},
{id:3789,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Public-praise craving egotist",desc:"Visibly seeks credit and recognition in group settings.",example:"I did do most of the actual work, just saying.",intensity:3,rarity:"signature",pol:{}},
{id:3790,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Meeting-halfway proposer",desc:"Regularly offers middle-ground compromises to resolve tension.",example:"What if we split it down the middle?",intensity:2,rarity:"common",pol:{}},
{id:3791,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Preference-suppressing accommodator",desc:"Buries their own wants to avoid inconveniencing others.",example:"Whatever's easiest for everyone. I really don't mind.",intensity:2,rarity:"common",pol:{}},
{id:3792,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Harmony-prioritizing accommodator",desc:"Values group cohesion over being personally right.",example:"I don't need to win it. I need us out of this room still speaking.",intensity:2,rarity:"signature",pol:{}},
{id:3793,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Gentle-pushback accommodator",desc:"Voices disagreement so softly it's barely noticeable.",example:"I wonder if maybe — just maybe — that's not quite right.",intensity:1,rarity:"common",pol:{}},
{id:3794,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Quick-to-apologize accommodator",desc:"Apologizes readily, even for things not clearly their fault.",example:"Sorry — my fault, probably. Let's fix it.",intensity:2,rarity:"common",pol:{}},
{id:3795,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Effort-matching accommodator",desc:"Adjusts their own effort to match whatever the group is doing.",example:"Whatever pace works for everyone else works for me.",intensity:1,rarity:"signature",pol:{}},
{id:3796,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Last-choice accepting accommodator",desc:"Consistently takes whatever's left over without complaint.",example:"I'll take what's left. Really, it's fine.",intensity:2,rarity:"common",pol:{}},
{id:3797,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Praise-redirecting accommodator",desc:"Sends credit toward others rather than claim it themselves.",example:"Wasn't just me. Everyone contributed to that.",intensity:2,rarity:"common",pol:{}},
{id:3798,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Tension-smoothing accommodator",desc:"Steps in quickly to defuse friction between others.",example:"Come on, we're not doing this tonight.",intensity:2,rarity:"signature",pol:{}},
{id:3799,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Group-first decision accommodator",desc:"Prioritizes what's best for the group over personal preference.",example:"Not what I'd choose. What's best for everyone, though.",intensity:2,rarity:"signature",pol:{}},
{id:3800,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Quick-forgiveness accommodator",desc:"Releases grievances readily rather than hold onto resentment.",example:"It's done. Not carrying that around.",intensity:2,rarity:"common",pol:{}},
{id:3801,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Volunteer-first accommodator",desc:"Steps up for unwanted tasks before being asked.",example:"I'll do it. Someone has to.",intensity:2,rarity:"common",pol:{}},
{id:3802,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Others-first scheduler",desc:"Rearranges their own plans readily to suit others' needs.",example:"I can shift things. Don't worry about my schedule.",intensity:2,rarity:"common",pol:{}},
{id:3804,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Consensus-seeking accommodator",desc:"Works actively to find agreement everyone can accept.",example:"What if we did a bit of both? Would that work?",intensity:2,rarity:"signature",pol:{}},
{id:3805,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Self-effacing accommodator",desc:"Downplays their own contribution to keep the peace.",example:"Wasn't much, really. Anyone could've done it.",intensity:1,rarity:"common",pol:{}},
{id:3807,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Gentle-request accommodator",desc:"Frames even reasonable requests as small, apologetic favors.",example:"If it's not too much trouble, could you possibly—",intensity:2,rarity:"signature",pol:{}},
{id:3808,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Adaptive-mood accommodator",desc:"Adjusts their own emotional tone to match the room.",example:"(reads the mood, softens or brightens to match it)",intensity:1,rarity:"signature",pol:{}},
{id:3809,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Quiet-sacrifice accommodator",desc:"Makes real personal sacrifices for others without mentioning it.",example:"(gave up the better seat, said nothing about it)",intensity:2,rarity:"signature",pol:{}},
{id:3819,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Superiority-implying contrarian",desc:"Frames disagreement as evidence of the other's lesser understanding.",example:"I suppose that makes sense, if you haven't really thought about it.",intensity:4,rarity:"signature",pol:{}},
{id:3820,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Correction-compulsive contrarian",desc:"Cannot let even minor factual errors go uncorrected.",example:"Actually, it was Thursday, not Wednesday.",intensity:2,rarity:"common",pol:{}},
{id:3821,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Argument-for-sport contrarian",desc:"Genuinely enjoys debate for its own sake, regardless of stakes.",example:"Come on, let's really go at this one.",intensity:2,rarity:"signature",pol:{}},
{id:3822,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Skeptical-by-default contrarian",desc:"Doubts new claims until independently, personally verified.",example:"I'll believe it when I see it myself.",intensity:2,rarity:"common",pol:{}},
{id:3823,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Rule-questioning contrarian",desc:"Challenges established procedures on principle, regularly.",example:"Why do we even do it this way?",intensity:2,rarity:"signature",pol:{}},
{id:3824,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Confrontation-comfortable contrarian",desc:"Doesn't shy from open disagreement, even with authority.",example:"With respect, sir, that's simply wrong.",intensity:3,rarity:"signature",pol:{}},
{id:3827,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Praise-resistant contrarian",desc:"Finds fault even in things generally agreed to be good.",example:"Sure, it's fine. Overrated, though, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:3828,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Interruption-prone contrarian",desc:"Cuts in specifically to disagree before a point is finished.",example:"—no, wait, that's not right at all—",intensity:3,rarity:"common",pol:{}},
{id:3829,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Provoke-to-clarify contrarian",desc:"Deliberately overstates disagreement to force real clarity.",example:"Let's say you're completely wrong. Convince me otherwise.",intensity:2,rarity:"signature",pol:{}},
{id:3830,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Elder-deferring speaker",desc:"Shows consistent, deliberate respect toward older people.",example:"After you, sir. Age before all else.",intensity:1,rarity:"common",pol:{}},
{id:3831,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Grateful-note sender",desc:"Follows kindness with genuine, specific expressions of thanks.",example:"I wanted to say properly — thank you for that.",intensity:1,rarity:"common",pol:{}},
{id:3832,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Formal-request phraser",desc:"Frames even small requests with proper, courteous phrasing.",example:"Might I trouble you for a moment of your time?",intensity:2,rarity:"signature",pol:{}},
{id:3833,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Guest-comfort prioritizer",desc:"Puts visitors' comfort ahead of their own, consistently.",example:"Please, take the good chair. I'm fine here.",intensity:1,rarity:"common",pol:{}},
{id:3834,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Punctual-respect keeper",desc:"Arrives precisely on time as a mark of respect for others.",example:"Said three. It's three. Shall we begin?",intensity:1,rarity:"signature",pol:{}},
{id:3835,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Gracious-loser",desc:"Accepts defeat or being wrong with genuine, unforced grace.",example:"Well played. You earned that one fairly.",intensity:1,rarity:"common",pol:{}},
{id:3836,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Interruption-avoider",desc:"Waits patiently, never cutting others off mid-sentence.",example:"(waits, fully, until they've finished speaking)",intensity:1,rarity:"common",pol:{}},
{id:3837,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Table-manner exemplar",desc:"Maintains careful, correct etiquette at every meal.",example:"(napkin in lap, waits for all to be served, first)",intensity:1,rarity:"signature",pol:{}},
{id:3838,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Proper-introduction giver",desc:"Always formally introduces people who haven't met.",example:"Have you two met? Allow me the pleasure.",intensity:1,rarity:"common",pol:{}},
{id:3839,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Compliment-graceful accepter",desc:"Receives praise with simple, genuine thanks, no deflection.",example:"Thank you. That means a great deal.",intensity:1,rarity:"common",pol:{}},
{id:3840,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Door-holding habitual",desc:"Reliably holds doors for anyone nearby, without exception.",example:"(holds it for the man forty feet away, and waits)",intensity:1,rarity:"common",pol:{}},
{id:3841,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Formal-farewell giver",desc:"Never leaves without a proper, individual goodbye to each person.",example:"(makes a point of a real goodbye to everyone present)",intensity:1,rarity:"signature",pol:{}},
{id:3842,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Considerate-volume keeper",desc:"Adjusts their volume thoughtfully for the setting and company.",example:"(lowers their voice, automatically, in a quiet room)",intensity:1,rarity:"common",pol:{}},
{id:3844,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Respectful-disagreement framer",desc:"Voices disagreement while maintaining full courtesy.",example:"With respect, I see it rather differently.",intensity:2,rarity:"signature",pol:{}},
{id:3845,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Host-anticipation giver",desc:"Anticipates guests' needs before they're voiced.",example:"(refills the glass before it's even empty)",intensity:1,rarity:"signature",pol:{}},
{id:3847,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Modest-praise receiver",desc:"Accepts compliments graciously without excessive self-deprecation or bragging.",example:"Kind of you to say. I did work hard on it.",intensity:1,rarity:"common",pol:{}},
{id:3848,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Correction-gentle giver",desc:"Corrects others' mistakes as gently and privately as possible.",example:"(quietly, aside) I think that figure's off, actually.",intensity:1,rarity:"signature",pol:{}},
{id:3849,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Warm-formality blender",desc:"Combines genuine warmth with careful, proper etiquette seamlessly.",example:"So very glad you could come. Please, make yourself at home.",intensity:1,rarity:"signature",pol:{}},
{id:3850,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Interruption-oblivious speaker",desc:"Talks over others without any awareness it's rude.",example:"—no wait, MY point is—",intensity:3,rarity:"common",pol:{}},
{id:3853,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Compliment-refusing bluntly",desc:"Rejects kind gestures without any softening.",example:"Don't need it. Keep it.",intensity:2,rarity:"signature",pol:{}},
{id:3856,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Never-says-please speaker",desc:"Issues requests as flat demands, never softened.",example:"Salt.",intensity:2,rarity:"common",pol:{}},
{id:3857,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Gift-critiquing rude",desc:"Comments negatively on gifts rather than thanking the giver.",example:"Interesting. Not what I'd have picked.",intensity:3,rarity:"signature",pol:{}},
{id:3858,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Bodily-noise unapologetic",desc:"Makes no effort to suppress or excuse bodily sounds.",example:"(makes the noise, carries on with the sentence)",intensity:2,rarity:"signature",pol:{}},
{id:3860,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Late-without-apology arriver",desc:"Shows up late repeatedly without any acknowledgment.",example:"(walks in twenty minutes late, says nothing about it)",intensity:2,rarity:"common",pol:{}},
{id:3861,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Name-forgetting rude",desc:"Doesn't bother remembering or using people's names.",example:"You. The tall one. Come here.",intensity:2,rarity:"signature",pol:{}},
{id:3862,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Dismissive-wave giver",desc:"Waves off others' concerns without engaging with them.",example:"(a flick of the hand, no further response)",intensity:2,rarity:"signature",pol:{}},
{id:3863,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Crude-joke teller",desc:"Tells inappropriate jokes regardless of company or setting.",example:"Now here's one you shouldn't tell in front of the vicar—",intensity:3,rarity:"signature",pol:{}},
{id:3864,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Personal-space invader",desc:"Stands too close without registering others' discomfort.",example:"(stands well inside anyone's comfortable distance)",intensity:2,rarity:"signature",pol:{}},
{id:3865,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Blunt-appearance commenter",desc:"Comments on people's looks without tact or invitation.",example:"You've put on weight, haven't you.",intensity:3,rarity:"signature",pol:{}},
{id:3866,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Interrupting-question asker",desc:"Asks their next question before hearing the current answer.",example:"Yeah yeah, but ALSO — what about the money?",intensity:2,rarity:"common",pol:{}},
{id:3867,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Loud-phone-user",desc:"Conducts personal conversations loudly in shared, quiet spaces.",example:"(carries on a loud call in the middle of the library)",intensity:2,rarity:"signature",pol:{}},
{id:3868,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Credit-taking rude",desc:"Claims credit for others' work without acknowledgment.",example:"Yeah, I did that. (Someone else clearly did.)",intensity:3,rarity:"signature",pol:{}},
{id:3869,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Complaint-without-tact giver",desc:"Voices dissatisfaction bluntly, regardless of who might be hurt.",example:"This food's terrible. Who made this?",intensity:2,rarity:"common",pol:{}},
{id:3870,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Fixed-routine keeper",desc:"Maintains the exact same daily structure regardless of circumstance.",example:"Half six. Kettle, window, radio. Every day of my life.",intensity:2,rarity:"common",pol:{}},
{id:3871,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Emotion-scheduling discipliner",desc:"Deliberately postpones processing feelings until an appropriate moment.",example:"Not now. Dealing with that properly, tonight.",intensity:2,rarity:"signature",pol:{}},
{id:3872,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Standard-maintaining discipliner",desc:"Refuses to lower quality even under time pressure.",example:"Rushed or not, still has to be done right.",intensity:3,rarity:"signature",pol:{}},
{id:3876,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Anger-contained discipliner",desc:"Feels strong anger but never lets it dictate action.",example:"(furious, visibly, still speaks with total control)",intensity:3,rarity:"signature",pol:{}},
{id:3878,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Goal-tracking discipliner",desc:"Regularly checks progress against stated goals, adjusts as needed.",example:"Behind schedule. Adjusting accordingly.",intensity:2,rarity:"signature",pol:{}},
{id:3881,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Early-riser discipliner",desc:"Rises at the same early hour without exception, ever.",example:"Up at five. Every day, thirty years now.",intensity:2,rarity:"common",pol:{}},
{id:3882,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Financial-discipline keeper",desc:"Sticks strictly to budgets and spending limits, without exception.",example:"Not in the budget. Not buying it.",intensity:2,rarity:"signature",pol:{}},
{id:3883,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Physical-training discipliner",desc:"Maintains a punishing exercise regimen without fail.",example:"Two hours before anyone's awake. Every morning.",intensity:3,rarity:"signature",pol:{}},
{id:3884,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Impulse-delaying discipliner",desc:"Deliberately waits before acting on strong urges.",example:"Want to say something. Waiting a beat first.",intensity:2,rarity:"signature",pol:{}},
{id:3885,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Consequence-weighing discipliner",desc:"Thinks through outcomes carefully before acting, every time.",example:"Before I do this, let's think through where it leads.",intensity:2,rarity:"signature",pol:{}},
{id:3886,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Silence-practicing discipliner",desc:"Observes deliberate periods of restraint from speaking.",example:"(will not speak before the appointed hour, ever)",intensity:2,rarity:"signature",pol:{}},
{id:3887,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Task-completion insister",desc:"Refuses to leave anything genuinely unfinished.",example:"Not stopping till it's actually done.",intensity:2,rarity:"common",pol:{}},
{id:3888,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Emotion-regulated discipliner",desc:"Manages strong feelings without letting them derail action.",example:"Feeling it. Not letting it drive the decision, though.",intensity:3,rarity:"signature",pol:{}},
{id:3889,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Structure-loving discipliner",desc:"Finds genuine comfort and stability in maintained routine.",example:"The routine's the only reason I'm still standing.",intensity:2,rarity:"signature",pol:{}},
{id:3900,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Distraction-prone undisciplined",desc:"Loses focus easily, jumps between tasks constantly.",example:"Wait, what were we — oh right, and also this—",intensity:2,rarity:"common",pol:{}},
{id:3902,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Overcommitting undisciplined",desc:"Says yes to more than they can possibly manage.",example:"Yes — yes — absolutely, put me down for that as well.",intensity:3,rarity:"signature",pol:{}},
{id:3904,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Sleep-schedule chaotic",desc:"Maintains no consistent sleep pattern whatsoever.",example:"Slept at some point. Not sure when, exactly.",intensity:2,rarity:"signature",pol:{}},
{id:3905,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Rule-bending undisciplined",desc:"Treats structure as optional whenever it's inconvenient.",example:"There's a rule and there's a reason for the rule, and neither's here tonight.",intensity:2,rarity:"common",pol:{}},
{id:3907,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Follow-through-lacking undisciplined",desc:"Enthusiastically starts things, rarely sees them through.",example:"Great idea! (Never happens.)",intensity:2,rarity:"signature",pol:{}},
{id:3908,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Impulse-purchase undisciplined",desc:"Buys things on a whim, regularly, without planning.",example:"Bought a horse. Don't need a horse.",intensity:3,rarity:"signature",pol:{}},
{id:3909,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Present-moment-only undisciplined",desc:"Acts entirely based on immediate feeling, ignoring future impact.",example:"Feels right now. That's all that matters right now.",intensity:2,rarity:"signature",pol:{}},
{id:3910,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Public-dissent voicer",desc:"Voices disagreement with authority openly and without hesitation.",example:"No. And you can minute that.",intensity:4,rarity:"common",pol:{}},
{id:3915,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Institution-distrusting defiant",desc:"Assumes official systems work against ordinary people by default.",example:"Of course the report says that. Who wrote it?",intensity:3,rarity:"signature",pol:{}},
{id:3918,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Tradition-dismissing defiant",desc:"Rejects 'the way it's always been done' as valid reasoning.",example:"'Always been' isn't an argument.",intensity:2,rarity:"signature",pol:{}},
{id:3920,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Loud-refusal defiant",desc:"States refusal of authority plainly, without softening.",example:"No. I won't. That's my answer.",intensity:3,rarity:"common",pol:{}},
{id:3926,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Martyr-willing defiant",desc:"Accepts punishment rather than comply with an unjust order.",example:"Lock me up, then. I'll say it again from in there.",intensity:4,rarity:"signature",pol:{}},
{id:3931,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Chain-of-command deferrer",desc:"Always defers decisions to whoever ranks above them.",example:"Above my level. Take it upstairs.",intensity:2,rarity:"common",pol:{}},
{id:3932,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Precedent-following conformist",desc:"Chooses the established, proven method over anything new.",example:"We've always done it this way. Let's keep it that way.",intensity:2,rarity:"signature",pol:{}},
{id:3944,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Uniform-comfort seeker conformist",desc:"Finds real comfort in shared dress codes and group conventions.",example:"Feels right, everyone matching, everyone together.",intensity:1,rarity:"signature",pol:{}},
{id:3945,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Deferential-to-elders conformist",desc:"Consistently defers to older or more senior members of a group.",example:"If they say so, that settles it for me.",intensity:2,rarity:"signature",pol:{}},
{id:3946,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Bureaucracy-trusting conformist",desc:"Believes formal processes exist for legitimate, good reasons.",example:"There's a form for this. Let's fill it out properly.",intensity:2,rarity:"signature",pol:{}},
{id:3947,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Group-loyalty conformist",desc:"Aligns with the group's stated position even when privately unsure.",example:"If that's what we've decided, that's what we've decided.",intensity:2,rarity:"signature",pol:{}},
{id:3948,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Rule-enforcing conformist",desc:"Actively holds others to the same standards they follow themselves.",example:"That's not how it's done. Do it properly.",intensity:3,rarity:"signature",pol:{}},
{id:3949,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Status-quo-preferring conformist",desc:"Genuinely prefers keeping things as they are over any change.",example:"Works fine as it is. Why fix what isn't broken?",intensity:2,rarity:"signature",pol:{}},
{id:3952,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Feeling-precisely-named expresser",desc:"Identifies and articulates their emotional state with real precision.",example:"That's not fury. That's fear with its coat on.",intensity:3,rarity:"signature",pol:{}},
{id:3960,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Openly-affectionate expresser",desc:"Expresses fondness verbally, often and without hesitation.",example:"Love you. Just wanted to say it out loud again.",intensity:2,rarity:"common",pol:{}},
{id:3961,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Empathic-mirror expresser",desc:"Visibly reflects others' emotional states back to them.",example:"(their face falls the instant the bad news lands)",intensity:2,rarity:"signature",pol:{}},
{id:3962,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Sorrow-articulate expresser",desc:"Describes grief with unusual precision and depth.",example:"It's not one feeling. It's grief, and relief, and guilt, all at once.",intensity:3,rarity:"signature",pol:{}},
{id:3963,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Passion-visible expresser",desc:"Cannot hide genuine enthusiasm, it shows in voice and face immediately.",example:"(practically vibrating with excitement) You have to hear this.",intensity:2,rarity:"common",pol:{}},
{id:3964,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Comfort-offering expresser",desc:"Actively, physically comforts others in visible distress.",example:"(sits close, offers a hand, doesn't rush them)",intensity:2,rarity:"common",pol:{}},
{id:3965,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Deep-feeling namer expressive",desc:"Names complex, layered emotions rather than simplifying them.",example:"It's not just sad. It's the specific sadness of things ending too soon.",intensity:3,rarity:"signature",pol:{}},
{id:3966,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Emotional-memory keeper expressive",desc:"Recalls and discusses past emotional experiences vividly.",example:"I still remember exactly how that felt. Every bit of it.",intensity:2,rarity:"signature",pol:{}},
{id:3967,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Unfiltered-reaction expresser",desc:"Reacts to news with immediate, visible, honest emotion.",example:"(face falls, immediately, no attempt to hide it)",intensity:2,rarity:"common",pol:{}},
{id:3968,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Warmth-radiating expresser",desc:"Emotional warmth is visible and constant, not just situational.",example:"(a steady, visible warmth, in nearly every interaction)",intensity:1,rarity:"signature",pol:{}},
{id:3969,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Compassion-acting expressive",desc:"Turns strong feeling immediately into caring action.",example:"Can't just feel bad about it. Doing something about it.",intensity:2,rarity:"signature",pol:{}},
{id:3980,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Emotional-distance keeper guarded",desc:"Maintains consistent distance from any real emotional exchange.",example:"Let's keep this practical, if you don't mind.",intensity:2,rarity:"signature",pol:{}},
{id:3981,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Feeling-postponing guarded",desc:"Consistently defers processing any strong emotion.",example:"Not the time for that. Later, maybe.",intensity:2,rarity:"common",pol:{}},
{id:3982,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Stoic-mask wearer guarded",desc:"Wears a controlled, unaffected expression regardless of internal state.",example:"(face gives away nothing, deliberately)",intensity:3,rarity:"signature",pol:{}},
{id:3983,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Grief-avoiding guarded",desc:"Changes the subject the instant loss or sorrow comes up.",example:"Anyway — did you sort the horses?",intensity:2,rarity:"common",pol:{}},
{id:3984,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Emotion-minimizing guarded",desc:"Consistently downplays the size or importance of their own feelings.",example:"It's nothing. Barely worth mentioning.",intensity:2,rarity:"common",pol:{}},
{id:3985,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Detached-empathy guarded",desc:"Understands others' pain intellectually without feeling it themselves.",example:"I understand why that would hurt. I don't feel it, though.",intensity:3,rarity:"signature",pol:{}},
{id:3986,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Silence-over-sharing guarded",desc:"Chooses to say nothing rather than reveal an emotional state.",example:"(says nothing at all, lets the moment pass)",intensity:2,rarity:"signature",pol:{}},
{id:3987,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Performance-of-fine guarded",desc:"Maintains a convincing appearance of being fine regardless of reality.",example:"(smiles, steady, entirely unreadable underneath)",intensity:3,rarity:"signature",pol:{}},
{id:3988,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Feeling-word-avoiding guarded",desc:"Systematically avoids naming specific emotions in conversation.",example:"It was a lot. That's all I'll say.",intensity:2,rarity:"signature",pol:{}},
{id:3989,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Closed-question responder guarded",desc:"Answers emotional questions with the shortest possible reply.",example:"Fine.",intensity:2,rarity:"common",pol:{}},
{id:4000,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Structural-weakness spotter",desc:"Identifies the fragile point in any plan before it fails.",example:"This whole thing hinges on him showing up. Risky.",intensity:3,rarity:"signature",pol:{}},
{id:4001,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Layered-motive reader",desc:"Sees multiple, sometimes conflicting motives behind actions.",example:"He wants to help. He also wants credit. Both true.",intensity:2,rarity:"signature",pol:{}},
{id:4002,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Efficient-path finder",desc:"Consistently identifies the most direct route to a goal.",example:"Skip that step entirely. Straight to this instead.",intensity:2,rarity:"signature",pol:{}},
{id:4003,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Fast-synthesis analyst",desc:"Combines scattered information into a coherent picture quickly.",example:"So: he lied, she covered, and the ledger's wrong. All connected.",intensity:3,rarity:"signature",pol:{}},
{id:4004,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Precedent-applying sharp",desc:"Draws useful comparisons from past situations to inform current ones.",example:"This is exactly like the Harrow business. We know how that went.",intensity:2,rarity:"signature",pol:{}},
{id:4005,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Risk-modeling sharp",desc:"Calculates likely outcomes and their probabilities before acting.",example:"Sixty percent this works. Worth the risk.",intensity:2,rarity:"signature",pol:{}},
{id:4006,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Question-behind-question sharp",desc:"Identifies the real concern hiding beneath a stated question.",example:"You're not really asking about the money, are you.",intensity:3,rarity:"signature",pol:{}},
{id:4007,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Systems-thinking sharp",desc:"Sees how one change ripples through an entire interconnected system.",example:"Close the eastern gate and you'll starve the market by Friday.",intensity:3,rarity:"signature",pol:{}},
{id:4009,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Precision-reasoning sharp",desc:"Builds arguments carefully, exposing flawed logic quickly.",example:"You've smuggled the conclusion into the second sentence.",intensity:3,rarity:"signature",pol:{}},
{id:4020,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Body-memory instinctive",desc:"Knows how to do things without being able to explain how.",example:"My hands just know. Can't explain it beyond that.",intensity:2,rarity:"signature",pol:{}},
{id:4021,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Practical-over-theoretical instinctive",desc:"Consistently favors hands-on solutions over abstract planning.",example:"All that's clever. Does it get the door open, though?",intensity:2,rarity:"signature",pol:{}},
{id:4023,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Direct-action instinctive",desc:"Skips deliberation entirely, moves straight to doing.",example:"Enough talk. Doing it now.",intensity:2,rarity:"common",pol:{}},
{id:4024,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Common-sense instinctive",desc:"Relies on unexamined, practical wisdom over formal logic.",example:"That's just common sense, isn't it?",intensity:2,rarity:"common",pol:{}},
{id:4025,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Immediate-reaction instinctive",desc:"Responds to situations without pausing to analyze first.",example:"(already moving before fully processing what happened)",intensity:2,rarity:"signature",pol:{}},
{id:4026,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Un-self-conscious instinctive",desc:"Acts naturally without overanalyzing their own behavior.",example:"Just did what felt right. Didn't overthink it.",intensity:1,rarity:"signature",pol:{}},
{id:4027,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Skill-over-explanation instinctive",desc:"Can perform a task expertly without being able to teach it verbally.",example:"Can't tell you how. Just watch, I'll show you.",intensity:2,rarity:"signature",pol:{}},
{id:4029,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Reflex-decision instinctive",desc:"Makes fast decisions in the moment without much deliberation.",example:"Didn't think. Just acted. Turned out fine.",intensity:2,rarity:"signature",pol:{}},
{id:4040,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Trust-extending optimist",desc:"Believes new people deserve the benefit of the doubt.",example:"I'll trust him. He hasn't given me a reason not to yet.",intensity:2,rarity:"signature",pol:{}},
{id:4041,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Celebration-quick optimist",desc:"Finds genuine cause for celebration in small wins.",example:"We got it done! Even if it took forever, we got it done!",intensity:2,rarity:"common",pol:{}},
{id:4042,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Perseverance-preaching optimist",desc:"Encourages continued effort with genuine belief it'll pay off.",example:"Keep at it. It's going to work out.",intensity:2,rarity:"common",pol:{}},
{id:4043,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Bright-side-finding optimist",desc:"Reflexively reframes bad news toward something workable.",example:"Could've been worse. At least we know now.",intensity:2,rarity:"common",pol:{}},
{id:4044,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Hope-anchored optimist",desc:"Explicitly names hope as their operating principle.",example:"I keep going because I believe it gets better.",intensity:2,rarity:"signature",pol:{}},
{id:4046,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Kindness-assuming optimist",desc:"Assumes good intent behind others' actions by default.",example:"He probably didn't mean it that way.",intensity:1,rarity:"signature",pol:{}},
{id:4047,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Recovery-quick optimist",desc:"Moves past setbacks faster than most, without dwelling.",example:"That's done. Onward.",intensity:2,rarity:"signature",pol:{}},
{id:4049,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Second-chance-believing optimist",desc:"Genuinely believes people can change and improve.",example:"He's not the same man he was. People do change.",intensity:2,rarity:"signature",pol:{}},
{id:4060,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Grim-forecast pessimist",desc:"Names the worst-case scenario out loud, reflexively, always.",example:"And when the bridge is watched? What then?",intensity:3,rarity:"signature",pol:{}},
{id:4061,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Disillusioned-veteran pessimist",desc:"Has watched hope fail enough times to distrust it entirely.",example:"Used to think it mattered. I was younger.",intensity:3,rarity:"signature",pol:{}},
{id:4062,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Suspicious-of-luck pessimist",desc:"Distrusts good fortune, expects it to reverse imminently.",example:"Too good. Something's going to go wrong now.",intensity:3,rarity:"signature",pol:{}},
{id:4063,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Effort-doubting pessimist",desc:"Questions whether hard work will actually change the outcome.",example:"Could try harder. Wouldn't change the ending, though.",intensity:3,rarity:"signature",pol:{}},
{id:4064,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Bitter-experience pessimist",desc:"Filters new situations through a specific past betrayal.",example:"Trusted the wrong shape of person once. Won't again.",intensity:3,rarity:"signature",pol:{}},
{id:4066,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Skeptical-of-kindness pessimist",desc:"Assumes generosity conceals a hidden cost.",example:"What's the catch? There's always a catch.",intensity:3,rarity:"signature",pol:{}},
{id:4068,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Preemptive-mourning pessimist",desc:"Grieves losses before they've actually happened.",example:"Already mourning this before it's even gone.",intensity:3,rarity:"signature",pol:{}},
{id:4069,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Contrarian-hope pessimist",desc:"Argues against hope specifically when others express it.",example:"Don't say that. Don't jinx it by hoping.",intensity:2,rarity:"signature",pol:{}},
{id:4079,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Constant-motion active",desc:"Rarely settles into complete stillness even when relaxed.",example:"(always doing something with the hands, even at rest)",intensity:2,rarity:"signature",pol:{}},
{id:4080,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Adventure-first active",desc:"Chooses the more physically demanding path, on principle.",example:"There's a shortcut. It's also a cliff. Let's take it.",intensity:3,rarity:"signature",pol:{}},
{id:4081,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Kinetic-fidgeter active",desc:"Needs some form of physical motion to think clearly.",example:"Can't sit still and figure this out. Walk with me.",intensity:2,rarity:"signature",pol:{}},
{id:4082,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Chore-anticipating active",desc:"Starts the next task before finishing the current one.",example:"Already thinking about tomorrow's list.",intensity:2,rarity:"signature",pol:{}},
{id:4083,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Restless-traveler active",desc:"Grows uneasy staying in one place too long.",example:"Been here a week. Getting itchy feet.",intensity:2,rarity:"signature",pol:{}},
{id:4084,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Physical-stress-reliever active",desc:"Uses exertion specifically to manage stress or frustration.",example:"Need to hit something. Not you. Just — something.",intensity:2,rarity:"signature",pol:{}},
{id:4085,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Dawn-to-dusk active",desc:"Fills the entire waking day with constant activity.",example:"Bed's overrated after the first three hours.",intensity:3,rarity:"common",pol:{}},
{id:4086,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Fast-walker active",desc:"Moves noticeably faster than most people around them.",example:"(everyone else is half a step behind, always)",intensity:1,rarity:"signature",pol:{}},
{id:4087,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Multi-tasking active",desc:"Handles several physical tasks simultaneously without difficulty.",example:"(talking, whittling, watching the door, all at once)",intensity:2,rarity:"signature",pol:{}},
{id:4088,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Never-idle active",desc:"Cannot tolerate being genuinely unoccupied for long.",example:"Give me something to do. Anything.",intensity:2,rarity:"common",pol:{}},
{id:4089,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Early-to-volunteer active",desc:"Consistently the first to offer for any physical undertaking.",example:"I'll go first. Someone's got to.",intensity:2,rarity:"common",pol:{}},
{id:4093,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Indoor-preferring low-energy",desc:"Chooses indoor, low-exertion settings whenever there's a choice.",example:"Bit cold out. Let's stay in.",intensity:2,rarity:"common",pol:{}},
{id:4100,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Task-avoidant low-energy",desc:"Finds reasons to postpone physically demanding chores.",example:"Could do it now. Could also do it never.",intensity:2,rarity:"signature",pol:{}},
{id:4101,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Long-recovery low-energy",desc:"Needs unusually long rest periods after exertion.",example:"Need the whole afternoon just to recover from that.",intensity:2,rarity:"signature",pol:{}},
{id:4102,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Homebody low-energy",desc:"Genuinely prefers staying in over going out, always.",example:"Send my apologies. I've got a chair and a lamp and no complaints.",intensity:2,rarity:"common",pol:{}},
{id:4103,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Comfortable-stillness low-energy",desc:"Finds real contentment in being genuinely, fully still.",example:"(perfectly content, doing absolutely nothing)",intensity:1,rarity:"signature",pol:{}},
{id:4104,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Slow-mover low-energy",desc:"Physically moves noticeably slower than average, unhurried.",example:"(never quite catches up, never seems to mind)",intensity:2,rarity:"signature",pol:{}},
{id:4105,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Effort-avoidant low-energy",desc:"Structures the day specifically to minimize physical demand.",example:"Planned the whole route to avoid the stairs.",intensity:2,rarity:"signature",pol:{}},
{id:4106,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Sedentary-hobby preferring",desc:"Chooses hobbies that require minimal physical movement.",example:"Reading. Sitting. That's the plan for today.",intensity:1,rarity:"common",pol:{}},
{id:4107,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Late-riser low-energy",desc:"Consistently starts the day much later than most.",example:"Morning's overrated. I'll join at noon.",intensity:2,rarity:"signature",pol:{}},
{id:4108,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Low-exertion problem solver",desc:"Prefers mental over physical solutions to avoid exertion.",example:"Let's think our way out instead of digging.",intensity:2,rarity:"signature",pol:{}},
{id:4109,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Comfort-seeking low-energy",desc:"Prioritizes physical ease and rest above nearly everything else.",example:"Why would I stand when there's a perfectly good chair?",intensity:2,rarity:"common",pol:{}},
{id:4150,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Sanctuary-building",desc:"Wants to construct a truly safe place for themselves and others.",example:"Just want four walls nobody can take from us.",intensity:3,rarity:"common",pol:{}},
{id:4151,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Debt-clearing",desc:"Wants to fully repay a specific, weighty obligation.",example:"Once that's paid, I can finally breathe.",intensity:3,rarity:"signature",pol:{}},
{id:4152,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Recognition-from-one",desc:"Wants acknowledgment specifically from one particular person.",example:"Don't care what anyone else thinks. Just him.",intensity:3,rarity:"signature",pol:{}},
{id:4153,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Skill-passing-on",desc:"Wants to teach what they know before it's too late.",example:"Someone needs to learn this before I'm gone.",intensity:2,rarity:"signature",pol:{}},
{id:4154,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Restoring-a-name",desc:"Wants to clear a family or personal name of old disgrace.",example:"That name meant something once. Want it to again.",intensity:3,rarity:"signature",pol:{}},
{id:4155,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Independence-from-family",desc:"Wants to build a life fully separate from inherited expectation.",example:"Not his son here. Just me. Want to be just me.",intensity:3,rarity:"signature",pol:{}},
{id:4156,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A-worthy-death",desc:"Wants their eventual death to mean something, not be wasted.",example:"If it comes to that, let it count for something.",intensity:4,rarity:"signature",pol:{}},
{id:4157,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Making-amends",desc:"Wants a real, accepted chance to make up for past harm.",example:"Not asking to be forgiven. Just to try to fix it.",intensity:3,rarity:"signature",pol:{}},
{id:4158,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A-place-in-history",desc:"Wants to be remembered specifically for one significant act.",example:"Want my name attached to something that mattered.",intensity:3,rarity:"signature",pol:{}},
{id:4159,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Simple-normalcy",desc:"Wants an unremarkable, quiet, ordinary life after chaos.",example:"Just want boring. Genuinely, boringly normal.",intensity:2,rarity:"common",pol:{}},
{id:4160,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-becoming-them",desc:"Terrified of turning into the person who hurt them.",example:"If I become him, everything was for nothing.",intensity:4,rarity:"signature",pol:{}},
{id:4161,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-wasted-potential",desc:"Terrified their talent will go unused and unrealized.",example:"Could've been something. Terrified that's all it'll ever be — could've.",intensity:3,rarity:"signature",pol:{}},
{id:4162,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-a-specific-person",desc:"Terrified of one particular individual finding them again.",example:"If he finds me here, everything ends.",intensity:4,rarity:"signature",pol:{}},
{id:4163,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-losing-the-last-one",desc:"Terrified of losing the one relationship they have left.",example:"She's all I've got left. Can't lose her too.",intensity:4,rarity:"signature",pol:{}},
{id:4164,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-irrelevance",desc:"Terrified of a world moving on without needing them at all.",example:"What happens when nobody asks for my opinion anymore?",intensity:3,rarity:"signature",pol:{}},
{id:4165,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-exposure-of-weakness",desc:"Terrified others will discover a specific vulnerability.",example:"If they knew how scared I actually am, that's it for me.",intensity:3,rarity:"signature",pol:{}},
{id:4166,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-broken-trust-repeating",desc:"Terrified of being deceived the exact same way again.",example:"Fell for it once. Can't let it happen twice.",intensity:3,rarity:"signature",pol:{}},
{id:4167,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-losing-agency",desc:"Terrified of becoming powerless to decide their own life.",example:"Someone else deciding for me — that's the nightmare.",intensity:3,rarity:"signature",pol:{}},
{id:4168,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-a-place",desc:"Terrified of one specific location tied to past trauma.",example:"Won't go near that street. Not ever again.",intensity:4,rarity:"signature",pol:{}},
{id:4169,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-disappointing-the-dead",desc:"Terrified of failing to live up to a deceased person's expectations.",example:"She believed in me. Can't let that be for nothing.",intensity:3,rarity:"signature",pol:{}},
{id:4170,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Chosen-last-repeatedly",desc:"Was consistently picked last or overlooked throughout childhood.",example:"Always the last one picked. Every single time.",intensity:3,rarity:"signature",pol:{}},
{id:4171,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-secret-that-cost-someone",desc:"Kept a secret that ultimately caused real harm to someone.",example:"If I'd said something sooner, she'd still be here.",intensity:5,rarity:"signature",pol:{}},
{id:4172,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Publicly-replaced",desc:"Watched someone else take the role or place meant for them.",example:"Watched him get given exactly what should've been mine.",intensity:3,rarity:"signature",pol:{}},
{id:4173,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-debt-inherited-unfairly",desc:"Was saddled with an obligation they never actually created.",example:"Wasn't my debt. Still had to pay for it, though.",intensity:3,rarity:"signature",pol:{}},
{id:4174,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Failed-a-test-that-mattered",desc:"Failed one critical, defining moment they've never recovered from.",example:"One test. Failed it. Been living in its shadow since.",intensity:4,rarity:"signature",pol:{}},
{id:4175,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-home-that-was-never-safe",desc:"Grew up in a place that never actually felt secure.",example:"Never really had a home. Just a house that wasn't safe.",intensity:4,rarity:"signature",pol:{}},
{id:4176,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Trusted-the-wrong-authority",desc:"Followed a leader or mentor who badly betrayed that trust.",example:"Did everything he asked. He used every bit of it against me.",intensity:4,rarity:"signature",pol:{}},
{id:4177,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-promise-they-broke-themselves",desc:"Broke their own solemn vow and never forgave it.",example:"I swore I wouldn't. I did anyway.",intensity:4,rarity:"signature",pol:{}},
{id:4178,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Watched-injustice-unpunished",desc:"Saw real wrongdoing go entirely without consequence.",example:"He got away with it. Completely. Still burns.",intensity:3,rarity:"signature",pol:{}},
{id:4179,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Loved-and-lost-too-young",desc:"Experienced deep loss at an age too young to process it properly.",example:"Wasn't old enough to understand it. Still isn't, some days.",intensity:4,rarity:"signature",pol:{}},
{id:4180,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-must-always-be-useful'",desc:"Believes their existence is only justified by continued output.",example:"If I'm not producing something, what's the point of me?",intensity:4,rarity:"signature",pol:{}},
{id:4181,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Real-strength-means-no-help'",desc:"Believes accepting help is a fundamental personal failure.",example:"Asking for help means I've already lost.",intensity:3,rarity:"signature",pol:{}},
{id:4182,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-attract-bad-luck'",desc:"Believes misfortune specifically follows them wherever they go.",example:"Bad things happen around me. They just do.",intensity:3,rarity:"signature",pol:{}},
{id:4183,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Being-liked-means-being-fake'",desc:"Believes genuine popularity is inherently dishonest.",example:"If everyone likes you, you're probably lying to all of them.",intensity:2,rarity:"signature",pol:{}},
{id:4184,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-have-to-be-first-to-matter'",desc:"Believes only being first or best confers any real worth.",example:"Second place is just first loser.",intensity:3,rarity:"signature",pol:{}},
{id:4185,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'My-past-defines-my-ceiling'",desc:"Believes where they started permanently limits where they can go.",example:"People like me don't end up somewhere better. We just don't.",intensity:3,rarity:"signature",pol:{}},
{id:4186,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Softness-invites-cruelty'",desc:"Believes showing gentleness reliably brings out others' worst.",example:"Be kind and people take it as permission to hurt you.",intensity:3,rarity:"signature",pol:{}},
{id:4187,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-can-fix-anyone'",desc:"Believes they're personally responsible for repairing broken people.",example:"If I just try hard enough, I can fix him.",intensity:3,rarity:"signature",pol:{}},
{id:4188,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Silence-is-strength'",desc:"Believes never speaking of pain is proof of genuine toughness.",example:"Real strength is never having to say it hurt.",intensity:3,rarity:"signature",pol:{}},
{id:4189,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-owe-my-existence-to-others'",desc:"Believes they must justify simply being alive through service.",example:"Wasn't given this life for free. Still paying for it.",intensity:4,rarity:"signature",pol:{}},
{id:4195,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Cold-calculated fighter",desc:"Becomes precisely, coldly strategic rather than hot-headed.",example:"(voice drops, calm) Let's talk about consequences.",intensity:4,rarity:"signature",pol:{}},
{id:4196,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Escalation-comfortable fighter",desc:"Meets rising tension with equal or greater force, always.",example:"You want this louder? Fine. Louder.",intensity:4,rarity:"signature",pol:{}},
{id:4201,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Geographic-solver fleer",desc:"Leaves town or moves house rather than resolve tension directly.",example:"New start somewhere else. Clean slate.",intensity:3,rarity:"signature",pol:{}},
{id:4202,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Relationship-abandoning fleer",desc:"Cuts contact entirely rather than work through difficulty.",example:"(simply stops answering, permanently)",intensity:4,rarity:"signature",pol:{}},
{id:4214,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Memory-blank freezer",desc:"Genuinely loses access to well-known information, under threat.",example:"Know this. Know this. I can't— it's gone.",intensity:3,rarity:"signature",pol:{}},
{id:4219,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Statue-stillness freezer",desc:"Becomes completely motionless when the center of attention.",example:"(doesn't move a muscle while everyone looks)",intensity:3,rarity:"common",pol:{}},
{id:4230,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Public-vindication",desc:"Wants to be proven right in front of the people who doubted them.",example:"Want them to see it. All of them. See I was right.",intensity:3,rarity:"signature",pol:{}},
{id:4231,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A-quiet-partnership",desc:"Wants a steady, unremarkable companionship, nothing dramatic.",example:"Just want someone to sit with in the evenings.",intensity:2,rarity:"common",pol:{}},
{id:4232,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Mastery-over-fear",desc:"Wants to conquer the specific thing that's always controlled them.",example:"Want to walk in there without my hands shaking.",intensity:3,rarity:"signature",pol:{}},
{id:4233,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Restored-family-bond",desc:"Wants to repair a specific broken relationship with kin.",example:"Just want my brother to answer the door again.",intensity:3,rarity:"signature",pol:{}},
{id:4234,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Financial-independence",desc:"Wants to never again be at someone else's mercy for survival.",example:"Never want to ask anyone for money again. Ever.",intensity:3,rarity:"common",pol:{}},
{id:4235,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Creative-legacy",desc:"Wants something they made to genuinely outlast them.",example:"Want the song to still be sung after I'm gone.",intensity:2,rarity:"signature",pol:{}},
{id:4236,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Community-standing",desc:"Wants to be a genuinely respected, trusted figure locally.",example:"Want people to come to me when it matters.",intensity:2,rarity:"signature",pol:{}},
{id:4237,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Undoing-isolation",desc:"Wants to finally belong somewhere after years of being apart.",example:"Just want somewhere that feels like mine, finally.",intensity:3,rarity:"common",pol:{}},
{id:4238,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"Justice-for-another",desc:"Wants accountability for harm done to someone they love.",example:"Not for me. For her. Want someone to answer for it.",intensity:4,rarity:"signature",pol:{}},
{id:4239,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A-clean-conscience",desc:"Wants to finally stop carrying a specific guilt.",example:"Just want to sleep without it, for once.",intensity:3,rarity:"signature",pol:{}},
{id:4240,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-being-unloved-as-is",desc:"Terrified that who they really are isn't enough to be loved.",example:"If they saw the real me, would they still stay?",intensity:4,rarity:"signature",pol:{}},
{id:4241,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-history-repeating-on-them",desc:"Terrified of experiencing the exact harm they once caused.",example:"What goes around. Terrified it's coming back around to me.",intensity:3,rarity:"signature",pol:{}},
{id:4242,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-a-final-goodbye",desc:"Terrified of the last conversation with someone dying.",example:"Don't know what to say when it's actually the last time.",intensity:4,rarity:"signature",pol:{}},
{id:4243,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-being-seen-as-fraud",desc:"Terrified their competence will be exposed as an act.",example:"One day they'll realize I don't actually know what I'm doing.",intensity:3,rarity:"signature",pol:{}},
{id:4244,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-outliving-purpose",desc:"Terrified of surviving past the point their role still matters.",example:"What am I for, once this is over?",intensity:3,rarity:"signature",pol:{}},
{id:4245,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-a-repeated-loss",desc:"Terrified of losing another person the same way as before.",example:"Can't lose someone else like that. Can't do it again.",intensity:4,rarity:"signature",pol:{}},
{id:4246,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-total-isolation",desc:"Terrified of a future with genuinely no one left.",example:"End up with nobody. That's the actual nightmare.",intensity:3,rarity:"signature",pol:{}},
{id:4247,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-losing-composure-publicly",desc:"Terrified of breaking down in front of people who rely on them.",example:"Can't let them see me fall apart. Not them.",intensity:3,rarity:"signature",pol:{}},
{id:4248,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-becoming-unrecognizable",desc:"Terrified they'll change into someone they wouldn't respect.",example:"Don't want to wake up one day and not know who I am.",intensity:3,rarity:"signature",pol:{}},
{id:4249,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear-of-a-specific-consequence",desc:"Terrified of one particular, concrete outcome if they're caught.",example:"If they find out, that's everything. Everything's gone.",intensity:4,rarity:"signature",pol:{}},
{id:4250,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Sacrificed-and-unthanked",desc:"Gave up something significant that went entirely unacknowledged.",example:"Gave up everything for that family. Nobody even noticed.",intensity:3,rarity:"signature",pol:{}},
{id:4251,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Failed-to-protect-someone",desc:"Was responsible for someone's safety and failed at the crucial moment.",example:"Was supposed to watch him. I looked away.",intensity:5,rarity:"signature",pol:{}},
{id:4252,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Ridiculed-for-a-dream",desc:"Was mocked publicly for something they once genuinely believed in.",example:"Laughed me out of the room. Never tried again after.",intensity:3,rarity:"signature",pol:{}},
{id:4253,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Raised-by-someone-absent",desc:"Grew up with a parent who was present but emotionally unreachable.",example:"He was there. He was never really there, though.",intensity:4,rarity:"signature",pol:{}},
{id:4254,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Lost-status-suddenly",desc:"Fell from a respected position through no clear fault of their own.",example:"Had it all. Gone within a season. Never got it back.",intensity:3,rarity:"signature",pol:{}},
{id:4255,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Betrayed-by-a-sibling",desc:"Was let down in a way that permanently damaged a sibling bond.",example:"My own brother. Still can't say his name easy.",intensity:4,rarity:"signature",pol:{}},
{id:4256,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"A-childhood-promise-broken-to-them",desc:"Was given a promise as a child that was never kept.",example:"Said he'd come back for me. He never did.",intensity:4,rarity:"signature",pol:{}},
{id:4257,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Forced-into-a-role-not-chosen",desc:"Was pushed into an identity or job they never wanted.",example:"Never asked for this. Got handed it anyway.",intensity:3,rarity:"signature",pol:{}},
{id:4258,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Watched-a-mentor-fall",desc:"Saw someone they admired collapse or be disgraced.",example:"Watched him become someone I didn't recognize.",intensity:3,rarity:"signature",pol:{}},
{id:4259,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Blamed-for-something-out-of-their-control",desc:"Carries responsibility for an outcome they had no real power over.",example:"Wasn't my fault. Still got blamed for it. Still do.",intensity:4,rarity:"signature",pol:{}},
{id:4260,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-have-to-earn-my-place-daily'",desc:"Believes belonging must be re-earned constantly, never secured.",example:"One bad day and they'll finally see I don't belong here.",intensity:3,rarity:"signature",pol:{}},
{id:4261,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Wanting-things-is-selfish'",desc:"Believes personal desire is inherently a moral failing.",example:"Shouldn't want that. Wanting things is selfish.",intensity:3,rarity:"signature",pol:{}},
{id:4262,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-cause-the-bad-things-around-me'",desc:"Believes their presence brings misfortune to those nearby.",example:"Bad things happen to people near me. Always have.",intensity:4,rarity:"signature",pol:{}},
{id:4263,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Love-has-to-be-proven-constantly'",desc:"Believes affection must be continually demonstrated or it's fake.",example:"If you really loved me, you'd show it. Every day. Always.",intensity:3,rarity:"signature",pol:{}},
{id:4264,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I'm-only-as-good-as-my-last-success'",desc:"Believes their worth resets to zero after each accomplishment.",example:"Doesn't matter what I did yesterday. What have I done today?",intensity:4,rarity:"signature",pol:{}},
{id:4265,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Trusting-fully-is-naive'",desc:"Believes complete trust in anyone is a fundamental mistake.",example:"Never trust anyone all the way. That's just foolish.",intensity:3,rarity:"signature",pol:{}},
{id:4266,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-have-to-hide-what-I-really-feel'",desc:"Believes genuine emotional honesty invites real danger.",example:"Can't let them see it. Not the real version.",intensity:3,rarity:"signature",pol:{}},
{id:4267,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Good-things-don't-happen-to-people-like-me'",desc:"Believes their circumstances permanently disqualify them from happiness.",example:"People like me don't get the good ending.",intensity:3,rarity:"signature",pol:{}},
{id:4268,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I-owe-everyone-who-ever-helped-me'",desc:"Believes every kindness received creates an unpayable debt.",example:"Never really free of it. Someone always helped, once.",intensity:3,rarity:"signature",pol:{}},
{id:4269,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'Being-needed-is-the-same-as-being-loved'",desc:"Believes usefulness and genuine affection are interchangeable.",example:"They need me. That's basically the same as loving me.",intensity:3,rarity:"signature",pol:{}},
{id:4270,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Loud-defense-first fighter",desc:"Meets any perceived threat with immediate, loud pushback.",example:"No! Absolutely not! Try me!",intensity:3,rarity:"common",pol:{}},
{id:4271,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Strategic-provocation fighter",desc:"Deliberately provokes an opponent into overreacting first.",example:"Go on, then. Say it. I dare you.",intensity:3,rarity:"signature",pol:{}},
{id:4272,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Righteous-anger fighter",desc:"Fights specifically when a moral line has been crossed.",example:"That's not just wrong. That's unforgivable.",intensity:4,rarity:"signature",pol:{}},
{id:4273,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Fast-escalation fighter",desc:"Goes from calm to full confrontation almost instantly.",example:"(zero to furious in a single breath)",intensity:4,rarity:"signature",pol:{}},
{id:4274,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Group-rallying fighter",desc:"Fights by pulling others into the confrontation on their side.",example:"You heard him. Are we just going to let that stand?",intensity:3,rarity:"signature",pol:{}},
{id:4275,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Icy-threat fighter",desc:"Delivers threats calmly, quietly, more unsettling than shouting.",example:"(quiet, level) You'll regret that. I promise you will.",intensity:4,rarity:"signature",pol:{}},
{id:4276,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Immovable-object fighter",desc:"Simply refuses to budge, absorbing pressure without breaking.",example:"Push all you like. Not moving.",intensity:3,rarity:"signature",pol:{}},
{id:4277,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Point-scoring fighter",desc:"Fights to win the argument specifically, tracking who's ahead.",example:"That's two for me, none for you, so far.",intensity:3,rarity:"signature",pol:{}},
{id:4278,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Physical-posturing fighter",desc:"Uses size and stance rather than words to assert dominance.",example:"(steps in close, squares up, says nothing yet)",intensity:3,rarity:"signature",pol:{}},
{id:4279,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Grudge-settling fighter",desc:"Uses the current conflict to finally address a much older one.",example:"This isn't even about today. This is about five years ago.",intensity:3,rarity:"signature",pol:{}},
{id:4280,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Denial-based fleer",desc:"Simply refuses to acknowledge conflict is happening at all.",example:"There's no problem here. Everything's fine.",intensity:3,rarity:"signature",pol:{}},
{id:4281,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Physical-distance fleer",desc:"Creates literal space between themselves and the conflict.",example:"(backs toward the door, slowly, without announcing it)",intensity:2,rarity:"common",pol:{}},
{id:4282,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Topic-avoidance fleer",desc:"Steers every conversation away from the source of tension.",example:"Anyway — how's the weather been?",intensity:2,rarity:"common",pol:{}},
{id:4283,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Work-immersion fleer",desc:"Buries themselves in unrelated obligations to avoid a confrontation.",example:"Can't talk now, swamped with work.",intensity:2,rarity:"common",pol:{}},
{id:4284,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Third-party-routing fleer",desc:"Gets someone else to handle the conflict on their behalf.",example:"Can you deal with him? I really can't right now.",intensity:3,rarity:"signature",pol:{}},
{id:4285,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Emotional-numbing fleer",desc:"Shuts down feeling entirely rather than engage with conflict.",example:"(goes strangely calm, disconnected, mid-argument)",intensity:3,rarity:"signature",pol:{}},
{id:4286,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Delay-tactic fleer",desc:"Postpones addressing conflict indefinitely through excuses.",example:"Let's talk about this another time. Not today.",intensity:2,rarity:"common",pol:{}},
{id:4287,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Total-avoidance fleer",desc:"Structures their whole life to never encounter the source of conflict again.",example:"Just don't go where he goes. Simplest solution.",intensity:3,rarity:"signature",pol:{}},
{id:4288,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Overcommitment fleer",desc:"Fills their schedule specifically to have no time left for conflict.",example:"Booked solid. Genuinely can't fit that conversation in.",intensity:2,rarity:"signature",pol:{}},
{id:4289,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Passive-resistance fleer",desc:"Avoids conflict through quiet non-compliance rather than direct refusal.",example:"(agrees aloud, simply doesn't follow through)",intensity:2,rarity:"signature",pol:{}},
{id:4290,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Overload-shutdown freezer",desc:"Shuts down entirely when too many demands hit at once.",example:"(stops responding altogether, overwhelmed)",intensity:4,rarity:"signature",pol:{}},
{id:4291,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Confrontation-mute freezer",desc:"Loses the ability to speak specifically during direct confrontation.",example:"(mouth opens, nothing comes out)",intensity:3,rarity:"signature",pol:{}},
{id:4292,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Dissociative-drift freezer",desc:"Mentally checks out entirely, present in body only.",example:"(eyes open, present, entirely elsewhere)",intensity:3,rarity:"signature",pol:{}},
{id:4293,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Fear-locked freezer",desc:"Becomes physically unable to move when truly afraid.",example:"(wants to run, cannot make the legs move)",intensity:4,rarity:"signature",pol:{}},
{id:4294,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Numb-compliance freezer",desc:"Goes along with anything asked, feeling nothing at all.",example:"(agrees to everything, registers none of it)",intensity:3,rarity:"signature",pol:{}},
{id:4295,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Delayed-collapse freezer",desc:"Holds together during the crisis, collapses entirely once it's over.",example:"(fine throughout, falls apart the moment it's safe)",intensity:3,rarity:"signature",pol:{}},
{id:4296,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Eye-contact-loss freezer",desc:"Cannot maintain eye contact once genuinely overwhelmed.",example:"(gaze drops, stays down, can't lift it back up)",intensity:2,rarity:"signature",pol:{}},
{id:4297,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Repetition-loop freezer",desc:"Gets stuck repeating the same small phrase under acute stress.",example:"I don't— I don't— I don't know.",intensity:3,rarity:"signature",pol:{}},
{id:4298,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Cold-hands freezer",desc:"Physical symptoms of shutdown appear — cold hands, pale face.",example:"(hands go cold, face drains of color)",intensity:3,rarity:"signature",pol:{}},
{id:4299,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Selective-mute freezer",desc:"Can respond to simple questions but not complex ones, under threat.",example:"(can nod yes or no, can't form actual sentences)",intensity:3,rarity:"signature",pol:{}},
{id:4300,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Anticipatory-obedience fawner",desc:"Complies before being asked, trying to prevent conflict entirely.",example:"(already doing it before the request is even finished)",intensity:3,rarity:"signature",pol:{}},
{id:4301,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Emotional-labor fawner",desc:"Takes on managing everyone else's feelings to avoid conflict.",example:"Let me smooth this over. I can fix the mood here.",intensity:3,rarity:"signature",pol:{}},
{id:4302,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Identity-erasing fawner",desc:"Suppresses their own opinions entirely around a dominant person.",example:"Whatever you think. I don't really have a view.",intensity:4,rarity:"signature",pol:{}},
{id:4303,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Praise-deflecting-toward-threat fawner",desc:"Redirects credit toward the person they're trying to appease.",example:"You did that, really. Not me. All you.",intensity:3,rarity:"signature",pol:{}},
{id:4304,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Constant-checking-in fawner",desc:"Repeatedly asks if the threatening party is satisfied.",example:"Is this okay? Are we okay? Just checking.",intensity:3,rarity:"signature",pol:{}},
{id:4305,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"History-citing fawner",desc:"Reminds the threat of past loyalty to defuse current anger.",example:"I've always been on your side. You know that.",intensity:3,rarity:"signature",pol:{}},
{id:4306,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Overwork-to-please fawner",desc:"Takes on excessive labor specifically to placate someone's anger.",example:"I'll stay late. I'll fix it. Whatever it takes.",intensity:3,rarity:"signature",pol:{}},
{id:4307,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Physical-comfort-offering fawner",desc:"Offers touch or closeness to soothe an angry party.",example:"(reaches out, gentle, trying to calm them down)",intensity:2,rarity:"signature",pol:{}},
{id:4308,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Rapid-concession fawner",desc:"Gives up multiple points in quick succession to end conflict fast.",example:"Fine, and fine, and that too — whatever ends this.",intensity:3,rarity:"common",pol:{}},
{id:4309,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Silent-compliance fawner",desc:"Says nothing, simply obeys, to avoid provoking further anger.",example:"(says nothing, does exactly as told)",intensity:3,rarity:"signature",pol:{}},
{id:4320,section:"Social Role in a Group",category:"Leader",trait:"Data-driven leader",desc:"Leads decisions with evidence rather than instinct or charisma.",example:"Show me the numbers. We'll decide from there.",intensity:2,rarity:"signature",pol:{}},
{id:4321,section:"Social Role in a Group",category:"Leader",trait:"Protective-parental leader",desc:"Leads with a strong instinct to shield the group from harm.",example:"Nobody gets hurt on my watch. Nobody.",intensity:3,rarity:"signature",pol:{}},
{id:4322,section:"Social Role in a Group",category:"Leader",trait:"Charismatic-but-hollow leader",desc:"Draws people in easily but struggles to follow through with substance.",example:"(the room loves them; the follow-through is thinner)",intensity:2,rarity:"signature",pol:{}},
{id:4323,section:"Social Role in a Group",category:"Leader",trait:"Unifying-across-factions leader",desc:"Specializes in bringing genuinely opposed factions to agreement.",example:"You two disagree on everything except this. Let's start there.",intensity:3,rarity:"signature",pol:{}},
{id:4324,section:"Social Role in a Group",category:"Leader",trait:"Steady-hand-in-chaos leader",desc:"Remains calm and clear specifically when everything else falls apart.",example:"(the only steady voice in a room full of panic)",intensity:3,rarity:"signature",pol:{}},
{id:4325,section:"Social Role in a Group",category:"Leader",trait:"Ambitious-visionary leader",desc:"Leads by painting a compelling, specific picture of the future.",example:"In five years, this whole valley looks different. Here's how.",intensity:2,rarity:"signature",pol:{}},
{id:4326,section:"Social Role in a Group",category:"Leader",trait:"Accountability-demanding leader",desc:"Leads by holding everyone, including themselves, to clear standards.",example:"I'll answer for my mistakes. You'll answer for yours.",intensity:3,rarity:"signature",pol:{}},
{id:4327,section:"Social Role in a Group",category:"Leader",trait:"Mentor-first leader",desc:"Leads primarily by developing the people beneath them.",example:"Wrong — but closer. Try it again.",intensity:2,rarity:"signature",pol:{}},
{id:4328,section:"Social Role in a Group",category:"Leader",trait:"Quietly-feared leader",desc:"Commands obedience through reputation rather than visible force.",example:"(nobody's seen them raise a hand; nobody tests them either)",intensity:3,rarity:"signature",pol:{}},
{id:4329,section:"Social Role in a Group",category:"Leader",trait:"Collaborative-power-sharing leader",desc:"Actively distributes authority rather than centralizing it.",example:"This isn't just my call. It's ours.",intensity:2,rarity:"signature",pol:{}},
{id:4336,section:"Social Role in a Group",category:"Peacemaker",trait:"Compromise-architect peacemaker",desc:"Actively constructs the middle-ground deal nobody else could find.",example:"What if neither of you gets everything, but both get enough?",intensity:2,rarity:"signature",pol:{}},
{id:4340,section:"Social Role in a Group",category:"Peacemaker",trait:"Empathy-first peacemaker",desc:"Leads mediation by validating both sides' feelings before facts.",example:"You're both hurting. Let's start there.",intensity:2,rarity:"signature",pol:{}},
{id:4341,section:"Social Role in a Group",category:"Peacemaker",trait:"Preventive-ritual peacemaker",desc:"Establishes recurring rituals specifically to maintain group harmony.",example:"Every Sunday, we clear the air. That's the rule.",intensity:2,rarity:"signature",pol:{}},
{id:4342,section:"Social Role in a Group",category:"Peacemaker",trait:"Quiet-forgiveness modeler",desc:"Demonstrates forgiveness through action rather than lecturing about it.",example:"(simply moves on, no speech about it, and the group follows)",intensity:2,rarity:"signature",pol:{}},
{id:4343,section:"Social Role in a Group",category:"Peacemaker",trait:"Third-option finder peacemaker",desc:"Resolves conflicts by proposing a solution neither side considered.",example:"What if it's neither yours nor his? What if it's new?",intensity:2,rarity:"signature",pol:{}},
{id:4344,section:"Social Role in a Group",category:"Peacemaker",trait:"De-escalation-voice peacemaker",desc:"Uses a specific calm, low tone deliberately to lower room tension.",example:"(voice drops, slows, on purpose, and the room follows)",intensity:2,rarity:"signature",pol:{}},
{id:4345,section:"Social Role in a Group",category:"Peacemaker",trait:"Reconciliation-orchestrator",desc:"Actively arranges the conditions for estranged parties to reconnect.",example:"I've set up a meeting. Just show up. That's all I ask.",intensity:2,rarity:"signature",pol:{}},
{id:4346,section:"Social Role in a Group",category:"Peacemaker",trait:"Face-saving peacemaker",desc:"Structures resolutions so no party has to lose face publicly.",example:"Nobody has to say they were wrong. Just move forward.",intensity:2,rarity:"signature",pol:{}},
{id:4348,section:"Social Role in a Group",category:"Peacemaker",trait:"Group-ritual restorer",desc:"Reinstates shared traditions specifically to rebuild fractured trust.",example:"Let's have the meal together again. Like before.",intensity:2,rarity:"signature",pol:{}},
{id:4349,section:"Social Role in a Group",category:"Peacemaker",trait:"Quiet-persistence peacemaker",desc:"Returns to the same peace effort repeatedly, undiscouraged by setbacks.",example:"Didn't work last time. Trying again anyway.",intensity:2,rarity:"signature",pol:{}},
{id:4360,section:"Social Role in a Group",category:"Instigator",trait:"Attention-seeking instigator",desc:"Provokes conflict specifically to draw the room's focus back to them.",example:"Well, that got everyone's attention, didn't it.",intensity:2,rarity:"common",pol:{}},
{id:4361,section:"Social Role in a Group",category:"Instigator",trait:"Ideological instigator",desc:"Provokes specifically to advance a strongly held belief or cause.",example:"Somebody's got to push this forward, whatever the cost.",intensity:3,rarity:"signature",pol:{}},
{id:4362,section:"Social Role in a Group",category:"Instigator",trait:"Underdog-championing instigator",desc:"Stirs conflict specifically on behalf of someone weaker or overlooked.",example:"Nobody's speaking for her. So I will.",intensity:2,rarity:"signature",pol:{}},
{id:4363,section:"Social Role in a Group",category:"Instigator",trait:"Wound-poking instigator",desc:"Reopens old, unresolved group tensions deliberately.",example:"Are we really pretending that never happened?",intensity:3,rarity:"signature",pol:{}},
{id:4364,section:"Social Role in a Group",category:"Instigator",trait:"Reckless-honesty instigator",desc:"Provokes by saying true things with no regard for the fallout.",example:"Everyone's thinking it. I'll just say it.",intensity:3,rarity:"signature",pol:{}},
{id:4365,section:"Social Role in a Group",category:"Instigator",trait:"Faction-splitting instigator",desc:"Deliberately introduces division into a previously unified group.",example:"Not everyone here agrees with that, actually.",intensity:3,rarity:"signature",pol:{}},
{id:4366,section:"Social Role in a Group",category:"Instigator",trait:"Envy-exploiting instigator",desc:"Provokes by drawing attention to unfair advantages between people.",example:"Notice he never has to do the hard jobs.",intensity:3,rarity:"signature",pol:{}},
{id:4367,section:"Social Role in a Group",category:"Instigator",trait:"Comfort-disrupting instigator",desc:"Deliberately unsettles complacent, self-satisfied groups.",example:"Everyone's very pleased with themselves, aren't they.",intensity:2,rarity:"signature",pol:{}},
{id:4368,section:"Social Role in a Group",category:"Instigator",trait:"Retaliation-inviting instigator",desc:"Provokes knowing it will draw a strong response, and wants it.",example:"Say that to my face, then. Go on.",intensity:3,rarity:"common",pol:{}},
{id:4369,section:"Social Role in a Group",category:"Instigator",trait:"Institution-testing instigator",desc:"Provokes specifically to test how far an official system can be pushed.",example:"Let's see what actually happens if we break this rule.",intensity:2,rarity:"signature",pol:{}},
{id:4380,section:"Social Role in a Group",category:"Outsider",trait:"Language-barrier outsider",desc:"Remains apart partly due to genuine difficulty communicating with the group.",example:"Missing half of what's actually being said, still.",intensity:2,rarity:"signature",pol:{}},
{id:4381,section:"Social Role in a Group",category:"Outsider",trait:"Disability-marginalized outsider",desc:"Kept at the edges due to the group's discomfort with a difference.",example:"Talk around me like I can't hear them. I can.",intensity:3,rarity:"signature",pol:{}},
{id:4382,section:"Social Role in a Group",category:"Outsider",trait:"Ideologically-isolated outsider",desc:"Holds beliefs different enough from the group to preclude real closeness.",example:"We just don't see the world the same way. Never will.",intensity:2,rarity:"signature",pol:{}},
{id:4383,section:"Social Role in a Group",category:"Outsider",trait:"Class-marked outsider",desc:"Remains apart due to visible social or economic difference.",example:"Not one of them. Never will be, not really.",intensity:3,rarity:"signature",pol:{}},
{id:4384,section:"Social Role in a Group",category:"Outsider",trait:"Trauma-isolated outsider",desc:"Kept apart by an experience the rest of the group can't relate to.",example:"They weren't there. They don't understand. Can't, really.",intensity:3,rarity:"signature",pol:{}},
{id:4385,section:"Social Role in a Group",category:"Outsider",trait:"Age-gapped outsider",desc:"Feels apart from the group primarily due to generational difference.",example:"Different world, the one I grew up in.",intensity:2,rarity:"signature",pol:{}},
{id:4386,section:"Social Role in a Group",category:"Outsider",trait:"Whistleblower-outsider",desc:"Ostracized specifically for exposing wrongdoing within the group.",example:"Told the truth. That's why nobody talks to me now.",intensity:4,rarity:"signature",pol:{}},
{id:4387,section:"Social Role in a Group",category:"Outsider",trait:"Chosen-solitude outsider",desc:"Prefers the clarity and freedom of standing genuinely apart.",example:"Clearer out here. Can actually think.",intensity:2,rarity:"signature",pol:{}},
{id:4388,section:"Social Role in a Group",category:"Outsider",trait:"Half-belonging outsider",desc:"Belongs partially to two different groups, fully to neither.",example:"Not quite one of them. Not quite one of you, either.",intensity:2,rarity:"signature",pol:{}},
{id:4389,section:"Social Role in a Group",category:"Outsider",trait:"Silent-witness outsider",desc:"Remains apart because of something they saw that changed everything.",example:"Saw what happened. Can't unsee it. Can't be normal after.",intensity:3,rarity:"signature",pol:{}},
{id:4400,section:"Social Role in a Group",category:"Caretaker",trait:"Financial-caretaker",desc:"Cares for others primarily by managing shared money and resources.",example:"I handle the accounts so nobody else has to worry.",intensity:2,rarity:"signature",pol:{}},
{id:4401,section:"Social Role in a Group",category:"Caretaker",trait:"Health-monitoring caretaker",desc:"Tracks and worries over the physical wellbeing of everyone nearby.",example:"You're pale. Sit down. When did you last eat?",intensity:2,rarity:"signature",pol:{}},
{id:4402,section:"Social Role in a Group",category:"Caretaker",trait:"Self-sacrificing-quietly caretaker",desc:"Makes real personal sacrifices for others without ever mentioning them.",example:"(gave up their own portion, said nothing about it)",intensity:3,rarity:"signature",pol:{}},
{id:4403,section:"Social Role in a Group",category:"Caretaker",trait:"Multi-generational caretaker",desc:"Simultaneously cares for both the young and the elderly in a family.",example:"Feeding the baby and checking on grandmother, same hour.",intensity:3,rarity:"signature",pol:{}},
{id:4404,section:"Social Role in a Group",category:"Caretaker",trait:"Reluctant-but-reliable caretaker",desc:"Complains about the burden while never once actually failing to show up.",example:"This is exhausting. (Shows up anyway. Every time.)",intensity:2,rarity:"signature",pol:{}},
{id:4405,section:"Social Role in a Group",category:"Caretaker",trait:"Ritual-comfort caretaker",desc:"Cares through consistent, comforting daily rituals and routines.",example:"Same tea, same time, every evening. That's for you.",intensity:1,rarity:"signature",pol:{}},
{id:4406,section:"Social Role in a Group",category:"Caretaker",trait:"Protective-fierce caretaker",desc:"Cares through vigilant, sometimes fierce protection of those weaker.",example:"Anyone comes near her, they answer to me first.",intensity:3,rarity:"signature",pol:{}},
{id:4407,section:"Social Role in a Group",category:"Caretaker",trait:"Listening-first caretaker",desc:"Cares primarily by offering full, patient, undivided attention.",example:"Talk. I'm not going anywhere. Take your time.",intensity:1,rarity:"common",pol:{}},
{id:4408,section:"Social Role in a Group",category:"Caretaker",trait:"Overextended caretaker",desc:"Has taken on caring for more people than is genuinely sustainable.",example:"Six people depend on me right now. Six.",intensity:3,rarity:"signature",pol:{}},
{id:4409,section:"Social Role in a Group",category:"Caretaker",trait:"Caretaking-through-cooking",desc:"Expresses care specifically and consistently through preparing food.",example:"Made extra. Knew you'd be hungry.",intensity:1,rarity:"common",pol:{}},
{id:4420,section:"Social Role in a Group",category:"Skeptic",trait:"Contrarian-by-default skeptic",desc:"Doubts specifically because everyone else has already agreed.",example:"Everyone's on board? That's exactly what worries me.",intensity:3,rarity:"signature",pol:{}},
{id:4421,section:"Social Role in a Group",category:"Skeptic",trait:"Chronic-doubter skeptic",desc:"Questions nearly everything, including things that are demonstrably true.",example:"And how do we actually know that's real?",intensity:3,rarity:"signature",pol:{}},
{id:4422,section:"Social Role in a Group",category:"Skeptic",trait:"Reformed-believer skeptic",desc:"Was once enthusiastically credulous, now overcorrects the other way.",example:"Believed everything, once. Learned my lesson.",intensity:2,rarity:"signature",pol:{}},
{id:4423,section:"Social Role in a Group",category:"Skeptic",trait:"Analytical-detachment skeptic",desc:"Approaches claims with cold, methodical scrutiny rather than emotion.",example:"Let's set feelings aside and look at this properly.",intensity:2,rarity:"signature",pol:{}},
{id:4424,section:"Social Role in a Group",category:"Skeptic",trait:"Trust-earning-slow skeptic",desc:"Requires repeated, demonstrated reliability before extending belief.",example:"You've been right twice. Not enough yet.",intensity:2,rarity:"signature",pol:{}},
{id:4425,section:"Social Role in a Group",category:"Skeptic",trait:"Institutional-audit skeptic",desc:"Specifically distrusts formal, official accounts of events.",example:"The official record says one thing. I want to check.",intensity:2,rarity:"signature",pol:{}},
{id:4426,section:"Social Role in a Group",category:"Skeptic",trait:"Warning-sign skeptic",desc:"Focuses specifically on identifying red flags others overlook.",example:"Notice how convenient the timing is?",intensity:3,rarity:"signature",pol:{}},
{id:4427,section:"Social Role in a Group",category:"Skeptic",trait:"Pattern-doubting skeptic",desc:"Distrusts claims that fit too neatly into an expected pattern.",example:"Feels a bit too tidy, doesn't it.",intensity:2,rarity:"signature",pol:{}},
{id:4428,section:"Social Role in a Group",category:"Skeptic",trait:"Self-skeptical skeptic",desc:"Applies the same doubt to their own judgment as to others' claims.",example:"Could be wrong about this too. Worth checking myself.",intensity:2,rarity:"signature",pol:{}},
{id:4429,section:"Social Role in a Group",category:"Skeptic",trait:"Faith-resistant skeptic",desc:"Cannot accept claims that rely purely on belief without evidence.",example:"Faith's not proof. Show me something real.",intensity:3,rarity:"signature",pol:{}},
{id:4440,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Unbending-under-pressure principled",desc:"Holds a position steady even when everyone else wants to compromise.",example:"Everyone else is bending. I'm not.",intensity:3,rarity:"signature",pol:{}},
{id:4441,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Precedent-setting moralist",desc:"Acts carefully because they know others will follow their example.",example:"If I do it, others will think it's fine too. So I won't.",intensity:2,rarity:"signature",pol:{}},
{id:4442,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Sacred-object principled",desc:"Treats specific objects or traditions as genuinely inviolable.",example:"Don't touch that. It's not a rule. It's sacred.",intensity:3,rarity:"signature",pol:{}},
{id:4443,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Whistleblowing principled",desc:"Will expose wrongdoing regardless of personal or professional cost.",example:"Have to report it. Whatever happens to me after.",intensity:4,rarity:"signature",pol:{}},
{id:4444,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Uncompromising-negotiator principled",desc:"Refuses to bargain away a core value, even for significant gain.",example:"Not for sale. Not for any price you can offer.",intensity:3,rarity:"signature",pol:{}},
{id:4445,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Vow-keeper-beyond-death principled",desc:"Continues honoring a promise made to someone now deceased.",example:"Promised her. She's gone. Promise still stands.",intensity:4,rarity:"signature",pol:{}},
{id:4446,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Rule-of-law principled",desc:"Believes formal, agreed rules must be honored even when inconvenient.",example:"Don't like the law. Still follow it.",intensity:2,rarity:"signature",pol:{}},
{id:4447,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Generational-standard principled",desc:"Holds themselves to a moral bar set by respected predecessors.",example:"My grandfather would've done it properly. So will I.",intensity:2,rarity:"signature",pol:{}},
{id:4448,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Public-confession principled",desc:"Willingly admits their own wrongdoing openly rather than hide it.",example:"I did it. I'll say so, plainly, to anyone who asks.",intensity:3,rarity:"signature",pol:{}},
{id:4449,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Non-negotiable-honesty principled",desc:"Treats truthfulness as a fixed rule with literally zero exceptions.",example:"Not even a kind lie. Not even that.",intensity:4,rarity:"signature",pol:{}},
{id:4460,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Risk-adjusted pragmatist",desc:"Calibrates moral flexibility to how much is actually at stake.",example:"Small stakes, small flexibility. Big stakes, more room.",intensity:2,rarity:"signature",pol:{}},
{id:4461,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Result-transparent pragmatist",desc:"Openly admits when they've bent a rule and why it was worth it.",example:"Yes, I broke procedure. Here's exactly why it mattered.",intensity:2,rarity:"signature",pol:{}},
{id:4462,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Adaptive-loyalty pragmatist",desc:"Shifts allegiance readily as circumstances genuinely change.",example:"Was with him when it made sense. Stopped making sense.",intensity:3,rarity:"signature",pol:{}},
{id:4463,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Improvised-ethics pragmatist",desc:"Builds moral reasoning on the fly for situations with no clear precedent.",example:"Never faced this before. Working out the right call as we go.",intensity:2,rarity:"signature",pol:{}},
{id:4464,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Efficiency-first pragmatist",desc:"Prioritizes the fastest workable solution over the most principled one.",example:"Slower and purer, or faster and good enough. Taking faster.",intensity:2,rarity:"signature",pol:{}},
{id:4465,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Selective-rule-follower pragmatist",desc:"Follows rules they agree with, quietly bends the ones they don't.",example:"That one makes sense. That other one, less so.",intensity:3,rarity:"signature",pol:{}},
{id:4466,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Harm-minimizing pragmatist",desc:"Focuses moral reasoning specifically on reducing total damage.",example:"Not about who's right. About who gets hurt least.",intensity:2,rarity:"signature",pol:{}},
{id:4467,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Compromise-broker pragmatist",desc:"Actively seeks the workable middle ground in moral disputes.",example:"Neither of you gets the pure version. Both get enough.",intensity:2,rarity:"signature",pol:{}},
{id:4468,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Track-record pragmatist",desc:"Judges ongoing trust based on demonstrated results, not stated principle.",example:"Talk's cheap. Show me it actually works.",intensity:2,rarity:"signature",pol:{}},
{id:4469,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Flexible-under-necessity pragmatist",desc:"Holds firm principles until genuine necessity requires bending them.",example:"Wouldn't normally. This isn't normal circumstances.",intensity:3,rarity:"signature",pol:{}},
{id:4480,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Mentor-bound loyalist",desc:"Maintains deep loyalty specifically to the person who trained them.",example:"Everything I know, I learned from her. That's not nothing.",intensity:2,rarity:"signature",pol:{}},
{id:4481,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Team-over-self loyalist",desc:"Consistently prioritizes group success over individual credit or gain.",example:"Doesn't matter who gets the credit. We won.",intensity:2,rarity:"signature",pol:{}},
{id:4482,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Loyalty-despite-disagreement holder",desc:"Stays loyal even while privately disagreeing with decisions made.",example:"Think he's wrong on this one. Still backing him.",intensity:3,rarity:"signature",pol:{}},
{id:4483,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Protective-secrecy loyalist",desc:"Keeps others' secrets even under significant personal pressure.",example:"Not telling you. Not going to. Ever.",intensity:3,rarity:"signature",pol:{}},
{id:4484,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Ride-or-die loyalist",desc:"Commits fully and immediately to standing by their chosen people.",example:"Whatever this is, wherever it goes, I'm in.",intensity:4,rarity:"signature",pol:{}},
{id:4485,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Old-friendship loyalist",desc:"Maintains loyalty to relationships formed long ago, regardless of drift.",example:"Known him thirty years. That still counts for something.",intensity:2,rarity:"signature",pol:{}},
{id:4486,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Loyalty-to-the-dead holder",desc:"Maintains commitments made to people who are no longer living.",example:"Promised him. He's gone. Promise still stands.",intensity:3,rarity:"signature",pol:{}},
{id:4487,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Community-rooted loyalist",desc:"Extends deep loyalty specifically to the place and people they grew up among.",example:"This is my town. I don't abandon my town.",intensity:2,rarity:"signature",pol:{}},
{id:4488,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Earned-not-given loyalist",desc:"Extends loyalty only after it's been genuinely, personally earned.",example:"Didn't trust him at first. Earned it, though. Now I do.",intensity:2,rarity:"signature",pol:{}},
{id:4489,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Sacrifice-proving loyalist",desc:"Demonstrates loyalty through visible, costly personal sacrifice.",example:"Gave up the promotion. For the team. Don't regret it.",intensity:3,rarity:"signature",pol:{}},
{id:4500,section:"Values & Moral Line",category:"Self-Interested",trait:"Advantage-maximizing self-interested",desc:"Consistently seeks the arrangement that benefits them most, openly.",example:"Take the better deal. Wherever it comes from.",intensity:2,rarity:"signature",pol:{}},
{id:4501,section:"Values & Moral Line",category:"Self-Interested",trait:"Consequence-avoiding self-interested",desc:"Structures actions specifically to escape personal accountability.",example:"Made sure my name's nowhere on that paperwork.",intensity:3,rarity:"signature",pol:{}},
{id:4502,section:"Values & Moral Line",category:"Self-Interested",trait:"Convenience-first self-interested",desc:"Chooses whatever option requires the least personal effort or cost.",example:"Easier for me this way. That settles it.",intensity:2,rarity:"common",pol:{}},
{id:4503,section:"Values & Moral Line",category:"Self-Interested",trait:"Image-protecting self-interested",desc:"Prioritizes their public reputation over the actual moral question.",example:"Doesn't matter if it's right. Matters how it looks.",intensity:3,rarity:"signature",pol:{}},
{id:4504,section:"Values & Moral Line",category:"Self-Interested",trait:"Zero-sum self-interested",desc:"Assumes their gain must come at someone else's loss, and accepts that.",example:"Someone wins, someone loses. Making sure it's me.",intensity:3,rarity:"signature",pol:{}},
{id:4505,section:"Values & Moral Line",category:"Self-Interested",trait:"Short-term-focused self-interested",desc:"Prioritizes immediate personal benefit over longer-term considerations.",example:"Worry about tomorrow's consequences tomorrow.",intensity:2,rarity:"signature",pol:{}},
{id:4506,section:"Values & Moral Line",category:"Self-Interested",trait:"Self-justifying self-interested",desc:"Constructs elaborate justifications for choices that happen to benefit them.",example:"Really, doing this for everyone's sake. (It's mostly for them.)",intensity:3,rarity:"signature",pol:{}},
{id:4507,section:"Values & Moral Line",category:"Self-Interested",trait:"Advantage-hoarding self-interested",desc:"Actively withholds useful information or resources to maintain an edge.",example:"Not telling him that part. Keeping that one for myself.",intensity:3,rarity:"signature",pol:{}},
{id:4508,section:"Values & Moral Line",category:"Self-Interested",trait:"Loyalty-conditional self-interested",desc:"Extends loyalty explicitly conditioned on continued personal benefit.",example:"With him as long as it works for me. No further.",intensity:3,rarity:"signature",pol:{}},
{id:4509,section:"Values & Moral Line",category:"Self-Interested",trait:"Self-first-then-others self-interested",desc:"Openly prioritizes their own needs before considering anyone else's.",example:"Sort myself out first. Then I'll think about helping.",intensity:2,rarity:"signature",pol:{}},
{id:4520,section:"Attachment & Intimacy Style",category:"Secure",trait:"Playfully-secure attacher",desc:"Maintains ease and humor even during relationship stress.",example:"(cracks a joke mid-argument; it actually helps)",intensity:1,rarity:"signature",pol:{}},
{id:4521,section:"Attachment & Intimacy Style",category:"Secure",trait:"Physically-affectionate secure",desc:"Shows consistent, easy physical affection without anxiety.",example:"(reaches for their hand without thinking about it)",intensity:1,rarity:"common",pol:{}},
{id:4522,section:"Attachment & Intimacy Style",category:"Secure",trait:"Boundary-respecting secure",desc:"Honors a partner's stated limits without taking it personally.",example:"Said no to that. Fine. Respect it.",intensity:1,rarity:"signature",pol:{}},
{id:4523,section:"Attachment & Intimacy Style",category:"Secure",trait:"Growth-encouraging secure",desc:"Actively supports a partner's independent goals and growth.",example:"Go do that thing. I'll be here when you're back, cheering.",intensity:2,rarity:"signature",pol:{}},
{id:4524,section:"Attachment & Intimacy Style",category:"Secure",trait:"Honest-vulnerability secure",desc:"Shares real fears and doubts without expecting rescue.",example:"Scared about this. Not asking you to fix it. Just wanted you to know.",intensity:2,rarity:"signature",pol:{}},
{id:4525,section:"Attachment & Intimacy Style",category:"Secure",trait:"Non-reactive secure",desc:"Responds to a partner's bad mood without escalating or personalizing it.",example:"Rough day? Okay. Not about me. I'm here, though.",intensity:2,rarity:"signature",pol:{}},
{id:4526,section:"Attachment & Intimacy Style",category:"Secure",trait:"Consistent-affection secure",desc:"Shows the same level of warmth regardless of external stress.",example:"(just as warm during the hard week as the easy one)",intensity:1,rarity:"signature",pol:{}},
{id:4527,section:"Attachment & Intimacy Style",category:"Secure",trait:"Curious-not-anxious secure",desc:"Approaches a partner's silence or distance with curiosity, not panic.",example:"You've been quiet. What's going on for you?",intensity:1,rarity:"signature",pol:{}},
{id:4528,section:"Attachment & Intimacy Style",category:"Secure",trait:"Long-view secure",desc:"Trusts the relationship's foundation even during rough short-term patches.",example:"Bad week doesn't undo three good years.",intensity:2,rarity:"signature",pol:{}},
{id:4529,section:"Attachment & Intimacy Style",category:"Secure",trait:"Mutual-repair secure",desc:"Actively participates in fixing ruptures rather than waiting to be approached.",example:"Let's both say what went wrong here.",intensity:2,rarity:"common",pol:{}},
{id:4533,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Merge-seeking anxious attacher",desc:"Wants near-total closeness, struggles with any separateness.",example:"Why can't I just come with you? Everywhere?",intensity:3,rarity:"signature",pol:{}},
{id:4538,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Test-setting anxious attacher",desc:"Unconsciously sets small tests to check if they're truly loved.",example:"Said I was fine. Did you actually believe me?",intensity:3,rarity:"signature",pol:{}},
{id:4540,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Protest-behavior anxious",desc:"Escalates behavior specifically to provoke a reaction when feeling unseen.",example:"Don't worry about it. Really. Don't. I'm obviously fine.",intensity:3,rarity:"signature",pol:{}},
{id:4541,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Anticipatory-anxiety attacher",desc:"Worries about the relationship's future even when the present is fine.",example:"Things are good now. What happens when they're not?",intensity:2,rarity:"signature",pol:{}},
{id:4542,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Comparison-anxious attacher",desc:"Measures their relationship anxiously against others' relationships.",example:"Do they text like that? Is that normal, or is something off with us?",intensity:2,rarity:"signature",pol:{}},
{id:4543,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Clinging-under-stress anxious",desc:"Becomes noticeably more attached specifically during hard periods.",example:"(holds on tighter, exactly when things get difficult)",intensity:3,rarity:"signature",pol:{}},
{id:4544,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Emotional-flooding anxious",desc:"Feels the relationship's ups and downs with unusual intensity.",example:"One good text and I'm elated. One late reply and I'm wrecked.",intensity:3,rarity:"signature",pol:{}},
{id:4545,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Rejection-primed anxious",desc:"Expects rejection so consistently it colors how they interpret everything.",example:"Knew you'd eventually get tired of me.",intensity:3,rarity:"signature",pol:{}},
{id:4546,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Repair-desperate anxious",desc:"Cannot rest until a conflict is fully, immediately resolved.",example:"Can't just leave it like this. Have to fix it now.",intensity:3,rarity:"signature",pol:{}},
{id:4547,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Attention-monitoring anxious",desc:"Tracks exactly how much attention they're getting compared to before.",example:"Used to call every night. Now it's every other. Noticed that.",intensity:2,rarity:"signature",pol:{}},
{id:4548,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Self-blaming anxious",desc:"Assumes relationship problems are primarily their own fault.",example:"Probably did something. Usually is me.",intensity:3,rarity:"signature",pol:{}},
{id:4549,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Love-language-anxious attacher",desc:"Requires a very specific form of reassurance to actually feel secure.",example:"Words aren't enough. Need you to show it, specifically like this.",intensity:2,rarity:"signature",pol:{}},
{id:4553,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Escape-hatch keeper avoidant",desc:"Always maintains an unspoken way out of the relationship.",example:"(never fully unpacks, keeps the old lease 'just in case')",intensity:3,rarity:"signature",pol:{}},
{id:4560,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Fiercely-independent avoidant",desc:"Treats needing a partner for anything as an uncomfortable admission.",example:"Could manage without you. Just don't have to, currently.",intensity:3,rarity:"signature",pol:{}},
{id:4561,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Emotionally-flat avoidant",desc:"Presents a consistently even, low-affect demeanor regardless of the relationship's state.",example:"(same flat tone whether things are wonderful or terrible)",intensity:3,rarity:"signature",pol:{}},
{id:4562,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Delayed-commitment avoidant",desc:"Postpones relationship milestones indefinitely without clear reason.",example:"We'll talk about that eventually. No rush, right?",intensity:3,rarity:"signature",pol:{}},
{id:4563,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Self-reliant-to-a-fault avoidant",desc:"Refuses help even when clearly, visibly struggling.",example:"I've got it. Said I've got it.",intensity:3,rarity:"signature",pol:{}},
{id:4566,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Practical-love-language avoidant",desc:"Expresses care exclusively through tasks, never through words.",example:"Fixed your cart. That's — that's how I say it.",intensity:2,rarity:"signature",pol:{}},
{id:4567,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Conflict-avoidant-through-distance",desc:"Handles relationship conflict by physically or emotionally withdrawing.",example:"(goes quiet, goes elsewhere, rather than argue)",intensity:3,rarity:"signature",pol:{}},
{id:4568,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Minimal-disclosure avoidant",desc:"Shares the absolute minimum necessary to maintain the relationship.",example:"Fine. That's the update. Fine.",intensity:2,rarity:"signature",pol:{}},
{id:4569,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Guarded-affection avoidant",desc:"Shows affection rarely and briefly, quickly retreating after.",example:"(a brief hand on the shoulder, then gone)",intensity:2,rarity:"signature",pol:{}},
{id:4580,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Hot-and-cold disorganized",desc:"Alternates unpredictably between intense pursuit and total withdrawal.",example:"(texts constantly for a week, silent for the next)",intensity:4,rarity:"signature",pol:{}},
{id:4581,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Self-sabotaging-love disorganized",desc:"Actively damages good relationships right when they're going well.",example:"It was going too well. Did what I do.",intensity:4,rarity:"signature",pol:{}},
{id:4582,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Push-pull disorganized",desc:"Simultaneously craves and fears real intimacy at nearly all times.",example:"Want you close. Can't stand you close. Both.",intensity:4,rarity:"signature",pol:{}},
{id:4583,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Reactive-abandonment disorganized",desc:"Overreacts intensely to perceived signs of being left.",example:"(spirals completely over a slightly delayed reply)",intensity:3,rarity:"signature",pol:{}},
{id:4584,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Emotional-whiplash disorganized",desc:"Shifts between extreme emotional states rapidly within a relationship.",example:"Furious. Now devoted. Now furious again. All within an hour.",intensity:4,rarity:"signature",pol:{}},
{id:4585,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Boundary-confused disorganized",desc:"Cannot maintain consistent boundaries, oscillates between none and rigid ones.",example:"No rules at all. Now suddenly, strict rules. Confusing, I know.",intensity:3,rarity:"signature",pol:{}},
{id:4586,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Chaos-comfort disorganized",desc:"Finds turbulent relationships oddly more comfortable than stable ones.",example:"Calm makes me nervous. Don't know what to do with calm.",intensity:3,rarity:"signature",pol:{}},
{id:4587,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Preemptive-sabotage disorganized",desc:"Ends good relationships before they can potentially end them first.",example:"Left before he could leave me. Every time.",intensity:4,rarity:"signature",pol:{}},
{id:4588,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Split-self disorganized",desc:"Presents dramatically different selves to the same partner at different times.",example:"(is a completely different person some days, and knows it)",intensity:3,rarity:"signature",pol:{}},
{id:4589,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Trauma-echoing disorganized",desc:"Relationship patterns visibly echo unresolved earlier trauma.",example:"Keep recreating the same thing. Don't know how to stop.",intensity:4,rarity:"signature",pol:{}},
{id:4600,section:"Humor Style",category:"Dry & Deadpan",trait:"Self-aware deadpan",desc:"Delivers dry humor while acknowledging, flatly, that it is dry humor.",example:"That was a joke. I don't know why nobody's laughing.",intensity:2,rarity:"signature",pol:{}},
{id:4601,section:"Humor Style",category:"Dry & Deadpan",trait:"Emotionless-crisis dry",desc:"Reports genuine emergencies in a strangely flat, unaffected tone.",example:"House is on fire. Kettle's also boiling. Priorities.",intensity:3,rarity:"signature",pol:{}},
{id:4602,section:"Humor Style",category:"Dry & Deadpan",trait:"Interview-flat dry",desc:"Answers even personal questions like a bored formal interview.",example:"Yes. That happened. Next question.",intensity:2,rarity:"signature",pol:{}},
{id:4603,section:"Humor Style",category:"Dry & Deadpan",trait:"Compliment-flattener dry",desc:"Delivers sincere compliments in an intentionally flat, ironic-sounding tone.",example:"Riveting work. Truly. Unbelievably riveting.",intensity:2,rarity:"signature",pol:{}},
{id:4604,section:"Humor Style",category:"Dry & Deadpan",trait:"Statistically-absurd dry",desc:"Cites fake precise statistics for comedic dry effect.",example:"Ninety-four percent of that plan is nonsense, roughly.",intensity:2,rarity:"signature",pol:{}},
{id:4605,section:"Humor Style",category:"Dry & Deadpan",trait:"Wordless-deadpan",desc:"Uses a single flat look instead of any verbal response.",example:"(just looks at them. Says nothing. That is the joke.)",intensity:2,rarity:"signature",pol:{}},
{id:4606,section:"Humor Style",category:"Dry & Deadpan",trait:"News-anchor dry",desc:"Delivers small domestic updates with grave newscaster gravity.",example:"This just in: the milk has expired.",intensity:2,rarity:"common",pol:{}},
{id:4607,section:"Humor Style",category:"Dry & Deadpan",trait:"Overqualified-explainer dry",desc:"Over-explains trivial things in a dry, mock-serious register.",example:"The spoon, as you'll note, is for stirring.",intensity:2,rarity:"signature",pol:{}},
{id:4608,section:"Humor Style",category:"Dry & Deadpan",trait:"Grim-comedy dry",desc:"Uses dry wit specifically to process genuinely dark situations.",example:"Well. Could've gone worse. Statistically unlikely, but could've.",intensity:3,rarity:"signature",pol:{}},
{id:4609,section:"Humor Style",category:"Dry & Deadpan",trait:"Detached-narrator dry",desc:"Narrates their own life events like a bored documentary voiceover.",example:"And here, our subject makes yet another poor decision.",intensity:2,rarity:"signature",pol:{}},
{id:4620,section:"Humor Style",category:"Self-Deprecating",trait:"Appearance-mocking self-dep",desc:"Jokes specifically about their own looks or physical quirks.",example:"This face has launched exactly zero ships.",intensity:2,rarity:"signature",pol:{}},
{id:4621,section:"Humor Style",category:"Self-Deprecating",trait:"Age-joking self-dep",desc:"Uses humor specifically about their own aging or slowing down.",example:"Bones creak louder than the door now.",intensity:1,rarity:"common",pol:{}},
{id:4622,section:"Humor Style",category:"Self-Deprecating",trait:"Competence-doubting self-dep",desc:"Jokes as though genuinely surprised whenever they succeed at anything.",example:"It worked? Didn't expect that, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:4623,section:"Humor Style",category:"Self-Deprecating",trait:"Overly-honest self-dep",desc:"Undercuts themselves with almost painfully honest self-assessment played for laughs.",example:"In fairness, I am exactly as useless as that sounds.",intensity:2,rarity:"signature",pol:{}},
{id:4624,section:"Humor Style",category:"Self-Deprecating",trait:"Group-scapegoat self-dep",desc:"Volunteers themselves as the joke whenever the group needs one.",example:"Blame me. Always works, and it's usually true anyway.",intensity:2,rarity:"signature",pol:{}},
{id:4625,section:"Humor Style",category:"Self-Deprecating",trait:"Historical-failure cataloger",desc:"Keeps and shares a running mental list of their own past blunders.",example:"That's number forty-seven on the list of things I've ruined.",intensity:2,rarity:"signature",pol:{}},
{id:4626,section:"Humor Style",category:"Self-Deprecating",trait:"Underdog-embracing self-dep",desc:"Frames themselves as the perpetual underdog, for comic effect.",example:"Rooting against myself at this point, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:4627,section:"Humor Style",category:"Self-Deprecating",trait:"Modest-achievement joker",desc:"Downplays genuine accomplishments with self-deprecating humor.",example:"Not bad for someone who can barely tie his own boots.",intensity:2,rarity:"common",pol:{}},
{id:4628,section:"Humor Style",category:"Self-Deprecating",trait:"Preemptive-apology comic",desc:"Apologizes in advance for jokes that haven't landed yet.",example:"Sorry, this one's not going to be funny. Here it is anyway.",intensity:1,rarity:"signature",pol:{}},
{id:4629,section:"Humor Style",category:"Self-Deprecating",trait:"Chronic-clumsiness admitter",desc:"Openly, humorously acknowledges a long pattern of physical mishaps.",example:"Third thing I've broken this week. We're keeping count now.",intensity:2,rarity:"signature",pol:{}},
{id:4640,section:"Humor Style",category:"Cruel & Barbed",trait:"Physical-flaw mocking cruel",desc:"Uses someone's appearance as recurring, unkind material.",example:"Careful, don't want that nose leading the charge.",intensity:4,rarity:"signature",pol:{}},
{id:4641,section:"Humor Style",category:"Cruel & Barbed",trait:"Group-turning comic cruel",desc:"Uses jokes specifically to turn a group against one target.",example:"We're all thinking it — go on, say it about him.",intensity:4,rarity:"signature",pol:{}},
{id:4642,section:"Humor Style",category:"Cruel & Barbed",trait:"Grief-adjacent cruel",desc:"Makes cruel jokes near genuinely painful, sensitive topics.",example:"Bit soon for jokes about the funeral? Never too soon.",intensity:4,rarity:"signature",pol:{}},
{id:4643,section:"Humor Style",category:"Cruel & Barbed",trait:"Backhanded-compliment cruel",desc:"Delivers insults wrapped in the shape of a compliment.",example:"Brave of you to wear that, honestly.",intensity:3,rarity:"common",pol:{}},
{id:4644,section:"Humor Style",category:"Cruel & Barbed",trait:"Public-error highlighting cruel",desc:"Draws attention loudly to others' mistakes for entertainment.",example:"Everyone, look — he's done it again.",intensity:3,rarity:"signature",pol:{}},
{id:4645,section:"Humor Style",category:"Cruel & Barbed",trait:"Weaponized-secret cruel",desc:"Uses private information as material for cutting public jokes.",example:"Tell them about the thing you told me. Go on.",intensity:4,rarity:"signature",pol:{}},
{id:4646,section:"Humor Style",category:"Cruel & Barbed",trait:"Condescension-laced cruel",desc:"Delivers 'jokes' that are actually thinly veiled put-downs.",example:"Sweet that you tried. Really. Sweet.",intensity:3,rarity:"signature",pol:{}},
{id:4647,section:"Humor Style",category:"Cruel & Barbed",trait:"Escalating-cruelty comic",desc:"Starts mild, escalates the cruelty of the jokes if unchallenged.",example:"(starts gentle, gets sharper with every unresisted laugh)",intensity:4,rarity:"signature",pol:{}},
{id:4648,section:"Humor Style",category:"Cruel & Barbed",trait:"Fear-exploiting cruel",desc:"Jokes specifically about things they know someone genuinely fears.",example:"Heights bother you? Come stand closer to the edge, then.",intensity:4,rarity:"signature",pol:{}},
{id:4649,section:"Humor Style",category:"Cruel & Barbed",trait:"Deniable-cruelty comic",desc:"Delivers cruel remarks with enough plausible deniability to claim innocence.",example:"Just joking, obviously. (Wasn't entirely joking.)",intensity:3,rarity:"signature",pol:{}},
{id:4660,section:"Humor Style",category:"Warm & Playful",trait:"Playful-nickname giver warm",desc:"Assigns fond, silly nicknames to people they care about.",example:"Morning, Trouble. Sleep well?",intensity:1,rarity:"common",pol:{}},
{id:4661,section:"Humor Style",category:"Warm & Playful",trait:"Gentle-roasting warm",desc:"Teases affectionately in a way that clearly reads as love.",example:"Still the worst cook I know. Still love you, though.",intensity:2,rarity:"signature",pol:{}},
{id:4662,section:"Humor Style",category:"Warm & Playful",trait:"Anticipatory-laugh sharer warm",desc:"Starts laughing before finishing their own joke, infectiously.",example:"(starts laughing halfway through, can barely finish)",intensity:1,rarity:"signature",pol:{}},
{id:4663,section:"Humor Style",category:"Warm & Playful",trait:"Kid-at-heart warm",desc:"Brings genuine childlike delight and play into ordinary moments.",example:"Puddle! We have to jump in the puddle.",intensity:1,rarity:"common",pol:{}},
{id:4664,section:"Humor Style",category:"Warm & Playful",trait:"Warmth-through-mischief warm",desc:"Uses harmless pranks specifically to build closeness and fun.",example:"(swaps the salt for sugar, waits, delighted, for the reaction)",intensity:2,rarity:"signature",pol:{}},
{id:4665,section:"Humor Style",category:"Warm & Playful",trait:"Celebration-amplifying warm",desc:"Turns any small win into a joyful, playful occasion.",example:"We fixed the fence! Cake. We're having cake.",intensity:1,rarity:"common",pol:{}},
{id:4666,section:"Humor Style",category:"Warm & Playful",trait:"Physical-comedy sharer warm",desc:"Includes others in silly physical bits and games, warmly.",example:"Race you to the gate. Loser makes dinner.",intensity:1,rarity:"common",pol:{}},
{id:4667,section:"Humor Style",category:"Warm & Playful",trait:"Reassuring-humor giver warm",desc:"Uses gentle jokes specifically to comfort someone who's anxious.",example:"We've survived worse than this. Remember the goat incident?",intensity:2,rarity:"signature",pol:{}},
{id:4668,section:"Humor Style",category:"Warm & Playful",trait:"Playfully-competitive warm",desc:"Turns mundane tasks into good-natured contests, warmly.",example:"Bet I finish my chores before you finish yours.",intensity:1,rarity:"signature",pol:{}},
{id:4669,section:"Humor Style",category:"Warm & Playful",trait:"Shared-absurdity finder warm",desc:"Finds and shares the small, delightful absurdities of everyday life.",example:"Did you SEE the way that cat looked at us? Personally offended.",intensity:1,rarity:"common",pol:{}},
{id:4675,section:"Humor Style",category:"Absurd & Chaotic",trait:"Non-sequitur artist absurd",desc:"Comedy built entirely on wildly unrelated conversational leaps.",example:"— which reminds me: do trees resent us?",intensity:2,rarity:"common",pol:{}},
{id:4680,section:"Humor Style",category:"Absurd & Chaotic",trait:"Character-voice chaos absurd",desc:"Adopts an increasingly elaborate fictional persona mid-conversation.",example:"(becomes 'Sir Reginald', complete with backstory, unprompted)",intensity:2,rarity:"signature",pol:{}},
{id:4681,section:"Humor Style",category:"Absurd & Chaotic",trait:"Genuinely-unhinged absurd",desc:"Says things so strange the room isn't sure how to react.",example:"I've decided the moon owes me money. Long story.",intensity:3,rarity:"signature",pol:{}},
{id:4682,section:"Humor Style",category:"Absurd & Chaotic",trait:"Improv-chaos absurd",desc:"Yes-ands every ridiculous suggestion into further ridiculousness.",example:"A goose mayor? Absolutely. What's her platform?",intensity:2,rarity:"signature",pol:{}},
{id:4683,section:"Humor Style",category:"Absurd & Chaotic",trait:"Fourth-wall-breaking absurd",desc:"Comments on the absurdity of their own joke while telling it.",example:"This isn't going anywhere, is it. Continuing anyway.",intensity:2,rarity:"signature",pol:{}},
{id:4685,section:"Humor Style",category:"Absurd & Chaotic",trait:"Escalating-dare absurd",desc:"Pushes increasingly ridiculous dares onto a group, gleefully.",example:"Now do it backwards. Now do it backwards blindfolded.",intensity:2,rarity:"signature",pol:{}},
{id:4686,section:"Humor Style",category:"Absurd & Chaotic",trait:"Faux-mythology builder absurd",desc:"Invents elaborate fake legends about ordinary objects or events.",example:"This is the Cursed Spoon of Aldren. Do not touch it.",intensity:2,rarity:"signature",pol:{}},
{id:4687,section:"Humor Style",category:"Absurd & Chaotic",trait:"Genre-shift comic absurd",desc:"Suddenly narrates ordinary events as though they're epic fantasy.",example:"And thus, the bread was toasted, and the realm rejoiced.",intensity:2,rarity:"signature",pol:{}},
{id:4688,section:"Humor Style",category:"Absurd & Chaotic",trait:"Deadpan-chaos hybrid absurd",desc:"Delivers wildly absurd content in a completely flat, serious tone.",example:"(flat) The goose has unionized. We should discuss terms.",intensity:3,rarity:"signature",pol:{}},
{id:4689,section:"Humor Style",category:"Absurd & Chaotic",trait:"Escalating-volume absurd",desc:"Comedy that builds specifically through increasing volume and energy.",example:"(starts a whisper, ends in a full theatrical shout)",intensity:2,rarity:"signature",pol:{}},
{id:4692,section:"Humor Style",category:"Humorless & Absent",trait:"Delayed-comprehension humorless",desc:"Understands the joke only long after everyone's moved on.",example:"(a full minute later, quietly) Oh — because the boat sank.",intensity:2,rarity:"signature",pol:{}},
{id:4700,section:"Humor Style",category:"Humorless & Absent",trait:"Literal-comprehension-only humorless",desc:"Can only process the literal meaning of statements, never the humor.",example:"You said you'd eat a horse. There's no horse present.",intensity:2,rarity:"signature",pol:{}},
{id:4701,section:"Humor Style",category:"Humorless & Absent",trait:"Anxiety-blocked humorless",desc:"Too preoccupied with worry to register or produce any humor.",example:"Can't think about jokes right now. Genuinely can't.",intensity:3,rarity:"signature",pol:{}},
{id:4702,section:"Humor Style",category:"Humorless & Absent",trait:"Status-conscious humorless",desc:"Avoids humor specifically to maintain a serious, authoritative image.",example:"Wouldn't be appropriate for someone in my position to joke.",intensity:2,rarity:"signature",pol:{}},
{id:4703,section:"Humor Style",category:"Humorless & Absent",trait:"Overanalytical humorless",desc:"Breaks down jokes analytically instead of simply laughing at them.",example:"I see — the humor derives from the unexpected juxtaposition.",intensity:2,rarity:"signature",pol:{}},
{id:4704,section:"Humor Style",category:"Humorless & Absent",trait:"Emotionally-flat humorless",desc:"Registers humor intellectually but experiences no actual amusement.",example:"That is, technically, a joke. I recognize the structure.",intensity:3,rarity:"signature",pol:{}},
{id:4705,section:"Humor Style",category:"Humorless & Absent",trait:"Deadly-serious humorless",desc:"Approaches every topic, however trivial, with total gravity.",example:"The sandwich situation requires immediate, serious attention.",intensity:2,rarity:"signature",pol:{}},
{id:4706,section:"Humor Style",category:"Humorless & Absent",trait:"Joke-correcting humorless",desc:"Responds to jokes by earnestly correcting their factual inaccuracy.",example:"Actually, horses can't literally be eaten whole, so—",intensity:2,rarity:"signature",pol:{}},
{id:4707,section:"Humor Style",category:"Humorless & Absent",trait:"Distracted-past-humor",desc:"So preoccupied with something else that jokes simply don't register.",example:"(nods absently through an entire joke, thinking of something else)",intensity:1,rarity:"signature",pol:{}},
{id:4708,section:"Humor Style",category:"Humorless & Absent",trait:"Formality-locked humorless",desc:"Cannot relax into casual, joking register even in casual settings.",example:"(delivers even light banter with total, stiff formality)",intensity:2,rarity:"signature",pol:{}},
{id:4709,section:"Humor Style",category:"Humorless & Absent",trait:"Recently-humorless",desc:"Used to have a sense of humor; something recent has switched it off.",example:"Don't really find things funny anymore. Not since.",intensity:4,rarity:"signature",pol:{}},
{id:4720,section:"Habits & Vices",category:"Substance & Consumption",trait:"Denial-maintaining substance user",desc:"Genuinely insists they don't have a problem, evidence notwithstanding.",example:"Could stop anytime. Just don't want to.",intensity:3,rarity:"signature",pol:{}},
{id:4721,section:"Habits & Vices",category:"Substance & Consumption",trait:"Peer-influenced substance user",desc:"Consumption patterns shift heavily based on who they're with.",example:"Wouldn't touch it alone. With them, though — different story.",intensity:2,rarity:"signature",pol:{}},
{id:4722,section:"Habits & Vices",category:"Substance & Consumption",trait:"Substitution-cycling user",desc:"Swaps one form of consumption for another, believing it's healthier.",example:"Cut back on that. Picked up this instead.",intensity:2,rarity:"signature",pol:{}},
{id:4723,section:"Habits & Vices",category:"Substance & Consumption",trait:"Time-of-day ritualist substance",desc:"Consumption is tied rigidly to a specific hour, never earlier.",example:"Not before sundown. Rule's the rule.",intensity:1,rarity:"signature",pol:{}},
{id:4724,section:"Habits & Vices",category:"Substance & Consumption",trait:"Guilt-cycling substance user",desc:"Alternates between indulgence and intense self-recrimination.",example:"Did it again. Feel terrible about it. Will probably do it again.",intensity:3,rarity:"signature",pol:{}},
{id:4725,section:"Habits & Vices",category:"Substance & Consumption",trait:"Celebratory-only substance user",desc:"Consumption is tied specifically and only to good news or achievement.",example:"Only when there's something to celebrate. That's the rule.",intensity:1,rarity:"common",pol:{}},
{id:4726,section:"Habits & Vices",category:"Substance & Consumption",trait:"Escalating-tolerance substance user",desc:"Needs progressively more to achieve the same effect, and knows it.",example:"Takes more than it used to. Worries me a little, honestly.",intensity:3,rarity:"signature",pol:{}},
{id:4727,section:"Habits & Vices",category:"Substance & Consumption",trait:"Public-versus-private substance user",desc:"Behaves very differently around the habit depending on who's watching.",example:"(controlled and light in public; heavier, alone)",intensity:3,rarity:"signature",pol:{}},
{id:4728,section:"Habits & Vices",category:"Substance & Consumption",trait:"Substance-as-medicine user",desc:"Frames their consumption explicitly as self-treatment for pain.",example:"Helps with the leg. That's all it is.",intensity:3,rarity:"signature",pol:{}},
{id:4729,section:"Habits & Vices",category:"Substance & Consumption",trait:"Recovery-proud substance user",desc:"Speaks openly and proudly about having overcome a past habit.",example:"Two years now. Don't mind saying it. Proud of it.",intensity:2,rarity:"signature",pol:{}},
{id:4740,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Sequence-obsessive compulsive",desc:"Must perform daily tasks in an exact, unvarying order.",example:"Boots before coat. Always boots before coat.",intensity:2,rarity:"signature",pol:{}},
{id:4741,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Repetitive-checking compulsive",desc:"Rechecks completed work obsessively, unable to trust it's done.",example:"Checked the numbers. Checking them again.",intensity:3,rarity:"signature",pol:{}},
{id:4742,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Object-alignment compulsive",desc:"Cannot leave objects at anything but a precise, deliberate angle.",example:"(nudges the cup, again, until it's exactly parallel)",intensity:2,rarity:"signature",pol:{}},
{id:4743,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Intrusive-thought ritualist compulsive",desc:"Performs a specific ritual to neutralize unwanted, distressing thoughts.",example:"(a small gesture, private, to push the bad thought away)",intensity:3,rarity:"signature",pol:{}},
{id:4744,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Time-ritual compulsive",desc:"Must perform certain actions at exactly the same time daily.",example:"Has to be four. Not five past. Four.",intensity:2,rarity:"signature",pol:{}},
{id:4745,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Number-significance compulsive",desc:"Assigns private, rigid meaning to specific numbers in daily life.",example:"Not that room. Thirteen's the room. Won't go near it.",intensity:2,rarity:"signature",pol:{}},
{id:4746,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Hand-washing ritualist compulsive",desc:"Washes hands repeatedly, well beyond practical necessity.",example:"(hands, again, third time this hour)",intensity:3,rarity:"signature",pol:{}},
{id:4747,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Doorway-ritual compulsive",desc:"Cannot pass through certain doorways without a specific private action.",example:"(pauses, does the small thing, then continues)",intensity:2,rarity:"signature",pol:{}},
{id:4748,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Speech-ritual compulsive",desc:"Must say a specific phrase before undertaking anything important.",example:"Can't start without saying it first. Every time.",intensity:2,rarity:"signature",pol:{}},
{id:4749,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Object-count ritualist compulsive",desc:"Needs a specific, exact number of items present to feel at ease.",example:"Needs to be seven candles. Not six. Seven.",intensity:2,rarity:"signature",pol:{}},
{id:4760,section:"Habits & Vices",category:"Risk & Escape",trait:"Cliffhanger-seeking risk",desc:"Actively seeks out situations with genuine, unresolved uncertainty.",example:"Don't know how it ends. That's exactly why I like it.",intensity:3,rarity:"signature",pol:{}},
{id:4761,section:"Habits & Vices",category:"Risk & Escape",trait:"Impulsive-travel escapist risk",desc:"Leaves suddenly, without planning, whenever things get difficult.",example:"Bought a ticket this morning. Leaving tonight.",intensity:3,rarity:"signature",pol:{}},
{id:4762,section:"Habits & Vices",category:"Risk & Escape",trait:"High-stakes-negotiation risk",desc:"Deliberately raises the stakes in negotiations beyond what's necessary.",example:"Could've settled for less. Wanted the bigger risk.",intensity:3,rarity:"signature",pol:{}},
{id:4763,section:"Habits & Vices",category:"Risk & Escape",trait:"Danger-normalizing risk-taker",desc:"Has become so used to risk that ordinary caution feels foreign.",example:"That's not dangerous. That's Tuesday.",intensity:3,rarity:"signature",pol:{}},
{id:4764,section:"Habits & Vices",category:"Risk & Escape",trait:"Escape-through-work risk",desc:"Uses reckless overwork as an escape from personal difficulty.",example:"Can't stop working. If I stop, I have to think.",intensity:3,rarity:"signature",pol:{}},
{id:4765,section:"Habits & Vices",category:"Risk & Escape",trait:"Thrill-chasing risk-taker",desc:"Actively seeks new, more intense sources of physical thrill.",example:"Done that one. What's next, something bigger?",intensity:3,rarity:"common",pol:{}},
{id:4766,section:"Habits & Vices",category:"Risk & Escape",trait:"Reckless-generosity risk",desc:"Gives away resources recklessly, beyond what's actually sustainable.",example:"Gave him the last of it. Don't know what we'll do now.",intensity:3,rarity:"signature",pol:{}},
{id:4767,section:"Habits & Vices",category:"Risk & Escape",trait:"Boundary-crossing risk-taker",desc:"Regularly tests physical or social boundaries considered unsafe.",example:"Sign says don't. Let's find out what happens.",intensity:2,rarity:"common",pol:{}},
{id:4768,section:"Habits & Vices",category:"Risk & Escape",trait:"Escape-through-relocation risk",desc:"Solves personal problems primarily by physically leaving them behind.",example:"New town, new problems. At least they're different ones.",intensity:3,rarity:"signature",pol:{}},
{id:4769,section:"Habits & Vices",category:"Risk & Escape",trait:"Unplanned-decision risk",desc:"Makes major life decisions abruptly, without meaningful planning.",example:"Decided this morning. Leaving by noon.",intensity:3,rarity:"signature",pol:{}},
{id:4790,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Middle-path finder",desc:"Consistently locates a workable compromise between rigid extremes.",example:"Neither of you gets it all. Both get enough.",intensity:2,rarity:"signature",pol:{}},
{id:4791,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Adaptive-ethics reasoner",desc:"Reconstructs their moral reasoning fresh for each unprecedented case.",example:"Never faced this exact thing before. Working it out now.",intensity:2,rarity:"signature",pol:{}},
{id:4792,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Wiggle-room preserver",desc:"Deliberately avoids absolute commitments to preserve future flexibility.",example:"Not promising forever. Promising for now.",intensity:2,rarity:"signature",pol:{}},
{id:4793,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Case-by-case judge",desc:"Refuses blanket rules, insists every situation be judged individually.",example:"Can't say in general. Depends entirely on the specifics.",intensity:2,rarity:"signature",pol:{}},
{id:4794,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Practical-loyalty balancer",desc:"Weighs loyalty against practical necessity rather than absolute duty.",example:"Loyal, sure. Not blindly, though.",intensity:2,rarity:"signature",pol:{}},
{id:4795,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Second-best acceptor",desc:"Settles for workable outcomes rather than holding out for ideal ones.",example:"Not the outcome I wanted. The one we can actually get.",intensity:2,rarity:"signature",pol:{}},
{id:4796,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Rule-bender-with-limits",desc:"Bends rules situationally but maintains a private sense of how far is too far.",example:"Bend it. Don't break it. There's a difference.",intensity:3,rarity:"signature",pol:{}},
{id:4797,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Trade-off namer",desc:"Explicitly names what's being sacrificed in any compromise.",example:"Getting speed. Losing some accuracy. Worth it here.",intensity:2,rarity:"signature",pol:{}},
{id:4798,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Provisional-commitment maker",desc:"Commits to positions while explicitly reserving the right to revise them.",example:"Agreeing for now. Reserve the right to change my mind.",intensity:2,rarity:"signature",pol:{}},
{id:4799,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Circumstance-first reasoner",desc:"Evaluates the situation fully before applying any moral framework.",example:"Tell me everything first. Then I'll say what's right.",intensity:2,rarity:"signature",pol:{}},
{id:4800,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Working-solution preferrer",desc:"Values what actually functions over what's theoretically correct.",example:"Ugly solution. Works, though. That's what matters.",intensity:2,rarity:"common",pol:{}},
{id:4801,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Flexible-under-scrutiny pragmatist",desc:"Adjusts their stated position when shown genuinely better information.",example:"Didn't know that part. Changes things. Reconsidering.",intensity:2,rarity:"signature",pol:{}},
{id:4802,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Never-again vow-keeper",desc:"Holds an absolute personal rule formed from a specific past failure.",example:"Swore I'd never let that happen again. Won't.",intensity:4,rarity:"signature",pol:{}},
{id:4803,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Standard-setting principled",desc:"Deliberately holds themselves to a higher bar than anyone requires.",example:"Nobody's checking. Holding myself to it anyway.",intensity:3,rarity:"signature",pol:{}},
{id:4804,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Non-negotiable-terms holder",desc:"States moral terms as fixed, refusing any negotiation on them.",example:"This isn't a discussion. This is the line.",intensity:3,rarity:"common",pol:{}},
{id:4805,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Consequence-accepting moralist",desc:"Willingly accepts real personal cost to keep a principle intact.",example:"Costs me plenty. Keeping it anyway.",intensity:4,rarity:"signature",pol:{}},
{id:4806,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Written-code follower",desc:"Adheres to an explicit, formally written personal or family code.",example:"It's written down. That's not decoration. That's the rule.",intensity:2,rarity:"signature",pol:{}},
{id:4807,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Integrity-over-outcome principled",desc:"Values how something was achieved over whether it succeeded.",example:"Won, but not fairly. Doesn't count, not to me.",intensity:3,rarity:"signature",pol:{}},
{id:4808,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Uncorrupted-by-power principled",desc:"Maintains the same values regardless of gained status or authority.",example:"More power now. Same rules as before. Exactly the same.",intensity:3,rarity:"signature",pol:{}},
{id:4809,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Personal-court-of-one principled",desc:"Judges their own conduct as strictly as they'd judge anyone else's.",example:"Wouldn't accept that excuse from him. Won't accept it from me either.",intensity:3,rarity:"signature",pol:{}},
{id:4810,section:"Values & Moral Line",category:"Rigid & Principled",trait:"No-exceptions-for-friends principled",desc:"Refuses to bend rules even for people they care about.",example:"Love you. Still breaking the rule gets the same answer.",intensity:3,rarity:"signature",pol:{}},
{id:4811,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Principle-before-profit holder",desc:"Turns down clearly profitable options that violate a stated value.",example:"Good money in it. Not the right thing, though. Passing.",intensity:3,rarity:"signature",pol:{}},
{id:4812,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Unspoken-bond loyalist",desc:"Maintains deep loyalty to relationships that were never formally declared.",example:"Never said it out loud. Doesn't make it less true.",intensity:2,rarity:"signature",pol:{}},
{id:4813,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Second-chance-giving loyalist",desc:"Extends renewed trust to their people even after real disappointment.",example:"Let me down once. Still mine, though. Still trying.",intensity:3,rarity:"signature",pol:{}},
{id:4814,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Quietly-watchful loyalist",desc:"Monitors their people's wellbeing from a distance without announcing it.",example:"Don't need to say I'm watching out for him. Just do it.",intensity:2,rarity:"signature",pol:{}},
{id:4815,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Public-defense loyalist",desc:"Defends their people openly, even against popular opinion.",example:"Whole room's against him. I'm not.",intensity:3,rarity:"signature",pol:{}},
{id:4816,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Practical-support loyalist",desc:"Shows loyalty primarily through consistent, unglamorous help.",example:"Doesn't need speeches. Just needs someone showing up.",intensity:2,rarity:"signature",pol:{}},
{id:4817,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Cause-bound loyalist",desc:"Extends deep loyalty to a shared mission rather than any single person.",example:"Not loyal to him specifically. Loyal to what we're building.",intensity:2,rarity:"signature",pol:{}},
{id:4818,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Debt-forgiving loyalist",desc:"Releases others from owed obligations as an act of loyalty.",example:"Don't need to pay me back. Already square, as far as I'm concerned.",intensity:2,rarity:"signature",pol:{}},
{id:4819,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Vouching loyalist",desc:"Puts their own reputation on the line to defend someone's character.",example:"I'll vouch for him. My name against his, if it comes to that.",intensity:3,rarity:"signature",pol:{}},
{id:4820,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Anniversary-honoring loyalist",desc:"Marks and honors the dates of significant loyalties and promises.",example:"Ten years today since we agreed to this. Still holds.",intensity:2,rarity:"signature",pol:{}},
{id:4821,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Inherited-enemy loyalist",desc:"Maintains an old family alliance even against personal preference.",example:"Not my fight, really. It's the family's fight, though.",intensity:2,rarity:"signature",pol:{}},
{id:4822,section:"Values & Moral Line",category:"Self-Interested",trait:"Cost-of-doing-business self-interested",desc:"Treats minor ethical compromises as simply the price of getting ahead.",example:"Everyone cuts a corner somewhere. This is mine.",intensity:3,rarity:"signature",pol:{}},
{id:4823,section:"Values & Moral Line",category:"Self-Interested",trait:"Insurance-first self-interested",desc:"Prioritizes protecting themselves from future risk over present fairness.",example:"Not thinking about now. Thinking about what happens if this goes wrong.",intensity:2,rarity:"signature",pol:{}},
{id:4824,section:"Values & Moral Line",category:"Self-Interested",trait:"Favor-banking self-interested",desc:"Does kindnesses specifically to accumulate future obligation from others.",example:"Helped him last month. He'll remember that, when I need it.",intensity:3,rarity:"signature",pol:{}},
{id:4825,section:"Values & Moral Line",category:"Self-Interested",trait:"Selective-generosity self-interested",desc:"Gives generously only when it visibly benefits their own standing.",example:"Give plenty. Where people can see it, mostly.",intensity:3,rarity:"signature",pol:{}},
{id:4826,section:"Values & Moral Line",category:"Self-Interested",trait:"Risk-transferring self-interested",desc:"Structures situations so others bear the consequences of their choices.",example:"Not my name on it, if it goes wrong.",intensity:3,rarity:"signature",pol:{}},
{id:4827,section:"Values & Moral Line",category:"Self-Interested",trait:"Best-offer self-interested",desc:"Consistently goes with whoever's currently offering the most.",example:"Not personal. Just going where the better deal is.",intensity:2,rarity:"common",pol:{}},
{id:4828,section:"Values & Moral Line",category:"Self-Interested",trait:"Minimal-obligation self-interested",desc:"Does exactly the minimum required, no more, in any commitment.",example:"Did what was asked. Not asked to do more than that.",intensity:2,rarity:"signature",pol:{}},
{id:4829,section:"Values & Moral Line",category:"Self-Interested",trait:"Advantage-timing self-interested",desc:"Waits patiently for the moment that most benefits their own position.",example:"Not yet. Wait for the moment this actually pays off.",intensity:2,rarity:"signature",pol:{}},
{id:4830,section:"Values & Moral Line",category:"Self-Interested",trait:"Self-first framing self-interested",desc:"Openly frames decisions around personal benefit without much disguise.",example:"Good for me first. We'll see about everyone else after.",intensity:3,rarity:"common",pol:{}},
{id:4831,section:"Values & Moral Line",category:"Self-Interested",trait:"Escape-clause self-interested",desc:"Always ensures agreements include an out that protects only themselves.",example:"Signed it. Made sure there's a way out, though. For me.",intensity:3,rarity:"signature",pol:{}},
{id:4832,section:"Social Role in a Group",category:"Leader",trait:"First-into-danger leader",desc:"Leads by personally taking the riskiest position first.",example:"I'll go first. Everyone else, wait for my signal.",intensity:3,rarity:"signature",pol:{}},
{id:4833,section:"Social Role in a Group",category:"Leader",trait:"Consensus-override leader",desc:"Leads by making the final call even when the group disagrees.",example:"Heard everyone. Deciding anyway. This is the call.",intensity:3,rarity:"signature",pol:{}},
{id:4834,section:"Social Role in a Group",category:"Leader",trait:"Quiet-authority leader",desc:"Commands respect through calm certainty rather than volume.",example:"(barely raises their voice; the room listens anyway)",intensity:2,rarity:"signature",pol:{}},
{id:4835,section:"Social Role in a Group",category:"Leader",trait:"Resource-securing leader",desc:"Leads primarily by ensuring the group has what it needs to function.",example:"My job's making sure nobody goes without. Rest follows from that.",intensity:2,rarity:"signature",pol:{}},
{id:4836,section:"Social Role in a Group",category:"Leader",trait:"Emotionally-attuned leader",desc:"Leads by reading and responding to the group's morale closely.",example:"Everyone's tired. We slow down before we push further.",intensity:2,rarity:"signature",pol:{}},
{id:4837,section:"Social Role in a Group",category:"Leader",trait:"Long-game leader",desc:"Leads with patience, willing to accept short-term setbacks for larger goals.",example:"Losing this round. Winning the actual war, though.",intensity:2,rarity:"signature",pol:{}},
{id:4838,section:"Social Role in a Group",category:"Leader",trait:"Fallback-plan leader",desc:"Leads by always having a backup ready before it's needed.",example:"If that fails, here's what we do instead. Already planned.",intensity:2,rarity:"signature",pol:{}},
{id:4839,section:"Social Role in a Group",category:"Leader",trait:"Humble-power leader",desc:"Wields real authority while actively downplaying their own importance.",example:"Not about me. Never was. Just doing the job.",intensity:2,rarity:"signature",pol:{}},
{id:4840,section:"Social Role in a Group",category:"Leader",trait:"Boundary-enforcing leader",desc:"Leads by clearly, consistently enforcing the group's stated limits.",example:"We said no further than the river. Holding that line.",intensity:2,rarity:"signature",pol:{}},
{id:4841,section:"Social Role in a Group",category:"Outsider",trait:"Reputation-preceded outsider",desc:"Kept apart because rumor about them arrived before they did.",example:"They knew the story before they met me. Hard to shake that.",intensity:3,rarity:"signature",pol:{}},
{id:4842,section:"Social Role in a Group",category:"Outsider",trait:"Skill-isolated outsider",desc:"Kept apart because their unusual competence unsettles the group.",example:"Too good at it, somehow. Makes people uneasy.",intensity:2,rarity:"signature",pol:{}},
{id:4843,section:"Social Role in a Group",category:"Outsider",trait:"Deliberately-mysterious outsider",desc:"Maintains distance by revealing almost nothing about their history.",example:"Where I'm from doesn't matter. Leave it there.",intensity:2,rarity:"signature",pol:{}},
{id:4844,section:"Social Role in a Group",category:"Outsider",trait:"Political-outcast outsider",desc:"Kept apart due to unpopular stated beliefs or allegiances.",example:"Said what I think. Not everyone forgave that.",intensity:3,rarity:"signature",pol:{}},
{id:4845,section:"Social Role in a Group",category:"Outsider",trait:"Grief-isolated outsider",desc:"Kept apart by others' discomfort around their visible mourning.",example:"People don't know what to say to me anymore. So they say nothing.",intensity:3,rarity:"signature",pol:{}},
{id:4846,section:"Social Role in a Group",category:"Outsider",trait:"Competing-loyalty outsider",desc:"Distrusted due to divided allegiance between two groups.",example:"Not fully theirs. Not fully yours either. Complicated.",intensity:3,rarity:"signature",pol:{}},
{id:4847,section:"Social Role in a Group",category:"Outsider",trait:"Formerly-enemy outsider",desc:"Remains partly apart due to a past adversarial history with the group.",example:"We used to be on opposite sides. Some of that doesn't just wash off.",intensity:3,rarity:"signature",pol:{}},
{id:4848,section:"Social Role in a Group",category:"Outsider",trait:"Unconventional-choice outsider",desc:"Kept apart due to a life choice the group doesn't fully accept.",example:"Chose differently than most of you. Still living with that gap.",intensity:2,rarity:"signature",pol:{}},
{id:4849,section:"Social Role in a Group",category:"Outsider",trait:"Silent-dissent outsider",desc:"Distanced by quietly refusing to go along with a group decision.",example:"Didn't agree. Didn't say much. Everyone noticed the distance anyway.",intensity:2,rarity:"signature",pol:{}},
{id:4850,section:"Social Role in a Group",category:"Caretaker",trait:"Grief-caretaker",desc:"Specifically steps into a caretaking role for those who are mourning.",example:"I know what to say. I know what not to say, too. I've done this before.",intensity:3,rarity:"signature",pol:{}},
{id:4851,section:"Social Role in a Group",category:"Caretaker",trait:"Newcomer-orienting caretaker",desc:"Focuses caretaking energy specifically on helping new members settle in.",example:"First week's the hardest. I make sure it isn't, for them.",intensity:2,rarity:"signature",pol:{}},
{id:4852,section:"Social Role in a Group",category:"Caretaker",trait:"Silent-provider caretaker",desc:"Meets others' material needs without ever drawing attention to it.",example:"(the firewood's just there, always, nobody knows from where)",intensity:2,rarity:"signature",pol:{}},
{id:4853,section:"Social Role in a Group",category:"Caretaker",trait:"Boundary-modeling caretaker",desc:"Teaches healthy limits by demonstrating them in their own caretaking.",example:"Care about you. Still going home at a decent hour, though.",intensity:2,rarity:"signature",pol:{}},
{id:4854,section:"Social Role in a Group",category:"Caretaker",trait:"Preventive-caretaker",desc:"Focuses on heading off problems before they require crisis response.",example:"Noticed it early. Fixed it before it became a real issue.",intensity:2,rarity:"signature",pol:{}},
{id:4855,section:"Social Role in a Group",category:"Caretaker",trait:"Inclusive-caretaker",desc:"Extends caretaking specifically to those the group tends to overlook.",example:"Nobody's checking on him. I will.",intensity:2,rarity:"signature",pol:{}},
{id:4856,section:"Social Role in a Group",category:"Caretaker",trait:"Restorative-caretaker",desc:"Specializes in helping people recover after conflict or hardship.",example:"Rough week for everyone. Let's rebuild from here.",intensity:2,rarity:"signature",pol:{}},
{id:4857,section:"Social Role in a Group",category:"Caretaker",trait:"Practical-wisdom caretaker",desc:"Cares for others by sharing hard-won, practical knowledge.",example:"Learned this the hard way. Sharing it so you don't have to.",intensity:2,rarity:"signature",pol:{}},
{id:4858,section:"Social Role in a Group",category:"Caretaker",trait:"Quiet-vigil caretaker",desc:"Sits with people through difficult nights without needing to fix anything.",example:"Not here to solve it. Just here so you're not alone with it.",intensity:2,rarity:"signature",pol:{}},
{id:4859,section:"Social Role in a Group",category:"Skeptic",trait:"Track-record skeptic",desc:"Bases trust entirely on demonstrated past reliability, nothing else.",example:"Talk's cheap. Show me the actual record.",intensity:2,rarity:"signature",pol:{}},
{id:4860,section:"Social Role in a Group",category:"Skeptic",trait:"Cross-examining skeptic",desc:"Questions claims through careful, methodical follow-up questioning.",example:"And how exactly do you know that? Walk me through it.",intensity:3,rarity:"signature",pol:{}},
{id:4861,section:"Social Role in a Group",category:"Skeptic",trait:"Too-convenient skeptic",desc:"Specifically distrusts explanations that fit a little too neatly.",example:"Bit too tidy, that story. Everything lining up just right.",intensity:3,rarity:"signature",pol:{}},
{id:4862,section:"Social Role in a Group",category:"Skeptic",trait:"Withheld-belief skeptic",desc:"Delays forming an opinion until genuinely sufficient evidence exists.",example:"Not deciding yet. Don't have enough to decide on.",intensity:2,rarity:"signature",pol:{}},
{id:4863,section:"Social Role in a Group",category:"Skeptic",trait:"Source-scrutinizing skeptic",desc:"Evaluates claims based heavily on who's making them and why.",example:"Who told you that, and what do they get out of you believing it?",intensity:2,rarity:"signature",pol:{}},
{id:4864,section:"Social Role in a Group",category:"Skeptic",trait:"Quiet-dissent skeptic",desc:"Withholds public agreement while privately reserving real doubt.",example:"(nods along publicly; asks the hard questions privately, later)",intensity:2,rarity:"signature",pol:{}},
{id:4865,section:"Social Role in a Group",category:"Skeptic",trait:"Proof-demanding skeptic",desc:"Will not act on a claim without independently verifiable proof.",example:"Not moving on this until I've seen it myself.",intensity:2,rarity:"common",pol:{}},
{id:4866,section:"Social Role in a Group",category:"Skeptic",trait:"Institution-testing skeptic",desc:"Specifically probes official accounts for inconsistency or convenient gaps.",example:"Official story's got a hole in it. Right there.",intensity:3,rarity:"signature",pol:{}},
{id:4867,section:"Social Role in a Group",category:"Skeptic",trait:"Reluctantly-convinced skeptic",desc:"Eventually accepts strong evidence, but only after real resistance.",example:"Fine. Fine, you've actually convinced me. Took some doing.",intensity:2,rarity:"signature",pol:{}},
{id:4868,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Task-substitution avoidant",desc:"Replaces emotional intimacy with acts of practical service instead.",example:"Fixed the roof instead of talking about it. That's my version.",intensity:2,rarity:"signature",pol:{}},
{id:4869,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Emotionally-armored avoidant",desc:"Maintains a consistent, impenetrable calm regardless of relational stress.",example:"(nothing seems to land, not really, not visibly)",intensity:3,rarity:"signature",pol:{}},
{id:4870,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Preemptive-distance avoidant",desc:"Creates distance before a partner can, to control the timing.",example:"Pulling back first. Rather it be my choice.",intensity:3,rarity:"signature",pol:{}},
{id:4871,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Overwork-avoidant",desc:"Uses professional ambition specifically as a socially acceptable excuse for distance.",example:"Can't, working. Always, conveniently, working.",intensity:2,rarity:"signature",pol:{}},
{id:4872,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Rational-framing avoidant",desc:"Explains emotional distance in purely logical, unemotional terms.",example:"Just being practical about this. Not personal.",intensity:2,rarity:"signature",pol:{}},
{id:4873,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Silent-retreat avoidant",desc:"Withdraws from closeness without any explanation or announcement.",example:"(simply isn't as available as before; never says why)",intensity:3,rarity:"signature",pol:{}},
{id:4874,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Mirror-check compulsive",desc:"Checks their own reflection repeatedly before any significant moment.",example:"(one more look, has to be one more look, before going in)",intensity:2,rarity:"signature",pol:{}},
{id:4875,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Salt-over-shoulder ritualist",desc:"Performs small superstitious gestures for luck before risky undertakings.",example:"(a pinch, tossed, before stepping out the door)",intensity:1,rarity:"signature",pol:{}},
{id:4876,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Repeated-goodbye ritualist",desc:"Cannot leave without performing the exact same farewell sequence.",example:"Same three words. Every single time. Has to be those three.",intensity:2,rarity:"signature",pol:{}},
{id:4877,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Object-return compulsive",desc:"Must return borrowed or moved items to their exact original position.",example:"Has to go back exactly there. Not close. Exactly.",intensity:2,rarity:"signature",pol:{}},
{id:4878,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Pre-sleep ritual performer",desc:"Requires a fixed, unvarying sequence of actions before sleep is possible.",example:"Can't sleep till it's done. All of it, in order.",intensity:2,rarity:"signature",pol:{}},
{id:4879,section:"Social Role in a Group",category:"Peacemaker",trait:"Timing-sensitive peacemaker",desc:"Waits for exactly the right moment to intervene in brewing conflict.",example:"Not yet. Let it breathe a second. Now.",intensity:2,rarity:"signature",pol:{}},
{id:4880,section:"Social Role in a Group",category:"Peacemaker",trait:"Multi-party mediator",desc:"Specializes in resolving conflicts involving more than two sides at once.",example:"Three of you disagree, three different ways. Let's untangle this.",intensity:3,rarity:"signature",pol:{}},
{id:4881,section:"Social Role in a Group",category:"Peacemaker",trait:"Ego-preserving peacemaker",desc:"Resolves conflict specifically in ways that let everyone save face.",example:"Nobody has to be wrong here. Just different, that's all.",intensity:2,rarity:"signature",pol:{}},
{id:4882,section:"Social Role in a Group",category:"Peacemaker",trait:"Long-term-relationship peacemaker",desc:"Prioritizes preserving the relationship over winning the immediate dispute.",example:"Don't care who's right today. Care that we're fine tomorrow.",intensity:2,rarity:"signature",pol:{}},
{id:4883,section:"Social Role in a Group",category:"Instigator",trait:"Comfort-puncturing instigator",desc:"Specifically targets complacent, self-satisfied group dynamics.",example:"Everyone's very pleased with themselves lately, aren't they.",intensity:2,rarity:"signature",pol:{}},
{id:4884,section:"Social Role in a Group",category:"Instigator",trait:"Question-everything instigator",desc:"Provokes by relentlessly questioning assumptions everyone else accepts.",example:"Why do we actually believe that, though?",intensity:2,rarity:"signature",pol:{}},
{id:4885,section:"Social Role in a Group",category:"Instigator",trait:"Underdog-stirring instigator",desc:"Deliberately provokes on behalf of someone the group has overlooked.",example:"Nobody's said his name all meeting. Curious, that.",intensity:3,rarity:"signature",pol:{}},
{id:4886,section:"Social Role in a Group",category:"Instigator",trait:"Silence-breaking instigator",desc:"Says the thing everyone's privately thinking but nobody will voice.",example:"We're all thinking it. I'll just say it.",intensity:3,rarity:"signature",pol:{}},
{id:4887,section:"Attachment & Intimacy Style",category:"Secure",trait:"Grounded-in-self secure",desc:"Maintains a stable sense of identity independent of relationship status.",example:"Know who I am whether you're here or not.",intensity:2,rarity:"signature",pol:{}},
{id:4888,section:"Attachment & Intimacy Style",category:"Secure",trait:"Assumption-checking secure",desc:"Verifies rather than assumes when uncertain about a partner's intent.",example:"Not sure what you meant. Going to just ask, rather than guess.",intensity:1,rarity:"signature",pol:{}},
{id:4889,section:"Attachment & Intimacy Style",category:"Secure",trait:"Warm-under-conflict secure",desc:"Maintains genuine warmth even during active disagreement.",example:"Still love you. Still think you're wrong about this, though.",intensity:2,rarity:"signature",pol:{}},
{id:4890,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Overthinking-replay anxious",desc:"Replays conversations repeatedly, searching for hidden negative meaning.",example:"What did that pause mean? Keep going over it.",intensity:3,rarity:"signature",pol:{}},
{id:4891,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Validation-loop anxious",desc:"Needs repeated confirmation of love that never quite feels sufficient.",example:"Said it already. Need to hear it again, though.",intensity:3,rarity:"signature",pol:{}},
{id:4892,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Distance-panicking anxious",desc:"Experiences even small, normal separations as acutely distressing.",example:"Just a weekend apart. Feels like much longer than that.",intensity:3,rarity:"signature",pol:{}},
{id:4893,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Conversation-ending fleer",desc:"Abruptly ends conversations the moment they turn toward conflict.",example:"We're done talking about this. Done.",intensity:3,rarity:"signature",pol:{}},
{id:4894,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Physical-symptom fleer",desc:"Develops sudden, convenient physical discomfort right as conflict looms.",example:"Not feeling well, actually. Have to go lie down.",intensity:2,rarity:"signature",pol:{}},
{id:4895,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Correspondence-formal courteous",desc:"Maintains proper etiquette even in informal written communication.",example:"Dear Sir — I hope this letter finds you well.",intensity:1,rarity:"signature",pol:{}},
{id:4896,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Gracious-under-pressure courteous",desc:"Maintains full courtesy even while under real personal stress.",example:"(still says please and thank you, mid-crisis)",intensity:2,rarity:"signature",pol:{}},
{id:4897,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Unfiltered-observation rude",desc:"States crude observations about others aloud, unprompted.",example:"You've gone grey early, haven't you.",intensity:2,rarity:"signature",pol:{}},
{id:4898,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Meal-monopolizing rude",desc:"Takes more than their share at shared meals without noticing.",example:"(reaches for the last portion without offering it around)",intensity:2,rarity:"signature",pol:{}},
{id:4899,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Mood-driven scheduler undisciplined",desc:"Rearranges plans entirely based on how they're feeling that day.",example:"Don't feel like it today. Not doing it today, then.",intensity:2,rarity:"signature",pol:{}},
{id:4900,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Instant-purchase undisciplined",desc:"Buys on impulse the moment something catches their eye.",example:"Saw it. Wanted it. Bought it. That's the whole process.",intensity:2,rarity:"common",pol:{}},
{id:4901,section:"Humor Style",category:"Self-Deprecating",trait:"Backhanded-self-praise comic",desc:"Compliments themselves in a way that's actually self-mockery.",example:"Genuinely impressive how consistently I mess this up.",intensity:2,rarity:"signature",pol:{}},
{id:4902,section:"Humor Style",category:"Self-Deprecating",trait:"Worst-case self-joker",desc:"Jokes about themselves ending up in the worst possible outcome.",example:"Watch, I'll be the one who trips into the well.",intensity:2,rarity:"common",pol:{}},
{id:4903,section:"Humor Style",category:"Cruel & Barbed",trait:"Public-record cruelty",desc:"Brings up someone's past failures publicly for comedic humiliation.",example:"Remember when he tried that? We all remember.",intensity:4,rarity:"signature",pol:{}},
{id:4904,section:"Humor Style",category:"Cruel & Barbed",trait:"Weakness-targeting cruel",desc:"Aims jokes precisely at someone's known insecurity.",example:"Still worried people don't respect you? Ha, funny that.",intensity:4,rarity:"signature",pol:{}},
{id:4905,section:"Habits & Vices",category:"Risk & Escape",trait:"Escape-through-recklessness",desc:"Uses genuinely dangerous behavior as a coping mechanism for pain.",example:"Don't feel much when I'm up there. That's sort of the point.",intensity:4,rarity:"signature",pol:{}},
{id:4906,section:"Habits & Vices",category:"Risk & Escape",trait:"All-in gambler",desc:"Consistently commits everything to a single risky bet rather than hedging.",example:"Not doing half-measures. All of it, or none of it.",intensity:3,rarity:"signature",pol:{}},
{id:4907,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Minimal-movement preferring",desc:"Structures the day specifically to require the least possible motion.",example:"Everything's within arm's reach. On purpose.",intensity:2,rarity:"signature",pol:{}},
{id:4908,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Story-pivot phrase user",desc:"Uses 'which reminds me' to pivot into a tangential story.",example:"Which reminds me, actually, of something else entirely.",intensity:2,rarity:"common",pol:{}},
{id:4909,section:"Humor Style",category:"Absurd & Chaotic",trait:"Reality-bending comic",desc:"Describes mundane events as though physically impossible things occurred.",example:"The chair simply refused to be sat in. We negotiated.",intensity:2,rarity:"signature",pol:{}},
{id:4910,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Micromanaging-from-insecurity",desc:"Controls small details obsessively to compensate for underlying self-doubt.",example:"Has to be exactly right. Can't explain why it matters so much.",intensity:3,rarity:"signature",pol:{}},
{id:4911,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Reflexive-counterpoint giver",desc:"Automatically generates the opposing view to whatever's just been said.",example:"Interesting. Here's the other side of that, though.",intensity:2,rarity:"signature",pol:{}},
{id:4912,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Body-first decision maker",desc:"Trusts physical sensation over reasoned analysis when deciding.",example:"Stomach says no. That's usually enough for me.",intensity:2,rarity:"signature",pol:{}},
{id:4913,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Boundary-enforcing fighter",desc:"Fights specifically and only when a stated personal limit is crossed.",example:"Said don't. You did. Now we have a problem.",intensity:3,rarity:"signature",pol:{}},
{id:4914,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Mixed-signal disorganized",desc:"Simultaneously communicates both wanting and fearing closeness.",example:"Come closer. Not too close, though. I don't know. Just — closer.",intensity:4,rarity:"signature",pol:{}},
{id:4915,section:"Humor Style",category:"Dry & Deadpan",trait:"Contextless deadpan",desc:"Delivers absurd statements with zero framing, leaving the listener to work it out.",example:"We're out of rope. And also, I saw a ghost. Anyway, rope.",intensity:2,rarity:"signature",pol:{}},
{id:4916,section:"Humor Style",category:"Humorless & Absent",trait:"Joke-explaining humorless",desc:"Responds to jokes by earnestly explaining why they're inaccurate or illogical.",example:"That couldn't actually happen. Horses don't do that.",intensity:2,rarity:"signature",pol:{}},
{id:4917,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Point-restater",desc:"Says the same point again in slightly different words, unprompted.",example:"It's over. Finished. Really and truly finished.",intensity:2,rarity:"common",pol:{}},
{id:4918,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Story-looper",desc:"Returns to the same anecdote repeatedly across a conversation.",example:"As I was saying earlier about my sister's wedding—",intensity:2,rarity:"signature",pol:{}},
{id:4919,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Question-repeater",desc:"Asks the same question again shortly after getting an answer.",example:"So, wait, when exactly is it due again?",intensity:2,rarity:"common",pol:{}},
{id:4920,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Circular-argument builder",desc:"Ends up back at their starting point after a long explanation.",example:"So basically — which is what I said at the start.",intensity:2,rarity:"signature",pol:{}},
{id:4921,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Catchphrase user",desc:"Falls back on the same fixed phrase in many different contexts.",example:"Well, that's how it goes, isn't it.",intensity:1,rarity:"common",pol:{}},
{id:4922,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Echo-agreement giver",desc:"Repeats back the last thing said as confirmation before responding.",example:"Leaving at six. Leaving at six, got it.",intensity:1,rarity:"common",pol:{}},
{id:4923,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Worry-looper",desc:"Returns compulsively to the same anxious topic throughout a talk.",example:"Anyway — but what if the bridge doesn't hold, though?",intensity:3,rarity:"signature",pol:{}},
{id:4924,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Retelling-with-variation speaker",desc:"Tells the same story multiple times, each slightly embellished.",example:"(the fish gets bigger each time the story's told)",intensity:2,rarity:"signature",pol:{}},
{id:4925,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Habitual-summary giver",desc:"Recaps the same information repeatedly even when unnecessary.",example:"So to summarize what I just summarized—",intensity:2,rarity:"signature",pol:{}},
{id:4926,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Refrain-user",desc:"Returns to a fixed phrase at the end of every point, like a refrain.",example:"—and that's the truth of it. That's the truth of it.",intensity:2,rarity:"signature",pol:{}},
{id:4927,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Obsessive-detail looper",desc:"Circles back to one specific detail again and again.",example:"But the DOOR was locked. I keep coming back to the door.",intensity:3,rarity:"signature",pol:{}},
{id:4928,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Nervous-repetition speaker",desc:"Repeats reassurances to themselves aloud under stress.",example:"It's fine, it's fine, it's fine.",intensity:3,rarity:"common",pol:{}},
{id:4929,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Self-quoting looper",desc:"Quotes their own earlier statement back verbatim later in conversation.",example:"Like I said before — and I'll say it again—",intensity:1,rarity:"signature",pol:{}},
{id:4930,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Grief-loop speaker",desc:"Returns unconsciously to the same memory throughout a conversation about loss.",example:"(keeps circling back to the same afternoon, unprompted)",intensity:4,rarity:"signature",pol:{}},
{id:4931,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Ritual-phrase repeater",desc:"Uses the exact same words to open or close every exchange.",example:"Right then. Same as always. Off we go.",intensity:1,rarity:"common",pol:{}},
{id:4932,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Argument-recycler",desc:"Reuses the same argument in a new dispute without noticing the repetition.",example:"This is exactly what I said last time, too.",intensity:2,rarity:"signature",pol:{}},
{id:4933,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Instruction-looper",desc:"Repeats the same instruction multiple times to ensure it lands.",example:"Left at the fork. Remember — left, not right. Left.",intensity:2,rarity:"common",pol:{}},
{id:4934,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Full-circle storyteller",desc:"Structures long stories so the ending deliberately echoes the opening line.",example:"And that — just like I said at the start — is how it ends.",intensity:2,rarity:"signature",pol:{}},
{id:4935,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Past-anchored speaker",desc:"Frames most conversation in terms of what already happened.",example:"Used to be different. Everything used to be different.",intensity:2,rarity:"common",pol:{}},
{id:4936,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Future-anchored speaker",desc:"Frames most conversation in terms of what's still to come.",example:"Once this is done, once we're through it, then—",intensity:2,rarity:"common",pol:{}},
{id:4937,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Present-only speaker",desc:"Speaks almost exclusively about right now, rarely past or future.",example:"This. Right now. That's what matters.",intensity:2,rarity:"signature",pol:{}},
{id:4938,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Historical-present user",desc:"Narrates past events using present tense for immediacy.",example:"So he walks in, and he just STARES at me.",intensity:2,rarity:"signature",pol:{}},
{id:4939,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Hypothetical-future speaker",desc:"Frequently speaks in conditional, not-yet-real future terms.",example:"If it happens. When it happens, maybe.",intensity:2,rarity:"common",pol:{}},
{id:4940,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Nostalgia-laced speaker",desc:"Colors present description with wistful reference to how things were.",example:"Not like it used to be. Nothing is, really.",intensity:3,rarity:"signature",pol:{}},
{id:4941,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Timeless-statement speaker",desc:"Frames observations as permanently, universally true rather than situational.",example:"That's just how people are. Always have been.",intensity:2,rarity:"signature",pol:{}},
{id:4942,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Immediate-past reporter",desc:"Consistently reports events as having just happened, moments ago.",example:"Just left. Not five minutes ago.",intensity:1,rarity:"common",pol:{}},
{id:4943,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Distant-past invoker",desc:"References events from long ago as though still vividly present.",example:"Forty years on and I still see it clear as day.",intensity:3,rarity:"signature",pol:{}},
{id:4944,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Countdown speaker",desc:"Frames upcoming events in terms of time remaining until they occur.",example:"Three days. Three days and it's done.",intensity:2,rarity:"signature",pol:{}},
{id:4945,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Anniversary-tracker",desc:"Marks time by recurring dates and their significance.",example:"Same day it happened, every year, this week.",intensity:2,rarity:"signature",pol:{}},
{id:4946,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Tense-shifting narrator",desc:"Slides between past and present tense mid-story without noticing.",example:"So we left — and now we're at the gate, and—",intensity:2,rarity:"signature",pol:{}},
{id:4947,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Deadline-obsessed speaker",desc:"Frames nearly everything in terms of time pressure and limits.",example:"By Friday. Has to be by Friday, or it's over.",intensity:3,rarity:"signature",pol:{}},
{id:4948,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Generational-time speaker",desc:"Frames events across timescales of decades or lifetimes.",example:"My grandfather saw this happen once too.",intensity:2,rarity:"signature",pol:{}},
{id:4949,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Momentary speaker",desc:"Emphasizes fleeting, temporary nature of the current situation.",example:"Just for now. Won't be like this forever.",intensity:2,rarity:"signature",pol:{}},
{id:4950,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Regretful-past speaker",desc:"Frequently references past choices with visible regret in phrasing.",example:"Should have. Should have done it differently.",intensity:3,rarity:"signature",pol:{}},
{id:4951,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Perpetual-present speaker",desc:"Describes ongoing habitual states as an unchanging now.",example:"This is just how it is. Every day. Still.",intensity:2,rarity:"common",pol:{}},
{id:4952,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Anticipatory speaker",desc:"Speaks about future events as though already partly experiencing them.",example:"I can already feel how good that's going to be.",intensity:2,rarity:"signature",pol:{}},
{id:4953,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Word-doubling speaker",desc:"Doubles a single word for emphasis rather than using an intensifier.",example:"Big, big trouble.",intensity:2,rarity:"common",pol:{}},
{id:4954,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Question-echo responder",desc:"Repeats a question back before answering it.",example:"Am I sure? Am I sure. Yes.",intensity:1,rarity:"common",pol:{}},
{id:4955,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Triadic-repeater",desc:"Structures key statements in groups of three for rhetorical weight.",example:"Never. Not now. Not ever.",intensity:2,rarity:"signature",pol:{}},
{id:4956,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Call-and-response structurer",desc:"Builds dialogue with a repeated call-and-response rhythm.",example:"Are we ready? — We're ready. Are we sure? — We're sure.",intensity:2,rarity:"signature",pol:{}},
{id:4957,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Anaphoric opener",desc:"Begins consecutive sentences with the same word or phrase.",example:"I will not lie. I will not hide. I will not run.",intensity:2,rarity:"signature",pol:{}},
{id:4958,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Confirmation-echo user",desc:"Repeats the last word of what someone else said before responding.",example:"'—gone.' Gone. Since when?",intensity:1,rarity:"common",pol:{}},
{id:4959,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Emphatic-doubling speaker",desc:"Repeats a key phrase back-to-back for dramatic emphasis.",example:"No. No. I said no.",intensity:3,rarity:"common",pol:{}},
{id:4960,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Mirrored-structure responder",desc:"Answers using the exact grammatical structure of the question asked.",example:"Are you coming? I am coming.",intensity:1,rarity:"signature",pol:{}},
{id:4961,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Refrain-closer",desc:"Closes multiple points in a conversation with the identical short phrase.",example:"And that's that. And that's that.",intensity:1,rarity:"signature",pol:{}},
{id:4962,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Chant-like repeater",desc:"Falls into a rhythmic, repeated phrase under stress or excitement.",example:"Go, go, go, go—",intensity:3,rarity:"signature",pol:{}},
{id:4963,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Verbatim-quote repeater",desc:"Repeats someone's exact words back to challenge or confirm them.",example:"You said 'never.' Those exact words. Never.",intensity:2,rarity:"signature",pol:{}},
{id:4964,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Escalating-repeat speaker",desc:"Repeats a phrase with rising intensity each time.",example:"Stop. STOP. I SAID STOP.",intensity:3,rarity:"signature",pol:{}},
{id:4965,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Name-repeating speaker",desc:"Uses a person's name multiple times within a single utterance.",example:"Martha. Martha, listen to me. Martha.",intensity:2,rarity:"signature",pol:{}},
{id:4966,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Structural-echo builder",desc:"Repeats sentence structure across a paragraph for rhythmic effect.",example:"We built this. We lost this. We'll rebuild this.",intensity:2,rarity:"signature",pol:{}},
{id:4967,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Reassurance-loop speaker",desc:"Repeats a comforting phrase multiple times in succession.",example:"You're safe. You're safe. You're safe now.",intensity:2,rarity:"common",pol:{}},
{id:4968,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"List-repetition user",desc:"Repeats a list's items a second time for retention or emphasis.",example:"Rope, water, bread — rope, water, bread — don't forget it.",intensity:1,rarity:"signature",pol:{}},
{id:4969,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Denial-repeater",desc:"Repeats a denial multiple times with mounting insistence.",example:"Wasn't me. Wasn't me. It wasn't me.",intensity:3,rarity:"signature",pol:{}},
{id:4970,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Gentle-echo comforter",desc:"Softly repeats what someone said back to them to show they were heard.",example:"You're scared. I hear you. You're scared.",intensity:1,rarity:"signature",pol:{}},
{id:4971,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Collar-straightener",desc:"Straightens their own collar reflexively before important moments.",example:"(adjusts the collar, once, before walking in)",intensity:1,rarity:"common",pol:{}},
{id:4972,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Cuff-checker",desc:"Checks and adjusts cuffs repeatedly during conversation.",example:"(tugs the cuff level, again, without noticing)",intensity:1,rarity:"signature",pol:{}},
{id:4973,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Hair-tucker",desc:"Tucks loose hair behind an ear when nervous or thinking.",example:"(tucks the same strand back, again)",intensity:1,rarity:"common",pol:{}},
{id:4974,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Button-fiddler",desc:"Fidgets with a coat or shirt button during tense exchanges.",example:"(thumb worries the top button, unconsciously)",intensity:1,rarity:"signature",pol:{}},
{id:4975,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Immaculate-presentation keeper",desc:"Maintains flawless, unwrinkled appearance regardless of circumstance.",example:"(not a hair out of place, even after the chase)",intensity:2,rarity:"signature",pol:{}},
{id:4976,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Deliberately-disheveled presenter",desc:"Maintains a carefully curated appearance of not caring about appearance.",example:"(the careless look took twenty minutes to arrange)",intensity:2,rarity:"signature",pol:{}},
{id:4977,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Jewelry-toucher",desc:"Touches a ring, necklace, or watch when thinking or anxious.",example:"(thumb finds the ring, turns it, thinking)",intensity:1,rarity:"signature",pol:{}},
{id:4978,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Sleeve-roller",desc:"Rolls up sleeves deliberately before undertaking serious work.",example:"(rolls both sleeves, methodically, before starting)",intensity:1,rarity:"common",pol:{}},
{id:4979,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Posture-conscious dresser",desc:"Adjusts clothing specifically to maintain a commanding silhouette.",example:"(straightens the coat, squares the shoulders, before entering)",intensity:2,rarity:"signature",pol:{}},
{id:4980,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Scent-conscious presenter",desc:"Notably, consistently wears the same distinctive scent.",example:"(you'd know they'd been in the room minutes after they left)",intensity:1,rarity:"signature",pol:{}},
{id:4981,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Shabby-comfort dresser",desc:"Prioritizes comfort over presentation, visibly and unapologetically.",example:"(same worn coat, every day, doesn't care who notices)",intensity:2,rarity:"common",pol:{}},
{id:4982,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Mirror-avoider",desc:"Visibly avoids their own reflection in mirrors and windows.",example:"(looks away from the glass, every time, without explaining why)",intensity:2,rarity:"signature",pol:{}},
{id:4983,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Grooming-ritual keeper",desc:"Follows an elaborate, unvarying grooming routine before any appearance.",example:"(the same forty-minute routine, without fail, every morning)",intensity:2,rarity:"signature",pol:{}},
{id:4984,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Practical-hands dresser",desc:"Chooses clothing entirely for function, indifferent to appearance.",example:"Pockets. That's the only thing that matters to me.",intensity:1,rarity:"common",pol:{}},
{id:4985,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Borrowed-item wearer",desc:"Habitually wears or carries an item that visibly belonged to someone else.",example:"(the coat's two sizes too big; was his father's)",intensity:2,rarity:"signature",pol:{}},
{id:4986,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Status-signaling dresser",desc:"Deliberately dresses to project rank or wealth beyond their means.",example:"(the coat's rented, but nobody here knows that)",intensity:2,rarity:"signature",pol:{}},
{id:4987,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Fidget-with-hem",desc:"Worries at a hem or seam when uncomfortable in conversation.",example:"(picks at the loose thread, doesn't look up)",intensity:1,rarity:"signature",pol:{}},
{id:4988,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Weather-defiant dresser",desc:"Wears the same outfit regardless of climate or occasion, on principle.",example:"Cold or not, this is what I wear.",intensity:1,rarity:"signature",pol:{}},
{id:4989,section:"Social Role in a Group",category:"Connector",trait:"Network-builder connector",desc:"Actively introduces people across otherwise separate social circles.",example:"You two should really meet. Different worlds, same problem.",intensity:2,rarity:"common",pol:{}},
{id:4990,section:"Social Role in a Group",category:"Connector",trait:"Information-broker connector",desc:"Serves as the hub through which news travels across a group.",example:"Haven't you heard? I'll catch you up on everything.",intensity:2,rarity:"signature",pol:{}},
{id:4991,section:"Social Role in a Group",category:"Connector",trait:"Bridge-building connector",desc:"Specifically links factions that wouldn't otherwise interact.",example:"I know people on both sides. Let me set something up.",intensity:2,rarity:"signature",pol:{}},
{id:4992,section:"Social Role in a Group",category:"Connector",trait:"Favor-facilitating connector",desc:"Connects people who can solve each other's problems.",example:"He needs a carpenter. You need work. Perfect.",intensity:2,rarity:"common",pol:{}},
{id:4993,section:"Social Role in a Group",category:"Connector",trait:"Reunion-orchestrator connector",desc:"Actively works to reconnect people who've drifted apart.",example:"Been years since you two spoke. Let's fix that.",intensity:2,rarity:"signature",pol:{}},
{id:4994,section:"Social Role in a Group",category:"Connector",trait:"Cross-generational connector",desc:"Bridges older and younger members of a community deliberately.",example:"The old ways matter. So does what they're building now. Both.",intensity:2,rarity:"signature",pol:{}},
{id:4995,section:"Social Role in a Group",category:"Connector",trait:"Resource-connecting connector",desc:"Links people to tools, opportunities, or resources they need.",example:"Know exactly who has what you're looking for.",intensity:1,rarity:"signature",pol:{}},
{id:4996,section:"Social Role in a Group",category:"Connector",trait:"Event-organizing connector",desc:"Creates gatherings specifically designed to bring disparate people together.",example:"Everyone's invited. That's rather the point.",intensity:2,rarity:"common",pol:{}},
{id:4997,section:"Social Role in a Group",category:"Connector",trait:"Trust-vouching connector",desc:"Facilitates new relationships by personally vouching for both parties.",example:"He's good people. You can trust him. I'll say so myself.",intensity:2,rarity:"signature",pol:{}},
{id:4998,section:"Social Role in a Group",category:"Connector",trait:"Quiet-matchmaker connector",desc:"Subtly arranges circumstances for two people to meet without announcing it.",example:"(mentions the market to both, on the same day, separately)",intensity:2,rarity:"signature",pol:{}},
{id:4999,section:"Social Role in a Group",category:"Connector",trait:"Community-memory connector",desc:"Keeps track of who knows whom across an entire community.",example:"Ask her. No — actually, ask him, he'd know better.",intensity:1,rarity:"signature",pol:{}},
{id:5000,section:"Social Role in a Group",category:"Connector",trait:"Cross-border connector",desc:"Maintains relationships across otherwise hostile or separate groups.",example:"Talk to people on both sides. Someone has to.",intensity:3,rarity:"signature",pol:{}},
{id:5001,section:"Social Role in a Group",category:"Connector",trait:"Skill-matching connector",desc:"Pairs people's specific abilities with where they're actually needed.",example:"You're wasted doing that. Let me put you where you're needed.",intensity:2,rarity:"signature",pol:{}},
{id:5002,section:"Social Role in a Group",category:"Connector",trait:"Reputation-building connector",desc:"Actively promotes others' skills and character to the wider group.",example:"You should hear what she can do. Really, you should.",intensity:1,rarity:"common",pol:{}},
{id:5003,section:"Social Role in a Group",category:"Connector",trait:"Silent-network connector",desc:"Maintains an extensive web of contacts without advertising the fact.",example:"(knows exactly who to call; never mentions how)",intensity:2,rarity:"signature",pol:{}},
{id:5004,section:"Social Role in a Group",category:"Connector",trait:"Newcomer-integrating connector",desc:"Specifically works to fold new arrivals into the existing social fabric.",example:"Come, let me introduce you around properly.",intensity:1,rarity:"common",pol:{}},
{id:5005,section:"Social Role in a Group",category:"Connector",trait:"Long-distance connector",desc:"Maintains and activates relationships across significant physical distance.",example:"Wrote to an old contact three towns over. She'll help.",intensity:2,rarity:"signature",pol:{}},
{id:5006,section:"Social Role in a Group",category:"Connector",trait:"Alliance-brokering connector",desc:"Facilitates formal cooperation agreements between separate parties.",example:"Both of you want the same thing, really. Let's talk terms.",intensity:2,rarity:"signature",pol:{}},
{id:5007,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Better-world believer",desc:"Genuinely believes sustained effort can meaningfully improve the world.",example:"It can be better than this. I actually believe that.",intensity:2,rarity:"common",pol:{}},
{id:5008,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Principle-over-precedent idealist",desc:"Judges situations by what should be true, not what's always been done.",example:"Doesn't matter how it's always been done. What SHOULD it be?",intensity:2,rarity:"signature",pol:{}},
{id:5009,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Future-generations idealist",desc:"Makes present sacrifices explicitly for people not yet born.",example:"Not doing this for us. Doing it for whoever comes after.",intensity:3,rarity:"signature",pol:{}},
{id:5010,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Radical-fairness idealist",desc:"Holds an uncompromising vision of what genuine fairness looks like.",example:"Not close to fair. Not going to pretend it is.",intensity:3,rarity:"signature",pol:{}},
{id:5011,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Movement-devoted idealist",desc:"Commits their life to advancing a cause bigger than themselves.",example:"This matters more than any one of us. Including me.",intensity:3,rarity:"signature",pol:{}},
{id:5012,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Utopian-planner idealist",desc:"Actively designs concrete plans toward an admittedly distant ideal.",example:"Won't happen tomorrow. Here's the first real step, though.",intensity:2,rarity:"signature",pol:{}},
{id:5013,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Uncompromising-vision idealist",desc:"Refuses to dilute their vision even when compromise would be easier.",example:"Watered down isn't the vision. I'm not doing watered down.",intensity:3,rarity:"signature",pol:{}},
{id:5014,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Inspirational idealist",desc:"Speaks in ways that make others genuinely believe change is possible.",example:"We can actually do this. I mean that. We can.",intensity:2,rarity:"common",pol:{}},
{id:5015,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Justice-first idealist",desc:"Prioritizes what's genuinely right over what's convenient or safe.",example:"Convenient and right aren't the same thing. Choosing right.",intensity:3,rarity:"signature",pol:{}},
{id:5016,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Reform-minded idealist",desc:"Believes existing systems can and should be substantially improved.",example:"The system's broken. Doesn't mean it can't be fixed.",intensity:2,rarity:"signature",pol:{}},
{id:5017,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Self-sacrificing idealist",desc:"Willingly accepts personal loss in service of a larger ideal.",example:"Costs me plenty. Worth it for what we're building.",intensity:3,rarity:"signature",pol:{}},
{id:5018,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Hope-anchored idealist",desc:"Explicitly names hope in a better future as their core motivation.",example:"Keep going because I believe it gets better. Actually believe it.",intensity:2,rarity:"common",pol:{}},
{id:5019,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Purity-of-cause idealist",desc:"Refuses to let the cause be compromised by expedient allies.",example:"Not partnering with them. Not even for this. Not worth it.",intensity:3,rarity:"signature",pol:{}},
{id:5020,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Legacy-idealist",desc:"Frames present action in terms of the world it will leave behind.",example:"What we do now, someone inherits. Want it to be good.",intensity:2,rarity:"signature",pol:{}},
{id:5021,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Convert-through-conviction idealist",desc:"Changes minds through the sheer sincerity of their belief.",example:"(nobody agreed at first; nobody disagrees by the end)",intensity:2,rarity:"signature",pol:{}},
{id:5022,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Impossible-standard idealist",desc:"Holds a vision so ambitious most consider it genuinely impossible.",example:"They said it couldn't be done. Doesn't mean we stop trying.",intensity:3,rarity:"signature",pol:{}},
{id:5023,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Community-visioning idealist",desc:"Believes collective effort, not individual heroics, achieves real change.",example:"Not one person's doing. All of us, together, or not at all.",intensity:2,rarity:"signature",pol:{}},
{id:5024,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Undeterred idealist",desc:"Maintains their vision fully intact despite repeated setbacks.",example:"Failed twice. Vision hasn't changed. Trying again.",intensity:3,rarity:"signature",pol:{}},
{id:5025,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Pun-compulsive wordplayer",desc:"Cannot resist a pun, however groan-worthy, in almost any context.",example:"I'm not lion, that joke was purr-fect.",intensity:1,rarity:"common",pol:{}},
{id:5026,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Etymological wordplayer",desc:"Jokes built on the surprising origins or double meanings of words.",example:"'Salary' comes from salt — so I'm literally worth my salt.",intensity:2,rarity:"signature",pol:{}},
{id:5027,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Callback humorist",desc:"Constructs jokes that pay off a setup made much earlier.",example:"Remember the goose from Tuesday? Well.",intensity:2,rarity:"signature",pol:{}},
{id:5028,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Reference-layering wordplayer",desc:"Builds jokes on obscure references that reward close listeners.",example:"Careful, or this becomes the Aldren incident all over again.",intensity:2,rarity:"signature",pol:{}},
{id:5029,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Logical-paradox joker",desc:"Delights in jokes built on genuine logical contradiction.",example:"This statement is false. Anyway, dinner?",intensity:2,rarity:"signature",pol:{}},
{id:5030,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Precise-wording humorist",desc:"Finds humor specifically in the exact, technical meaning of words.",example:"Technically, that's not a lie. It's a very confident guess.",intensity:2,rarity:"signature",pol:{}},
{id:5031,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Anagram-and-wordgame player",desc:"Constructs elaborate wordplay from names and phrases on the spot.",example:"'Silent' and 'listen' — same letters. Coincidence? Obviously.",intensity:1,rarity:"signature",pol:{}},
{id:5032,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Double-entendre user",desc:"Constructs jokes with a layered, secondary meaning underneath.",example:"Oh, I meant that in every possible way.",intensity:2,rarity:"signature",pol:{}},
{id:5033,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Socratic-joker",desc:"Uses leading questions to walk someone into their own punchline.",example:"So if that's true, what does that make you, exactly?",intensity:2,rarity:"signature",pol:{}},
{id:5034,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Definitional humorist",desc:"Redefines ordinary words in absurd but internally consistent ways.",example:"A 'quick meeting' is just a lie with a start time.",intensity:2,rarity:"common",pol:{}},
{id:5035,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Meta-joke teller",desc:"Jokes about the structure or mechanics of joke-telling itself.",example:"This is the part where I'd normally have a punchline.",intensity:2,rarity:"signature",pol:{}},
{id:5036,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Erudite-reference humorist",desc:"Builds jokes on historical or literary references most won't catch.",example:"Very Icarus of you, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:5037,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Contradiction-exploiting wordplayer",desc:"Finds comedy in genuinely self-contradictory statements.",example:"I never make mistakes — except for that one, obviously.",intensity:1,rarity:"common",pol:{}},
{id:5038,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Precision-timing wordplayer",desc:"Delivers wordplay with exact comedic timing, never rushed.",example:"(waits exactly the right beat) ...worth the pun, I think.",intensity:2,rarity:"signature",pol:{}},
{id:5039,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Cross-language wordplayer",desc:"Constructs jokes that only work across two languages at once.",example:"In my language, that word means both 'goat' and 'disaster'. Draw conclusions.",intensity:2,rarity:"signature",pol:{}},
{id:5040,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Structural-irony humorist",desc:"Points out the ironic structure of a situation with dry precision.",example:"We built a fireproof shed. It's currently on fire.",intensity:2,rarity:"common",pol:{}},
{id:5041,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Riddle-poser",desc:"Naturally frames observations and jokes as small riddles.",example:"What has four legs in the morning and none by dinner? Don't ask.",intensity:2,rarity:"signature",pol:{}},
{id:5042,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Semantic-trap humorist",desc:"Leads listeners into agreeing with something absurd through careful wording.",example:"So you'd agree a horse-sized duck is technically 'compact'?",intensity:2,rarity:"signature",pol:{}},
{id:5043,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Deadline-brinkmanship procrastinator",desc:"Consistently waits until the absolute last moment to begin anything.",example:"Plenty of time. (There is not plenty of time.)",intensity:3,rarity:"common",pol:{}},
{id:5044,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Busywork-substituting procrastinator",desc:"Fills time with minor unrelated tasks to avoid the important one.",example:"I'll just tidy the desk first. And the shelf. And—",intensity:2,rarity:"common",pol:{}},
{id:5045,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Chronic-postponer",desc:"Defers decisions and tasks indefinitely, rarely with a clear reason.",example:"Later. We'll deal with it later.",intensity:2,rarity:"common",pol:{}},
{id:5046,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Avoidance-through-planning procrastinator",desc:"Endlessly plans a task as a way of never actually starting it.",example:"Just need one more draft of the plan before we begin.",intensity:2,rarity:"signature",pol:{}},
{id:5047,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Difficult-conversation avoider",desc:"Delays hard conversations for as long as humanly possible.",example:"I'll bring it up. Eventually. Soon, probably.",intensity:3,rarity:"signature",pol:{}},
{id:5048,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Task-abandonment procrastinator",desc:"Starts things reliably, quietly stops the moment they get difficult.",example:"Was doing so well. Then it got hard.",intensity:2,rarity:"signature",pol:{}},
{id:5049,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Distraction-seeking avoider",desc:"Actively seeks out anything else to focus on rather than the task at hand.",example:"Wait, is that a bird? Anyway, where was I.",intensity:2,rarity:"common",pol:{}},
{id:5050,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Perfectionism-paralyzed procrastinator",desc:"Delays starting because it won't be done perfectly from the first try.",example:"Not starting until I know exactly how to do it right.",intensity:3,rarity:"signature",pol:{}},
{id:5051,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Emotional-avoidance procrastinator",desc:"Puts off tasks specifically tied to unresolved feelings.",example:"Can't face sorting through that box yet. Not yet.",intensity:3,rarity:"signature",pol:{}},
{id:5052,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Responsibility-deflecting avoider",desc:"Finds reasons the task should fall to someone else instead.",example:"Not really my job, is it? Someone else should handle that.",intensity:2,rarity:"signature",pol:{}},
{id:5053,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Overcommitment avoider",desc:"Says yes to everything specifically to avoid confronting one hard task.",example:"Busy with everything else. Genuinely can't get to that one.",intensity:2,rarity:"signature",pol:{}},
{id:5054,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Sleep-escape procrastinator",desc:"Retreats into excessive sleep specifically to avoid facing obligations.",example:"Just going to lie down for a bit. An hour. Or five.",intensity:2,rarity:"signature",pol:{}},
{id:5055,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Avoidance-through-helping procrastinator",desc:"Takes on others' problems to avoid dealing with their own.",example:"Can't think about my own mess right now, let me help with yours.",intensity:2,rarity:"signature",pol:{}},
{id:5056,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Confrontation-postponing avoider",desc:"Delays addressing conflict specifically until it's unavoidable.",example:"We'll sort it out. Eventually. When we have to.",intensity:2,rarity:"common",pol:{}},
{id:5057,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Habitual-excuse maker",desc:"Reliably generates a fresh reason not to start, every single day.",example:"Tomorrow's better anyway. More time tomorrow.",intensity:2,rarity:"common",pol:{}},
{id:5058,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Overwhelm-freezing avoider",desc:"Becomes unable to start specifically when a task feels too large.",example:"Don't even know where to begin with it. So — haven't.",intensity:3,rarity:"signature",pol:{}},
{id:5059,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Financial-avoidance procrastinator",desc:"Delays looking at money problems until they become unavoidable.",example:"Haven't opened that letter yet. Know what it says, though.",intensity:3,rarity:"signature",pol:{}},
{id:5060,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Health-avoidance procrastinator",desc:"Puts off addressing physical or medical concerns indefinitely.",example:"It's probably nothing. Haven't actually checked, though.",intensity:3,rarity:"signature",pol:{}},
{id:5061,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Compulsive full-loop retracer",desc:"Cannot stop reliving and re-narrating the same story in exhaustive, unbroken detail.",example:"Has to tell it again. All of it. Every single time, start to finish.",intensity:5,rarity:"signature",pol:{}},
{id:5062,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Frozen-in-the-moment speaker",desc:"Speaks as though permanently trapped in the instant of a past trauma.",example:"It's happening. It's still happening. It never stopped happening.",intensity:4,rarity:"signature",pol:{}},
{id:5063,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Time-collapsed speaker",desc:"Experiences and describes past and present as genuinely indistinguishable.",example:"He's not gone. He's right there. He's always right there.",intensity:5,rarity:"signature",pol:{}},
{id:5064,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Obsessive verbatim repeater",desc:"Cannot stop repeating an exact phrase, word for word, dozens of times.",example:"Gone gone gone gone gone gone gone—",intensity:4,rarity:"signature",pol:{}},
{id:5065,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Total-breakdown echo speaker",desc:"Repetition becomes the entire content of speech during acute crisis.",example:"No. No. No no no no no.",intensity:5,rarity:"signature",pol:{}},
{id:5066,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Compulsive-appearance corrector",desc:"Repeatedly, anxiously adjusts appearance to the point of visible distress.",example:"(straightens the same collar six times in a minute, can't stop)",intensity:3,rarity:"signature",pol:{}},
{id:5067,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Total-neglect presenter",desc:"Has stopped attending to appearance entirely, visibly, for some time.",example:"(hasn't changed clothes in days; hasn't noticed)",intensity:4,rarity:"signature",pol:{}},
{id:5068,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Complete-transformation dresser",desc:"Has entirely reinvented their appearance to become unrecognizable.",example:"(nothing about how they look now matches who they were)",intensity:5,rarity:"signature",pol:{}},
{id:5069,section:"Social Role in a Group",category:"Connector",trait:"Master-network connector",desc:"Maintains and actively uses an extraordinarily vast web of relationships.",example:"Know someone everywhere. Genuinely, everywhere.",intensity:4,rarity:"signature",pol:{}},
{id:5070,section:"Social Role in a Group",category:"Connector",trait:"Indispensable-hub connector",desc:"The entire group's cohesion depends almost entirely on this one person.",example:"Take them away and this whole network falls apart.",intensity:5,rarity:"signature",pol:{}},
{id:5071,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Faint-hope idealist",desc:"Holds onto a small, private belief that things could be better, rarely voiced.",example:"Still think it could be different. Don't say it much.",intensity:1,rarity:"common",pol:{}},
{id:5072,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Zealous-cause idealist",desc:"Has subordinated nearly every part of their life to a singular vision.",example:"Everything I have goes to this. Everything.",intensity:4,rarity:"signature",pol:{}},
{id:5073,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Martyr-willing idealist",desc:"Would give their life without hesitation for the ideal they hold.",example:"If it takes that, it takes that. Wouldn't hesitate.",intensity:5,rarity:"signature",pol:{}},
{id:5074,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Elaborate-construction humorist",desc:"Builds a single, extraordinarily intricate wordplay joke over several minutes.",example:"(the pun takes four minutes to set up and is somehow worth it)",intensity:3,rarity:"signature",pol:{}},
{id:5075,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Compulsive-pun machine",desc:"Cannot stop generating puns, layered on top of each other, unstoppably.",example:"That's not just punny — that's a whole pundemic at this point.",intensity:4,rarity:"signature",pol:{}},
{id:5076,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Reality-bending wordplay virtuoso",desc:"Constructs wordplay so dense and layered it becomes genuinely disorienting.",example:"(the joke has four simultaneous meanings; nobody's fully sure which one landed)",intensity:5,rarity:"signature",pol:{}},
{id:5077,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Mild everyday postponer",desc:"Puts off small, low-stakes tasks occasionally, without real consequence.",example:"Get to it eventually. No rush, really.",intensity:1,rarity:"common",pol:{}},
{id:5078,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Life-disrupting avoider",desc:"Avoidance has begun seriously damaging relationships and obligations.",example:"Missed it again. Know it's a problem now. Still can't face it.",intensity:4,rarity:"signature",pol:{}},
{id:5079,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Total-shutdown avoider",desc:"Has become entirely unable to function due to accumulated avoided tasks.",example:"Can't even look at the pile anymore. Any of it.",intensity:5,rarity:"signature",pol:{}},
{id:5080,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Meandering-tangent talker",desc:"Follows every passing thought down its own lengthy detour.",example:"Which reminds me — actually, before that, let me back up—",intensity:3,rarity:"common",pol:{}},
{id:5081,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Justification-piler",desc:"Stacks reason upon reason to defend even uncontested points.",example:"Not just because of that. Also because of this. And this.",intensity:2,rarity:"signature",pol:{}},
{id:5082,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Every-detail includer",desc:"Cannot omit even the most trivial detail from an account.",example:"And the door was blue, not that it matters, but blue.",intensity:2,rarity:"common",pol:{}},
{id:5083,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Emotional-processing-out-loud talker",desc:"Thinks through feelings verbally, at length, whether or not asked.",example:"Okay so I feel — well, first I feel this, then also this—",intensity:3,rarity:"signature",pol:{}},
{id:5084,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Compulsive-context-giver",desc:"Cannot state a fact without first explaining its entire backstory.",example:"To understand this you really need to know what happened first—",intensity:2,rarity:"signature",pol:{}},
{id:5085,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Running-commentary provider",desc:"Narrates ongoing events aloud continuously as they happen.",example:"And now I'm opening it, and now I'm looking inside, and—",intensity:2,rarity:"signature",pol:{}},
{id:5086,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Enthusiastic-list maker",desc:"Turns simple answers into extended, itemized lists.",example:"So many reasons — one, two, three, and honestly four—",intensity:2,rarity:"common",pol:{}},
{id:5087,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Anecdote-stacker",desc:"Follows one story immediately with a second related one.",example:"And that reminds me of another time, actually—",intensity:2,rarity:"signature",pol:{}},
{id:5088,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Circling-back explainer",desc:"Returns repeatedly to add 'oh, and one more thing' to finished points.",example:"Oh, and one more thing — actually, two more things—",intensity:2,rarity:"common",pol:{}},
{id:5089,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Descriptive-overflow talker",desc:"Piles on more descriptive detail than the moment requires.",example:"It was cold, and grey, and quiet, and somehow heavier than usual.",intensity:2,rarity:"signature",pol:{}},
{id:5090,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Necessity-only speaker",desc:"Speaks exactly as much as the situation strictly requires, no more.",example:"Rope's frayed.",intensity:2,rarity:"common",pol:{}},
{id:5091,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Abbreviated-farewell giver",desc:"Ends conversations with the shortest possible closing.",example:"Right. Later.",intensity:1,rarity:"common",pol:{}},
{id:5092,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Cost-conscious talker",desc:"Treats each spoken word as though it carries a real price.",example:"No. Won't.",intensity:3,rarity:"signature",pol:{}},
{id:5093,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Silent-preference speaker",desc:"Prefers a look or gesture to speech whenever one will suffice.",example:"(a raised hand answers it)",intensity:2,rarity:"signature",pol:{}},
{id:5094,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Clipped-consent giver",desc:"Agrees with the shortest possible affirmative.",example:"Yep.",intensity:1,rarity:"common",pol:{}},
{id:5095,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Data-only reporter",desc:"Reduces status updates to bare, essential data points.",example:"Six left. Three hurt.",intensity:2,rarity:"signature",pol:{}},
{id:5096,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"No-elaboration refuser",desc:"Declines to explain reasoning, offering only the bare decision.",example:"That's the decision.",intensity:3,rarity:"common",pol:{}},
{id:5097,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Word-count-conscious speaker",desc:"Visibly measures and restrains their own speech length.",example:"(catches themselves mid-sentence, cuts it short deliberately)",intensity:2,rarity:"signature",pol:{}},
{id:5098,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Wordless-acknowledgment giver",desc:"Responds to most statements with a nod rather than words.",example:"(nods, once, and that's the whole reply)",intensity:2,rarity:"common",pol:{}},
{id:5099,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Terse-verdict deliverer",desc:"States conclusions with zero supporting explanation, ever.",example:"Wrong. Try again.",intensity:3,rarity:"signature",pol:{}},
{id:5100,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Grief-slowed narrator",desc:"Words come heavy and delayed specifically while discussing loss.",example:"It's been — (long pause) — hard. Since.",intensity:3,rarity:"common",pol:{}},
{id:5101,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Threat-quickened speaker",desc:"Speech accelerates sharply the instant real danger is perceived.",example:"Move-move-move-NOW—",intensity:4,rarity:"signature",pol:{}},
{id:5102,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Formal-occasion measured speaker",desc:"Deliberately paces every word during ceremonial moments.",example:"We. Are. Gathered. Here.",intensity:2,rarity:"signature",pol:{}},
{id:5103,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Post-crisis-slowed speaker",desc:"Speech noticeably slows and steadies once immediate danger passes.",example:"(fast through the emergency; slow, careful, once it's over)",intensity:2,rarity:"signature",pol:{}},
{id:5104,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Comfort-eased talker",desc:"Pacing loosens the longer they're with trusted company.",example:"(starts guarded, ends relaxed, an hour into the visit)",intensity:2,rarity:"signature",pol:{}},
{id:5105,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Interrogation-controlled pace",desc:"Deliberately controls tempo to project calm under hostile questioning.",example:"(answers every hostile question at exactly the same measured pace)",intensity:3,rarity:"signature",pol:{}},
{id:5106,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Excitement-tumbling speaker",desc:"Words tumble out faster and faster as genuine excitement builds.",example:"And then — and THEN — you won't believe—",intensity:2,rarity:"common",pol:{}},
{id:5107,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Confession-rushed talker",desc:"Rushes through hard admissions to get the difficult part over fast.",example:"Iditit'smyfaultI'msorry—",intensity:4,rarity:"signature",pol:{}},
{id:5108,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Deadline-accelerating speaker",desc:"Gets visibly faster in speech the closer a deadline approaches.",example:"Ten minutes. Nine. We need to move faster than this.",intensity:3,rarity:"signature",pol:{}},
{id:5109,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Exhaustion-slowed speaker",desc:"Pacing drags and flattens under accumulated fatigue.",example:"Just — (slow) — give me a moment. Just a moment.",intensity:3,rarity:"common",pol:{}},
{id:5110,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Diplomatic-cable phraser",desc:"Frames blunt realities in the layered language of formal correspondence.",example:"It is with some concern that we note recent developments.",intensity:3,rarity:"signature",pol:{}},
{id:5112,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Grand-declaration speaker",desc:"Delivers ordinary opinions with the force of a public proclamation.",example:"Be it hereby noted: the soup is a disgrace.",intensity:3,rarity:"signature",pol:{}},
{id:5114,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Requiem-cadenced speaker",desc:"Speaks about ordinary setbacks with the structured solemnity of a funeral rite.",example:"We gather, briefly, to mark the passing of the good pen.",intensity:3,rarity:"signature",pol:{}},
{id:5115,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Court-formal speaker",desc:"Speaks with the precise, procedural formality of legal testimony.",example:"The witness states, for the record, the door was locked.",intensity:3,rarity:"signature",pol:{}},
{id:5116,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Mythic-comparison speaker",desc:"Compares mundane struggles to legendary quests and trials.",example:"Like Jason and the fleece, I too seek the missing sock.",intensity:2,rarity:"signature",pol:{}},
{id:5117,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Proclamation-styled speaker",desc:"Delivers minor grievances with the weight of a public declaration.",example:"Let it be known, henceforth, that the porridge was cold.",intensity:3,rarity:"signature",pol:{}},
{id:5118,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Relic-treatment describer",desc:"Handles and describes ordinary objects as though they were sacred artifacts.",example:"This spoon has served three generations. Treat it accordingly.",intensity:2,rarity:"signature",pol:{}},
{id:5119,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"War-horn speaker",desc:"Delivers mundane rallying calls with full wartime intensity.",example:"TO THE GARDEN! TO VICTORY OVER THESE WEEDS!",intensity:3,rarity:"signature",pol:{}},
{id:5120,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Weathervane-metaphor user",desc:"Frames indecision and change through wind-direction imagery.",example:"Which way's he leaning today? Depends which way the wind's blowing.",intensity:2,rarity:"signature",pol:{}},
{id:5121,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Root-system vocabulary",desc:"Frames hidden connection and support through underground-root imagery.",example:"Looks separate on top. Same roots underneath, though.",intensity:2,rarity:"signature",pol:{}},
{id:5122,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Tide-pool vocabulary",desc:"Describes small, contained worlds through tide-pool imagery.",example:"Whole little world in there, if you actually stop and look.",intensity:1,rarity:"signature",pol:{}},
{id:5123,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Quarry-and-stone words",desc:"Frames extraction and hard-won resource through quarrying imagery.",example:"Had to cut that out of him. Nothing came easy, not with him.",intensity:2,rarity:"signature",pol:{}},
{id:5124,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Migration-pattern vocabulary",desc:"Frames recurring seasonal behavior through animal-migration imagery.",example:"Same time every year, like clockwork. Some things don't change.",intensity:1,rarity:"signature",pol:{}},
{id:5125,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Root-cellar vocabulary",desc:"Frames storage and preservation of memory through cellar imagery.",example:"Kept that memory down where it's cold. Doesn't rot down there.",intensity:2,rarity:"signature",pol:{}},
{id:5126,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Bridge-and-span words",desc:"Frames connection across distance or difference through bridge imagery.",example:"There's a bridge between us. Rickety, but it holds.",intensity:2,rarity:"signature",pol:{}},
{id:5127,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Furnace-heat vocabulary",desc:"Frames intense internal drive through furnace and forge-fire imagery.",example:"There's a furnace in him. Keeps him moving when nothing else would.",intensity:3,rarity:"signature",pol:{}},
{id:5128,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Wind-shelter vocabulary",desc:"Frames protection and refuge through natural-shelter imagery.",example:"He's the wind-break. Stand behind him, weather's easier.",intensity:2,rarity:"signature",pol:{}},
{id:5129,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Frost-bitten vocabulary",desc:"Frames lasting damage from cold treatment through frostbite imagery.",example:"That kind of cold leaves a mark. Doesn't heal clean.",intensity:3,rarity:"signature",pol:{}},
{id:5130,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Slow-burn devotion vocabulary",desc:"Chooses words describing steady, patient, unhurried affection.",example:"Not a spark. Something that just kept building, quietly, for years.",intensity:2,rarity:"signature",pol:{}},
{id:5131,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Volcanic-restraint diction",desc:"Chooses vocabulary suggesting massive contained pressure beneath calm.",example:"(the calm is doing a great deal of work right now)",intensity:4,rarity:"signature",pol:{}},
{id:5132,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Featherweight-relief words",desc:"Describes sudden lightness after long-carried tension.",example:"Feels like I've set something down I didn't know I was carrying.",intensity:2,rarity:"common",pol:{}},
{id:5133,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Storm-front vocabulary",desc:"Chooses words suggesting emotion building visibly before it breaks.",example:"Something's coming. You can feel it in the air before it lands.",intensity:3,rarity:"signature",pol:{}},
{id:5134,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Hollowed-grief diction",desc:"Describes sorrow as an emptying-out rather than a filling-up.",example:"Not full of sadness. Just — emptied of everything else.",intensity:4,rarity:"signature",pol:{}},
{id:5135,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Static-charged vocabulary",desc:"Chooses words suggesting tension crackling just beneath the surface.",example:"Room's charged. Say the wrong thing and it goes off.",intensity:3,rarity:"signature",pol:{}},
{id:5136,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Sun-breaking-through words",desc:"Describes hope returning after sustained difficulty.",example:"First bit of light in a long while. Feels almost unfamiliar.",intensity:2,rarity:"common",pol:{}},
{id:5137,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Undertow-grief vocabulary",desc:"Describes sorrow as a pull that returns unpredictably, not steadily.",example:"Fine, and then — out of nowhere — pulled right back under.",intensity:3,rarity:"signature",pol:{}},
{id:5138,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Threadbare-hope diction",desc:"Chooses words suggesting hope worn thin but still, barely, holding.",example:"Not much of it left. Enough, though. Just enough.",intensity:3,rarity:"signature",pol:{}},
{id:5139,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Overflowing-tenderness words",desc:"Chooses vocabulary suggesting an abundance of gentle feeling.",example:"Can barely hold it, honestly, how much I feel for all of you.",intensity:2,rarity:"common",pol:{}},
{id:5151,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"No-hyperbole enforcer",desc:"Refuses exaggeration even for emphasis, sticks to literal accuracy.",example:"Not 'a million times'. Four. I counted.",intensity:2,rarity:"signature",pol:{}},
{id:5154,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Fact-first responder",desc:"Leads every account with bare facts, feelings addressed only after.",example:"The bridge collapsed. Three injured. Now — how are you?",intensity:3,rarity:"signature",pol:{}},
{id:5160,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Trade-suffix inventor",desc:"Invents occupational titles by attaching '-er' to unlikely verbs.",example:"She's the designated finder-of-things around here.",intensity:2,rarity:"signature",pol:{}},
{id:5169,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Silent-letter emphasizer vocab",desc:"Deliberately pronounces normally-silent letters for effect.",example:"Feb-ru-ary. All of it, please.",intensity:1,rarity:"signature",pol:{}},
{id:5179,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Nasal-resonance speaker vocab",desc:"Directs vocal resonance heavily through the nose.",example:"Nnno, I don't think so, not really.",intensity:2,rarity:"signature",pol:{}},
{id:5192,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Precise-cause namer vocab",desc:"Insists on the exact mechanism behind any outcome.",example:"Don't say 'it failed'. The weld cracked. Say that.",intensity:3,rarity:"signature",pol:{}},
{id:5940,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Rule-of-thirds discipliner vice",desc:"Applies strict, self-imposed numerical limits to indulgence.",example:"One-third saved, one-third spent, one-third given.",intensity:2,rarity:"signature",pol:{}},
{id:5941,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Habit-stacking discipliner vice",desc:"Builds new disciplined behaviors onto existing reliable routines.",example:"Right after coffee. Exercise happens then.",intensity:2,rarity:"signature",pol:{}},
{id:5942,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Public-service discipliner vice",desc:"Channels restraint into visible service or charitable action instead.",example:"Not spending it on that. School fund.",intensity:2,rarity:"signature",pol:{}},
{id:5943,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Cold-turkey discipliner vice",desc:"Stopped a habit abruptly and completely, with no gradual tapering.",example:"Stopped in a single day.",intensity:3,rarity:"signature",pol:{}},
{id:5944,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Long-view discipliner vice",desc:"Frames present restraint explicitly in terms of a distant future goal.",example:"For the person I'll be in ten years.",intensity:2,rarity:"signature",pol:{}},
{id:5945,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Self-monitoring discipliner vice",desc:"Keeps detailed, honest records of their own behavior and lapses.",example:"Wrote it down. Slipped Tuesday.",intensity:2,rarity:"signature",pol:{}},
{id:5946,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Reward-earning discipliner vice",desc:"Allows indulgence only after meeting a specific, earned threshold.",example:"Finish the job first. Then.",intensity:2,rarity:"common",pol:{}},
{id:5947,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Community-supported discipliner vice",desc:"Draws consistent strength from a group specifically built around shared restraint.",example:"Meeting's Thursday. Keeps me honest.",intensity:2,rarity:"signature",pol:{}},
{id:5948,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Identity-shift discipliner vice",desc:"Frames their restraint as core to who they've decided to become.",example:"Not who I am anymore.",intensity:3,rarity:"signature",pol:{}},
{id:5949,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Gradual-taper discipliner vice",desc:"Reduces a habit incrementally rather than stopping all at once.",example:"Half of what it was last month.",intensity:2,rarity:"signature",pol:{}},
{id:5950,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Mildly curious about new things",desc:"Notices unfamiliar things a little more than most, without much follow-through.",example:"Huh. Wonder what that's about.",intensity:1,rarity:"common",pol:{}},
{id:5951,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Question-asker",desc:"Asks genuine follow-up questions rather than letting things pass.",example:"Wait, go back — why did that happen?",intensity:2,rarity:"common",pol:{}},
{id:5952,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Rabbit-hole follower",desc:"Chases one small question into a much longer investigation.",example:"Meant to look up one thing. That was two hours ago.",intensity:3,rarity:"signature",pol:{}},
{id:5953,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"New-place seeker",desc:"Actively chooses unfamiliar routes and places over familiar ones.",example:"Never been down that street. Let's find out what's there.",intensity:2,rarity:"common",pol:{}},
{id:5954,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Mechanism-wonderer",desc:"Wants to understand how things actually work, not just that they do.",example:"Yes, but why does it work that way?",intensity:2,rarity:"signature",pol:{}},
{id:5955,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Stranger-interviewer",desc:"Asks real, specific questions of people they've just met.",example:"So how did you end up doing this, of all things?",intensity:2,rarity:"common",pol:{}},
{id:5956,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Book-devourer",desc:"Reads widely and eagerly outside their own area of expertise.",example:"Finished that. What's next? Anything, really.",intensity:2,rarity:"signature",pol:{}},
{id:5957,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Puzzle-drawn",desc:"Gravitates toward unsolved problems simply because they're unsolved.",example:"Nobody's figured that out yet? Let me try.",intensity:3,rarity:"signature",pol:{}},
{id:5958,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Field-trip proposer",desc:"Suggests going to see the actual thing rather than just discussing it.",example:"Why are we talking about it? Let's go look.",intensity:2,rarity:"common",pol:{}},
{id:5959,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Cross-topic connector curious",desc:"Draws unexpected links between completely unrelated fields.",example:"This is basically the same problem as the one in beekeeping.",intensity:3,rarity:"signature",pol:{}},
{id:5960,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Idea-collector",desc:"Keeps a running list of things they want to learn or try someday.",example:"Adding that to the list. The list's getting long.",intensity:1,rarity:"common",pol:{}},
{id:5961,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Uncomfortable-question asker",desc:"Willing to ask the question everyone else is avoiding, out of genuine interest.",example:"Nobody's actually asked why, though. Why?",intensity:3,rarity:"signature",pol:{}},
{id:5962,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"First-to-try",desc:"Volunteers to test the new, unfamiliar thing before anyone else will.",example:"I'll try it first. Someone's got to.",intensity:2,rarity:"common",pol:{}},
{id:5963,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Obsessive-deep-diver",desc:"Cannot stop researching a topic once it's genuinely caught their interest.",example:"Just one more source. Then I'll stop. (Doesn't stop.)",intensity:4,rarity:"signature",pol:{}},
{id:5964,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Reverse-engineer",desc:"Takes things apart, literally or conceptually, just to see how they fit.",example:"Had to know what was inside. Couldn't not know.",intensity:3,rarity:"signature",pol:{}},
{id:5965,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Wonder-struck observer",desc:"Registers genuine awe at things others have stopped noticing.",example:"Have you actually looked at that? Really looked?",intensity:1,rarity:"common",pol:{}},
{id:5966,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Life-story asker",desc:"Genuinely wants to hear how people ended up where they are.",example:"No, but really — what's the whole story?",intensity:2,rarity:"signature",pol:{}},
{id:5967,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Experiment-runner",desc:"Tests small hypotheses about the world just to see what happens.",example:"What happens if I do it backwards? Let's find out.",intensity:2,rarity:"signature",pol:{}},
{id:5968,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Total-immersion learner",desc:"Throws themselves completely into a new subject, all at once.",example:"Learning everything about this. Starting now.",intensity:4,rarity:"signature",pol:{}},
{id:5969,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Never-satisfied questioner",desc:"No answer is ever quite enough; there's always a further question.",example:"Okay, but what caused THAT?",intensity:3,rarity:"signature",pol:{}},
{id:5970,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Map-margin wanderer",desc:"Drawn specifically to the unexplained, unlabeled edges of any subject.",example:"That's the part nobody's really explained properly.",intensity:2,rarity:"signature",pol:{}},
{id:5971,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Insatiably curious",desc:"Curiosity borders on compulsive, touching nearly everything encountered.",example:"Have to know. About all of it. Can't help it.",intensity:5,rarity:"signature",pol:{}},
{id:5972,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Mildly set in routine",desc:"Prefers the familiar slightly more than most, without much resistance to change.",example:"Same as usual works fine for me.",intensity:1,rarity:"common",pol:{}},
{id:5973,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Question-declining",desc:"Lets unanswered questions simply pass without much interest.",example:"Don't know. Don't especially need to know.",intensity:2,rarity:"common",pol:{}},
{id:5974,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Comfortable-with-not-knowing",desc:"Genuinely unbothered by gaps in their own understanding.",example:"No idea how that works. Not going to lose sleep over it.",intensity:2,rarity:"common",pol:{}},
{id:5975,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Familiar-path preferrer",desc:"Consistently takes the known route over the unknown one.",example:"Know this way. Sticking with this way.",intensity:2,rarity:"common",pol:{}},
{id:5976,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Surface-level satisfied",desc:"Accepts a basic explanation without wanting to dig further.",example:"That's enough of an answer for me.",intensity:2,rarity:"signature",pol:{}},
{id:5977,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"New-topic avoider",desc:"Steers conversation away from unfamiliar subjects, mildly.",example:"Don't really know much about that. Anyway—",intensity:2,rarity:"signature",pol:{}},
{id:5978,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Practical-only learner",desc:"Only interested in information with immediate, direct use.",example:"Why would I need to know that? Doesn't help with anything.",intensity:2,rarity:"common",pol:{}},
{id:5979,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Routine-defender",desc:"Actively resists suggestions to try something new or unfamiliar.",example:"Don't see why we'd change it. Works as it is.",intensity:3,rarity:"signature",pol:{}},
{id:5980,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Explanation-uninterested",desc:"Wants the result, not the reasoning behind it.",example:"Just tell me what to do. Skip the why.",intensity:2,rarity:"common",pol:{}},
{id:5981,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Same-questions asker",desc:"Circles the same familiar handful of questions, rarely new ones.",example:"Same as I always ask. Same as I always get.",intensity:1,rarity:"signature",pol:{}},
{id:5982,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Novelty-fatigued",desc:"Finds new things tiring rather than exciting, by default.",example:"Something else new? Already? Really.",intensity:3,rarity:"signature",pol:{}},
{id:5983,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"World-closed observer",desc:"Has stopped actively noticing much beyond their immediate concerns.",example:"Didn't notice. Don't really notice much these days.",intensity:3,rarity:"signature",pol:{}},
{id:5984,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Firmly-uninterested",desc:"States plainly that certain topics simply don't interest them.",example:"Not curious about that. At all. Never have been.",intensity:2,rarity:"common",pol:{}},
{id:5985,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Change-resistant settled",desc:"Prefers things to stay exactly as they've always been.",example:"Why fix what's not broken? Leave it be.",intensity:2,rarity:"common",pol:{}},
{id:5986,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Explanation-skeptical",desc:"Doubts that understanding the mechanism actually matters.",example:"Works, doesn't it? That's all that matters.",intensity:2,rarity:"signature",pol:{}},
{id:5987,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Totally incurious",desc:"Has essentially stopped wondering about anything beyond routine.",example:"Don't wonder about much anymore. Haven't in years.",intensity:4,rarity:"signature",pol:{}},
{id:5988,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Question-shutting",desc:"Actively discourages others' questions as a waste of time.",example:"Enough questions. Just get on with it.",intensity:3,rarity:"signature",pol:{}},
{id:5989,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Predictability-seeking",desc:"Actively prefers knowing exactly what will happen, every time.",example:"Like knowing. Don't like surprises, new or otherwise.",intensity:2,rarity:"signature",pol:{}},
{id:5990,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Chronically unmoved",desc:"Genuinely nothing seems to spark real interest anymore.",example:"Nothing much catches my attention these days. Nothing really does.",intensity:4,rarity:"signature",pol:{}},
{id:5991,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Willfully unexamined",desc:"Deliberately avoids looking closer at things that might unsettle their view.",example:"Rather not know, honestly. Rather just not.",intensity:3,rarity:"signature",pol:{}},
{id:5992,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Disengaged-from-world",desc:"Has narrowed their attention almost entirely to the immediate and familiar.",example:"World's big. Mine's small. Prefer it that way.",intensity:3,rarity:"signature",pol:{}},
{id:5993,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Completely closed-off curious",desc:"Shows no interest whatsoever in anything outside a narrow, fixed routine.",example:"Same, same, same. That's the whole of it, and that's fine.",intensity:5,rarity:"signature",pol:{}},
{id:5994,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Quietly unpersuaded",desc:"Goes along with rules outwardly while never actually accepting their authority.",example:"(complies, and clearly doesn't agree)",intensity:1,rarity:"common",pol:{}},
{id:5995,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Nature-and-weather imagery",desc:"Reaches for storms, seasons, and open sky to describe feelings and events.",example:"It's a storm that hasn't broken yet. Give it time.",intensity:2,rarity:"common",pol:{}},
{id:5996,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Fire-and-heat imagery",desc:"Describes intensity, anger, and passion through burning and heat.",example:"That's not simmering anymore. That's a full boil.",intensity:2,rarity:"common",pol:{}},
{id:5997,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Water-and-flow imagery",desc:"Frames change, emotion, and time as currents, tides, and depth.",example:"Let it flow through. Don't dam it up.",intensity:2,rarity:"common",pol:{}},
{id:5998,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Body-and-physicality imagery",desc:"Describes abstract situations in terms of muscle, bone, and breath.",example:"This plan has no backbone. It'll collapse the first time it's tested.",intensity:2,rarity:"common",pol:{}},
{id:5999,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Growth-and-plant imagery",desc:"Frames development and patience through roots, seeds, and blooming.",example:"Give it a season. Nothing worth having grows overnight.",intensity:2,rarity:"common",pol:{}},
{id:6000,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Machine-and-mechanism imagery",desc:"Describes people and systems as gears, engines, and moving parts.",example:"He's a cog that stopped turning. Someone needs to notice.",intensity:2,rarity:"signature",pol:{}},
{id:6001,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Construction-and-structure imagery",desc:"Frames stability and collapse through beams, foundations, and load.",example:"That argument's got no foundation. It'll fall the second you push it.",intensity:2,rarity:"common",pol:{}},
{id:6002,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Combat-and-conflict imagery",desc:"Describes ordinary disagreements in terms of battle and siege.",example:"We're not negotiating. We're holding a line.",intensity:3,rarity:"signature",pol:{}},
{id:6003,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Money-and-value imagery",desc:"Frames worth, cost, and exchange through commerce and price.",example:"Everything's got a price. I'm just naming ours out loud.",intensity:2,rarity:"common",pol:{}},
{id:6004,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Games-and-chance imagery",desc:"Describes risk and outcome through cards, dice, and odds.",example:"We're not owed a win here. The odds don't care what we deserve.",intensity:2,rarity:"signature",pol:{}},
{id:6005,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Journey-and-motion imagery",desc:"Frames progress and setback as roads, distance, and direction.",example:"We're not lost. We're just further from where we thought we'd be.",intensity:2,rarity:"common",pol:{}},
{id:6006,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Time-and-decay imagery",desc:"Describes change and loss through rust, erosion, and the passage of years.",example:"It didn't break all at once. It just wore down, year by year.",intensity:2,rarity:"common",pol:{}},
{id:6007,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Animal-and-instinct imagery",desc:"Frames behavior and character through animal comparison and instinct.",example:"He circled it three times before he'd say a word. Like something wild deciding whether to trust.",intensity:2,rarity:"signature",pol:{}},
{id:6008,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Light-and-shadow imagery",desc:"Describes clarity, secrecy, and hope through light and dark.",example:"He keeps that part of himself in shadow. On purpose.",intensity:2,rarity:"common",pol:{}},
{id:6009,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Sound-and-music imagery",desc:"Frames harmony, discord, and rhythm through musical comparison.",example:"We're out of tune lately. Has been for a while, honestly.",intensity:2,rarity:"signature",pol:{}},
{id:6010,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Number-and-measurement imagery",desc:"Describes situations through counting, weighing, and precise measure.",example:"Doesn't add up. Never has. I've checked the sum a dozen times.",intensity:2,rarity:"signature",pol:{}},
{id:6011,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Map-and-territory imagery",desc:"Frames understanding and uncertainty as charted or unmapped ground.",example:"We're off the map here. No lines drawn, no telling what's past the edge.",intensity:2,rarity:"signature",pol:{}},
{id:6012,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Thread-and-weave imagery",desc:"Describes connection and unraveling through fabric and binding.",example:"Pull one thread and the whole thing comes apart. Careful which one.",intensity:2,rarity:"signature",pol:{}},
{id:6013,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Food-and-appetite imagery",desc:"Frames desire, satisfaction, and excess through eating and hunger.",example:"He's hungry for it in a way that's a little uncomfortable to watch.",intensity:2,rarity:"common",pol:{}},
{id:6014,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Weight-and-gravity imagery",desc:"Describes burden and relief through heaviness and pressure.",example:"That's a weight he's been carrying alone. Nobody offered to take a corner of it.",intensity:2,rarity:"common",pol:{}},
{id:6015,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Door-and-threshold imagery",desc:"Frames choice and transition through doors, gates, and crossing over.",example:"That door's closed now. Doesn't mean there isn't another one somewhere.",intensity:2,rarity:"signature",pol:{}},
{id:6016,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Circle-and-cycle imagery",desc:"Describes repetition and return through circles, loops, and seasons.",example:"Same argument, same shape, third time round. We're just circling.",intensity:2,rarity:"signature",pol:{}},
{id:6017,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Blade-and-edge imagery",desc:"Frames sharpness, danger, and precision through cutting and edges.",example:"Careful. That question's got an edge on it.",intensity:3,rarity:"signature",pol:{}},
{id:6018,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Root-and-foundation imagery",desc:"Describes origin and stability through roots, bedrock, and what lies beneath.",example:"Whatever's wrong here goes down to the root. Fixing the leaves won't help.",intensity:2,rarity:"common",pol:{}},
{id:6019,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Weave of multiple domains",desc:"Draws freely from several unrelated conceptual sources in the same breath, without settling on one.",example:"It's a slow burn, and also a long road, and also — I don't know, a held breath. Pick one, I can't.",intensity:2,rarity:"signature",pol:{}},
{id:6020,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Sparse metaphor user",desc:"Almost never reaches for figurative comparison, describing things as they literally are.",example:"It's bad. Just bad. I don't need a metaphor for it.",intensity:1,rarity:"common",pol:{}}
];
